    /**
     * 1.10.39 local ET4 media storage.
     *
     * ET4 image URLs are upstream provenance only. They are never emitted to the
     * browser. The local file lives outside the Media Library in
     * wp-content/uploads/rpg-et4-event-media/ and is keyed by ET4 global_id.
     */
    private function event_local_media_dir_v1039() {
        $uploads=wp_upload_dir(null,false);
        if(!is_array($uploads)||!empty($uploads['error'])||empty($uploads['basedir'])||empty($uploads['baseurl']))return new WP_Error('rpg_et4_local_upload_dir','WordPress-Upload-Verzeichnis nicht verfuegbar');
        $dir=trailingslashit((string)$uploads['basedir']).'rpg-et4-event-media';
        if(!is_dir($dir)&&!wp_mkdir_p($dir))return new WP_Error('rpg_et4_local_mkdir','Lokales ET4-Bildverzeichnis konnte nicht angelegt werden');
        // The image files themselves must stay publicly readable. An index.php
        // prevents casual directory browsing without relying on host-specific
        // .htaccess directives that could make the entire image directory 500.
        $index=trailingslashit($dir).'index.php';if(!is_file($index))@file_put_contents($index,"<?php\n// Silence is golden.\n",LOCK_EX);
        return array('dir'=>$dir,'basedir'=>(string)$uploads['basedir'],'baseurl'=>(string)$uploads['baseurl']);
    }

    private function event_local_media_allowed_mime_v1039($mime) {
        $mime=strtolower(trim((string)$mime));if(strpos($mime,';')!==false)$mime=trim(strtok($mime,';'));
        return in_array($mime,array('image/jpeg','image/png','image/webp','image/gif','image/avif'),true)?$mime:'';
    }

    private function event_local_media_detect_mime_v1039($file) {
        $mime='';
        if(function_exists('wp_get_image_mime'))$mime=$this->event_local_media_allowed_mime_v1039((string)wp_get_image_mime($file));
        if($mime===''&&function_exists('getimagesize')){$size=@getimagesize($file);if(is_array($size)&&!empty($size['mime']))$mime=$this->event_local_media_allowed_mime_v1039((string)$size['mime']);}
        if($mime!=='')return $mime;
        $head=(string)@file_get_contents($file,false,null,0,16);
        if(strlen($head)>=3&&substr($head,0,3)==="\xFF\xD8\xFF")return 'image/jpeg';
        if(strlen($head)>=8&&substr($head,0,8)==="\x89PNG\r\n\x1A\n")return 'image/png';
        if(strlen($head)>=6&&(substr($head,0,6)==='GIF87a'||substr($head,0,6)==='GIF89a'))return 'image/gif';
        if(strlen($head)>=12&&substr($head,0,4)==='RIFF'&&substr($head,8,4)==='WEBP')return 'image/webp';
        if(strlen($head)>=12&&substr($head,4,4)==='ftyp'&&in_array(substr($head,8,4),array('avif','avis'),true))return 'image/avif';
        return '';
    }

    private function event_local_media_ext_v1039($mime) {
        $map=array('image/jpeg'=>'jpg','image/png'=>'png','image/webp'=>'webp','image/gif'=>'gif','image/avif'=>'avif');
        return $map[$mime]??'';
    }

    private function event_local_media_public_url_v1039($row) {
        if(!is_array($row))return '';
        $rel=ltrim(str_replace('\\','/',trim((string)($row['local_path']??''))),'/');
        if($rel===''||strpos($rel,'rpg-et4-event-media/')!==0)return '';
        $uploads=wp_upload_dir(null,false);if(!is_array($uploads)||!empty($uploads['error'])||empty($uploads['basedir'])||empty($uploads['baseurl']))return '';
        $file=trailingslashit((string)$uploads['basedir']).$rel;if(!is_file($file)||filesize($file)<=0)return '';
        $url=trailingslashit((string)$uploads['baseurl']).str_replace('%2F','/',rawurlencode($rel));
        $url=set_url_scheme($url,'https');
        $hash=preg_replace('/[^a-f0-9]/i','',(string)($row['local_content_hash']??''));
        if($hash!=='')$url=add_query_arg('v',substr($hash,0,16),$url);
        return esc_url_raw($url);
    }

    private function event_local_media_download_v1039($global_id,$upstream) {
        $global_id=$this->event_text($global_id,190);$upstream=esc_url_raw(trim((string)$upstream));
        if($global_id===''||$upstream===''||!preg_match('#^https?://#i',$upstream)||!wp_http_validate_url($upstream))return new WP_Error('rpg_et4_local_bad_source','Ungueltige ET4-Bildquelle');
        $paths=$this->event_local_media_dir_v1039();if(is_wp_error($paths))return $paths;
        $dir=$paths['dir'];$stem='et4-'.substr(hash('sha256',$global_id),0,40);$meta_path=trailingslashit($dir).$stem.'.json';
        $source_hash=hash('sha256',$upstream);$meta=is_file($meta_path)?json_decode((string)@file_get_contents($meta_path),true):null;
        if(is_array($meta)&&!empty($meta['file'])&&!empty($meta['mime'])){
            $existing=trailingslashit($dir).basename((string)$meta['file']);
            if(is_file($existing)&&filesize($existing)>0&&(string)($meta['source_hash']??'')===$source_hash){
                // A URL match alone is not enough: validate the existing bytes so a
                // truncated/corrupt local file can never become a permanent cache hit.
                $existing_mime=$this->event_local_media_detect_mime_v1039($existing);
                $existing_hash=(string)@hash_file('sha256',$existing);
                if($existing_mime!==''&&$existing_mime===(string)$meta['mime']&&$existing_hash!==''){
                    return array('local_path'=>'rpg-et4-event-media/'.basename($existing),'local_mime'=>$existing_mime,'local_bytes'=>(int)filesize($existing),'local_content_hash'=>$existing_hash,'local_cached_at'=>(string)($meta['cached_at']??current_time('mysql')),'cache'=>'hit');
                }
            }
        }
        $tmp=trailingslashit($dir).'.'.$stem.'.'.wp_generate_password(12,false,false).'.tmp';
        $response=wp_remote_get($upstream,array(
            // Deliberately use the same WordPress HTTP transport that already
            // proved ET4 images reachable in the existing Media-Health check.
            // Unlike that probe we stream the complete response to disk.
            'timeout'=>20,'redirection'=>5,'stream'=>true,'filename'=>$tmp,'limit_response_size'=>12*1024*1024,
            'user-agent'=>'RuhrpottGuru/1.7.1 EventMediaHealth',
            'headers'=>array('Accept'=>'image/avif,image/webp,image/apng,image/png,image/jpeg,image/gif,image/*,*/*;q=0.8')
        ));
        if(is_wp_error($response)){@unlink($tmp);return new WP_Error('rpg_et4_local_fetch',$response->get_error_message());}
        $code=(int)wp_remote_retrieve_response_code($response);if($code<200||$code>=300){@unlink($tmp);return new WP_Error('rpg_et4_local_http','ET4-Bild lieferte HTTP '.$code);}
        if(!is_file($tmp)||filesize($tmp)<=0||filesize($tmp)>12*1024*1024){@unlink($tmp);return new WP_Error('rpg_et4_local_size','ET4-Bild ist leer oder zu gross');}
        $mime=$this->event_local_media_detect_mime_v1039($tmp);$ext=$this->event_local_media_ext_v1039($mime);if($mime===''||$ext===''){@unlink($tmp);return new WP_Error('rpg_et4_local_not_image','ET4-Antwort ist kein unterstuetztes Bild');}
        $header_mime=$this->event_local_media_allowed_mime_v1039((string)wp_remote_retrieve_header($response,'content-type'));
        if($header_mime!==''&&$header_mime!==$mime){@unlink($tmp);return new WP_Error('rpg_et4_local_mime','ET4-Bildtyp stimmt nicht mit dem Inhalt ueberein');}
        $target=trailingslashit($dir).$stem.'.'.$ext;
        // Publish only after the new file has been completely downloaded and
        // validated. rename() is atomic on the normal Linux WordPress filesystem
        // and replaces an existing same-name file without an empty-file window.
        $moved=@rename($tmp,$target);
        if(!$moved){
            // Portable fallback for filesystems that refuse replacement rename.
            if(is_file($target)&&!@unlink($target)){@unlink($tmp);return new WP_Error('rpg_et4_local_replace','Vorhandenes lokales ET4-Bild konnte nicht ersetzt werden');}
            if(!@rename($tmp,$target)){if(!@copy($tmp,$target)){@unlink($tmp);return new WP_Error('rpg_et4_local_move','Lokales ET4-Bild konnte nicht gespeichert werden');}@unlink($tmp);}
        }
        @chmod($target,0644);
        // Delete an obsolete extension only after the replacement is live.
        foreach(array('jpg','png','webp','gif','avif') as $oldext){$old=trailingslashit($dir).$stem.'.'.$oldext;if($old!==$target&&is_file($old))@unlink($old);}
        $content_hash=(string)hash_file('sha256',$target);$cached_at=current_time('mysql');
        if($content_hash==='')return new WP_Error('rpg_et4_local_hash','Lokales ET4-Bild konnte nicht verifiziert werden');
        $meta_json=wp_json_encode(array('global_id'=>$global_id,'file'=>basename($target),'mime'=>$mime,'bytes'=>(int)filesize($target),'source_hash'=>$source_hash,'content_hash'=>$content_hash,'cached_at'=>$cached_at),JSON_UNESCAPED_SLASHES|JSON_UNESCAPED_UNICODE);
        $meta_tmp=$meta_path.'.tmp';
        if(@file_put_contents($meta_tmp,$meta_json,LOCK_EX)!==false){if(!@rename($meta_tmp,$meta_path)){@file_put_contents($meta_path,$meta_json,LOCK_EX);@unlink($meta_tmp);}}
        return array('local_path'=>'rpg-et4-event-media/'.basename($target),'local_mime'=>$mime,'local_bytes'=>(int)filesize($target),'local_content_hash'=>$content_hash,'local_cached_at'=>$cached_at,'cache'=>'miss');
    }

