    public function cleanup_orphan_night_submissions_v184() {
        if(get_option('rg_night_orphan_cleanup_v184'))return;
        global $wpdb;$sub=$this->table('place_override_submissions');$ms=$this->table('place_media_submissions');
        $ids=(array)$wpdb->get_col("SELECT s.id FROM $sub s WHERE s.submission_type='place_contribution' AND s.payload_json LIKE '%\"category\":\"night\"%' AND s.status IN ('awaiting_verification','pending') AND NOT EXISTS (SELECT 1 FROM $ms m WHERE m.submission_id=s.id) LIMIT 200");
        foreach($ids as $id)$wpdb->delete($sub,array('id'=>(int)$id),array('%d'));
        update_option('rg_night_orphan_cleanup_v184',current_time('mysql',true),false);
    }

    public static function activate() {
        $self = self::instance();
        $self->install_schema();
        $self->seed_municipalities();
        if (!get_option(self::OPTION_MODE)) {
            update_option(self::OPTION_MODE, 'auto', false);
        }
        if (!get_option(self::OPTION_STATUS)) {
            update_option(self::OPTION_STATUS, 'bootstrap_pending', false);
        }
        if (!get_option(self::OPTION_CATALOG_VERSION)) {
            update_option(self::OPTION_CATALOG_VERSION, 'bootstrap', false);
        }
        $self->ensure_cron_event();
        $self->ensure_events_nightly_cron();
        $self->ensure_event_selm_calendar_schedule_v101102();
    }

    public static function deactivate() {
        $timestamp = wp_next_scheduled(self::CRON_HOOK);
        if ($timestamp) {
            wp_unschedule_event($timestamp, self::CRON_HOOK);
        }
        $timestamp = wp_next_scheduled(self::EVENT_NIGHTLY_HOOK);
        if ($timestamp) {
            wp_unschedule_event($timestamp, self::EVENT_NIGHTLY_HOOK);
        }
        wp_clear_scheduled_hook(self::ACTIVITY_COVERAGE_HOOK);
        wp_clear_scheduled_hook(self::PLACE_MEDIA_COVERAGE_HOOK);
        wp_clear_scheduled_hook(self::PLACE_MEDIA_TEXT_CLASSIFY_HOOK);
        wp_clear_scheduled_hook(self::REPROCESS_HOOK);
        wp_clear_scheduled_hook(self::EVENT_NIGHTLY_BATCH_HOOK);
        wp_clear_scheduled_hook(self::EVENT_HOT_HOOK);
        wp_clear_scheduled_hook(self::EVENT_PLAN_HOOK);
        wp_clear_scheduled_hook(self::EVENT_TIER_BATCH_HOOK);
        wp_clear_scheduled_hook(self::EVENT_TIER_DISPATCH_HOOK);
        wp_clear_scheduled_hook(self::EVENT_SELM_HOOK);
        wp_clear_scheduled_hook(self::EVENT_SELM_BATCH_HOOK);
        wp_clear_scheduled_hook(self::EVENT_SELM_RETRY_HOOK);
        delete_option(self::EVENT_IMPORT_LOCK);

        wp_clear_scheduled_hook(self::EVENT_ENRICH_BATCH_HOOK);
        wp_clear_scheduled_hook(self::EVENT_CATALOG_MEDIA_HOOK);
        wp_clear_scheduled_hook(self::EVENT_LOCAL_MEDIA_HOOK);
        wp_clear_scheduled_hook(self::EVENT_FALLBACK_MEDIA_HOOK);
        wp_clear_scheduled_hook(self::EVENT_CONTEXT_UPGRADE_HOOK);
        wp_clear_scheduled_hook(self::EVENT_CANDIDATE_HASH_HOOK);
        wp_clear_scheduled_hook(self::EVENT_COVERAGE_HOOK);
        wp_clear_scheduled_hook(self::EVENT_RAW_MEDIA_HOOK);
        wp_clear_scheduled_hook('rg_iga_intelligence_batch_v101081');
        delete_option('rg_intelligence_iga_lock');
    }

    private function table($suffix) {
        global $wpdb;
        return $wpdb->prefix . 'rg_' . $suffix;
    }

    /**
     * 1.10.129 - one-time, idempotent repair for the historic place_media
     * wpdb-format shift. No worker state, cursor or queue is modified here.
     */
    private function repair_place_media_contract_v101129() {
        global $wpdb;
        $done_key='rg_place_media_contract_repair_v101129_done';
        if(get_option($done_key,false))return;
        $media=$this->table('place_media');
        if($wpdb->get_var($wpdb->prepare('SHOW TABLES LIKE %s',$media))!==$media)return;
        $columns=(array)$wpdb->get_col("SHOW COLUMNS FROM $media",0);
        foreach(array('relation_type','visual_quality','source','is_primary','verified_at','last_seen_at') as $required){if(!in_array($required,$columns,true))return;}

        $invalid=(int)$wpdb->get_var("SELECT COUNT(*) FROM $media WHERE relation_type='' OR relation_type NOT IN ('place','contextual','night')");
        if($invalid>0){
            // Historic Buedchen street-level candidates were the only intended
            // contextual rows in the affected data. Community night uploads are
            // unambiguous by source; all remaining malformed rows are place media.
            $wpdb->query("UPDATE $media SET relation_type=CASE WHEN source='community_night_upload' THEN 'night' WHEN source IN ('kartaview','panoramax') AND is_primary=0 THEN 'contextual' ELSE 'place' END WHERE relation_type='' OR relation_type NOT IN ('place','contextual','night')");
            if($wpdb->last_error!=='')return;
        }

        // The same format shift coerced visual_quality through %d. Restore only
        // the broken zero values; legitimate non-zero editorial values are kept.
        $wpdb->query("UPDATE $media SET visual_quality=CASE WHEN source='editorial-place-upload' THEN 0.9800 WHEN source IN ('community_upload','community_night_upload') THEN 0.9000 ELSE 0.7500 END WHERE visual_quality=0.0000");
        if($wpdb->last_error!=='')return;

        // verified_at is an actual source verification timestamp. Reuse it for
        // last_seen_at only where that timestamp exists; do not invent a time for
        // lower-confidence historic rows where the original write lost it.
        $wpdb->query("UPDATE $media SET last_seen_at=verified_at WHERE verified_at IS NOT NULL AND verified_at<>'0000-00-00 00:00:00' AND (last_seen_at IS NULL OR last_seen_at='0000-00-00 00:00:00')");
        if($wpdb->last_error!=='')return;

        $remaining=(int)$wpdb->get_var("SELECT COUNT(*) FROM $media WHERE relation_type='' OR relation_type NOT IN ('place','contextual','night') OR visual_quality=0.0000");
        if($remaining===0)update_option($done_key,current_time('mysql',true),false);
    }

    private function repair_place_media_primary_v101150() {
        global $wpdb;$done='rg_place_media_primary_repair_v101150_done';if(get_option($done,false))return;
        $media=$this->table('place_media');$dupes=(array)$wpdb->get_col("SELECT place_id FROM $media WHERE media_type='image' AND relation_type='place' AND moderation_status='active' AND is_primary=1 GROUP BY place_id HAVING COUNT(*)>1");
        foreach($dupes as $placeId){
            $placeId=(int)$placeId;if($placeId<=0)continue;
            $rows=(array)$wpdb->get_results($wpdb->prepare("SELECT id,identity_confidence,visual_quality,verified_at FROM $media WHERE place_id=%d AND media_type='image' AND relation_type='place' AND moderation_status='active' AND is_primary=1 ORDER BY (verified_at IS NOT NULL) DESC,identity_confidence DESC,visual_quality DESC,id ASC",$placeId),ARRAY_A);
            if(count($rows)<2)continue;$keep=(int)$rows[0]['id'];
            $wpdb->query($wpdb->prepare("UPDATE $media SET is_primary=0 WHERE place_id=%d AND media_type='image' AND relation_type='place' AND moderation_status='active' AND is_primary=1 AND id<>%d",$placeId,$keep));
            if($wpdb->last_error!=='')return;
        }
        $remaining=(int)$wpdb->get_var("SELECT COUNT(*) FROM (SELECT place_id FROM $media WHERE media_type='image' AND relation_type='place' AND moderation_status='active' AND is_primary=1 GROUP BY place_id HAVING COUNT(*)>1) mp");
        if($remaining===0)update_option($done,current_time('mysql',true),false);
    }

    /**
     * 1.10.154 - one-time canonical repair for source date typos that would keep an
     * event alive for years or centuries. Raw source payloads stay untouched for
     * provenance; only the canonical visitor range is repaired.
     */
    private function repair_event_implausible_ranges_v101154() {
        global $wpdb;
        $done='rg_event_implausible_range_repair_v101154_done';
        if(get_option($done,false))return;
        $events=$this->table('events');
        if($wpdb->get_var($wpdb->prepare('SHOW TABLES LIKE %s',$events))!==$events)return;
        $now=current_time('mysql');
        $rows=(array)$wpdb->get_results("SELECT id,start_at,end_at,status FROM $events WHERE end_at IS NOT NULL AND (end_at<start_at OR end_at>DATE_ADD(start_at, INTERVAL 5 YEAR)) ORDER BY id ASC LIMIT 250",ARRAY_A);
        foreach($rows as $row){
            $id=(int)($row['id']??0);if($id<=0)continue;
            $status=(string)($row['status']??'');
            $data=array('end_at'=>null,'updated_at'=>$now);
            if($status==='active' && strtotime((string)($row['start_at']??''))<current_time('timestamp'))$data['status']='expired';
            $ok=$wpdb->update($events,$data,array('id'=>$id));
            if($ok===false||$wpdb->last_error!=='')return;
        }
        $wpdb->query($wpdb->prepare("UPDATE $events SET status='expired',updated_at=%s WHERE status='active' AND COALESCE(end_at,start_at)<%s",$now,$now));
        if($wpdb->last_error!=='')return;
        $remaining=(int)$wpdb->get_var("SELECT COUNT(*) FROM $events WHERE end_at IS NOT NULL AND (end_at<start_at OR end_at>DATE_ADD(start_at, INTERVAL 5 YEAR))");
        if($remaining===0)update_option($done,current_time('mysql',true),false);
    }

    public function ensure_schema_and_schedule() {
        if (get_option('rg_places_schema_version') !== self::SCHEMA_VERSION) {
            $this->install_schema();
            $this->seed_municipalities();
        }
        $this->repair_place_media_contract_v101129();
        $this->repair_place_media_primary_v101150();
        $this->repair_event_implausible_ranges_v101154();
        $this->ensure_cron_event();
        $this->ensure_events_nightly_cron();
        $this->ensure_event_selm_calendar_schedule_v101102();
        $this->maybe_bootstrap_et4_local_media_v1039();
        $this->maybe_bootstrap_destination_one_local_media_v1041();
        $this->maybe_restart_et4_address_image_reconcile_v1074();
        $this->ensure_et4_catalog_media_backfill_v1022();
        $this->ensure_event_local_media_cache_v1039();
        $this->maybe_migrate_event_auto_visual_quality_v101110();
        $this->maybe_relax_event_media_policy_v101112();
        $this->ensure_event_raw_feed_media_backfill_v1028();
        $this->maybe_restart_broad_supplemental_v180();
        $this->maybe_restart_supplemental_tracking_v182();
        $this->maybe_restart_rich_supplemental_media_v1027();
        $this->ensure_event_coverage_schedule_v1051();
    }

    /**
     * 1.10.111: one-time surgical cleanup for the one repeatedly wrong
     * Waldschule-Cappenberg venue image seen on the live Selm event grid.
     *
     * No visual/text heuristic is used here. We identify the exact persisted
     * venue-context asset by repetition across at least three active native
     * Selm events at the same venue, persist its URL/content fingerprint, reject
     * only rows carrying that fingerprint, and hand those events back to the
     * already existing fallback resolver.
     */
    public function maybe_block_waldschule_bad_event_media_v101111() {
        if (get_option('rg_event_waldschule_bad_media_v101111_done')) return;
        global $wpdb;
        $events=$this->table('events');$media=$this->table('event_media');$places=$this->table('places');$placeMedia=$this->table('place_media');$enr=$this->table('event_enrichment');$now=current_time('mysql');

        $rows=(array)$wpdb->get_results($wpdb->prepare(
            "SELECT m.id,m.event_id,m.url,m.source_url,m.local_content_hash,m.source_content_hash,m.source,e.venue_name,e.city
             FROM $media m INNER JOIN $events e ON e.id=m.event_id
             WHERE e.status='active' AND e.source='stadt_selm_calendar' AND e.city=%s
               AND LOWER(e.venue_name) LIKE %s
               AND m.media_type='image' AND m.moderation_status='active'
               AND m.source='venue-commons-context' AND m.local_cache_status='ready'",
            'Selm','%waldschule%cappenberg%'
        ),ARRAY_A);

        $groups=array();
        foreach($rows as $r){
            $hash=strtolower(trim((string)($r['local_content_hash']??'')));
            if(!preg_match('/^[a-f0-9]{64}$/',$hash))$hash=strtolower(trim((string)($r['source_content_hash']??'')));
            $url=esc_url_raw((string)($r['source_url']??''));if($url==='')$url=esc_url_raw((string)($r['url']??''));
            $key=preg_match('/^[a-f0-9]{64}$/',$hash)?'h:'.$hash:($url!==''?'u:'.strtolower(preg_replace('/[?#].*$/','',$url)):'');
            if($key==='')continue;
            if(!isset($groups[$key]))$groups[$key]=array('key'=>$key,'hash'=>preg_match('/^[a-f0-9]{64}$/',$hash)?$hash:'','url'=>$url,'rows'=>array(),'events'=>array());
            $groups[$key]['rows'][]=(int)$r['id'];$groups[$key]['events'][(int)$r['event_id']]=1;
        }
        uasort($groups,function($a,$b){return count($b['events'])<=>count($a['events']);});
        $bad=null;foreach($groups as $g){if(count($g['events'])>=3){$bad=$g;break;}}

        if(!$bad){
            // Do not guess. Leave all media untouched if the exact repeated live
            // asset cannot be proven from persisted Selm/Waldschule assignments.
            update_option('rg_event_waldschule_bad_media_v101111_status',array('status'=>'no-repeated-context-candidate','checked_at'=>$now,'rows'=>count($rows)),false);
            update_option('rg_event_waldschule_bad_media_v101111_done',$now,false);
            return;
        }

        $block=array('hashes'=>array(),'urls'=>array(),'created_at'=>$now,'reason'=>'waldschule-cappenberg-repeated-context-v101111');
        if($bad['hash']!=='')$block['hashes'][]=$bad['hash'];
        if($bad['url']!=='')$block['urls'][]=strtolower(preg_replace('/[?#].*$/','',$bad['url']));
        update_option('rg_event_media_surgical_blocklist_v101111',$block,false);

        $ids=array_values(array_unique(array_map('intval',$bad['rows'])));$eventIds=array_values(array_unique(array_map('intval',array_keys($bad['events']))));
        if($ids){$idSql=implode(',',$ids);$wpdb->query("UPDATE $media SET moderation_status='rejected',is_primary=0,health_status='invalid',health_error='surgical-block-v101111',visual_quality_status='rejected',visual_quality_reason='surgical-block-waldschule-v101111',visual_quality_checked_at='".esc_sql($now)."',local_cache_error='Gesperrt: wiederholtes falsches Waldschule-Kontextbild 1.10.111' WHERE id IN ($idSql)");}

        // If the Event-Ort image originated from the venue's place_media pool,
        // disable only the matching URL row. No other place image is touched.
        $placeIds=(array)$wpdb->get_col($wpdb->prepare("SELECT id FROM $places WHERE active=1 AND city=%s AND LOWER(name) LIKE %s",'Selm','%waldschule%cappenberg%'));
        if($placeIds&&$bad['url']!==''){
            $pSql=implode(',',array_map('intval',$placeIds));$plain=strtolower(preg_replace('/[?#].*$/','',$bad['url']));
            $pmRows=(array)$wpdb->get_results("SELECT id,url,source_url FROM $placeMedia WHERE place_id IN ($pSql) AND moderation_status='active'",ARRAY_A);
            foreach($pmRows as $pm){$u1=strtolower(preg_replace('/[?#].*$/','',esc_url_raw((string)($pm['url']??''))));$u2=strtolower(preg_replace('/[?#].*$/','',esc_url_raw((string)($pm['source_url']??''))));if($plain!==''&&($u1===$plain||$u2===$plain)){$wpdb->update($placeMedia,array('moderation_status'=>'disabled','is_primary'=>0,'disabled_at'=>$now,'removal_reason'=>'Gesperrt fuer Event-Ort: wiederholtes falsches Waldschule-Kontextbild 1.10.111'),array('id'=>(int)$pm['id']));}}
            foreach($placeIds as $pid){delete_transient('rg_event_venue_context_v287_'.(int)$pid);delete_transient('rg_event_venue_context_v235_'.(int)$pid);}
        }

        if($eventIds){$eventSql=implode(',',$eventIds);$wpdb->query("UPDATE $events SET media_status='pending',enrichment_status='retry',updated_at='".esc_sql($now)."' WHERE id IN ($eventSql)");$wpdb->query("UPDATE $enr SET last_enriched_at=NULL,last_error='',updated_at='".esc_sql($now)."' WHERE event_id IN ($eventSql)");foreach($eventIds as $eid)$this->event_reselect_primary_v1042((int)$eid);}
        update_option('rg_event_waldschule_bad_media_v101111_status',array('status'=>'blocked','checked_at'=>$now,'event_rows'=>count($ids),'events'=>count($eventIds),'hash'=>$bad['hash'],'url'=>$bad['url']),false);
        update_option('rg_event_waldschule_bad_media_v101111_done',$now,false);
        if($eventIds)$this->start_event_fallback_media_wave_v1044('v101111-surgical-waldschule-block');
    }

    private function event_media_is_surgically_blocked_v101111($url,$localHash='',$sourceHash='') {
        $block=get_option('rg_event_media_surgical_blocklist_v101111',array());if(!is_array($block))return false;
        $hashes=array_map('strtolower',(array)($block['hashes']??array()));
        foreach(array($localHash,$sourceHash) as $h){$h=strtolower(trim((string)$h));if($h!==''&&in_array($h,$hashes,true))return true;}
        $u=strtolower(preg_replace('/[?#].*$/','',esc_url_raw((string)$url)));if($u==='')return false;
        foreach((array)($block['urls']??array()) as $blocked){if($u===strtolower((string)$blocked))return true;}
        return false;
    }

    /** 1.10.110: auto fallback images are never visitor-live before the new crop-aware quality gate passed. */
    private function maybe_migrate_event_auto_visual_quality_v101110() {
        if (get_option('rg_event_auto_visual_quality_v101110_migrated')) return;
        global $wpdb;
        $media=$this->table('event_media');
        // dbDelta has already added the visual-quality columns at init priority 2.
        // Legacy automatic fallbacks become pending-by-default and therefore fail
        // closed in every visitor query until the resumable 1.10.110 audit passes them.
        $wpdb->query("UPDATE $media SET visual_quality_status='unchecked',visual_quality_reason='legacy-awaiting-v101110',visual_quality_checked_at=NULL WHERE source IN ('venue-commons-context','pexels-symbolic-event') AND moderation_status='active' AND (visual_quality_status='' OR visual_quality_status='unchecked')");
        delete_option('rg_events_media_quality_repair_started_v101110');
        update_option('rg_events_media_quality_repair_pending_v101110', current_time('mysql'), false);
        update_option(self::OPTION_CATALOG_VERSION,'event-auto-visual-quality-v101110-'.gmdate('YmdHis'),false);
        wp_clear_scheduled_hook(self::REPROCESS_HOOK);
        update_option('rg_event_auto_visual_quality_v101110_migrated',current_time('mysql'),false);
    }


    /** 1.10.112: policy reset after editorial clarification: posters, symbolic and venue images are valid media. */
    private function maybe_relax_event_media_policy_v101112() {
        if (get_option('rg_event_media_policy_v101112_migrated')) return;
        global $wpdb;
        $media=$this->table('event_media');$placeMedia=$this->table('place_media');$events=$this->table('events');$now=current_time('mysql');

        // Re-enable only rows that were machine-rejected by the temporary visual/text gates
        // or the one-off Waldschule block. Explicit rights/editorial rejections remain untouched.
        $wpdb->query("UPDATE $media SET moderation_status='active',health_status='unchecked',health_error='',visual_quality_status='allowed',visual_quality_reason='editorial-policy-v101112',visual_quality_checked_at='".esc_sql($now)."',local_cache_error='' WHERE media_type='image' AND source IN ('venue-commons-context','pexels-symbolic-event') AND rights_status<>'rejected' AND local_cache_status='ready' AND local_path<>'' AND moderation_status='rejected' AND (health_error LIKE 'auto-quality%' OR health_error='surgical-block-v101111' OR local_cache_error LIKE '%Qualitätsfilter%' OR local_cache_error LIKE '%Bildqualitätsfilter%' OR local_cache_error LIKE '%Waldschule-Kontextbild%')");
        $wpdb->query("UPDATE $media SET visual_quality_status='allowed',visual_quality_reason='editorial-policy-v101112',visual_quality_checked_at='".esc_sql($now)."' WHERE media_type='image' AND source IN ('venue-commons-context','pexels-symbolic-event') AND rights_status<>'rejected' AND local_cache_status='ready' AND local_path<>'' AND moderation_status='active'");
        $wpdb->query("UPDATE $placeMedia SET moderation_status='active',disabled_at=NULL,disabled_by=0,removal_reason=NULL WHERE media_type='image' AND moderation_status='disabled' AND removal_reason LIKE 'Gesperrt fuer Event-Ort:%Waldschule-Kontextbild%'");
        delete_option('rg_event_media_surgical_blocklist_v101111');
        delete_option('rg_events_media_quality_repair_pending_v101110');delete_option('rg_events_media_quality_repair_started_v101110');

        // The old text/poster quality jobs are now historical. Mark any unfinished state complete
        // so they cannot re-quarantine media after this policy change.
        $state=get_option(self::REPROCESS_STATE,array());if(!is_array($state))$state=array();
        foreach(array('event-fallback-media-quality-v101107','event-fallback-media-quality-v101110') as $key){
            if(isset($state['jobs'][$key])&&is_array($state['jobs'][$key])){
                $state['jobs'][$key]['status']='complete';$state['jobs'][$key]['finished_at']=$now;$state['jobs'][$key]['wait_reason']='';$state['jobs'][$key]['last_result']='Abgeschlossen durch Medienrichtlinie 1.10.112: Ortsbilder, Symbolbilder und Plakate sind erlaubt.';
            }
        }
        update_option(self::REPROCESS_STATE,$state,false);
        wp_clear_scheduled_hook(self::REPROCESS_HOOK);

        // Re-select primary media for events touched by the former automated gates.
        $eventIds=(array)$wpdb->get_col("SELECT DISTINCT event_id FROM $media WHERE media_type='image' AND source IN ('venue-commons-context','pexels-symbolic-event') AND moderation_status='active' AND local_cache_status='ready' AND local_path<>'' LIMIT 5000");
        foreach($eventIds as $eid)$this->event_reselect_primary_v1042((int)$eid);
        if($eventIds){$ids=implode(',',array_map('intval',$eventIds));$wpdb->query("UPDATE $events SET media_status='verified',updated_at='".esc_sql($now)."' WHERE id IN ($ids)");}

        update_option(self::OPTION_CATALOG_VERSION,'media-crop-policy-v101112-'.gmdate('YmdHis'),false);
        update_option('rg_event_media_policy_v101112_migrated',$now,false);
    }

