    private function maybe_restart_broad_supplemental_v180() {
        if (get_option('rg_events_supplemental_exact_city_v180_migrated')) return;
        $state = get_option('rg_events_supplemental_state', array());
        if (!is_array($state)) $state = array();
        // v1.7.9 accepted any of the 53 municipalities after a city-scoped provider call.
        // If such a wave is still running, restart it from city 0 with the exact-city gate.
        if (($state['status'] ?? '') === 'running' && (int)($state['cities_done'] ?? 0) > 0) {
            $token = sanitize_key((string)($state['master_run_token'] ?? ''));
            $this->start_event_supplemental_wave($token);
            $fresh = get_option('rg_events_supplemental_state', array());
            if (!is_array($fresh)) $fresh = array();
            $fresh['restart_reason'] = 'v1.8.0 exact-city gate: breiten v1.7.9-Lauf neu bei Stadt 1 gestartet';
            update_option('rg_events_supplemental_state', $fresh, false);
        }
        update_option('rg_events_supplemental_exact_city_v180_migrated', current_time('mysql'), false);
    }

    private function maybe_restart_supplemental_tracking_v182() {
        if (get_option('rg_events_supplemental_tracking_v182_migrated')) return;
        $night = get_option('rg_events_nightly_state', array());
        if (!is_array($night) || ($night['status'] ?? '') !== 'finished') {
            update_option('rg_events_supplemental_tracking_v182_migrated', current_time('mysql'), false);
            return;
        }
        $token = sanitize_key((string)($night['run_token'] ?? ''));
        if ($token !== '') {
            // Start one fresh exact-city wave so every accepted supplemental occurrence
            // receives a deterministic supplemental run token before stale rows are pruned.
            $this->start_event_supplemental_wave($token);
            $fresh = get_option('rg_events_supplemental_state', array());
            if (!is_array($fresh)) $fresh = array();
            $fresh['restart_reason'] = 'v1.8.2: sauberer 53-Städte-Lauf mit Supplemental-Run-Tracking gestartet';
            update_option('rg_events_supplemental_state', $fresh, false);
        }
        update_option('rg_events_supplemental_tracking_v182_migrated', current_time('mysql'), false);
    }

    private function maybe_restart_rich_supplemental_media_v1027() {
        // Do not reset a currently running event wave. The next normal init after it
        // finishes will enter here again and start one complete rich-source pass.
        if (get_option('rg_events_supplemental_rich_media_v1027_migrated')) return;
        $supp = get_option('rg_events_supplemental_state', array());
        if (!is_array($supp)) $supp = array();
        if (($supp['status'] ?? '') === 'running') return;
        $night = get_option('rg_events_nightly_state', array());
        if (!is_array($night) || ($night['status'] ?? '') !== 'finished') return;
        $token = sanitize_key((string)($night['run_token'] ?? ''));
        if ($token === '') return;

        // Re-run the canonical catalog once with the v1.10.27 title-candidate fix,
        // then refresh all 53 public supplemental city feeds from rich source objects.
        delete_option(self::EVENT_CATALOG_MEDIA_DONE);
        delete_option(self::EVENT_CATALOG_MEDIA_STATE);
        wp_clear_scheduled_hook(self::EVENT_CATALOG_MEDIA_HOOK);
        $this->ensure_et4_catalog_media_backfill_v1022();
        $this->start_event_supplemental_wave($token);
        $fresh = get_option('rg_events_supplemental_state', array());
        if (!is_array($fresh)) $fresh = array();
        $fresh['restart_reason'] = 'v1.10.27: rich unique ET4 source objects fuer vollstaendige Eventbilder';
        update_option('rg_events_supplemental_state', $fresh, false);
        update_option('rg_events_supplemental_rich_media_v1027_migrated', current_time('mysql'), false);
    }

