    public function seed_municipalities() {
        global $wpdb;
        $table = $this->table('places_municipalities');
        $now = current_time('mysql', true);
        foreach ($this->municipalities_seed() as $entry) {
            list($name, $level, $group) = $entry;
            $slug = sanitize_title($name);
            $wpdb->query($wpdb->prepare(
                "INSERT INTO $table (slug,name,admin_level,group_name,status,updated_at)
                 VALUES (%s,%s,%d,%s,'pending',%s)
                 ON DUPLICATE KEY UPDATE name=VALUES(name),admin_level=VALUES(admin_level),group_name=VALUES(group_name),updated_at=VALUES(updated_at)",
                $slug, $name, $level, $group, $now
            ));
        }
    }

    public function cron_schedules($schedules) {
        if (!isset($schedules[self::CRON_SCHEDULE])) {
            $schedules[self::CRON_SCHEDULE] = array(
                'interval' => 15 * MINUTE_IN_SECONDS,
                'display' => 'Alle 15 Minuten (RuhrpottGuru Places)',
            );
        }
        if (!isset($schedules[self::EVENT_HOT_SCHEDULE])) {
            $schedules[self::EVENT_HOT_SCHEDULE] = array(
                'interval' => 4 * HOUR_IN_SECONDS,
                'display' => 'Alle 4 Stunden (RuhrpottGuru Events 0–14 Tage)',
            );
        }
        if (!isset($schedules[self::EVENT_WEEKLY_SCHEDULE])) {
            $schedules[self::EVENT_WEEKLY_SCHEDULE] = array(
                'interval' => 7 * DAY_IN_SECONDS,
                'display' => 'Wöchentlich (RuhrpottGuru Events 365 Tage)',
            );
        }
        return $schedules;
    }

    private function ensure_cron_event() {
        if (!wp_next_scheduled(self::CRON_HOOK)) {
            wp_schedule_event(time() + 300, self::CRON_SCHEDULE, self::CRON_HOOK);
        }
    }

    private function next_events_hot_timestamp_v101101() {
        $tz=wp_timezone();$now=new DateTimeImmutable('now',$tz);
        $hour=(int)$now->format('G');$nextHour=((int)floor($hour/4)+1)*4;
        if($nextHour>=24){$next=$now->modify('+1 day')->setTime(0,0,0);}
        else{$next=$now->setTime($nextHour,0,0);}
        if($next<=$now)$next=$next->modify('+4 hours');
        return $next->getTimestamp();
    }

    private function next_events_plan_timestamp_v101101() {
        $tz=wp_timezone();$now=new DateTimeImmutable('now',$tz);$next=$now->setTime(1,0,0);
        if($next<=$now)$next=$next->modify('+1 day');
        return $next->getTimestamp();
    }

    private function next_events_nightly_timestamp() {
        // V1.10.101: the former nightly 365-day master is now the weekly
        // reconciliation wave. Sunday 03:00 local time avoids the daily 01:00
        // planning refresh while preserving a quiet server window.
        $tz=wp_timezone();$now=new DateTimeImmutable('now',$tz);
        $days=(7-(int)$now->format('w'))%7;
        $next=$now->setTime(3,0,0);
        if($days>0)$next=$next->modify('+'.$days.' days');
        if($next<=$now)$next=$next->modify('+7 days');
        return $next->getTimestamp();
    }

    private function ensure_events_nightly_cron() {
        // Migrate the historical daily 03:00 full import to one weekly full
        // reconciliation. A running batch uses EVENT_NIGHTLY_BATCH_HOOK and is
        // deliberately not touched by this scheduling migration.
        $scheduled=wp_next_scheduled(self::EVENT_NIGHTLY_HOOK);
        $schedule=$scheduled?wp_get_schedule(self::EVENT_NIGHTLY_HOOK):false;
        $local=$scheduled?wp_date('w H:i',$scheduled,wp_timezone()):'';
        if(!$scheduled || $schedule!==self::EVENT_WEEKLY_SCHEDULE || $local!=='0 03:00'){
            wp_clear_scheduled_hook(self::EVENT_NIGHTLY_HOOK);
            wp_schedule_event($this->next_events_nightly_timestamp(),self::EVENT_WEEKLY_SCHEDULE,self::EVENT_NIGHTLY_HOOK);
        }

        $hot=wp_next_scheduled(self::EVENT_HOT_HOOK);
        if(!$hot || wp_get_schedule(self::EVENT_HOT_HOOK)!==self::EVENT_HOT_SCHEDULE){
            wp_clear_scheduled_hook(self::EVENT_HOT_HOOK);
            wp_schedule_event($this->next_events_hot_timestamp_v101101(),self::EVENT_HOT_SCHEDULE,self::EVENT_HOT_HOOK);
        }

        $plan=wp_next_scheduled(self::EVENT_PLAN_HOOK);
        $planLocal=$plan?wp_date('H:i',$plan,wp_timezone()):'';
        if(!$plan || wp_get_schedule(self::EVENT_PLAN_HOOK)!=='daily' || $planLocal!=='01:00'){
            wp_clear_scheduled_hook(self::EVENT_PLAN_HOOK);
            wp_schedule_event($this->next_events_plan_timestamp_v101101(),'daily',self::EVENT_PLAN_HOOK);
        }
    }

    private function runtime_mode() {
        $forced = defined('RUHRPOTT_GURU_PLACES_MODE') ? strtolower((string) RUHRPOTT_GURU_PLACES_MODE) : '';
        if ($forced === 'osm') {
            return 'osm';
        }
        if ($forced === 'database') {
            return get_option(self::OPTION_STATUS) === 'ready' ? 'database' : 'osm';
        }
        $mode = strtolower((string) get_option(self::OPTION_MODE, 'auto'));
        if ($mode === 'osm') {
            return 'osm';
        }
        if ($mode === 'database') {
            return get_option(self::OPTION_STATUS) === 'ready' ? 'database' : 'osm';
        }
        return get_option(self::OPTION_STATUS) === 'ready' ? 'database' : 'osm';
    }

    public function filter_runtime_settings($settings) {
        if (!is_array($settings)) {
            $settings = array();
        }
        $mode = $this->runtime_mode();
        $settings['placesMode'] = $mode;
        $settings['placesStatus'] = (string) get_option(self::OPTION_STATUS, 'bootstrap_pending');
        $settings['placesCatalogVersion'] = (string) get_option(self::OPTION_CATALOG_VERSION, 'bootstrap');
        $settings['placesHomeUrl'] = esc_url_raw(rest_url('ruhrpottguru/v1/places/home'));
        $settings['placesStatusUrl'] = esc_url_raw(rest_url('ruhrpottguru/v1/places/status'));
        $settings['industrialRouteUrl'] = esc_url_raw(rest_url('ruhrpottguru/v1/places/industrial-route'));
        $settings['shareItemUrl'] = esc_url_raw(rest_url('ruhrpottguru/v1/share-item'));
        $settings['shareBaseUrl'] = esc_url_raw(home_url('/teilen/'));
        $settings['seoPlaceBaseUrl'] = esc_url_raw(home_url('/ort/'));
        $settings['seoEventBaseUrl'] = esc_url_raw(home_url('/veranstaltung/'));
        $settings['seoDeepLinksEnabled'] = true;
        if ($mode === 'database') {
            // The compiled category loader already talks to an OSM-proxy-shaped endpoint.
            // Point it at the DB compatibility adapter; no browser/provider rewrite required.
            $settings['overpassProxyUrl'] = esc_url_raw(rest_url('ruhrpottguru/v1/places/overpass'));
            $settings['osmTransportVersion'] = 'places-db-v1.2.4';
        }
        return $settings;
    }

    public function enqueue_frontend_cache_reset() {
        if ($this->runtime_mode() !== 'database') return;
        if (!function_exists('wp_add_inline_script')) return;
        $js = '(function(){try{var m="rg_places_adapter_cache_reset",v="1.2.4";if(localStorage.getItem(m)===v)return;for(var i=sessionStorage.length-1;i>=0;i--){var k=sessionStorage.key(i)||"";if(k.indexOf("ruhrpott_osm_")===0||k.indexOf("rg_snap_")===0||k.indexOf("rg_home_pool_")===0){sessionStorage.removeItem(k);}}localStorage.setItem(m,v);}catch(e){}})();';
        wp_add_inline_script('ruhrpott-compiled-js', $js, 'before');
    }

    private function share_category_from_value($value) {
        $value = strtolower(trim((string)$value));
        $map = array(
            'e'=>'events','event'=>'events','events'=>'events','veranstaltung'=>'events','veranstaltungen'=>'events',
            'f'=>'food','food'=>'food','gastronomie'=>'food','restaurant'=>'food',
            'h'=>'highlights','highlight'=>'highlights','highlights'=>'highlights','sehenswuerdigkeit'=>'highlights','sehenswürdigkeit'=>'highlights',
            'c'=>'culture','culture'=>'culture','kultur'=>'culture',
            'a'=>'activities','aktiv'=>'activities','activity'=>'activities','activities'=>'activities','aktivitaeten'=>'activities','aktivitäten'=>'activities',
            'w'=>'wurst','wurst'=>'wurst','imbiss'=>'wurst',
            'b'=>'buedchen','buedchen'=>'buedchen','büdchen'=>'buedchen','trinkhalle'=>'buedchen',
        );
        return isset($map[$value]) ? $map[$value] : '';
    }

    private function share_category_code($category) {
        $category = $this->share_category_from_value($category);
        $map = array('events'=>'e','food'=>'f','highlights'=>'h','culture'=>'c','activities'=>'a','wurst'=>'w','buedchen'=>'b');
        return isset($map[$category]) ? $map[$category] : '';
    }

    private function share_segment_for_category($category) {
        $category = $this->share_category_from_value($category);
        $map = array('events'=>'event','food'=>'food','highlights'=>'highlight','culture'=>'kultur','activities'=>'aktiv','wurst'=>'imbiss','buedchen'=>'buedchen');
        return isset($map[$category]) ? $map[$category] : 'ort';
    }

    private function share_trim_description($value, $fallback='') {
        $text = trim(preg_replace('/\\s+/u', ' ', wp_strip_all_tags((string)$value)));
        if ($text === '') $text = trim((string)$fallback);
        if (function_exists('mb_strlen') && mb_strlen($text, 'UTF-8') > 190) return rtrim(mb_substr($text, 0, 187, 'UTF-8')) . '…';
        return strlen($text) > 190 ? rtrim(substr($text, 0, 187)) . '…' : $text;
    }

    private function share_place_payload($place_id, $category='') {
        global $wpdb;
        $place_id = absint($place_id);
        if (!$place_id) return null;
        $places = $this->table('places');
        $row = $wpdb->get_row($wpdb->prepare("SELECT p.*,p.primary_subcategory AS subcategory FROM $places p WHERE p.id=%d AND p.active=1 LIMIT 1", $place_id), ARRAY_A);
        if (!$row) return null;
        $category = $this->share_category_from_value($category);
        if ($category === 'events' || $category === '') $category = $this->share_category_from_value((string)($row['primary_category'] ?? ''));
        if (!in_array($category, array('food','highlights','culture','activities','wurst','buedchen'), true)) $category = 'highlights';
        $row['_rg_response_category'] = $category;
        // 1.10.153: direct/share detail must use the same visitor projection as
        // category results, otherwise intelligence chips disappear on deep links.
        if($category==='highlights'){
            $profile=$this->highlight_experience_profile($row);
            if($profile){$row['_rg_highlight_score']=$profile['score'];$row['_rg_highlight_rank_score']=$profile['rank_score'];$row['_rg_highlight_tier']=$profile['tier'];$row['_rg_highlight_bucket']=$profile['bucket'];$row['_rg_highlight_tags']=$profile['labels'];$row['_rg_response_subcategory']=$profile['subcategory'];if(!empty($profile['route'])){$row['_rg_industrial_route_slug']=$profile['route']['slug'];$row['_rg_industrial_route_type']=$profile['route']['type'];$row['_rg_industrial_route_title']=$profile['route']['title'];}}
        }elseif($category==='culture'){
            $profile=$this->culture_experience_profile($row);
            if($profile){$row['_rg_culture_score']=$profile['score'];$row['_rg_culture_rank_score']=$profile['rank_score'];$row['_rg_culture_bucket']=$profile['bucket'];$row['_rg_culture_tags']=$profile['labels'];$row['_rg_response_subcategory']=$profile['subcategory'];}
        }elseif($category==='activities'){
            $profile=$this->activity_v2_public_projection($row);
            if($profile){$row['_rg_activity_score']=$profile['score'];$row['_rg_activity_rank_score']=$profile['rank_score'];$row['_rg_activity_bucket']=$profile['bucket'];$row['_rg_experience_tags']=$profile['labels'];$row['_rg_response_subcategory']=$profile['subcategory'];$row['_rg_activity_v2_admission']='rein';$row['_rg_activity_v2_primary']=$profile['primary_experience'];$row['_rg_activity_environment']=$profile['environment'];$row['_rg_activity_multi_count']=$profile['multi_experience_count'];}
        }
        $elements = $this->rows_to_elements(array($row));
        if (!$elements) return null;
        $element = $elements[0];
        $tags = isset($element['tags']) && is_array($element['tags']) ? $element['tags'] : array();
        $title = trim((string)($tags['name'] ?? $row['name'] ?? 'RuhrpottGuru-Tipp'));
        $city = trim((string)($tags['addr:city'] ?? $row['city'] ?? ''));
        $address = trim(implode(' ', array_filter(array(
            trim((string)($tags['addr:street'] ?? '')),
            trim((string)($tags['addr:housenumber'] ?? '')),
            trim((string)($tags['addr:postcode'] ?? '')),
            $city,
        ))));
        $desc_fallback = trim(($category === 'food' ? 'Gastronomie-Tipp' : ($category === 'activities' ? 'Aktivität' : ($category === 'culture' ? 'Kultur-Tipp' : 'RuhrpottGuru-Tipp'))) . ($city !== '' ? ' in ' . $city : ' im Ruhrgebiet'));
        $description = $this->share_trim_description($tags['description'] ?? ($tags['description:de'] ?? ''), $desc_fallback);
        $image = esc_url_raw((string)($tags['image:url'] ?? ($tags['image'] ?? '')));
        return array(
            'ok'=>true,'kind'=>'place','token'=>'p'.$place_id,'category'=>$category,'categoryCode'=>$this->share_category_code($category),
            'element'=>$element,
            'share'=>array('title'=>$title,'description'=>$description,'image'=>$image,'city'=>$city,'address'=>$address,'id'=>$place_id),
        );
    }

    /**
     * 1.10.162 – public discovery source membership.
     *
     * Only stable source keys are exposed to the visitor read model. URLs,
     * rights notes, permissions and credits stay in their existing dedicated
     * fields and are deliberately not copied into this discovery metadata.
     */
    private function event_public_source_membership_map_v101162($event_ids) {
        global $wpdb;
        $ids=array_values(array_unique(array_filter(array_map('absint',(array)$event_ids))));
        if(!$ids)return array();
        $sources=$this->table('event_sources');$map=array();
        foreach(array_chunk($ids,300) as $chunk){
            $id_sql=implode(',',array_map('intval',$chunk));if($id_sql==='')continue;
            $rows=(array)$wpdb->get_results("SELECT event_id,source_name FROM $sources WHERE event_id IN ($id_sql) AND source_name<>'' ORDER BY event_id ASC,id ASC",ARRAY_A);
            foreach($rows as $row){$eid=(int)($row['event_id']??0);$key=sanitize_key((string)($row['source_name']??''));if(!$eid||$key==='')continue;if(!isset($map[$eid]))$map[$eid]=array();$map[$eid][$key]=1;}
        }
        foreach($map as $eid=>$set)$map[$eid]=array_keys($set);
        return $map;
    }

    private function event_public_source_keys_for_row_v101162($row,$membership_map=array()) {
        $row=is_array($row)?$row:array();$out=array();
        $add=function($value)use(&$out){$key=sanitize_key((string)$value);if($key!=='')$out[$key]=1;};
        $add($row['source']??'');$ids=array((int)($row['id']??0));
        foreach((array)($row['_rpg_cluster_ids']??array()) as $memberId)$ids[]=(int)$memberId;
        foreach(array_values(array_unique(array_filter($ids))) as $eid){foreach((array)($membership_map[$eid]??array()) as $key)$add($key);}
        return array_keys($out);
    }

    private function share_event_payload($event_id) {
        global $wpdb;
        $event_id = absint($event_id);
        if (!$event_id) return null;
        $events = $this->table('events');
        $row = $wpdb->get_row($wpdb->prepare("SELECT * FROM $events WHERE id=%d LIMIT 1", $event_id), ARRAY_A);
        if (!$row) return null;
        $row=$this->event_apply_curated_visitor_data_to_row($row);
        $raw = json_decode((string)($row['raw_payload'] ?? ''), true);
        if (!is_array($raw)) $raw = array();
        $raw['global_id'] = $row['external_id'] !== '' ? (string)$row['external_id'] : (string)$row['canonical_key'];
        $raw['id'] = $raw['global_id'];
        $raw['title'] = (string)$row['title'];
        $raw['description'] = (string)$row['description'];
        $raw['start'] = !empty($row['start_at']) ? $this->event_visitor_datetime_iso($row['start_at'],$row) : '';
        if (!empty($row['end_at'])) $raw['end'] = $this->event_visitor_datetime_iso($row['end_at'],$row); else unset($raw['end'],$raw['endDate'],$raw['end_date'],$raw['to']);
        $raw['venueName'] = (string)$row['venue_name'];
        $raw['category'] = (string)$row['event_category'];
        if ($row['lat'] !== null && $row['lng'] !== null) {
            $raw['latitude'] = (float)$row['lat']; $raw['longitude'] = (float)$row['lng'];
            $raw['geo'] = array('latitude'=>(float)$row['lat'],'longitude'=>(float)$row['lng']);
        }
        $raw['address'] = array(
            'street'=>(string)$row['street'],'houseNumber'=>(string)$row['house_number'],
            'postalCode'=>(string)$row['postcode'],'city'=>(string)$row['city'],
            'addressLocality'=>(string)$row['city'],'type'=>'event','rel'=>'event'
        );
        // source_url is provenance and may point to destination.one/eT4. Never expose it
        // as a visitor link in the direct-share payload. event_apply_db_enrichment_to_item()
        // resolves a validated public website separately.
        unset($raw['url'],$raw['detailUrl'],$raw['detail_url'],$raw['website'],$raw['sameAs']);
        if (!empty($row['ticket_url'])) $raw['ticketUrl']=(string)$row['ticket_url'];
        $raw['provider_source']=(string)$row['source'];
        $raw['source_name']=(string)$row['source'];
        $shareSourceMap=$this->event_public_source_membership_map_v101162(array($event_id));
        $raw['rpg_sources']=$this->event_public_source_keys_for_row_v101162($row,$shareSourceMap);
        $raw = $this->event_apply_db_enrichment_to_item($raw, $event_id);
        // 1.10.78: finalize direct/share media with the SAME rights-aware hierarchy as
        // the normal /events visitor response. This also strips raw ET4 media branches,
        // so a provider URL can never outrank the verified localized handoff in React.
        $raw = $this->event_finalize_direct_media_v1078($raw,$row,$event_id);
        $raw = $this->event_sanitize_public_range_v101155($raw,$row);
        $image = '';
        if (!empty($raw['rpg_event_media']['imageUrl'])) $image = esc_url_raw((string)$raw['rpg_event_media']['imageUrl']);
        $city = trim((string)$row['city']);
        $venue = trim((string)$row['venue_name']);
        $fallback = trim(implode(' · ', array_filter(array($venue, $city, !empty($row['start_at']) ? wp_date('j. F Y · H:i', strtotime((string)$row['start_at'])) : ''))));
        $description = $this->share_trim_description((string)($row['short_description'] ?: $row['description']), $fallback ?: 'Event im Ruhrgebiet');
        $address = trim(implode(' ', array_filter(array((string)$row['street'],(string)$row['house_number'],(string)$row['postcode'],$city))));
        return array(
            'ok'=>true,'kind'=>'event','token'=>'e'.$event_id,'category'=>'events','categoryCode'=>'e','item'=>$raw,
            'share'=>array('title'=>(string)$row['title'],'description'=>$description,'image'=>$image,'city'=>$city,'address'=>$address,'id'=>$event_id),
        );
    }

    private function share_rdi_payload($slug) {
        $slug = sanitize_title((string)$slug);
        if ($slug === '') return null;
        foreach ($this->industrial_route_dataset() as $entry) {
            if ((string)($entry['slug'] ?? '') !== $slug) continue;
            if (!empty($entry['row']) && is_array($entry['row'])) {
                $row = $entry['row'];
                $row['_rg_response_category']='highlights';
                $row['_rg_industrial_route_slug']=$slug;
                $row['_rg_industrial_route_type']=(string)($entry['type'] ?? '');
                $row['_rg_industrial_route_title']=(string)($entry['title'] ?? ($row['name'] ?? ''));
                $elements = $this->rows_to_elements(array($row));
                if ($elements) {
                    $element=$elements[0];
                    if (!isset($element['tags']) || !is_array($element['tags'])) $element['tags']=array();
                    $element['tags']['rg:industrial_route_official_url']=(string)($entry['officialUrl']??'');
                    $tags=$element['tags'];
                    $image=esc_url_raw((string)($tags['image:url']??($entry['fallbackImage']??'')));
                    return array('ok'=>true,'kind'=>'place','token'=>'rdi:'.$slug,'category'=>'highlights','categoryCode'=>'h','element'=>$element,
                        'share'=>array('title'=>(string)$entry['title'],'description'=>$this->share_trim_description('', 'Route der Industriekultur · '.(string)$entry['city']),'image'=>$image,'city'=>(string)$entry['city'],'address'=>'','id'=>'rdi:'.$slug));
                }
            }
            $lat=isset($entry['fallbackLat'])?(float)$entry['fallbackLat']:null; $lng=isset($entry['fallbackLng'])?(float)$entry['fallbackLng']:null;
            $item=array('kind'=>'place','id'=>'rdi:'.$slug,'category'=>'highlights','title'=>(string)$entry['title'],'subtitle'=>'','city'=>(string)$entry['city'],'address'=>'',
                'coords'=>($lat!==null&&$lng!==null)?array('lat'=>$lat,'lng'=>$lng):null,'distanceKm'=>null,'tags'=>array(),'labels'=>array(),'description'=>'',
                'website'=>'','menuUrl'=>'','reservationUrl'=>'','openingHours'=>'','phone'=>'','imageUrl'=>(string)($entry['fallbackImage']??''),'galleryImages'=>array(),
                'routeIndustrial'=>true,'routeType'=>(string)($entry['type']??''),'routeTitle'=>(string)$entry['title'],'routeOfficialUrl'=>(string)($entry['officialUrl']??''));
            return array('ok'=>true,'kind'=>'direct','token'=>'rdi:'.$slug,'category'=>'highlights','categoryCode'=>'h','item'=>$item,
                'share'=>array('title'=>(string)$entry['title'],'description'=>$this->share_trim_description('', 'Route der Industriekultur · '.(string)$entry['city']),'image'=>esc_url_raw((string)($entry['fallbackImage']??'')),'city'=>(string)$entry['city'],'address'=>'','id'=>'rdi:'.$slug));
        }
        return null;
    }

    private function share_item_payload($token, $category='') {
        $token = trim((string)$token);
        if (preg_match('/^e(?:vent:)?(\\d+)$/i', $token, $m)) return $this->share_event_payload((int)$m[1]);
        if (preg_match('/^event:(\\d+)$/i', $token, $m)) return $this->share_event_payload((int)$m[1]);
        if (preg_match('/^p(?:lace:)?(\\d+)$/i', $token, $m)) return $this->share_place_payload((int)$m[1], $category);
        if (preg_match('/^place:(\\d+)$/i', $token, $m)) return $this->share_place_payload((int)$m[1], $category);
        if (preg_match('/^rdi:(.+)$/i', $token, $m)) return $this->share_rdi_payload($m[1]);
        return null;
    }

    public function rest_share_item(WP_REST_Request $request) {
        $token = sanitize_text_field((string)$request->get_param('token'));
        $category = sanitize_text_field((string)$request->get_param('category'));
        $payload = $this->share_item_payload($token, $category);
        if (!$payload) return new WP_REST_Response(array('ok'=>false,'error'=>'share-item-not-found'), 404);
        return rest_ensure_response($payload);
    }

    private function share_request_from_path() {
        $request_path = wp_parse_url('https://example.invalid' . (isset($_SERVER['REQUEST_URI']) ? wp_unslash($_SERVER['REQUEST_URI']) : '/'), PHP_URL_PATH);
        $request_path = trim(rawurldecode((string)$request_path), '/');
        $home_path = trim((string)wp_parse_url(home_url('/'), PHP_URL_PATH), '/');
        if ($home_path !== '' && strpos($request_path, $home_path . '/') === 0) $request_path = substr($request_path, strlen($home_path) + 1);
        if (!preg_match('#^teilen/(event|food|highlight|kultur|aktiv|imbiss|buedchen|industriekultur)/([^/]+)(?:/[^/]*)?/?$#iu', $request_path, $m)) return null;
        $segment = strtolower((string)$m[1]); $id = sanitize_text_field((string)$m[2]);
        if ($segment === 'industriekultur') return array('token'=>'rdi:'.sanitize_title($id),'category'=>'highlights');
        $map = array('event'=>'events','food'=>'food','highlight'=>'highlights','kultur'=>'culture','aktiv'=>'activities','imbiss'=>'wurst','buedchen'=>'buedchen');
        if (!isset($map[$segment]) || !ctype_digit($id)) return null;
        return array('token'=>($segment==='event'?'e':'p').(int)$id,'category'=>$map[$segment]);
    }

    public function maybe_render_share_landing() {
        if (is_admin() || (defined('REST_REQUEST') && REST_REQUEST)) return;
        $request = $this->share_request_from_path();
        if (!$request) return;
        $payload = $this->share_item_payload($request['token'], $request['category']);
        if (!$payload || empty($payload['share']['title'])) return;
        $share = $payload['share'];
        $title = trim((string)$share['title']);
        $description = $this->share_trim_description((string)($share['description'] ?? ''), 'Entdecke diesen Tipp bei RuhrpottGuru.');
        $image = esc_url_raw((string)($share['image'] ?? ''));
        if ($image === '') $image = esc_url_raw((string)get_site_icon_url(512));
        $category_code = (string)($payload['categoryCode'] ?? $this->share_category_code($payload['category'] ?? ''));
        $open_args=array('rg_open'=>(string)$payload['token'],'rgc'=>$category_code);
        $open_base=home_url('/');
        // 1.10.78: external Event links open over the Event world itself. The
        // coordinates are page-local URL context only; Theme v263 reads them
        // without persisting or replacing the visitor's saved GPS/manual city.
        if((string)($payload['kind']??'')==='event'){
            $open_base=home_url('/veranstaltungen/');$it=is_array($payload['item']??null)?$payload['item']:array();$geo=is_array($it['geo']??null)?$it['geo']:array();
            $lat=(float)($geo['latitude']??($it['latitude']??NAN));$lng=(float)($geo['longitude']??($it['longitude']??NAN));$eventCity=trim((string)($share['city']??($it['city']??($it['address']['city']??''))));
            if(is_finite($lat)&&is_finite($lng)&&abs($lat)<=90&&abs($lng)<=180){$open_args['rg_lat']=number_format($lat,6,'.','');$open_args['rg_lng']=number_format($lng,6,'.','');if($eventCity!=='')$open_args['rg_city']=$eventCity;}
            elseif($eventCity!==''){$open_args['place']=$eventCity;}
        }
        $open_url = add_query_arg($open_args, $open_base);
        $current_url = home_url('/' . trim((string)wp_parse_url('https://example.invalid' . wp_unslash($_SERVER['REQUEST_URI']), PHP_URL_PATH), '/') . '/');
        $canonical_url=$current_url;
        $share_id=$share['id']??'';
        if((string)($payload['kind']??'')==='event' && is_numeric($share_id)) $canonical_url=$this->seo_event_url_v101096((int)$share_id,$title,(string)($share['city']??''));
        elseif((string)($payload['kind']??'')==='place' && is_numeric($share_id)) $canonical_url=$this->seo_place_url_v101096((int)$share_id,$title,(string)($share['city']??''));
        nocache_headers(); status_header(200);
        header('Content-Type: text/html; charset=' . get_bloginfo('charset'));
        header('X-Robots-Tag: noindex, follow', true);
        $esc = function($v){ return esc_attr((string)$v); };
        echo '<!doctype html><html lang="de"><head><meta charset="'.esc_attr(get_bloginfo('charset')).'"><meta name="viewport" content="width=device-width,initial-scale=1">';
        echo '<title>'.esc_html($title.' | RuhrpottGuru').'</title>';
        echo '<meta name="description" content="'.$esc($description).'">';
        echo '<meta property="og:locale" content="de_DE"><meta property="og:type" content="website"><meta property="og:site_name" content="RuhrpottGuru">';
        echo '<meta property="og:title" content="'.$esc($title).'"><meta property="og:description" content="'.$esc($description).'"><meta property="og:url" content="'.$esc($current_url).'">';
        if ($image !== '') echo '<meta property="og:image" content="'.$esc($image).'"><meta property="og:image:secure_url" content="'.$esc($image).'">';
        echo '<meta name="twitter:card" content="'.($image!==''?'summary_large_image':'summary').'"><meta name="twitter:title" content="'.$esc($title).'"><meta name="twitter:description" content="'.$esc($description).'">';
        if ($image !== '') echo '<meta name="twitter:image" content="'.$esc($image).'">';
        echo '<link rel="canonical" href="'.$esc($canonical_url).'">';
        echo '</head><body style="margin:0;background:#020617;color:#f8fafc;font-family:system-ui,-apple-system,BlinkMacSystemFont,Segoe UI,sans-serif">';
        echo '<main style="min-height:100vh;display:grid;place-items:center;padding:24px"><div style="max-width:560px;text-align:center"><strong style="display:block;color:#f59e0b;font-size:14px;letter-spacing:.08em">RUHRPOTTGURU</strong><h1 style="font-size:26px;margin:12px 0">'.esc_html($title).'</h1><p style="color:#cbd5e1">'.esc_html($description).'</p><p><a style="display:inline-block;margin-top:12px;padding:12px 18px;border-radius:999px;background:#f59e0b;color:#020617;font-weight:800;text-decoration:none" href="'.esc_url($open_url).'">Tipp öffnen →</a></p></div></main>';
        echo '<script>window.location.replace('.wp_json_encode($open_url).');</script></body></html>';
        exit;
    }

    private function seo_request_path_v101096() {
        $path=wp_parse_url('https://example.invalid'.(isset($_SERVER['REQUEST_URI'])?wp_unslash($_SERVER['REQUEST_URI']):'/'),PHP_URL_PATH);
        $path=trim(rawurldecode((string)$path),'/');
        $home=trim((string)wp_parse_url(home_url('/'),PHP_URL_PATH),'/');
        if($home!=='' && strpos($path,$home.'/')===0)$path=substr($path,strlen($home)+1);
        return $path;
    }

    private function seo_place_url_v101096($place_id,$title='',$city='') {
        $place_id=absint($place_id);if(!$place_id)return '';
        $city_slug=sanitize_title((string)$city);if($city_slug==='')$city_slug='ruhrgebiet';
        $slug=sanitize_title((string)$title);if($slug==='')$slug='ort';
        return home_url('/ort/'.$place_id.'/'.$city_slug.'/'.$slug.'/');
    }

    private function seo_event_url_v101096($event_id,$title='',$city='') {
        $event_id=absint($event_id);if(!$event_id)return '';
        $city_slug=sanitize_title((string)$city);if($city_slug==='')$city_slug='ruhrgebiet';
        $slug=sanitize_title((string)$title);if($slug==='')$slug='veranstaltung';
        return home_url('/veranstaltung/'.$event_id.'/'.$city_slug.'/'.$slug.'/');
