    public function filter_robots_txt_v101096($output,$public) {
        $sitemap=home_url('/rpg-sitemap.xml');
        if(stripos((string)$output,'Sitemap: '.$sitemap)===false){
            $output=rtrim((string)$output)."\nSitemap: ".$sitemap."\n";
        }
        return $output;
    }

    private function seo_public_place_category_v101096($row) {
        if(!is_array($row) || empty($row['active']) || (string)($row['lifecycle_status']??'active')!=='active')return '';
        $primary=sanitize_key((string)($row['primary_category']??''));
        $passes=function($cat)use($row){
            if($cat==='food')return true;
            if($cat==='activities')return $this->activity_v2_public_projection($row)!==null;
            if($cat==='culture')return $this->culture_experience_profile($row)!==null;
            if($cat==='highlights')return $this->highlight_experience_profile($row)!==null;
            return false;
        };
        if(in_array($primary,array('food','highlights','culture','activities'),true) && $passes($primary))return $primary;
        // Cross-category fallback mirrors the existing visitor intelligence: a DB
        // primary category may differ from the category visitors actually see.
        foreach(array('highlights','culture','activities') as $cat){if($cat!==$primary && $passes($cat))return $cat;}
        return '';
    }

    private function seo_public_place_row_v101096($place_id) {
        global $wpdb;$place_id=absint($place_id);if(!$place_id)return null;
        $row=$wpdb->get_row($wpdb->prepare("SELECT * FROM {$this->table('places')} WHERE id=%d AND active=1 AND lifecycle_status='active' LIMIT 1",$place_id),ARRAY_A);
        if(!$row)return null;$cat=$this->seo_public_place_category_v101096($row);if($cat==='')return null;
        $row['_rg_response_category']=$cat;return $row;
    }

    private function seo_public_event_row_v101096($event_id) {
        global $wpdb;$event_id=absint($event_id);if(!$event_id)return null;$now=current_time('mysql',true);
        return $wpdb->get_row($wpdb->prepare("SELECT * FROM {$this->table('events')} WHERE id=%d AND status='active' AND COALESCE(end_at,start_at)>=%s LIMIT 1",$event_id,$now),ARRAY_A);
    }

    private function seo_category_label_v101096($cat) {
        $map=array('food'=>'Food & Drinks','highlights'=>'Sehenswürdigkeit','culture'=>'Kultur','activities'=>'Aktivität','events'=>'Event');
        return $map[$cat]??'RuhrpottGuru-Tipp';
    }

    /** 1.10.140: SEO/GEO presentation only. Derive a useful public type label from the
     * existing visitor/OSM truth without creating a second classification source. */
    private function seo_place_type_label_v101140($row,$tags,$cat) {
        $tags=is_array($tags)?$tags:array();
        $eq=function($key,$value)use($tags){return strtolower(trim((string)($tags[$key]??'')))===$value;};
        $has=function($key,$value)use($tags){$v=strtolower((string)($tags[$key]??''));return $v!==''&&strpos(';'.$v.';',';'.$value.';')!==false;};
        if($eq('tourism','museum'))return 'Museum';
        if($eq('amenity','theatre'))return 'Theater';
        if($eq('amenity','cinema'))return 'Kino';
        if($eq('tourism','gallery'))return 'Galerie';
        if($eq('tourism','artwork'))return 'Kunstwerk';
        if($eq('tourism','theme_park'))return 'Freizeitpark';
        if($eq('tourism','zoo'))return 'Zoo';
        if($eq('tourism','viewpoint'))return 'Aussichtspunkt';
        if($eq('historic','monument')||$eq('historic','memorial'))return 'Denkmal';
        if($eq('leisure','stadium'))return 'Stadion';
        if($eq('leisure','water_park'))return 'Erlebnisbad';
        if($eq('leisure','swimming_pool')||$eq('sport','swimming')||$has('sport','swimming'))return 'Schwimmbad';
        if($eq('leisure','bowling_alley'))return 'Bowling';
        if($eq('leisure','escape_game'))return 'Escape Game';
        if($eq('amenity','restaurant'))return 'Restaurant';
        if($eq('amenity','cafe'))return 'Café';
        if($eq('amenity','bar'))return 'Bar';
        if($eq('amenity','pub'))return 'Pub';
        if($eq('amenity','fast_food'))return 'Imbiss';
        $sub=trim((string)($row['primary_subcategory']??''));
        if($sub!=='')return $sub;
        return $this->seo_category_label_v101096($cat);
    }

    private function seo_place_description_v101140($title,$type,$city,$address,$hours,$source_description='') {
        $source_description=trim((string)$source_description);
        if($source_description!=='')return $source_description;
        $lead=trim((string)$title).' – '.trim((string)$type).($city!==''?' in '.$city:' im Ruhrgebiet').'.';
        $facts=array();
        if($address!=='')$facts[]='Adresse: '.$address.'.';
        if($hours!=='')$facts[]='Öffnungszeiten: '.$hours.'.';
        return trim($lead.(empty($facts)?'':' '.implode(' ',$facts)));
    }

    private function seo_xml_escape_v101096($value) {
        return function_exists('esc_xml')?esc_xml((string)$value):htmlspecialchars((string)$value,ENT_XML1|ENT_QUOTES,'UTF-8');
    }

    private function seo_sitemap_cache_key_v101096($kind) { return 'rg_seo_sitemap_v101096_'.sanitize_key($kind); }

    private function seo_place_sitemap_entries_v101096() {
        $cached=get_transient($this->seo_sitemap_cache_key_v101096('places'));if(is_array($cached))return $cached;
        global $wpdb;$places=$this->table('places');
        $rows=(array)$wpdb->get_results("SELECT * FROM $places WHERE active=1 AND lifecycle_status='active' AND primary_category IN ('food','highlights','culture','activities') ORDER BY id ASC LIMIT 45000",ARRAY_A);
        $out=array();
        foreach($rows as $row){$cat=$this->seo_public_place_category_v101096($row);if($cat==='')continue;$out[]=array('loc'=>$this->seo_place_url_v101096((int)$row['id'],(string)$row['name'],(string)$row['city']),'lastmod'=>(string)($row['updated_at']??''));}
        set_transient($this->seo_sitemap_cache_key_v101096('places'),$out,6*HOUR_IN_SECONDS);return $out;
    }

    private function seo_event_sitemap_entries_v101096() {
        $cached=get_transient($this->seo_sitemap_cache_key_v101096('events'));if(is_array($cached))return $cached;
        global $wpdb;$events=$this->table('events');$now=current_time('mysql',true);
        $rows=(array)$wpdb->get_results($wpdb->prepare("SELECT id,title,city,updated_at FROM $events WHERE status='active' AND COALESCE(end_at,start_at)>=%s ORDER BY id ASC LIMIT 45000",$now),ARRAY_A);
        $out=array();foreach($rows as $row)$out[]=array('loc'=>$this->seo_event_url_v101096((int)$row['id'],(string)$row['title'],(string)$row['city']),'lastmod'=>(string)($row['updated_at']??''));
        set_transient($this->seo_sitemap_cache_key_v101096('events'),$out,HOUR_IN_SECONDS);return $out;
    }

    private function seo_render_sitemap_urlset_v101096($entries) {
        nocache_headers();status_header(200);header('Content-Type: application/xml; charset=UTF-8');
        echo '<?xml version="1.0" encoding="UTF-8"?>';echo '<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">';
        foreach((array)$entries as $entry){$loc=$this->seo_xml_escape_v101096($entry['loc']??'');if($loc==='')continue;echo '<url><loc>'.$loc.'</loc>';if(!empty($entry['lastmod'])){ $ts=strtotime((string)$entry['lastmod']);if($ts)echo '<lastmod>'.gmdate('c',$ts).'</lastmod>'; }echo '</url>';}
        echo '</urlset>';exit;
    }

    public function maybe_render_rpg_sitemap_v101096() {
        if(is_admin()||(defined('REST_REQUEST')&&REST_REQUEST))return;$path=$this->seo_request_path_v101096();
        if($path==='rpg-sitemap.xml'){
            nocache_headers();status_header(200);header('Content-Type: application/xml; charset=UTF-8');$x=function($v){return $this->seo_xml_escape_v101096($v);};
            echo '<?xml version="1.0" encoding="UTF-8"?>';echo '<sitemapindex xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">';
            echo '<sitemap><loc>'.$x(home_url('/rpg-sitemap-places.xml')).'</loc></sitemap>';
            echo '<sitemap><loc>'.$x(home_url('/rpg-sitemap-events.xml')).'</loc></sitemap>';
            echo '</sitemapindex>';exit;
        }
        if($path==='rpg-sitemap-places.xml')$this->seo_render_sitemap_urlset_v101096($this->seo_place_sitemap_entries_v101096());
        if($path==='rpg-sitemap-events.xml')$this->seo_render_sitemap_urlset_v101096($this->seo_event_sitemap_entries_v101096());
    }

    private function seo_render_not_found_v101096() {
        nocache_headers();status_header(404);header('X-Robots-Tag: noindex, follow',true);header('Content-Type: text/html; charset='.get_bloginfo('charset'));
        echo '<!doctype html><html lang="de"><head><meta charset="'.esc_attr(get_bloginfo('charset')).'"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,follow"><title>Nicht gefunden | RuhrpottGuru</title></head><body><main><h1>Nicht gefunden</h1><p>Dieser Eintrag ist nicht mehr öffentlich verfügbar.</p></main></body></html>';exit;
