    private function seo_detail_value_v101148($value) {
        $value=trim((string)$value);
        if($value==='')return '';
        $flat=strtolower(preg_replace('/\\s+/u','',$value));
        if(in_array($flat,array('-','--','---','n/a','na','n.v.','nv','null','unknown','unbekannt'),true))return '';
        return $value;
    }

    // P0 read-only canonical Event HTML preview. No routing, SEO-head,
    // JSON-LD, event lifecycle, API or category changes. Render the public
