    private function seo_direct_initial_html_p0($data) {
        $is_event = (string)($data['direct_category'] ?? '') === 'events';
        $token = trim((string)($data['direct_token'] ?? ''));
        if (!preg_match('/^[ep][1-9][0-9]*$/', $token)) return '';
        $title = trim((string)($data['title'] ?? ''));
        if ($title === '') return '';
        $city = $this->seo_detail_value_v101148($data['city'] ?? '');
