        $hours = $this->seo_detail_value_v101148($data['hours'] ?? '');
        $label = $this->seo_detail_value_v101148($data['label'] ?? '');
        $start = trim((string)($data['start_iso'] ?? ''));
        $image = esc_url_raw((string)($data['image'] ?? ''));
        $ticket = esc_url_raw((string)($data['ticket_url'] ?? ''));
        $route = esc_url_raw((string)($data['route_url'] ?? ''));
        $website = esc_url_raw((string)($data['website'] ?? ''));
        $program = esc_url_raw((string)($data['program_url'] ?? ''));
        $menu = esc_url_raw((string)($data['menu_url'] ?? ''));
        $reservation = esc_url_raw((string)($data['reservation_url'] ?? ''));
        $organizers = is_array($data['organizers'] ?? null) ? $data['organizers'] : array();
        $participants = is_array($data['participants'] ?? null) ? $data['participants'] : array();
        $overview = esc_url_raw((string)($data['overview_url'] ?? home_url('/veranstaltungen/')));
        $html = '<main><article class="rpgx-ssr-article">';
        if ($image !== '') $html .= '<img class="rpgx-ssr-image" src="'.esc_url($image).'" alt="'.esc_attr($title).'" fetchpriority="high">';
        $html .= '<div class="rpgx-ssr-content"><h1>'.esc_html($title).'</h1>';
        $facts = array();
        if ($when !== '') $facts[] = $start !== '' ? '<time datetime="'.esc_attr($start).'">'.esc_html($when).'</time>' : esc_html($when);
        if (!$is_event && $label !== '') $facts[] = esc_html($label);
        if (!$is_event && $hours !== '') $facts[] = esc_html('Öffnungszeiten: '.$hours);
        if ($city !== '') $facts[] = esc_html($city);
        if ($venue !== '') $facts[] = esc_html($venue);
        if ($address !== '') $facts[] = esc_html($address);
        if ($price !== '') $facts[] = esc_html($price);
        if ($facts) { $html .= '<ul class="rpgx-ssr-facts">'; foreach ($facts as $fact) $html .= '<li>'.$fact.'</li>'; $html .= '</ul>'; }
        if ($description !== '') $html .= '<section aria-labelledby="rpgx-ssr-desc-title"><h2 id="rpgx-ssr-desc-title">'.($is_event ? 'Über die Veranstaltung' : 'Über diesen Ort').'</h2><div class="rpgx-ssr-desc">'.esc_html($description).'</div></section>';
        foreach (($is_event ? array('Veranstalter' => $organizers, 'Mitwirkende' => $participants) : array()) as $heading => $records) {
            $names = array();
            foreach ($records as $entry) {
                $name = is_array($entry) ? trim((string)($entry['name'] ?? ($entry['title'] ?? ''))) : (is_scalar($entry) ? trim((string)$entry) : '');
                if ($name !== '') $names[] = $name;
            }
            if ($names) {
                $html .= '<section class="rpgx-ssr-people"><h2>'.esc_html($heading).'</h2><ul>';
                foreach ($names as $name) $html .= '<li>'.esc_html($name).'</li>';
                $html .= '</ul></section>';
            }
        }
        $html .= '<nav class="rpgx-ssr-actions" aria-label="'.($is_event ? 'Veranstaltungsaktionen' : 'Ortsinformationen').'">';
        if ($ticket !== '' && $is_event) $html .= '<a href="'.esc_url($ticket).'" rel="noopener noreferrer">Tickets</a>';
        if ($website !== '') $html .= '<a href="'.esc_url($website).'" rel="noopener noreferrer">Veranstalterwebsite</a>';
        if ($program !== '' && $is_event) $html .= '<a href="'.esc_url($program).'" rel="noopener noreferrer">Programm</a>';
        if ($menu !== '') $html .= '<a href="'.esc_url($menu).'" rel="noopener noreferrer">Speisekarte</a>';
        if ($reservation !== '') $html .= '<a href="'.esc_url($reservation).'" rel="noopener noreferrer">Reservieren</a>';
        if ($route !== '') $html .= '<a href="'.esc_url($route).'" rel="noopener noreferrer" target="_blank">Route planen</a>';
        $html .= '<a href="'.esc_url($overview).'">'.($is_event ? 'Weitere Veranstaltungen' : 'RuhrpottGuru entdecken').'</a></nav></div></article></main>';

        return $html;
    }

