    /** 1.10.144: Return SEO context only for the 53 city hubs and their five category children. */
    private function city_guide_seo_context_v101144() {
        if(!is_page())return null;
        $post=get_queried_object();if(!($post instanceof WP_Post))return null;
        $root_id=3355;$city=null;$kind='';$kind_label='';
        if((int)$post->post_parent===$root_id){
            $city=$post;$kind='city';$kind_label='Stadt-Guide';
        }else{
            $parent=get_post((int)$post->post_parent);
            if(!($parent instanceof WP_Post)||(int)$parent->post_parent!==$root_id)return null;
            $allowed=array(
                'veranstaltungen'=>'Veranstaltungen',
                'restaurants'=>'Restaurants & Food',
                'sehenswuerdigkeiten'=>'Sehenswürdigkeiten',
                'kultur'=>'Kultur',
                'freizeit'=>'Freizeitaktivitäten',
            );
            $slug=(string)$post->post_name;if(!isset($allowed[$slug]))return null;
            $city=$parent;$kind=$slug;$kind_label=$allowed[$slug];
        }
        $city_name=trim((string)$city->post_title);if($city_name==='')return null;
        $canonical=get_permalink($post);if(!$canonical)return null;
        $desc=trim(wp_strip_all_tags((string)$post->post_excerpt));
        if($desc===''){
            $plain=trim(preg_replace('/\s+/u',' ',wp_strip_all_tags(strip_shortcodes((string)$post->post_content))));
            if($plain!=='')$desc=wp_trim_words($plain,28,'…');
        }
        if($desc===''){
            $desc=$kind==='city'
                ? 'Entdecke '.$city_name.' mit RuhrpottGuru: Veranstaltungen, Food, Sehenswürdigkeiten, Kultur und Freizeitaktivitäten.'
                : $kind_label.' in '.$city_name.' entdecken – aktuelle lokale Tipps und Orte bei RuhrpottGuru.';
        }
        $desc=$this->share_trim_description($desc,$desc);
        $title=$kind==='city'?$city_name.' entdecken':$kind_label.' in '.$city_name;
        return array('post'=>$post,'city'=>$city,'city_name'=>$city_name,'kind'=>$kind,'kind_label'=>$kind_label,'canonical'=>$canonical,'description'=>$desc,'title'=>$title);
    }

    /** Remove the core canonical only on our city-guide surfaces; 1.10.144 prints one deterministic canonical below. */
    public function prepare_city_guide_seo_v101144() {
        if($this->city_guide_seo_context_v101144()!==null)remove_action('wp_head','rel_canonical');
    }

    public function render_city_guide_seo_head_v101144() {
        $ctx=$this->city_guide_seo_context_v101144();if($ctx===null)return;
        $canonical=esc_url_raw((string)$ctx['canonical']);$desc=(string)$ctx['description'];$title=(string)$ctx['title'];$city=(string)$ctx['city_name'];$kind=(string)$ctx['kind'];
        echo "\n".'<meta name="description" content="'.esc_attr($desc).'">';
        echo "\n".'<link rel="canonical" href="'.esc_url($canonical).'">';
        echo "\n".'<meta property="og:locale" content="de_DE"><meta property="og:type" content="website"><meta property="og:site_name" content="RuhrpottGuru">';
        echo '<meta property="og:title" content="'.esc_attr($title).'"><meta property="og:description" content="'.esc_attr($desc).'"><meta property="og:url" content="'.esc_url($canonical).'">';
        echo "\n".'<meta name="twitter:card" content="summary"><meta name="twitter:title" content="'.esc_attr($title).'"><meta name="twitter:description" content="'.esc_attr($desc).'">';
        $root=home_url('/stadt/');$city_url=get_permalink((int)$ctx['city']->ID);
        $crumbs=array(
            array('@type'=>'ListItem','position'=>1,'name'=>'RuhrpottGuru','item'=>home_url('/')),
            array('@type'=>'ListItem','position'=>2,'name'=>'Städte','item'=>$root),
            array('@type'=>'ListItem','position'=>3,'name'=>$city,'item'=>$city_url),
        );
        if($kind!=='city')$crumbs[]=array('@type'=>'ListItem','position'=>4,'name'=>(string)$ctx['kind_label'],'item'=>$canonical);
        $schema=array(
            '@context'=>'https://schema.org',
            '@type'=>'CollectionPage',
            'name'=>$title,
            'url'=>$canonical,
            'description'=>$desc,
            'isPartOf'=>array('@type'=>'WebSite','name'=>'RuhrpottGuru','url'=>home_url('/')),
            'about'=>array('@type'=>'City','name'=>$city),
            'breadcrumb'=>array('@type'=>'BreadcrumbList','itemListElement'=>$crumbs),
        );
        if($kind==='city'){
            $parts=array();
            foreach(array('veranstaltungen'=>'Veranstaltungen','restaurants'=>'Restaurants & Food','sehenswuerdigkeiten'=>'Sehenswürdigkeiten','kultur'=>'Kultur','freizeit'=>'Freizeitaktivitäten') as $slug=>$label){
                $parts[]=array('@type'=>'WebPage','name'=>$label.' in '.$city,'url'=>trailingslashit($city_url).$slug.'/');
            }
            $schema['hasPart']=$parts;
        }
        echo "\n".'<script type="application/ld+json">'.wp_json_encode($schema,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES).'</script>'."\n";
    }

