    private function night_auto_profile($row) {
        $tags=json_decode((string)($row['raw_tags']??''),true);if(!is_array($tags))$tags=array();
        $name=remove_accents(mb_strtolower((string)($row['name']??''),'UTF-8'));
        $blob=$name.' '.remove_accents(mb_strtolower(wp_json_encode($tags,JSON_UNESCAPED_UNICODE),'UTF-8'));
        $cat=(string)($row['primary_category']??'');
        $score=$cat==='highlights'?45.0:($cat==='culture'?32.0:20.0);
        $score+=max(0.0,min(20.0,((float)($row['quality_score']??0.5))*20.0));
        $out=array();
        $has=function($parts)use($blob){foreach($parts as $p)if(strpos($blob,$p)!==false)return true;return false;};
        if($has(array('industrial','industrie','zeche','bergwerk','mine','mineshaft','hochofen','foerder','forder','kokerei','gasometer','landschaftspark','huette','hutte'))){$out[]='industrial';$score+=25;}
        if($has(array('viewpoint','aussicht','halde','panorama','tetraeder','tower','turm','skyline'))){$out[]='view';$score+=24;}
        if($has(array('illumination','beleucht','lichtkunst','lichtinstallation','gasometer','landschaftspark'))){$out[]='light';$score+=18;}
        if($has(array('castle','schloss','architecture','architektur','monument','denkmal','artwork','kunstwerk','bridge','bruecke','brucke'))){$out[]='architecture';$score+=12;}
        if($has(array('hafen','harbour','marina','kanal','canal','water','see'))){$out[]='water';$score+=10;}
        if(!empty($row['wikidata'])||!empty($row['wikipedia'])||$has(array('wikidata','wikipedia'))){$out[]='photo';$score+=4;}
        $out=array_values(array_unique($out));
        $reason='Besonderer Ruhrgebietsort mit Potenzial für Abend- und Nachtansichten.';
        if(in_array('industrial',$out,true))$reason='Industriekulisse mit starkem Reviercharakter – nach Einbruch der Dunkelheit besonders atmosphärisch.';
        elseif(in_array('view',$out,true))$reason='Landmarke oder Aussichtspunkt – interessant für Abendstimmung, Skyline und Nachtansichten.';
        elseif(in_array('light',$out,true))$reason='Beleuchtung und markante Kulisse machen diesen Ort besonders interessant für den Abend.';
        elseif(in_array('water',$out,true))$reason='Wasser, Hafen- oder Kanalkulisse bietet besondere Licht- und Spiegelungsstimmungen.';
        elseif(in_array('architecture',$out,true))$reason='Markante Architektur oder ein Denkmal mit besonderer Wirkung am Abend.';
        return array('score'=>min(100.0,$score),'tags'=>$out,'reason'=>$reason);
    }

    public function rest_night_places(WP_REST_Request $request) {
        global $wpdb;
        $lat=(float)$request->get_param('lat');$lng=(float)$request->get_param('lng');
        $radius=max(1.0,min(50.0,(float)($request->get_param('radiusKm')?:10)));
        $limit=max(6,min(80,(int)($request->get_param('limit')?:40)));
        $mode=sanitize_key((string)($request->get_param('mode')?:'all'));
        if(abs($lat)>90||abs($lng)>180||($lat==0.0&&$lng==0.0))return new WP_REST_Response(array('ok'=>false,'error'=>'location-required'),400);
        $places=$this->table('places');$media=$this->table('place_media');$night=$this->table('place_night_profiles');
        $lat_delta=$radius/110.574;$cos=max(0.15,abs(cos(deg2rad($lat))));$lng_delta=$radius/(111.320*$cos);
        $distance="(6371.0088 * 2 * ASIN(SQRT(POWER(SIN(RADIANS(p.lat - %f)/2),2) + COS(RADIANS(%f)) * COS(RADIANS(p.lat)) * POWER(SIN(RADIANS(p.lng - %f)/2),2))))";
        $distance_sql=$wpdb->prepare($distance,$lat,$lat,$lng);
        $sql=$wpdb->prepare(
            "SELECT p.*,np.status night_status,np.night_score editorial_night_score,np.tags_json editorial_night_tags,np.reason editorial_night_reason,np.access_status editorial_access,
             nm.url night_image,nm.credit night_credit,nm.artist night_artist,
             pm.url place_image,pm.credit place_credit,pm.artist place_artist,
             (SELECT COUNT(*) FROM $media nmc WHERE nmc.place_id=p.id AND nmc.media_type='image' AND nmc.relation_type='night' AND nmc.moderation_status='active') night_photo_count,
             $distance_sql AS distance_km
             FROM $places p
             LEFT JOIN $night np ON np.place_id=p.id
             LEFT JOIN $media nm ON nm.id=(SELECT nm2.id FROM $media nm2 WHERE nm2.place_id=p.id AND nm2.media_type='image' AND nm2.relation_type='night' AND nm2.moderation_status='active' ORDER BY nm2.is_primary DESC,nm2.visual_quality DESC,nm2.id DESC LIMIT 1)
             LEFT JOIN $media pm ON pm.id=(SELECT pm2.id FROM $media pm2 WHERE pm2.place_id=p.id AND pm2.media_type='image' AND pm2.relation_type='place' AND pm2.moderation_status='active' ORDER BY pm2.is_primary DESC,pm2.visual_quality DESC,pm2.id DESC LIMIT 1)
             WHERE p.active=1 AND p.lifecycle_status='active'
               AND p.primary_category IN ('highlights','culture','activities')
               AND p.lat BETWEEN %f AND %f AND p.lng BETWEEN %f AND %f
               AND (np.status IS NULL OR np.status<>'hidden')
             HAVING distance_km<=%f
             ORDER BY p.quality_score DESC,distance_km ASC
             LIMIT 260",
             $lat-$lat_delta,$lat+$lat_delta,$lng-$lng_delta,$lng+$lng_delta,$radius
        );
        $rows=(array)$wpdb->get_results($sql,ARRAY_A);$items=array();
        foreach($rows as $row){
            $raw=json_decode((string)($row['raw_tags']??''),true);if(!is_array($raw))$raw=array();
            $access=strtolower(trim((string)($raw['access']??'')));
            if(in_array($access,array('private','no'),true))continue;
            $auto=$this->night_auto_profile($row);
            $editorial=(float)($row['editorial_night_score']??0);
            $score=max((float)$auto['score'],$editorial);
            $tags=$auto['tags'];$etags=json_decode((string)($row['editorial_night_tags']??''),true);if(is_array($etags))$tags=array_values(array_unique(array_merge($tags,array_map('sanitize_key',$etags))));
            $photo_count=(int)($row['night_photo_count']??0);if($photo_count>0){$score=min(100,$score+12);$tags[]='photo';}
            $tags=array_values(array_unique($tags));
            if((string)($row['night_status']??'')!=='active' && $score<58)continue;
            if($mode!=='all'){
                $map=array('light'=>'light','view'=>'view','industrial'=>'industrial','photo'=>'photo','water'=>'water','architecture'=>'architecture');
                if(isset($map[$mode])&&!in_array($map[$mode],$tags,true))continue;
            }
            $reason=trim((string)($row['editorial_night_reason']??''));if($reason==='')$reason=$auto['reason'];
            $night_image=(string)($row['night_image']??'');$place_image=(string)($row['place_image']??'');
            $rank=$score-min(45,(float)$row['distance_km'])*0.85;
            $items[]=array(
                'id'=>(int)$row['id'],'name'=>(string)$row['name'],'city'=>(string)$row['city'],
                'category'=>(string)$row['primary_category'],'subcategory'=>(string)$row['primary_subcategory'],
                'lat'=>(float)$row['lat'],'lng'=>(float)$row['lng'],'distanceKm'=>round((float)$row['distance_km'],2),
                'nightScore'=>round($score,1),'nightTags'=>$tags,'nightReason'=>$reason,
                'accessStatus'=>(string)($row['editorial_access']?:'unknown'),
                'nightPhotoCount'=>$photo_count,'imageUrl'=>$night_image!==''?$night_image:$place_image,
                'imageKind'=>$night_image!==''?'night':'day','imageCredit'=>$night_image!==''?(string)($row['night_credit']??''):(string)($row['place_credit']??''),
                'address'=>trim((string)$row['street'].' '.(string)$row['house_number'].', '.(string)$row['postcode'].' '.(string)$row['city'],", "),
                'openingHours'=>(string)$row['opening_hours'],'website'=>(string)$row['website'],'_rank'=>$rank
            );
        }
        usort($items,function($a,$b){if(abs($a['_rank']-$b['_rank'])>0.001)return $a['_rank']>$b['_rank']?-1:1;return $a['distanceKm']<=>$b['distanceKm'];});
        $items=array_slice($items,0,$limit);foreach($items as &$i)unset($i['_rank']);unset($i);
        return rest_ensure_response(array('ok'=>true,'source'=>'places-db-night-v1','requestedRadiusKm'=>$radius,'count'=>count($items),'elements'=>$items));
    }

    public function rest_night_photos(WP_REST_Request $request) {
        global $wpdb;
        $place_id=absint($request['id']);
        if(!$place_id)return new WP_REST_Response(array('ok'=>false,'error'=>'invalid-place'),400);
        $places=$this->table('places');$media=$this->table('place_media');$night=$this->table('place_night_profiles');
        $place=$wpdb->get_row($wpdb->prepare(
            "SELECT p.id,p.name,p.city,p.street,p.house_number,p.postcode,p.website,p.opening_hours,p.lat,p.lng,np.night_score,np.tags_json,np.reason,np.access_status
             FROM $places p LEFT JOIN $night np ON np.place_id=p.id
             WHERE p.id=%d AND p.active=1 AND p.lifecycle_status='active'",$place_id),ARRAY_A);
        if(!$place)return new WP_REST_Response(array('ok'=>false,'error'=>'place-not-found'),404);
        $rows=(array)$wpdb->get_results($wpdb->prepare(
            "SELECT id,url,source,source_url,license,artist,credit,is_primary,visual_quality,verified_at
             FROM $media
             WHERE place_id=%d AND media_type='image' AND relation_type='night' AND moderation_status='active'
             ORDER BY is_primary DESC,visual_quality DESC,verified_at DESC,id DESC",$place_id),ARRAY_A);
        $photos=array();
        foreach($rows as $m){
            $photos[]=array('id'=>(int)$m['id'],'url'=>(string)$m['url'],'credit'=>(string)$m['credit'],'artist'=>(string)$m['artist'],'source'=>(string)$m['source'],'sourceUrl'=>(string)$m['source_url'],'license'=>(string)$m['license'],'isPrimary'=>(bool)$m['is_primary']);
        }
        $tags=json_decode((string)($place['tags_json']??'[]'),true);if(!is_array($tags))$tags=array();
        return rest_ensure_response(array('ok'=>true,'place'=>array(
            'id'=>(int)$place['id'],'name'=>(string)$place['name'],'city'=>(string)$place['city'],
            'address'=>trim((string)$place['street'].' '.(string)$place['house_number'].', '.(string)$place['postcode'].' '.(string)$place['city'],", "),
            'website'=>(string)$place['website'],'openingHours'=>(string)$place['opening_hours'],'lat'=>(float)$place['lat'],'lng'=>(float)$place['lng'],
            'nightScore'=>(float)($place['night_score']??0),'nightTags'=>$tags,'nightReason'=>(string)($place['reason']??''),'accessStatus'=>(string)($place['access_status']??'unknown')
        ),'count'=>count($photos),'photos'=>$photos));
    }

    public function rest_night_submit(WP_REST_Request $request) {
        $request->set_param('category','night');
        $request->set_param('submitter_type','community');
        if(!$request->get_param('fields_json'))$request->set_param('fields_json','{}');
        return $this->rest_place_contribute($request);
    }

    public function can_manage() {
        return current_user_can('manage_options');
    }

    /**
     * V1.10.17 visitor-facing event identity.
     * This is intentionally stricter than a generic fuzzy title merge: city and
     * venue/position are part of the key. V1.10.29 uses this key first to
     * choose one owner source for obvious duplicates and then to collapse daily
     * occurrences that belong to one short multi-day run (festival/fair/etc.).
     * Weekly/monthly recurrences stay separate.
     */
    private function event_listing_norm($value) {
        $v=remove_accents(mb_strtolower(wp_strip_all_tags((string)$value),'UTF-8'));
        $v=preg_replace('/[^a-z0-9]+/u',' ',(string)$v);
        return trim(preg_replace('/\s+/u',' ',(string)$v));
    }

    private function event_listing_identity_key($row) {
        if(!is_array($row)) return '';
        $title=$this->event_listing_norm($row['title']??'');
        $city=$this->event_listing_norm($row['city']??'');
        $venue=$this->event_listing_norm($row['venue_name']??($row['subtitle']??''));
        if($title===''||$city==='') return '';
        if($venue===''){
            $lat=isset($row['lat'])&&is_numeric($row['lat'])?number_format((float)$row['lat'],3,'.',''):'';
            $lng=isset($row['lng'])&&is_numeric($row['lng'])?number_format((float)$row['lng'],3,'.',''):'';
            $venue=$lat!==''&&$lng!==''?'geo:'.$lat.','.$lng:'city';
        }
        return sha1($title.'|'.$city.'|'.$venue);
    }

    /**
     * V1.10.18 narrowly scoped visitor-facing schedule/program overrides.
     * These values come from the verified official event website and are kept
     * separate from the imported source occurrence so provenance remains intact.
     */
    private function event_curated_visitor_data($row) {
        // 1.10.42: no hard-coded per-event visitor overrides.
        return array();
    }

    /**
     * Serialize a visitor-facing local event time with the event's explicit
     * timezone when one is known. This must not depend on the WordPress site
     * timezone: on installations configured as UTC, mysql2date() would emit
     * 10:00+00:00 and a German browser correctly turns that into 12:00 CEST.
     */
    private function event_visitor_datetime_iso($value, $row=array()) {
        $value=trim((string)$value);
        if($value==='') return '';
        $timezone=trim((string)($row['_rpg_visitor_timezone']??''));
        if($timezone!==''){
            try{
                $tz=new DateTimeZone($timezone);
                $dt=DateTimeImmutable::createFromFormat('Y-m-d H:i:s',$value,$tz);
                if($dt instanceof DateTimeImmutable) return $dt->format(DateTimeInterface::ATOM);
            }catch(Exception $e){}
        }
        return (string)mysql2date('c',$value,false);
    }

    private function event_apply_curated_visitor_data_to_row($row) {
        $data=$this->event_curated_visitor_data($row);
        if(!$data) return $row;
        $row['start_at']=$data['start_at'];
        $row['end_at']=$data['end_at'];
        $row['_rpg_program_url']=$data['program_url'];
        $row['_rpg_program_label']=$data['program_label'];
        $row['_rpg_visitor_hours']=$data['visitor_hours'];
        $row['_rpg_day_hours']=$data['day_hours'];
        $row['_rpg_visitor_hours_source']=$data['official_source'];
        $row['_rpg_visitor_timezone']=$data['timezone']??'';
        return $row;
    }

    /**
     * V1.10.29 source ownership: one real visitor event has exactly one owner.
     * Priority is intentionally simple and deterministic:
     *   1) current licensed Ruhr-Tourismus ET4 master
     *   2) supplemental public ET4/destination.one pool
     *   3) legacy ET4 rows
     *   4) Essen EMG export
     *   5) other explicit supplemental sources
     * Lower-priority duplicates remain in the database for provenance/audit, but
     * they never donate text, dates or media to a higher-priority event.
     */
    private function event_public_source_rank($row) {
        if(!is_array($row)) return 99;
        $src=strtolower(trim((string)($row['source']??'')));
        $rowMaster=sanitize_key((string)($row['last_master_run']??''));
        // Any row carrying a real master-run token is master-owned. This remains
        // stable even while the next nightly master wave is still in progress.
        if($rowMaster!=='' && in_array($src,array('open_data_finder','et4'),true)) return 0;
        if($src==='destination_one_open_data') return 10;
        if(in_array($src,array('open_data_finder','et4'),true)) return 20;
        if($src==='essen_emg_export') return 30;
        if($src==='stadt_selm_calendar') return 35;
        if($src==='wesel_marketing_calendar') return 35;
        if($src==='verified-official-wesel') return 40;
        if($src==='rpg_seasonal_editorial') return 80;
        return 90;
    }

    private function event_listing_cluster_rows($rows) {
        $rows=$this->event_exact_external_collapse_v1063($rows);
        $groups=array();$loose=array();
        foreach((array)$rows as $row){
            if(!is_array($row))continue;
            $key=$this->event_listing_identity_key($row);
            if($key===''){
                $row['_rpg_cluster_ids']=!empty($row['_rpg_cluster_ids'])?(array)$row['_rpg_cluster_ids']:array((int)($row['id']??0));
                $row['_rpg_cluster_count']=!empty($row['_rpg_cluster_count'])?(int)$row['_rpg_cluster_count']:1;
                $row['_rpg_source_rank']=$this->event_public_source_rank($row);
                $loose[]=$row;continue;
            }
            if(!isset($groups[$key]))$groups[$key]=array();
            $groups[$key][]=$row;
        }
        $out=$loose;
        foreach($groups as $identity=>$members){
            usort($members,function($a,$b){return strtotime((string)($a['start_at']??''))<=>strtotime((string)($b['start_at']??''));});
            $clusters=array();$current=array();$previousTs=null;
            foreach($members as $row){
                $ts=strtotime((string)($row['start_at']??''));
                if(!$current){$current=array($row);$previousTs=$ts;continue;}
                $delta=($ts&&$previousTs)?abs($ts-$previousTs):PHP_INT_MAX;
                $sameOccurrence=$delta<=2*HOUR_IN_SECONDS;
                $dailyNeighbour=$delta>=18*HOUR_IN_SECONDS&&$delta<=30*HOUR_IN_SECONDS;
                $clusterStart=strtotime((string)($current[0]['start_at']??''));
                $shortRun=$clusterStart&&$ts&&($ts-$clusterStart)<=10*DAY_IN_SECONDS;
                if($sameOccurrence||($dailyNeighbour&&$shortRun)){$current[]=$row;$previousTs=$ts;continue;}
                $clusters[]=$current;$current=array($row);$previousTs=$ts;
            }
            if($current)$clusters[]=$current;

            foreach($clusters as $cluster){
                // Select ONE owner source before any field/media handling.
                $bestRank=99;
                foreach($cluster as $m)$bestRank=min($bestRank,$this->event_public_source_rank($m));
                $owned=array_values(array_filter($cluster,function($m)use($bestRank){return $this->event_public_source_rank($m)===$bestRank;}));
                if(!$owned)continue;
                usort($owned,function($a,$b){return strtotime((string)($a['start_at']??''))<=>strtotime((string)($b['start_at']??''));});

                $rep=$owned[0];$ids=array();$firstTs=null;$lastTs=null;
                foreach($owned as $m){
                    $memberIds=!empty($m['_rpg_cluster_ids'])?(array)$m['_rpg_cluster_ids']:array((int)($m['id']??0));foreach($memberIds as $id){$id=(int)$id;if($id)$ids[]=$id;}
                    $st=strtotime((string)($m['_rpg_series_first_at']??($m['start_at']??'')));$en=strtotime((string)($m['_rpg_series_last_at']??($m['end_at']??'')));
                    if($st&&($firstTs===null||$st<$firstTs))$firstTs=$st;
                    $effective=$en&&$en>$st?$en:$st;if($effective&&($lastTs===null||$effective>$lastTs))$lastTs=$effective;
                    $repScore=(trim((string)($rep['description']??''))!==''?4:0)+(trim((string)($rep['ticket_url']??''))!==''?2:0)+(trim((string)($rep['price_text']??''))!==''?1:0);
                    $mScore=(trim((string)($m['description']??''))!==''?4:0)+(trim((string)($m['ticket_url']??''))!==''?2:0)+(trim((string)($m['price_text']??''))!==''?1:0);
                    if($mScore>$repScore)$rep=$m;
                }
                // Series timing/count now comes ONLY from the owner source. A
                // lower-priority feed can neither add a date nor alter the card.
                if($firstTs)$rep['start_at']=date('Y-m-d H:i:s',$firstTs);
                $rep['_rpg_cluster_ids']=array_values(array_unique($ids));
                $rep['_rpg_cluster_count']=count(array_values(array_unique($ids)));
                $rep['_rpg_series_first_at']=$firstTs?date('Y-m-d H:i:s',$firstTs):'';
                $rep['_rpg_series_last_at']=$lastTs?date('Y-m-d H:i:s',$lastTs):'';
                $rep['_rpg_series_identity']=$identity;
                $rep['_rpg_source_rank']=$bestRank;

                // Same-source series may reuse an already joined image from one
                // of their own occurrences. Cross-source image inheritance is forbidden.
                if(empty($rep['image_url']))foreach($owned as $m){if(!empty($m['image_url'])){$rep['image_url']=$m['image_url'];$rep['image_credit']=$m['image_credit']??'';$rep['image_license']=$m['image_license']??'';break;}}
                $out[]=$rep;
            }
        }
        usort($out,function($a,$b){$ta=strtotime((string)($a['start_at']??''));$tb=strtotime((string)($b['start_at']??''));if($ta===$tb)return ((float)($a['distance_km']??0)<=> (float)($b['distance_km']??0));return $ta<=>$tb;});
        return $out;
    }

    /**
     * 1.10.157: apply the same visitor-facing place intelligence used by category
     * feeds / direct details before a place is serialized into global search.
     * This intentionally changes response presentation only; canonical DB fields stay untouched.
     */
    private function global_search_place_projection_v101157($row, $category) {
        $row = is_array($row) ? $row : array();
        $category = $this->share_category_from_value($category);
        if ($category === '') $category = $this->share_category_from_value((string)($row['primary_category'] ?? ''));
        if (!in_array($category,array('food','highlights','culture','activities','buedchen'),true)) return $row;
        $row['subcategory'] = (string)($row['primary_subcategory'] ?? ($row['subcategory'] ?? ''));
