    /**
     * Search cards need a browser-loadable image URL. rows_to_elements() deliberately
     * preserves raw OSM/Commons provenance, so normalize only the final display URL here.
     */
    private function global_search_place_image_url_v101157($tags) {
        $tags=is_array($tags)?$tags:array();
        foreach(array('image:url','image','wikimedia_commons') as $key){
            $value=trim((string)($tags[$key]??''));
            if($value==='')continue;
            if(preg_match('/^File\s*:\s*(.+)$/i',$value,$m))return 'https://commons.wikimedia.org/wiki/Special:FilePath/'.rawurlencode(trim($m[1])).'?width=1200';
            if(preg_match('#^https?://commons\.wikimedia\.org/wiki/File:(.+)$#i',$value,$m)){
                $file=rawurldecode(preg_replace('/[?#].*$/','',$m[1]));$file=str_replace('_',' ',$file);
                if($file!=='')return 'https://commons.wikimedia.org/wiki/Special:FilePath/'.rawurlencode($file).'?width=1200';
            }
            if(!preg_match('#^https?://#i',$value))continue;
            if(preg_match('#commons\.wikimedia\.org/wiki/(?:Category:|Special:MediaSearch|Main_Page)#i',$value))continue;
            if(preg_match('#upload\.wikimedia\.org/|Special:FilePath/|\.(?:jpe?g|png|webp|gif|avif)(?:[?#].*)?$#i',$value))return esc_url_raw($value);
            // `image` / `image:url` may legitimately be another direct HTTPS image URL.
            if($key!=='wikimedia_commons' && !preg_match('#/(?:Category|File):#i',$value))return esc_url_raw($value);
        }
        return '';
    }

    private function global_search_place_crop_v101157($tags,$key) {
        $value=is_array($tags)&&array_key_exists($key,$tags)?$tags[$key]:null;
