    public function rest_status() {
        return rest_ensure_response($this->status_payload());
    }

    private function status_payload() {
        global $wpdb;
        $places = $this->table('places');
        $muni = $this->table('places_municipalities');
        $cats = $this->table('place_categories');
        $total = (int) $wpdb->get_var("SELECT COUNT(*) FROM $places WHERE active=1");
        $completed = (int) $wpdb->get_var("SELECT COUNT(*) FROM $muni WHERE status='complete'");
        $counts = array('food'=>0,'highlights'=>0,'culture'=>0,'activities'=>0);
        $rows = $wpdb->get_results("SELECT category,COUNT(*) c FROM $cats c INNER JOIN $places p ON p.id=c.place_id WHERE p.active=1 GROUP BY category", ARRAY_A);
        foreach ((array) $rows as $row) {
            if (isset($counts[$row['category']])) {
                $counts[$row['category']] = (int) $row['c'];
            }
        }
        return array(
            'ok' => true,
            'version' => self::VERSION,
            'schemaVersion' => self::SCHEMA_VERSION,
            'status' => (string) get_option(self::OPTION_STATUS, 'bootstrap_pending'),
            'mode' => $this->runtime_mode(),
            'catalogVersion' => (string) get_option(self::OPTION_CATALOG_VERSION, 'bootstrap'),
            'municipalitiesComplete' => $completed,
            'municipalitiesTotal' => 53,
            'activePlaces' => $total,
            'categoryCounts' => $counts,
            'rollback' => 'Installiere den archivierten v70-Theme-Build; ohne den v71-Settings-Filter bleibt der Places-Pluginbestand ungenutzt und der alte OSM-Laufzeitpfad ist wieder aktiv.',
        );
    }

    private function sanitize_category($category) {
        $category = strtolower(trim((string) $category));
        return in_array($category, array('food','highlights','culture','activities'), true) ? $category : '';
    }

    public function rest_home(WP_REST_Request $request) {
        if ($this->runtime_mode() !== 'database') {
            return new WP_REST_Response(array('ok'=>false,'error'=>'places-db-not-ready','mode'=>'osm'), 503);
        }
        $data = $request->get_json_params();
        $lat = isset($data['lat']) ? (float) $data['lat'] : 0.0;
        $lng = isset($data['lng']) ? (float) $data['lng'] : 0.0;
        $radius = isset($data['radiusKm']) ? (float) $data['radiusKm'] : 5.0;
        $category = $this->sanitize_category(isset($data['category']) ? $data['category'] : '');
        $limit = isset($data['limit']) ? max(1, min(1500, (int) $data['limit'])) : 20;
        if (!$category || !$this->valid_coordinate($lat, $lng)) {
            return new WP_REST_Response(array('ok'=>false,'error'=>'invalid-request'), 400);
        }
        $radius = max(0.5, min(50.0, $radius));
        if ($category === 'activities') {
            $rows = $this->nearby_activity_experience_rows($lat, $lng, $radius, $limit);
        } elseif ($category === 'highlights') {
            $rows = $this->nearby_highlight_experience_rows($lat, $lng, $radius, $limit);
        } else {
            $rows = $this->nearby_rows($category, $lat, $lng, $radius, $limit, 'all');
        }
        return rest_ensure_response(array(
            'ok' => true,
            'source' => 'places-db',
            'category' => $category,
            'requestedRadiusKm' => $radius,
            'effectiveRadiusKm' => $radius,
            'elements' => $this->rows_to_elements($rows),
            'catalogVersion' => (string) get_option(self::OPTION_CATALOG_VERSION, 'bootstrap'),
        ));
    }

    public function rest_overpass_adapter(WP_REST_Request $request) {
        if ($this->runtime_mode() !== 'database') {
            return new WP_REST_Response(array('ok'=>false,'errorType'=>'db-not-ready','message'=>'Places DB not ready'), 503);
        }
        $data = $request->get_json_params();
        $query = isset($data['query']) ? (string) $data['query'] : '';
        if (!$query) {
            // Support form-encoded diagnostic callers as a defensive compatibility path.
            $query = (string) $request->get_param('data');
        }
        $ctx = $this->parse_overpass_query_context($query);
        if (!$ctx) {
            return new WP_REST_Response(array('ok'=>false,'errorType'=>'invalid-query','message'=>'Could not parse legacy OSM query'), 400);
        }
        if ($ctx['category'] === 'mixed') {
            $rows = $this->nearby_rows_multi($ctx['lat'], $ctx['lng'], $ctx['radius_km'], $ctx['limit']);
        } elseif ($ctx['category'] === 'highlights' && $ctx['kind'] === 'all') {
            $rows = $this->nearby_highlight_experience_rows($ctx['lat'], $ctx['lng'], $ctx['radius_km'], $ctx['limit']);
        } elseif ($ctx['category'] === 'activities' && $ctx['kind'] === 'all') {
            $rows = $this->nearby_activity_experience_rows($ctx['lat'], $ctx['lng'], $ctx['radius_km'], $ctx['limit']);
        } else {
            $rows = $this->nearby_rows($ctx['category'], $ctx['lat'], $ctx['lng'], $ctx['radius_km'], $ctx['limit'], $ctx['kind']);
        }
        $elements = $this->rows_to_elements($rows);
        return rest_ensure_response(array(
            'ok' => true,
            'data' => array('version'=>0.6,'generator'=>'RuhrpottGuru Places DB ' . self::VERSION,'elements'=>$elements),
            'mirror' => 'places-db',
            'cached' => true,
            'emptyConfirmed' => true,
            'source' => 'places-db',
        ));
    }

    private function valid_coordinate($lat, $lng) {
        return is_finite($lat) && is_finite($lng) && abs($lat) <= 90 && abs($lng) <= 180 && abs($lat) > 0.1;
    }

    private function parse_overpass_query_context($query) {
        if (!is_string($query) || $query === '') {
            return null;
        }
        if (!preg_match('/around:\s*([0-9.]+)\s*,\s*(-?[0-9.]+)\s*,\s*(-?[0-9.]+)/i', $query, $m)) {
            return null;
        }
        $radius_km = max(0.5, min(80.0, ((float) $m[1]) / 1000.0));
        $lat = (float) $m[2];
        $lng = (float) $m[3];
        if (!$this->valid_coordinate($lat, $lng)) {
            return null;
        }

        $q = strtolower($query);
        $category = 'highlights';
        $kind = 'all';

        // First recognize the focused quick-question queries. They intentionally map to
        // one DB subcategory. Broad category queries must stay kind=all; otherwise a
        // request for e.g. "Kultur" would accidentally return museums only.
        if (strpos($q, 'amenity"="fast_food') !== false || strpos($q, 'amenity"="food_court') !== false || strpos($q, 'takeaway"="only') !== false || strpos($q, 'cuisine"~"currywurst|sausage|burger|kebab') !== false) {
            $category = 'food';
            $kind = 'food-fast';
        } elseif (strpos($q, 'amenity"~"cafe|ice_cream') !== false || strpos($q, 'shop"~"coffee|tea') !== false || strpos($q, 'craft"="roastery') !== false) {
            $category = 'food';
            $kind = 'food-cafe';
        } elseif (strpos($q, 'amenity"~"biergarten|pub|restaurant') !== false || strpos($q, 'craft"="brewery') !== false || strpos($q, 'microbrewery"="yes') !== false) {
            $category = 'food';
            $kind = 'food-beer';
        } elseif (strpos($q, 'historic"~"mine|industrial"') !== false || strpos($q, 'man_made"="headframe') !== false) {
            $category = 'highlights';
            $kind = 'highlights-industrial';
        } elseif (strpos($q, 'historic"~"castle|manor|ruins"') !== false || strpos($q, 'building"="castle') !== false) {
            $category = 'highlights';
            $kind = 'highlights-castle';
        } elseif (strpos($q, 'man_made"~"spoil_heap|tower|headframe') !== false || strpos($q, 'tourism"="viewpoint') !== false) {
            $category = 'highlights';
            $kind = 'highlights-landmark';
        } elseif (strpos($q, 'leisure"~"swimming_pool|water_park"') !== false || strpos($q, 'amenity"~"public_bath|swimming_pool|sauna') !== false) {
            $category = 'activities';
            $kind = 'activities-water';
        } elseif (strpos($q, 'sport"~"climbing|bouldering"') !== false) {
            $category = 'activities';
            $kind = 'activities-climbing';
        } elseif (strpos($q, 'sport"~"swimming|canoeing|kayak|sailing|rowing|wakeboarding|water_ski|scuba_diving') !== false
            || strpos($q, 'leisure"~"water_park|marina|slipway') !== false) {
            // The current Activities quick filter "Wasser / See" is broader than
            // pools/thermes. Keep it as an exact raw-tag DB filter so it cannot
            // accidentally fall through to Highlights.
            $category = 'activities';
            $kind = 'activities-water-outdoor';
        } elseif (strpos($q, 'tourism"~"zoo|theme_park|attraction') !== false || strpos($q, 'leisure"~"park|nature_reserve|animal_park') !== false) {
            $category = 'highlights';
            $kind = 'all';
        } else {
            // Broad category signatures emitted by the current compiled theme.
            $broad_food = strpos($q, 'amenity"~"fast_food|restaurant|cafe|pub|bar|biergarten|food_court|ice_cream') !== false
                || strpos($q, 'craft"~"brewery|roastery') !== false;
            $broad_activities = strpos($q, 'leisure"~"sports_centre|sports_hall|swimming_pool|water_park|bowling_alley|park|playground|pitch|fitness_station|fitness_centre|ice_rink|track|miniature_golf|disc_golf_course|stadium|marina|slipway|escape_game|trampoline_park|amusement_park|animal_park') !== false;
            $broad_highlights = strpos($q, 'historic"~"mine|industrial|castle|manor|ruins|archaeological_site|city_gate|fort|fortification|monument') !== false
                || strpos($q, 'heritage"]') !== false;
            $broad_culture = strpos($q, 'amenity"~"theatre|cinema|arts_centre|community_centre|planetarium|library|events_venue|cultural_center|nightclub|concert_hall|music_venue') !== false;

            if ($broad_food) {
                $category = 'food';
            } elseif ($broad_activities) {
                $category = 'activities';
            } elseif ($broad_highlights) {
                $category = 'highlights';
            } elseif ($broad_culture) {
                $category = 'culture';
            } else {
                // The generic discovery query contains several category families at once.
                // Return one distance-sorted mixed DB pool and let the existing frontend
                // classifier / rg:category tags split it exactly as before.
                $signals = 0;
                if (strpos($q, 'fast_food|restaurant|cafe|pub|bar|biergarten') !== false) $signals++;
                if (strpos($q, 'theatre|cinema|arts_centre') !== false || strpos($q, 'museum|viewpoint|artwork') !== false) $signals++;
                if (strpos($q, 'mine|castle|manor|monument|industrial') !== false || strpos($q, 'headframe|spoil_heap') !== false) $signals++;
                if (strpos($q, 'sports_centre|swimming_pool|water_park|bowling_alley|park|fitness_centre') !== false) $signals++;
                if ($signals >= 2) {
                    $category = 'mixed';
                } elseif (strpos($q, 'theatre|cinema|arts_centre|community_centre') !== false || strpos($q, 'tourism"~"museum|gallery|artwork') !== false) {
                    $category = 'culture';
                } elseif (strpos($q, 'swimming_pool|water_park') !== false || strpos($q, 'climbing|bouldering') !== false || strpos($q, 'bowling_alley') !== false || strpos($q, 'tourism"~"zoo|theme_park') !== false || strpos($q, 'escape_game') !== false) {
                    $category = 'activities';
                } elseif (strpos($q, 'fast_food|restaurant|cafe|pub|bar|biergarten') !== false) {
                    $category = 'food';
                } else {
                    $category = 'highlights';
                }
            }
        }

        $limit = 1500;
        if (preg_match('/out\s+center\s+([0-9]+)/i', $query, $lm)) {
            $limit = max(1, min(1500, (int) $lm[1]));
        }
        return compact('category','kind','lat','lng','radius_km','limit');
    }

    private function nearby_rows_multi($lat, $lng, $radius_km, $limit) {
        global $wpdb;
        $places = $this->table('places');
        $categories = $this->table('place_categories');
        $limit = max(1, min(1500, (int) $limit));
        $radius_km = max(0.5, min(80.0, (float) $radius_km));
        $lat_delta = $radius_km / 110.574;
        $cos = max(0.2, cos(deg2rad($lat)));
        $lng_delta = $radius_km / (111.320 * $cos);
        $min_lat = $lat - $lat_delta;
        $max_lat = $lat + $lat_delta;
        $min_lng = $lng - $lng_delta;
        $max_lng = $lng + $lng_delta;
        $distance = "(6371.0088 * 2 * ASIN(SQRT(POWER(SIN(RADIANS(p.lat - %f)/2),2) + COS(RADIANS(%f)) * COS(RADIANS(p.lat)) * POWER(SIN(RADIANS(p.lng - %f)/2),2))))";
        $distance_sql = $wpdb->prepare($distance, $lat, $lat, $lng);
        $mixed_activity_blacklist_sql = " AND NOT (p.primary_category='activities' AND (" . $this->activity_known_closed_expression('p') . ") ) ";
        $mixed_activity_blacklist_sql .= " AND NOT (p.primary_category='activities' AND (LOCATE('\"access\":\"private\"',p.raw_tags)>0 OR LOCATE('\"access\":\"no\"',p.raw_tags)>0 OR LOCATE('\"access\":\"members\"',p.raw_tags)>0)) ";
        $sql = $wpdb->prepare(
            "SELECT p.*, c.subcategory, c.weight, $distance_sql AS distance_km
             FROM $places p
             INNER JOIN $categories c ON c.place_id=p.id AND c.category IN ('food','highlights','culture','activities')
             WHERE p.active=1
               AND p.lifecycle_status='active'
               AND p.lat BETWEEN %f AND %f
               AND p.lng BETWEEN %f AND %f
               $mixed_activity_blacklist_sql
             HAVING distance_km <= %f
             ORDER BY distance_km ASC, p.quality_score DESC, p.id ASC
             LIMIT %d",
            $min_lat, $max_lat, $min_lng, $max_lng, $radius_km, $limit
        );
        $rows=(array)$wpdb->get_results($sql,ARRAY_A);
        $clean=array();
        foreach($rows as $row){
            $cat=(string)($row['primary_category']??'');
            if($cat==='culture'){
                $profile=$this->culture_experience_profile($row); if(!$profile)continue;
                $row['_rg_culture_score']=$profile['score'];$row['_rg_culture_rank_score']=$profile['rank_score'];
                $row['_rg_culture_bucket']=$profile['bucket'];$row['_rg_culture_tags']=$profile['labels'];
                $row['_rg_response_category']='culture';$row['_rg_response_subcategory']=$profile['subcategory'];
            }elseif($cat==='activities'){
                $profile=$this->activity_v2_public_projection($row); if(!$profile)continue;
                $row['_rg_activity_score']=$profile['score'];$row['_rg_activity_rank_score']=$profile['rank_score'];
                $row['_rg_activity_bucket']=$profile['bucket'];$row['_rg_experience_tags']=$profile['labels'];$row['_rg_response_subcategory']=$profile['subcategory'];
                $row['_rg_activity_v2_admission']='rein';$row['_rg_activity_v2_primary']=$profile['primary_experience'];$row['_rg_activity_environment']=$profile['environment'];$row['_rg_activity_multi_count']=$profile['multi_experience_count'];
            }elseif($cat==='highlights'){
                $profile=$this->highlight_experience_profile($row); if(!$profile)continue;
                $row['_rg_highlight_score']=$profile['score'];$row['_rg_highlight_rank_score']=$profile['rank_score'];
                $row['_rg_highlight_tier']=$profile['tier'];$row['_rg_highlight_bucket']=$profile['bucket'];$row['_rg_highlight_tags']=$profile['labels'];
                $row['_rg_response_category']='highlights';$row['_rg_response_subcategory']=$profile['subcategory'];
                if(!empty($profile['route'])){$row['_rg_industrial_route_slug']=$profile['route']['slug'];$row['_rg_industrial_route_type']=$profile['route']['type'];$row['_rg_industrial_route_title']=$profile['route']['title'];}
            }
            $clean[]=$row;
            if(count($clean)>=$limit)break;
        }
        return $clean;
    }

    /**
     * V1.2.3 SQL-level hard blacklist for Activities.
     *
     * These exact OSM tags are excluded before PHP ranking so they can never
     * consume a result slot or a candidate-pool slot. The clause deliberately
     * uses LOCATE on the persisted raw JSON for compatibility with older
     * MySQL/MariaDB versions on shared hosting.
     */
    private function activity_hard_blacklist_expression($alias = 'p') {
        $alias = $alias === 'p' ? 'p' : 'p';
        return "(
            LOCATE('\"leisure\":\"fitness_centre\"', {$alias}.raw_tags) > 0 OR
            LOCATE('\"sport\":\"yoga\"', {$alias}.raw_tags) > 0 OR
            LOCATE('\"sport\":\"pilates\"', {$alias}.raw_tags) > 0 OR
            LOCATE('\"sport\":\"gymnastics\"', {$alias}.raw_tags) > 0 OR
            LOCATE('\"sport\":\"soccer\"', {$alias}.raw_tags) > 0 OR
            (
                LOCATE('\"leisure\":\"pitch\"', {$alias}.raw_tags) > 0 AND NOT (
                    LOCATE('\"leisure\":\"skate_park\"', {$alias}.raw_tags) > 0 OR
                    LOCATE('\"sport\":\"skateboard\"', {$alias}.raw_tags) > 0 OR
                    LOCATE('\"sport\":\"skateboarding\"', {$alias}.raw_tags) > 0 OR
                    LOCATE('\"sport\":\"bmx\"', {$alias}.raw_tags) > 0
                )
            )
        )";
    }


    private function activity_hard_blacklist_sql($alias = 'p') {
        return ' AND NOT ' . $this->activity_hard_blacklist_expression($alias) . ' ';
    }


    /**
     * V1.2.3: independent sports/leisure evidence. Tourism/historic metadata may
     * coexist with a real activity, but may never qualify a place by itself.
     * This preserves e.g. a climbing park tagged tourism=attraction while keeping
     * zoos, museums and pure industrial heritage out of Activities.
     */
    private function activity_independent_signal_expression($alias = 'p') {
        $alias = $alias === 'p' ? 'p' : 'p';
        return "(
            LOCATE('\"amenity\":\"public_bath\"', {$alias}.raw_tags) > 0 OR
            LOCATE('\"amenity\":\"swimming_pool\"', {$alias}.raw_tags) > 0 OR
            LOCATE('\"amenity\":\"sauna\"', {$alias}.raw_tags) > 0 OR
            LOCATE('\"leisure\":\"swimming_pool\"', {$alias}.raw_tags) > 0 OR
            LOCATE('\"leisure\":\"water_park\"', {$alias}.raw_tags) > 0 OR
            LOCATE('\"leisure\":\"bowling_alley\"', {$alias}.raw_tags) > 0 OR
            LOCATE('\"leisure\":\"skate_park\"', {$alias}.raw_tags) > 0 OR
            LOCATE('\"leisure\":\"ice_rink\"', {$alias}.raw_tags) > 0 OR
            LOCATE('\"leisure\":\"miniature_golf\"', {$alias}.raw_tags) > 0 OR
            LOCATE('\"leisure\":\"disc_golf_course\"', {$alias}.raw_tags) > 0 OR
            LOCATE('\"leisure\":\"marina\"', {$alias}.raw_tags) > 0 OR
            LOCATE('\"leisure\":\"slipway\"', {$alias}.raw_tags) > 0 OR
            LOCATE('\"leisure\":\"escape_game\"', {$alias}.raw_tags) > 0 OR
            LOCATE('\"leisure\":\"trampoline_park\"', {$alias}.raw_tags) > 0 OR
            LOCATE('\"sport\":\"swimming\"', {$alias}.raw_tags) > 0 OR
            LOCATE('\"sport\":\"climbing\"', {$alias}.raw_tags) > 0 OR
            LOCATE('\"sport\":\"bouldering\"', {$alias}.raw_tags) > 0 OR
            LOCATE('\"sport\":\"climbing_adventure\"', {$alias}.raw_tags) > 0 OR
            LOCATE('\"sport\":\"skateboard\"', {$alias}.raw_tags) > 0 OR
            LOCATE('\"sport\":\"skateboarding\"', {$alias}.raw_tags) > 0 OR
            LOCATE('\"sport\":\"bmx\"', {$alias}.raw_tags) > 0 OR
            LOCATE('\"sport\":\"karting\"', {$alias}.raw_tags) > 0 OR
            LOCATE('\"sport\":\"wakeboarding\"', {$alias}.raw_tags) > 0 OR
            LOCATE('\"sport\":\"water_ski\"', {$alias}.raw_tags) > 0 OR
            LOCATE('\"sport\":\"scuba_diving\"', {$alias}.raw_tags) > 0 OR
            LOCATE('\"sport\":\"canoeing\"', {$alias}.raw_tags) > 0 OR
            LOCATE('\"sport\":\"kayak\"', {$alias}.raw_tags) > 0 OR
            LOCATE('\"sport\":\"sailing\"', {$alias}.raw_tags) > 0 OR
            LOCATE('\"sport\":\"rowing\"', {$alias}.raw_tags) > 0 OR
            LOCATE('\"sport\":\"ice_skating\"', {$alias}.raw_tags) > 0 OR
            LOCATE('\"sport\":\"bowling\"', {$alias}.raw_tags) > 0 OR
            LOCATE('\"sport\":\"billiards\"', {$alias}.raw_tags) > 0 OR
            LOCATE('\"sport\":\"padel\"', {$alias}.raw_tags) > 0 OR
            LOCATE('\"sport\":\"equestrian\"', {$alias}.raw_tags) > 0 OR
            LOCATE('\"sport\":\"skiing\"', {$alias}.raw_tags) > 0 OR
            LOCATE('\"sport\":\"snowboarding\"', {$alias}.raw_tags) > 0
        )";
    }

    private function activity_category_leakage_expression($alias = 'p') {
        $alias = $alias === 'p' ? 'p' : 'p';
        $independent = $this->activity_independent_signal_expression($alias);
        return "((LOCATE('\"tourism\":', {$alias}.raw_tags) > 0 OR LOCATE('\"historic\":', {$alias}.raw_tags) > 0) AND NOT $independent)";
    }

    private function activity_known_closed_expression($alias = 'p') {
        $alias = $alias === 'p' ? 'p' : 'p';
        return "(
            {$alias}.lifecycle_status <> 'active' OR
            LOCATE('\"disused\":\"yes\"', {$alias}.raw_tags) > 0 OR
            LOCATE('\"abandoned\":\"yes\"', {$alias}.raw_tags) > 0 OR
            LOCATE('\"demolished\":\"yes\"', {$alias}.raw_tags) > 0 OR
            LOCATE('\"razed\":\"yes\"', {$alias}.raw_tags) > 0 OR
            LOCATE('\"removed\":\"yes\"', {$alias}.raw_tags) > 0 OR
            LOCATE('\"closed\":\"yes\"', {$alias}.raw_tags) > 0 OR
            LOCATE('\"disused:', {$alias}.raw_tags) > 0 OR
            LOCATE('\"abandoned:', {$alias}.raw_tags) > 0 OR
            LOCATE('\"demolished:', {$alias}.raw_tags) > 0 OR
            LOCATE('\"razed:', {$alias}.raw_tags) > 0 OR
            LOCATE('\"removed:', {$alias}.raw_tags) > 0 OR
            LOCATE('\"opening_hours\":\"closed\"', {$alias}.raw_tags) > 0
        )";
    }

    private function activity_read_filter_sql($alias = 'p') {
        return ' AND NOT ' . $this->activity_hard_blacklist_expression($alias)
            . ' AND NOT ' . $this->activity_category_leakage_expression($alias)
            . ' AND NOT ' . $this->activity_known_closed_expression($alias) . ' ';
    }

    /**
     * V1.2.3 SQL candidate priority. This does not replace PHP Experience
     * Intelligence; it prevents nationally/regionally relevant experiences from
     * being lost when the 1,500-row bounded candidate pool is filled by nearer
     * low-value POIs. Wikidata/Wikipedia is only a secondary trust bonus after activity qualification.
     */
    private function activity_priority_sql($alias = 'p') {
        $alias = $alias === 'p' ? 'p' : 'p';
        return "(
            CASE
                WHEN (
                    LOCATE('\"sport\":\"skateboard\"', {$alias}.raw_tags) > 0 OR
                    LOCATE('\"sport\":\"skateboarding\"', {$alias}.raw_tags) > 0 OR
                    LOCATE('\"sport\":\"bmx\"', {$alias}.raw_tags) > 0 OR
                    LOCATE('\"sport\":\"climbing\"', {$alias}.raw_tags) > 0 OR
                    LOCATE('\"sport\":\"bouldering\"', {$alias}.raw_tags) > 0 OR
                    LOCATE('\"sport\":\"climbing_adventure\"', {$alias}.raw_tags) > 0 OR
                    LOCATE('\"sport\":\"karting\"', {$alias}.raw_tags) > 0 OR
                    LOCATE('\"sport\":\"wakeboarding\"', {$alias}.raw_tags) > 0 OR
                    LOCATE('\"sport\":\"water_ski\"', {$alias}.raw_tags) > 0 OR
                    LOCATE('\"sport\":\"scuba_diving\"', {$alias}.raw_tags) > 0 OR
                    LOCATE('\"leisure\":\"water_park\"', {$alias}.raw_tags) > 0
                ) THEN 300
                WHEN (LOCATE('\"natural\":\"water\"', {$alias}.raw_tags) > 0 AND LOCATE('\"sport\":\"swimming\"', {$alias}.raw_tags) > 0) THEN 240
                WHEN (
                    LOCATE('\"leisure\":\"swimming_pool\"', {$alias}.raw_tags) > 0 OR
                    LOCATE('\"amenity\":\"public_bath\"', {$alias}.raw_tags) > 0 OR
                    LOCATE('\"amenity\":\"swimming_pool\"', {$alias}.raw_tags) > 0
                ) THEN 130
                ELSE 170
            END
            + CASE WHEN ({$alias}.wikidata <> '' OR {$alias}.wikipedia <> '' OR LOCATE('\"wikidata\":', {$alias}.raw_tags) > 0 OR LOCATE('\"wikipedia\":', {$alias}.raw_tags) > 0) THEN 20 ELSE 0 END
        )";
    }



    /**
     * Activities Intelligence V2 – Dark Launch 1.10.88.
     *
     * This resolver is deliberately additive. It does NOT drive the public
     * Activities feed yet. It produces a structured, developer-facing profile
     * so admission/role/capability/scoring can be audited against real Places
     * before the existing visitor path is switched.
     */
    private function activity_v2_values($value) {
        if (is_array($value)) $parts = $value;
        else $parts = preg_split('/[;,|]+/u', strtolower(trim((string)$value)));
        $out = array();
        foreach ((array)$parts as $part) {
            $v = strtolower(trim((string)$part));
            if ($v !== '' && !in_array($v, $out, true)) $out[] = $v;
        }
        return $out;
    }

    private function activity_v2_profile($row) {
        $tags = json_decode((string)($row['raw_tags'] ?? ''), true);
        if (!is_array($tags)) $tags = array();
        $name = $this->normalize_text((string)($row['name'] ?? ''));
        $derived_name = strtolower(trim((string)($tags['rg:name_source'] ?? ''))) === 'derived'
            || in_array(strtolower(trim((string)($tags['rg:derived_name'] ?? ''))), array('yes','true','1'), true);
        $access = strtolower((string)($tags['access'] ?? ''));
        $leisure = strtolower((string)($tags['leisure'] ?? ''));
        $amenity = strtolower((string)($tags['amenity'] ?? ''));
        $shop = strtolower((string)($tags['shop'] ?? ''));
        $tourism = strtolower((string)($tags['tourism'] ?? ''));
        $building = strtolower((string)($tags['building'] ?? ''));
        $natural = strtolower((string)($tags['natural'] ?? ''));
        $surface = strtolower((string)($tags['surface'] ?? ''));
        $indoor = strtolower((string)($tags['indoor'] ?? ''));
        $covered = strtolower((string)($tags['covered'] ?? ''));
        $fee = strtolower((string)($tags['fee'] ?? ''));
        $informal = strtolower((string)($tags['informal'] ?? ''));
        $operator_type = strtolower((string)($tags['operator:type'] ?? ''));
        $sports = $this->activity_v2_values($tags['sport'] ?? '');
        $leisures = $this->activity_v2_values($tags['leisure'] ?? '');
        $has_sport = function($needle) use ($sports) { return in_array($needle, $sports, true); };
        $has_leisure = function($needle) use ($leisures, $leisure) { return $leisure === $needle || in_array($needle, $leisures, true); };
        $has_website = !empty($tags['website']) || !empty($tags['contact:website']) || !empty($row['website']);
        $has_hours = !empty($tags['opening_hours']) || !empty($row['opening_hours']);
        $has_contact = !empty($tags['phone']) || !empty($tags['contact:phone']) || !empty($tags['email']) || !empty($tags['contact:email']) || !empty($row['phone']);
        $booking_signal = !empty($tags['reservation']) || !empty($tags['booking']) || !empty($tags['booking:website'])
            || !empty($tags['contact:booking']) || preg_match('/\b(buchung|booking|reservier|tickets?|tageskarte|gastkarte)\b/u', $name);
        $rental_signal = in_array(strtolower((string)($tags['rental'] ?? '')), array('yes','true','1','boat','canoe','kayak','sup','bicycle'), true)
            || in_array(strtolower((string)($tags['boat_rental'] ?? ($tags['rental:boat'] ?? ''))), array('yes','true','1','boat','canoe','kayak','sup'), true)
            || preg_match('/\b(verleih|vermiet|mietstation|tagespass|tageskarte|gastspieler|gastspiel|schnupper|kurse?|ausritt|reitstunden?)\b/u', $name);
        $public_access = in_array($access, array('yes','permissive','customers','public'), true);
        $private_access = in_array($access, array('private','no','members'), true);
        $commercial_visit = (($fee === 'yes' || $fee === '1' || $fee === 'true') && ($has_hours || $has_website || $booking_signal)) || $booking_signal || $rental_signal;
        $visitor_offer = $public_access || $commercial_visit || $rental_signal;
