            $add_exp('ice_skating','rein',0.94,array('solo_friendly','friends_friendly','pair_friendly','date_friendly','active','indoor','weatherproof'),array('ice rink/skating'),!$core_assigned);
        if ($has_sport('skiing') || $has_sport('snowboarding') || preg_match('/\b(skihalle|indoor ski)\b/u',$name))
            $add_exp('indoor_ski','rein',0.94,array('solo_friendly','friends_friendly','pair_friendly','date_friendly','action','active','indoor','weatherproof','booking_required'),array('ski/snowboard'),!$core_assigned);
        if ($amenity === 'sauna' || preg_match('/\b(therme|saunalandschaft|day spa)\b/u',$name))
            $add_exp('wellness',($visitor_offer||$has_website||$has_hours||strpos($name,'therme')!==false)?'rein':'bedingt',0.82,array('solo_friendly','pair_friendly','date_friendly','relaxed','indoor','weatherproof'),array('sauna/therme'),!$core_assigned);

        if (preg_match('/\bgolf house\b/u',$name)) $hard[] = 'retail_only';

        // Retail is never promoted into a leisure Experience merely because it carries a sport tag.
        if ($shop !== '' && !$has_leisure('skate_park') && !$has_leisure('water_park') && !$has_leisure('escape_game') && !$has_leisure('trampoline_park') && !$has_leisure('bowling_alley') && !$has_leisure('miniature_golf')) {
            $hard[] = 'retail_only';
        }

        // No recognised experience means the row is outside Activities V2, even if the legacy catalogue contains it.
        if (!$experiences) $hard[] = 'experience_missing';

        if ($hard) {
            foreach ($experiences as &$exp) $exp['admission'] = 'raus';
            unset($exp);
            $admission = 'raus';
        } else {
            $admission = 'raus';
            foreach ($experiences as $exp) {
                if (($exp['admission'] ?? '') === 'rein') { $admission = 'rein'; break; }
                if (($exp['admission'] ?? '') === 'bedingt') $admission = 'bedingt';
            }
            // Membership identity is not a hard blocker by name alone. It may only suppress
            // conditional/member-type Experiences when there is no visitor evidence.
            if ($membership_identity && !$visitor_offer && !$public_access && !$verified_model_flying && !$verified_soccerfive && !$verified_jump_academy && !$verified_activity_landscape) {
                $has_inherently_public = false;
                foreach ($experiences as $exp) if (in_array($exp['type'],array('skatepark','pumptrack','bikepark','bmx','basketball','bolzplatz','outdoor_fitness','disc_golf','bathing_lake'),true)) {$has_inherently_public=true;break;}
                if (!$has_inherently_public && $admission === 'rein') $admission = 'bedingt';
            }
        }

        $primary = $experiences ? $experiences[0] : null;
        foreach ($experiences as $exp) if (($exp['role'] ?? '') === 'core') { $primary = $exp; break; }
        $type = (string)($primary['type'] ?? '');

        $access_score = $private_access ? 0 : ($public_access ? 96 : ($visitor_offer ? 86 : 62));
        if ($admission === 'raus') $access_score = min($access_score,25);
        $experience_base = array(
            'water_park'=>96,'swimming'=>78,'bathing_lake'=>82,'escape_room'=>96,'trampoline_park'=>95,'karting'=>97,
            'climbing_adventure'=>97,'climbing'=>94,'bouldering'=>95,'skatepark'=>96,'pumptrack'=>94,'bikepark'=>94,'bmx'=>92,
            'basketball'=>86,'beach_volleyball'=>84,'table_tennis'=>68,'outdoor_fitness'=>82,'disc_golf'=>84,'bolzplatz'=>75,'soccer_pitch'=>45,
            'bowling'=>90,'billiards'=>82,'laser_tag'=>92,'vr'=>88,'mini_golf'=>84,'blacklight_golf'=>90,'adventure_golf'=>88,
            'paintball'=>90,'axe_throwing'=>88,'wakeboarding'=>96,'water_ski'=>96,'scuba_diving'=>90,'sup'=>84,'kayak'=>84,'canoeing'=>84,
            'barefoot_trail'=>94,'archery'=>84,'parkour'=>90,'footballgolf'=>86,'padel'=>82,'tennis'=>70,'squash'=>78,'badminton'=>74,'equestrian'=>78,'ice_skating'=>86,'indoor_ski'=>94,'wellness'=>76,'soccer_five'=>88,'model_flying'=>82,'shooting_sports'=>78,'athletics'=>68,'golf'=>72,'dance_fitness'=>76,'volleyball'=>72,'handball'=>72,'korfball'=>70,'multi_sport_park'=>80
        );
        $destination_base = array(
            'water_park'=>90,'swimming'=>52,'bathing_lake'=>70,'escape_room'=>78,'trampoline_park'=>80,'karting'=>82,
            'climbing_adventure'=>86,'climbing'=>76,'bouldering'=>76,'skatepark'=>68,'pumptrack'=>66,'bikepark'=>72,'bmx'=>64,
            'basketball'=>52,'beach_volleyball'=>54,'table_tennis'=>38,'outdoor_fitness'=>48,'disc_golf'=>62,'bolzplatz'=>42,'soccer_pitch'=>30,
            'bowling'=>72,'billiards'=>62,'laser_tag'=>74,'vr'=>72,'mini_golf'=>68,'blacklight_golf'=>74,'adventure_golf'=>72,
            'paintball'=>76,'axe_throwing'=>66,'wakeboarding'=>82,'water_ski'=>82,'scuba_diving'=>76,'sup'=>64,'kayak'=>66,'canoeing'=>66,
            'barefoot_trail'=>82,'archery'=>68,'parkour'=>68,'footballgolf'=>72,'padel'=>62,'tennis'=>52,'squash'=>58,'badminton'=>54,'equestrian'=>66,'ice_skating'=>70,'indoor_ski'=>86,'wellness'=>78,'soccer_five'=>70,'model_flying'=>62,'shooting_sports'=>58,'athletics'=>50,'golf'=>62,'dance_fitness'=>58,'volleyball'=>52,'handball'=>52,'korfball'=>50,'multi_sport_park'=>68
        );
        $spont_base = array(
            'skatepark'=>98,'pumptrack'=>98,'bikepark'=>90,'bmx'=>94,'basketball'=>99,'beach_volleyball'=>92,'table_tennis'=>96,'outdoor_fitness'=>99,'disc_golf'=>88,'bolzplatz'=>96,
            'swimming'=>78,'bathing_lake'=>95,'water_park'=>60,'escape_room'=>40,'trampoline_park'=>55,'karting'=>48,'climbing_adventure'=>45,'climbing'=>70,'bouldering'=>78,
            'bowling'=>65,'billiards'=>75,'laser_tag'=>45,'vr'=>45,'mini_golf'=>78,'blacklight_golf'=>60,'adventure_golf'=>70,'paintball'=>35,'axe_throwing'=>40,
            'wakeboarding'=>38,'water_ski'=>38,'scuba_diving'=>25,'sup'=>52,'kayak'=>52,'canoeing'=>52,'padel'=>42,'tennis'=>42,'squash'=>50,'badminton'=>50,
            'barefoot_trail'=>95,'archery'=>62,'parkour'=>92,'footballgolf'=>72,'equestrian'=>28,'ice_skating'=>70,'indoor_ski'=>42,'wellness'=>60,'soccer_pitch'=>60,'soccer_five'=>42,'model_flying'=>35,'shooting_sports'=>30,'athletics'=>70,'golf'=>45,'dance_fitness'=>45,'volleyball'=>72,'handball'=>68,'korfball'=>68,'multi_sport_park'=>70
        );
        $experience_score = (int)($experience_base[$type] ?? 55);
        $destination_score = (int)($destination_base[$type] ?? 50);
        $spontaneity_score = (int)($spont_base[$type] ?? 55);
        if ($booking_signal) $spontaneity_score = min($spontaneity_score,50);
        if ($fee === 'no' || $fee === '0' || $fee === 'false') $spontaneity_score = min(100,$spontaneity_score+5);
        if ($has_hours) $destination_score = min(100,$destination_score+4);
        if ($has_website) $destination_score = min(100,$destination_score+4);
        if (!empty($tags['lit']) && strtolower((string)$tags['lit']) === 'yes') $destination_score = min(100,$destination_score+3);

        // A real multi-offer is valuable, but sport=multi by itself is not evidence.
        // Count only concrete REIN experiences already admitted by the resolver.
        $accepted_experience_count = 0;
        foreach ($experiences as $multi_exp) if (($multi_exp['admission'] ?? '') === 'rein') $accepted_experience_count++;
        if ($accepted_experience_count >= 3) {
            $experience_score = min(100,$experience_score + min(8,($accepted_experience_count-2)*3));
            $destination_score = min(100,$destination_score + min(10,($accepted_experience_count-2)*4));
        }

        $caps = array();
        foreach ($experiences as $exp) foreach ((array)($exp['capabilities'] ?? array()) as $cap) if (!in_array($cap,$caps,true)) $caps[]=$cap;
        if ($accepted_experience_count >= 3 && !in_array('multi_activity',$caps,true)) $caps[]='multi_activity';

        // Environment is descriptive/searchable metadata, never a generic ranking penalty.
        // Prefer explicit OSM indoor semantics; otherwise use accepted experience capabilities.
        $has_indoor_cap = false; $has_outdoor_cap = false;
        foreach ($experiences as $env_exp) {
            if (($env_exp['admission'] ?? '') !== 'rein') continue;
            $env_caps = (array)($env_exp['capabilities'] ?? array());
            if (in_array('indoor',$env_caps,true)) $has_indoor_cap = true;
            if (in_array('outdoor',$env_caps,true)) $has_outdoor_cap = true;
        }
        if (in_array($indoor,array('yes','true','1'),true)) $activity_environment = $has_outdoor_cap ? 'both' : 'indoor';
        elseif ($indoor === 'no') $activity_environment = $has_indoor_cap ? 'both' : 'outdoor';
        elseif ($has_indoor_cap && $has_outdoor_cap) $activity_environment = 'both';
        elseif ($has_indoor_cap) $activity_environment = 'indoor';
        elseif ($has_outdoor_cap) $activity_environment = 'outdoor';
        elseif ($building !== '' || $covered === 'yes') $activity_environment = 'indoor';
        else $activity_environment = 'unknown';

        $evidence = array();
        if ($public_access) $evidence[]='public_access';
        if ($visitor_offer) $evidence[]='visitor_offer';
        if ($has_website) $evidence[]='website';
        if ($has_hours) $evidence[]='opening_hours';
        if ($has_contact) $evidence[]='contact';
        if ($fee !== '') $evidence[]='fee='.$fee;
        if ($membership_identity) $evidence[]='membership_identity';
        if ($derived_name) $evidence[]='derived_name';

        return array(
            'spec_version'=>self::ACTIVITY_V2_SPEC_VERSION,
            'admission'=>$admission,
            'primary_experience'=>$type,
            'experiences'=>$experiences,
            'hard_blockers'=>array_values(array_unique($hard)),
            'capabilities'=>$caps,
            'environment'=>$activity_environment,
            'multi_experience_count'=>$accepted_experience_count,
            'scores'=>array(
                'access'=>(int)max(0,min(100,$access_score)),
                'experience'=>(int)max(0,min(100,$experience_score)),
                'destination'=>(int)max(0,min(100,$destination_score)),
                'spontaneity'=>(int)max(0,min(100,$spontaneity_score)),
                'local_relevance'=>null,
            ),
            'local_relevance_mode'=>'phase2b_radial_5_15km',
            'evidence'=>$evidence,
        );
    }

    /**
     * Activities V2 Phase 2C – public projection.
     * Only REIN experiences are allowed to reach the visitor feed. BEDINGT is
     * intentionally not "rescued" by distance/scarcity; it remains a research
     * state exactly as defined by the V2 spec.
     */
    private function activity_v2_public_label($type) {
        $map = array(
            'water_park'=>'Erlebnisbad & Wasserpark','swimming'=>'Schwimmen','bathing_lake'=>'Badesee',
            'escape_room'=>'Escape Room','trampoline_park'=>'Trampolinpark','karting'=>'Karting',
            'climbing_adventure'=>'Kletterpark','climbing'=>'Klettern','bouldering'=>'Bouldern',
            'skatepark'=>'Skatepark','pumptrack'=>'Pumptrack','bikepark'=>'Bikepark','bmx'=>'BMX',
            'basketball'=>'Basketball','beach_volleyball'=>'Beachvolleyball','table_tennis'=>'Tischtennis',
            'outdoor_fitness'=>'Outdoor-Fitness','disc_golf'=>'Disc Golf','barefoot_trail'=>'Barfußpfad','archery'=>'Bogenschießen','parkour'=>'Parkour','footballgolf'=>'Footballgolf','bolzplatz'=>'Bolzplatz',
            'soccer_five'=>'Soccer & Futsal','bowling'=>'Bowling','billiards'=>'Billard','laser_tag'=>'Lasertag',
            'vr'=>'Virtual Reality','mini_golf'=>'Minigolf','blacklight_golf'=>'Schwarzlichtgolf',
            'adventure_golf'=>'Adventure Golf','paintball'=>'Paintball','axe_throwing'=>'Axtwerfen',
            'wakeboarding'=>'Wakeboard','water_ski'=>'Wasserski','scuba_diving'=>'Tauchen','sup'=>'SUP',
            'kayak'=>'Kajak','canoeing'=>'Kanu','padel'=>'Padel','tennis'=>'Tennis','squash'=>'Squash',
            'badminton'=>'Badminton','equestrian'=>'Reiten','ice_skating'=>'Eislaufen','indoor_ski'=>'Skihalle',
            'wellness'=>'Therme & Sauna','model_flying'=>'Modellflug','shooting_sports'=>'Schießsport',
            'athletics'=>'Leichtathletik','golf'=>'Golf','dance_fitness'=>'Tanz & Fitness',
            'volleyball'=>'Volleyball','handball'=>'Handball','korfball'=>'Korfball','multi_sport_park'=>'Sportpark'
        );
        return isset($map[$type]) ? $map[$type] : ucwords(str_replace('_',' ',(string)$type));
    }

    private function activity_v2_public_bucket($type) {
        if (in_array($type,array('water_park','swimming','bathing_lake'),true)) return 'water_fun';
        if (in_array($type,array('wakeboarding','water_ski','scuba_diving','sup','kayak','canoeing'),true)) return 'water_action';
        if (in_array($type,array('climbing_adventure','climbing','bouldering'),true)) return 'climbing';
        if (in_array($type,array('skatepark','pumptrack','bikepark','bmx','parkour'),true)) return 'urban_action';
        if (in_array($type,array('karting','paintball','laser_tag','indoor_ski'),true)) return 'adrenaline';
        if (in_array($type,array('escape_room','trampoline_park','bowling','billiards','vr','mini_golf','blacklight_golf','adventure_golf','axe_throwing'),true)) return 'group_indoor';
        if (in_array($type,array('basketball','beach_volleyball','table_tennis','outdoor_fitness','disc_golf','barefoot_trail','footballgolf','bolzplatz','multi_sport_park'),true)) return 'outdoor';
        if (in_array($type,array('padel','tennis','squash','badminton','soccer_five','volleyball','handball','korfball','dance_fitness'),true)) return 'group_sport';
        if (in_array($type,array('equestrian','archery','model_flying','shooting_sports','athletics','golf'),true)) return 'outdoor';
        if ($type==='ice_skating') return 'action';
        if ($type==='wellness') return 'wellness';
        return 'experience';
    }

    private function activity_v2_public_subcategory($type) {
        $bucket=$this->activity_v2_public_bucket($type);
        if ($bucket==='climbing') return 'Klettern & Bouldern';
        if (strpos($bucket,'water_')===0 || $bucket==='wellness') return 'Wasser & Badespaß';
        if (in_array($bucket,array('adrenaline','urban_action','action'),true)) return 'Action & Adrenalin';
        if ($bucket==='group_indoor') return 'Games & Gruppen';
        if ($bucket==='group_sport') return 'Sport & Bewegung';
        if ($bucket==='outdoor') return 'Outdoor & Entdecken';
        return 'Freizeit & Erlebnis';
    }

    private function activity_v2_public_projection($row) {
        $profile=$this->activity_v2_profile($row);
        if (!is_array($profile) || (string)($profile['admission']??'')!=='rein') return null;
        $accepted=array();
        foreach((array)($profile['experiences']??array()) as $exp){
            if((string)($exp['admission']??'')==='rein')$accepted[]=$exp;
        }
        if(!$accepted)return null;
        $primary=null;
        foreach($accepted as $exp){if((string)($exp['role']??'')==='core'){$primary=$exp;break;}}
        if(!$primary)$primary=$accepted[0];
        $type=(string)($primary['type']??'');
        if($type==='')return null;
        $scores=(array)($profile['scores']??array());
        $access=(float)($scores['access']??0);$experience=(float)($scores['experience']??0);
        $destination=(float)($scores['destination']??0);$spont=(float)($scores['spontaneity']??0);
        $score=0.28*$access+0.32*$experience+0.22*$destination+0.18*$spont;
        if(count($accepted)>1)$score+=min(4.0,(count($accepted)-1)*1.5);
        $score=max(0.0,min(100.0,$score));
        $distance=isset($row['distance_km'])?max(0.0,(float)$row['distance_km']):0.0;
        $rank=$score-min(10.0,$distance*0.40);
        $labels=array();
        foreach($accepted as $exp){
            $label=$this->activity_v2_public_label((string)($exp['type']??''));
            if($label!==''&&!in_array($label,$labels,true))$labels[]=$label;
        }
        return array(
            'score'=>round($score,2),'rank_score'=>round($rank,2),'bucket'=>$this->activity_v2_public_bucket($type),
            'subcategory'=>$this->activity_v2_public_subcategory($type),'labels'=>array_slice($labels,0,6),
            'primary_experience'=>$type,'environment'=>(string)($profile['environment']??'unknown'),'multi_experience_count'=>(int)($profile['multi_experience_count']??count($accepted)),'accepted_experiences'=>$accepted,'profile'=>$profile
        );
    }

    /**
     * Phase 2C SQL safety gate. Do not reintroduce the former generic pitch/
     * fitness blacklist here: V2 must see those rows so it can distinguish e.g.
     * a public basketball court from a football club pitch or a verified course
     * venue from a generic gym. Only unequivocal hard access/lifecycle blockers
     * are removed before PHP admission.
     */
    private function activity_v2_public_read_filter_sql($alias='p') {
        $alias=$alias==='p'?'p':'p';
        return " AND NOT (".$this->activity_known_closed_expression($alias).")"
            ." AND LOCATE('\"access\":\"private\"', {$alias}.raw_tags)=0"
            ." AND LOCATE('\"access\":\"no\"', {$alias}.raw_tags)=0"
            ." AND LOCATE('\"access\":\"members\"', {$alias}.raw_tags)=0 ";
    }

    private function activity_v2_audit_snapshot() {
        global $wpdb;
        $catalog = (string)get_option(self::OPTION_CATALOG_VERSION,'bootstrap');
        $cache_key = 'rg_act_v2_' . md5(self::ACTIVITY_V2_SPEC_VERSION . '|' . $catalog);
        $cached = get_transient($cache_key);
        if (is_array($cached)) return $cached;
        $places = $this->table('places');
        $summary = array('total'=>0,'rein'=>0,'bedingt'=>0,'raus'=>0,'types'=>array(),'type_admission'=>array(),'blockers'=>array(),'municipalities'=>array(),'municipalities_seen'=>array(),'derived_names'=>0,'edge_cases'=>array(),'none_samples'=>array());
        $tracked = array('skatepark','basketball','beach_volleyball','table_tennis','outdoor_fitness','bolzplatz','soccer_pitch','soccer_five','tennis','padel','equestrian','swimming','water_park','escape_room','bowling','karting','model_flying','shooting_sports','athletics','golf','dance_fitness','multi_sport_park','none');
        $sample_counts = array();
        $last_id = 0;
        $batch_size = 1000;
        do {
            $rows = (array)$wpdb->get_results($wpdb->prepare(
                "SELECT id,name,city,municipality_slug,lat,lng,website,opening_hours,phone,raw_tags,quality_score,active,lifecycle_status FROM $places WHERE active=1 AND lifecycle_status='active' AND primary_category='activities' AND id>%d ORDER BY id ASC LIMIT %d",
                $last_id, $batch_size
            ), ARRAY_A);
            foreach ($rows as $row) {
                $last_id = max($last_id, (int)($row['id'] ?? 0));
                $p = $this->activity_v2_profile($row);
                $summary['total']++;
                $a = (string)($p['admission'] ?? 'raus');
                if (!isset($summary[$a])) $summary[$a]=0;
                $summary[$a]++;
                $type=(string)($p['primary_experience']??''); if($type==='')$type='none';
                $summary['types'][$type]=(int)($summary['types'][$type]??0)+1;
                if(!isset($summary['type_admission'][$type]))$summary['type_admission'][$type]=array('rein'=>0,'bedingt'=>0,'raus'=>0,'total'=>0);
                if(!isset($summary['type_admission'][$type][$a]))$summary['type_admission'][$type][$a]=0;
                $summary['type_admission'][$type][$a]++;
                $summary['type_admission'][$type]['total']++;
                foreach((array)($p['hard_blockers']??array()) as $b)$summary['blockers'][$b]=(int)($summary['blockers'][$b]??0)+1;
                $m=(string)($row['municipality_slug']??'');
                if($m!==''){
                    $summary['municipalities_seen'][$m]=(int)($summary['municipalities_seen'][$m]??0)+1;
                    if($a!=='raus')$summary['municipalities'][$m]=(int)($summary['municipalities'][$m]??0)+1;
                }

                $tags=json_decode((string)($row['raw_tags']??''),true);if(!is_array($tags))$tags=array();
                if(strtolower(trim((string)($tags['rg:name_source']??'')))==='derived'||in_array(strtolower(trim((string)($tags['rg:derived_name']??''))),array('yes','true','1'),true))$summary['derived_names']++;
                $signal=array();foreach(array('leisure','sport','amenity','access','shop','surface','fee','rg:name_source') as $k){$v=trim((string)($tags[$k]??''));if($v!=='')$signal[]=$k.'='.$v;}
                $edge=array('id'=>(int)$row['id'],'name'=>(string)$row['name'],'city'=>(string)$row['city'],'admission'=>$a,'type'=>$type,'blockers'=>(array)($p['hard_blockers']??array()),'evidence'=>(array)($p['evidence']??array()),'signal'=>implode(' · ',$signal));
                if(in_array($type,$tracked,true)){$sample_counts[$type]=(int)($sample_counts[$type]??0);if($sample_counts[$type]<5){$summary['edge_cases'][]=$edge;$sample_counts[$type]++;}}
                if($type==='none'&&count($summary['none_samples'])<15)$summary['none_samples'][]=$edge;
            }
        } while (count($rows) === $batch_size);
        arsort($summary['types']);arsort($summary['blockers']);arsort($summary['municipalities']);arsort($summary['municipalities_seen']);
        uasort($summary['type_admission'],function($a,$b){return (int)($b['total']??0)<=>(int)($a['total']??0);});
        set_transient($cache_key,$summary,10*MINUTE_IN_SECONDS);
        return $summary;
    }

    /**
     * V1.2.4 Activity Intelligence for the Activities catalogue.
     *
     * The persistent DB deliberately remains broad. At read time we suppress
     * membership/training businesses and generic sports infrastructure, then
     * rank actual leisure experiences. No re-import or destructive migration is
     * required. The returned helper fields are transient response metadata only.
     */
    private function activity_experience_profile($row, $allow_highlight = false) {
        $tags = json_decode((string) ($row['raw_tags'] ?? ''), true);
        if (!is_array($tags)) $tags = array();
        $name = $this->normalize_text((string) ($row['name'] ?? ''));
        $amenity = strtolower((string) ($tags['amenity'] ?? ''));
        $tourism = strtolower((string) ($tags['tourism'] ?? ''));
        $leisure = strtolower((string) ($tags['leisure'] ?? ''));
        $sport = strtolower((string) ($tags['sport'] ?? ''));
        $historic = strtolower((string) ($tags['historic'] ?? ''));
        $access = strtolower((string) ($tags['access'] ?? ''));
        $fee = strtolower((string) ($tags['fee'] ?? ''));
        $indoor = strtolower((string) ($tags['indoor'] ?? ''));
        $covered = strtolower((string) ($tags['covered'] ?? ''));
        $building = strtolower((string) ($tags['building'] ?? ''));
        $natural = strtolower((string) ($tags['natural'] ?? ''));
        $rental = strtolower((string) ($tags['rental'] ?? ''));
        $boat_rental = strtolower((string) ($tags['boat_rental'] ?? ($tags['rental:boat'] ?? '')));
        $operator_type = strtolower((string) ($tags['operator:type'] ?? ''));

        if (empty($row['active']) && array_key_exists('active', $row)) return null;
        if (!empty($row['lifecycle_status']) && (string) $row['lifecycle_status'] !== 'active') return null;
        if ($this->is_inactive_tags($tags)) return null;
        if (in_array($access, array('private','no','members'), true)) return null;

        // Hard blacklist: everyday training infrastructure is not an experience feed.
        // A skatepark may legitimately be mapped as leisure=pitch + sport=skateboard/skateboarding/bmx.
        $is_skate_activity = $leisure === 'skate_park' || in_array($sport, array('skateboard','skateboarding','bmx'), true);
        if ($leisure === 'fitness_centre' || ($leisure === 'pitch' && !$is_skate_activity) || in_array($sport, array('yoga','pilates','gymnastics','soccer'), true)) return null;

        // V1.2.4 visitor-use gate: infrastructure or membership organisations are
        // not activities by themselves. A marina, harbour or paddling club is only
        // useful in the discovery feed when OSM/name data exposes a concrete public
        // offer such as rental, tours, courses or an unmistakable visitor activity.
        $membership_identity = (bool) preg_match('/\b(verein|club|freunde|gemeinschaft|yachtclub|yacht club|segelclub|segel club|ruderclub|ruder club|kanuclub|kanu club|kanu-freunde)\b/u', $name);
        $visitor_offer_name = (bool) preg_match('/\b(verleih|vermiet|mietstation|bootsverleih|kanuverleih|kajakverleih|sup(?:-?station)?|stand up paddle|paddelstation|kanustation|kajakstation|touren?|kurse?|schnupper|wake(?:board|park)?|wasserski|tauchbasis|diving center|diving centre)\b/u', $name);
        $visitor_offer_tag = in_array($rental, array('yes','boat','canoe','kayak','sup'), true)
            || in_array($boat_rental, array('yes','boat','canoe','kayak','sup'), true)
            || $amenity === 'boat_rental'
            || in_array(strtolower((string) ($tags['canoe_rental'] ?? '')), array('yes','true','1'), true)
            || in_array(strtolower((string) ($tags['kayak_rental'] ?? '')), array('yes','true','1'), true);
        $visitor_offer = $visitor_offer_name || $visitor_offer_tag;
        if (in_array($leisure, array('marina','slipway'), true) && !$visitor_offer) return null;
        if (in_array($sport, array('canoeing','kayak','sailing','rowing'), true) && $membership_identity && !$visitor_offer) return null;

        $score = 0.0;
        $bucket = '';
        $labels = array();
        $strong = false;
        $outdoor = $indoor === 'no' || (($indoor === '' || $indoor === 'outdoor') && $building === '' && $covered !== 'yes');
        $is_bathing_lake = $natural === 'water' && $sport === 'swimming';
        $has_wikimedia_notability = !empty($tags['wikidata']) || !empty($tags['wikipedia']) || !empty($row['wikidata']) || !empty($row['wikipedia']);

        $sport_action = in_array($sport, array(
            'swimming','climbing','bouldering','climbing_adventure','skateboard','skateboarding','bmx','karting',
            'wakeboarding','water_ski','scuba_diving','canoeing','kayak','sailing','rowing','ice_skating','bowling',
            'billiards','padel','equestrian','skiing','snowboarding'
        ), true);
        $leisure_action = in_array($leisure, array(
            'swimming_pool','water_park','bowling_alley','skate_park','ice_rink','miniature_golf','disc_golf_course',
            'marina','slipway','escape_game','trampoline_park'
        ), true);
        $amenity_activity = in_array($amenity, array('public_bath','swimming_pool','sauna'), true);
        $independent_activity = $sport_action || $leisure_action || $amenity_activity || $is_bathing_lake;

        // Category separation: tourism/historic metadata never qualifies a place for
        // Activities. A genuine sport/action signal may coexist with those tags.
        if (($tourism !== '' || $historic !== '') && !$independent_activity) return null;

        $add = function($label) use (&$labels) {
            if ($label !== '' && !in_array($label, $labels, true)) $labels[] = $label;
        };

        if (in_array($leisure, array('escape_game','trampoline_park'), true)) {
            $strong = true; $score = $leisure === 'escape_game' ? 94 : 93; $bucket = 'group';
            $add($leisure === 'escape_game' ? 'Escape' : 'Action'); $add('Für Gruppen'); $add('Active Date'); $add('Indoor');
        } elseif ($sport === 'karting' || strpos($name, 'kart') !== false) {
            $strong = true; $score = 97; $bucket = 'adrenaline'; $add('Adrenalin'); $add('Für Gruppen');
        } elseif (in_array($sport, array('climbing','bouldering','climbing_adventure'), true) || strpos($name, 'kletter') !== false || strpos($name, 'boulder') !== false) {
            $strong = true; $score = $sport === 'climbing_adventure' ? 98 : 95; $bucket = 'climbing';
            $add('Klettern & Bouldern'); $add('Action'); $add($outdoor ? 'Outdoor' : 'Indoor');
        } elseif ($is_skate_activity || preg_match('/\b(skatepark|skate park|pumptrack|pump track|bikepark|bike park|bmx|halfpipe)\b/u', $name)) {
            $strong = true; $score = 98; $bucket = 'urban_action'; $add('Urban Action'); $add('Outdoor');
        } elseif (in_array($sport, array('wakeboarding','water_ski','scuba_diving'), true) || preg_match('/\b(wakeboard|wake park|tauch(?:en|spot)|diving)\b/u', $name)) {
            $strong = true; $score = $sport === 'scuba_diving' ? 96 : 98; $bucket = 'water_action';
            $add('Action'); $add('Am Wasser'); $add('Outdoor'); $add('Für Gruppen');
        } elseif (in_array($sport, array('canoeing','kayak','sailing','rowing'), true) || in_array($leisure, array('marina','slipway'), true) || preg_match('/\b(sup|stand up paddle|kanu|kajak)\b/u', $name)) {
            // Paddling/sailing only reaches this branch after the visitor-use gate.
            // Public rental/tour offers outrank mere infrastructure.
            $strong = true; $score = $visitor_offer ? 88 : 80; $bucket = 'water_outdoor';
            $add('Am Wasser'); $add('Outdoor'); $add($visitor_offer ? 'Direkt nutzbar' : 'Für Gruppen');
        } elseif ($leisure === 'water_park' || preg_match('/\b(aquapark|aqua park|erlebnisbad|freizeitbad|wellenbad)\b/u', $name)) {
            $strong = true; $score = 97; $bucket = 'water_fun';
            $add('Badespaß'); $add('Für Gruppen'); $add($outdoor ? 'Outdoor' : 'Indoor');
        } elseif ($is_bathing_lake) {
            $strong = true; $score = 88; $bucket = 'water_outdoor';
            $add('Am Wasser'); $add('Outdoor');
        } elseif (in_array($leisure, array('swimming_pool'), true) || in_array($amenity, array('public_bath','swimming_pool'), true) || $sport === 'swimming') {
            // Local completeness rule: a normal indoor/outdoor pool remains eligible.
            // It is deliberately weaker than an Erlebnisbad/Action water spot, never hidden.
            $is_special_bath = preg_match('/\b(therme|strandbad|naturbad|freibad|badesee)\b/u', $name);
            $is_explicit_outdoor_bath = $indoor === 'no' || preg_match('/\b(strandbad|naturbad|freibad|badesee)\b/u', $name);
            $strong = true;
            $score = $is_special_bath ? 76 : 58;
            $bucket = $is_special_bath || $is_explicit_outdoor_bath ? 'water_outdoor' : 'water_pool';
            $add($is_special_bath ? 'Am Wasser' : 'Schwimmen');
            $add($is_explicit_outdoor_bath ? 'Outdoor' : 'Indoor');
        } elseif ($amenity === 'sauna' && preg_match('/\b(therme|sauna|spa)\b/u', $name)) {
            $strong = true; $score = 70; $bucket = 'wellness'; $add('Wellness'); $add('Active Date'); $add('Indoor');
        } elseif ($leisure === 'ice_rink' || $sport === 'ice_skating') {
            $strong = true; $score = 89; $bucket = 'action'; $add('Action'); $add('Active Date'); $add('Für Gruppen');
        } elseif ($leisure === 'bowling_alley' || $sport === 'bowling' || $sport === 'billiards') {
            $strong = true; $score = 84; $bucket = 'group_indoor'; $add('Für Gruppen'); $add('Active Date'); $add('Indoor');
        } elseif (in_array($leisure, array('miniature_golf','disc_golf_course'), true)) {
            $strong = true; $score = 82; $bucket = 'active_date'; $add('Für Gruppen'); $add('Active Date'); $add('Outdoor');
        } elseif ($sport === 'padel') {
            $strong = true; $score = 72; $bucket = 'group_sport'; $add('Für Gruppen'); $add('Active Date');
        } elseif ($sport === 'equestrian' && !preg_match('/\b(verein|club|schule)\b/u', $name)) {
            $strong = true; $score = 68; $bucket = 'outdoor'; $add('Outdoor'); $add('Erlebnis');
        }

        $training_name = preg_match('/\b(fitness|fitnessstudio|sportstudio|gym|yoga(?:schule|studio)?|pilates|personal training|personaltraining|ems|crossfit|bodybuilding|sportschule|trainingszentrum|fitnesstraining|kampfsport|kampfkunst|karate|taekwondo|judo|boxschule)\b/u', $name);
        $generic_facility = in_array($leisure, array('fitness_centre','fitness_station','sports_hall','pitch','track','stadium'), true)
            || in_array($sport, array('fitness','yoga','pilates','gymnastics','soccer','tennis','golf'), true);
        if (!$strong && ($training_name || $generic_facility || $leisure === 'sports_centre')) return null;
        if (!$strong) return null;

        $quality = isset($row['quality_score']) ? max(0.0, min(1.0, (float) $row['quality_score'])) : 0.5;
        $score += $quality * 8.0;
        if (!empty($tags['website']) || !empty($tags['contact:website']) || !empty($row['website'])) $score += 4.0;
        if (!empty($tags['opening_hours']) || !empty($row['opening_hours'])) $score += 4.0;
        if (!empty($tags['image']) || !empty($tags['wikimedia_commons'])) $score += 2.0;
        if (in_array($fee, array('no','0','false'), true)) { $score += 4.0; $add('Kostenlos'); }

        // Notability is a secondary trust bonus only after a place has independently
        // qualified as an activity. It can no longer turn a museum/zoo/industrial POI
        // into an Activities result or overpower the experience class itself.
        if ($has_wikimedia_notability) $score *= 1.10;

        $distance = isset($row['distance_km']) ? max(0.0, (float) $row['distance_km']) : 0.0;
        $rank_score = $score - min(8.0, $distance * 0.55);
        return array(
            'score' => round($score, 2),
            'rank_score' => round($rank_score, 2),
            'bucket' => $bucket ?: 'experience',
            'labels' => array_slice($labels, 0, 4),
        );
    }
    private function rank_activity_rows($rows, $limit, $allow_highlight = false) {
        $ranked=array();
        foreach((array)$rows as $row){
            $projection=$this->activity_v2_public_projection($row);
            if(!$projection)continue;
            $row['_rg_activity_score']=$projection['score'];
            $row['_rg_activity_rank_score']=$projection['rank_score'];
            $row['_rg_activity_bucket']=$projection['bucket'];
            $row['_rg_experience_tags']=$projection['labels'];
            $row['_rg_response_subcategory']=$projection['subcategory'];
            $row['_rg_activity_v2_admission']='rein';
            $row['_rg_activity_v2_primary']=$projection['primary_experience'];
            $row['_rg_activity_environment']=$projection['environment'];
            $row['_rg_activity_multi_count']=$projection['multi_experience_count'];
            $ranked[]=$row;
        }

        // De-duplicate equivalent OSM representations before any curation.
        usort($ranked,function($a,$b){
            $sa=(float)($a['_rg_activity_rank_score']??0);$sb=(float)($b['_rg_activity_rank_score']??0);
            if(abs($sa-$sb)>0.001)return $sa>$sb?-1:1;
            $da=(float)($a['distance_km']??999);$db=(float)($b['distance_km']??999);
            if(abs($da-$db)>0.0001)return $da<$db?-1:1;
            return strcmp((string)($a['name']??''),(string)($b['name']??''));
        });
        $deduped=array();
        foreach($ranked as $row){
            $name_a=trim($this->normalize_text((string)($row['name']??'')));$duplicate=false;
            foreach($deduped as $kept){
                $name_b=trim($this->normalize_text((string)($kept['name']??'')));
                if($name_a===''||$name_b==='')continue;
                $name_match=($name_a===$name_b)||(strlen($name_a)>=6&&strlen($name_b)>=6&&(strpos($name_a,$name_b)===0||strpos($name_b,$name_a)===0));
                if(!$name_match)continue;
                $lat1=(float)($row['lat']??0);$lng1=(float)($row['lng']??0);$lat2=(float)($kept['lat']??0);$lng2=(float)($kept['lng']??0);
                $dy=($lat1-$lat2)*110.574;$dx=($lng1-$lng2)*111.320*max(0.2,cos(deg2rad(($lat1+$lat2)/2)));
                if(sqrt($dx*$dx+$dy*$dy)<=0.15){$duplicate=true;break;}
            }
            if(!$duplicate)$deduped[]=$row;
        }
        $ranked=$deduped;
        $limit=max(1,min(1500,(int)$limit));

        // Full category pages are a local catalogue: nearest first. V2 decides
        // eligibility; distance decides visible order, matching the Theme contract.
        if($limit>=1000){
            usort($ranked,function($a,$b){$da=(float)($a['distance_km']??999);$db=(float)($b['distance_km']??999);if(abs($da-$db)>0.0001)return $da<$db?-1:1;return strcmp((string)($a['name']??''),(string)($b['name']??''));});
            return array_slice($ranked,0,$limit);
        }

        // Home/discovery receives a diversified REIN-only candidate pool. The
        // Theme still performs the final six-card distance/quality selection.
        $target=min(36,count($ranked),$limit);if($target<=0)return array();
        $picked=array();$picked_ids=array();$bucket_counts=array();$water_count=0;
        $is_water=function($bucket){return strpos((string)$bucket,'water_')===0||$bucket==='wellness';};
        $id_key=function($row,$idx){return !empty($row['id'])?'id:'.$row['id']:'idx:'.$idx;};
        $take=function($row,$idx)use(&$picked,&$picked_ids,&$bucket_counts,&$water_count,$is_water,$id_key,$target){
            if(count($picked)>=$target)return false;$key=$id_key($row,$idx);if(isset($picked_ids[$key]))return false;
            $bucket=(string)($row['_rg_activity_bucket']??'experience');if($is_water($bucket)&&$water_count>=7)return false;
            $picked[]=$row;$picked_ids[$key]=true;$bucket_counts[$bucket]=(int)($bucket_counts[$bucket]??0)+1;if($is_water($bucket))$water_count++;return true;
        };
        foreach($ranked as $idx=>$row){$bucket=(string)($row['_rg_activity_bucket']??'experience');if(!empty($bucket_counts[$bucket]))continue;$take($row,$idx);}
        $nearest=$ranked;usort($nearest,function($a,$b){$da=(float)($a['distance_km']??999);$db=(float)($b['distance_km']??999);if(abs($da-$db)>0.0001)return $da<$db?-1:1;return strcmp((string)($a['name']??''),(string)($b['name']??''));});
        $nearest_bucket_seen=array();foreach($nearest as $idx=>$row){$bucket=(string)($row['_rg_activity_bucket']??'experience');if(isset($nearest_bucket_seen[$bucket]))continue;$nearest_bucket_seen[$bucket]=true;$take($row,'n'.$idx);}
        foreach($ranked as $idx=>$row){if(count($picked)>=$target)break;$bucket=(string)($row['_rg_activity_bucket']??'experience');if((int)($bucket_counts[$bucket]??0)>=3)continue;$take($row,$idx);}
        foreach($ranked as $idx=>$row){if(count($picked)>=$target)break;$key=$id_key($row,$idx);if(isset($picked_ids[$key]))continue;$picked[]=$row;$picked_ids[$key]=true;}
        return $picked;
    }
    private function nearby_activity_experience_rows($lat, $lng, $radius_km, $limit) {
        global $wpdb;
        $places = $this->table('places');
        $limit = max(1, min(1500, (int) $limit));
        $radius_km = max(0.5, min(50.0, (float) $radius_km));
        $lat_delta = $radius_km / 110.574;
        $cos = max(0.2, cos(deg2rad($lat)));
        $lng_delta = $radius_km / (111.320 * $cos);
        $min_lat = $lat - $lat_delta; $max_lat = $lat + $lat_delta;
        $min_lng = $lng - $lng_delta; $max_lng = $lng + $lng_delta;
        $distance = "(6371.0088 * 2 * ASIN(SQRT(POWER(SIN(RADIANS(p.lat - %f)/2),2) + COS(RADIANS(%f)) * COS(RADIANS(p.lat)) * POWER(SIN(RADIANS(p.lng - %f)/2),2))))";
        $distance_sql = $wpdb->prepare($distance, $lat, $lat, $lng);
        $read_filter_sql = $this->activity_v2_public_read_filter_sql('p');
        $priority_sql = $this->activity_priority_sql('p');
        // Activities are now category-pure at read time. Existing stale rows that
        // were once classified as zoo/industrial are rejected by the leakage gate;
        // Highlights can still discover them through Highlight Intelligence.
        $sql = $wpdb->prepare(
            "SELECT p.*, p.primary_subcategory AS subcategory, 1.0 AS weight,
                    $priority_sql AS experience_db_priority,
                    $distance_sql AS distance_km
             FROM $places p
             WHERE p.active=1
               AND p.lifecycle_status='active'
               AND p.primary_category='activities'
               AND p.lat BETWEEN %f AND %f
               AND p.lng BETWEEN %f AND %f
               $read_filter_sql
             HAVING distance_km <= %f
             ORDER BY experience_db_priority DESC, distance_km ASC, p.quality_score DESC, p.id ASC
             LIMIT 8000",
            $min_lat, $max_lat, $min_lng, $max_lng, $radius_km
        );
        return $this->rank_activity_rows((array) $wpdb->get_results($sql, ARRAY_A), $limit, false);
    }




