    private function industrial_route_type_label($type) {
        if ($type === 'anchor') return 'Ankerpunkt';
        if ($type === 'panorama') return 'Panorama';
        if ($type === 'settlement') return 'Siedlung';
        return 'Primärstandort';
    }

    private function industrial_route_source_url($type = '', $slug = '') {
        $base = 'https://www.route-industriekultur.ruhr/';
        if ($type === 'anchor') $base .= 'ankerpunkte/';
        elseif ($type === 'panorama') $base .= 'panoramen/';
        elseif ($type === 'settlement') $base .= 'siedlungen/';
        if ($slug !== '') return $base . sanitize_title($slug) . '/';
        return $base;
    }

