    private function industrial_route_name_score($row, $item) {
        $row_name = $this->normalize_text((string) ($row['name'] ?? ''));
        if ($row_name === '') $row_name = $this->normalize_text((string) ($row['normalized_name'] ?? ''));
        if ($row_name === '') return 0;

        // V1.2.1: a municipality itself must never become a Route-Industriekultur
        // destination. The Route is made of concrete sites (anchor points,
        // panoramas and settlements), never city/town administrative objects.
        $row_tags = json_decode((string) ($row['raw_tags'] ?? ''), true);
        if (!is_array($row_tags)) $row_tags = array();
        $place_type = strtolower((string) ($row_tags['place'] ?? ''));
        $boundary_type = strtolower((string) ($row_tags['boundary'] ?? ''));
        if (in_array($place_type, array('city','town','village','municipality'), true) || $boundary_type === 'administrative') return 0;
        $row_city_name = $this->normalize_text((string) ($row['city'] ?? ''));
        if ($row_city_name !== '' && $row_name === $row_city_name) return 0;
        $municipality_name = $this->normalize_text(str_replace('-', ' ', (string) ($row['municipality_slug'] ?? '')));
        if ($municipality_name !== '' && $row_name === $municipality_name) return 0;

        // V1.8.9: imported POIs can carry a district/borough in municipality_slug
        // (e.g. a Duisburg district) while `city` still correctly says Duisburg.
        // Accept the route city when EITHER city field resolves to it. Previously
        // municipality_slug won unconditionally and valid RDI sites became unmatched.
        $row_municipality_slug = sanitize_title((string) ($row['municipality_slug'] ?? ''));
        $row_city_slug = sanitize_title((string) ($row['city'] ?? ''));
        $target_city_slug = sanitize_title((string) ($item['city'] ?? ''));
        if ($target_city_slug !== '') {
            $municipality_matches = ($row_municipality_slug === $target_city_slug)
                || ($row_municipality_slug !== '' && strpos($row_municipality_slug, $target_city_slug . '-') === 0);
            $city_matches = ($row_city_slug === $target_city_slug);
            if (($row_municipality_slug !== '' || $row_city_slug !== '') && !$municipality_matches && !$city_matches) return 0;
        }
        $best = 0;
        foreach ((array) ($item['aliases'] ?? array($item['title'])) as $alias) {
            $a = $this->normalize_text($alias);
            if ($a === '') continue;
            if ($row_name === $a) $best = max($best, 130);
            elseif (strlen($a) >= 6 && (strpos($row_name, $a) !== false || strpos($a, $row_name) !== false)) $best = max($best, 108);
            else {
                $tokens = array_values(array_filter(explode(' ', $a), function($v) { return strlen($v) >= 4; }));
                if ($tokens) {
                    $hits = 0;
                    foreach ($tokens as $token) if (strpos(' ' . $row_name . ' ', ' ' . $token . ' ') !== false) $hits++;
                    if (($hits / count($tokens)) >= 0.8) $best = max($best, 88);
                }
            }
        }
        if ($best > 0) {
            if (!empty($row['wikidata'])) $best += 4;
            if (!empty($row['wikipedia'])) $best += 4;
            if (!empty($row['website'])) $best += 2;
            $best += min(3, max(0, (float) ($row['quality_score'] ?? 0.5) * 3));
        }
        return $best;
    }

    private function industrial_route_match_for_row($row) {
        static $cache = array();
        $key = !empty($row['id']) ? 'id:' . (int)$row['id'] : 'n:' . sanitize_title((string)($row['municipality_slug'] ?? $row['city'] ?? '')) . ':' . $this->normalize_text((string)($row['name'] ?? ''));
        if (array_key_exists($key, $cache)) return $cache[$key];
        $best = null; $best_score = 0;
        foreach ($this->industrial_route_manifest() as $item) {
            $score = $this->industrial_route_name_score($row, $item);
            if ($score > $best_score) { $best_score = $score; $best = $item; }
        }
        if ($best_score < 86) $best = null;
        if ($best) {
            $best['matchScore'] = round($best_score, 2);
            $best['typeLabel'] = $this->industrial_route_type_label($best['type']);
            $best['officialUrl'] = $this->industrial_route_source_url($best['type'], $best['slug']);
        }
        $cache[$key] = $best;
        return $best;
    }

    private function industrial_route_dataset() {
        $catalog = preg_replace('/[^a-zA-Z0-9_.-]/', '_', (string) get_option(self::OPTION_CATALOG_VERSION, 'bootstrap'));
        // v5 adds canonical coordinates/OSM identities for the handful of RDI
        // primary sites whose imported OSM representation is structurally unusual.
        $transient_key = 'rg_route57_v7_' . substr(sha1($catalog), 0, 12);
        $cached = get_transient($transient_key);
        if (is_array($cached) && count($cached) === 57) return $cached;
        global $wpdb;
        $places = $this->table('places');

        $manifest = array();
        foreach ($this->industrial_route_manifest() as $base_item) {
            $manifest[] = array_merge($base_item, $this->industrial_route_fallback_meta((string)$base_item['slug']));
        }

        $city_slugs = array();
        foreach ($manifest as $item) $city_slugs[] = sanitize_title($item['city']);
        $city_slugs = array_values(array_unique($city_slugs));
        $quoted = array_map(function($v) { return "'" . esc_sql($v) . "'"; }, $city_slugs);
        $city_names = array_values(array_unique(array_map(function($item) { return (string)($item['city'] ?? ''); }, $manifest)));
        $quoted_cities = array_map(function($v) { return "'" . esc_sql($v) . "'"; }, $city_names);

        $where_parts = array();
        if ($quoted) {
            $where_parts[] = 'municipality_slug IN (' . implode(',', $quoted) . ')';
            $prefix_parts = array_map(function($v) { return "municipality_slug LIKE '" . esc_sql($v) . "-%'"; }, $city_slugs);
            if ($prefix_parts) $where_parts[] = '(' . implode(' OR ', $prefix_parts) . ')';
        }
        if ($quoted_cities) $where_parts[] = 'city IN (' . implode(',', $quoted_cities) . ')';

        // Exact OSM identities bypass broken/missing city metadata.
        $osm_by_type = array('n'=>array(),'w'=>array(),'r'=>array());
        foreach ($manifest as $item) {
            foreach ((array)($item['osmIds'] ?? array()) as $identity) {
                if (!preg_match('/^([nwr]):(\d+)$/', (string)$identity, $m)) continue;
                $osm_by_type[$m[1]][] = (int)$m[2];
            }
        }
        foreach ($osm_by_type as $type=>$ids) {
            $ids = array_values(array_unique(array_filter(array_map('intval',$ids))));
            if ($ids) $where_parts[] = "(primary_osm_type='" . esc_sql($type) . "' AND primary_osm_id IN (" . implode(',',$ids) . "))";
        }

        $where = $where_parts ? ' AND (' . implode(' OR ', $where_parts) . ')' : '';
        $candidates = (array) $wpdb->get_results(
            "SELECT id,name,normalized_name,municipality_slug,city,lat,lng,website,wikidata,wikipedia,primary_osm_type,primary_osm_id,primary_category,primary_subcategory,quality_score,raw_tags
             FROM $places WHERE active=1 $where", ARRAY_A
        );

        $by_osm = array();
        foreach ($candidates as $row) {
            $otype = (string)($row['primary_osm_type'] ?? '');
            $oid = (int)($row['primary_osm_id'] ?? 0);
            if ($otype && $oid) $by_osm[$otype . ':' . $oid][] = $row;
        }

        $used = array(); $matched_ids = array(); $matches = array();
        foreach ($manifest as $item) {
            $best = null; $best_score = 0;

            // 1) Exact OSM identity is authoritative for the finite 57-site list.
            foreach ((array)($item['osmIds'] ?? array()) as $identity) {
                foreach ((array)($by_osm[(string)$identity] ?? array()) as $row) {
                    $id = (int)($row['id'] ?? 0);
                    if (!$id || isset($used[$id])) continue;
                    $best = $row; $best_score = 500; break 2;
                }
            }

            // 2) Normal title/city intelligence for the rest of the official list.
            if (!$best) {
                foreach ($candidates as $row) {
                    $id = (int)($row['id'] ?? 0);
                    if (!$id || isset($used[$id])) continue;
                    $score = $this->industrial_route_name_score($row, $item);
                    if ($score > $best_score) { $best_score = $score; $best = $row; }
                }
            }

            if ($best && $best_score >= 86) {
                $id = (int)$best['id']; $used[$id] = true; $matched_ids[] = $id;
                $matches[$item['slug']] = array('id'=>$id,'matchScore'=>round($best_score,2));
            }
        }

        $full = array();
        if ($matched_ids) {
            $ids = implode(',', array_map('intval', array_values(array_unique($matched_ids))));
            foreach ((array)$wpdb->get_results("SELECT p.*,p.primary_subcategory AS subcategory FROM $places p WHERE p.id IN ($ids)", ARRAY_A) as $row) {
                $full[(int)$row['id']] = $row;
            }
        }

        $dataset = array();
        foreach ($manifest as $item) {
            $entry = $item;
            $entry['typeLabel'] = $this->industrial_route_type_label($item['type']);
            $entry['officialUrl'] = $this->industrial_route_source_url($item['type'], $item['slug']);
            $entry['matched'] = false; $entry['matchScore'] = 0; $entry['row'] = null;
            if (isset($matches[$item['slug']]) && isset($full[$matches[$item['slug']]['id']])) {
                $entry['matched'] = true;
                $entry['matchScore'] = $matches[$item['slug']]['matchScore'];
                $entry['row'] = $full[$matches[$item['slug']]['id']];
            }
            $dataset[] = $entry;
        }
        set_transient($transient_key, $dataset, 6 * HOUR_IN_SECONDS);
        return $dataset;
    }

    private function industrial_route_distance_km($lat1, $lng1, $lat2, $lng2) {
        if (!$this->valid_coordinate($lat1, $lng1) || !$this->valid_coordinate($lat2, $lng2)) return null;
        return $this->distance_m($lat1, $lng1, $lat2, $lng2) / 1000.0;
    }

    public function rest_industrial_route(WP_REST_Request $request) {
        if ($this->runtime_mode() !== 'database') return new WP_REST_Response(array('ok'=>false,'error'=>'places-db-not-ready','mode'=>'osm'), 503);
        $lat = (float) $request->get_param('lat'); $lng = (float) $request->get_param('lng');
        $has_location = $this->valid_coordinate($lat, $lng);
        $items = array(); $matched_count = 0;
        foreach ($this->industrial_route_dataset() as $entry) {
            $out = array('index'=>(int)$entry['index'],'slug'=>$entry['slug'],'title'=>$entry['title'],'city'=>$entry['city'],
                'type'=>$entry['type'],'typeLabel'=>$entry['typeLabel'],'officialUrl'=>$entry['officialUrl'],
                'matched'=>(bool)$entry['matched'],'matchScore'=>(float)$entry['matchScore'],'placeId'=>null,'distanceKm'=>null,'element'=>null,
                'fallbackLat'=>isset($entry['fallbackLat'])?(float)$entry['fallbackLat']:null,
                'fallbackLng'=>isset($entry['fallbackLng'])?(float)$entry['fallbackLng']:null,
                'fallbackImage'=>(string)($entry['fallbackImage'] ?? ''),
                'fallbackCredit'=>(string)($entry['fallbackCredit'] ?? ''),
                'fallbackLicense'=>(string)($entry['fallbackLicense'] ?? ''),
                'forceFallbackImage'=>!empty($entry['forceFallbackImage']));
            if (!empty($entry['row']) && is_array($entry['row'])) {
                $row = $entry['row'];
                $row['_rg_industrial_route_slug']=$entry['slug'];
                $row['_rg_industrial_route_type']=$entry['type'];
                $row['_rg_industrial_route_title']=$entry['title'];
                $row['_rg_highlight_tier']='A';
                $els=$this->rows_to_elements(array($row));
                $out['element']=$els?$els[0]:null; $out['placeId']=(int)$row['id'];
                if ($has_location) $out['distanceKm']=round($this->industrial_route_distance_km($lat,$lng,(float)$row['lat'],(float)$row['lng']),4);
                $matched_count++;
            }
            if ($has_location && !is_numeric($out['distanceKm']) && $out['fallbackLat'] !== null && $out['fallbackLng'] !== null) {
                $fallback_distance = $this->industrial_route_distance_km($lat,$lng,(float)$out['fallbackLat'],(float)$out['fallbackLng']);
                if ($fallback_distance !== null) $out['distanceKm']=round($fallback_distance,4);
            }
            $items[]=$out;
        }
        if ($has_location) usort($items,function($a,$b){
            $ad=is_numeric($a['distanceKm'])?(float)$a['distanceKm']:INF; $bd=is_numeric($b['distanceKm'])?(float)$b['distanceKm']:INF;
            if ($ad!==$bd) return $ad<$bd?-1:1; return strcmp((string)$a['title'],(string)$b['title']);
        });
        return rest_ensure_response(array('ok'=>true,'version'=>'route57-v7','officialCount'=>57,'matchedCount'=>$matched_count,
            'source'=>'Regionalverband Ruhr · Route Industriekultur / Entdeckerpass 2026','items'=>$items,
            'catalogVersion'=>(string)get_option(self::OPTION_CATALOG_VERSION,'bootstrap')));
    }

    private function highlight_ensemble_key($row, $route_match = null) {
        if ($route_match && !empty($route_match['slug'])) return 'route:' . $route_match['slug'];
        $name = $this->normalize_text((string)($row['name'] ?? ''));
        if ($name === '') return 'id:' . (string)($row['id'] ?? uniqid());
        // Component/status suffixes describe the OSM object, not a separate visitor destination.
        // Keep the semantic site stem here; spatial separation is handled in rank_highlight_rows().
        $base = preg_replace('/\([^)]*\b(stillgelegt|geschlossen|verfuellt|verfullt|abgebrochen)\b[^)]*\)/u', '', $name);
        $base = preg_replace('/\b(schacht|shaft|foerdergeruest|fordergerust|foerderturm|forderturm|mineshaft)\s*(?:nr\s*)?(?:\d+(?:\s*[\/\-]\s*\d+)*|[ivx]+)\b/u', '', $base);
        $base = preg_replace('/\b(schacht|shaft)\b.*$/u', '', $base);
        $base = preg_replace('/^(?:zeche|bergwerk)\s+/u', '', $base);
        $base = preg_replace('/\s+\d+$/u', '', $base);
        $base = trim(preg_replace('/\s+/', ' ', $base));
        if (strlen($base) >= 5) return 'site:' . sanitize_title($base);
        return 'id:' . (string)($row['id'] ?? $name);
    }

    private function highlight_same_site_cluster_key($row, $route_match, &$clusters) {
        $base_key=$this->highlight_ensemble_key($row,$route_match);
        if(strpos($base_key,'route:')===0 || strpos($base_key,'id:')===0)return $base_key;
        $lat=(float)($row['lat']??0);$lng=(float)($row['lng']??0);
        if(!$this->valid_coordinate($lat,$lng))return $base_key.':id:'.(string)($row['id']??'0');
        if(!isset($clusters[$base_key]))$clusters[$base_key]=array();
        foreach($clusters[$base_key] as $cluster){
            $distance=$this->industrial_route_distance_km($lat,$lng,(float)$cluster['lat'],(float)$cluster['lng']);
            if($distance!==null && $distance<=0.25)return $cluster['key'];
        }
        $key=$base_key.':cluster:'.(count($clusters[$base_key])+1);
        $clusters[$base_key][]=array('key'=>$key,'lat'=>$lat,'lng'=>$lng);
        return $key;
    }

    /**
     * City Highlight Intelligence V2.
     *
     * Highlights are "places worth a detour", not a raw tourism directory.
     * The persistent catalogue stays broad; read-time intelligence suppresses
     * generic memorials/parks/museums and ranks visual, Ruhr-specific and
     * experience-rich destinations. Cross-category candidates are allowed only
     * when their OSM evidence independently qualifies them as a Highlight.
     */
    private function highlight_experience_profile($row) {
        $tags=json_decode((string)($row['raw_tags']??''),true); if(!is_array($tags))$tags=array();
        $name=$this->normalize_text((string)($row['name']??'')); $tourism=strtolower((string)($tags['tourism']??''));
        $historic=strtolower((string)($tags['historic']??'')); $man_made=strtolower((string)($tags['man_made']??''));
        $leisure=strtolower((string)($tags['leisure']??'')); $amenity=strtolower((string)($tags['amenity']??''));
        $building=strtolower((string)($tags['building']??'')); $artwork_type=strtolower((string)($tags['artwork_type']??''));
        $office=strtolower((string)($tags['office']??'')); $shop=strtolower((string)($tags['shop']??''));
        $access=strtolower((string)($tags['access']??'')); $fee=strtolower((string)($tags['fee']??''));
        $heritage=trim((string)($tags['heritage']??'')); $primary_category=strtolower((string)($row['primary_category']??'highlights'));
        if(in_array($access,array('private','no','members'),true))return null;
        $has_website=!empty($tags['website'])||!empty($tags['contact:website'])||!empty($row['website']);
        $has_hours=!empty($tags['opening_hours'])||!empty($row['opening_hours']);
        $has_wikidata=!empty($tags['wikidata'])||!empty($row['wikidata']);
        $has_wikipedia=!empty($tags['wikipedia'])||!empty($row['wikipedia']);
        $has_image=!empty($tags['image'])||!empty($tags['image:url'])||!empty($tags['wikimedia_commons']);
        $has_heritage=$heritage!==''||!empty($tags['heritage:operator'])||!empty($tags['ref:whc']);
        $route_match=$this->industrial_route_match_for_row($row);

        // A protected/historic building is not automatically a visitor Highlight.
        // Current primary uses such as hotel, care/health facility, school or plain
        // office remain out unless the object has an explicit attraction signal or
        // is one of the authoritative Route Industriekultur sites.
        $accommodation=in_array($tourism,array('hotel','hostel','guest_house','motel','apartment','chalet'),true);
        $service_use=in_array($amenity,array(
            'social_facility','nursing_home','hospital','clinic','doctors','dentist',
            'school','kindergarten','college','university','childcare'
        ),true);
        $plain_office=($office!=='' && !in_array($tourism,array('attraction','museum','gallery'),true));
        $plain_shop=($shop!=='' && $tourism!=='attraction');
        $non_destination_name=(bool)preg_match('/\b(hotel|senioren(?:haus|heim)|pflegeheim|gesundheitshaus|rechenzentrum|schule|kindergarten)\b/u',$name);
        if(!$route_match && $tourism!=='attraction' && ($accommodation||$service_use||$plain_office||$plain_shop||$non_destination_name))return null;

        $industrial=in_array($historic,array('mine','industrial'),true)||in_array($man_made,array('headframe','mineshaft','adit','works','chimney'),true)
            ||preg_match('/\b(zeche|kokerei|hochofen|huttenwerk|huettenwerk|forderturm|foerderturm|fordergerust|foerdergeruest|industrieanlage|maschinenhalle)\b/u',$name);
        $component=in_array($man_made,array('mineshaft','adit','headframe'),true)
            ||preg_match('/\b(schacht|foerdergeruest|fordergerust|foerderturm|forderturm)\s*(?:nr\s*)?(?:\d+(?:\s*[\/\-]\s*\d+)*|[ivx]+)\b/u',$name);
        $viewpoint=$tourism==='viewpoint'||$man_made==='spoil_heap';
        $castle=in_array($historic,array('castle','manor','ruins','fort','fortification','city_gate','archaeological_site'),true)||$building==='castle';
        $landmark_structure=in_array($man_made,array('spoil_heap'),true)||(in_array($man_made,array('tower','water_tower','lighthouse','windmill','headframe'),true)&&($tourism==='attraction'||$has_wikidata||$has_wikipedia||$has_heritage));
        $urban_art=($tourism==='artwork'&&($artwork_type==='mural'||in_array($artwork_type,array('sculpture','installation'),true)))||preg_match('/\b(streetart|street art|graffiti|urban art|kreativquartier|kreativ quartier|kunstquartier)\b/u',$name);
        $significant_nature=in_array($leisure,array('park','garden','nature_reserve'),true)&&($tourism==='attraction'||$has_wikidata||$has_wikipedia||$has_heritage);
        $generic_memorial=in_array($historic,array('memorial','monument'),true)||$tourism==='memorial'||preg_match('/\b(stolperstein|gedenkstein|kriegerdenkmal|ehrenmal)\b/u',$name);
        $generic_museum=$tourism==='museum'||$building==='museum';
        $religious=$amenity==='place_of_worship'||in_array($building,array('church','cathedral','chapel','mosque','synagogue'),true);
        $major_family=in_array($tourism,array('zoo','theme_park'),true)||in_array($leisure,array('animal_park','amusement_park'),true);
        if($route_match){
            $labels=array('Route Industriekultur',$route_match['typeLabel']);
            $labels[]=$route_match['type']==='panorama'?'Aussicht':($route_match['type']==='settlement'?'Geschichte':'Industriekultur');
            return array('score'=>100.0,'rank_score'=>100.0,'tier'=>'A',
                'bucket'=>$route_match['type']==='panorama'?'viewpoint_sunset':($route_match['type']==='settlement'?'heritage_vibe':'industrial_icon'),
                'labels'=>array_slice(array_values(array_unique($labels)),0,4),'subcategory'=>'Route Industriekultur · '.$route_match['typeLabel'],'route'=>$route_match);
        }
        if($major_family){
            $labels=array();
            if(in_array($tourism,array('zoo'),true)||$leisure==='animal_park'){$labels[]='Zoo & Tiere';$bucket='family_icon';$subcategory='Zoos & Tierparks';}
            else{$labels[]='Freizeitpark';$bucket='family_icon';$subcategory='Freizeitparks & Attraktionen';}
            if($has_wikidata||$has_wikipedia)$labels[]='Bekannter Ort';
            $labels[]='Ausflugsziel';
            $base=($has_wikidata||$has_wikipedia)?88.0:78.0;
            if($has_website)$base+=3.0;if($has_hours)$base+=2.0;if($has_image)$base+=2.0;
            return array('score'=>min(98.0,$base),'rank_score'=>min(98.0,$base),'tier'=>$base>=84?'A':'B','bucket'=>$bucket,'labels'=>array_slice(array_values(array_unique($labels)),0,4),'subcategory'=>$subcategory,'route'=>null);
        }
        if($component&&!$has_wikipedia&&!$has_wikidata&&$tourism!=='attraction')return null;
        if($generic_memorial&&!$has_wikipedia&&!$has_wikidata&&!$has_heritage)return null;
        if($religious&&!($tourism==='attraction'&&($has_wikidata||$has_wikipedia)&&$has_heritage))return null;
        if($generic_museum&&$tourism!=='attraction'&&!$has_wikipedia&&!$has_wikidata)return null;
        if(in_array($leisure,array('park','garden','nature_reserve'),true)&&!$significant_nature&&!$viewpoint)return null;
        if($tourism==='artwork'&&!$urban_art&&!$has_wikidata&&!$has_wikipedia)return null;
        $authority=0;
        if(!empty($tags['ref:whc']))$authority=35;
        elseif($tourism==='attraction'&&$has_wikidata&&$has_wikipedia)$authority=34;
        elseif($tourism==='attraction'&&($has_wikidata||$has_wikipedia))$authority=30;
        elseif($has_heritage&&$has_wikidata&&$has_wikipedia)$authority=28;
        elseif($viewpoint&&($has_wikidata||$has_wikipedia))$authority=27;
        elseif(($castle||$industrial||$landmark_structure||$urban_art)&&($has_wikidata||$has_wikipedia))$authority=25;
        elseif($has_heritage&&($has_wikidata||$has_wikipedia))$authority=23;
        else return null;
        $city_importance=min(25,($tourism==='attraction'?10:0)+($has_wikipedia?7:0)+($has_wikidata?5:0)+($has_heritage?3:0));
        $public_prominence=min(15,($has_wikipedia?8:0)+($has_wikidata?5:0)+($has_image?2:0));
        $experience=10; $bucket='heritage_vibe'; $subcategory='Highlights & Ausflugsziele'; $labels=array();
        $add=function($label)use(&$labels){if($label&&!in_array($label,$labels,true))$labels[]=$label;};
        if($industrial){$experience=15;$bucket='industrial_icon';$subcategory='Industriekultur & Landmarken';$add('Industriekultur');$add('Ruhrpott Vibes');}
        elseif($viewpoint){$experience=15;$bucket='viewpoint_sunset';$subcategory='Aussicht & Landmarken';$add('Aussicht');$add('Sunset');$add('Outdoor');}
        elseif($urban_art){$experience=14;$bucket='urban_art';$subcategory='Urban Art & Architektur';$add('Urban Art');$add('Architektur');}
        elseif($landmark_structure){$experience=14;$bucket='visual_landmark';$subcategory='Landmarken & Architektur';$add('Architektur');$add('Fotospot');}
        elseif($castle){$experience=13;$bucket='heritage_vibe';$subcategory='Schloss, Burg & Geschichte';$add('Geschichte');$add('Besonderer Ort');}
        elseif($significant_nature){$experience=11;$bucket='hidden_hotspot';$subcategory='Besondere Parks & Natur';$add('Outdoor');$add('Natur');}
        else $add('Besonderer Ort');
        $visitability=min(10,($has_website?3:0)+($has_hours?2:0)+((!empty($row['city'])||!empty($row['municipality_slug']))?2:0)+(!empty($row['street'])?1:0)+(($access===''||in_array($access,array('yes','permissive','public'),true))?2:0));
        $visual=min(5,($has_image?3:0)+(($has_wikidata||$has_wikipedia)?2:0));
        if($has_image||$viewpoint||$urban_art||$landmark_structure)$add('Fotospot');
        if(in_array($fee,array('no','0','false'),true))$add('Kostenlos');
        if(in_array($primary_category,array('culture','activities'),true))$add($primary_category==='culture'?'Kultur & Erlebnis':'Mehr erleben');
        $score=min(99.0,$authority+$city_importance+$public_prominence+$experience+$visitability+$visual);
        $tier=$score>=78?'A':'B'; if($tier==='B'&&$score<64)return null;
        return array('score'=>round($score,2),'rank_score'=>round($score,2),'tier'=>$tier,'bucket'=>$bucket,'labels'=>array_slice($labels,0,4),'subcategory'=>$subcategory,'route'=>null);
    }

    private function rank_highlight_rows($rows,$limit){
        $best_by_ensemble=array();$site_clusters=array();
        foreach((array)$rows as $row){
            $profile=$this->highlight_experience_profile($row); if(!$profile)continue;
            $route=!empty($profile['route'])?$profile['route']:null;
            $row['_rg_highlight_score']=$profile['score'];$row['_rg_highlight_rank_score']=$profile['rank_score'];$row['_rg_highlight_tier']=$profile['tier'];
            $row['_rg_highlight_bucket']=$profile['bucket'];$row['_rg_highlight_tags']=$profile['labels'];$row['_rg_response_category']='highlights';$row['subcategory']=$profile['subcategory'];
            if($route){$row['_rg_industrial_route_slug']=$route['slug'];$row['_rg_industrial_route_type']=$route['type'];$row['_rg_industrial_route_title']=$route['title'];$row['_rg_industrial_route_match_score']=(float)($route['matchScore']??0);}
            $key=$this->highlight_same_site_cluster_key($row,$route,$site_clusters);
            if(!isset($best_by_ensemble[$key])){$best_by_ensemble[$key]=$row;continue;}
            $prev=$best_by_ensemble[$key];$tr=array('A'=>2,'B'=>1);$cr=$tr[$row['_rg_highlight_tier']]??0;$pr=$tr[$prev['_rg_highlight_tier']]??0;
            // 1.10.157: all authoritative Route rows intentionally share tier A / score 100.
            // Inside one route ensemble the route matcher therefore has to decide which OSM
            // object is the canonical visitor destination BEFORE distance is considered.
            // Otherwise a nearby component containing a broad alias (e.g. "Zollverein")
            // can replace the exact Primärstandort solely because it is a few metres closer.
            $route_current=(float)($row['_rg_industrial_route_match_score']??0);$route_previous=(float)($prev['_rg_industrial_route_match_score']??0);
            if($cr!==$pr)$replace=$cr>$pr;
            elseif((float)$row['_rg_highlight_score']!==(float)$prev['_rg_highlight_score'])$replace=(float)$row['_rg_highlight_score']>(float)$prev['_rg_highlight_score'];
            elseif(strpos($key,'route:')===0 && abs($route_current-$route_previous)>0.0001)$replace=$route_current>$route_previous;
            else $replace=(float)($row['distance_km']??INF)<(float)($prev['distance_km']??INF);
            if($replace)$best_by_ensemble[$key]=$row;
        }
        $ranked=array_values($best_by_ensemble);
        usort($ranked,function($a,$b){$da=(float)($a['distance_km']??INF);$db=(float)($b['distance_km']??INF);if(abs($da-$db)>0.0001)return $da<$db?-1:1;$ta=($a['_rg_highlight_tier']??'B')==='A'?2:1;$tb=($b['_rg_highlight_tier']??'B')==='A'?2:1;if($ta!==$tb)return $ta>$tb?-1:1;return strcmp((string)($a['name']??''),(string)($b['name']??''));});
        return array_slice($ranked,0,max(1,min(1500,(int)$limit)));
    }

    private function nearby_highlight_experience_rows($lat, $lng, $radius_km, $limit) {
        global $wpdb;
        $places = $this->table('places');
        $limit = max(1, min(1500, (int) $limit));
        $radius_km = max(0.5, min(50.0, (float) $radius_km));
        $lat_delta = $radius_km / 110.574;
        $cos = max(0.2, cos(deg2rad($lat)));
        $lng_delta = $radius_km / (111.320 * $cos);
        $min_lat = $lat - $lat_delta; $max_lat = $lat + $lat_delta;
        $min_lng = $lng - $lng_delta; $max_lng = $lng + $lng_delta;
        $distance = "(6371.0088 * 2 * ASIN(SQRT(POWER(SIN(RADIANS(p.lat - %f)/2),2) + COS(RADIANS(%f)) * COS(RADIANS(p.lat)) * POWER(SIN(RADIANS(p.lng - %f)/2),2))))";
        $distance_sql = $wpdb->prepare($distance, $lat, $lat, $lng);
        // Highlights can originate in Culture/Activities only if the raw OSM
        // evidence independently passes Highlight Experience Intelligence.
        $sql = $wpdb->prepare(
            "SELECT p.*, p.primary_subcategory AS subcategory, 1.0 AS weight, $distance_sql AS distance_km
             FROM $places p
             WHERE p.active=1
               AND p.lifecycle_status='active'
               AND p.primary_category IN ('highlights','culture','activities')
               AND p.lat BETWEEN %f AND %f
               AND p.lng BETWEEN %f AND %f
             HAVING distance_km <= %f
             ORDER BY distance_km ASC, p.quality_score DESC, p.id ASC
             LIMIT 1500",
            $min_lat, $max_lat, $min_lng, $max_lng, $radius_km
        );
        return $this->rank_highlight_rows((array) $wpdb->get_results($sql, ARRAY_A), $limit);
    }


    /**
     * Places 1.10.80: Culture Visitor Intelligence.
     *
     * OSM amenity=community_centre and amenity=events_venue are intentionally
     * broad tags. They also describe sports clubhouses, parish rooms, youth
     * facilities and rentable halls. Those records stay available in the raw
     * catalogue, but the public Culture feed only exposes them when an
     * independent cultural signal exists. Canonical visitor-facing culture
     * types (museum, theatre, cinema, gallery, arts centre, library, etc.)
     * remain eligible without a notability requirement.
     */
    private function culture_experience_profile($row) {
        if (!is_array($row)) return null;
        $tags=json_decode((string)($row['raw_tags']??''),true); if(!is_array($tags))$tags=array();
        if (!empty($row['lifecycle_status']) && (string)$row['lifecycle_status']!=='active') return null;
        if (array_key_exists('active',$row) && empty($row['active'])) return null;
        if ($this->is_inactive_tags($tags) || $this->is_stolperstein_row($row)) return null;

        $name=$this->normalize_text((string)($row['name']??''));
        $amenity=strtolower((string)($tags['amenity']??''));
        $tourism=strtolower((string)($tags['tourism']??''));
        $building=strtolower((string)($tags['building']??''));
        $leisure=strtolower((string)($tags['leisure']??''));
        $artwork=strtolower((string)($tags['artwork_type']??''));
        $access=strtolower((string)($tags['access']??''));
        $office=strtolower((string)($tags['office']??''));
        $sport=strtolower((string)($tags['sport']??''));
        if(in_array($access,array('private','no','members'),true)) return null;

        $labels=array();$score=0.0;$bucket='culture';$subcategory='Kultur & Szene';
        $add=function($label)use(&$labels){if($label!==''&&!in_array($label,$labels,true))$labels[]=$label;};

        if($tourism==='museum'||$building==='museum'){
            $score=96;$bucket='museum';$subcategory='Museum & Ausstellung';$add('Museum');
        }elseif($amenity==='theatre'||$building==='theatre'){
            $score=95;$bucket='stage';$subcategory='Theater & Bühne';$add('Theater');
        }elseif($amenity==='cinema'){
            $score=92;$bucket='cinema';$subcategory='Kino & Film';$add('Kino');
        }elseif($amenity==='planetarium'){
            $score=94;$bucket='museum';$subcategory='Museum & Wissen';$add('Planetarium');
        }elseif($tourism==='gallery'){
            $score=89;$bucket='gallery';$subcategory='Galerie & Ausstellung';$add('Galerie');
        }elseif(in_array($amenity,array('arts_centre','cultural_center'),true)){
            $score=88;$bucket='arts';$subcategory='Kulturzentrum & Kunst';$add('Kulturzentrum');
        }elseif(in_array($amenity,array('concert_hall','music_venue'),true)){
            $score=90;$bucket='music';$subcategory='Musik & Konzert';$add('Live-Musik');
        }elseif($amenity==='library'){
            $score=76;$bucket='library';$subcategory='Bibliothek & Literatur';$add('Bibliothek');
        }elseif($amenity==='nightclub'){
            $score=74;$bucket='scene';$subcategory='Club & Szene';$add('Szene');
        }elseif($tourism==='artwork'){
            $public_art = in_array($artwork,array('mural','sculpture','installation','statue'),true)
                || preg_match('/\b(streetart|street art|graffiti|mural|wandbild|skulptur|installation|kunstwerk|kunst)\b/u',$name)
                || !empty($tags['wikidata']) || !empty($tags['wikipedia']);
            if(!$public_art)return null;
            $score=$artwork==='mural'?84:72;$bucket='public_art';$subcategory='Streetart & Kunst im öffentlichen Raum';
            $add($artwork==='mural'?'Streetart':'Kunst');
        }elseif(in_array($amenity,array('community_centre','events_venue'),true)){
            // Broad OSM tags require an independent visitor-facing signal. Do
            // not punish distinctive local culture venues merely because their
            // name lacks the word "Kultur"; at the same time generic rentable
            // halls and club/parish/youth facilities stay out.
            $hard_non_culture = $sport!==''
                || $office==='association'
                || in_array($leisure,array('sports_centre','sports_hall','pitch','stadium','fitness_centre'),true)
                || in_array($building,array('sports_hall','stadium','school','kindergarten','clubhouse'),true)
                || preg_match('/\b(vereinsheim|clubheim|schutzenheim|schuetzenheim|sportverein|sportfreunde|sporthalle|turnhalle|sportplatz|stadion|tennis|tus|sv |fc |kanu|ruder|segel|fischer|angler|thw|jugendtreff|jugendzentrum|jugendfreizeit|jugend und burger|jugend und buerger|gemeindehaus|gemeindezentrum|kirchengemeinde|pfarrheim|dpsg|kleingarten|kgv|schule|kindergarten)\b/u',$name);
            if($hard_non_culture)return null;
            $culture_identity = (bool)preg_match('/\b(kultur|kulturhaus|kulturzentrum|kunst|galerie|theater|theatre|buhne|buehne|musik|konzert|kleinkunst|soziokultur|kreativ|atelier|burgerhaus|buergerhaus)\b/u',$name);
            $generic_hall = (bool)preg_match('/\b(event|eventlocation|festsaal|veranstaltungszentrum|veranstaltungshalle|mehrzweckhalle|gemeindesaal|hochzeit|wedding|vermietung|saalbetrieb)\b/u',$name);
            $authority = !empty($tags['wikidata'])||!empty($tags['wikipedia'])||!empty($row['wikidata'])||!empty($row['wikipedia']);
            $tag_culture = in_array(strtolower((string)($tags['live_music']??'')),array('yes','only'),true)
                || !empty($tags['music']) || !empty($tags['theatre:genre']) || !empty($tags['art']) || !empty($tags['cultural']);
            $has_web = !empty($tags['website'])||!empty($tags['contact:website'])||!empty($row['website']);
            if(!$culture_identity&&!$authority&&!$tag_culture&&(!($has_web&&!$generic_hall)))return null;
            $score=$amenity==='events_venue'?78:74;$bucket='culture_house';$subcategory='Kulturhaus & Bühne';$add('Kulturort');
        }else{
            return null;
        }

        if(!empty($tags['wikidata'])||!empty($row['wikidata'])){$score+=3;$add('Bekannter Ort');}
        if(!empty($tags['wikipedia'])||!empty($row['wikipedia']))$score+=3;
        if(!empty($tags['website'])||!empty($tags['contact:website'])||!empty($row['website']))$score+=2;
        if(!empty($tags['opening_hours'])||!empty($row['opening_hours']))$score+=2;
        $distance=isset($row['distance_km'])?max(0.0,(float)$row['distance_km']):0.0;
        return array(
            'score'=>round(min(100.0,$score),2),
            'rank_score'=>round(min(100.0,$score)-min(5.0,$distance*0.20),2),
            'bucket'=>$bucket,
            'labels'=>array_slice($labels,0,4),
            'subcategory'=>$subcategory,
        );
    }

    private function rank_culture_rows($rows,$limit){
        $out=array();
        foreach((array)$rows as $row){
            $profile=$this->culture_experience_profile($row); if(!$profile)continue;
            $row['_rg_culture_score']=$profile['score'];
            $row['_rg_culture_rank_score']=$profile['rank_score'];
            $row['_rg_culture_bucket']=$profile['bucket'];
            $row['_rg_culture_tags']=$profile['labels'];
            $row['_rg_response_category']='culture';
            $row['_rg_response_subcategory']=$profile['subcategory'];
            $out[]=$row;
        }
        // Product rule: Culture stays distance-first. Intelligence is an
        // eligibility gate, not a hidden popularity sort.
        usort($out,function($a,$b){
            $da=(float)($a['distance_km']??INF);$db=(float)($b['distance_km']??INF);
            if(abs($da-$db)>0.0001)return $da<$db?-1:1;
            $sa=(float)($a['_rg_culture_score']??0);$sb=(float)($b['_rg_culture_score']??0);
            if(abs($sa-$sb)>0.001)return $sa>$sb?-1:1;
            return strcmp((string)($a['name']??''),(string)($b['name']??''));
        });
        return array_slice($out,0,max(1,min(1500,(int)$limit)));
    }

    /**
     * Culture feed hygiene. Keep Stolperstein records in the catalogue for a
     * future dedicated product, but never let this hygiene rule alter the SQL
     * query used by the public Culture feed. This deliberately runs after the
     * database read so a malformed/unsupported SQL fragment cannot blank the
     * whole Culture section.
     */
    private function is_stolperstein_row($row) {
        if (!is_array($row)) return false;
        $haystack = strtolower((string) ($row['name'] ?? '') . ' ' . (string) ($row['raw_tags'] ?? ''));
        return strpos($haystack, 'stolperstein') !== false;
    }

    private function nearby_rows($category, $lat, $lng, $radius_km, $limit, $kind = 'all') {
        global $wpdb;
        $places = $this->table('places');
        $categories = $this->table('place_categories');
        $limit = max(1, min(1500, (int) $limit));
        $radius_km = max(0.5, min(80.0, (float) $radius_km));
        $lat_delta = $radius_km / 110.574;
        $cos = max(0.2, cos(deg2rad($lat)));
        $lng_delta = $radius_km / (111.320 * $cos);
        $min_lat = $lat - $lat_delta;
        $max_lat = $lat + $lat_delta;
        $min_lng = $lng - $lng_delta;
        $max_lng = $lng + $lng_delta;
        $sub_sql = '';
        $kind_sql = '';
        if ($kind === 'activities-water-outdoor') {
            // Preserve the legacy OSM query semantics for the "Wasser / See"
            // quick filter. These tags are stored verbatim in raw_tags and the
            // clause is static (no user input). LOCATE keeps compatibility with
            // older MariaDB/MySQL versions without requiring JSON functions.
            $kind_sql = " AND (
                LOCATE('\"sport\":\"swimming\"', p.raw_tags) > 0 OR
                LOCATE('\"sport\":\"canoeing\"', p.raw_tags) > 0 OR
                LOCATE('\"sport\":\"kayak\"', p.raw_tags) > 0 OR
                LOCATE('\"sport\":\"sailing\"', p.raw_tags) > 0 OR
                LOCATE('\"sport\":\"rowing\"', p.raw_tags) > 0 OR
                LOCATE('\"sport\":\"wakeboarding\"', p.raw_tags) > 0 OR
                LOCATE('\"sport\":\"water_ski\"', p.raw_tags) > 0 OR
                LOCATE('\"sport\":\"scuba_diving\"', p.raw_tags) > 0 OR
                LOCATE('\"leisure\":\"water_park\"', p.raw_tags) > 0 OR
                LOCATE('\"leisure\":\"marina\"', p.raw_tags) > 0 OR
                LOCATE('\"leisure\":\"slipway\"', p.raw_tags) > 0
            ) ";
        } else {
            $sub = $this->kind_to_subcategory($kind);
            if ($sub) {
                $sub_sql = $wpdb->prepare(' AND c.subcategory=%s ', $sub);
            }
        }
        $distance = "(6371.0088 * 2 * ASIN(SQRT(POWER(SIN(RADIANS(p.lat - %f)/2),2) + COS(RADIANS(%f)) * COS(RADIANS(p.lat)) * POWER(SIN(RADIANS(p.lng - %f)/2),2))))";
        $distance_sql = $wpdb->prepare($distance, $lat, $lat, $lng);
        $activity_hard_blacklist_sql = $category === 'activities' ? $this->activity_v2_public_read_filter_sql('p') : '';
        $activity_priority_select_sql = $category === 'activities' ? ', ' . $this->activity_priority_sql('p') . ' AS experience_db_priority' : '';
        $activity_order_sql = $category === 'activities' ? 'experience_db_priority DESC, ' : '';
        // Culture is post-filtered for Stolpersteine. Read a generous candidate
        // pool so nearby memorial stones cannot crowd genuine culture venues out
        // before the safe PHP filter runs. Other categories keep their old limit.
        $db_limit = $category === 'culture' ? max($limit, 1500) : $limit;
        $sql = $wpdb->prepare(
            "SELECT p.*, c.subcategory, c.weight $activity_priority_select_sql, $distance_sql AS distance_km
             FROM $places p
             INNER JOIN $categories c ON c.place_id=p.id AND c.category=%s
             WHERE p.active=1
               AND p.lifecycle_status='active'
               AND p.lat BETWEEN %f AND %f
               AND p.lng BETWEEN %f AND %f
               $sub_sql
               $kind_sql
               $activity_hard_blacklist_sql
             HAVING distance_km <= %f
             ORDER BY $activity_order_sql distance_km ASC, p.quality_score DESC, p.id ASC
             LIMIT %d",
            $category, $min_lat, $max_lat, $min_lng, $max_lng, $radius_km, $db_limit
        );
        $rows = (array) $wpdb->get_results($sql, ARRAY_A);
        if ($category === 'culture') {
            return $this->rank_culture_rows($rows, $limit);
        }
        if ($category === 'activities') {
            return $this->rank_activity_rows($rows, $limit, false);
        }
        if ($category === 'highlights') {
            return $this->rank_highlight_rows($rows, $limit);
        }
        return $rows;
    }

    private function kind_to_subcategory($kind) {
        $map = array(
            'food-fast' => 'Imbiss & Streetfood',
            'food-cafe' => 'Café & Eis',
            'food-beer' => 'Bar & Biergarten',
            'culture-stage' => 'Theater & Bühne',
            'culture-museum' => 'Museum & Galerie',
            'activities-water' => 'Schwimmbäder & Thermen',
            'activities-climbing' => 'Klettern & Bouldern',
            'activities-animals' => 'Zoos & Tierparks',
            'highlights-landmark' => 'Halden & Landmarken',
            'highlights-industrial' => 'Industriekultur & Zechen',
            'highlights-castle' => 'Schloss & Burg',
            'highlights-nature' => 'Park & Natur',
        );
        return isset($map[$kind]) ? $map[$kind] : '';
    }

    private function sanitize_override_source_type($value) {
        $value=sanitize_key((string)$value);
        return in_array($value,array('editorial','operator','community','official'),true) ? $value : 'editorial';
    }

    private function override_row($place_id) {
        global $wpdb;
        $table=$this->table('place_overrides');
        return $wpdb->get_row($wpdb->prepare("SELECT * FROM $table WHERE place_id=%d AND status='active'",(int)$place_id),ARRAY_A);
    }

    private function decode_override_data($row_or_json) {
        $json=is_array($row_or_json) ? (string)($row_or_json['override_data']??'') : (string)$row_or_json;
        $data=json_decode($json,true);
        if(!is_array($data)) $data=array();
        if(!isset($data['fields'])||!is_array($data['fields'])) $data['fields']=array();
        if(!isset($data['features'])||!is_array($data['features'])) $data['features']=array();
        if(!isset($data['buedchen'])||!is_array($data['buedchen'])) $data['buedchen']=array();
        return $data;
    }

    private function override_field_value($data,$field,$default=null) {
        if(!isset($data['fields'][$field])) return $default;
        $node=$data['fields'][$field];
        if(is_array($node) && array_key_exists('value',$node)) return $node['value'];
        return $node;
    }

    private function save_override_data($place_id,$data,$source_type='editorial',$source_label='RuhrpottGuru', $verified=true) {
        global $wpdb;
        $place_id=(int)$place_id;
        if($place_id<=0) return false;
        $places=$this->table('places');
        if(!(int)$wpdb->get_var($wpdb->prepare("SELECT COUNT(*) FROM $places WHERE id=%d",$place_id))) return false;
        $table=$this->table('place_overrides');
        $now=current_time('mysql',true);
        $existing=$wpdb->get_row($wpdb->prepare("SELECT created_at,created_by FROM $table WHERE place_id=%d",$place_id),ARRAY_A);
        $source_type=$this->sanitize_override_source_type($source_type);
        $source_label=substr(sanitize_text_field((string)$source_label),0,190);
        $encoded=wp_json_encode($data,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES);
        $row=array(
            'place_id'=>$place_id,
            'override_data'=>$encoded,
            'status'=>'active',
            'source_type'=>$source_type,
            'source_label'=>$source_label,
            'created_by'=>$existing ? (int)$existing['created_by'] : get_current_user_id(),
            'created_at'=>$existing ? $existing['created_at'] : $now,
            'updated_at'=>$now,
            'verified_at'=>$verified ? $now : null,
        );
        return $wpdb->replace($table,$row,array('%d','%s','%s','%s','%s','%d','%s','%s','%s'))!==false;
    }

    private function normalize_price_tier($value) {
        $v=trim((string)$value);
        if($v==='') return '';
        if(preg_match('/^€{1,3}$/u',$v)) return $v;
        if(preg_match('/^\${1,3}$/',$v)) return str_repeat('€',strlen($v));
        if(preg_match('/^([1-3])(?:\.0+)?$/',$v,$m)) return str_repeat('€',(int)$m[1]);
        return '';
    }

    private function merge_override_into_tags(&$tags,&$row,$override_row) {
        if(!$override_row) return;
        $data=$this->decode_override_data($override_row);
        $field_map=array(
            'name'=>'name',
            'street'=>'addr:street',
            'house_number'=>'addr:housenumber',
            'postcode'=>'addr:postcode',
            'city'=>'addr:city',
            'phone'=>'phone',
            'website'=>'website',
            'opening_hours'=>'opening_hours',
            'instagram'=>'contact:instagram',
            'description'=>'description',
            'menu_url'=>'menu',
            'reservation_url'=>'reservation:website',
            'booking_url'=>'booking',
            'ticket_url'=>'tickets',
            'program_url'=>'programme',
            'cuisine'=>'cuisine',
            'price_tier'=>'rg:price_tier',
            'access'=>'access',
            'accessibility'=>'wheelchair',
            'admission'=>'charge',
            'activity_type'=>'rg:activity_type',
            'community_status'=>'rg:community_status',
        );
        foreach($field_map as $field=>$tag){
            $value=$this->override_field_value($data,$field,null);
            if($value===null) continue;
            $value=is_bool($value)?($value?'yes':'no'):trim((string)$value);
            if($value==='') unset($tags[$tag]); else $tags[$tag]=$value;
            if($field==='name' && $value!=='') $row['name']=$value;
        }
        foreach($data['features'] as $feature=>$value){
            $key='rg:buedchen_feature_'.sanitize_key($feature);
            if($value===null) continue;
            $tags[$key]=$value ? 'yes' : 'no';
        }
        $review=sanitize_key((string)($data['buedchen']['review_status']??''));
        if($review!=='') $tags['rg:buedchen_review_status']=$review;
        if(!empty($data['buedchen']['review_note'])) $tags['rg:buedchen_review_note']=sanitize_text_field((string)$data['buedchen']['review_note']);
        $tags['rg:manual_override']='1';
        $tags['rg:override_source']=$override_row['source_type'];
        $tags['rg:override_source_label']=$override_row['source_label'];
        if(!empty($override_row['verified_at'])) $tags['rg:override_verified_at']=$override_row['verified_at'];
    }

    private function buedchen_review_samples($per_tier=8) {
        global $wpdb;
        $places=$this->table('places');
        $overrides=$this->table('place_overrides');
        $out=array();
        foreach(array('A','B','C') as $tier){
            $needle='%"rg:buedchen_tier":"'.$tier.'"%';
            $rows=$wpdb->get_results($wpdb->prepare(
                "SELECT p.id,p.name,p.city,p.municipality_slug,p.street,p.house_number,p.opening_hours,p.website,p.raw_tags,
                        o.override_data,o.source_type,o.source_label,o.verified_at
                 FROM $places p
                 LEFT JOIN $overrides o ON o.place_id=p.id AND o.status='active'
                 WHERE p.active=1 AND p.primary_category='buedchen' AND p.raw_tags LIKE %s
                 ORDER BY CASE WHEN o.override_data IS NULL THEN 0 ELSE 1 END ASC, RAND()
                 LIMIT %d",
                $needle,max(1,min(20,(int)$per_tier))
            ),ARRAY_A);
            $out[$tier]=(array)$rows;
        }
        return $out;
    }

    public function admin_review_buedchen() {
        if(!current_user_can('manage_options')) wp_die('Keine Berechtigung.');
        check_admin_referer('rg_places_review_buedchen');
        $place_id=absint($_POST['place_id']??0);
        $verdict=sanitize_key($_POST['verdict']??'auto');
        if(!in_array($verdict,array('verified','rejected','auto'),true)) $verdict='auto';
        $row=$this->override_row($place_id);
        $data=$this->decode_override_data($row?:'');
        if($verdict==='auto'){
            unset($data['buedchen']['review_status'],$data['buedchen']['review_note']);
        }else{
            $data['buedchen']['review_status']=$verdict;
            $data['buedchen']['review_note']=substr(sanitize_text_field(wp_unslash($_POST['review_note']??'')),0,500);
        }
        $this->save_override_data($place_id,$data,'editorial','RuhrpottGuru Redaktion',true);
        wp_safe_redirect(add_query_arg(array('page'=>'ruhrpottguru-places','rg_reviewed'=>'1'),admin_url('tools.php')));
        exit;
    }

    public function admin_save_override() {
        if(!current_user_can('manage_options')) wp_die('Keine Berechtigung.');
        check_admin_referer('rg_places_save_override');
        $place_id=absint($_POST['place_id']??0);
        $row=$this->override_row($place_id);
        $data=$this->decode_override_data($row?:'');
        $source_type=$this->sanitize_override_source_type($_POST['source_type']??'editorial');
        $source_label=sanitize_text_field(wp_unslash($_POST['source_label']??'RuhrpottGuru Redaktion'));
        $field_names=array('name','street','house_number','postcode','city','phone','website','opening_hours','instagram','description');
        $now=current_time('mysql',true);
        foreach($field_names as $field){
            $posted=isset($_POST['fields'][$field]) ? trim(sanitize_textarea_field(wp_unslash($_POST['fields'][$field]))) : '';
            if($posted===''){
                unset($data['fields'][$field]);
                continue;
            }
            $data['fields'][$field]=array(
                'value'=>$posted,
                'source_type'=>$source_type,
                'source_label'=>$source_label,
                'verified_at'=>$now,
            );
        }
        if(isset($_POST['features']) && is_array($_POST['features'])){
            foreach(array('mixed_candy','coffee','sandwiches','seating','lottery','parcel_shop','tobacco','late_night') as $feature){
                $v=sanitize_key($_POST['features'][$feature]??'unknown');
                if($v==='unknown') unset($data['features'][$feature]);
                else $data['features'][$feature]=($v==='yes');
            }
        }
        $this->save_override_data($place_id,$data,$source_type,$source_label,true);
        $return_page=sanitize_key((string)($_POST['return_page']??''));$return_section=sanitize_key((string)($_POST['rg_section']??'places'));
        if($return_page==='rp-places') wp_safe_redirect(add_query_arg(array('page'=>'rp-places','rg_section'=>$return_section,'edit_place'=>$place_id,'rg_saved'=>'1'),admin_url('admin.php')));
        else wp_safe_redirect(add_query_arg(array('page'=>'ruhrpottguru-places','edit_place'=>$place_id,'rg_saved'=>'1'),admin_url('tools.php')));
        exit;
    }

    /** V1.10.76: load the native WordPress media picker only on the Place editor. */
    public function admin_enqueue_place_media_v1076($hook='') {
        if(!is_admin() || !current_user_can('manage_options')) return;
        $page=sanitize_key((string)($_GET['page']??''));
        if(!in_array($page,array('ruhrpottguru-places','rp-places'),true) || !absint($_GET['edit_place']??0)) return;
        if(function_exists('wp_enqueue_media')) wp_enqueue_media();
    }

    private function place_editorial_media_rows_v1076($place_id,$include_disabled=true) {
        global $wpdb;$media=$this->table('place_media');$place_id=(int)$place_id;if($place_id<=0)return array();
        $where=$include_disabled?"moderation_status IN ('active','disabled')":"moderation_status='active'";
        return (array)$wpdb->get_results($wpdb->prepare(
            "SELECT * FROM $media WHERE place_id=%d AND media_type='image' AND relation_type='place' AND source='editorial-place-upload' AND $where ORDER BY is_primary DESC,CASE WHEN moderation_status='active' THEN 0 ELSE 1 END,id ASC",
            $place_id
        ),ARRAY_A);
    }

    private function place_editorial_media_set_primary_v1076($place_id,$media_id) {
        global $wpdb;$media=$this->table('place_media');$place_id=(int)$place_id;$media_id=(int)$media_id;
        if($place_id<=0||$media_id<=0)return false;
        $owned=(int)$wpdb->get_var($wpdb->prepare("SELECT COUNT(*) FROM $media WHERE id=%d AND place_id=%d AND media_type='image' AND relation_type='place' AND source='editorial-place-upload' AND moderation_status='active'",$media_id,$place_id));
        if(!$owned)return false;
        $wpdb->query($wpdb->prepare("UPDATE $media SET is_primary=0 WHERE place_id=%d AND relation_type='place' AND media_type='image'",$place_id));
        return $wpdb->update($media,array('is_primary'=>1),array('id'=>$media_id),array('%d'),array('%d'))!==false;
    }

    public function admin_places_upload_media_v1076() {
        if(!current_user_can('manage_options'))wp_die('Keine Berechtigung.');
        check_admin_referer('rg_places_upload_media_v1076');
        global $wpdb;$place_id=absint($_POST['place_id']??0);$places=$this->table('places');$media=$this->table('place_media');
        $place=$wpdb->get_row($wpdb->prepare("SELECT id,name FROM $places WHERE id=%d",$place_id),ARRAY_A);if(!$place)wp_die('Ort nicht gefunden.');
        $ids_raw=sanitize_text_field((string)wp_unslash($_POST['attachment_ids']??''));$ids=array_values(array_unique(array_filter(array_map('absint',preg_split('/\s*,\s*/',$ids_raw)))));$ids=array_slice($ids,0,20);
        if(!$ids)wp_die('Bitte mindestens ein Bild auswählen.');
        $artist=substr(sanitize_text_field((string)wp_unslash($_POST['artist']??'')),0,190);
        $credit=substr(sanitize_text_field((string)wp_unslash($_POST['credit']??'')),0,900);
        $license=substr(sanitize_text_field((string)wp_unslash($_POST['license']??'')),0,120);
        $source_url=esc_url_raw((string)wp_unslash($_POST['source_url']??''));
        if($credit===''||$license==='')wp_die('Credit und Nutzungsgrundlage/Lizenz sind Pflicht.');
        $now=current_time('mysql',true);$had_manual=(int)$wpdb->get_var($wpdb->prepare("SELECT COUNT(*) FROM $media WHERE place_id=%d AND relation_type='place' AND source='editorial-place-upload' AND moderation_status='active'",$place_id));$inserted=array();
        foreach($ids as $aid){
            if(get_post_type($aid)!=='attachment'||!wp_attachment_is_image($aid))continue;$url=wp_get_attachment_url($aid);if(!$url)continue;$url=esc_url_raw($url);
            $exists=(int)$wpdb->get_var($wpdb->prepare("SELECT id FROM $media WHERE place_id=%d AND relation_type='place' AND source='editorial-place-upload' AND url=%s LIMIT 1",$place_id,$url));
            if($exists){$wpdb->update($media,array('moderation_status'=>'active','disabled_at'=>null,'disabled_by'=>0,'removal_reason'=>'','artist'=>$artist,'credit'=>$credit,'license'=>$license,'source_url'=>$source_url,'verified_at'=>$now,'last_seen_at'=>$now),array('id'=>$exists));$inserted[]=$exists;continue;}
            $ok=$wpdb->insert($media,array('place_id'=>$place_id,'media_type'=>'image','url'=>$url,'source'=>'editorial-place-upload','source_url'=>$source_url,'license'=>$license,'artist'=>$artist,'credit'=>$credit,'relation_type'=>'place','identity_confidence'=>1.0,'visual_quality'=>0.98,'is_primary'=>0,'moderation_status'=>'active','verified_at'=>$now,'last_seen_at'=>$now),array('%d','%s','%s','%s','%s','%s','%s','%s','%s','%f','%f','%d','%s','%s','%s'));
            if($ok)$inserted[]=(int)$wpdb->insert_id;
        }
        if(!$inserted)wp_die('Es konnte kein gültiges Bild übernommen werden.');
