                    'card'=>array('x'=>(float)$o['card_x'],'y'=>(float)$o['card_y'],'zoom'=>(float)$o['card_zoom']),
                    'detail'=>array('x'=>(float)$o['detail_x'],'y'=>(float)$o['detail_y'],'zoom'=>(float)$o['detail_zoom'])
                );
            }
            $r['_crop_identity']=$rowIdentities[$i]??array();
        }
        unset($r);
        return $rows;
    }

    private function media_crop_payload_v101112($row,$which='card') {
        $o=is_array($row['_crop_override']??null)?$row['_crop_override']:array();if(($o['mode']??'')==='manual'){$v=is_array($o[$which]??null)?$o[$which]:array();return array('mode'=>'manual','x'=>max(0,min(100,(float)($v['x']??50))),'y'=>max(0,min(100,(float)($v['y']??50))),'zoom'=>max(0,min(2.5,(float)($v['zoom']??1))));}
        return $this->media_auto_crop_payload_v101112($row,$which);
    }

    /**
     * 1.10.123 visitor-safe event crop payload.
     * Never opens/decodes/hashes image files inside the public event-list REST request.
     * Manual overrides are already batch-attached by the canonical persisted identity.
     * Without one, null intentionally delegates to the frontend's existing centred cover.
     */
    private function media_crop_payload_runtime_safe_v101123($row,$which='card') {
        $which=$which==='detail'?'detail':'card';
        $o=is_array($row['_crop_override']??null)?$row['_crop_override']:array();
        if(($o['mode']??'')!=='manual')return null;
        $v=is_array($o[$which]??null)?$o[$which]:array();
        return array(
            'mode'=>'manual',
            'x'=>max(0,min(100,(float)($v['x']??50))),
            'y'=>max(0,min(100,(float)($v['y']??50))),
            'zoom'=>max(0,min(2.5,(float)($v['zoom']??1)))
        );
    }

    /**
     * 1.10.158 visitor-address fallback for authoritative Route sites.
     * Only fills fields missing from the canonical Place/OSM record; it never
     * overwrites an existing address and never writes back to the database.
     */
    private function industrial_route_visitor_address_v101158($slug) {
        $slug=sanitize_title((string)$slug);
        $map=array(
            'unesco-welterbe-zollverein'=>array(
                'street'=>'Gelsenkirchener Str.',
                'house_number'=>'181',
                'postcode'=>'45309',
                'city'=>'Essen',
                'source'=>'https://www.zollverein.de/besuch-planen/anfahrt/'
            ),
        );
        return $map[$slug]??array();
    }

    private function rows_to_elements($rows) {
        global $wpdb;
        if (!$rows) return array();
        $place_ids = array_values(array_unique(array_map('intval', wp_list_pluck($rows, 'id'))));
        $links = array();
        $schedules = array();
        $overrides = array();
        $enrichment = array();
        $media = array();
        if ($place_ids) {
            $table = $this->table('place_links');
            $ids_sql = implode(',', $place_ids);
            $link_rows = $wpdb->get_results("SELECT place_id,link_type,url,source,confidence FROM $table WHERE place_id IN ($ids_sql) AND status='active'", ARRAY_A);
            foreach ((array) $link_rows as $link) {
                $links[(int) $link['place_id']][$link['link_type']] = $link;
            }
            $schedule_table = $this->table('place_schedules');
            $schedule_rows = $wpdb->get_results("SELECT place_id,schedule_type,raw_value,source,confidence FROM $schedule_table WHERE place_id IN ($ids_sql)", ARRAY_A);
            foreach ((array) $schedule_rows as $schedule) {
                if ($schedule['schedule_type'] === 'general') {
                    $schedules[(int) $schedule['place_id']] = $schedule;
                }
            }
            $override_table = $this->table('place_overrides');
            $override_rows = $wpdb->get_results("SELECT * FROM $override_table WHERE status='active' AND place_id IN ($ids_sql)", ARRAY_A);
            foreach ((array)$override_rows as $override) $overrides[(int)$override['place_id']]=$override;
            // V1.10.13: the runtime response must also expose already persisted enrichment.
            // Some enrichment jobs update place_enrichment / places directly while older
            // place_links or place_schedules rows can legitimately be absent. Hiding those
            // values made verified menus and opening hours disappear from the frontend.
            $enrichment_table = $this->table('place_enrichment');
            $enrichment_rows = $wpdb->get_results("SELECT place_id,price_tier,website_url,menu_url,reservation_url,opening_hours FROM $enrichment_table WHERE place_id IN ($ids_sql)", ARRAY_A);
            foreach ((array)$enrichment_rows as $entry) $enrichment[(int)$entry['place_id']]=$entry;
            $media_table=$this->table('place_media');
            $media_rows=$wpdb->get_results("SELECT id,place_id,url,source,source_url,license,artist,credit,is_primary,identity_confidence,visual_quality FROM $media_table WHERE place_id IN ($ids_sql) AND relation_type='place' AND moderation_status='active' ORDER BY CASE WHEN source='editorial-place-upload' THEN 0 ELSE 1 END ASC,is_primary DESC,identity_confidence DESC,visual_quality DESC,id ASC",ARRAY_A);
            $media_rows=$this->media_crop_overrides_for_rows_v101112((array)$media_rows,'place');
            foreach((array)$media_rows as $m){
                $mpid=(int)$m['place_id'];
                if(!isset($media[$mpid])) $media[$mpid]=array();
                $media[$mpid][]=$m;
            }
        }
        $out = array();
        foreach ($rows as $row) {
            $tags = json_decode((string) $row['raw_tags'], true);
            if (!is_array($tags)) $tags = array();
            $pid = (int) $row['id'];
            $tags['name'] = $row['name'];
            $routeAddress=$this->industrial_route_visitor_address_v101158((string)($row['_rg_industrial_route_slug']??''));
            if ($row['street'] !== '') $tags['addr:street'] = $row['street'];
            elseif (empty($tags['addr:street']) && !empty($routeAddress['street'])) $tags['addr:street']=(string)$routeAddress['street'];
            if ($row['house_number'] !== '') $tags['addr:housenumber'] = $row['house_number'];
            elseif (empty($tags['addr:housenumber']) && !empty($routeAddress['house_number'])) $tags['addr:housenumber']=(string)$routeAddress['house_number'];
            if ($row['postcode'] !== '') $tags['addr:postcode'] = $row['postcode'];
            elseif (empty($tags['addr:postcode']) && !empty($routeAddress['postcode'])) $tags['addr:postcode']=(string)$routeAddress['postcode'];
            if ($row['city'] !== '') $tags['addr:city'] = $row['city'];
            elseif (empty($tags['addr:city']) && !empty($routeAddress['city'])) $tags['addr:city']=(string)$routeAddress['city'];
            if($routeAddress && !empty($routeAddress['source']))$tags['rg:address_source']=(string)$routeAddress['source'];
            if ($row['district'] !== '') $tags['addr:suburb'] = $row['district'];
            if ($row['phone'] !== '') $tags['phone'] = $row['phone'];
            if ($row['wikidata'] !== '') $tags['wikidata'] = $row['wikidata'];
            if ($row['wikipedia'] !== '') $tags['wikipedia'] = $row['wikipedia'];
            $en = isset($enrichment[$pid]) && is_array($enrichment[$pid]) ? $enrichment[$pid] : array();
            // Runtime precedence: curated active link/schedule > persisted enrichment >
            // canonical places column > original raw OSM tag. Never drop a verified value
            // merely because one auxiliary table has no row yet.
            if (isset($links[$pid]['website']) && !empty($links[$pid]['website']['url'])) $tags['website'] = $links[$pid]['website']['url'];
            elseif (!empty($en['website_url'])) $tags['website'] = $en['website_url'];
            elseif (!empty($row['website'])) $tags['website'] = $row['website'];
            if (isset($links[$pid]['menu']) && !empty($links[$pid]['menu']['url'])) $tags['menu'] = $links[$pid]['menu']['url'];
            elseif (!empty($en['menu_url'])) $tags['menu'] = $en['menu_url'];
            if (isset($links[$pid]['reservation']) && !empty($links[$pid]['reservation']['url'])) $tags['reservation:website'] = $links[$pid]['reservation']['url'];
            elseif (!empty($en['reservation_url'])) $tags['reservation:website'] = $en['reservation_url'];
            if (isset($schedules[$pid]) && $schedules[$pid]['raw_value'] !== '') $tags['opening_hours'] = $schedules[$pid]['raw_value'];
            elseif (!empty($en['opening_hours'])) $tags['opening_hours'] = $en['opening_hours'];
            elseif (!empty($row['opening_hours'])) $tags['opening_hours'] = $row['opening_hours'];
            // 1.10.93: place_enrichment.price_tier existed in the schema but was not
            // selected/exposed by rows_to_elements(). Only explicit 1-3 / € tiers are
            // accepted; absent or free-form values stay invisible rather than guessed.
            if (!empty($en['price_tier'])) {
                $price_tier=$this->normalize_price_tier($en['price_tier']);
                if($price_tier!=='') $tags['rg:price_tier']=$price_tier;
            }
            if(isset($media[$pid]) && is_array($media[$pid]) && !empty($media[$pid][0]['url'])){
                $display_media=$media[$pid];$manual_media=array_values(array_filter($display_media,function($m){return (string)($m['source']??'')==='editorial-place-upload';}));if($manual_media)$display_media=$manual_media;
                $primary_media=$display_media[0];
                $tags['image:url']=$primary_media['url'];
                $tags['rg:image_source']=$primary_media['source'];
                if(!empty($primary_media['source_url'])) $tags['rg:image_source_url']=$primary_media['source_url'];
                if(!empty($primary_media['license'])) $tags['rg:image_license']=$primary_media['license'];
                if(!empty($primary_media['credit'])) $tags['rg:image_credit']=$primary_media['credit'];
                $cardCrop=$this->media_crop_payload_v101112($primary_media,'card');$detailCrop=$this->media_crop_payload_v101112($primary_media,'detail');
                if($cardCrop)$tags['rg:image_crop_card']=wp_json_encode($cardCrop,JSON_UNESCAPED_SLASHES|JSON_UNESCAPED_UNICODE);
                if($detailCrop)$tags['rg:image_crop_detail']=wp_json_encode($detailCrop,JSON_UNESCAPED_SLASHES|JSON_UNESCAPED_UNICODE);
                $gallery=array();
                foreach($display_media as $gm){
                    if(empty($gm['url'])) continue;
                    $gallery[]=array(
                        'url'=>(string)$gm['url'],
                        'credit'=>(string)($gm['credit']?:$gm['artist']),
                        'artist'=>(string)$gm['artist'],
                        'source'=>(string)$gm['source'],
                        'license'=>(string)$gm['license'],
                        'cropCard'=>$this->media_crop_payload_v101112($gm,'card'),
                        'cropDetail'=>$this->media_crop_payload_v101112($gm,'detail'),
                    );
                }
                if($gallery) $tags['rg:media_gallery']=wp_json_encode($gallery,JSON_UNESCAPED_SLASHES|JSON_UNESCAPED_UNICODE);
            }
            if (isset($overrides[$pid])) $this->merge_override_into_tags($tags,$row,$overrides[$pid]);
            // 1.10.68: a verified/approved active override that explicitly marks a
            // place as permanently closed/inactive is visitor-authoritative. Keep the
            // catalogue row for reversibility/audit, but do not expose it through any
            // public endpoint that uses rows_to_elements(). Unknown hours are NEVER a
            // closure signal; only an explicit approved lifecycle status triggers this.
            if (isset($overrides[$pid]) && !empty($overrides[$pid]['verified_at'])) {
                $community_status = mb_strtolower(trim((string)($tags['rg:community_status'] ?? '')), 'UTF-8');
                $community_status = preg_replace('/\s+/u', ' ', $community_status);
                if (in_array($community_status, array('closed','geschlossen','inactive','inaktiv','dauerhaft geschlossen','permanently closed'), true)) continue;
            }
            $tags['rg:place_id'] = (string) $pid;
            $tags['rg:canonical_url'] = $this->seo_place_url_v101096($pid, (string)$row['name'], (string)($row['city']??''));
            $tags['rg:source'] = 'places-db';
            $tags['rg:category'] = !empty($row['_rg_response_category']) ? (string) $row['_rg_response_category'] : $row['primary_category'];
            $tags['rg:subcategory'] = !empty($row['_rg_response_subcategory']) ? (string) $row['_rg_response_subcategory'] : $row['subcategory'];
            $tags['rg:quality_score'] = (string) $row['quality_score'];
            $tags['rg:last_synced_at'] = $row['last_synced_at'];
            if (isset($row['_rg_activity_score'])) $tags['rg:activity_score'] = (string) $row['_rg_activity_score'];
            if (isset($row['_rg_activity_rank_score'])) $tags['rg:activity_rank_score'] = (string) $row['_rg_activity_rank_score'];
            if (!empty($row['_rg_activity_bucket'])) $tags['rg:activity_bucket'] = (string) $row['_rg_activity_bucket'];
            if (!empty($row['_rg_experience_tags']) && is_array($row['_rg_experience_tags'])) $tags['rg:experience_tags'] = implode('|', $row['_rg_experience_tags']);
            if (!empty($row['_rg_activity_v2_admission'])) $tags['rg:activity_v2_admission'] = (string) $row['_rg_activity_v2_admission'];
            if (!empty($row['_rg_activity_v2_primary'])) $tags['rg:activity_v2_primary'] = (string) $row['_rg_activity_v2_primary'];
            if (!empty($row['_rg_activity_environment'])) $tags['rg:activity_environment'] = (string) $row['_rg_activity_environment'];
            if (isset($row['_rg_activity_multi_count'])) $tags['rg:activity_multi_count'] = (string) $row['_rg_activity_multi_count'];
            if (isset($row['_rg_culture_score'])) $tags['rg:culture_score'] = (string) $row['_rg_culture_score'];
            if (isset($row['_rg_culture_rank_score'])) $tags['rg:culture_rank_score'] = (string) $row['_rg_culture_rank_score'];
            if (!empty($row['_rg_culture_bucket'])) $tags['rg:culture_bucket'] = (string) $row['_rg_culture_bucket'];
            if (!empty($row['_rg_culture_tags']) && is_array($row['_rg_culture_tags'])) $tags['rg:culture_tags'] = implode('|', $row['_rg_culture_tags']);
            if (isset($row['_rg_highlight_score'])) $tags['rg:highlight_score'] = (string) $row['_rg_highlight_score'];
            if (isset($row['_rg_highlight_rank_score'])) $tags['rg:highlight_rank_score'] = (string) $row['_rg_highlight_rank_score'];
            if (!empty($row['_rg_highlight_bucket'])) $tags['rg:highlight_bucket'] = (string) $row['_rg_highlight_bucket'];
            if (!empty($row['_rg_highlight_tags']) && is_array($row['_rg_highlight_tags'])) $tags['rg:highlight_tags'] = implode('|', $row['_rg_highlight_tags']);
            if (!empty($row['_rg_highlight_tier'])) $tags['rg:highlight_tier'] = (string) $row['_rg_highlight_tier'];
            if (!empty($row['_rg_industrial_route_slug'])) {
                $tags['rg:industrial_route'] = '1';
                $tags['rg:industrial_route_slug'] = (string) $row['_rg_industrial_route_slug'];
                $tags['rg:industrial_route_type'] = (string) ($row['_rg_industrial_route_type'] ?? '');
                $tags['rg:industrial_route_title'] = (string) ($row['_rg_industrial_route_title'] ?? $row['name']);
                if(isset($row['_rg_industrial_route_match_score'])) $tags['rg:industrial_route_match_score'] = (string) $row['_rg_industrial_route_match_score'];
                $tags['rg:industrial_route_page'] = home_url('/route-industriekultur/');
            }
            $type = $row['primary_osm_type'] === 'w' ? 'way' : ($row['primary_osm_type'] === 'r' ? 'relation' : 'node');
            $element = array(
                'type' => $type,
                'id' => (int) $row['primary_osm_id'],
                'tags' => $tags,
                'timestamp' => gmdate('c', strtotime($row['last_synced_at'])),
            );
            if ($type === 'node') {
                $element['lat'] = (float) $row['lat'];
                $element['lon'] = (float) $row['lng'];
            } else {
                $element['center'] = array('lat'=>(float)$row['lat'], 'lon'=>(float)$row['lng']);
            }
            $out[] = $element;
        }
        return $out;
    }

    /**
     * V1.2.6.1 queue state:
     * distinguish "really finished" from "work exists but is cooling down".
     */
    private function browser_sync_queue_state($refresh_ready = null) {
        global $wpdb;
        $table = $this->table('places_municipalities');
        if ($refresh_ready === null) $refresh_ready = get_option(self::OPTION_STATUS) === 'ready';
        $now = current_time('mysql', true);

        if ($refresh_ready) {
            $cutoff = gmdate('Y-m-d H:i:s', time() - DAY_IN_SECONDS);
            $row = $wpdb->get_row($wpdb->prepare(
                "SELECT slug,name,last_synced_at,locked_until,attempts
                 FROM $table
                 WHERE status='complete'
                   AND (last_synced_at IS NULL OR last_synced_at < %s)
                 ORDER BY CASE WHEN locked_until IS NULL OR locked_until < %s THEN 0 ELSE 1 END,
                          COALESCE(locked_until,'2000-01-01') ASC,
                          attempts ASC,
                          slug ASC
                 LIMIT 1",
                $cutoff, $now
            ), ARRAY_A);
        } else {
            $row = $wpdb->get_row($wpdb->prepare(
                "SELECT slug,name,last_synced_at,locked_until,attempts
                 FROM $table
                 WHERE status IN ('pending','failed','in_progress')
                 ORDER BY CASE WHEN locked_until IS NULL OR locked_until < %s THEN 0 ELSE 1 END,
                          COALESCE(locked_until,'2000-01-01') ASC,
                          attempts ASC,
                          slug ASC
                 LIMIT 1",
                $now
            ), ARRAY_A);
        }

        if (!$row) return array('hasWork'=>false,'waiting'=>false,'retryAfter'=>0,'next'=>null);

        $locked_ts = !empty($row['locked_until']) ? strtotime($row['locked_until'].' UTC') : 0;
        $now_ts = time();
        $waiting = $locked_ts > $now_ts;
        return array(
            'hasWork'=>true,
            'waiting'=>$waiting,
            'retryAfter'=>$waiting ? max(1,$locked_ts-$now_ts) : 0,
            'next'=>array(
                'slug'=>(string)$row['slug'],
                'name'=>(string)$row['name'],
                'lockedUntil'=>(string)($row['locked_until'] ?? ''),
                'attempts'=>(int)($row['attempts'] ?? 0),
            ),
        );
    }

    public function rest_bootstrap_next() {
        $is_refresh = get_option(self::OPTION_STATUS) === 'ready';
        $next = $this->claim_next_municipality($is_refresh);
        if (!$next) {
            $queue = $this->browser_sync_queue_state($is_refresh);
            if (!empty($queue['hasWork']) && !empty($queue['waiting'])) {
                return rest_ensure_response(array(
                    'ok'=>true,
                    'done'=>false,
                    'waiting'=>true,
                    'retryAfter'=>(int)$queue['retryAfter'],
                    'nextRetry'=>$queue['next'],
                    'status'=>$this->status_payload(),
                ));
            }
            if (!$is_refresh) $this->maybe_finalize_catalog();
            return rest_ensure_response(array('ok'=>true,'done'=>true,'waiting'=>false,'status'=>$this->status_payload()));
        }
        return rest_ensure_response(array(
            'ok' => true,
            'done' => false,
            'runType' => $is_refresh ? 'refresh' : 'bootstrap',
            'municipality' => array(
                'slug' => $next['slug'],
                'name' => $next['name'],
                'adminLevel' => (int) $next['admin_level'],
                'group' => $next['group_name'],
            ),
            'query' => $this->build_city_overpass_query($next['name'], (int) $next['admin_level']),
            'queries' => $this->build_city_overpass_queries($next['name'], (int) $next['admin_level']),
        ));
    }

    public function rest_bootstrap_import(WP_REST_Request $request) {
        $data = $request->get_json_params();
        $slug = sanitize_title(isset($data['municipality']) ? $data['municipality'] : '');
        $elements = isset($data['elements']) && is_array($data['elements']) ? $data['elements'] : array();
        if (!$slug || count($elements) > 500) {
            return new WP_REST_Response(array('ok'=>false,'error'=>'invalid-import-batch'), 400);
        }
        $municipality = $this->get_municipality($slug);
        if (!$municipality) {
            return new WP_REST_Response(array('ok'=>false,'error'=>'unknown-municipality'), 404);
        }
        $stats = $this->import_elements($elements, $municipality);
        return rest_ensure_response(array('ok'=>true,'stats'=>$stats));
    }

    public function rest_bootstrap_complete(WP_REST_Request $request) {
        global $wpdb;
        $data = $request->get_json_params();
        $slug = sanitize_title(isset($data['municipality']) ? $data['municipality'] : '');
        $raw_count = isset($data['rawCount']) ? max(0, (int) $data['rawCount']) : 0;
        $imported_count = isset($data['importedCount']) ? max(0, (int) $data['importedCount']) : 0;
        $run_type = isset($data['runType']) && $data['runType'] === 'refresh' ? 'refresh' : 'bootstrap';
        $municipality = $this->get_municipality($slug);
        if (!$municipality) {
            return new WP_REST_Response(array('ok'=>false,'error'=>'unknown-municipality'), 404);
        }
        // A real municipality in the RVR area should yield more than a handful of named candidates.
        // Treat suspiciously empty results as transport/area lookup failures, not a successful city import.
        if ($raw_count < 5 || $imported_count < 3) {
            $this->mark_municipality_error($slug, 'Suspiciously small import: raw=' . $raw_count . ', imported=' . $imported_count, $run_type === 'refresh');
            return new WP_REST_Response(array('ok'=>false,'error'=>'suspicious-empty-city'), 422);
        }
        $table = $this->table('places_municipalities');
        $now = current_time('mysql', true);
        if ($run_type === 'refresh' && !empty($municipality['sync_started_at'])) {
            $this->reconcile_stale_primary_sources_after_snapshot_v1080($slug, $municipality['sync_started_at']);
            $this->mark_missing_after_snapshot($slug, $municipality['sync_started_at']);
        }
        $wpdb->update($table, array(
            'status'=>'complete', 'raw_count'=>$raw_count, 'imported_count'=>$imported_count,
            'last_error'=>null, 'locked_until'=>null, 'sync_started_at'=>null, 'last_synced_at'=>$now, 'updated_at'=>$now,
        ), array('slug'=>$slug));
        $this->maybe_finalize_catalog();
        return rest_ensure_response(array('ok'=>true,'status'=>$this->status_payload()));
    }

    private function get_municipality($slug) {
        global $wpdb;
        $table = $this->table('places_municipalities');
        return $wpdb->get_row($wpdb->prepare("SELECT * FROM $table WHERE slug=%s", $slug), ARRAY_A);
    }

    private function claim_next_municipality($refresh_ready = false) {
        global $wpdb;
        $table = $this->table('places_municipalities');
        $now = current_time('mysql', true);
        if ($refresh_ready) {
            // Refresh is intentionally bounded: a complete municipality becomes due after 24h.
            // Keep status=complete while refreshing so a failed refresh can never make the live DB incomplete.
            $cutoff = gmdate('Y-m-d H:i:s', time() - DAY_IN_SECONDS);
            $row = $wpdb->get_row($wpdb->prepare(
                "SELECT * FROM $table
                 WHERE status='complete'
                   AND (last_synced_at IS NULL OR last_synced_at < %s)
                   AND (locked_until IS NULL OR locked_until < %s)
                 ORDER BY attempts ASC, COALESCE(last_synced_at,'2000-01-01') ASC, slug ASC LIMIT 1",
                $cutoff, $now
            ), ARRAY_A);
        } else {
            $row = $wpdb->get_row($wpdb->prepare(
                "SELECT * FROM $table
                 WHERE (status='pending' AND (locked_until IS NULL OR locked_until < %s))
                    OR (status='failed' AND (locked_until IS NULL OR locked_until < %s))
                    OR (status='in_progress' AND (locked_until IS NULL OR locked_until < %s))
                 ORDER BY CASE status WHEN 'pending' THEN 0 WHEN 'failed' THEN 1 ELSE 2 END, attempts ASC, slug ASC LIMIT 1",
                $now,$now,$now
            ), ARRAY_A);
        }
        if (!$row) return null;
        $locked = gmdate('Y-m-d H:i:s', time() + 15 * MINUTE_IN_SECONDS);
        if ($refresh_ready) {
            $wpdb->query($wpdb->prepare(
                "UPDATE $table SET locked_until=%s,sync_started_at=%s,attempts=attempts+1,updated_at=%s WHERE slug=%s",
                $locked, $now, $now, $row['slug']
            ));
            $row['status'] = 'complete';
        } else {
            $wpdb->query($wpdb->prepare(
                "UPDATE $table SET status='in_progress',locked_until=%s,sync_started_at=%s,attempts=attempts+1,updated_at=%s WHERE slug=%s",
                $locked, $now, $now, $now, $row['slug']
            ));
            $row['status'] = 'in_progress';
        }
        $row['sync_started_at'] = $now;
        return $row;
    }

    private function mark_municipality_error($slug, $message, $preserve_complete = false) {
        global $wpdb;
        $table = $this->table('places_municipalities');
        $status = $preserve_complete ? 'complete' : 'failed';
        $attempts=(int)$wpdb->get_var($wpdb->prepare("SELECT attempts FROM $table WHERE slug=%s",$slug));
        // A failing large city must yield to the other municipalities instead of
        // being reclaimed immediately. 5/15/30/60 minute cooldown, capped at 60.
        $minutes = $attempts <= 1 ? 5 : ($attempts === 2 ? 15 : ($attempts === 3 ? 30 : 60));
        $locked = gmdate('Y-m-d H:i:s', time() + $minutes * MINUTE_IN_SECONDS);
        $wpdb->update($table, array(
            'status'=>$status,
            'last_error'=>substr((string)$message,0,2000),
            'locked_until'=>$locked,
            'sync_started_at'=>null,
            'updated_at'=>current_time('mysql', true)
        ), array('slug'=>$slug));
    }


    /**
     * Places 1.10.80: if the OSM object currently used as a place's primary
     * source disappeared from a fully successful municipality snapshot while a
     * duplicate/current OSM representation of the same canonical place is still
     * present, switch the core to that current source. This prevents a stale
     * primary row from surviving forever merely because another source keeps the
     * canonical place "seen".
     */
    private function reconcile_stale_primary_sources_after_snapshot_v1080($municipality_slug,$sync_started_at) {
        global $wpdb;
        if(!$municipality_slug||!$sync_started_at)return 0;
        $places=$this->table('places');$sources=$this->table('place_sources');$cats=$this->table('place_categories');
        $rows=(array)$wpdb->get_results($wpdb->prepare(
            "SELECT p.*,
                    s.id AS current_source_id,s.source_uid AS current_source_uid,s.osm_type AS current_osm_type,s.osm_id AS current_osm_id,
                    s.raw_payload AS current_raw_payload,s.last_seen_at AS current_source_seen
             FROM $places p
             INNER JOIN $sources s ON s.place_id=p.id AND s.source_type='osm' AND s.last_seen_at >= %s
             LEFT JOIN $sources ps ON ps.place_id=p.id AND ps.source_type='osm'
                  AND ps.osm_type=p.primary_osm_type AND ps.osm_id=p.primary_osm_id
             WHERE p.municipality_slug=%s
               AND p.active=1
               AND p.lifecycle_status='active'
               AND (ps.id IS NULL OR ps.last_seen_at < %s)
             ORDER BY p.id ASC,s.last_seen_at DESC,s.id DESC",
            $sync_started_at,$municipality_slug,$sync_started_at
        ),ARRAY_A);
        if(!$rows)return 0;

        // A canonical place may have several current OSM representations (node,
        // way, relation). Pick the best *current* one, not merely the last row.
        $best=array();
        foreach($rows as $row){
            $pid=(int)$row['id'];
            $payload=json_decode((string)($row['current_raw_payload']??''),true);if(!is_array($payload))continue;
            $tags=(isset($payload['tags'])&&is_array($payload['tags']))?$payload['tags']:$payload; // legacy source rows
            if($this->is_inactive_tags($tags))continue;
            $name=trim((string)($tags['name']??$row['name']??''));if($name==='')continue;
            $classification=$this->classify_tags($tags,$name);if(!$classification)continue;
            $street=trim((string)($tags['addr:street']??$row['street']??''));
            $house=trim((string)($tags['addr:housenumber']??$row['house_number']??''));
            $city=trim((string)($tags['addr:city']??$row['city']??''));
            $quality=$this->quality_score($tags,$street,$house,$city);
            $tag_count=count($tags);
            if(isset($best[$pid])){
                $b=$best[$pid];
                if($quality<(float)$b['quality'])continue;
                if(abs($quality-(float)$b['quality'])<0.000001 && $tag_count<=(int)$b['tag_count'])continue;
            }
            $best[$pid]=array('row'=>$row,'tags'=>$tags,'classification'=>$classification,'quality'=>$quality,'tag_count'=>$tag_count,
                'lat'=>isset($payload['lat'])&&is_numeric($payload['lat'])?(float)$payload['lat']:(float)($row['lat']??0),
                'lng'=>isset($payload['lng'])&&is_numeric($payload['lng'])?(float)$payload['lng']:(float)($row['lng']??0));
        }

        $changed=0;$now=current_time('mysql',true);
        foreach($best as $pid=>$candidate){
            $row=$candidate['row'];$tags=$candidate['tags'];$classification=$candidate['classification'];$quality=(float)$candidate['quality'];
            $name=trim((string)($tags['name']??$row['name']??''));
            $street=trim((string)($tags['addr:street']??$row['street']??''));
            $house=trim((string)($tags['addr:housenumber']??$row['house_number']??''));
            $postcode=trim((string)($tags['addr:postcode']??$row['postcode']??''));
            $city=trim((string)($tags['addr:city']??$row['city']??''));
            $district=trim((string)($tags['addr:suburb']??($tags['addr:district']??($tags['neighbourhood']??($row['district']??'')))));
            $website=$this->first_url(array($tags['website']??'',$tags['contact:website']??'',$tags['url']??'',$tags['contact:url']??''));
            $phone=trim((string)($tags['phone']??($tags['contact:phone']??'')));
            $opening=trim((string)($tags['opening_hours']??''));
            $wikidata=trim((string)($tags['wikidata']??''));
            $wikipedia=trim((string)($tags['wikipedia']??''));
            $raw_json=wp_json_encode($tags,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES);
            $provenance=wp_json_encode(array(
                'name'=>'osm','coordinates'=>'osm','address'=>'osm',
                'website'=>isset($tags['website'])||isset($tags['contact:website'])?'osm':'unknown',
                'opening_hours'=>isset($tags['opening_hours'])?'osm':'unknown','normalized_at'=>$now
            ));
            $update=array(
                'name'=>$name,'normalized_name'=>$this->normalize_text($name),
                'city'=>$city,'district'=>$district,'street'=>$street,'house_number'=>$house,'postcode'=>$postcode,
                'phone'=>$phone,'website'=>$website,'opening_hours'=>$opening,'wikidata'=>$wikidata,'wikipedia'=>$wikipedia,
                'primary_category'=>$classification['category'],'primary_subcategory'=>$classification['subcategory'],
                'primary_osm_type'=>(string)$row['current_osm_type'],'primary_osm_id'=>(int)$row['current_osm_id'],
                'raw_tags'=>$raw_json,'field_provenance'=>$provenance,'quality_score'=>$quality,
                'last_seen_at'=>$now,'last_synced_at'=>$now,'updated_at'=>$now
            );
            if($this->valid_coordinate((float)$candidate['lat'],(float)$candidate['lng'])){
                $update['lat']=(float)$candidate['lat'];$update['lng']=(float)$candidate['lng'];
            }
            $wpdb->update($places,$update,array('id'=>(int)$pid));
            $wpdb->query($wpdb->prepare(
                "DELETE FROM $cats WHERE place_id=%d AND source LIKE 'classifier-%%' AND category<>%s",
                (int)$pid,$classification['category']
            ));
            $wpdb->query($wpdb->prepare(
                "INSERT INTO $cats (place_id,category,subcategory,weight,source,updated_at)
                 VALUES (%d,%s,%s,%f,'classifier-v1.10.80',%s)
                 ON DUPLICATE KEY UPDATE subcategory=VALUES(subcategory),weight=VALUES(weight),source=VALUES(source),updated_at=VALUES(updated_at)",
                (int)$pid,$classification['category'],$classification['subcategory'],$classification['weight'],$now
            ));
            $this->ingest_osm_links_and_schedule((int)$pid,$tags,$now);
            $changed++;
        }
        return $changed;
    }

    private function mark_missing_after_snapshot($municipality_slug, $sync_started_at) {
        global $wpdb;
        if (!$municipality_slug || !$sync_started_at) return 0;
        $places = $this->table('places');
        $sources = $this->table('place_sources');
        $now = current_time('mysql', true);
        // Only a fully successful municipality snapshot may hide objects that disappeared
        // from the current relevant OSM set. Partial/failed syncs never call this method.
        return (int) $wpdb->query($wpdb->prepare(
            "UPDATE $places p
             SET p.active=0,p.lifecycle_status='source_missing',p.updated_at=%s
             WHERE p.municipality_slug=%s
               AND p.active=1
               AND NOT EXISTS (
                   SELECT 1 FROM $sources s
                   WHERE s.place_id=p.id AND s.source_type='osm' AND s.last_seen_at >= %s
               )",
            $now, $municipality_slug, $sync_started_at
        ));
    }


    /**
     * V1.2.6: Start a clean retry epoch. "attempts" now reflects attempts since
     * this reliability fix instead of historical development retries.
     */
    public function ensure_retry_fix_state() {
        if ((string)get_option('rg_places_retry_fix_version','') === '1.2.6') return;
        global $wpdb;
        $table=$this->table('places_municipalities');
        $wpdb->query("UPDATE $table SET attempts=0, locked_until=NULL, sync_started_at=NULL, updated_at=UTC_TIMESTAMP()");
        update_option('rg_places_retry_fix_version','1.2.6',false);
    }

    /**
     * V1.2.5: Existing 20k+ catalog remains live while all 53 municipalities
     * are refreshed once with the broadened kiosk/convenience import query.
     */

    /**
     * Separate evidence inventory for "Hier geht's um die Wurst".
     * It intentionally does NOT reclassify Food places.
     */
    public function ensure_wurst_backfill_state() {
        $target='1.3.7';
        $state=get_option('rg_wurst_backfill_state');
        if(is_array($state) && (string)($state['version']??'')===$target) return;
        update_option('rg_wurst_backfill_state',array(
            'version'=>$target,'cursor'=>0,'processed'=>0,'candidates'=>0,
            'done'=>false,'started_at'=>current_time('mysql',true),'finished_at'=>null
        ),false);
    }

    private function wurst_menu_items_from_text($text) {
        $norm=' '.$this->normalize_text((string)$text).' ';
        $map=array(
            'currywurst'=>'currywurst','curry wurst'=>'currywurst',
            'bratwurst'=>'bratwurst','rostbratwurst'=>'bratwurst','brat wurst'=>'bratwurst',
            'mantaplatte'=>'mantaplatte','manta platte'=>'mantaplatte',
            'pommes'=>'pommes','fritten'=>'pommes',
            'schnitzel'=>'schnitzel','jaegerschnitzel'=>'schnitzel','jagerschnitzel'=>'schnitzel',
            'paprikaschnitzel'=>'schnitzel',
            'frikadelle'=>'frikadelle','bulette'=>'frikadelle',
            'schaschlik'=>'schaschlik'
        );
        $out=array();
        foreach($map as $needle=>$item) if(strpos($norm,' '.$this->normalize_text($needle).' ')!==false)$out[]=$item;
        return array_values(array_unique($out));
    }

    private function wurst_profile($tags,$name,$website_evidence=array()) {
        if(!is_array($tags)) $tags=array();

        $amenity=strtolower(trim((string)($tags['amenity']??'')));
        $takeaway=strtolower(trim((string)($tags['takeaway']??'')));
        $cuisine=$this->normalize_text((string)($tags['cuisine']??''));
        $brand=$this->normalize_text((string)($tags['brand']??''));
        $operator=$this->normalize_text((string)($tags['operator']??''));
        $name_norm=$this->normalize_text($name);
        $identity_text=' '.$name_norm.' '.$brand.' '.$operator.' ';
        $cuisine_text=' '.$cuisine.' ';

        $signals=array();
        $exclusions=array();
        $conflicts=array();
        $menu_items=array();
        $score=0;

        // Food-shape is context only. It must never create a Wurst candidate by itself.
        $fast_shape=($amenity==='fast_food' || $takeaway==='only');
        if($amenity==='fast_food') $signals[]='OSM: fast_food';
        if($takeaway==='only') $signals[]='OSM: takeaway only';

        // Absolute business-type exclusions remain absolute.
        if($amenity==='restaurant') $exclusions[]='Restaurant – kein klassischer Imbiss';
        if(in_array($amenity,array('cafe','pub','bar','biergarten','food_court'),true)) $exclusions[]='anderer Gastronomie-Typ';
        if(in_array($amenity,array('theatre','arts_centre','cinema','library','community_centre'),true)) $exclusions[]='fachfremder Kultur-/Freizeitort';

        $chain_terms=array(
            'mcdonalds','mcdonald','burger king','kfc','kentucky fried chicken',
            'subway','five guys','dominos','domino s','pizza hut','l osteria',
            'nordsee','backwerk','kochloeffel','kochloffel'
        );
        foreach($chain_terms as $term) {
            if(strpos($identity_text,' '.$this->normalize_text($term).' ')!==false) {
                $exclusions[]='Systemgastronomie/Kette';
                break;
            }
        }

        // Identity evidence: what kind of place is this?
        $strong_identity=false;
        $classic_identity=false;

        foreach(array('currywurst'=>48,'bratwurst'=>44,'wurstbude'=>44,'wurst'=>34,'curry'=>30) as $term=>$points) {
            if(strpos($identity_text,' '.$this->normalize_text($term).' ')!==false) {
                $score+=$points; $signals[]='Identität/Name: '.$term; $strong_identity=true;
            }
        }
        // Classic Ruhrpott-Imbiss identity. Synonymous name hits form ONE capped family.
        $classic_identity=false;$hut_identity=false;$classic_name_score=0;$classic_name_label='';
        $classic_name_terms=array(
            'wurstgrill'=>32,'currybude'=>32,'metzgergrill'=>30,'grillimbiss'=>30,
            'grillhütte'=>28,'grillhuette'=>28,'imbissbude'=>28,'imbissstube'=>26,
            'pommesbude'=>26,'pommesstube'=>24,'imbisseck'=>24,'grillstation'=>22,
            'brutzelhütte'=>22,'brutzelhuette'=>22,'brutzelbude'=>22,
            'grillhaus'=>18,'imbiss'=>20,'fritten'=>16,'pommes'=>14,
            'schmiede'=>14,'metzger'=>14
        );
        foreach($classic_name_terms as $term=>$points) {
            $needle=$this->normalize_text($term);
            if($needle!=='' && strpos($name_norm,$needle)!==false && $points>$classic_name_score) {
                $classic_name_score=$points;$classic_name_label=$term;
            }
        }
        if($classic_name_score===0 && preg_match('/(?:^|\s)grill(?:\s|$)/u',$name_norm)) {
            $classic_name_score=16;$classic_name_label='grill';
        }
        foreach(array('hütte','huette','bude','stube','klause') as $term) {
            if(strpos($name_norm,$this->normalize_text($term))!==false) {$hut_identity=true;break;}
        }
        if($classic_name_score>0) {
            $score+=$classic_name_score;$signals[]='Identität/Name: '.$classic_name_label;$classic_identity=true;
        }

        // Tier B is deliberately narrow: a concrete classic name indicator is mandatory.
        $b_name_indicator=false;
        foreach(array('hütte','huette','bude','fritten','metzger','brutzel','pommes','schmiede','imbiss') as $term) {
            if(strpos($name_norm,$this->normalize_text($term))!==false) {$b_name_indicator=true;break;}
        }
        if(!$b_name_indicator && preg_match('/(?:^|\s)grill(?:\s|$)/u',$name_norm))$b_name_indicator=true;

        // Cuisine can be strong positive evidence, but cuisine=regional/german alone is not enough.
        foreach(array('currywurst'=>48,'bratwurst'=>44,'sausage'=>42) as $term=>$points) {
            if(strpos($cuisine_text,' '.$this->normalize_text($term).' ')!==false) {
                $score+=$points; $signals[]='Cuisine: '.$term; $strong_identity=true;
                $menu_items[]=$term==='sausage'?'bratwurst':$term;
            }
        }
        foreach(array('german'=>12,'regional'=>12) as $term=>$points) {
            if(strpos($cuisine_text,' '.$term.' ')!==false) {
                $score+=$points; $signals[]='Cuisine: '.$term;
            }
        }

        // Foreign concepts: distinguish explicit identity from cuisine/menu conflicts.
        $foreign=array(
            'doner'=>'Döner/Kebab','doener'=>'Döner/Kebab','kebab'=>'Döner/Kebab','kebap'=>'Döner/Kebab',
            'pizza'=>'Pizza/Pizzeria','pizzeria'=>'Pizza/Pizzeria','italian'=>'italienisches Konzept',
            'sushi'=>'Sushi/Asia','asia'=>'Sushi/Asia','asian'=>'Sushi/Asia','chinese'=>'Sushi/Asia','china'=>'Sushi/Asia',
            'thai'=>'Sushi/Asia','vietnam'=>'Sushi/Asia','vietnamese'=>'Sushi/Asia',
            'indian'=>'indisches Konzept','indisch'=>'indisches Konzept','tandoori'=>'indisches Konzept',
            'falafel'=>'Falafel/Shawarma','shawarma'=>'Falafel/Shawarma','gyros'=>'Gyros/Grieche','greek'=>'Gyros/Grieche'
        );

        foreach($foreign as $term=>$label) {
            $needle=' '.$this->normalize_text($term).' ';
            if(strpos($identity_text,$needle)!==false) {
                $exclusions[]=$label.' als Betriebsidentität';
                break;
            }
        }

        // A foreign cuisine tag is not automatically an exclusion when the name/identity is neutral.
        // It becomes a conflict that requires evidence/review.
        foreach($foreign as $term=>$label) {
            $needle=' '.$this->normalize_text($term).' ';
            if(strpos($cuisine_text,$needle)!==false) {
                $conflicts[]=$label.' in cuisine';
                break;
            }
        }

        // Explicit burger identity is an exclusion; burger merely in cuisine is a conflict.
        if(strpos($identity_text,' burger ')!==false) $exclusions[]='Burger-Konzept als Betriebsidentität';
        elseif(strpos($cuisine_text,' burger ')!==false) $conflicts[]='Burger in cuisine';

        // Menu/source evidence describes dishes only; the existence of a website itself is irrelevant.
        if(is_array($website_evidence) && !empty($website_evidence['menu_items'])) {
            foreach((array)$website_evidence['menu_items'] as $item) $menu_items[]=$item;
            $official_items=array_values(array_unique((array)$website_evidence['menu_items']));
            $wurst_hits=array_intersect($official_items,array('currywurst','bratwurst','mantaplatte'));
            $classic_hits=array_intersect($official_items,array('schnitzel','frikadelle','schaschlik','pommes'));
            if($wurst_hits) $score+=min(28,16+count($wurst_hits)*6);
            elseif($classic_hits) $score+=min(18,8+count($classic_hits)*4);
            $signals[]='Angebots-Evidenz: typische Gerichte bestätigt';
        }

        // Legacy source-based exclusion hints are never hard exclusions. Preserve them as review conflicts only.
        if(is_array($website_evidence) && !empty($website_evidence['exclusion'])) {
            $conflicts[]='Quellen-Hinweis: '.(string)$website_evidence['exclusion'];
        }

        $signals[]='Klassifikation: '.self::WURST_CLASSIFIER_VERSION;
        $menu_items=array_values(array_unique($menu_items));
        $signals=array_values(array_unique($signals));
        $exclusions=array_values(array_unique($exclusions));
        $conflicts=array_values(array_unique($conflicts));

        $has_core_menu=(bool)array_intersect($menu_items,array('currywurst','bratwurst','schnitzel','frikadelle','schaschlik','mantaplatte'));
        $has_wurst_menu=(bool)array_intersect($menu_items,array('currywurst','bratwurst','mantaplatte'));

        // Candidate gate:
        // - explicit/classic identity, or
        // - core dish evidence, or
        // - German/regional fast-food with a meaningful classic name.
        // fast_food alone is deliberately NOT enough.
        $regional=(strpos($cuisine_text,' german ')!==false || strpos($cuisine_text,' regional ')!==false);
        if($hut_identity && ($regional || $fast_shape)) {
            $score+=6;$signals[]='Kontext: Hütte/Bude/Stube + regional/fast_food';$classic_identity=true;
        }
        $candidate=$strong_identity || $classic_identity || $has_core_menu;
        if(!$candidate) return null;

        // Metadata such as website/opening hours is deliberately classification-neutral.
        // It may be displayed or used as a source for enrichment, but contributes 0 points.
        if($fast_shape && ($strong_identity||$classic_identity||$has_core_menu)) $score+=8;

        $score=max(0,min(100,(int)$score));

        // Explicit foreign/chain/restaurant identity wins.
        if($exclusions) {
            return array(
                'score'=>min(95,max(0,(int)$score)),'tier'=>'X','decision'=>'exclude','public_eligible'=>false,
                'signals'=>$signals,'exclusions'=>$exclusions,'conflicts'=>$conflicts,'menu_items'=>$menu_items,
                'audit_reason'=>'X: '.implode(' · ',$exclusions)
            );
        }

        // Conflicting evidence must never be auto-public.
        // It enters B only with a concrete classic name indicator; otherwise U.
        if($conflicts) {
            $signals[]='Konflikt: '.implode(' · ',$conflicts);
            $conflict_tier=$b_name_indicator?'B':'U';
            return array(
                'score'=>min(95,max(0,(int)$score)),'tier'=>$conflict_tier,'decision'=>$b_name_indicator?'review':'research','public_eligible'=>false,
                'signals'=>array_values(array_unique($signals)),'exclusions'=>array(),'conflicts'=>$conflicts,'menu_items'=>$menu_items,
                'audit_reason'=>$b_name_indicator?'B: klassischer Namensindikator, aber widersprüchliche Evidenz':'U: widersprüchliche Evidenz ohne klassischen Namensindikator'
            );
        }

        // Tier decision is semantic, not metadata-driven:
        // A: explicit Wurst/Curry identity OR classic Imbiss identity plus confirmed Wurst/core offer.
        // B: plausible classic identity or dish evidence, but identity/offer still incomplete.
        // X: only positively evidenced exclusion (handled above).
        $identity_safe=$strong_identity || ($classic_identity && $has_wurst_menu);
        $audit_reason='';
        if($identity_safe) {
            $tier='A'; $decision='include'; $public=true;
            $identity_bits=array();
            foreach($signals as $sig) {
                if(strpos($sig,'Identität/Name:')===0 || strpos($sig,'Cuisine: currywurst')===0 ||
                   strpos($sig,'Cuisine: bratwurst')===0 || strpos($sig,'Cuisine: sausage')===0) {
                    $identity_bits[]=$sig;
                }
            }
            $identity_bits=array_values(array_unique($identity_bits));
            if($classic_identity && $has_wurst_menu) {
                $wurst_items=array_values(array_intersect($menu_items,array('currywurst','bratwurst','mantaplatte')));
                $audit_reason='A: '.implode(' + ',$identity_bits).' + Wurstangebot: '.implode(', ',$wurst_items);
            } else {
                $audit_reason='A: '.($identity_bits?implode(' + ',$identity_bits):'explizite Wurst-/Curry-Identität');
            }
        } elseif($b_name_indicator) {
            $tier='B'; $decision='review'; $public=false;
            $audit_reason='B: klassischer Namensindikator'.($classic_name_label!==''?' „'.$classic_name_label.'“':'').' – finale Wurst-Evidenz fehlt';
        } else {
            $tier='U'; $decision='research'; $public=false;
            $signals[]='Unklar: zu wenig positive Identitäts-/Angebotsevidenz';
            $audit_reason='U: kein belastbarer klassischer Namensindikator';
        }

        return array(
            'score'=>min(95,max(0,(int)$score)),'tier'=>$tier,'decision'=>$decision,'public_eligible'=>$public,
            'signals'=>array_values(array_unique($signals)),
            'exclusions'=>array(),'conflicts'=>$conflicts,'menu_items'=>$menu_items,'audit_reason'=>$audit_reason
        );
    }

    private function sync_wurst_candidate_for_place($place_id,$tags,$name) {
        global $wpdb;
        $place_id=absint($place_id);
        if(!$place_id) return false;
        $table=$this->table('wurst_candidates');
        $existing=$wpdb->get_row($wpdb->prepare("SELECT * FROM $table WHERE place_id=%d",$place_id),ARRAY_A);
        $evidence=array();
        if($existing && !empty($existing['evidence_json'])) {
            $decoded=json_decode((string)$existing['evidence_json'],true);
            if(is_array($decoded)) $evidence=$decoded;
        }
        $profile=$this->wurst_profile($tags,$name,$evidence);
        if(!$profile) {
            if($existing) {
                $now=current_time('mysql',true);
                $wpdb->update($table,array(
                    'score'=>0,'tier'=>'U','auto_decision'=>'research','public_eligible'=>0,
                    'signals_json'=>wp_json_encode(array('Klassifikation: '.self::WURST_CLASSIFIER_VERSION,'Unklar: noch kein belastbares Identitätssignal'),JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES),
                    'exclusions_json'=>'[]','audit_reason'=>'U: kein belastbarer klassischer Namensindikator',
                    'menu_items_json'=>'[]','updated_at'=>$now
                ),array('place_id'=>$place_id));
            }
            return false;
        }

        $now=current_time('mysql',true);
        $review=$existing?sanitize_key((string)$existing['review_status']):'auto';
        if(!in_array($review,array('auto','confirmed','rejected'),true)) $review='auto';
        $public=$review==='confirmed'?1:($review==='rejected'?0:(!empty($profile['public_eligible'])?1:0));

        $wpdb->replace($table,array(
            'place_id'=>$place_id,'score'=>(int)$profile['score'],'tier'=>(string)$profile['tier'],
            'auto_decision'=>(string)$profile['decision'],'public_eligible'=>$public,'review_status'=>$review,
            'signals_json'=>wp_json_encode($profile['signals'],JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES),
            'exclusions_json'=>wp_json_encode($profile['exclusions'],JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES),
            'audit_reason'=>substr((string)($profile['audit_reason']??''),0,500),
            'menu_items_json'=>wp_json_encode($profile['menu_items'],JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES),
            'evidence_json'=>wp_json_encode($evidence,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES),
            'website_scan_status'=>$existing?(string)$existing['website_scan_status']:'pending',
            'website_checked_at'=>$existing?$existing['website_checked_at']:null,
            'first_seen_at'=>$existing?$existing['first_seen_at']:$now,'updated_at'=>$now
        ),array('%d','%d','%s','%s','%d','%s','%s','%s','%s','%s','%s','%s','%s','%s','%s'));
        return true;
    }

    private function process_wurst_backfill_batch($limit=250) {
        global $wpdb;
        $state=get_option('rg_wurst_backfill_state');
        if(!is_array($state)) {$this->ensure_wurst_backfill_state();$state=get_option('rg_wurst_backfill_state');}
        if(!empty($state['done'])) return $state;
        $cursor=max(0,(int)($state['cursor']??0));
        $places=$this->table('places');
        $rows=(array)$wpdb->get_results($wpdb->prepare(
            "SELECT id,name,raw_tags FROM $places
             WHERE id>%d AND active=1
               AND (primary_category='food'
                    OR LOCATE('\"amenity\":\"fast_food\"',raw_tags)>0
                    OR LOCATE('\"takeaway\":\"only\"',raw_tags)>0
                    OR LOCATE('currywurst',LOWER(raw_tags))>0
                    OR LOCATE('sausage',LOWER(raw_tags))>0)
             ORDER BY id ASC LIMIT %d",
            $cursor,max(1,min(1000,(int)$limit))
        ),ARRAY_A);

        if(!$rows) {
            $state['done']=true;$state['finished_at']=current_time('mysql',true);
            update_option('rg_wurst_backfill_state',$state,false);
            return $state;
        }
        foreach($rows as $row) {
            $tags=json_decode((string)$row['raw_tags'],true); if(!is_array($tags))$tags=array();
            if($this->sync_wurst_candidate_for_place((int)$row['id'],$tags,(string)$row['name'])) {
                $state['candidates']=(int)($state['candidates']??0)+1;
            }
            $state['processed']=(int)($state['processed']??0)+1;
            $state['cursor']=(int)$row['id'];
        }
        update_option('rg_wurst_backfill_state',$state,false);
        return $state;
    }

    private function wurst_stats() {
        global $wpdb;
        $w=$this->table('wurst_candidates');$places=$this->table('places');
        $row=$wpdb->get_row(
            "SELECT COUNT(*) total,
             SUM(CASE WHEN w.tier='A' THEN 1 ELSE 0 END) tier_a,
             SUM(CASE WHEN w.tier='B' THEN 1 ELSE 0 END) tier_b,
             SUM(CASE WHEN w.tier='C' THEN 1 ELSE 0 END) tier_c,
             SUM(CASE WHEN w.tier='U' THEN 1 ELSE 0 END) tier_u,
             SUM(CASE WHEN w.tier='X' THEN 1 ELSE 0 END) excluded,
             SUM(CASE WHEN w.review_status='confirmed' THEN 1 ELSE 0 END) confirmed,
             SUM(CASE WHEN w.review_status='rejected' THEN 1 ELSE 0 END) rejected,
             SUM(CASE WHEN w.public_eligible=1 THEN 1 ELSE 0 END) public_eligible,
             SUM(CASE WHEN w.website_scan_status='done' THEN 1 ELSE 0 END) website_scanned,
             SUM(CASE WHEN w.website_scan_status='failed' THEN 1 ELSE 0 END) website_failed,
             SUM(CASE WHEN w.website_scan_status='no-website' THEN 1 ELSE 0 END) website_no_website,
             SUM(CASE WHEN w.website_scan_status='pending' AND p.website<>'' AND w.tier<>'X' THEN 1 ELSE 0 END) website_pending,
             SUM(CASE WHEN w.menu_items_json IS NOT NULL AND w.menu_items_json<>'[]' THEN 1 ELSE 0 END) menu_evidence
             FROM $w w INNER JOIN $places p ON p.id=w.place_id WHERE p.active=1",
            ARRAY_A
        );
        $out=array();
        foreach(array('total','tier_a','tier_b','tier_c','tier_u','excluded','confirmed','rejected','public_eligible','website_scanned','website_failed','website_no_website','website_pending','menu_evidence') as $key) $out[$key]=(int)($row[$key]??0);
        return $out;
    }

    private function wurst_audit_filters_from_request() {
        $tier_raw=sanitize_key((string)($_GET['wurst_tier']??'all'));
        $tier=$tier_raw==='all'?'all':strtoupper($tier_raw);
        if(!in_array($tier,array('all','A','B','C','U','X'),true)) $tier='all';

        $review=sanitize_key((string)($_GET['wurst_review']??'all'));
        if(!in_array($review,array('all','auto','confirmed','rejected'),true)) $review='all';

        $city=sanitize_text_field(wp_unslash((string)($_GET['wurst_city']??'')));
        $search=sanitize_text_field(wp_unslash((string)($_GET['wurst_search']??'')));
        $menu=sanitize_key((string)($_GET['wurst_menu']??'all'));
        $allowed_menu=array('all','currywurst','bratwurst','pommes','schnitzel','frikadelle','schaschlik','mantaplatte','none');
        if(!in_array($menu,$allowed_menu,true)) $menu='all';

        $website=sanitize_key((string)($_GET['wurst_website']??'all'));
        if(!in_array($website,array('all','done','failed','pending','has_website','no_website'),true)) $website='all';

        return array('tier'=>$tier,'review'=>$review,'city'=>$city,'search'=>$search,'menu'=>$menu,'website'=>$website);
    }

    private function wurst_audit_cities() {
        global $wpdb;
        $w=$this->table('wurst_candidates');$places=$this->table('places');
        return (array)$wpdb->get_col(
            "SELECT DISTINCT p.city FROM $w w INNER JOIN $places p ON p.id=w.place_id
             WHERE p.active=1 AND p.city<>'' ORDER BY p.city ASC"
        );
    }

    private function wurst_admin_rows($filters=array(),$limit=120) {
        global $wpdb;
        $w=$this->table('wurst_candidates');$places=$this->table('places');

        $where=array("p.active=1");
        $params=array();

        if(!empty($filters['tier']) && $filters['tier']!=='all') {
            $where[]="w.tier=%s"; $params[]=$filters['tier'];
        }
        if(!empty($filters['review']) && $filters['review']!=='all') {
            $where[]="w.review_status=%s"; $params[]=$filters['review'];
        }
        if(!empty($filters['city'])) {
            $where[]="p.city=%s"; $params[]=$filters['city'];
        }
        if(!empty($filters['search'])) {
            $like='%'.$wpdb->esc_like($filters['search']).'%';
            $where[]="(p.name LIKE %s OR p.street LIKE %s OR p.city LIKE %s OR p.raw_tags LIKE %s)";
            array_push($params,$like,$like,$like,$like);
        }
        if(!empty($filters['menu']) && $filters['menu']!=='all') {
            if($filters['menu']==='none') {
                $where[]="(w.menu_items_json IS NULL OR w.menu_items_json='' OR w.menu_items_json='[]')";
            } else {
                $like='%'.esc_sql($filters['menu']).'%';
                $where[]="w.menu_items_json LIKE %s"; $params[]=$like;
            }
        }
        if(!empty($filters['website']) && $filters['website']!=='all') {
            if($filters['website']==='has_website') {
                $where[]="p.website<>''";
            } elseif($filters['website']==='no_website') {
                $where[]="(p.website IS NULL OR p.website='')";
            } elseif($filters['website']==='pending') {
                $where[]="w.website_scan_status='pending' AND p.website<>'' AND w.tier<>'X'";
            } else {
                $where[]="w.website_scan_status=%s"; $params[]=$filters['website'];
            }
        }

        $sql="SELECT w.*,p.name,p.city,p.street,p.house_number,p.website,p.opening_hours,p.raw_tags,p.primary_subcategory
              FROM $w w INNER JOIN $places p ON p.id=w.place_id
              WHERE ".implode(' AND ',$where)."
              ORDER BY FIELD(w.review_status,'auto','confirmed','rejected'),
                       FIELD(w.tier,'A','B','C','X'),w.score DESC,p.name ASC LIMIT %d";
        $params[]=max(1,min(3000,(int)$limit));
        return (array)$wpdb->get_results($wpdb->prepare($sql,$params),ARRAY_A);
    }

    private function wurst_audit_count($filters=array()) {
        global $wpdb;
        $w=$this->table('wurst_candidates');$places=$this->table('places');
        $where=array("p.active=1");
        $params=array();

        if(!empty($filters['tier']) && $filters['tier']!=='all') {$where[]="w.tier=%s";$params[]=$filters['tier'];}
        if(!empty($filters['review']) && $filters['review']!=='all') {$where[]="w.review_status=%s";$params[]=$filters['review'];}
        if(!empty($filters['city'])) {$where[]="p.city=%s";$params[]=$filters['city'];}
        if(!empty($filters['search'])) {
            $like='%'.$wpdb->esc_like($filters['search']).'%';
            $where[]="(p.name LIKE %s OR p.street LIKE %s OR p.city LIKE %s OR p.raw_tags LIKE %s)";
            array_push($params,$like,$like,$like,$like);
        }
        if(!empty($filters['menu']) && $filters['menu']!=='all') {
            if($filters['menu']==='none') $where[]="(w.menu_items_json IS NULL OR w.menu_items_json='' OR w.menu_items_json='[]')";
            else {$where[]="w.menu_items_json LIKE %s";$params[]='%'.$wpdb->esc_like($filters['menu']).'%';}
        }
        if(!empty($filters['website']) && $filters['website']!=='all') {
            if($filters['website']==='has_website') $where[]="p.website<>''";
            elseif($filters['website']==='no_website') $where[]="(p.website IS NULL OR p.website='')";
            elseif($filters['website']==='pending') $where[]="w.website_scan_status='pending' AND p.website<>'' AND w.tier<>'X'";
            else {$where[]="w.website_scan_status=%s";$params[]=$filters['website'];}
        }

        $sql="SELECT COUNT(*) FROM $w w INNER JOIN $places p ON p.id=w.place_id WHERE ".implode(' AND ',$where);
        return $params ? (int)$wpdb->get_var($wpdb->prepare($sql,$params)) : (int)$wpdb->get_var($sql);
    }


    private function wurst_reclass_state() {
        $s=get_option(self::WURST_RECLASS_STATE_OPTION,array());
        return wp_parse_args(is_array($s)?$s:array(),array('done'=>false,'cursor'=>0,'processed'=>0,'changed'=>0,'classifier'=>self::WURST_CLASSIFIER_VERSION));
    }

    private function wurst_reclass_reset_state() {
        $s=array('done'=>false,'cursor'=>0,'processed'=>0,'changed'=>0,'classifier'=>self::WURST_CLASSIFIER_VERSION);
        update_option(self::WURST_RECLASS_STATE_OPTION,$s,false);
        delete_option(self::WURST_CLASSIFIER_APPLIED_OPTION);
        return $s;
    }

    private function process_wurst_reclass_batch($limit=300) {
        global $wpdb;
        $s=$this->wurst_reclass_state();
        if(!empty($s['done']) && $s['classifier']===self::WURST_CLASSIFIER_VERSION) return $s;
        $places=$this->table('places'); $w=$this->table('wurst_candidates');
        $rows=(array)$wpdb->get_results($wpdb->prepare(
            "SELECT id,name,website,raw_tags FROM $places
             WHERE id>%d AND active=1
               AND (primary_category='food'
                    OR LOCATE('\"amenity\":\"fast_food\"',raw_tags)>0
                    OR LOCATE('\"takeaway\":\"only\"',raw_tags)>0
                    OR LOCATE('currywurst',LOWER(raw_tags))>0
                    OR LOCATE('sausage',LOWER(raw_tags))>0)
             ORDER BY id ASC LIMIT %d",
            (int)$s['cursor'],max(1,min(600,(int)$limit))
        ),ARRAY_A);
        if(!$rows) {
            $s['done']=true;
            update_option(self::WURST_RECLASS_STATE_OPTION,$s,false);
            update_option(self::WURST_CLASSIFIER_APPLIED_OPTION,self::WURST_CLASSIFIER_VERSION,false);
            return $s;
        }
        foreach($rows as $row) {
            $id=(int)$row['id'];
            $before=$wpdb->get_row($wpdb->prepare("SELECT * FROM $w WHERE place_id=%d",$id),ARRAY_A);
            $tags=json_decode((string)$row['raw_tags'],true); if(!is_array($tags))$tags=array();
            if(!empty($row['website']) && empty($tags['website']))$tags['website']=$row['website'];
            $evidence=array();
            if($before) {
                $e=json_decode((string)($before['website_evidence_json']??''),true); if(is_array($e))$evidence=$e;
                $m=json_decode((string)($before['menu_items_json']??''),true); if(is_array($m)&&$m)$evidence['menu_items']=$m;
            }
            $profile=$this->wurst_profile($tags,(string)$row['name'],$evidence);
            $old_signature=$before?implode('|',array($before['tier'],$before['score'],$before['auto_decision'],$before['signals_json'],$before['exclusions_json'])):'';
            if($profile) {
                $now=current_time('mysql',true);
                $data=array(
                    'score'=>(int)$profile['score'],'tier'=>$profile['tier'],'auto_decision'=>$profile['decision'],
                    'public_eligible'=>$profile['public_eligible']?1:0,
                    'signals_json'=>wp_json_encode($profile['signals'],JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES),
                    'exclusions_json'=>wp_json_encode($profile['exclusions'],JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES),
                    'audit_reason'=>substr((string)($profile['audit_reason']??''),0,500),
                    'menu_items_json'=>wp_json_encode($profile['menu_items'],JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES),
                    'updated_at'=>$now
                );
                if($before) {
                    $wpdb->update($w,$data,array('place_id'=>$id));
                } else {
                    $data['place_id']=$id;$data['review_status']='auto';
                    $data['website_scan_status']=empty($row['website'])?'no-website':'pending';
                    $data['website_evidence_json']='{}';$data['first_seen_at']=$now;
                    $wpdb->insert($w,$data);
                }
            } elseif($before) {
                $wpdb->update($w,array(
                    'score'=>0,'tier'=>'U','auto_decision'=>'research','public_eligible'=>0,
                    'signals_json'=>wp_json_encode(array('Klassifikation: '.self::WURST_CLASSIFIER_VERSION,'Unklar: noch kein belastbares Identitätssignal'),JSON_UNESCAPED_UNICODE),
                    'exclusions_json'=>'[]',
                    'updated_at'=>current_time('mysql',true)
                ),array('place_id'=>$id));
            }
            $after=$wpdb->get_row($wpdb->prepare("SELECT tier,score,auto_decision,signals_json,exclusions_json FROM $w WHERE place_id=%d",$id),ARRAY_A);
            $new_signature=$after?implode('|',$after):'';
            if($old_signature!==$new_signature)$s['changed']++;
            $s['processed']++;$s['cursor']=$id;
        }
        update_option(self::WURST_RECLASS_STATE_OPTION,$s,false);
        return $s;
    }

    public function ajax_wurst_reclass_batch() {
        if(!current_user_can('manage_options'))wp_send_json_error(array('message'=>'forbidden'),403);
        check_ajax_referer(self::ADMIN_NONCE_ACTION,'nonce');
        wp_send_json_success(array('state'=>$this->process_wurst_reclass_batch(300),'stats'=>$this->wurst_stats()));
    }

