    private function wurst_b_enrich_state() {
        $s=get_option(self::WURST_B_ENRICH_STATE_OPTION,array());
        return wp_parse_args(is_array($s)?$s:array(),array(
            'done'=>false,'cursor'=>0,'processed'=>0,'promoted_a'=>0,'excluded_x'=>0,'still_b'=>0
        ));
    }

    private function wurst_b_enrich_reset_state() {
        $s=array('done'=>false,'cursor'=>0,'processed'=>0,'promoted_a'=>0,'excluded_x'=>0,'still_b'=>0);
        update_option(self::WURST_B_ENRICH_STATE_OPTION,$s,false); return $s;
    }

    private function process_wurst_b_enrich_batch($limit=4) {
        global $wpdb;
        $w=$this->table('wurst_candidates');$places=$this->table('places');
        $s=$this->wurst_b_enrich_state();
        if(!empty($s['done'])) return $s;

        $rows=(array)$wpdb->get_results($wpdb->prepare(
            "SELECT w.*,p.name,p.website,p.raw_tags
             FROM $w w INNER JOIN $places p ON p.id=w.place_id
             WHERE p.active=1 AND w.tier='B' AND w.review_status<>'rejected'
               AND p.website<>'' AND w.place_id>%d
             ORDER BY w.place_id ASC LIMIT %d",
            (int)$s['cursor'],max(1,min(8,(int)$limit))
        ),ARRAY_A);

        if(!$rows) {
            $s['done']=true;
            $s['still_b']=(int)$wpdb->get_var("SELECT COUNT(*) FROM $w WHERE tier='B'");
            update_option(self::WURST_B_ENRICH_STATE_OPTION,$s,false); return $s;
        }

        foreach($rows as $row) {
            $id=(int)$row['place_id']; $s['cursor']=$id;
            $evidence=$this->wurst_scan_official_website($row);
            $wpdb->update($w,array(
                'evidence_json'=>wp_json_encode($evidence,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES),
                'website_scan_status'=>(string)$evidence['status'],
                'website_checked_at'=>current_time('mysql',true),'updated_at'=>current_time('mysql',true)
            ),array('place_id'=>$id));

            $tags=json_decode((string)$row['raw_tags'],true); if(!is_array($tags))$tags=array();
            $this->sync_wurst_candidate_for_place($id,$tags,(string)$row['name']);
            $tier=(string)$wpdb->get_var($wpdb->prepare("SELECT tier FROM $w WHERE place_id=%d",$id));
            $s['processed']++;
            if($tier==='A')$s['promoted_a']++;
            elseif($tier==='X')$s['excluded_x']++;
        }
        $s['still_b']=(int)$wpdb->get_var("SELECT COUNT(*) FROM $w WHERE tier='B'");
        update_option(self::WURST_B_ENRICH_STATE_OPTION,$s,false); return $s;
    }

    public function ajax_wurst_b_enrich_batch() {
        if(!current_user_can('manage_options'))wp_send_json_error(array('message'=>'forbidden'),403);
        check_ajax_referer(self::ADMIN_NONCE_ACTION,'nonce');
        wp_send_json_success(array('state'=>$this->process_wurst_b_enrich_batch(4),'stats'=>$this->wurst_stats()));
    }

