    private function wurst_same_host_url($base,$href) {
        $href=html_entity_decode(trim((string)$href),ENT_QUOTES,'UTF-8');
        if($href===''||strpos($href,'#')===0||stripos($href,'mailto:')===0||stripos($href,'tel:')===0) return '';
        $bp=wp_parse_url($base); if(!$bp||empty($bp['host'])) return '';
        if(preg_match('#^https?://#i',$href)) {
            $hp=wp_parse_url($href);
            if(!$hp||empty($hp['host'])||strtolower($hp['host'])!==strtolower($bp['host'])) return '';
            return esc_url_raw($href);
        }
        if(strpos($href,'//')===0) return '';
        $root=($bp['scheme']??'https').'://'.$bp['host'].(!empty($bp['port'])?':'.$bp['port']:'');
        return esc_url_raw($root.'/'.ltrim($href,'/'));
    }

    private function wurst_scan_official_website($row) {
        $url=esc_url_raw((string)($row['website']??''));
        if(!$url) return array('status'=>'no-website','menu_items'=>array(),'source_urls'=>array());
        $response=wp_remote_get($url,array(
            'timeout'=>10,'redirection'=>3,
            'headers'=>array('User-Agent'=>'RuhrpottGuru-Places/1.4.9 (+https://www.ruhrpottguru.de/)')
        ));
        if(is_wp_error($response)||wp_remote_retrieve_response_code($response)<200||wp_remote_retrieve_response_code($response)>=400) {
            return array('status'=>'failed','menu_items'=>array(),'source_urls'=>array($url));
        }
        $body=(string)wp_remote_retrieve_body($response);
        $texts=array(wp_strip_all_tags($body,true));$source_urls=array($url);

        if(preg_match_all("~<a[^>]+href=[\"']([^\"']+)[\"'][^>]*>(.*?)</a>~is",$body,$matches,PREG_SET_ORDER)) {
            foreach($matches as $m) {
                $label=$this->normalize_text(wp_strip_all_tags($m[2],true).' '.$m[1]);
                if(strpos($label,'speisekarte')===false && strpos($label,'menu')===false && strpos($label,'karte')===false) continue;
                $menu_url=$this->wurst_same_host_url($url,$m[1]);
                if(!$menu_url||$menu_url===$url) continue;
                $mres=wp_remote_get($menu_url,array(
                    'timeout'=>10,'redirection'=>3,
                    'headers'=>array('User-Agent'=>'RuhrpottGuru-Places/1.4.9 (+https://www.ruhrpottguru.de/)')
                ));
                if(!is_wp_error($mres)&&wp_remote_retrieve_response_code($mres)>=200&&wp_remote_retrieve_response_code($mres)<400) {
                    $texts[]=wp_strip_all_tags((string)wp_remote_retrieve_body($mres),true);
                    $source_urls[]=$menu_url;
                }
                break;
            }
        }

        $combined=implode(' ',$texts);
        $items=$this->wurst_menu_items_from_text($combined);
        return array(
            'status'=>'done','menu_items'=>$items,
            'source_urls'=>array_values(array_unique($source_urls)),
            // 1.3.7: dishes on a menu are not treated as business identity.
            'exclusion'=>''
        );
    }

    private function process_wurst_website_batch($limit=3) {
        global $wpdb;
        $w=$this->table('wurst_candidates');$places=$this->table('places');
        $rows=(array)$wpdb->get_results($wpdb->prepare(
            "SELECT w.*,p.name,p.website,p.raw_tags
             FROM $w w INNER JOIN $places p ON p.id=w.place_id
             WHERE p.active=1 AND p.website<>'' AND w.tier<>'X'
               AND w.website_scan_status='pending'
             ORDER BY w.score DESC,w.place_id ASC LIMIT %d",
             max(1,min(10,(int)$limit))
        ),ARRAY_A);
        foreach($rows as $row) {
            $evidence=$this->wurst_scan_official_website($row);
            $wpdb->update($w,array(
                'evidence_json'=>wp_json_encode($evidence,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES),
                'website_scan_status'=>(string)$evidence['status'],
                'website_checked_at'=>current_time('mysql',true),'updated_at'=>current_time('mysql',true)
            ),array('place_id'=>(int)$row['place_id']));
            $tags=json_decode((string)$row['raw_tags'],true); if(!is_array($tags))$tags=array();
            $this->sync_wurst_candidate_for_place((int)$row['place_id'],$tags,(string)$row['name']);
        }
        $remaining=(int)$wpdb->get_var(
            "SELECT COUNT(*) FROM $w w INNER JOIN $places p ON p.id=w.place_id
             WHERE p.active=1 AND p.website<>'' AND w.tier<>'X'
               AND w.website_scan_status='pending'"
        );
        return array('processed'=>count($rows),'remaining'=>$remaining);
    }

    public function ajax_wurst_website_enrich_batch() {
        if(!current_user_can('manage_options')) wp_send_json_error(array('message'=>'forbidden'),403);
        check_ajax_referer(self::ADMIN_NONCE_ACTION,'nonce');
        wp_send_json_success(array('run'=>$this->process_wurst_website_batch(3),'stats'=>$this->wurst_stats()));
    }

    public function ajax_wurst_bulk_review() {
        global $wpdb;
        if(!current_user_can('manage_options')) wp_send_json_error(array('message'=>'Keine Berechtigung.'),403);
        check_ajax_referer(self::ADMIN_NONCE_ACTION,'nonce');

        $ids=isset($_POST['ids'])?(array)$_POST['ids']:array();
        $ids=array_values(array_unique(array_filter(array_map('absint',$ids))));
        $decision=sanitize_key((string)($_POST['decision']??''));
        if(!$ids || !in_array($decision,array('confirmed','rejected','auto'),true)) {
            wp_send_json_error(array('message'=>'Ungültige Auswahl.'),400);
        }

        $w=$this->table('wurst_candidates');
        $changed=0;
        foreach($ids as $place_id) {
            $row=$wpdb->get_row($wpdb->prepare("SELECT tier,auto_decision FROM $w WHERE place_id=%d",$place_id),ARRAY_A);
            if(!$row) continue;
            $public=$decision==='confirmed'?1:($decision==='rejected'?0:(($row['tier']==='A'&&$row['auto_decision']==='include')?1:0));
            $r=$wpdb->update($w,array(
                'review_status'=>$decision,
                'public_eligible'=>$public,
                'updated_at'=>current_time('mysql',true)
            ),array('place_id'=>$place_id));
            if($r!==false) $changed++;
        }
        wp_send_json_success(array('changed'=>$changed));
    }

    public function admin_review_wurst() {
        if(!current_user_can('manage_options')) wp_die('Keine Berechtigung.');
        check_admin_referer('rg_places_review_wurst');
        global $wpdb;
        $place_id=absint($_POST['place_id']??0);
        $decision=sanitize_key((string)($_POST['decision']??'auto'));
        if(!in_array($decision,array('confirmed','rejected','auto'),true)) $decision='auto';
        $w=$this->table('wurst_candidates');
        $row=$wpdb->get_row($wpdb->prepare("SELECT tier,auto_decision FROM $w WHERE place_id=%d",$place_id),ARRAY_A);
        if($row) {
            $public=$decision==='confirmed'?1:($decision==='rejected'?0:(($row['tier']==='A'&&$row['auto_decision']==='include')?1:0));
            $wpdb->update($w,array(
                'review_status'=>$decision,'public_eligible'=>$public,'updated_at'=>current_time('mysql',true)
            ),array('place_id'=>$place_id));
        }
        $args=array('page'=>'ruhrpottguru-places','rg_wurst_reviewed'=>1);
        foreach(array('wurst_tier','wurst_city','wurst_menu','wurst_review','wurst_website','wurst_search') as $key) {
            if(isset($_POST[$key]) && (string)$_POST[$key]!=='') $args[$key]=sanitize_text_field(wp_unslash((string)$_POST[$key]));
        }
        wp_safe_redirect(add_query_arg($args,admin_url('tools.php')).'#rg-wurst-audit');
        exit;
    }

    public function ensure_buedchen_refresh_wave() {
        $target = '1.2.5';
        if ((string) get_option('rg_places_buedchen_import_version', '') === $target) return;
        global $wpdb;
        $table = $this->table('places_municipalities');
        // Keep status=complete: this is a refresh wave, never a destructive re-bootstrap.
        $wpdb->query("UPDATE $table
                      SET last_synced_at=NULL, locked_until=NULL, sync_started_at=NULL, updated_at=UTC_TIMESTAMP()
                      WHERE status='complete'");
        update_option('rg_places_buedchen_import_version', $target, false);
        update_option('rg_places_buedchen_refresh_started_at', current_time('mysql', true), false);
    }

