    /**
     * Activities 1.10.89: read-only progress view for the explicit 53-city
     * Source-Coverage refresh. A municipality counts as completed only after a
     * successful refresh whose last_synced_at is newer than this wave's start.
     */
    private function activity_source_coverage_state_v1089() {
        global $wpdb;
        $table=$this->table('places_municipalities');
        $state=get_option(self::ACTIVITY_COVERAGE_STATE,array());
        if(!is_array($state))$state=array();
        $status=sanitize_key((string)($state['status']??'idle'));
        if(!in_array($status,array('idle','queued','running','complete'),true))$status='idle';
        $started=trim((string)($state['started_at']??''));
        $total=(int)$wpdb->get_var("SELECT COUNT(*) FROM $table");
        $completed=0;$errors=0;$active=0;
        $now=current_time('mysql',true);
        if($started!==''){
            $completed=(int)$wpdb->get_var($wpdb->prepare(
                "SELECT COUNT(*) FROM $table WHERE status='complete' AND last_synced_at IS NOT NULL AND last_synced_at >= %s",
                $started
            ));
            $errors=(int)$wpdb->get_var($wpdb->prepare(
                "SELECT COUNT(*) FROM $table WHERE status='complete' AND updated_at >= %s AND COALESCE(last_error,'')<>'' AND (last_synced_at IS NULL OR last_synced_at < %s)",
                $started,$started
            ));
        }
        $active=(int)$wpdb->get_var($wpdb->prepare(
            "SELECT COUNT(*) FROM $table WHERE sync_started_at IS NOT NULL AND locked_until IS NOT NULL AND locked_until >= %s",
            $now
        ));
        return array(
            'status'=>$status,
            'requestedAt'=>(string)($state['requested_at']??''),
            'startedAt'=>$started,
            'completedAt'=>(string)($state['completed_at']??''),
            'lastCity'=>(string)($state['last_city']??''),
            'lastTickAt'=>(string)($state['last_tick_at']??''),
            'lastResult'=>(string)($state['last_result']??''),
            'total'=>$total,
            'completed'=>$completed,
            'remaining'=>max(0,$total-$completed),
            'errors'=>$errors,
            'active'=>$active,
        );
    }

    private function schedule_activity_source_coverage_tick_v1089($delay=180) {
        $delay=max(5,(int)$delay);
        if(!wp_next_scheduled(self::ACTIVITY_COVERAGE_HOOK)){
            wp_schedule_single_event(time()+$delay,self::ACTIVITY_COVERAGE_HOOK);
        }
        if($delay<=10 && function_exists('spawn_cron'))spawn_cron();
    }


    public function ensure_activity_source_coverage_worker_v1089() {
        $state=get_option(self::ACTIVITY_COVERAGE_STATE,array());
        if(!is_array($state))return;
        if(in_array(sanitize_key((string)($state['status']??'')),array('queued','running'),true) && !wp_next_scheduled(self::ACTIVITY_COVERAGE_HOOK)){
            $this->schedule_activity_source_coverage_tick_v1089(30);
        }
    }

    /**
     * Activities 1.10.90: while the explicit Source-Coverage wave owns the
     * municipality refresh lane, the generic 15-minute Places cron must not
     * claim a second city. The persisted 1.10.89 state/hook names are kept on
     * purpose so an already running wave continues with its existing progress.
     */
    private function activity_source_coverage_owns_refresh_lane_v1090() {
        $state=get_option(self::ACTIVITY_COVERAGE_STATE,array());
        if(!is_array($state))return false;
        return in_array(
            sanitize_key((string)($state['status']??'')),
            array('queued','running'),
            true
        );
    }

    public function admin_activity_source_coverage_start_v1089() {
        if(!current_user_can('manage_options'))wp_die('Keine Berechtigung.');
        check_admin_referer('rg_places_activity_source_coverage_start_v1089');
        $current=$this->activity_source_coverage_state_v1089();
        if(in_array((string)$current['status'],array('queued','running'),true) && (int)$current['remaining']>0){
            $notice='already-running';
        }else{
            $now=current_time('mysql',true);
            update_option(self::ACTIVITY_COVERAGE_STATE,array(
                'status'=>'queued','requested_at'=>$now,'started_at'=>'','completed_at'=>'',
                'last_city'=>'','last_tick_at'=>'','last_result'=>'queued','version'=>self::VERSION,
            ),false);
            wp_clear_scheduled_hook(self::ACTIVITY_COVERAGE_HOOK);
            $this->schedule_activity_source_coverage_tick_v1089(5);
            $notice='started';
        }
        wp_safe_redirect(add_query_arg(array('page'=>'ruhrpottguru-places','rg_activity_coverage_notice'=>$notice),admin_url('tools.php')).'#rg-activities-v2');
        exit;
    }

    /**
     * Dedicated, server-side wave driver. It reuses the established municipality
     * refresh path and never changes status=complete to a destructive bootstrap
     * state. Before starting the wave it waits for an already running municipality
     * sync, so the explicit coverage pass does not trample a normal refresh.
     */
    public function cron_activity_source_coverage_tick_v1089() {
        global $wpdb;
        $table=$this->table('places_municipalities');
        $state=get_option(self::ACTIVITY_COVERAGE_STATE,array());
        if(!is_array($state))return;
        $status=sanitize_key((string)($state['status']??''));
        if(!in_array($status,array('queued','running'),true))return;
        $now=current_time('mysql',true);
        $active=(int)$wpdb->get_var($wpdb->prepare(
            "SELECT COUNT(*) FROM $table WHERE sync_started_at IS NOT NULL AND locked_until IS NOT NULL AND locked_until >= %s",
            $now
        ));
        if($active>0){
            $state['last_tick_at']=$now;$state['last_result']='waiting-for-active-sync';
            update_option(self::ACTIVITY_COVERAGE_STATE,$state,false);
            $this->schedule_activity_source_coverage_tick_v1089(180);
            return;
        }
        if($status==='queued'){
            // One controlled non-destructive wave: all currently complete cities
            // become due, while their public catalogue status remains complete.
            $wpdb->query("UPDATE $table
                          SET last_synced_at=NULL, locked_until=NULL, sync_started_at=NULL, last_error=NULL, updated_at=UTC_TIMESTAMP()
                          WHERE status='complete'");
            $state['status']='running';$state['started_at']=$now;$state['last_tick_at']=$now;$state['last_result']='wave-started';
            update_option(self::ACTIVITY_COVERAGE_STATE,$state,false);
        }
        if(get_option(self::OPTION_STATUS)!=='ready'){
            $state['last_tick_at']=$now;$state['last_result']='waiting-for-ready-catalog';
            update_option(self::ACTIVITY_COVERAGE_STATE,$state,false);
            $this->schedule_activity_source_coverage_tick_v1089(300);
            return;
        }
        $municipality=$this->claim_next_municipality(true);
        if($municipality){
            $ok=$this->server_sync_municipality($municipality,'refresh');
            $state=get_option(self::ACTIVITY_COVERAGE_STATE,$state);if(!is_array($state))$state=array();
            $state['status']='running';$state['last_city']=(string)($municipality['name']??$municipality['slug']??'');
            $state['last_tick_at']=current_time('mysql',true);$state['last_result']=$ok?'success':'retry-pending';
            update_option(self::ACTIVITY_COVERAGE_STATE,$state,false);
        }
        $progress=$this->activity_source_coverage_state_v1089();
        if((int)$progress['total']>0 && (int)$progress['remaining']===0){
            $state=get_option(self::ACTIVITY_COVERAGE_STATE,array());if(!is_array($state))$state=array();
            $state['status']='complete';$state['completed_at']=current_time('mysql',true);$state['last_result']='complete';
            update_option(self::ACTIVITY_COVERAGE_STATE,$state,false);
            wp_clear_scheduled_hook(self::ACTIVITY_COVERAGE_HOOK);
            return;
        }
        $this->schedule_activity_source_coverage_tick_v1089($municipality?180:300);
    }

    /**
     * Score whether an OSM kiosk/convenience record is likely to be a Ruhrgebiet
     * Büdchen/Trinkhalle. Tier A/B may later appear publicly; C stays inventory-only.
     * This is cultural confidence, not a star rating.
     */
    private function buedchen_profile($tags, $name) {
        $shop = strtolower(trim((string)($tags['shop'] ?? '')));
        if (!in_array($shop, array('kiosk','convenience'), true)) return null;

        $score = $shop === 'kiosk' ? 60 : 34;
        $signals = array($shop === 'kiosk' ? 'OSM: kiosk' : 'OSM: convenience');
        $lower = $this->normalize_text($name);

        $strong_names = array('trinkhalle'=>30, 'büdchen'=>28, 'buedchen'=>28, 'bude'=>22);
        foreach ($strong_names as $word=>$points) {
            if (strpos($lower, $word) !== false) {
                $score += $points;
                $signals[] = 'Name: ' . $word;
                break;
            }
        }
        if (strpos($lower, 'kiosk') !== false) {
            $score += 12;
            $signals[] = 'Name: kiosk';
        }
        if (strpos($lower, 'späti') !== false || strpos($lower, 'spaeti') !== false) {
            $score += 8;
            $signals[] = 'Name: späti';
        }

        if (!empty($tags['opening_hours'])) { $score += 5; $signals[] = 'Öffnungszeiten'; }
        if (($tags['tobacco'] ?? '') === 'yes') { $score += 5; $signals[] = 'Tabak'; }
        if (($tags['lottery'] ?? '') === 'yes') { $score += 5; $signals[] = 'Lotto'; }
        if (($tags['drink:coffee'] ?? '') === 'yes' || ($tags['coffee'] ?? '') === 'yes') { $score += 4; $signals[] = 'Kaffee'; }
        if (($tags['outdoor_seating'] ?? '') === 'yes' || ($tags['seating'] ?? '') === 'yes') { $score += 4; $signals[] = 'Sitzgelegenheiten'; }
        if (($tags['parcel_pickup'] ?? '') === 'yes' || ($tags['post_office'] ?? '') === 'yes' || !empty($tags['parcel_mail_in'])) { $score += 2; $signals[] = 'Paketservice'; }

        // Negative evidence: convenience/fuel/station chains are candidates at most,
        // never automatically promoted as authentic Büdchen.
        $brand = $this->normalize_text((string)($tags['brand'] ?? ''));
        $operator = $this->normalize_text((string)($tags['operator'] ?? ''));
        $chain_text = trim($lower . ' ' . $brand . ' ' . $operator);
        $chain_terms = array('rewe to go','service store db','servicestore db','yormas','aral','shell','esso','totalenergies','star tankstelle','jet tankstelle');
        foreach ($chain_terms as $term) {
            if (strpos($chain_text, $term) !== false) {
                $score -= 28;
                $signals[] = 'Ketten-/Tankstellensignal';
                break;
            }
        }
        if (($tags['amenity'] ?? '') === 'fuel') { $score -= 35; $signals[] = 'Tankstelle'; }
        if (($tags['railway'] ?? '') === 'station' || ($tags['public_transport'] ?? '') === 'station') { $score -= 12; $signals[] = 'Bahnhofsumfeld'; }

        $score = max(0, min(100, (int)$score));
        $tier = $score >= 72 ? 'A' : ($score >= 50 ? 'B' : 'C');

        return array(
            'score' => $score,
            'tier' => $tier,
            'signals' => array_values(array_unique($signals)),
            'shop' => $shop,
        );
    }

    private function buedchen_admin_stats() {
        global $wpdb;
        $places = $this->table('places');
        $total = (int)$wpdb->get_var("SELECT COUNT(*) FROM $places WHERE active=1 AND primary_category='buedchen'");
        $a = (int)$wpdb->get_var("SELECT COUNT(*) FROM $places WHERE active=1 AND primary_category='buedchen' AND LOCATE('\"rg:buedchen_tier\":\"A\"',raw_tags)>0");
        $b = (int)$wpdb->get_var("SELECT COUNT(*) FROM $places WHERE active=1 AND primary_category='buedchen' AND LOCATE('\"rg:buedchen_tier\":\"B\"',raw_tags)>0");
        $c = max(0, $total - $a - $b);
        $opening = (int)$wpdb->get_var("SELECT COUNT(*) FROM $places WHERE active=1 AND primary_category='buedchen' AND opening_hours<>''");
        $website = (int)$wpdb->get_var("SELECT COUNT(*) FROM $places WHERE active=1 AND primary_category='buedchen' AND website<>''");
        return array('total'=>$total,'A'=>$a,'B'=>$b,'C'=>$c,'openingHours'=>$opening,'website'=>$website);
    }

    private function buedchen_admin_municipality_rows() {
        global $wpdb;
        $places = $this->table('places');
        return (array)$wpdb->get_results(
            "SELECT municipality_slug,
                    MAX(city) city,
                    COUNT(*) total,
                    SUM(CASE WHEN LOCATE('\"rg:buedchen_tier\":\"A\"',raw_tags)>0 THEN 1 ELSE 0 END) tier_a,
                    SUM(CASE WHEN LOCATE('\"rg:buedchen_tier\":\"B\"',raw_tags)>0 THEN 1 ELSE 0 END) tier_b,
                    SUM(CASE WHEN LOCATE('\"rg:buedchen_tier\":\"C\"',raw_tags)>0 THEN 1 ELSE 0 END) tier_c,
                    SUM(CASE WHEN opening_hours<>'' THEN 1 ELSE 0 END) with_hours,
                    SUM(CASE WHEN website<>'' THEN 1 ELSE 0 END) with_website
             FROM $places
             WHERE active=1 AND primary_category='buedchen'
             GROUP BY municipality_slug
             ORDER BY total DESC, municipality_slug ASC",
            ARRAY_A
        );
    }

    private function map_tile_bytes($z,$x,$y) {
        $z=(int)$z; $x=(int)$x; $y=(int)$y;
        if($z<10||$z>18) return null;
        $max=(1<<$z);
        if($x<0||$y<0||$x>=$max||$y>=$max) return null;

        $uploads=wp_upload_dir();
        $dir=trailingslashit($uploads['basedir']).'ruhrpottguru/maptiles/'.$z.'/'.$x;
        $path=$dir.'/'.$y.'.png';
        if(file_exists($path) && (time()-filemtime($path)) < 30*DAY_IN_SECONDS) {
            $body=@file_get_contents($path);
            return $body!==false?$body:null;
        }

        $url='https://tile.openstreetmap.org/'.$z.'/'.$x.'/'.$y.'.png';
        $remote=wp_remote_get($url,array(
            'timeout'=>8,'redirection'=>2,
            'headers'=>array(
                'User-Agent'=>'RuhrpottGuru/1.3.0 (+https://www.ruhrpottguru.de/; contact via website)',
                'Referer'=>home_url('/buedchen-radar/')
            )
        ));
        if(is_wp_error($remote)) return null;
        $code=(int)wp_remote_retrieve_response_code($remote);
        $body=wp_remote_retrieve_body($remote);
        $type=(string)wp_remote_retrieve_header($remote,'content-type');
        if($code!==200||$body===''||stripos($type,'image/')!==0) return null;
        if(wp_mkdir_p($dir)) @file_put_contents($path,$body,LOCK_EX);
        return $body;
    }

    public function ajax_map_tile() {
        $z=isset($_GET['z'])?(int)$_GET['z']:-1;
        $x=isset($_GET['x'])?(int)$_GET['x']:-1;
        $y=isset($_GET['y'])?(int)$_GET['y']:-1;
        $body=$this->map_tile_bytes($z,$x,$y);
        if($body===null){
            status_header(404);
            header('Content-Type: text/plain; charset=utf-8');
            echo 'tile unavailable';
            wp_die();
        }
        nocache_headers();
        header('Content-Type: image/png');
        header('Cache-Control: public, max-age=604800');
        header('Content-Length: '.strlen($body));
        echo $body;
        exit;
    }

    /**
     * Privacy-friendly OSM raster proxy for the Büdchen radar.
     * Browser talks only to RuhrpottGuru; tiles are cached locally.
     */
    public function rest_map_tile(WP_REST_Request $request) {
        $body=$this->map_tile_bytes((int)$request['z'],(int)$request['x'],(int)$request['y']);
        if($body===null) return new WP_REST_Response(array('error'=>'tile-unavailable'),404);
        // Kept for compatibility/diagnostics. Frontend uses the binary AJAX route.
        return rest_ensure_response(array('ok'=>true,'bytes'=>strlen($body)));
    }



    /**
     * Places 1.10.95: central, versioned reprocessing contract.
     *
     * Future parser/resolver changes register ONE job here (or via the trusted
     * filter) instead of inventing a new one-off option/cron. The fingerprint is
     * the semantic input version. Same key + same fingerprint is immutable and
     * never re-runs; a changed fingerprint becomes one new resumable pass.
     * Processors MUST be idempotent. Cursor scopes are monotonic by primary ID.
     */
    private function reprocess_catalog_v101095() {
        $jobs=array(
            'places-quality-v1080'=>array(
                'label'=>'Places-Datenqualität / Primärquellen 1.10.80','component'=>'places-resolver','fingerprint'=>'places-quality:1.10.80',
                'historical'=>true,'mode'=>'external-heavy','scope'=>'municipalities','autostart'=>false,
            ),
            'opening-date-fragment-v1093'=>array(
                'label'=>'Öffnungszeiten Parser-Sicherheitsrevalidierung 1.10.93','component'=>'opening-hours-parser','fingerprint'=>'opening-parser:date-fragment:1.10.93',
                'historical'=>true,'mode'=>'external-heavy','scope'=>'opening-hours','autostart'=>false,
            ),
            'place-media-coverage-v1094'=>array(
                'label'=>'Ortsbild-Coverage 1.10.94','component'=>'place-media-resolver','fingerprint'=>'place-media-coverage:1.10.94',
                'historical'=>true,'mode'=>'external-heavy','scope'=>'active_places','autostart'=>false,
            ),
            'event-fallback-media-quality-v101107'=>array(
                'label'=>'Event-Fallbackbilder Text/Poster-Qualitätsgate 1.10.107','component'=>'event-media-resolver','fingerprint'=>'event-media:auto-fallback-visual-quality:1.10.107',
                'historical'=>true,'mode'=>'local','scope'=>'event_media_auto','autostart'=>false,
            ),
            'event-fallback-media-quality-v101110'=>array(
                'label'=>'Event-Fallbackbilder Crop-/Text-Qualitätsgate 1.10.110','component'=>'event-media-resolver','fingerprint'=>'event-media:auto-fallback-crop-quality:1.10.110',
                'historical'=>true,'mode'=>'local','scope'=>'event_media_auto','autostart'=>false,'batch_size'=>12,
                'selector'=>'reprocess_select_event_fallback_media_v101110','processor'=>'reprocess_event_fallback_media_quality_v101110',
                // Local DB/filesystem validation only. It may safely run alongside
                // the unrelated duplicate-hash and Place-media workers. The normal
                // Event fallback writer waits for this exact gate before resuming.
                'conflicts'=>array(),
