            if((int)($q['completed']??0)>=53 && (int)($q['remaining']??53)===0)return array('status'=>'complete','detail'=>'53/53 Kommunen abgeschlossen');
            return array('status'=>'legacy-running','detail'=>(int)($q['completed']??0).'/53 Kommunen');
        }
        if($key==='opening-date-fragment-v1093'){
            $v=get_option('rg_opening_hours_audit_v1093_date_fragment_cleanup',false);
            if($v!==false)return array('status'=>'complete','detail'=>'gezielte Revalidierung registriert');
            return array('status'=>'legacy-pending','detail'=>'Legacy-Marker noch nicht gesetzt');
        }
        if($key==='place-media-coverage-v1094'){
            $done=get_option(self::PLACE_MEDIA_COVERAGE_DONE,false);$m=$this->place_media_coverage_state_v101094();
            if($done || (string)($m['status']??'')==='completed')return array('status'=>'complete','detail'=>'Ortsbild-Coverage abgeschlossen');
            return array('status'=>'legacy-running','detail'=>'geprüft '.(int)($m['processed']??0).' · neu '.(int)($m['found']??0));
        }
        return array('status'=>'legacy-pending','detail'=>'historischer Status unbekannt');
    }

