            'fingerprint'=>(string)($job['fingerprint']??''),'status'=>$status,'cursor'=>0,'processed'=>0,'changed'=>0,'skipped'=>0,'errors'=>0,
            'started_at'=>'','updated_at'=>'','completed_at'=>'','last_entity_id'=>0,'last_error'=>'','last_result'=>'','detail'=>'','error_ids'=>array(),
        );
    }

    private function reprocess_sync_registry_v101095() {
        $catalog=$this->reprocess_catalog_v101095();$state=$this->reprocess_state_v101095();$changed=false;
        foreach($catalog as $key=>$job){
            $key=sanitize_key((string)$key);if($key==='')continue;
            $fingerprint=trim((string)($job['fingerprint']??''));if($fingerprint==='')continue;
            if(!empty($job['historical'])){
                $legacy=$this->reprocess_historical_status_v101095($key);
                $old=is_array($state['jobs'][$key]??null)?$state['jobs'][$key]:array();
                $row=array_merge($this->reprocess_default_job_state_v101095($job,(string)$legacy['status']),$old);
                $row['fingerprint']=$fingerprint;$row['status']=(string)$legacy['status'];$row['detail']=(string)$legacy['detail'];
                if($row['status']==='complete' && $row['completed_at']==='')$row['completed_at']=current_time('mysql',true);
                if(!isset($state['jobs'][$key]) || $state['jobs'][$key]!=$row){$state['jobs'][$key]=$row;$changed=true;}
                continue;
            }
            $old=is_array($state['jobs'][$key]??null)?$state['jobs'][$key]:array();
            $old_fp=(string)($old['fingerprint']??'');
            if(!$old || $old_fp!==$fingerprint){
                // 1.10.126: a managed reprocessing job is auto-queued by default.
                // Dependency-gated jobs may still opt out explicitly with autostart=false
                // and wake themselves once their declared prerequisite is available.
                $autostart=array_key_exists('autostart',$job)?!empty($job['autostart']):true;
                $state['jobs'][$key]=$this->reprocess_default_job_state_v101095($job,$autostart?'queued':'pending');
                $state['jobs'][$key]['last_result']=$old_fp!==''?'Fingerprint geändert: '.$old_fp.' → '.$fingerprint:'neu registriert';
                $changed=true;
            }
        }
        // Keep retired jobs as immutable history; only currently registered jobs can execute.
        $managed_active=false;$managed_wait=false;$managed_error=false;
        foreach($catalog as $rawkey=>$job){$key=sanitize_key((string)$rawkey);if(!empty($job['historical']))continue;$j=$state['jobs'][$key]??array();$st=(string)($j['status']??'');if(in_array($st,array('queued','running'),true))$managed_active=true;elseif($st==='waiting')$managed_wait=true;elseif($st==='error')$managed_error=true;}
        if((string)($state['api_version']??'')!==self::REPROCESS_API_VERSION)$changed=true;
        $state['api_version']=self::REPROCESS_API_VERSION;
        $state['status']=$managed_active?'running':($managed_wait?'waiting':($managed_error?'error':'ready'));
        if($changed)update_option(self::REPROCESS_STATE,$state,false);
        return array($state,$catalog);
    }

    private function reprocess_conflict_status_v101095($job) {
        $conflicts=is_array($job['conflicts']??null)?$job['conflicts']:array();
        if(!$conflicts){$scope=sanitize_key((string)($job['scope']??''));if($scope==='active_places')$conflicts=array('place_media','municipality','opening_hours');elseif($scope==='active_events')$conflicts=array('events_external');}
        $blockers=array();
        foreach($conflicts as $lane){
            $lane=sanitize_key((string)$lane);
            if($lane==='place_media'){
                $m=$this->place_media_coverage_state_v101094();if(!get_option(self::PLACE_MEDIA_COVERAGE_DONE) && in_array((string)($m['status']??''),array('queued','running','waiting'),true))$blockers[]='Ortsbild-Coverage';
            }elseif($lane==='municipality'){
                $a=get_option(self::ACTIVITY_COVERAGE_STATE,array());if(is_array($a)&&in_array((string)($a['status']??''),array('queued','running'),true))$blockers[]='Activities Source-Coverage';
                if($this->places_import_actively_running())$blockers[]='Places / OSM Kommune';
            }elseif($lane==='opening_hours'){
                $o=get_option('rg_opening_hours_audit_state_v1108',array());if(is_array($o)&&in_array((string)($o['status']??''),array('running','queued'),true))$blockers[]='Öffnungszeiten-Audit';
            }elseif($lane==='events_external'){
                foreach($this->event_worker_snapshot_v1050() as $w)if(!empty($w['active'])&&($w['class']??'')==='external-heavy'&&($w['key']??'')!=='places')$blockers[]=(string)$w['label'];
            }
        }
        return array_values(array_unique($blockers));
    }

    private function reprocess_schedule_tick_v101095($delay=20) {
        $delay=max(5,(int)$delay);if(!wp_next_scheduled(self::REPROCESS_HOOK))wp_schedule_single_event(time()+$delay,self::REPROCESS_HOOK);
        if($delay<=10&&function_exists('spawn_cron'))spawn_cron();
    }

    public function ensure_reprocess_worker_v101095() {
        list($state,$catalog)=$this->reprocess_sync_registry_v101095();
        // V1.10.108 migration: v1.10.107 could leave the local fallback-quality
        // audit in waiting because its conflict lane unnecessarily included the
        // unrelated external SHA-256 worker. Preserve cursor/progress, only wake
        // the exact existing job and let it resume immediately under the narrowed
        // conflict contract.
        if(!get_option('rg_event_fallback_quality_conflict_fix_v101108')){
            $key='event-fallback-media-quality-v101107';
            if(isset($state['jobs'][$key])&&is_array($state['jobs'][$key])&&(string)($state['jobs'][$key]['status']??'')==='waiting'){
                $state['jobs'][$key]['status']='queued';
                $state['jobs'][$key]['updated_at']=current_time('mysql',true);
                $state['jobs'][$key]['last_result']='1.10.108: lokale Qualitätsprüfung aus zu breiter Worker-Sperre gelöst; Fortschritt/Cursor beibehalten';
                $state['status']='running';$state['active_job']='';
                update_option(self::REPROCESS_STATE,$state,false);
                wp_clear_scheduled_hook(self::REPROCESS_HOOK);
                $this->reprocess_schedule_tick_v101095(5);
            }
            update_option('rg_event_fallback_quality_conflict_fix_v101108',current_time('mysql'),false);
        }
        // 1.10.124: do not start semantic Pexels reprocessing until Theme v298
        // is active. Plugins load before the theme, but this init hook runs after
        // theme functions are available, so the dependency can be checked safely.
        $semanticKey='event-symbolic-semantic-v101124';
        if(function_exists('ruhrpott_guru_event_media_pexels_v298')&&isset($state['jobs'][$semanticKey])&&is_array($state['jobs'][$semanticKey])&&(string)($state['jobs'][$semanticKey]['status']??'')==='pending'){
            $state['jobs'][$semanticKey]['status']='queued';
            $state['jobs'][$semanticKey]['updated_at']=current_time('mysql',true);
            $state['jobs'][$semanticKey]['last_result']='Theme v298 erkannt; semantische Symbolfoto-Bereinigung eingereiht';
            $state['status']='running';$state['active_job']='';
            update_option(self::REPROCESS_STATE,$state,false);
            wp_clear_scheduled_hook(self::REPROCESS_HOOK);
            $this->reprocess_schedule_tick_v101095(10);
        }

        $needs=false;
        foreach($catalog as $rawkey=>$job){if(!empty($job['historical']))continue;$key=sanitize_key((string)$rawkey);$st=(string)($state['jobs'][$key]['status']??'');if(in_array($st,array('queued','running','waiting'),true)){$needs=true;break;}}
        if($needs&&!wp_next_scheduled(self::REPROCESS_HOOK))$this->reprocess_schedule_tick_v101095(15);
    }

    private function reprocess_select_batch_v101095($job,$cursor,$limit) {
        global $wpdb;$scope=sanitize_key((string)($job['scope']??''));$cursor=max(0,(int)$cursor);$limit=max(1,min(50,(int)$limit));
        if($scope==='active_places'){
            $table=$this->table('places');$cats=is_array($job['categories']??null)?array_values(array_filter(array_map('sanitize_key',$job['categories']))):array();$where="active=1 AND lifecycle_status='active' AND id>".$cursor;
            if($cats){$quoted=array_map(function($v){return "'".esc_sql($v)."'";},$cats);$where.=' AND primary_category IN ('.implode(',',$quoted).')';}
            return (array)$wpdb->get_results("SELECT * FROM $table WHERE $where ORDER BY id ASC LIMIT ".(int)$limit,ARRAY_A);
        }
        if($scope==='active_events'){
            $table=$this->table('events');return (array)$wpdb->get_results("SELECT * FROM $table WHERE status='active' AND id>".$cursor." ORDER BY id ASC LIMIT ".(int)$limit,ARRAY_A);
        }
        $selector=(string)($job['selector']??'');if($selector!==''&&method_exists($this,$selector))return (array)$this->$selector($cursor,$limit,$job);
        return array();
    }


