        $title=(string)($row['title']??'');$city=(string)($row['city']??'');$venue=(string)($row['venue_name']??'');$eventType=(string)($row['event_category']??'');
        $coords=array('lat'=>(float)($row['lat']??0),'lng'=>(float)($row['lng']??0));

