                $eventId,$source,$candidateUrl
            ));
            if($acceptedId>0){
                $wpdb->update($media,array(
                    'visual_quality_status'=>'passed','visual_quality_reason'=>'semantic-v298-accepted','visual_quality_checked_at'=>$now,
                    'health_status'=>'healthy','health_error'=>'','last_seen_at'=>$now
