            if(!$sameRevalidated){
                $wpdb->update($media,array('moderation_status'=>'rejected','is_primary'=>0,'health_status'=>'invalid','health_error'=>'semantic-v298-replaced','visual_quality_status'=>'rejected','visual_quality_reason'=>'semantic-v298-replaced','visual_quality_checked_at'=>$now,'last_seen_at'=>$now),array('id'=>$mediaId));
