        }

        // No exact venue image and no strict theme match: an honest neutral
        // placeholder is preferable to an unrelated stock photo.
        $ok=$wpdb->update($media,array(
            'moderation_status'=>'rejected','is_primary'=>0,'health_status'=>'invalid',
            'health_error'=>'semantic-v298-no-safe-fallback','visual_quality_status'=>'rejected',
            'visual_quality_reason'=>'semantic-v298-no-safe-fallback','visual_quality_checked_at'=>$now,'last_seen_at'=>$now
