        $more=false;foreach($catalog as $rawkey=>$candidate){if(!empty($candidate['historical']))continue;$key=sanitize_key((string)$rawkey);$st=$key===$job_key?(string)$js['status']:(string)($state['jobs'][$key]['status']??'');if(in_array($st,array('queued','running','waiting'),true)){$more=true;break;}}
        $state['status']=$more?'running':((string)$js['status']==='error'?'error':'ready');if(!$more)$state['active_job']='';update_option(self::REPROCESS_STATE,$state,false);delete_transient($lock);
