    public function admin_place_media_coverage_pause_v101094() {
        if(!current_user_can('manage_options'))wp_die('forbidden');
        check_admin_referer('rg_places_media_coverage_pause_v101094');
        update_option(self::PLACE_MEDIA_COVERAGE_PAUSED,1,false);
