        exit;
    }


    public function admin_place_media_coverage_resume_v101094() {
        if(!current_user_can('manage_options'))wp_die('forbidden');
        check_admin_referer('rg_places_media_coverage_resume_v101094');
        delete_option(self::PLACE_MEDIA_COVERAGE_PAUSED);
        $state=$this->place_media_coverage_state_v101094();
        if($state['status']!=='completed'){
            $state['status']='queued';
            $state['resumed_at']=current_time('mysql',true);
            $state['last_result']='Fortsetzung am gespeicherten Cursor geplant';
            $this->save_place_media_coverage_state_v101094($state);
