        exit;
    }


    public function ensure_place_media_coverage_worker_v101094() {
        if(get_option(self::PLACE_MEDIA_COVERAGE_DONE))return;
        $state=$this->place_media_coverage_state_v101094();
        if($state['status']==='completed'){
            update_option(self::PLACE_MEDIA_COVERAGE_DONE,current_time('mysql',true),false);return;
        }
        if($this->place_media_coverage_is_paused_v101094()){
            if($state['status']!=='paused'){$state['status']='paused';$this->save_place_media_coverage_state_v101094($state);}return;
        }
        if($state['status']==='idle' || $state['status']==='paused'){
            $state['status']='queued';
            if(!$state['started_at'])$state['started_at']=current_time('mysql',true);
            $this->save_place_media_coverage_state_v101094($state);
        }
        if(!wp_next_scheduled(self::PLACE_MEDIA_COVERAGE_HOOK))wp_schedule_single_event(time()+30,self::PLACE_MEDIA_COVERAGE_HOOK);
    }

    private function place_has_immediate_image_v101094($row,$tags) {
        global $wpdb;$media=$this->table('place_media');
        $pid=(int)($row['id']??0);
        if($pid>0){
            $existing=(int)$wpdb->get_var($wpdb->prepare("SELECT COUNT(*) FROM $media WHERE place_id=%d AND media_type='image' AND relation_type='place' AND moderation_status='active'",$pid));
            if($existing>0)return true;
        }
        foreach(array('image','image:url') as $key){
            $v=trim((string)($tags[$key]??''));
            if($v!=='' && preg_match('#^(?:https?:)?//#i',$v))return true;
            if($v!=='' && preg_match('/\.(?:jpe?g|png|webp|gif|avif)(?:[?#].*)?$/i',$v))return true;
        }
        $commons=trim((string)($tags['wikimedia_commons']??''));
        if($commons!=='' && (stripos($commons,'File:')!==false || stripos($commons,'Special:FilePath/')!==false || preg_match('/\.(?:jpe?g|png|webp|gif|avif)(?:[?#].*)?$/i',$commons)))return true;
        return false;
    }

    private function place_media_coverage_candidates_v101094($cursor,$limit=4) {
        global $wpdb;$places=$this->table('places');$cursor=max(0,(int)$cursor);$limit=max(1,min(6,(int)$limit));
        return (array)$wpdb->get_results($wpdb->prepare(
            "SELECT id,name,city,district,street,house_number,postcode,lat,lng,website,wikidata,wikipedia,primary_category,primary_subcategory,quality_score,raw_tags FROM $places WHERE active=1 AND lifecycle_status='active' AND primary_category IN ('food','highlights','culture','activities') AND id>%d ORDER BY id ASC LIMIT %d",
            $cursor,$limit
        ),ARRAY_A);
    }

    private function place_media_coverage_resolve_v101094($row) {
        if(!function_exists('rest_do_request'))return array('ok'=>false,'reason'=>'rest-unavailable');
        $tags=json_decode((string)($row['raw_tags']??''),true);if(!is_array($tags))$tags=array();
        if($this->place_has_immediate_image_v101094($row,$tags))return array('ok'=>true,'existing'=>true,'reason'=>'already-visible');
        $category=sanitize_key((string)($row['primary_category']??''));
        $website=esc_url_raw((string)($row['website']??($tags['website']??($tags['contact:website']??''))));
        $address=trim((string)($row['street']??'').' '.(string)($row['house_number']??'').', '.(string)($row['postcode']??'').' '.(string)($row['city']??''));
        $qid=(string)($tags['wikidata']??($row['wikidata']??''));
        $wiki=(string)($tags['wikipedia']??($row['wikipedia']??''));
        if($category!=='food' && $website==='' && $qid!==''){
            $info=new WP_REST_Request('POST','/ruhrpottguru/v1/place-info');
            $info->set_header('content-type','application/json');
            $info->set_body(wp_json_encode(array('title'=>(string)$row['name'],'category'=>$category,'city'=>(string)$row['city'],'address'=>$address,'website'=>'','wikidata'=>$qid,'lat'=>(float)$row['lat'],'lng'=>(float)$row['lng'])));
            $ir=rest_do_request($info);
            if(!is_wp_error($ir) && $ir->get_status()>=200 && $ir->get_status()<300){$id=$ir->get_data();if(is_array($id)&&!empty($id['website']))$website=esc_url_raw((string)$id['website']);}
        }
        $req=new WP_REST_Request('POST','/ruhrpottguru/v1/food-media');
        $payload=array(
            'title'=>(string)$row['name'],'city'=>(string)$row['city'],'address'=>$address,'website'=>$website,
            'wikidata'=>$qid,'wikipedia'=>$wiki,'osmImage'=>(string)($tags['image']??($tags['image:url']??'')),'wikimediaCommons'=>(string)($tags['wikimedia_commons']??''),
            'lat'=>(float)$row['lat'],'lng'=>(float)$row['lng'],'subcategory'=>(string)($row['primary_subcategory']??''),'cuisine'=>(string)($tags['cuisine']??''),
            'tags'=>array_values(array_filter(array((string)($tags['cuisine']??''),(string)($tags['tourism']??''),(string)($tags['leisure']??''),(string)($tags['historic']??''),(string)($tags['amenity']??''),(string)($tags['sport']??'')))),
            // 1.10.150: the persistent coverage worker only stores identity-bearing images.
            // Symbolic Food/Pexels may remain a frontend fallback, but is not an Ortsbild and
            // must not be written into the canonical place-media coverage pool.
            'allowSymbolic'=>false,'category'=>$category,
        );
        $req->set_header('content-type','application/json');$req->set_body(wp_json_encode($payload));$resp=rest_do_request($req);
        if(is_wp_error($resp))return array('ok'=>false,'reason'=>$resp->get_error_message());
        $status=(int)$resp->get_status();$data=$resp->get_data();if($status<200||$status>=300||!is_array($data))return array('ok'=>false,'reason'=>'resolver-http-'.$status);
        $url=esc_url_raw((string)($data['imageUrl']??''));if(!$url)return array('ok'=>false,'reason'=>(string)($data['status']??'no-image'));
        return array('ok'=>true,'url'=>$url,'source'=>sanitize_key((string)($data['source']??'resolver')),'source_url'=>esc_url_raw((string)($data['sourceUrl']??'')),'license'=>sanitize_text_field((string)($data['license']??'')),'artist'=>sanitize_text_field((string)($data['artist']??'')),'credit'=>sanitize_text_field((string)($data['credit']??'')),'confidence'=>isset($data['identityConfidence'])&&is_numeric($data['identityConfidence'])?(float)$data['identityConfidence']:0.0,'method'=>sanitize_key((string)($data['matchMethod']??'')),'raw'=>$data);
    }

    private function save_place_media_coverage_result_v101094($place_id,$resolved) {
        global $wpdb;$media=$this->table('place_media');$place_id=(int)$place_id;$url=esc_url_raw((string)($resolved['url']??''));if($place_id<=0||!$url)return false;
        $exists=(int)$wpdb->get_var($wpdb->prepare("SELECT id FROM $media WHERE place_id=%d AND media_type='image' AND relation_type='place' AND moderation_status='active' AND url=%s LIMIT 1",$place_id,$url));if($exists)return true;
        $has_any=(int)$wpdb->get_var($wpdb->prepare("SELECT COUNT(*) FROM $media WHERE place_id=%d AND media_type='image' AND relation_type='place' AND moderation_status='active'",$place_id));
        $now=current_time('mysql',true);$confidence=max(0,min(1,(float)($resolved['confidence']??0)));
        return $wpdb->insert($media,array(
            'place_id'=>$place_id,'media_type'=>'image','url'=>$url,'source'=>substr(sanitize_text_field((string)($resolved['source']??'resolver')),0,64),'source_url'=>esc_url_raw((string)($resolved['source_url']??'')),
            'license'=>substr(sanitize_text_field((string)($resolved['license']??'')),0,120),'artist'=>substr(sanitize_text_field((string)($resolved['artist']??'')),0,190),'credit'=>sanitize_text_field((string)($resolved['credit']??'')),
            'relation_type'=>'place','identity_confidence'=>$confidence,'visual_quality'=>0.75,'is_primary'=>$has_any?0:1,'moderation_status'=>'active','verified_at'=>$confidence>=0.88?$now:null,'last_seen_at'=>$now,
        ),array('%d','%s','%s','%s','%s','%s','%s','%s','%s','%f','%f','%d','%s','%s','%s'))!==false;
    }

    public function cron_place_media_coverage_tick_v101094() {
        if(get_option(self::PLACE_MEDIA_COVERAGE_DONE))return;
        if($this->place_media_coverage_is_paused_v101094()){
            $state=$this->place_media_coverage_state_v101094();if($state['status']!=='completed'){$state['status']='paused';$this->save_place_media_coverage_state_v101094($state);}return;
        }
        $lock='rg_places_media_coverage_lock_v101094';if(get_transient($lock))return;set_transient($lock,1,4*MINUTE_IN_SECONDS);
        $state=$this->place_media_coverage_state_v101094();if($state['status']==='completed'){delete_transient($lock);return;}
        if(!function_exists('ruhrpott_guru_food_media_resolver')){
            $state['status']='waiting';$state['last_tick_at']=current_time('mysql',true);$state['last_result']='Theme-Mediaresolver derzeit nicht verfügbar; es wurde kein Place übersprungen.';$this->save_place_media_coverage_state_v101094($state);delete_transient($lock);if(!$this->place_media_coverage_is_paused_v101094()&&!wp_next_scheduled(self::PLACE_MEDIA_COVERAGE_HOOK))wp_schedule_single_event(time()+10*MINUTE_IN_SECONDS,self::PLACE_MEDIA_COVERAGE_HOOK);return;
        }
        if(!$state['started_at'])$state['started_at']=current_time('mysql',true);$state['status']='running';$state['last_tick_at']=current_time('mysql',true);
        $rows=$this->place_media_coverage_candidates_v101094((int)$state['cursor'],3);
        if(!$rows){$state['status']='completed';$state['finished_at']=current_time('mysql',true);$this->save_place_media_coverage_state_v101094($state);update_option(self::PLACE_MEDIA_COVERAGE_DONE,$state['finished_at'],false);delete_transient($lock);return;}
        foreach($rows as $row){
            $id=(int)$row['id'];$cat=sanitize_key((string)$row['primary_category']);$state['cursor']=max((int)$state['cursor'],$id);$state['processed']++;if(isset($state['categories'][$cat]))$state['categories'][$cat]['processed']++;
            $resolved=$this->place_media_coverage_resolve_v101094($row);$state['last_place']=(string)$row['name'].' · '.(string)$row['city'];
            if(!empty($resolved['existing'])){$state['existing']++;$state['last_result']='bereits Bild vorhanden';continue;}
            if(!empty($resolved['ok']) && !empty($resolved['url'])){
                if($this->save_place_media_coverage_result_v101094($id,$resolved)){$state['found']++;if(isset($state['categories'][$cat]))$state['categories'][$cat]['found']++;$state['last_result']='Bild gespeichert · '.(string)($resolved['source']??'resolver');}
                else{$state['errors']++;$state['last_result']='DB-Speicherfehler';}
            }else{$state['missing']++;if(isset($state['categories'][$cat]))$state['categories'][$cat]['missing']++;$state['last_result']='kein belastbarer Treffer';}
        }
        if($this->place_media_coverage_is_paused_v101094()){$state['status']='paused';$state['last_result'].=' · danach pausiert';$this->save_place_media_coverage_state_v101094($state);delete_transient($lock);wp_clear_scheduled_hook(self::PLACE_MEDIA_COVERAGE_HOOK);return;}
        $this->save_place_media_coverage_state_v101094($state);delete_transient($lock);
        if(!wp_next_scheduled(self::PLACE_MEDIA_COVERAGE_HOOK))wp_schedule_single_event(time()+45,self::PLACE_MEDIA_COVERAGE_HOOK);
    }

    private function render_place_media_coverage_v101094() {
        $s=$this->place_media_coverage_state_v101094();$status=(string)$s['status'];$paused=$this->place_media_coverage_is_paused_v101094();if($paused&&$status!=='completed')$status='paused';
        $label=$status==='completed'?'abgeschlossen':($status==='paused'?'pausiert':($status==='running'?'läuft serverseitig':($status==='queued'?'wartet auf Start':($status==='waiting'?'wartet auf Theme-Mediaresolver':'bereit'))));
        echo '<div class="rg-admin-card" style="padding:14px 16px"><strong>Ortsbild-Coverage 1.10.94 · '.esc_html($label).'</strong>';
        echo '<p style="margin:6px 0 10px">Food, Highlights, Kultur und Aktivitäten werden serverseitig mit der bestehenden identitätssicheren Bildquellenkette nachangereichert. Pause/Fortsetzen behält Cursor, Zähler und bereits gespeicherte Bilder vollständig bei.</p>';
        echo '<div class="rg-count-cards">';foreach(array('geprüft'=>(int)$s['processed'],'bereits Bild'=>(int)$s['existing'],'neu gefunden'=>(int)$s['found'],'ohne Treffer'=>(int)$s['missing'],'Fehler'=>(int)$s['errors']) as $k=>$v)echo '<div class="rg-count-card"><small>'.esc_html($k).'</small><strong>'.number_format_i18n($v).'</strong></div>';echo '</div>';
        if($s['last_place']!=='')echo '<p class="description">Zuletzt: '.esc_html($s['last_place']).' · '.esc_html($s['last_result']).'</p>';
        if($status!=='completed'){
            if($paused){$url=wp_nonce_url(admin_url('admin-post.php?action=rg_places_media_coverage_resume'),'rg_places_media_coverage_resume_v101094');echo '<p><a class="button button-primary" href="'.esc_url($url).'">Ortsbild-Worker fortsetzen</a> <span class="description">setzt am gespeicherten Cursor weiter</span></p>';}
            else{$url=wp_nonce_url(admin_url('admin-post.php?action=rg_places_media_coverage_pause'),'rg_places_media_coverage_pause_v101094');echo '<p><a class="button" href="'.esc_url($url).'">Ortsbild-Worker pausieren</a> <span class="description">ein bereits gestartetes 3er-Batch darf noch sauber fertiglaufen</span></p>';}
        }
        echo '</div>';
    }

    private function buedchen_media_state() {
        $state=get_option('rg_buedchen_media_enrichment_v131',array());
        if(!is_array($state)) $state=array();
        if(!isset($state['done'])||!is_array($state['done'])) $state['done']=array();
        foreach(array('processed','found','primary','skipped','failed') as $k){
            if(!isset($state[$k])) $state[$k]=0;
        }
        if(!isset($state['started_at'])) $state['started_at']='';
        if(!isset($state['updated_at'])) $state['updated_at']='';
        return $state;
    }

    private function buedchen_media_stats() {
        global $wpdb;
        $places=$this->table('places');
        $media=$this->table('place_media');
        $total=(int)$wpdb->get_var("SELECT COUNT(*) FROM $places WHERE active=1 AND primary_category='buedchen'");
        $public=(int)$wpdb->get_var(
            "SELECT COUNT(*) FROM $places p
             WHERE p.active=1 AND p.primary_category='buedchen'
               AND (
                 LOCATE('\"rg:buedchen_tier\":\"A\"',p.raw_tags)>0 OR
                 LOCATE('\"rg:buedchen_tier\":\"B\"',p.raw_tags)>0 OR
                 EXISTS (
                   SELECT 1 FROM {$this->table('place_overrides')} o
                   WHERE o.place_id=p.id AND o.status='active'
                     AND LOCATE('\"review_status\":\"verified\"',o.override_data)>0
                 )
               )"
        );
        $with_primary=(int)$wpdb->get_var(
            "SELECT COUNT(DISTINCT p.id)
             FROM $places p INNER JOIN $media m ON m.place_id=p.id AND m.media_type='image' AND m.relation_type='place' AND m.moderation_status='active' AND m.is_primary=1
             WHERE p.active=1 AND p.primary_category='buedchen'"
        );
        $with_any=(int)$wpdb->get_var(
            "SELECT COUNT(DISTINCT p.id)
             FROM $places p INNER JOIN $media m ON m.place_id=p.id AND m.media_type='image' AND m.relation_type='place' AND m.moderation_status='active'
             WHERE p.active=1 AND p.primary_category='buedchen'"
        );
        return array(
            'total'=>$total,
            'publicEligible'=>$public,
            'withPrimaryImage'=>$with_primary,
            'withAnyImage'=>$with_any,
            'withoutPrimary'=>max(0,$total-$with_primary),
        );
    }

    private function buedchen_media_candidates($limit=4) {
        global $wpdb;
        $places=$this->table('places');
        $media=$this->table('place_media');
        $overrides=$this->table('place_overrides');
        $state=$this->buedchen_media_state();
        $done=array_map('intval',array_keys($state['done']));
        $exclude='';
        if($done){
            // Keep bounded: the queue is ~1.5k entries and is admin-only.
            $exclude=' AND p.id NOT IN ('.implode(',',array_slice($done,0,3000)).') ';
        }
        $limit=max(1,min(8,(int)$limit));
        $sql="
            SELECT p.*
            FROM $places p
            LEFT JOIN $media m ON m.place_id=p.id AND m.media_type='image' AND m.relation_type='place' AND m.is_primary=1 AND m.moderation_status='active'
            LEFT JOIN $overrides o ON o.place_id=p.id AND o.status='active'
            WHERE p.active=1
              AND p.primary_category='buedchen'
              AND m.id IS NULL
              $exclude
            ORDER BY
              CASE
                WHEN LOCATE('\"review_status\":\"verified\"',COALESCE(o.override_data,''))>0 THEN 0
                WHEN LOCATE('\"rg:buedchen_tier\":\"A\"',p.raw_tags)>0 THEN 1
                WHEN LOCATE('\"rg:buedchen_tier\":\"B\"',p.raw_tags)>0 THEN 2
                ELSE 3
              END ASC,
              p.quality_score DESC,
              p.id ASC
            LIMIT $limit
        ";
        return (array)$wpdb->get_results($sql,ARRAY_A);
    }

    private function buedchen_media_internal_resolve($row) {
        if(!function_exists('rest_do_request')) return array('ok'=>false,'reason'=>'rest-unavailable');
        $tags=json_decode((string)($row['raw_tags']??''),true);
        if(!is_array($tags)) $tags=array();

        // Re-use the battle-tested identity-safe place media resolver from the
        // active RuhrpottGuru theme. No generic web/image search is introduced.
        $req=new WP_REST_Request('POST','/ruhrpottguru/v1/food-media');
        $payload=array(
            'title'=>(string)$row['name'],
            'city'=>(string)$row['city'],
            'address'=>trim((string)$row['street'].' '.(string)$row['house_number'].', '.(string)$row['postcode'].' '.(string)$row['city']),
            'website'=>(string)$row['website'],
            'wikidata'=>(string)($tags['wikidata']??$row['wikidata']??''),
            'wikipedia'=>(string)($tags['wikipedia']??$row['wikipedia']??''),
            'osmImage'=>(string)($tags['image']??''),
            'wikimediaCommons'=>(string)($tags['wikimedia_commons']??''),
            'lat'=>(float)$row['lat'],
            'lng'=>(float)$row['lng'],
            'subcategory'=>'Büdchen / Trinkhalle',
            'cuisine'=>'',
            'tags'=>array_values(array_filter(array(
                (string)($tags['shop']??''),
                (string)($tags['lottery']??''),
                (string)($tags['tobacco']??'')
            ))),
            'allowSymbolic'=>false,
            'category'=>'buedchen'
        );
        $req->set_header('content-type','application/json');
        $req->set_body(wp_json_encode($payload));
        $resp=rest_do_request($req);
        if(is_wp_error($resp)) return array('ok'=>false,'reason'=>$resp->get_error_message());
        $status=(int)$resp->get_status();
        $data=$resp->get_data();
        if($status<200||$status>=300||!is_array($data)) return array('ok'=>false,'reason'=>'resolver-http-'.$status);

        $url=isset($data['imageUrl'])?esc_url_raw((string)$data['imageUrl']):'';
        if(!$url) return array('ok'=>false,'reason'=>(string)($data['status']??'no-image'));

        $confidence=isset($data['identityConfidence'])&&is_numeric($data['identityConfidence'])?(float)$data['identityConfidence']:0.0;
        $source=sanitize_key((string)($data['source']??'resolver'));
        $source_url=esc_url_raw((string)($data['sourceUrl']??''));
        $credit=sanitize_text_field((string)($data['credit']??''));
        $license=sanitize_text_field((string)($data['license']??''));
        $method=sanitize_key((string)($data['matchMethod']??''));

        // A concrete place image must be identity-bound. Lower-confidence street
        // imagery is useful as a candidate, but must not silently become primary.
        $primary=$confidence>=0.88;
        return array(
            'ok'=>true,
            'url'=>$url,
            'source'=>$source?:'resolver',
            'source_url'=>$source_url,
            'credit'=>$credit,
            'license'=>$license,
            'confidence'=>$confidence,
            'method'=>$method,
            'primary'=>$primary,
            'raw'=>$data,
        );
    }

    private function save_buedchen_media_result($place_id,$resolved) {
        global $wpdb;
        $media=$this->table('place_media');
        $place_id=(int)$place_id;
        $url=esc_url_raw((string)($resolved['url']??''));
        if($place_id<=0||!$url) return false;

        $exists=(int)$wpdb->get_var($wpdb->prepare(
            "SELECT id FROM $media WHERE place_id=%d AND relation_type='place' AND media_type='image' AND moderation_status='active' AND url=%s LIMIT 1",
            $place_id,$url
        ));
        if($exists) return true;

        $primary=!empty($resolved['primary'])?1:0;
        if($primary){
            $wpdb->update($media,array('is_primary'=>0),array('place_id'=>$place_id,'media_type'=>'image','relation_type'=>'place'),array('%d'),array('%d','%s','%s'));
        }
        $now=current_time('mysql',true);
        return $wpdb->insert($media,array(
            'place_id'=>$place_id,
            'media_type'=>'image',
            'url'=>$url,
            'source'=>substr(sanitize_text_field((string)($resolved['source']??'resolver')),0,64),
            'source_url'=>esc_url_raw((string)($resolved['source_url']??'')),
            'license'=>substr(sanitize_text_field((string)($resolved['license']??'')),0,120),
            'artist'=>'',
            'credit'=>sanitize_text_field((string)($resolved['credit']??'')),
            'relation_type'=>$primary?'place':'contextual',
            'identity_confidence'=>max(0,min(1,(float)($resolved['confidence']??0))),
            'visual_quality'=>0.75,
            'is_primary'=>$primary,
            'verified_at'=>$primary?$now:null,
            'last_seen_at'=>$now,
        ),array('%d','%s','%s','%s','%s','%s','%s','%s','%s','%f','%f','%d','%s','%s'))!==false;
    }

    public function ajax_buedchen_media_enrich_batch() {
        if(!current_user_can('manage_options')) wp_send_json_error(array('message'=>'forbidden'),403);
        check_ajax_referer(self::ADMIN_NONCE_ACTION,'nonce');

        $state=$this->buedchen_media_state();
        if(!$state['started_at']) $state['started_at']=current_time('mysql',true);
        $rows=$this->buedchen_media_candidates(4);

        foreach($rows as $row){
            $id=(int)$row['id'];
            $resolved=$this->buedchen_media_internal_resolve($row);
            $state['processed']++;
            if(!empty($resolved['ok'])){
                $state['found']++;
                if(!empty($resolved['primary'])) $state['primary']++;
                if($this->save_buedchen_media_result($id,$resolved)===false) $state['failed']++;
            }else{
                $state['skipped']++;
            }
            $state['done'][(string)$id]=array(
                'at'=>current_time('mysql',true),
                'status'=>!empty($resolved['ok'])?(!empty($resolved['primary'])?'primary':'candidate'):'none',
                'reason'=>(string)($resolved['reason']??$resolved['method']??''),
            );
        }
        $state['updated_at']=current_time('mysql',true);
        update_option('rg_buedchen_media_enrichment_v131',$state,false);

        $remaining=count($this->buedchen_media_candidates(1))>0;
        wp_send_json_success(array(
            'state'=>array(
                'processed'=>(int)$state['processed'],
                'found'=>(int)$state['found'],
                'primary'=>(int)$state['primary'],
                'skipped'=>(int)$state['skipped'],
                'failed'=>(int)$state['failed'],
                'updatedAt'=>$state['updated_at'],
            ),
            'inventory'=>$this->buedchen_media_stats(),
            'remaining'=>$remaining,
        ));
    }

    public function ajax_buedchen_media_reset() {
        if(!current_user_can('manage_options')) wp_send_json_error(array('message'=>'forbidden'),403);
        check_ajax_referer(self::ADMIN_NONCE_ACTION,'nonce');
        delete_option('rg_buedchen_media_enrichment_v131');
        wp_send_json_success(array('inventory'=>$this->buedchen_media_stats()));
    }

    private function buedchen_submission_whitelist() {
        return array(
            'opening_hours','website','phone','instagram','description',
            'mixed_candy','coffee','sandwiches','seating','lottery','parcel_shop',
            'tobacco','late_night','closed','note'
        );
    }

    private function buedchen_submission_rate_key() {
        $ip=(string)($_SERVER['REMOTE_ADDR']??'');
        $ua=(string)($_SERVER['HTTP_USER_AGENT']??'');
        return 'rg_bude_submit_' . substr(hash_hmac('sha256',$ip.'|'.$ua,wp_salt('nonce')),0,28);
    }

    private function sanitize_buedchen_submission_value($field,$value,&$valid) {
        $valid=true;
        $bool_fields=array('mixed_candy','coffee','sandwiches','seating','lottery','parcel_shop','tobacco','late_night','closed');
        if(in_array($field,$bool_fields,true)) {
            $v=is_bool($value)?$value:sanitize_key((string)$value);
            if(!is_bool($v) && !in_array($v,array('yes','no','true','false','1','0'),true)) {
                $valid=false; return null;
            }
            return is_bool($v)?$v:in_array($v,array('yes','true','1'),true);
        }
        $v=trim(sanitize_textarea_field(wp_unslash((string)$value)));
        if($v==='' || mb_strlen($v)>1000) {$valid=false; return null;}
        return $v;
    }

    private function wurst_frontend_payload($data) {
        if ($this->runtime_mode() !== 'database') {
            return new WP_Error('places-db-not-ready','places-db-not-ready',array('status'=>503));
        }
        $lat = isset($data['lat']) ? (float)$data['lat'] : 0.0;
        $lng = isset($data['lng']) ? (float)$data['lng'] : 0.0;
        $radius = isset($data['radiusKm']) ? max(0.5,min(50.0,(float)$data['radiusKm'])) : 5.0;
        $limit = isset($data['limit']) ? max(1,min(800,(int)$data['limit'])) : 100;
        if (!$this->valid_coordinate($lat,$lng)) return new WP_Error('invalid-request','invalid-request',array('status'=>400));

        global $wpdb;
        $places = $this->table('places');
        $wurst = $this->table('wurst_candidates');
        if ($wpdb->get_var($wpdb->prepare("SHOW TABLES LIKE %s", $wurst)) !== $wurst) {
            return new WP_Error('wurst-table-missing','wurst-table-missing',array('status'=>503));
        }
        $lat_delta = $radius / 110.574;
        $cos = max(0.2, cos(deg2rad($lat)));
        $lng_delta = $radius / (111.320 * $cos);
        $distance = "(6371.0088 * 2 * ASIN(SQRT(POWER(SIN(RADIANS(p.lat - %f)/2),2) + COS(RADIANS(%f)) * COS(RADIANS(p.lat)) * POWER(SIN(RADIANS(p.lng - %f)/2),2))))";
        $distance_sql = $wpdb->prepare($distance,$lat,$lat,$lng);
        $rows = (array)$wpdb->get_results($wpdb->prepare(
            "SELECT p.*, p.primary_subcategory AS subcategory, w.tier AS _rg_wurst_tier, w.review_status AS _rg_wurst_review_status,
                    w.menu_items_json AS _rg_wurst_menu_items, w.audit_reason AS _rg_wurst_audit_reason,
                    w.first_seen_at AS _rg_wurst_first_seen, $distance_sql AS distance_km
             FROM $places p INNER JOIN $wurst w ON w.place_id=p.id
             WHERE p.active=1
               AND p.lifecycle_status='active'
               AND p.primary_category='food'
               AND (w.public_eligible=1 OR w.tier='B')
               AND w.review_status<>'rejected'
               AND p.lat BETWEEN %f AND %f
               AND p.lng BETWEEN %f AND %f
             HAVING distance_km<=%f
             ORDER BY distance_km ASC, p.quality_score DESC, p.id ASC
             LIMIT %d",
             $lat-$lat_delta,$lat+$lat_delta,$lng-$lng_delta,$lng+$lng_delta,$radius,$limit
        ), ARRAY_A);

        $elements=$this->rows_to_elements($rows);
        foreach($elements as $i=>$element) {
            $row=$rows[$i]??array();
            $menu=json_decode((string)($row['_rg_wurst_menu_items']??'[]'),true); if(!is_array($menu))$menu=array();
            $elements[$i]['tags']['rg:wurst_tier']=(string)($row['_rg_wurst_tier']??'');
            $elements[$i]['tags']['rg:wurst_review_status']=(string)($row['_rg_wurst_review_status']??'auto');
            $elements[$i]['tags']['rg:wurst_menu_items']=implode('|',array_values(array_unique(array_map('sanitize_key',$menu))));
            $elements[$i]['tags']['rg:wurst_first_seen']=(string)($row['_rg_wurst_first_seen']??'');
        }
        $verified_total=(int)$wpdb->get_var("SELECT COUNT(*) FROM $wurst w INNER JOIN $places p ON p.id=w.place_id WHERE p.active=1 AND p.lifecycle_status='active' AND p.primary_category='food' AND w.public_eligible=1 AND w.review_status<>'rejected'");
        $radar_total=(int)$wpdb->get_var("SELECT COUNT(*) FROM $wurst w INNER JOIN $places p ON p.id=w.place_id WHERE p.active=1 AND p.lifecycle_status='active' AND p.primary_category='food' AND (w.public_eligible=1 OR w.tier='B') AND w.review_status<>'rejected'");
        return array('ok'=>true,'source'=>'places-db','requestedRadiusKm'=>$radius,'count'=>count($elements),'verifiedTotal'=>$verified_total,'radarTotal'=>$radar_total,'elements'=>$elements);
    }

    public function rest_wurst(WP_REST_Request $request) {
        $data = $request->get_method() === 'GET' ? $request->get_params() : (array)$request->get_json_params();
        $payload=$this->wurst_frontend_payload($data);
        if (is_wp_error($payload)) return new WP_REST_Response(array('ok'=>false,'error'=>$payload->get_error_code()),(int)($payload->get_error_data()['status']??500));
        return rest_ensure_response($payload);
    }

    public function ajax_wurst_frontend() {
        $data=array(
            'lat'=>isset($_REQUEST['lat']) ? wp_unslash($_REQUEST['lat']) : null,
            'lng'=>isset($_REQUEST['lng']) ? wp_unslash($_REQUEST['lng']) : null,
            'radiusKm'=>isset($_REQUEST['radiusKm']) ? wp_unslash($_REQUEST['radiusKm']) : null,
            'limit'=>isset($_REQUEST['limit']) ? wp_unslash($_REQUEST['limit']) : null,
        );
        $payload=$this->wurst_frontend_payload($data);
        if (is_wp_error($payload)) wp_send_json_error(array('ok'=>false,'error'=>$payload->get_error_code()),(int)($payload->get_error_data()['status']??500));
        wp_send_json_success($payload);
    }

    public function rest_wurst_submit(WP_REST_Request $request) {
        $data=(array)$request->get_json_params();
        $name=sanitize_text_field((string)($data['name']??''));
        $city=sanitize_text_field((string)($data['city']??''));
        $address=sanitize_text_field((string)($data['address']??''));
        $website=esc_url_raw((string)($data['website']??''));
        $note=sanitize_textarea_field((string)($data['note']??''));
        $hp=trim((string)($data['company']??''));
        if($hp!=='') return rest_ensure_response(array('ok'=>true,'accepted'=>true));
        if(mb_strlen($name)<2 || mb_strlen($name)>190 || mb_strlen($city)>120 || mb_strlen($address)>240 || mb_strlen($note)>1000) {
            return new WP_REST_Response(array('ok'=>false,'error'=>'invalid-value'),400);
        }
        global $wpdb;
        $payload=array('name'=>$name,'city'=>$city,'address'=>$address,'website'=>$website,'note'=>$note);
        $ok=$wpdb->insert($this->table('place_override_submissions'),array(
            'place_id'=>0,'submission_type'=>'wurst_suggestion','submitter_type'=>'community',
            'payload_json'=>wp_json_encode($payload,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES),
            'status'=>'pending','source_label'=>'Community · Imbissbuden','notes'=>'',
            'created_at'=>current_time('mysql',true),'reviewed_at'=>null,'reviewed_by'=>0,
        ),array('%d','%s','%s','%s','%s','%s','%s','%s','%s','%d'));
        if($ok===false) return new WP_REST_Response(array('ok'=>false,'error'=>'storage-error'),500);
        return rest_ensure_response(array('ok'=>true,'accepted'=>true,'message'=>'Danke! Deine Stammbude landet erst in unserer Prüfung.'));
    }

    public function rest_buedchen_submit(WP_REST_Request $request) {
        global $wpdb;
        $data=(array)$request->get_json_params();

        if(trim((string)($data['company']??''))!=='') {
            return rest_ensure_response(array('ok'=>true,'accepted'=>true));
        }

        $place_id=absint($data['placeId']??0);
        $submitter_type=sanitize_key((string)($data['submitterType']??'community'));
        if(!in_array($submitter_type,array('community','operator'),true)) $submitter_type='community';

        if(!$place_id) return new WP_REST_Response(array('ok'=>false,'error'=>'invalid-submission'),400);

        $places=$this->table('places');
        $place=$wpdb->get_row($wpdb->prepare(
            "SELECT id,name,primary_category,active FROM $places WHERE id=%d",$place_id
        ),ARRAY_A);
        if(!$place || $place['primary_category']!=='buedchen' || !(int)$place['active']) {
            return new WP_REST_Response(array('ok'=>false,'error'=>'unknown-place'),404);
        }

        $rate_key=$this->buedchen_submission_rate_key();
        $count=(int)get_transient($rate_key);
        if($count>=8) {
            return new WP_REST_Response(array('ok'=>false,'error'=>'rate-limited','message'=>'Bitte versuche es später erneut.'),429);
        }
        set_transient($rate_key,$count+1,15*MINUTE_IN_SECONDS);

        $whitelist=$this->buedchen_submission_whitelist();
        $clean=array();

        // v1.3.2: one request may contain several optional fields.
        if(isset($data['fields']) && is_array($data['fields'])) {
            foreach($data['fields'] as $raw_field=>$raw_value) {
                $field=sanitize_key((string)$raw_field);
                if(!in_array($field,$whitelist,true)) continue;
                $valid=false;
                $value=$this->sanitize_buedchen_submission_value($field,$raw_value,$valid);
                if($valid) $clean[$field]=$value;
            }
        } else {
            // Backward compatibility with all existing themes.
            $field=sanitize_key((string)($data['field']??''));
            if(in_array($field,$whitelist,true)) {
                $valid=false;
                $value=$this->sanitize_buedchen_submission_value($field,$data['value']??'',$valid);
                if($valid) $clean[$field]=$value;
            }
        }

        if(!$clean) return new WP_REST_Response(array('ok'=>false,'error'=>'invalid-value'),400);
        if(count($clean)>20) return new WP_REST_Response(array('ok'=>false,'error'=>'too-many-fields'),400);

        $payload=array(
            'fields'=>$clean,
            'place_name'=>(string)$place['name'],
        );
        // Keep legacy shape for a single-field submission so older admin tooling remains readable.
        if(count($clean)===1) {
            $first_key=array_key_first($clean);
            $payload['field']=$first_key;
            $payload['value']=$clean[$first_key];
        }

        $table=$this->table('place_override_submissions');
        $ok=$wpdb->insert($table,array(
            'place_id'=>$place_id,
            'submission_type'=>isset($clean['closed'])&&count($clean)===1?'status':'correction',
            'submitter_type'=>$submitter_type,
            'payload_json'=>wp_json_encode($payload,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES),
            'status'=>'pending',
            'source_label'=>$submitter_type==='operator'?'Betreiberangabe':'Community-Hinweis',
            'notes'=>'',
            'created_at'=>current_time('mysql',true),
            'reviewed_at'=>null,
            'reviewed_by'=>0,
        ),array('%d','%s','%s','%s','%s','%s','%s','%s','%s','%d'));

        if($ok===false) return new WP_REST_Response(array('ok'=>false,'error'=>'storage-error'),500);
        return rest_ensure_response(array(
            'ok'=>true,'accepted'=>true,
            'fieldCount'=>count($clean),
            'message'=>'Danke! Deine Angaben werden gemeinsam geprüft.'
        ));
    }

    private function pending_wurst_suggestions($limit=30) {
        global $wpdb;
        $sub=$this->table('place_override_submissions');
        return (array)$wpdb->get_results($wpdb->prepare(
            "SELECT * FROM $sub WHERE status='pending' AND submission_type='wurst_suggestion' ORDER BY created_at DESC LIMIT %d",
            max(1,min(100,(int)$limit))
        ),ARRAY_A);
    }

    public function admin_wurst_suggestion_review() {
        if(!current_user_can('manage_options')) wp_die('Keine Berechtigung.');
        check_admin_referer('rg_wurst_suggestion_review');
        global $wpdb;
        $id=absint($_POST['submission_id']??0);
        $decision=sanitize_key((string)($_POST['decision']??'reviewed'));
        $status=$decision==='reject'?'rejected':'reviewed';
        if($id){
            $wpdb->update($this->table('place_override_submissions'),array(
                'status'=>$status,'reviewed_at'=>current_time('mysql',true),'reviewed_by'=>get_current_user_id()
            ),array('id'=>$id,'submission_type'=>'wurst_suggestion','status'=>'pending'));
        }
        wp_safe_redirect(add_query_arg(array('page'=>'ruhrpottguru-places'),admin_url('tools.php')).'#rg-wurst-suggestions');
        exit;
    }

    private function place_contribution_categories() {
        return array('food','highlights','culture','activities','buedchen','wurst','night');
    }

    private function place_contribution_fields($category) {
        $common=array('opening_hours','website','phone','description','community_status');
        $by=array(
            'food'=>array('menu_url','reservation_url','cuisine','price_tier'),
            'highlights'=>array('access','accessibility','admission'),
            'culture'=>array('ticket_url','program_url','admission'),
            'activities'=>array('booking_url','activity_type','price_tier','admission'),
            'buedchen'=>array('instagram','mixed_candy','coffee','sandwiches','seating','lottery','parcel_shop','tobacco','late_night'),
            'wurst'=>array('menu_url','cuisine','price_tier'),
        );
        return array_values(array_unique(array_merge($common,$by[$category]??array())));
    }

    private function sanitize_place_contribution_field($field,$value,&$valid) {
        $valid=true;
        $bool_fields=array('mixed_candy','coffee','sandwiches','seating','lottery','parcel_shop','tobacco','late_night');
        if(in_array($field,$bool_fields,true)) return (bool)$value;
        $url_fields=array('website','menu_url','reservation_url','booking_url','ticket_url','program_url');
        if(in_array($field,$url_fields,true)) {
            $v=esc_url_raw(trim((string)$value));
            if($v===''){ $valid=false; return null; }
            return $v;
        }
        $v=trim(sanitize_textarea_field(wp_unslash((string)$value)));
        if($v==='' || mb_strlen($v)>1500){$valid=false;return null;}
        return $v;
    }

    private function contribution_rate_key() {
        $ip=(string)($_SERVER['REMOTE_ADDR']??'');
        $ua=(string)($_SERVER['HTTP_USER_AGENT']??'');
        return 'rg_place_contrib_' . substr(hash_hmac('sha256',$ip.'|'.$ua,wp_salt('nonce')),0,28);
    }

    public function rest_place_contribute(WP_REST_Request $request) {
        global $wpdb;
        $place_id=absint($request->get_param('place_id'));
        $category=sanitize_key((string)$request->get_param('category'));
        if(!$place_id || !in_array($category,$this->place_contribution_categories(),true)) return new WP_REST_Response(array('ok'=>false,'error'=>'invalid-request'),400);
        $places=$this->table('places');
        $place=$wpdb->get_row($wpdb->prepare("SELECT id,name,city FROM $places WHERE id=%d AND active=1",$place_id),ARRAY_A);
        if(!$place) return new WP_REST_Response(array('ok'=>false,'error'=>'place-not-found'),404);

        $rate_key=$this->contribution_rate_key();
        $count=(int)get_transient($rate_key);
        if($count>=8) return new WP_REST_Response(array('ok'=>false,'error'=>'rate-limit'),429);

        $raw_fields=json_decode((string)$request->get_param('fields_json'),true);
        if(!is_array($raw_fields)) $raw_fields=array();
        $allowed=$this->place_contribution_fields($category);
        $clean=array();
        foreach($raw_fields as $raw_field=>$value){
            $field=sanitize_key((string)$raw_field);
            if(!in_array($field,$allowed,true)) continue;
            $valid=true;$sv=$this->sanitize_place_contribution_field($field,$value,$valid);
            if($valid) $clean[$field]=$sv;
        }
        $submitter=sanitize_key((string)$request->get_param('submitter_type'))==='operator'?'operator':'community';
        $source_label=$submitter==='operator'?'Betreiber-Einsendung':'Community-Einsendung';
        $rights_confirmed=(string)$request->get_param('rights_confirmed')==='1';
        $submitter_name=sanitize_text_field(trim((string)$request->get_param('submitter_name')));
        $submitter_email=sanitize_email(trim((string)$request->get_param('submitter_email')));

        $files=$request->get_file_params();
        $image_entries=array();
        $allowed_upload_mimes=array('jpg|jpeg'=>'image/jpeg','png'=>'image/png','webp'=>'image/webp','heic'=>'image/heic','heif'=>'image/heif');
        foreach($files as $key=>$file){
            if(strpos((string)$key,'image_')!==0 || !is_array($file)) continue;
            if(count($image_entries)>=5) break;
            $idx=substr((string)$key,6);
            $upload_error=(int)($file['error']??UPLOAD_ERR_OK);
            if($upload_error!==UPLOAD_ERR_OK){
                $msg=($upload_error===UPLOAD_ERR_INI_SIZE||$upload_error===UPLOAD_ERR_FORM_SIZE)?'Das Bild ist größer als das Server-Uploadlimit.':($upload_error===UPLOAD_ERR_NO_FILE?'Bitte wähle ein Bild aus.':'Das Bild konnte vom Browser nicht vollständig hochgeladen werden.');
                return new WP_REST_Response(array('ok'=>false,'error'=>'upload-error','message'=>$msg),400);
            }
            if(empty($file['tmp_name'])||!is_uploaded_file($file['tmp_name'])) return new WP_REST_Response(array('ok'=>false,'error'=>'upload-missing','message'=>'Die Bilddatei ist beim Upload nicht angekommen. Bitte erneut versuchen.'),400);
            $copyright=trim(sanitize_text_field((string)$request->get_param('copyright_'.$idx)));
            if($copyright==='') return new WP_REST_Response(array('ok'=>false,'error'=>'copyright-required','message'=>'Copyright ist für jedes Bild ein Pflichtfeld.'),400);
            if(!$rights_confirmed) return new WP_REST_Response(array('ok'=>false,'error'=>'rights-confirmation-required','message'=>'Bitte bestätige die Rechteerklärung.'),400);
            if((int)($file['size']??0)>2*1024*1024) return new WP_REST_Response(array('ok'=>false,'error'=>'image-too-large','message'=>'Das hochgeladene Bild darf nach der automatischen Optimierung maximal 2 MB groß sein.'),400);
            $check=wp_check_filetype_and_ext((string)$file['tmp_name'],(string)($file['name']??''),$allowed_upload_mimes);
            $mime=(string)($check['type']??'');if($mime==='')$mime=(string)($file['type']??'');
            if(!in_array($mime,array('image/jpeg','image/png','image/webp','image/heic','image/heif'),true)) return new WP_REST_Response(array('ok'=>false,'error'=>'invalid-image-type','message'=>'Erlaubt sind JPEG, PNG, WebP und – wenn der Server es unterstützt – HEIC/HEIF.'),400);
            $source_url=esc_url_raw(trim((string)$request->get_param('source_url_'.$idx)));
            $image_entries[]=array('file'=>$file,'copyright'=>$copyright,'source_url'=>$source_url,'detected_mime'=>$mime);
        }
        if($image_entries && ($submitter_name==='' || !$submitter_email || !is_email($submitter_email))) return new WP_REST_Response(array('ok'=>false,'error'=>'submitter-contact-required','message'=>'Für Bild-Uploads sind Name und eine gültige E-Mail-Adresse erforderlich.'),400);
        if(!$clean && !$image_entries) return new WP_REST_Response(array('ok'=>false,'error'=>'empty-submission','message'=>'Bitte Daten ergänzen oder mindestens ein Bild auswählen.'),400);

        $now=current_time('mysql',true);
        $subtable=$this->table('place_override_submissions');
        $verification_token=$image_entries?wp_generate_password(48,false,false):'';
        $initial_status=$image_entries?'awaiting_verification':'pending';
        $ok=$wpdb->insert($subtable,array(
            'place_id'=>$place_id,
            'submission_type'=>'place_contribution',
            'submitter_type'=>$submitter,
            'payload_json'=>wp_json_encode(array('category'=>$category,'fields'=>$clean),JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES),
            'status'=>$initial_status,'source_label'=>$source_label,
            'submitter_name'=>$submitter_name,'submitter_email'=>$submitter_email,
            'verification_token_hash'=>$verification_token?hash('sha256',$verification_token):'',
            'rights_statement_version'=>$image_entries?self::RIGHTS_STATEMENT_VERSION:'',
            'rights_statement_text'=>$image_entries?self::RIGHTS_STATEMENT_TEXT:'',
            'rights_confirmed_at'=>$image_entries?$now:null,
            'notes'=>'','created_at'=>$now,
        ));
        if(!$ok) return new WP_REST_Response(array('ok'=>false,'error'=>'db-write-failed'),500);
        $submission_id=(int)$wpdb->insert_id;

        $uploaded_count=0;$upload_failures=array();
        if($image_entries){
            require_once ABSPATH.'wp-admin/includes/file.php';
            require_once ABSPATH.'wp-admin/includes/image.php';
            $mtable=$this->table('place_media_submissions');
            foreach($image_entries as $entry){
                $uploaded=wp_handle_upload($entry['file'],array('test_form'=>false,'mimes'=>$allowed_upload_mimes));
                if(!is_array($uploaded)||!empty($uploaded['error'])||empty($uploaded['url'])){$upload_failures[]=(string)($uploaded['error']??'Upload fehlgeschlagen');continue;}
                $uploaded_type=(string)($uploaded['type']??$entry['detected_mime']??'');
                if(in_array($uploaded_type,array('image/heic','image/heif'),true)){
                    $editor=wp_get_image_editor((string)($uploaded['file']??''));
                    if(is_wp_error($editor)){if(!empty($uploaded['file'])&&is_file($uploaded['file']))@unlink($uploaded['file']);$upload_failures[]='HEIC/HEIF kann auf diesem Server nicht in ein Webbild umgewandelt werden. Bitte JPEG verwenden.';continue;}
                    $editor->set_quality(88);$target=preg_replace('/\.(heic|heif)$/i','.jpg',(string)$uploaded['file']);$saved=$editor->save($target,'image/jpeg');
                    if(is_wp_error($saved)||empty($saved['path'])){if(!empty($uploaded['file'])&&is_file($uploaded['file']))@unlink($uploaded['file']);$upload_failures[]='HEIC/HEIF konnte nicht konvertiert werden. Bitte JPEG verwenden.';continue;}
                    if((string)$saved['path']!==(string)$uploaded['file']&&is_file((string)$uploaded['file']))@unlink((string)$uploaded['file']);
                    $uploads=wp_upload_dir();$uploaded['file']=(string)$saved['path'];$uploaded['type']='image/jpeg';
                    $basepath=wp_normalize_path((string)$uploads['basedir']);$savedpath=wp_normalize_path((string)$saved['path']);
                    $uploaded['url']=rtrim((string)$uploads['baseurl'],'/').'/'.ltrim(str_replace($basepath,'',$savedpath),'/');
                }
                $ok_media=$wpdb->insert($mtable,array(
                    'submission_id'=>$submission_id,'place_id'=>$place_id,'file_url'=>esc_url_raw($uploaded['url']),
                    'file_path'=>(string)($uploaded['file']??''),'mime_type'=>(string)($uploaded['type']??''),
                    'original_name'=>sanitize_file_name((string)($entry['file']['name']??'')),
                    'copyright_text'=>$entry['copyright'],'source_url'=>(string)($entry['source_url']??''),'rights_confirmed'=>1,'status'=>$initial_status,'created_at'=>$now,
                ),array('%d','%d','%s','%s','%s','%s','%s','%s','%d','%s','%s'));
                if($ok_media)$uploaded_count++;
            }
            if($uploaded_count===0){$wpdb->delete($subtable,array('id'=>$submission_id),array('%d'));return new WP_REST_Response(array('ok'=>false,'error'=>'image-upload-failed','message'=>$upload_failures?implode(' ',array_unique($upload_failures)):'Das Bild konnte nicht gespeichert werden. Bitte versuche es erneut.'),400);}
        }
        $mail_sent=true;
        if($image_entries){
            $verify_url=add_query_arg(array('rpg_verify_submission'=>$submission_id,'token'=>$verification_token),home_url('/'));
            $subject='RuhrpottGuru: Bild-Einsendung bestätigen';
            $body="Hallo ".$submitter_name.",

bitte bestätige deine Bild-Einsendung mit diesem Link:
".$verify_url."

Erst danach erscheint sie in der redaktionellen Prüfung.

RuhrpottGuru";
            $mail_sent=(bool)wp_mail($submitter_email,$subject,$body,array('Content-Type: text/plain; charset=UTF-8'));
        }
        set_transient($rate_key,$count+1,10*MINUTE_IN_SECONDS);
        $message=$image_entries?($mail_sent?'Danke! Das Foto wurde gespeichert. Bitte bestätige jetzt die E-Mail, die wir dir geschickt haben. Erst danach landet die Einsendung in der Redaktion.':'Das Foto wurde gespeichert, aber die Bestätigungs-E-Mail konnte gerade nicht versendet werden. Bitte versuche es später noch einmal oder melde dich bei RuhrpottGuru.'):'Danke! Deine Angaben warten jetzt auf redaktionelle Freigabe.';
        return rest_ensure_response(array('ok'=>true,'submissionId'=>$submission_id,'uploadedCount'=>$uploaded_count,'emailSent'=>$mail_sent,'message'=>$message));
    }


    public function handle_contribution_email_verification() {
        if(empty($_GET['rpg_verify_submission']) || empty($_GET['token'])) return;
        global $wpdb;
        $id=absint($_GET['rpg_verify_submission']);$token=(string)$_GET['token'];
        $sub=$this->table('place_override_submissions');$media=$this->table('place_media_submissions');
        $row=$wpdb->get_row($wpdb->prepare("SELECT * FROM $sub WHERE id=%d",$id),ARRAY_A);
        if(!$row || $row['status']!=='awaiting_verification' || empty($row['verification_token_hash']) || !hash_equals((string)$row['verification_token_hash'],hash('sha256',$token))){
            wp_die('<h1>Bestätigung nicht möglich</h1><p>Der Link ist ungültig oder wurde bereits verwendet.</p>','RuhrpottGuru',array('response'=>400));
        }
        $now=current_time('mysql',true);
        $wpdb->update($sub,array('status'=>'pending','email_verified_at'=>$now,'verification_token_hash'=>''),array('id'=>$id));
        $wpdb->update($media,array('status'=>'pending'),array('submission_id'=>$id,'status'=>'awaiting_verification'));
        wp_die('<h1>Danke!</h1><p>Deine E-Mail-Adresse wurde bestätigt. Die Einsendung wartet jetzt auf redaktionelle Freigabe.</p><p><a href="'.esc_url(home_url('/')).'">Zurück zu RuhrpottGuru</a></p>','RuhrpottGuru',array('response'=>200));
    }

    public function admin_place_rights_dossier() {
        if(!current_user_can('manage_options')) wp_die('Keine Berechtigung.');
        $id=absint($_GET['submission_id']??0);check_admin_referer('rg_place_rights_dossier_'.$id);
        global $wpdb;$sub=$this->table('place_override_submissions');$ms=$this->table('place_media_submissions');$places=$this->table('places');
        $row=$wpdb->get_row($wpdb->prepare("SELECT s.*,p.name place_name,p.city,p.street,p.house_number FROM $sub s LEFT JOIN $places p ON p.id=s.place_id WHERE s.id=%d",$id),ARRAY_A);
        if(!$row) wp_die('Einsendung nicht gefunden.');
        $imgs=(array)$wpdb->get_results($wpdb->prepare("SELECT * FROM $ms WHERE submission_id=%d ORDER BY id ASC",$id),ARRAY_A);
        nocache_headers();header('Content-Type: text/html; charset=UTF-8');
        echo '<!doctype html><html><head><meta charset="utf-8"><title>Rechteakte #'.intval($id).'</title><style>body{font:15px/1.5 Arial,sans-serif;max-width:900px;margin:40px auto;color:#111}h1{margin-bottom:0}.muted{color:#666}table{border-collapse:collapse;width:100%;margin:20px 0}td,th{border:1px solid #ccc;padding:8px;text-align:left;vertical-align:top}img{max-width:240px;max-height:180px}.print{position:fixed;right:20px;top:20px}@media print{.print{display:none}body{margin:0}}</style></head><body><button class="print" onclick="window.print()">Drucken / als PDF speichern</button>';
        echo '<h1>RuhrpottGuru - Rechteakte</h1><p class="muted">Einsendung #'.intval($id).' · erzeugt '.esc_html(current_time('mysql')).'</p><table>';
        $pairs=array('Location'=>$row['place_name'].' · '.$row['city'],'Place-ID'=>$row['place_id'],'Eingereicht am'=>$row['created_at'],'Einreicher'=>$row['submitter_name'],'E-Mail'=>$row['submitter_email'],'E-Mail bestätigt am'=>$row['email_verified_at']?:'nicht bestätigt','Rechteerklärung Version'=>$row['rights_statement_version'],'Rechteerklärung'=>$row['rights_statement_text'],'Rechteerklärung bestätigt am'=>$row['rights_confirmed_at'],'Status'=>$row['status'],'Quelle'=>$row['source_label']);
        foreach($pairs as $k=>$v)echo '<tr><th>'.esc_html($k).'</th><td>'.esc_html((string)$v).'</td></tr>';echo '</table><h2>Bilder</h2>';
        foreach($imgs as $m){echo '<table><tr><th>Bild-ID</th><td>'.intval($m['id']).'</td></tr><tr><th>Originaldatei</th><td>'.esc_html($m['original_name']).'</td></tr><tr><th>Copyrightangabe</th><td>'.esc_html($m['copyright_text']).'</td></tr><tr><th>Quelle</th><td>'.esc_html($m['source_url']).'</td></tr><tr><th>Status</th><td>'.esc_html($m['status']).'</td></tr><tr><th>Prüfung</th><td>'.esc_html($m['reviewed_at']?:'offen').'</td></tr><tr><td colspan="2"><img src="'.esc_url($m['file_url']).'"></td></tr></table>';}
        echo '<p><strong>Hinweis:</strong> Diese Akte dokumentiert technische und redaktionelle Vorgänge. Sie ist keine rechtliche Bewertung der Haftung.</p></body></html>';exit;
    }

    private function pending_place_contributions($limit=80) {
        global $wpdb;
        $sub=$this->table('place_override_submissions');$places=$this->table('places');
        return (array)$wpdb->get_results($wpdb->prepare(
            "SELECT s.*,p.name AS place_name,p.city,p.street,p.house_number FROM $sub s LEFT JOIN $places p ON p.id=s.place_id WHERE s.status='pending' AND s.submission_type='place_contribution' ORDER BY s.created_at DESC LIMIT %d",max(1,min(200,(int)$limit))),ARRAY_A);
    }

    private function pending_place_media_submissions($limit=120) {
        global $wpdb;
        $m=$this->table('place_media_submissions');$places=$this->table('places');
        return (array)$wpdb->get_results($wpdb->prepare(
            "SELECT m.*,p.name AS place_name,p.city,s.payload_json AS parent_payload_json,s.submission_type AS parent_submission_type FROM $m m LEFT JOIN $places p ON p.id=m.place_id LEFT JOIN {$this->table('place_override_submissions')} s ON s.id=m.submission_id WHERE m.status='pending' ORDER BY m.created_at DESC LIMIT %d",max(1,min(300,(int)$limit))),ARRAY_A);
    }

    public function admin_place_contribution_review() {
        if(!current_user_can('manage_options'))wp_die('Keine Berechtigung.');check_admin_referer('rg_place_contribution_review');global $wpdb;
        $id=absint($_POST['submission_id']??0);$decision=sanitize_key((string)($_POST['decision']??''));$field=sanitize_key((string)($_POST['field_name']??''));$subtable=$this->table('place_override_submissions');
        $sub=$wpdb->get_row($wpdb->prepare("SELECT * FROM $subtable WHERE id=%d AND status='pending' AND submission_type='place_contribution'",$id),ARRAY_A);if(!$sub){wp_safe_redirect(add_query_arg(array('page'=>'rp-redaktion'),admin_url('admin.php')));exit;}
        $payload=json_decode((string)$sub['payload_json'],true);if(!is_array($payload))$payload=array();$fields=is_array($payload['fields']??null)?$payload['fields']:array();
        if($field===''||!array_key_exists($field,$fields))wp_die('Datenfeld nicht gefunden.');$value=$fields[$field];
        if($decision==='approve_field'){$orow=$this->override_row((int)$sub['place_id']);$odata=$this->decode_override_data($orow?:'');$now=current_time('mysql',true);$bool_fields=array('mixed_candy','coffee','sandwiches','seating','lottery','parcel_shop','tobacco','late_night');
            if(in_array($field,$bool_fields,true))$odata['features'][$field]=(bool)$value;else $odata['fields'][$field]=array('value'=>(string)$value,'source_type'=>$sub['submitter_type']==='operator'?'operator':'community','source_label'=>(string)$sub['source_label'],'verified_at'=>$now);
            $this->save_override_data((int)$sub['place_id'],$odata,$sub['submitter_type']==='operator'?'operator':'community',(string)$sub['source_label'],true);
        }elseif($decision!=='reject_field')wp_die('Ungültige Entscheidung.');
        unset($fields[$field]);$payload['fields']=$fields;$history=is_array($payload['reviewed_fields']??null)?$payload['reviewed_fields']:array();$history[$field]=array('decision'=>$decision==='approve_field'?'approved':'rejected','reviewed_at'=>current_time('mysql',true),'reviewed_by'=>get_current_user_id());$payload['reviewed_fields']=$history;
        $status=$fields?'pending':'reviewed';$wpdb->update($subtable,array('payload_json'=>wp_json_encode($payload,JSON_UNESCAPED_SLASHES|JSON_UNESCAPED_UNICODE),'status'=>$status,'reviewed_at'=>current_time('mysql',true),'reviewed_by'=>get_current_user_id()),array('id'=>$id),array('%s','%s','%s','%d'),array('%d'));
        wp_safe_redirect(add_query_arg(array('page'=>'rp-redaktion','rg_contribution_reviewed'=>'1'),admin_url('admin.php')));exit;
    }

    public function admin_place_media_submission_review() {
        if(!current_user_can('manage_options')) wp_die('Keine Berechtigung.');
        check_admin_referer('rg_place_media_submission_review');
        global $wpdb;
        $id=absint($_POST['media_submission_id']??0);$decision=sanitize_key((string)($_POST['decision']??'reject'));
        $mtable=$this->table('place_media_submissions');
        $m=$wpdb->get_row($wpdb->prepare("SELECT * FROM $mtable WHERE id=%d AND status='pending'",$id),ARRAY_A);
        if(!$m){wp_safe_redirect(add_query_arg(array('page'=>'rp-redaktion-medien'),admin_url('admin.php')));exit;}
        $subtable=$this->table('place_override_submissions');
        $parent=$wpdb->get_row($wpdb->prepare("SELECT submission_type,payload_json FROM $subtable WHERE id=%d",(int)$m['submission_id']),ARRAY_A);
        $payload=json_decode((string)($parent['payload_json']??''),true);if(!is_array($payload))$payload=array();
        $is_night=(sanitize_key((string)($payload['category']??''))==='night' || (string)($parent['submission_type']??'')==='night_photo');
        if($decision==='approve'){
            $media=$this->table('place_media');$now=current_time('mysql',true);$relation=$is_night?'night':'place';
            $has_primary=(int)$wpdb->get_var($wpdb->prepare("SELECT COUNT(*) FROM $media WHERE place_id=%d AND relation_type=%s AND is_primary=1 AND moderation_status='active'",(int)$m['place_id'],$relation));
            $credit='© '.trim((string)$m['copyright_text']);
            $wpdb->insert($media,array(
                'place_id'=>(int)$m['place_id'],'media_type'=>'image','url'=>(string)$m['file_url'],'source'=>$is_night?'community_night_upload':'community_upload','source_url'=>(string)$m['source_url'],
                'license'=>'Nutzung für RuhrpottGuru bestätigt','artist'=>(string)$m['copyright_text'],'credit'=>$credit,'relation_type'=>$relation,
                'identity_confidence'=>1.0,'visual_quality'=>0.90,'is_primary'=>$has_primary?0:1,'moderation_status'=>'active','verified_at'=>$now,'last_seen_at'=>$now,
            ),array('%d','%s','%s','%s','%s','%s','%s','%s','%s','%f','%f','%d','%s','%s','%s'));
            if($is_night){
                $night=$this->table('place_night_profiles');
                $existing=(int)$wpdb->get_var($wpdb->prepare("SELECT COUNT(*) FROM $night WHERE place_id=%d",(int)$m['place_id']));
                $data=array('status'=>'active','night_score'=>85.0,'tags_json'=>wp_json_encode(array('photo'),JSON_UNESCAPED_UNICODE),'reason'=>'Redaktionell freigegebenes Nachtfoto vorhanden.','access_status'=>'unknown','source_type'=>'community_photo','verified_at'=>$now,'updated_at'=>$now);
                if($existing)$wpdb->update($night,$data,array('place_id'=>(int)$m['place_id']));
                else{$data['place_id']=(int)$m['place_id'];$wpdb->insert($night,$data);}
            }
            $status='approved';
        }else{
            $status='rejected';
            $path=(string)$m['file_path'];if($path && is_file($path)) @unlink($path);
        }
        $wpdb->update($mtable,array('status'=>$status,'reviewed_at'=>current_time('mysql',true),'reviewed_by'=>get_current_user_id()),array('id'=>$id),array('%s','%s','%d'),array('%d'));
        update_option(self::OPTION_CATALOG_VERSION,'night-media-'.gmdate('YmdHis'),false);
        wp_safe_redirect(add_query_arg(array('page'=>'rp-redaktion-medien','rg_media_reviewed'=>'1','media_relation'=>$is_night?'night':''),admin_url('admin.php')));exit;
    }


    private function place_media_admin_filters() {
        return array('search'=>sanitize_text_field((string)($_GET['media_search']??'')),'source'=>sanitize_key((string)($_GET['media_source']??'')),'status'=>sanitize_key((string)($_GET['media_status']??'')),'category'=>sanitize_key((string)($_GET['media_category']??'')),'relation'=>sanitize_key((string)($_GET['media_relation']??'')),'content'=>sanitize_key((string)($_GET['media_content']??'')),'limit'=>50);
    }

    private function place_media_admin_where($filters,&$params) {
        global $wpdb;$params=array();$where=array("m.media_type='image'");$status=$filters['status']??'';if(in_array($status,array('active','disabled'),true)){$where[]='m.moderation_status=%s';$params[]=$status;}$source=$filters['source']??'';if($source!==''){$where[]='m.source=%s';$params[]=$source;}$relation=$filters['relation']??'';if(in_array($relation,array('place','night'),true)){$where[]='m.relation_type=%s';$params[]=$relation;}$content=$filters['content']??'';if($content==='text_any'){$where[]="m.content_class IN ('mixed','text')";}elseif(in_array($content,array('image','mixed','text','unknown','unavailable'),true)){$where[]='m.content_class=%s';$params[]=$content;}$category=$filters['category']??'';if(in_array($category,array('food','highlights','culture','activities'),true)){$where[]='EXISTS (SELECT 1 FROM '.$this->table('place_categories').' pc WHERE pc.place_id=m.place_id AND pc.category=%s)';$params[]=$category;}$search=trim((string)($filters['search']??''));if($search!==''){$like='%'.$wpdb->esc_like($search).'%';if(ctype_digit($search)){$where[]='(m.id=%d OR p.id=%d OR p.name LIKE %s OR p.city LIKE %s OR p.street LIKE %s OR m.artist LIKE %s OR m.credit LIKE %s OR m.source_url LIKE %s OR m.url LIKE %s)';$params[]=(int)$search;$params[]=(int)$search;for($i=0;$i<7;$i++)$params[]=$like;}else{$where[]='(p.name LIKE %s OR p.city LIKE %s OR p.street LIKE %s OR m.artist LIKE %s OR m.credit LIKE %s OR m.source_url LIKE %s OR m.url LIKE %s)';for($i=0;$i<7;$i++)$params[]=$like;}}return $where;
    }

