                $where[]='(em.id=%d OR e.id=%d OR e.title LIKE %s OR e.venue_name LIKE %s OR e.city LIKE %s OR e.street LIKE %s OR em.artist LIKE %s OR em.credit LIKE %s OR em.rights_holder LIKE %s OR em.source_url LIKE %s OR em.url LIKE %s)';
