            $cur=$groups[$key]['representative'];$rScore=((string)($r['moderation_status']??'')==='active'?100:0)+(!empty($r['is_primary'])?20:0)+((string)($r['local_cache_status']??'')==='ready'?10:0);$cScore=((string)($cur['moderation_status']??'')==='active'?100:0)+(!empty($cur['is_primary'])?20:0)+((string)($cur['local_cache_status']??'')==='ready'?10:0);if($rScore>$cScore)$groups[$key]['representative']=$r;
