    private function log_place_media_action($row,$action,$reason='',$requested_by='') {
        global $wpdb;$log=$this->table('place_media_removal_log');
        $wpdb->insert($log,array(
            'media_id'=>(int)($row['id']??0),'place_id'=>(int)($row['place_id']??0),
            'action_type'=>sanitize_key((string)$action),'reason'=>sanitize_textarea_field((string)$reason),
            'requested_by'=>sanitize_text_field((string)$requested_by),
            'media_snapshot'=>wp_json_encode($row,JSON_UNESCAPED_SLASHES|JSON_UNESCAPED_UNICODE),
            'created_by'=>get_current_user_id(),'created_at'=>current_time('mysql',true),
        ),array('%d','%d','%s','%s','%s','%s','%d','%s'));
