    private function promote_place_media_primary($place_id,$relation_type='place') {
        global $wpdb;$media=$this->table('place_media');$place_id=(int)$place_id;$relation_type=in_array($relation_type,array('place','night'),true)?$relation_type:'place';
        $active_primary=(int)$wpdb->get_var($wpdb->prepare("SELECT id FROM $media WHERE place_id=%d AND relation_type=%s AND media_type='image' AND moderation_status='active' AND is_primary=1 ORDER BY id ASC LIMIT 1",$place_id,$relation_type));
        if($active_primary)return;
        $next=(int)$wpdb->get_var($wpdb->prepare("SELECT id FROM $media WHERE place_id=%d AND relation_type=%s AND media_type='image' AND moderation_status='active' ORDER BY identity_confidence DESC,visual_quality DESC,verified_at DESC,id ASC LIMIT 1",$place_id,$relation_type));
        if($next)$wpdb->update($media,array('is_primary'=>1),array('id'=>$next),array('%d'),array('%d'));
    }

    private function delete_local_media_file_if_owned($url) {
        $url=(string)$url;if($url==='')return false;$uploads=wp_upload_dir();
        $baseurl=rtrim((string)($uploads['baseurl']??''),'/');$basedir=rtrim((string)($uploads['basedir']??''),DIRECTORY_SEPARATOR);
        if($baseurl===''||$basedir===''||strpos($url,$baseurl.'/')!==0)return false;
        $rel=substr($url,strlen($baseurl)+1);$rel=str_replace(array('../','..\\'),'',$rel);
        $path=$basedir.DIRECTORY_SEPARATOR.str_replace('/',DIRECTORY_SEPARATOR,$rel);
        if(is_file($path))return @unlink($path);return false;
    }

    public function admin_place_media_manage() {
        if(!current_user_can('manage_options'))wp_die('Keine Berechtigung.');check_admin_referer('rg_place_media_manage');
        global $wpdb;$id=absint($_POST['media_id']??0);$action=sanitize_key((string)($_POST['media_action']??''));
        $reason=sanitize_textarea_field((string)($_POST['reason']??''));$requested_by=sanitize_text_field((string)($_POST['requested_by']??''));
        $media=$this->table('place_media');$row=$wpdb->get_row($wpdb->prepare("SELECT * FROM $media WHERE id=%d",$id),ARRAY_A);
        if(!$row)wp_die('Bild nicht gefunden.');
        if(in_array($action,array('disable','delete'),true)&&trim($reason)==='')wp_die('Bitte einen Lösch-/Deaktivierungsgrund angeben.');
        $place_id=(int)$row['place_id'];$relation=(string)($row['relation_type']??'place');
        if($action==='disable'){
            $this->log_place_media_action($row,'disabled',$reason,$requested_by);
            $wpdb->update($media,array('moderation_status'=>'disabled','is_primary'=>0,'disabled_at'=>current_time('mysql',true),'disabled_by'=>get_current_user_id(),'removal_reason'=>$reason),array('id'=>$id),array('%s','%d','%s','%d','%s'),array('%d'));
            $this->promote_place_media_primary($place_id,$relation);
        }elseif($action==='reactivate'){
            $this->log_place_media_action($row,'reactivated',$reason,$requested_by);
            $wpdb->update($media,array('moderation_status'=>'active','disabled_at'=>null,'disabled_by'=>0,'removal_reason'=>null),array('id'=>$id),array('%s','%s','%d','%s'),array('%d'));
            $this->promote_place_media_primary($place_id,$relation);
        }elseif($action==='delete'){
            $this->log_place_media_action($row,'deleted',$reason,$requested_by);$this->delete_local_media_file_if_owned((string)$row['url']);
            $wpdb->delete($media,array('id'=>$id),array('%d'));$this->promote_place_media_primary($place_id,$relation);
        }elseif($action==='set_primary' && $relation==='night'){
            $wpdb->query($wpdb->prepare("UPDATE $media SET is_primary=0 WHERE place_id=%d AND relation_type='night'",$place_id));
            $wpdb->update($media,array('is_primary'=>1),array('id'=>$id),array('%d'),array('%d'));
            $this->log_place_media_action($row,'night_primary','','');
        }else wp_die('Ungültige Aktion.');
        update_option(self::OPTION_CATALOG_VERSION,'media-'.gmdate('YmdHis'),false);
        $args=array('page'=>'rp-redaktion-medien','rg_media_managed'=>'1');
        foreach(array('media_search','media_source','media_status','media_category','media_relation','media_content') as $key)if(isset($_POST[$key])&&(string)$_POST[$key]!=='')$args[$key]=sanitize_text_field((string)$_POST[$key]);
        wp_safe_redirect(add_query_arg($args,admin_url('admin.php')).'#rg-media-library');exit;
    }


    public function admin_media_crop_override_v101112() {
        if(!current_user_can('manage_options'))wp_die('Keine Berechtigung.');
        check_admin_referer('rg_media_crop_override');
        global $wpdb;
        $table=$this->table('media_crop_overrides');
        $action=sanitize_key((string)($_POST['crop_action']??'save'));
        $target=$this->media_crop_direct_target_v101118($_POST);
        $master='';$keys=array();

        // 1.10.122: direct editors always resolve one canonical crop identity from
        // the concrete DB row. Client-provided URL/alias/master keys are ignored.
        if($target['id']>0){
            $direct=$this->media_crop_direct_group_v101118($target['scope'],$target['id']);
            if(!$direct)wp_die('Das ausgewählte Bild wurde nicht gefunden.');
            $master=strtolower((string)$direct['master_key']);
            $keys=array($master);
        }else{
            $master=strtolower(trim((string)($_POST['master_key']??'')));
            foreach((array)($_POST['identity_keys']??array()) as $k){
                $k=strtolower(trim(sanitize_text_field((string)$k)));
                if(preg_match('/^[a-f0-9]{64}$/',$k))$keys[$k]=1;
            }
            $keys=array_keys($keys);
            if(!$keys&&preg_match('/^[a-f0-9]{64}$/',$master))$keys=array($master);
        }
        if(!preg_match('/^[a-f0-9]{64}$/',$master))wp_die('Ungültige Medien-ID.');
        $keys=array_values(array_unique(array_filter($keys,function($k){return preg_match('/^[a-f0-9]{64}$/',$k);})));
        if(!$keys)$keys=array($master);

        if($action==='reset'){
            // Canonical reset only. Legacy URL/source-url alias rows are deliberately
            // left inert instead of deleting a possibly unrelated old alias cluster.
            foreach(array_chunk($keys,100) as $chunk){
                $ph=implode(',',array_fill(0,count($chunk),'%s'));
                $wpdb->query($wpdb->prepare("DELETE FROM $table WHERE identity_key IN ($ph)",...$chunk));
            }
        }else{
            $clamp=function($v,$min,$max){return max($min,min($max,(float)$v));};
            $row=array(
                'master_key'=>$master,
                'card_x'=>$clamp($_POST['card_x']??50,0,100),
                'card_y'=>$clamp($_POST['card_y']??50,0,100),
                'card_zoom'=>$clamp($_POST['card_zoom']??1,0,2.5),
                'detail_x'=>$clamp($_POST['detail_x']??50,0,100),
                'detail_y'=>$clamp($_POST['detail_y']??50,0,100),
                'detail_zoom'=>$clamp($_POST['detail_zoom']??1,0,2.5),
                'updated_by'=>get_current_user_id(),
                'updated_at'=>current_time('mysql',true)
            );
            foreach($keys as $key){
                $data=array_merge(array('identity_key'=>$key),$row);
                $wpdb->replace($table,$data,array('%s','%s','%f','%f','%f','%f','%f','%f','%d','%s'));
            }
        }
        update_option(self::OPTION_CATALOG_VERSION,'media-crop-'.gmdate('YmdHis'),false);
        $q=sanitize_text_field((string)($_POST['crop_search']??''));

        if(sanitize_key((string)($_POST['crop_return']??''))==='library' && $target['id']>0){
            $args=array('page'=>'rp-redaktion-medien','rg_crop_saved'=>'1','crop_edit_scope'=>$target['scope'],'crop_edit_id'=>$target['id']);
            foreach(array('media_search','media_source','media_status','media_category','media_relation','media_content') as $key){
                if(isset($_POST[$key])&&(string)$_POST[$key]!=='')$args[$key]=sanitize_text_field((string)$_POST[$key]);
            }
            wp_safe_redirect(add_query_arg($args,admin_url('admin.php')).'#rg-media-inline-'.$target['scope'].'-'.$target['id']);
            exit;
        }

        $args=array('page'=>'rp-redaktion-medien','crop_search'=>$q,'rg_crop_saved'=>'1');
        if($target['id']>0){$args['crop_scope']=$target['scope'];$args['crop_media_id']=$target['id'];$args['crop_focus']=$target['legacy'];}
        wp_safe_redirect(add_query_arg($args,admin_url('admin.php')).'#rg-media-crop');
        exit;
    }

    private function media_crop_admin_groups_v101112($search,$focus='') {
        global $wpdb;
        $search=trim((string)$search);if($search==='')return array();
        $like='%'.$wpdb->esc_like($search).'%';$rows=array();
        $focusScope='';$focusId=0;if(preg_match('/^(place|event):(\d+)$/',(string)$focus,$fm)){$focusScope=(string)$fm[1];$focusId=(int)$fm[2];}
        $pm=$this->table('place_media');$p=$this->table('places');
        $placeRows=(array)$wpdb->get_results($wpdb->prepare("SELECT m.*,p.name entity_name,p.city entity_city,'place' media_scope FROM $pm m LEFT JOIN $p p ON p.id=m.place_id WHERE m.media_type='image' AND (p.name LIKE %s OR p.city LIKE %s OR m.artist LIKE %s OR m.credit LIKE %s OR m.url LIKE %s OR m.source_url LIKE %s OR m.source LIKE %s) ORDER BY m.last_seen_at DESC,m.id DESC LIMIT 240",$like,$like,$like,$like,$like,$like,$like),ARRAY_A);
        foreach($placeRows as &$r){$r['_scope']='place';$r['_public_url']=(string)($r['url']??'');$r['_entity']='Ort: '.trim((string)($r['entity_name']??'')).(!empty($r['entity_city'])?' · '.$r['entity_city']:'');}unset($r);$rows=array_merge($rows,$placeRows);
        $em=$this->table('event_media');$e=$this->table('events');
        $eventRows=(array)$wpdb->get_results($wpdb->prepare("SELECT m.*,e.title event_title,e.venue_name,e.city entity_city,'event' media_scope FROM $em m LEFT JOIN $e e ON e.id=m.event_id WHERE m.media_type='image' AND (e.title LIKE %s OR e.venue_name LIKE %s OR e.city LIKE %s OR m.artist LIKE %s OR m.credit LIKE %s OR m.url LIKE %s OR m.source_url LIKE %s OR m.source LIKE %s) ORDER BY m.id DESC LIMIT 240",$like,$like,$like,$like,$like,$like,$like,$like),ARRAY_A);
        foreach($eventRows as &$r){$r['_scope']='event';$local=$this->event_local_media_public_url_v1039($r);$r['_public_url']=$local!==''?$local:(string)($r['url']??'');$label=trim((string)($r['venue_name']??''));if($label==='')$label=trim((string)($r['event_title']??''));$r['_entity']='Event: '.$label.(!empty($r['entity_city'])?' · '.$r['entity_city']:'');}unset($r);$rows=array_merge($rows,$eventRows);
        if($focusId>0){
            $focusRow=null;
            if($focusScope==='place'){
                $focusRow=$wpdb->get_row($wpdb->prepare("SELECT m.*,p.name entity_name,p.city entity_city,'place' media_scope FROM $pm m LEFT JOIN $p p ON p.id=m.place_id WHERE m.media_type='image' AND m.id=%d LIMIT 1",$focusId),ARRAY_A);
                if($focusRow){$focusRow['_scope']='place';$focusRow['_public_url']=(string)($focusRow['url']??'');$focusRow['_entity']='Ort: '.trim((string)($focusRow['entity_name']??'')).(!empty($focusRow['entity_city'])?' · '.$focusRow['entity_city']:'');}
            }elseif($focusScope==='event'){
                $focusRow=$wpdb->get_row($wpdb->prepare("SELECT m.*,e.title event_title,e.venue_name,e.city entity_city,'event' media_scope FROM $em m LEFT JOIN $e e ON e.id=m.event_id WHERE m.media_type='image' AND m.id=%d LIMIT 1",$focusId),ARRAY_A);
                if($focusRow){$focusRow['_scope']='event';$local=$this->event_local_media_public_url_v1039($focusRow);$focusRow['_public_url']=$local!==''?$local:(string)($focusRow['url']??'');$label=trim((string)($focusRow['venue_name']??''));if($label==='')$label=trim((string)($focusRow['event_title']??''));$focusRow['_entity']='Event: '.$label.(!empty($focusRow['entity_city'])?' · '.$focusRow['entity_city']:'');}
            }
            if($focusRow){
                $seen=false;foreach($rows as $rr){if((string)($rr['_scope']??'')===$focusScope&&(int)($rr['id']??0)===$focusId){$seen=true;break;}}
                if(!$seen)$rows[]=$focusRow;
            }
        }
        if(!$rows)return array();

        $groups=array();
        foreach($rows as $r){
            $identity=$this->media_crop_canonical_identity_v101122($r,(string)$r['_scope']);
            $key=(string)($identity['key']??'');
            if(!preg_match('/^[a-f0-9]{64}$/',$key))continue;
            if(!isset($groups[$key]))$groups[$key]=array('rows'=>array(),'key'=>$key,'identity'=>$identity);
            $groups[$key]['rows'][]=$r;
        }
        if(!$groups)return array();

        $cropTable=$this->table('media_crop_overrides');$over=array();$keys=array_keys($groups);
        foreach(array_chunk($keys,200) as $chunk){
            $ph=implode(',',array_fill(0,count($chunk),'%s'));
            foreach((array)$wpdb->get_results($wpdb->prepare("SELECT * FROM $cropTable WHERE identity_key IN ($ph)",...$chunk),ARRAY_A) as $o)$over[(string)$o['identity_key']]=$o;
        }
        $out=array();
        foreach($groups as $key=>$g){
            $override=$over[$key]??null;$preview='';
            $activeFirst=array_values(array_filter($g['rows'],function($r){return (string)($r['moderation_status']??'active')==='active'&&!empty($r['_public_url']);}));
            $cand=$activeFirst?:array_values(array_filter($g['rows'],function($r){return !empty($r['_public_url']);}));
            if($cand)$preview=(string)$cand[0]['_public_url'];
            $entities=array();foreach($g['rows'] as $r)if(!empty($r['_entity']))$entities[$r['_entity']]=1;
            $out[]=array('master_key'=>$key,'keys'=>array($key),'rows'=>$g['rows'],'override'=>$override,'preview'=>$preview,'entities'=>array_keys($entities),'identity'=>$g['identity']);
        }
        usort($out,function($a,$b){return count($b['rows'])<=>count($a['rows']);});
        return $out;
    }

    private function media_crop_direct_target_v101118($src) {
        $src=is_array($src)?$src:array();$scope=sanitize_key((string)($src['crop_scope']??''));$id=absint($src['crop_media_id']??0);
        if(in_array($scope,array('place','event'),true)&&$id>0)return array('scope'=>$scope,'id'=>$id,'legacy'=>$scope.':'.$id);
        $legacy=sanitize_text_field((string)($src['crop_focus']??''));if(preg_match('/^(place|event):(\d+)$/',$legacy,$m))return array('scope'=>(string)$m[1],'id'=>(int)$m[2],'legacy'=>$legacy);
