    private function media_crop_direct_group_v101118($scope,$id) {
        global $wpdb;
        $scope=$scope==='event'?'event':($scope==='place'?'place':'');
        $id=absint($id);
        if($scope===''||$id<=0)return null;
        if($scope==='place'){
            $pm=$this->table('place_media');$p=$this->table('places');
            $r=$wpdb->get_row($wpdb->prepare("SELECT m.*,p.name entity_name,p.city entity_city,'place' media_scope FROM $pm m LEFT JOIN $p p ON p.id=m.place_id WHERE m.media_type='image' AND m.id=%d LIMIT 1",$id),ARRAY_A);
            if(!$r)return null;
            $r['_scope']='place';$r['_public_url']=(string)($r['url']??'');
            $r['_entity']='Ort: '.trim((string)($r['entity_name']??'')).(!empty($r['entity_city'])?' · '.$r['entity_city']:'');
        }else{
            $em=$this->table('event_media');$e=$this->table('events');
            $r=$wpdb->get_row($wpdb->prepare("SELECT m.*,e.title event_title,e.venue_name,e.city entity_city,'event' media_scope FROM $em m LEFT JOIN $e e ON e.id=m.event_id WHERE m.media_type='image' AND m.id=%d LIMIT 1",$id),ARRAY_A);
            if(!$r)return null;
            $r['_scope']='event';$local=$this->event_local_media_public_url_v1039($r);
            $r['_public_url']=$local!==''?$local:(string)($r['url']??'');
            $label=trim((string)($r['venue_name']??''));if($label==='')$label=trim((string)($r['event_title']??''));
            $r['_entity']='Event: '.$label.(!empty($r['entity_city'])?' · '.$r['entity_city']:'');
        }
        $identity=$this->media_crop_canonical_identity_v101122($r,$scope);
        $key=(string)($identity['key']??'');
        if(!preg_match('/^[a-f0-9]{64}$/',$key))return null;
        $cropTable=$this->table('media_crop_overrides');
        $override=$wpdb->get_row($wpdb->prepare("SELECT * FROM $cropTable WHERE identity_key=%s LIMIT 1",$key),ARRAY_A);
        return array(
            'master_key'=>$key,
            'keys'=>array($key),
            'rows'=>array($r),
            'override'=>$override?:null,
            'preview'=>(string)($r['_public_url']??''),
            'entities'=>array((string)($r['_entity']??'')),
            'identity'=>$identity,
            'legacy_master'=>$override?(string)($override['master_key']??''):'',
            '_direct'=>true,'_direct_scope'=>$scope,'_direct_id'=>$id
        );
    }

