    private function media_crop_group_from_card_v101121($scope,$row,$preview) {
        global $wpdb;
        $scope=$scope==='event'?'event':($scope==='place'?'place':'');
        $row=is_array($row)?$row:array();
        $id=absint($row['id']??0);
        $preview=esc_url_raw((string)$preview);
        if($scope===''||$id<=0||$preview==='')return null;
        $row['_scope']=$scope;$row['_public_url']=$preview;
        $identity=$this->media_crop_canonical_identity_v101122($row,$scope);
        $key=strtolower((string)($identity['key']??''));
        if(!preg_match('/^[a-f0-9]{64}$/',$key))return null;
        $cropTable=$this->table('media_crop_overrides');
        $override=$wpdb->get_row($wpdb->prepare("SELECT * FROM $cropTable WHERE identity_key=%s LIMIT 1",$key),ARRAY_A);
        return array(
            'master_key'=>$key,'keys'=>array($key),'rows'=>array($row),
            'override'=>$override?:null,'preview'=>$preview,'identity'=>$identity,
