        }echo '</div><script>(function(){function clamp(v){return Math.max(0,Math.min(100,v));}document.querySelectorAll("[data-rgcrop]").forEach(function(root){if(root.dataset.rgcropBound)return;root.dataset.rgcropBound="1";var form=root.querySelector("form");if(!form)return;function update(kind){var st=root.querySelector("[data-stage=\""+kind+"\"]"),img=st&&st.querySelector("img"),dot=st&&st.querySelector(".rgcrop-dot"),x=form.querySelector("[data-val=\""+kind+"-x\"]"),y=form.querySelector("[data-val=\""+kind+"-y\"]"),z=form.querySelector("[data-zoom=\""+kind+"\"]");if(!img||!x||!y)return;var xv=clamp(parseFloat(x.value)||50),yv=clamp(parseFloat(y.value)||50),raw=parseFloat(z&&z.value),zoom=Number.isFinite(raw)?Math.max(0,Math.min(2.5,raw)):1;img.style.objectPosition=xv+"% "+yv+"%";img.style.transformOrigin=xv+"% "+yv+"%";if(zoom>=0.999){img.style.objectFit="cover";img.style.transform=zoom>1.001?"scale("+zoom+")":"none";}else{var nw=img.naturalWidth||0,nh=img.naturalHeight||0,cw=st.clientWidth||0,ch=st.clientHeight||0;if(nw>0&&nh>0&&cw>0&&ch>0){var sr=nw/nh,br=cw/ch,cover=sr>br?sr/br:br/sr,scale=1+(cover-1)*zoom;img.style.objectFit="contain";img.style.transform="scale("+scale+")";}else{img.style.objectFit="contain";img.style.transform="none";}}if(dot){dot.style.left=xv+"%";dot.style.top=yv+"%";}}function bind(kind){var st=root.querySelector("[data-stage=\""+kind+"\"]"),x=form.querySelector("[data-val=\""+kind+"-x\"]"),y=form.querySelector("[data-val=\""+kind+"-y\"]"),z=form.querySelector("[data-zoom=\""+kind+"\"]");if(!st||!x||!y)return;function set(e){var r=st.getBoundingClientRect();x.value=clamp((e.clientX-r.left)/r.width*100).toFixed(2);y.value=clamp((e.clientY-r.top)/r.height*100).toFixed(2);update(kind);}st.addEventListener("pointerdown",function(e){st.setPointerCapture&&st.setPointerCapture(e.pointerId);set(e);});st.addEventListener("pointermove",function(e){if(e.buttons)set(e);});if(z)z.addEventListener("input",function(){update(kind);});var img=st.querySelector("img");if(img&&!img.complete)img.addEventListener("load",function(){update(kind);},{once:true});update(kind);}bind("card");bind("detail");});})();</script>';
