    private function pending_buedchen_submissions($limit=30) {
        global $wpdb;
        $sub=$this->table('place_override_submissions');
        $places=$this->table('places');
        return (array)$wpdb->get_results($wpdb->prepare(
            "SELECT s.*,p.name place_name,p.city,p.street,p.house_number
             FROM $sub s LEFT JOIN $places p ON p.id=s.place_id
             WHERE s.status='pending' AND s.submission_type<>'wurst_suggestion'
             ORDER BY s.created_at DESC LIMIT %d",
             max(1,min(100,(int)$limit))
        ),ARRAY_A);
    }

    public function admin_submission_review() {
        if(!current_user_can('manage_options')) wp_die('Keine Berechtigung.');
        check_admin_referer('rg_places_submission_review');
        global $wpdb;
        $id=absint($_POST['submission_id']??0);
        $decision=sanitize_key((string)($_POST['decision']??'reject'));
        $subtable=$this->table('place_override_submissions');
        $sub=$wpdb->get_row($wpdb->prepare("SELECT * FROM $subtable WHERE id=%d AND status='pending'",$id),ARRAY_A);
        if(!$sub) {
            wp_safe_redirect(add_query_arg(array('page'=>'ruhrpottguru-places'),admin_url('tools.php'))); exit;
        }

        if($decision==='approve') {
            $payload=json_decode((string)$sub['payload_json'],true);
            if(is_array($payload)) {
                $fields=(isset($payload['fields'])&&is_array($payload['fields']))
                    ? $payload['fields']
                    : (!empty($payload['field'])?array((string)$payload['field']=>$payload['value']??null):array());

                if($fields) {
                    $orow=$this->override_row((int)$sub['place_id']);
                    $odata=$this->decode_override_data($orow?:'');
                    $now=current_time('mysql',true);
                    $bool_fields=array('mixed_candy','coffee','sandwiches','seating','lottery','parcel_shop','tobacco','late_night');
                    $map=array('opening_hours'=>'opening_hours','website'=>'website','phone'=>'phone','instagram'=>'instagram','description'=>'description');

                    foreach($fields as $raw_field=>$value) {
                        $field=sanitize_key((string)$raw_field);
                        if(in_array($field,$bool_fields,true)) {
                            $odata['features'][$field]=(bool)$value;
                        } elseif($field==='closed') {
                            $odata['buedchen']['review_status']=$value?'rejected':($odata['buedchen']['review_status']??'auto');
                            $odata['buedchen']['review_note']=$value?'Community/Betreiber meldet geschlossen':'';
                        } elseif($field!=='note' && isset($map[$field])) {
                            $odata['fields'][$map[$field]]=array(
                                'value'=>(string)$value,
                                'source_type'=>$sub['submitter_type']==='operator'?'operator':'community',
                                'source_label'=>(string)$sub['source_label'],
                                'verified_at'=>$now,
                            );
                        }
                    }

                    $this->save_override_data((int)$sub['place_id'],$odata,
                        $sub['submitter_type']==='operator'?'operator':'community',
                        (string)$sub['source_label'],true);
                }
            }
            $status='approved';
        } else {
            $status='rejected';
        }

        $wpdb->update($subtable,array(
            'status'=>$status,
            'reviewed_at'=>current_time('mysql',true),
            'reviewed_by'=>get_current_user_id(),
        ),array('id'=>$id),array('%s','%s','%d'),array('%d'));

        wp_safe_redirect(add_query_arg(array('page'=>'ruhrpottguru-places','rg_submission_reviewed'=>'1'),admin_url('tools.php')));
        exit;
    }

    public function rest_buedchen_status() {
        return rest_ensure_response(array(
            'ok'=>true,
            'version'=>self::VERSION,
            'refreshStartedAt'=>(string)get_option('rg_places_buedchen_refresh_started_at',''),
            'inventory'=>$this->buedchen_admin_stats(),
            'municipalities'=>$this->buedchen_admin_municipality_rows(),
        ));
    }

    public function rest_buedchen(WP_REST_Request $request) {
        if ($this->runtime_mode() !== 'database') {
            return new WP_REST_Response(array('ok'=>false,'error'=>'places-db-not-ready'),503);
        }
        $data = $request->get_method() === 'GET' ? $request->get_params() : (array)$request->get_json_params();
        $lat = isset($data['lat']) ? (float)$data['lat'] : 0.0;
        $lng = isset($data['lng']) ? (float)$data['lng'] : 0.0;
        $radius = isset($data['radiusKm']) ? max(0.5,min(50.0,(float)$data['radiusKm'])) : 5.0;
        $limit = isset($data['limit']) ? max(1,min(200,(int)$data['limit'])) : 50;
        if (!$this->valid_coordinate($lat,$lng)) return new WP_REST_Response(array('ok'=>false,'error'=>'invalid-request'),400);

        global $wpdb;
        $places = $this->table('places');
        $lat_delta = $radius / 110.574;
        $cos = max(0.2, cos(deg2rad($lat)));
        $lng_delta = $radius / (111.320 * $cos);
        $distance = "(6371.0088 * 2 * ASIN(SQRT(POWER(SIN(RADIANS(p.lat - %f)/2),2) + COS(RADIANS(%f)) * COS(RADIANS(p.lat)) * POWER(SIN(RADIANS(p.lng - %f)/2),2))))";
        $distance_sql = $wpdb->prepare($distance,$lat,$lat,$lng);
        $rows = (array)$wpdb->get_results($wpdb->prepare(
            "SELECT p.*, $distance_sql AS distance_km
             FROM $places p
             LEFT JOIN {$this->table('place_overrides')} o ON o.place_id=p.id AND o.status='active'
             WHERE p.active=1
               AND p.lifecycle_status='active'
               AND p.primary_category='buedchen'
               AND (o.override_data IS NULL OR LOCATE('\"review_status\":\"rejected\"',o.override_data)=0)
               AND (
                    LOCATE('\"rg:buedchen_tier\":\"A\"',p.raw_tags)>0
                    OR LOCATE('\"rg:buedchen_tier\":\"B\"',p.raw_tags)>0
                    OR LOCATE('\"review_status\":\"verified\"',o.override_data)>0
               )
               AND p.lat BETWEEN %f AND %f
               AND p.lng BETWEEN %f AND %f
             HAVING distance_km<=%f
             ORDER BY CASE WHEN LOCATE('\"review_status\":\"verified\"',COALESCE(o.override_data,''))>0 THEN 0 ELSE 1 END ASC,
                      distance_km ASC,
                      CASE WHEN LOCATE('\"rg:buedchen_tier\":\"A\"',p.raw_tags)>0 THEN 0 ELSE 1 END ASC,
                      p.quality_score DESC,
                      p.id ASC
             LIMIT %d",
             $lat-$lat_delta,$lat+$lat_delta,$lng-$lng_delta,$lng+$lng_delta,$radius,$limit
        ), ARRAY_A);

        return rest_ensure_response(array(
            'ok'=>true,
            'source'=>'places-db',
            'requestedRadiusKm'=>$radius,
            'count'=>count($rows),
            'elements'=>$this->rows_to_elements($rows),
        ));
    }

    private function build_city_overpass_query($name, $admin_level) {
        // Compatibility fallback for older callers: one complete query.
        $queries=$this->build_city_overpass_queries($name,$admin_level);
        if (count($queries)===1) return $queries[0];
        $escaped = str_replace(array('\\','"'), array('\\\\','\\"'), $name);
        $bodies=array();
        foreach ($this->city_overpass_groups() as $group) {
            foreach ($group as $line) $bodies[]=$line;
        }
        return $this->compose_city_overpass_query($escaped,$admin_level,$bodies,45);
    }

    private function city_overpass_groups() {
        // Deliberately split the former giant union. Essen/Dortmund no longer
        // have to produce one very large Overpass response before any progress.
        return array(
            array(
                ' nwr["name"]["amenity"~"^(restaurant|cafe|fast_food|pub|bar|biergarten|food_court|ice_cream|theatre|cinema|arts_centre|community_centre|planetarium|library|events_venue|cultural_center|nightclub|concert_hall|music_venue|public_bath|swimming_pool|sauna)$"](area.searchArea);',
                ' nwr["name"]["craft"~"^(brewery|roastery)$"](area.searchArea);',
                ' nwr["name"]["microbrewery"="yes"](area.searchArea);',
                ' nwr["name"]["shop"~"^(coffee|tea)$"](area.searchArea);',
                ' nwr["name"]["takeaway"="only"](area.searchArea);',
                ' nwr["name"]["cuisine"](area.searchArea);'
            ),
            array(
                ' nwr["name"]["tourism"~"^(museum|gallery|artwork|attraction|viewpoint|zoo|theme_park)$"](area.searchArea);',
                ' nwr["name"]["historic"~"^(mine|industrial|castle|manor|ruins|fort|fortification|city_gate|archaeological_site|monument)$"](area.searchArea);',
                ' nwr["name"]["heritage"](area.searchArea);',
                ' nwr["name"]["man_made"~"^(headframe|spoil_heap|tower|water_tower|lighthouse|windmill|mineshaft|adit)$"](area.searchArea);',
                ' nwr["name"]["building"~"^(castle|museum|theatre)$"](area.searchArea);'
            ),
            array(
                ' nwr["name"]["leisure"~"^(sports_centre|sports_hall|swimming_pool|water_park|bowling_alley|skate_park|park|garden|nature_reserve|fitness_centre|ice_rink|miniature_golf|disc_golf_course|stadium|marina|escape_game|trampoline_park|amusement_park|animal_park|fitness_station)$"](area.searchArea);',
                ' nwr["name"]["sport"~"^(swimming|climbing|bouldering|climbing_adventure|tennis|padel|golf|fitness|skateboard|skateboarding|bmx|ice_skating|skiing|snowboarding|canoeing|kayak|sailing|rowing|wakeboarding|water_ski|scuba_diving|cycling|equestrian|karting|billiards|bowling|soccer|basketball|table_tennis|beachvolleyball|beach_volleyball|volleyball|handball|korfball|futsal|model_aerodrome|shooting|athletics)$"](area.searchArea);',
                ' nwr["name"]["shop"~"^(kiosk|convenience)$"](area.searchArea);'
            ),
            // Activities V2 source coverage: only highly specific nameless public-use facilities.
            // Generic soccer/tennis/fitness infrastructure stays name-gated to avoid catalogue flooding.
            array(
                ' nwr[!"name"]["sport"~"^(basketball|table_tennis|beachvolleyball|beach_volleyball|skateboard|skateboarding|bmx)$"](area.searchArea);',
                ' nwr[!"name"]["leisure"~"^(skate_park|fitness_station)$"](area.searchArea);'
            )
        );
    }

    private function compose_city_overpass_query($escaped,$admin_level,$body_lines,$timeout=30) {
        // 1.10.150: resolve municipality names only inside North Rhine-Westphalia.
        // The old global name lookup could select an unrelated same-named admin area
        // outside NRW (observed live for Kamen), causing foreign POIs to be refreshed
        // as healthy RuhrpottGuru places. Relation 62761 is the NRW state boundary;
        // map_to_area follows the documented Overpass relation-to-area contract.
        $lines=array(
            '[out:json][timeout:'.max(15,(int)$timeout).'];',
            'rel(62761);',
            'map_to_area->.rpgNwArea;',
            'rel["boundary"="administrative"]["admin_level"="' . (int)$admin_level . '"]["name"="' . $escaped . '"](area.rpgNwArea);',
            'map_to_area->.searchArea;',
            '('
        );
        foreach ($body_lines as $line) $lines[]=$line;
        $lines[]=');';
        $lines[]='out center meta;';
        return implode("\n",$lines);
    }

    private function build_city_overpass_queries($name,$admin_level) {
        $escaped = str_replace(array('\\','"'), array('\\\\','\\"'), $name);
        $queries=array();
        foreach ($this->city_overpass_groups() as $group) {
            $queries[]=$this->compose_city_overpass_query($escaped,$admin_level,$group,30);
        }
        return $queries;
    }

    private function import_elements($elements, $municipality) {
        $stats = array('received'=>count($elements),'accepted'=>0,'created'=>0,'updated'=>0,'rejected'=>0);
        foreach ($elements as $element) {
            $result = $this->upsert_element($element, $municipality);
            if ($result === 'created') { $stats['accepted']++; $stats['created']++; }
            elseif ($result === 'updated') { $stats['accepted']++; $stats['updated']++; }
            else { $stats['rejected']++; }
        }
        return $stats;
    }

    private function derived_activity_name_from_tags($tags) {
        if (!is_array($tags)) return '';
        $leisure = strtolower(trim((string)($tags['leisure'] ?? '')));
        $sports = $this->activity_v2_values($tags['sport'] ?? '');
        if ($leisure === 'skate_park') return 'Skatepark';
        if ($leisure === 'fitness_station') return 'Outdoor-Fitnessanlage';
        if (in_array('basketball',$sports,true)) return 'Basketballplatz';
        if (in_array('table_tennis',$sports,true)) return 'Tischtennisanlage';
        if (in_array('beachvolleyball',$sports,true) || in_array('beach_volleyball',$sports,true)) return 'Beachvolleyballfeld';
        if (in_array('skateboard',$sports,true) || in_array('skateboarding',$sports,true)) return 'Skateanlage';
        if (in_array('bmx',$sports,true)) return 'BMX-Anlage';
        return '';
    }

    private function import_coordinate_in_nrw_v101150($lat,$lng) {
        // Deliberately padded beyond the official NRW bbox. This is defense in depth,
        // not a municipal boundary test; all 53 Ruhr municipalities are comfortably
        // inside it, while accidental foreign same-name areas are rejected.
        $lat=(float)$lat;$lng=(float)$lng;
        return $lat>=50.20 && $lat<=52.70 && $lng>=5.70 && $lng<=9.70;
    }

    private function upsert_element($element, $municipality) {
        global $wpdb;
        if (!is_array($element)) return 'rejected';
        $tags = isset($element['tags']) && is_array($element['tags']) ? $element['tags'] : array();
        $name = trim((string) (isset($tags['name']) ? $tags['name'] : (isset($tags['brand']) ? $tags['brand'] : '')));
        if ($name === '') {
            $name = $this->derived_activity_name_from_tags($tags);
            if ($name === '') return 'rejected';
            $tags['rg:name_source'] = 'derived';
            $tags['rg:derived_name'] = 'yes';
        }
        $lat = isset($element['lat']) ? (float)$element['lat'] : (isset($element['center']['lat']) ? (float)$element['center']['lat'] : 0.0);
        $lng = isset($element['lon']) ? (float)$element['lon'] : (isset($element['center']['lon']) ? (float)$element['center']['lon'] : 0.0);
        if (!$this->valid_coordinate($lat, $lng)) return 'rejected';
        if (!$this->import_coordinate_in_nrw_v101150($lat,$lng)) return 'rejected';
        // Preserve the existing reversible Food identity knowledge in the canonical DB path.
        // These are narrow, user-confirmed Wesel records; generic fuzzy exclusions are forbidden.
        $norm_for_local = $this->normalize_text($name);
        if ($municipality['slug'] === 'wesel' && in_array($norm_for_local, array('san marino','san marino ii','berliner stube','berliner stuben'), true)) {
            return 'rejected';
        }
        if ($municipality['slug'] === 'wesel' && in_array($norm_for_local, array('mezzomar','mezzomar wesel'), true)) {
            $distance_to_oliv = $this->distance_m($lat, $lng, 51.656753, 6.617025);
            if ($distance_to_oliv <= 120) {
                $tags['old_name'] = isset($tags['old_name']) ? $tags['old_name'] : $name;
                $tags['name'] = 'Café-Bistro Oliv';
                $tags['rg:correction'] = 'mezzomar-to-oliv';
                $name = 'Café-Bistro Oliv';
            }
        }
        $classification = $this->classify_tags($tags, $name);
        if (!$classification) return 'rejected';

        $osm_type_full = isset($element['type']) ? strtolower((string)$element['type']) : 'node';
        $osm_type = $osm_type_full === 'way' ? 'w' : ($osm_type_full === 'relation' ? 'r' : 'n');
        $osm_id = isset($element['id']) ? abs((int)$element['id']) : 0;
        if ($osm_id <= 0) return 'rejected';
        $source_uid = 'osm:' . $osm_type . ':' . $osm_id;
        $normal = $this->normalize_text($name);
        $street = trim((string)($tags['addr:street'] ?? ''));
        $house = trim((string)($tags['addr:housenumber'] ?? ''));
        $postcode = trim((string)($tags['addr:postcode'] ?? ''));
        $city = trim((string)($tags['addr:city'] ?? $municipality['name']));
        $district = trim((string)($tags['addr:suburb'] ?? ($tags['addr:district'] ?? ($tags['neighbourhood'] ?? ''))));
        $identity = $normal . '|';
        if ($street !== '' && $house !== '') {
            $identity .= $this->normalize_text($street) . '|' . $this->normalize_text($house) . '|' . $this->normalize_text($city);
        } else {
            $identity .= number_format($lat, 4, '.', '') . '|' . number_format($lng, 4, '.', '');
        }
        $canonical_key = sha1($identity);
        $inactive = $this->is_inactive_tags($tags);
        $quality = $this->quality_score($tags, $street, $house, $city);
        $now = current_time('mysql', true);
        $timestamp = isset($element['timestamp']) ? gmdate('Y-m-d H:i:s', strtotime($element['timestamp'])) : null;
        $version = isset($element['version']) ? max(0, (int)$element['version']) : 0;

        $sources = $this->table('place_sources');
        $places = $this->table('places');
        $existing_source = $wpdb->get_row($wpdb->prepare("SELECT * FROM $sources WHERE source_uid=%s", $source_uid), ARRAY_A);
        $place_id = $existing_source ? (int)$existing_source['place_id'] : 0;
        $created = false;
        if (!$place_id) {
            $candidate = $wpdb->get_row($wpdb->prepare(
                "SELECT id,quality_score FROM $places WHERE canonical_key=%s AND municipality_slug=%s ORDER BY quality_score DESC LIMIT 1",
                $canonical_key, $municipality['slug']
            ), ARRAY_A);
            if ($candidate) $place_id = (int)$candidate['id'];
        }

        if ($classification['category'] === 'buedchen') {
            $bp = $this->buedchen_profile($tags, $name);
            if ($bp) {
                $tags['rg:buedchen_score'] = (string)$bp['score'];
                $tags['rg:buedchen_tier'] = (string)$bp['tier'];
                $tags['rg:buedchen_signals'] = implode('|', $bp['signals']);
            }
        }
        $raw_json = wp_json_encode($tags, JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES);
        // Source rows keep the coordinates of each concrete OSM representation.
        // The public place raw_tags remain a plain tag object for backwards
        // compatibility; only place_sources.raw_payload uses this private envelope.
        $source_raw_json = wp_json_encode(array(
            'schema'=>'rpg-osm-source-v2','tags'=>$tags,'lat'=>$lat,'lng'=>$lng
        ), JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES);
        $provenance = wp_json_encode(array(
            'name'=>'osm','coordinates'=>'osm','address'=>'osm','website'=>isset($tags['website'])||isset($tags['contact:website'])?'osm':'unknown',
            'opening_hours'=>isset($tags['opening_hours'])?'osm':'unknown','normalized_at'=>$now
        ));
        $website = $this->first_url(array($tags['website'] ?? '', $tags['contact:website'] ?? '', $tags['url'] ?? '', $tags['contact:url'] ?? ''));
        $phone = trim((string)($tags['phone'] ?? ($tags['contact:phone'] ?? '')));
        $opening = trim((string)($tags['opening_hours'] ?? ''));
        $wikidata = trim((string)($tags['wikidata'] ?? ''));
        $wikipedia = trim((string)($tags['wikipedia'] ?? ''));

        if (!$place_id) {
            $wpdb->insert($places, array(
                'canonical_key'=>$canonical_key,'name'=>$name,'normalized_name'=>$normal,'lat'=>$lat,'lng'=>$lng,
                'municipality_slug'=>$municipality['slug'],'city'=>$city,'district'=>$district,'street'=>$street,'house_number'=>$house,'postcode'=>$postcode,
                'phone'=>$phone,'website'=>$website,'opening_hours'=>$opening,'wikidata'=>$wikidata,'wikipedia'=>$wikipedia,
                'primary_category'=>$classification['category'],'primary_subcategory'=>$classification['subcategory'],
                'lifecycle_status'=>$inactive?'source-inactive':'active','active'=>$inactive?0:1,'quality_score'=>$quality,
                'primary_osm_type'=>$osm_type,'primary_osm_id'=>$osm_id,'raw_tags'=>$raw_json,'field_provenance'=>$provenance,
                'first_seen_at'=>$now,'last_seen_at'=>$now,'last_synced_at'=>$now,'updated_at'=>$now,
            ), array('%s','%s','%s','%f','%f','%s','%s','%s','%s','%s','%s','%s','%s','%s','%s','%s','%s','%s','%s','%d','%f','%s','%d','%s','%s','%s','%s','%s','%s'));
            $place_id = (int)$wpdb->insert_id;
            if (!$place_id) return 'rejected';
            $created = true;
        } else {
            $current = $wpdb->get_row($wpdb->prepare("SELECT * FROM $places WHERE id=%d", $place_id), ARRAY_A);
            // Freshness beats richness for the same canonical OSM object. Previously,
            // removing a website/tag or correcting a category could lower quality_score
            // and leave the richer *old* raw_tags/core fields permanently frozen.
            // Lifecycle and classifier ownership follow the source that owns the
            // canonical core. Lower-quality duplicate sources remain evidence only.
            $should_replace_core = $this->should_replace_osm_core_v1080($current,$osm_type,$osm_id,$quality,$inactive);
            $update = array('last_seen_at'=>$now,'last_synced_at'=>$now,'updated_at'=>$now);
            if ($should_replace_core) {
                $update = array_merge($update, array(
                    'canonical_key'=>$canonical_key,'name'=>$name,'normalized_name'=>$normal,'lat'=>$lat,'lng'=>$lng,
                    'municipality_slug'=>$municipality['slug'],'city'=>$city,'district'=>$district,'street'=>$street,'house_number'=>$house,'postcode'=>$postcode,
                    'phone'=>$phone,'website'=>$website,'opening_hours'=>$opening,'wikidata'=>$wikidata,'wikipedia'=>$wikipedia,
                    'primary_category'=>$classification['category'],'primary_subcategory'=>$classification['subcategory'],
                    'lifecycle_status'=>$inactive?'source-inactive':'active','active'=>$inactive?0:1,'quality_score'=>$quality,
                    'primary_osm_type'=>$osm_type,'primary_osm_id'=>$osm_id,'raw_tags'=>$raw_json,'field_provenance'=>$provenance,
                ));
            }
            $wpdb->update($places, $update, array('id'=>$place_id));
        }

        $wpdb->query($wpdb->prepare(
            "INSERT INTO $sources (place_id,source_type,source_uid,osm_type,osm_id,osm_version,osm_timestamp,raw_payload,first_seen_at,last_seen_at)
             VALUES (%d,'osm',%s,%s,%d,%d,%s,%s,%s,%s)
             ON DUPLICATE KEY UPDATE place_id=VALUES(place_id),osm_version=VALUES(osm_version),osm_timestamp=VALUES(osm_timestamp),raw_payload=VALUES(raw_payload),last_seen_at=VALUES(last_seen_at)",
            $place_id, $source_uid, $osm_type, $osm_id, $version, $timestamp, $source_raw_json, $now, $now
        ));

        $cats = $this->table('place_categories');
        // Keep the public classifier in lock-step with the canonical core. A
        // lower-quality duplicate source is stored in place_sources but does not
        // get to move the public category away from the primary source.
        if ($created || !empty($should_replace_core)) {
            $wpdb->query($wpdb->prepare(
                "DELETE FROM $cats WHERE place_id=%d AND source LIKE 'classifier-%%' AND category<>%s",
                $place_id, $classification['category']
            ));
            $wpdb->query($wpdb->prepare(
                "INSERT INTO $cats (place_id,category,subcategory,weight,source,updated_at)
                 VALUES (%d,%s,%s,%f,'classifier-v1.10.80',%s)
                 ON DUPLICATE KEY UPDATE subcategory=VALUES(subcategory),weight=VALUES(weight),source=VALUES(source),updated_at=VALUES(updated_at)",
                $place_id, $classification['category'], $classification['subcategory'], $classification['weight'], $now
            ));
        }

        // Link/schedule evidence belongs to the imported source. Existing OSM-derived
        // link cleanup is safe only when this source owns the core; otherwise a
        // lower-quality duplicate could retire the primary source's website/hours.
        if ($created || !empty($should_replace_core)) $this->ingest_osm_links_and_schedule($place_id, $tags, $now);
        $this->sync_wurst_candidate_for_place($place_id, $tags, $name);
        return $created ? 'created' : 'updated';
    }

    private function normalize_text($text) {
        $text = remove_accents(strtolower(trim((string)$text)));
        $text = str_replace('ß', 'ss', $text);
        return trim(preg_replace('/[^a-z0-9]+/i', ' ', $text));
    }
    private function is_inactive_tags($tags) {
        foreach (array('disused','abandoned','demolished','razed','removed','closed') as $key) {
            $v = strtolower(trim((string)($tags[$key] ?? '')));
            if (in_array($v, array('yes','true','1'), true)) return true;
        }
        $features = array('amenity','leisure','sport','tourism','historic','building','shop','craft','man_made');
        foreach (array('disused','abandoned','demolished','razed','removed') as $prefix) {
            foreach ($features as $feature) {
                if (!empty($tags[$prefix . ':' . $feature])) return true;
            }
        }
        $opening = strtolower(trim((string)($tags['opening_hours'] ?? '')));
        if (in_array($opening, array('closed','off'), true)) return true;
        return false;
    }


    private function distance_m($lat1, $lng1, $lat2, $lng2) {
        $earth = 6371000.0;
        $dlat = deg2rad($lat2 - $lat1);
        $dlng = deg2rad($lng2 - $lng1);
        $a = sin($dlat/2)*sin($dlat/2) + cos(deg2rad($lat1))*cos(deg2rad($lat2))*sin($dlng/2)*sin($dlng/2);
        return $earth * 2 * atan2(sqrt($a), sqrt(max(0.0, 1.0-$a)));
    }

    private function classify_tags($tags, $name) {
        $amenity = strtolower((string)($tags['amenity'] ?? ''));
        $tourism = strtolower((string)($tags['tourism'] ?? ''));
        $historic = strtolower((string)($tags['historic'] ?? ''));
        $leisure = strtolower((string)($tags['leisure'] ?? ''));
        $sport = strtolower((string)($tags['sport'] ?? ''));
        $craft = strtolower((string)($tags['craft'] ?? ''));
        $shop = strtolower((string)($tags['shop'] ?? ''));
        $takeaway = strtolower((string)($tags['takeaway'] ?? ''));
        $microbrewery = strtolower((string)($tags['microbrewery'] ?? ''));
        $man = strtolower((string)($tags['man_made'] ?? ''));
        $heritage = trim((string)($tags['heritage'] ?? ''));
        $building = strtolower((string)($tags['building'] ?? ''));
        $cuisine = strtolower((string)($tags['cuisine'] ?? ''));
        $lower = $this->normalize_text($name);

        $buedchen = $this->buedchen_profile($tags, $name);
        if ($buedchen) {
            return array(
                'category'=>'buedchen',
                'subcategory'=>'Büdchen-Radar · Tier '.$buedchen['tier'],
                'weight'=>max(0.01,min(1.0,$buedchen['score']/100))
            );
        }

        // Cuisine is useful supporting metadata, but on its own it must not override an
        // explicitly non-gastronomic primary OSM identity. Strong gastro evidence always wins,
        // so genuine hybrid venues remain eligible.
        $strong_food = in_array($amenity, array('restaurant','cafe','fast_food','pub','bar','biergarten','food_court','ice_cream'), true)
            || in_array($craft, array('brewery','roastery'), true)
            || in_array($shop, array('coffee','tea'), true)
            || $takeaway === 'only'
            || $microbrewery === 'yes';
        $cuisine_blocked_shops = array('beauty','bookmaker','copyshop','hairdresser','hairdresser_supply','pet','clothes','florist','interior_decoration','newsagent','supermarket','vacant');
        $cuisine_blocked_amenities = array('social_facility');
        $cuisine_only_allowed = $cuisine !== ''
            && !in_array($shop, $cuisine_blocked_shops, true)
            && !in_array($amenity, $cuisine_blocked_amenities, true);
        $food = $strong_food || $cuisine_only_allowed;
        if ($food) {
            $sub = 'Gastronomie';
            if (in_array($amenity, array('cafe','ice_cream'), true) || $craft === 'roastery' || in_array($shop, array('coffee','tea'), true)) $sub = 'Café & Eis';
            elseif (in_array($amenity, array('bar','pub','biergarten'), true) || $craft === 'brewery' || $microbrewery === 'yes') $sub = 'Bar & Biergarten';
            elseif (in_array($amenity, array('fast_food','food_court'), true) || $takeaway === 'only') $sub = 'Imbiss & Streetfood';
            return array('category'=>'food','subcategory'=>$sub,'weight'=>1.0);
        }

        $sport_values = $this->activity_v2_values($sport);
        $has_activity_sport = function($needle) use ($sport_values) { return in_array($needle,$sport_values,true); };
        $activity_amenity = in_array($amenity, array('public_bath','swimming_pool','sauna'), true);
        $activity_leisure = in_array($leisure, array('sports_centre','sports_hall','swimming_pool','water_park','bowling_alley','skate_park','fitness_centre','fitness_station','ice_rink','miniature_golf','disc_golf_course','stadium','marina','escape_game','trampoline_park'), true);
        $activity_sport_types = array('swimming','climbing','bouldering','climbing_adventure','tennis','padel','golf','fitness','skateboard','skateboarding','bmx','ice_skating','skiing','snowboarding','canoeing','kayak','sailing','rowing','wakeboarding','water_ski','scuba_diving','cycling','equestrian','karting','billiards','bowling','soccer','basketball','table_tennis','beachvolleyball','beach_volleyball','volleyball','handball','korfball','futsal','model_aerodrome','shooting','athletics');
        $activity_sport = count(array_intersect($sport_values,$activity_sport_types)) > 0;
        if ($activity_amenity || $activity_leisure || $activity_sport) {
            $sub = 'Freizeit & Action';
            if ($activity_amenity || in_array($leisure, array('swimming_pool','water_park'), true) || $has_activity_sport('swimming')) $sub = 'Schwimmbäder & Thermen';
            elseif ($has_activity_sport('climbing') || $has_activity_sport('bouldering') || $has_activity_sport('climbing_adventure') || strpos($lower,'kletter') !== false || strpos($lower,'boulder') !== false) $sub = 'Klettern & Bouldern';
            elseif ($has_activity_sport('skateboard') || $has_activity_sport('skateboarding') || $has_activity_sport('bmx') || $has_activity_sport('karting') || $has_activity_sport('shooting') || $leisure === 'skate_park') $sub = 'Action & Adrenalin';
            return array('category'=>'activities','subcategory'=>$sub,'weight'=>1.0);
        }

        $culture = in_array($amenity, array('theatre','cinema','arts_centre','community_centre','planetarium','library','events_venue','cultural_center','nightclub','concert_hall','music_venue'), true)
            || in_array($tourism, array('museum','gallery','artwork'), true)
            || in_array($building, array('museum','theatre'), true);
        if ($culture) {
            $sub = 'Kulturzentren & Szene';
            if (in_array($amenity, array('theatre','concert_hall','music_venue'), true) || $building === 'theatre') $sub = 'Theater & Bühne';
            elseif (in_array($tourism, array('museum','gallery'), true) || $building === 'museum') $sub = 'Museum & Galerie';
            return array('category'=>'culture','subcategory'=>$sub,'weight'=>1.0);
        }

        $highlight = in_array($tourism, array('attraction','viewpoint','zoo','theme_park'), true)
            || in_array($historic, array('mine','industrial','castle','manor','ruins','fort','city_gate','archaeological_site','monument','memorial'), true)
            || in_array($man, array('headframe','spoil_heap','tower','water_tower','lighthouse','windmill','mineshaft','adit'), true)
            || $heritage !== ''
            || in_array($building, array('castle'), true)
            || in_array($leisure, array('park','garden','nature_reserve','animal_park','amusement_park'), true);
        if ($highlight) {
            $sub = 'Highlights & Ausflugsziele';
            if (in_array($tourism, array('zoo','theme_park'), true) || in_array($leisure, array('animal_park','amusement_park'), true)) $sub = 'Zoos & Freizeitparks';
            elseif (in_array($historic, array('mine','industrial'), true) || in_array($man, array('headframe','mineshaft','adit'), true)) $sub = 'Industriekultur & Zechen';
            elseif (in_array($historic, array('castle','manor','ruins','fort','fortification','city_gate'), true) || $building === 'castle') $sub = 'Schloss & Burg';
            elseif ($tourism === 'viewpoint' || in_array($man, array('spoil_heap','tower','water_tower','lighthouse','windmill','headframe'), true)) $sub = 'Halden & Landmarken';
            elseif (in_array($leisure, array('park','garden','nature_reserve'), true)) $sub = 'Park & Natur';
            return array('category'=>'highlights','subcategory'=>$sub,'weight'=>1.0);
        }
        return null;
    }

    /**
     * Places 1.10.80: canonical OSM core ownership decision.
     *
     * Same-source freshness always wins. A different active source may take over
     * when it is at least as complete, and any current active representation may
     * recover a source_missing/source-inactive place. An inactive secondary source
     * can never deactivate a healthy active primary place.
     */
    private function should_replace_osm_core_v1080($current,$osm_type,$osm_id,$quality,$inactive) {
        if (!is_array($current) || !$current) return true;
        $same = (string)($current['primary_osm_type']??'') === (string)$osm_type
            && (int)($current['primary_osm_id']??0) === (int)$osm_id;
        if ($same) return true;
        $recovery = !$inactive && in_array((string)($current['lifecycle_status']??''), array('source_missing','source-inactive'), true);
        if ($recovery) return true;
        if ($inactive) return false;
        return (float)$quality >= (float)($current['quality_score']??0);
    }

    private function quality_score($tags, $street, $house, $city) {
        $score = 0.45;
        if ($street !== '') $score += 0.08;
        if ($house !== '') $score += 0.05;
        if ($city !== '') $score += 0.04;
        if (!empty($tags['website']) || !empty($tags['contact:website'])) $score += 0.09;
        if (!empty($tags['opening_hours'])) $score += 0.09;
        if (!empty($tags['phone']) || !empty($tags['contact:phone'])) $score += 0.04;
        if (!empty($tags['wikidata'])) $score += 0.07;
        if (!empty($tags['image']) || !empty($tags['wikimedia_commons'])) $score += 0.05;
        if (!empty($tags['wheelchair'])) $score += 0.02;
        return min(1.0, $score);
    }

    private function first_url($values) {
        foreach ($values as $value) {
            $url = esc_url_raw(trim((string)$value));
            if ($url && preg_match('#^https?://#i', $url)) return $url;
        }
        return '';
    }

    private function ingest_osm_links_and_schedule($place_id, $tags, $now) {
        $website = $this->first_url(array($tags['website'] ?? '', $tags['contact:website'] ?? '', $tags['url'] ?? '', $tags['contact:url'] ?? ''));
        $menu = $this->first_url(array($tags['menu'] ?? '', $tags['menu:url'] ?? '', $tags['website:menu'] ?? '', $tags['contact:menu'] ?? ''));
        $reservation = $this->first_url(array($tags['reservation:website'] ?? '', $tags['reservation:url'] ?? '', $tags['website:reservation'] ?? '', $tags['booking:website'] ?? '', $tags['contact:reservation'] ?? ''));
        $this->sync_osm_link($place_id, 'website', $website, 0.85, $now);
        $this->sync_osm_link($place_id, 'menu', $menu, 0.82, $now);
        $this->sync_osm_link($place_id, 'reservation', $reservation, 0.82, $now);

        $opening = trim((string)($tags['opening_hours'] ?? ''));
        global $wpdb;
        $table = $this->table('place_schedules');
        if ($opening !== '') {
            $wpdb->query($wpdb->prepare(
                "INSERT INTO $table (place_id,schedule_type,raw_value,source,confidence,verified_at,last_seen_at,locked)
                 VALUES (%d,'general',%s,'osm',0.8500,%s,%s,0)
                 ON DUPLICATE KEY UPDATE raw_value=IF(locked=1,raw_value,IF(VALUES(confidence)>=confidence,VALUES(raw_value),raw_value)),source=IF(locked=1,source,IF(VALUES(confidence)>=confidence,VALUES(source),source)),confidence=IF(locked=1,confidence,GREATEST(confidence,VALUES(confidence))),last_seen_at=VALUES(last_seen_at)",
                $place_id, $opening, $now, $now
            ));
        } else {
            // Removal from OSM invalidates only an unlocked OSM schedule; an official or
            // editorial schedule is independent and must survive.
            $wpdb->query($wpdb->prepare(
                "DELETE FROM $table WHERE place_id=%d AND schedule_type='general' AND source='osm' AND locked=0",
                $place_id
            ));
        }
    }

    private function sync_osm_link($place_id, $type, $url, $confidence, $now) {
        global $wpdb;
        $table = $this->table('place_links');
        if ($url) {
            $this->upsert_link($place_id, $type, $url, 'osm', $confidence, $now, false);
            return;
        }
        // If OSM removed a URL, only retire the OSM-derived value. Official/editorial
        // links of the same type remain active.
        $wpdb->query($wpdb->prepare(
            "UPDATE $table SET status='inactive',last_seen_at=%s WHERE place_id=%d AND link_type=%s AND source='osm' AND locked=0",
            $now, $place_id, $type
        ));
    }

    private function upsert_link($place_id, $type, $url, $source, $confidence, $now, $locked = false) {
        global $wpdb;
        $table = $this->table('place_links');
        $wpdb->query($wpdb->prepare(
            "INSERT INTO $table (place_id,link_type,url,source,confidence,status,verified_at,last_seen_at,locked)
             VALUES (%d,%s,%s,%s,%f,'active',%s,%s,%d)
             ON DUPLICATE KEY UPDATE
               url=IF(locked=1,url,IF(VALUES(confidence)>=confidence,VALUES(url),url)),
               source=IF(locked=1,source,IF(VALUES(confidence)>=confidence,VALUES(source),source)),
               confidence=IF(locked=1,confidence,GREATEST(confidence,VALUES(confidence))),
               status='active',verified_at=IF(VALUES(confidence)>=confidence,VALUES(verified_at),verified_at),last_seen_at=VALUES(last_seen_at)",
            $place_id, $type, $url, $source, $confidence, $now, $now, $locked?1:0
        ));
    }

    private function maybe_finalize_catalog() {
        global $wpdb;
        $muni = $this->table('places_municipalities');
        $places = $this->table('places');
        $cats = $this->table('place_categories');
        $completed = (int)$wpdb->get_var("SELECT COUNT(*) FROM $muni WHERE status='complete'");
        if ($completed < 53) {
            update_option(self::OPTION_STATUS, 'bootstrap_running', false);
            return false;
        }
        $total = (int)$wpdb->get_var("SELECT COUNT(*) FROM $places WHERE active=1");
        $counts = array();
        foreach (array('food','highlights','culture','activities') as $cat) {
            $counts[$cat] = (int)$wpdb->get_var($wpdb->prepare("SELECT COUNT(*) FROM $cats c INNER JOIN $places p ON p.id=c.place_id WHERE c.category=%s AND p.active=1", $cat));
        }
        $wesel_count = count($this->nearby_rows('food', 51.6572, 6.6186, 1.0, 200, 'all'));
        $valid = $total >= 10000 && $counts['food'] >= 3000 && $counts['highlights'] >= 300 && $counts['culture'] >= 300 && $counts['activities'] >= 300 && $wesel_count >= 50;
        if (!$valid) {
            update_option(self::OPTION_STATUS, 'validation_failed', false);
            update_option('rg_places_validation_report', array('total'=>$total,'counts'=>$counts,'weselFood1km'=>$wesel_count,'checkedAt'=>current_time('mysql', true)), false);
            return false;
        }
        $version = 'catalog-' . gmdate('Ymd-His') . '-' . substr(md5($total . '|' . implode('|',$counts)),0,8);
        update_option(self::OPTION_CATALOG_VERSION, $version, false);
        update_option(self::OPTION_STATUS, 'ready', false);
        if (!wp_next_scheduled('rg_places_generate_export')) wp_schedule_single_event(time()+60, 'rg_places_generate_export');
        update_option('rg_places_validation_report', array('total'=>$total,'counts'=>$counts,'weselFood1km'=>$wesel_count,'checkedAt'=>current_time('mysql', true),'pass'=>true), false);
        return true;
    }

    public function cron_sync_tick() {
        $this->event_cache_maintenance_tick();
        $this->process_wurst_backfill_batch(250);
        $ready = get_option(self::OPTION_STATUS) === 'ready';

        // Activities 1.10.90: the explicit 53-city coverage worker has exclusive
        // ownership of municipality/Overpass refreshes while queued or running.
        // Do not claim a second city here. Any regular sync that was already in
        // flight before the wave started is allowed to finish; the coverage worker
        // already waits for that active municipality before claiming its next one.
        if($this->activity_source_coverage_owns_refresh_lane_v1090()) {
            if($ready) $this->process_wurst_website_batch(1);
            return;
        }

        $municipality = $this->claim_next_municipality($ready);
        if (!$municipality) {
            $this->maybe_finalize_catalog();
            if($ready) $this->process_wurst_website_batch(1);
            return;
        }
        $this->server_sync_municipality($municipality, $ready ? 'refresh' : 'bootstrap');
        if ($ready) {
            $this->enrich_recent_food_batch(3);
            $this->process_wurst_website_batch(1);
        }
    }

    private function server_sync_municipality($municipality, $run_type) {
        global $wpdb;
        $runs = $this->table('places_sync_runs');
        $start = current_time('mysql', true);
        $wpdb->insert($runs, array(
            'municipality_slug'=>$municipality['slug'],'run_type'=>$run_type,'transport'=>'server-overpass','status'=>'running','started_at'=>$start
        ));
        $run_id = (int)$wpdb->insert_id;
        $queries = $this->build_city_overpass_queries($municipality['name'], (int)$municipality['admin_level']);
        $providers = array(
            'https://overpass.private.coffee/api/interpreter',
            'https://maps.mail.ru/osm/tools/overpass/api/interpreter',
            'https://overpass-api.de/api/interpreter',
        );
        $last_error = 'No provider attempted';
        $merged=array();
        $all_parts_ok=true;
        foreach ($queries as $part_index=>$query) {
            $part_payload=null;
            foreach ($providers as $provider) {
                $response = wp_remote_post($provider, array(
                    'timeout'=>22,'redirection'=>2,
                    'headers'=>array('Content-Type'=>'application/x-www-form-urlencoded; charset=UTF-8','User-Agent'=>'RuhrpottGuru-Places/1.2.6 (+https://www.ruhrpottguru.de/)'),
                    'body'=>array('data'=>$query),
                ));
                if (is_wp_error($response)) {
                    $last_error = 'Teil '.($part_index+1).': '.$response->get_error_message();
                    continue;
                }
                $code = (int) wp_remote_retrieve_response_code($response);
                $payload = json_decode(wp_remote_retrieve_body($response), true);
                if ($code < 200 || $code >= 300 || !is_array($payload) || !isset($payload['elements']) || !is_array($payload['elements']) || !empty($payload['remark'])) {
                    $last_error = 'Teil '.($part_index+1).' HTTP ' . $code . (isset($payload['remark']) ? ': ' . $payload['remark'] : ' invalid response');
                    continue;
                }
                $part_payload=$payload['elements'];
                break;
            }
            if (!is_array($part_payload)) {
                $all_parts_ok=false;
                break;
            }
            foreach ($part_payload as $element) {
                $type=(string)($element['type']??'');
                $id=(string)($element['id']??'');
                if ($type===''||$id==='') continue;
                $merged[$type.':'.$id]=$element;
            }
        }
        if ($all_parts_ok) {
            $elements=array_values($merged);
            $stats = $this->import_elements($elements, $municipality);
            if (count($elements) >= 5 && $stats['accepted'] >= 3) {
                $table = $this->table('places_municipalities');
                $now = current_time('mysql', true);
                if ($run_type === 'refresh') {
                    $this->reconcile_stale_primary_sources_after_snapshot_v1080($municipality['slug'], $start);
                    $this->mark_missing_after_snapshot($municipality['slug'], $start);
                }
                $wpdb->update($table, array(
                    'status'=>'complete','raw_count'=>count($elements),'imported_count'=>$stats['accepted'],'last_error'=>null,
                    'locked_until'=>null,'sync_started_at'=>null,'last_synced_at'=>$now,'updated_at'=>$now
                ), array('slug'=>$municipality['slug']));
                if ($run_id) $wpdb->update($runs, array(
                    'status'=>'success','raw_count'=>count($elements),'imported_count'=>$stats['accepted'],
                    'message'=>'3-part Overpass sync','finished_at'=>$now
                ), array('id'=>$run_id));
                $this->maybe_finalize_catalog();
                if (get_option(self::OPTION_STATUS) === 'ready') $this->maybe_refresh_osm_export();
                return true;
            }
            $last_error='Suspiciously small merged server import';
        }
        $preserve = ($run_type === 'refresh');
        $this->mark_municipality_error($municipality['slug'], $last_error, $preserve);
        if ($run_id) $wpdb->update($runs, array('status'=>'failed','message'=>$last_error,'finished_at'=>current_time('mysql', true)), array('id'=>$run_id));
        return false;
    }

    private function enrich_recent_food_batch($limit = 3) {
        if (!function_exists('ruhrpott_guru_food_info_enrichment')) return;
        global $wpdb;
        $places = $this->table('places');
        $rows = $wpdb->get_results($wpdb->prepare(
            "SELECT * FROM $places WHERE active=1 AND primary_category='food' AND (last_enriched_at IS NULL OR last_enriched_at < DATE_SUB(UTC_TIMESTAMP(),INTERVAL 30 DAY)) ORDER BY quality_score DESC,last_enriched_at ASC LIMIT %d",
            max(1,min(10,(int)$limit))
        ), ARRAY_A);
        foreach ((array)$rows as $row) {
            $req = new WP_REST_Request('POST', '/ruhrpottguru/v1/food-info');
            $req->set_body_params(array(
                'title'=>$row['name'],'city'=>$row['city'],'address'=>trim($row['street'].' '.$row['house_number']),
                'website'=>$row['website'],'wikidata'=>$row['wikidata'],'lat'=>(float)$row['lat'],'lng'=>(float)$row['lng']
            ));
            try {
                $response = ruhrpott_guru_food_info_enrichment($req);
                if ($response instanceof WP_REST_Response) $payload = $response->get_data(); else $payload = $response;
                $this->persist_food_enrichment((int)$row['id'], is_array($payload)?$payload:array());
            } catch (Throwable $e) {
                // Enrichment is non-critical. Existing place data remains publishable.
            }
        }
    }

    public function capture_food_enrichment_response($response, $handler, $request) {
        if (!($request instanceof WP_REST_Request) || $request->get_route() !== '/ruhrpottguru/v1/food-info') return $response;
        $params = $request->get_json_params();
        if (!is_array($params)) $params = $request->get_body_params();
        $lat = isset($params['lat']) ? (float)$params['lat'] : 0.0;
        $lng = isset($params['lng']) ? (float)$params['lng'] : 0.0;
        $title = isset($params['title']) ? (string)$params['title'] : '';
        if (!$this->valid_coordinate($lat,$lng) || $title==='') return $response;
        $payload = $response instanceof WP_REST_Response ? $response->get_data() : null;
        if (!is_array($payload) || ($payload['status'] ?? '') !== 'success') return $response;
        global $wpdb;
        $places = $this->table('places');
        $norm = $this->normalize_text($title);
        $row = $wpdb->get_row($wpdb->prepare(
            "SELECT id FROM $places WHERE normalized_name=%s AND lat BETWEEN %f AND %f AND lng BETWEEN %f AND %f ORDER BY ABS(lat-%f)+ABS(lng-%f) ASC LIMIT 1",
            $norm, $lat-0.002, $lat+0.002, $lng-0.003, $lng+0.003, $lat, $lng
        ), ARRAY_A);
        if ($row) $this->persist_food_enrichment((int)$row['id'], $payload);
        return $response;
    }

    private function persist_food_enrichment($place_id, $payload) {
        if (!$place_id || !is_array($payload) || ($payload['status'] ?? '') !== 'success') return;
        global $wpdb;
        $now = current_time('mysql', true);
        $source = sanitize_text_field((string)($payload['source'] ?? 'official-resolver'));
        $price_tier=$this->normalize_price_tier($payload['priceTier'] ?? ($payload['price_tier'] ?? ''));
        if (!empty($payload['website'])) $this->upsert_link($place_id,'website',esc_url_raw($payload['website']),$source,0.95,$now,false);
        if (!empty($payload['menuUrl'])) $this->upsert_link($place_id,'menu',esc_url_raw($payload['menuUrl']),$source,0.95,$now,false);
        if (!empty($payload['reservationUrl'])) $this->upsert_link($place_id,'reservation',esc_url_raw($payload['reservationUrl']),$source,0.95,$now,false);
        if (!empty($payload['openingHours'])) {
            $schedule = $this->table('place_schedules');
            $wpdb->query($wpdb->prepare(
                "INSERT INTO $schedule (place_id,schedule_type,raw_value,source,confidence,verified_at,last_seen_at,locked)
                 VALUES (%d,'general',%s,%s,0.9500,%s,%s,0)
                 ON DUPLICATE KEY UPDATE raw_value=IF(locked=1,raw_value,IF(VALUES(confidence)>=confidence,VALUES(raw_value),raw_value)),source=IF(locked=1,source,IF(VALUES(confidence)>=confidence,VALUES(source),source)),confidence=IF(locked=1,confidence,GREATEST(confidence,VALUES(confidence))),verified_at=IF(locked=1,verified_at,VALUES(verified_at)),last_seen_at=VALUES(last_seen_at)",
                $place_id, sanitize_text_field($payload['openingHours']), $source, $now, $now
            ));
        }
        $enrichment = $this->table('place_enrichment');
        $wpdb->query($wpdb->prepare(
            "INSERT INTO $enrichment (place_id,price_tier,website_url,website_source,menu_url,menu_source,reservation_url,reservation_source,opening_hours,opening_hours_source,last_enriched_at,updated_at)
             VALUES (%d,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s)
             ON DUPLICATE KEY UPDATE price_tier=IF(VALUES(price_tier)<>'',VALUES(price_tier),price_tier),website_url=VALUES(website_url),website_source=VALUES(website_source),menu_url=VALUES(menu_url),menu_source=VALUES(menu_source),reservation_url=VALUES(reservation_url),reservation_source=VALUES(reservation_source),opening_hours=VALUES(opening_hours),opening_hours_source=VALUES(opening_hours_source),last_enriched_at=VALUES(last_enriched_at),updated_at=VALUES(updated_at)",
            $place_id, $price_tier, $payload['website'] ?? null, $source, $payload['menuUrl'] ?? null, $source, $payload['reservationUrl'] ?? null, $source, $payload['openingHours'] ?? null, $source, $now, $now
        ));
        $places = $this->table('places');
        $update = array('last_enriched_at'=>$now,'updated_at'=>$now);
        if (!empty($payload['website'])) $update['website'] = esc_url_raw($payload['website']);
        if (!empty($payload['openingHours'])) $update['opening_hours'] = sanitize_text_field($payload['openingHours']);
        $wpdb->update($places, $update, array('id'=>$place_id));
    }


    public function rest_export() {
        $meta = get_option('rg_places_export_meta', array());
        if (get_option(self::OPTION_STATUS) === 'ready' && (empty($meta['path']) || !file_exists($meta['path']))) {
            $this->generate_osm_export();
            $meta = get_option('rg_places_export_meta', array());
        }
        return rest_ensure_response(array(
            'ok'=>true,
            'license'=>'ODbL 1.0',
            'attribution'=>'© OpenStreetMap contributors',
            'catalogVersion'=>(string)get_option(self::OPTION_CATALOG_VERSION,'bootstrap'),
            'downloadUrl'=>isset($meta['url'])?$meta['url']:null,
            'generatedAt'=>isset($meta['generated_at'])?$meta['generated_at']:null,
            'note'=>'Der Export enthält nur den OSM-basierten/abgeleiteten Places-Layer. RuhrpottGuru-Enrichment und andere unabhängige Datenlayer sind getrennt.',
        ));
    }

    private function maybe_refresh_osm_export() {
        $meta = get_option('rg_places_export_meta', array());
        $last = !empty($meta['generated_at']) ? strtotime($meta['generated_at']) : 0;
        if (!$last || time() - $last > DAY_IN_SECONDS) {
            if (!wp_next_scheduled('rg_places_generate_export')) wp_schedule_single_event(time()+60, 'rg_places_generate_export');
        }
    }

    public function generate_osm_export() {
        if (!function_exists('gzopen')) return false;
        global $wpdb;
        $uploads = wp_upload_dir();
        if (!empty($uploads['error'])) return false;
        $dir = trailingslashit($uploads['basedir']) . 'ruhrpottguru';
        if (!wp_mkdir_p($dir)) return false;
        $path = trailingslashit($dir) . 'ruhrpottguru-osm-places-latest.ndjson.gz';
        $tmp = $path . '.tmp';
        $fh = @gzopen($tmp, 'wb6');
        if (!$fh) return false;
        $places = $this->table('places');
        $sources = $this->table('place_sources');
        $cats = $this->table('place_categories');
        $offset = 0;
        $batch = 500;
        $written = 0;
        do {
            $rows = $wpdb->get_results($wpdb->prepare(
                "SELECT p.id,p.name,p.lat,p.lng,p.city,p.district,p.street,p.house_number,p.postcode,p.lifecycle_status,p.active,p.primary_category,p.primary_subcategory,p.raw_tags,p.last_synced_at,
                        s.source_uid,s.osm_type,s.osm_id,s.osm_version,s.osm_timestamp
                 FROM $places p LEFT JOIN $sources s ON s.place_id=p.id AND s.source_type='osm'
                 ORDER BY p.id ASC LIMIT %d OFFSET %d",
                $batch, $offset
            ), ARRAY_A);
            foreach ((array)$rows as $row) {
                $record = array(
                    'place_id'=>(int)$row['id'],'name'=>$row['name'],'lat'=>(float)$row['lat'],'lng'=>(float)$row['lng'],
                    'city'=>$row['city'],'district'=>$row['district'],'street'=>$row['street'],'house_number'=>$row['house_number'],'postcode'=>$row['postcode'],
                    'category'=>$row['primary_category'],'subcategory'=>$row['primary_subcategory'],'lifecycle_status'=>$row['lifecycle_status'],'active'=>(bool)$row['active'],
                    'osm_source_uid'=>$row['source_uid'],'osm_type'=>$row['osm_type'],'osm_id'=>(int)$row['osm_id'],'osm_version'=>(int)$row['osm_version'],'osm_timestamp'=>$row['osm_timestamp'],
                    'raw_osm_tags'=>json_decode((string)$row['raw_tags'],true),'last_synced_at'=>$row['last_synced_at']
                );
                gzwrite($fh, wp_json_encode($record, JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES) . "\n");
                $written++;
            }
            $offset += $batch;
        } while (count((array)$rows) === $batch);
        gzclose($fh);
        if (!@rename($tmp, $path)) { @unlink($tmp); return false; }
        $url = trailingslashit($uploads['baseurl']) . 'ruhrpottguru/ruhrpottguru-osm-places-latest.ndjson.gz';
        update_option('rg_places_export_meta', array('path'=>$path,'url'=>$url,'generated_at'=>current_time('mysql',true),'records'=>$written), false);
        return true;
    }

    private function has_browser_sync_work() {
        $state=$this->browser_sync_queue_state(get_option(self::OPTION_STATUS) === 'ready');
        return !empty($state['hasWork']);
    }

    public function admin_enqueue_bootstrap($hook) {
        if (!current_user_can('manage_options')) return;
        if (!$this->has_browser_sync_work()) return;
        $path = plugin_dir_path(__FILE__) . 'assets/bootstrap.js';
        wp_enqueue_script('rg-places-bootstrap', plugin_dir_url(__FILE__) . 'assets/bootstrap.js', array(), file_exists($path)?filemtime($path):self::VERSION, true);
        wp_localize_script('rg-places-bootstrap', 'RGPlacesBootstrap', array(
            'nextUrl'=>esc_url_raw(rest_url('ruhrpottguru/v1/places/bootstrap/next')),
            'importUrl'=>esc_url_raw(rest_url('ruhrpottguru/v1/places/bootstrap/import')),
            'completeUrl'=>esc_url_raw(rest_url('ruhrpottguru/v1/places/bootstrap/complete')),
            'statusUrl'=>esc_url_raw(rest_url('ruhrpottguru/v1/places/status')),
            'nonce'=>wp_create_nonce(self::ADMIN_NONCE_ACTION),
            'providers'=>array('https://overpass.private.coffee/api/interpreter','https://maps.mail.ru/osm/tools/overpass/api/interpreter','https://overpass-api.de/api/interpreter'),
            'version'=>self::VERSION,
        ));
    }


    private function event_text($value, $max=0) {
        if (is_array($value) || is_object($value)) return '';
        $v=trim(wp_strip_all_tags((string)$value));
        if($max>0 && function_exists('mb_substr'))$v=mb_substr($v,0,$max);
        elseif($max>0)$v=substr($v,0,$max);
        return $v;
    }

    /** V1.10.58: convert ET4 rich text to safe readable plaintext without flattening paragraphs. */
    private function event_plaintext_blocks_v1058($value, $max=0) {
        if (is_array($value) || is_object($value)) return '';
        $v=(string)$value;
        $v=preg_replace('~<\s*br\s*/?\s*>~i', "\n", $v);
        $v=preg_replace('~</\s*(?:p|div|li|h[1-6]|section|article|tr)\s*>~i', "\n", $v);
        $v=preg_replace('~<\s*li\b[^>]*>~i', '• ', $v);
        $v=html_entity_decode(wp_strip_all_tags($v), ENT_QUOTES | ENT_HTML5, 'UTF-8');
        $v=str_replace(array("\r\n","\r"),"\n",$v);
        $lines=array();$blank=false;
        foreach(explode("\n",$v) as $line){
            $line=trim(preg_replace('/[ \t\x{00A0}]+/u',' ',(string)$line));
            if($line===''){if(!$blank&&$lines){$lines[]='';$blank=true;}continue;}
            $lines[]=$line;$blank=false;
        }
        while($lines && end($lines)==='')array_pop($lines);
        $v=trim(implode("\n",$lines));
        if($max>0 && function_exists('mb_substr'))$v=mb_substr($v,0,$max);
        elseif($max>0)$v=substr($v,0,$max);
        return $v;
    }

    private function event_datetime_mysql($value) {
        if($value===null || $value==='')return null;
        try{
            $dt=new DateTimeImmutable((string)$value);
            $dt=$dt->setTimezone(wp_timezone());
            return $dt->format('Y-m-d H:i:s');
        }catch(Exception $e){return null;}
    }

    /** 1.10.154: pure canonical range guard. Five years is intentionally
     * conservative: normal exhibitions may span well beyond one year, while a
     * century-long source range is treated as an untrusted end value. */
    private function event_range_guard_v101154($start,$end) {
        $result=array('end'=>$end,'guarded'=>false,'reason'=>'');
        if($end===null||$end==='')return $result;
        try{
            $s=$start instanceof DateTimeInterface?DateTimeImmutable::createFromInterface($start):new DateTimeImmutable((string)$start,wp_timezone());
            $e=$end instanceof DateTimeInterface?DateTimeImmutable::createFromInterface($end):new DateTimeImmutable((string)$end,wp_timezone());
        }catch(Exception $e){$result['end']=null;$result['guarded']=true;$result['reason']='invalid-end';return $result;}
        $seconds=$e->getTimestamp()-$s->getTimestamp();
        if($seconds<0){$result['end']=null;$result['guarded']=true;$result['reason']='end-before-start';return $result;}
        if($e>$s->modify('+5 years')){$result['end']=null;$result['guarded']=true;$result['reason']='end-over-five-years';return $result;}
        return $result;
    }

    /** 1.10.154: keep DB lifecycle state consistent even if a long-running
     * import wave reaches an occurrence only after that occurrence has ended. */
    private function event_status_for_range_v101154($sourceLifecycle,$start,$end,$nowTs=null) {
        if((string)$sourceLifecycle==='cancelled')return 'cancelled';
        $nowTs=$nowTs===null?current_time('timestamp'):(int)$nowTs;
        $effective=trim((string)($end?:$start));$ts=$effective!==''?strtotime($effective):0;
        return ($ts>0&&$ts<$nowTs)?'expired':'active';
    }

    private function event_public_range_bad_v101155($start,$end) {
        if($start===null||$start===''||$end===null||$end==='')return false;
        try{
            $s=$start instanceof DateTimeInterface?DateTimeImmutable::createFromInterface($start):new DateTimeImmutable((string)$start,wp_timezone());
            $e=$end instanceof DateTimeInterface?DateTimeImmutable::createFromInterface($end):new DateTimeImmutable((string)$end,wp_timezone());
        }catch(Exception $e){return false;}
        $guard=$this->event_range_guard_v101154($s,$e);
        return !empty($guard['guarded'])&&in_array((string)($guard['reason']??''),array('end-before-start','end-over-five-years'),true);
    }

