            if(isset($node[$sk])&&!is_array($node[$sk])&&!is_object($node[$sk])&&trim((string)$node[$sk])!==''){$localStart=(string)$node[$sk];break;}
        }
        foreach(array('end','endDate','end_date','to','_rpg_occurrence_end') as $ek){
