        }
        foreach($node as $k=>$v){if(is_array($v))$node[$k]=$this->event_sanitize_public_range_node_v101155($v,$localStart);}
        return $node;
    }

    private function event_sanitize_public_range_v101155($item,$row=array()) {
        if(!is_array($item))return $item;
        $fallback='';
        if(is_array($row)&&!empty($row['start_at']))$fallback=(string)$row['start_at'];
        elseif(isset($item['start'])&&!is_array($item['start'])&&!is_object($item['start']))$fallback=(string)$item['start'];
        return $this->event_sanitize_public_range_node_v101155($item,$fallback);
    }

    private function event_first_interval($item) {
        $intervals=$item['timeIntervals']??($item['time_intervals']??($item['intervals']??array()));
        if(isset($intervals['timeInterval']))$intervals=$intervals['timeInterval'];
        if(isset($intervals['start']) || isset($intervals['end']))return $intervals;
        if(is_array($intervals))foreach($intervals as $v)if(is_array($v))return $v;
        return array();
    }

    /** V1.7.4: collect ET2014A interval/occurrence rules recursively. */
