        return $out;
    }

    private function event_et4_weekday_number($value) {
        if(is_numeric($value)){$n=(int)$value;return ($n>=0&&$n<=6)?$n:null;}
        $v=mb_strtolower(trim((string)$value));$map=array('sunday'=>0,'sonntag'=>0,'monday'=>1,'montag'=>1,'tuesday'=>2,'dienstag'=>2,'wednesday'=>3,'mittwoch'=>3,'thursday'=>4,'donnerstag'=>4,'friday'=>5,'freitag'=>5,'saturday'=>6,'samstag'=>6);return array_key_exists($v,$map)?$map[$v]:null;
    }

    private function event_et4_weekdays($interval) {
        if(!is_array($interval))return array();$value=$interval['weekdays']??($interval['weekday']??null);if(is_array($value)&&isset($value['weekday']))$value=$value['weekday'];if($value===null||$value==='')return array();$values=is_array($value)?$value:array($value);$out=array();foreach($values as $v){$n=$this->event_et4_weekday_number($v);if($n!==null&&!in_array($n,$out,true))$out[]=$n;}return $out;
