    private function event_et4_nth_weekday(DateTimeImmutable $date,$weekday,$ordinal) {
        $weekday=(int)$weekday;$ordinal=(int)$ordinal;if($ordinal===0)return true;$y=(int)$date->format('Y');$m=(int)$date->format('n');$tz=$date->getTimezone();
        if($ordinal>0){$first=new DateTimeImmutable(sprintf('%04d-%02d-01',$y,$m),$tz);$delta=($weekday-(int)$first->format('w')+7)%7;$wanted=1+$delta+7*($ordinal-1);return (int)$date->format('j')===$wanted;}
        $last=(new DateTimeImmutable(sprintf('%04d-%02d-01',$y,$m),$tz))->modify('last day of this month');$delta=((int)$last->format('w')-$weekday+7)%7;$wanted=(int)$last->format('j')-$delta+7*($ordinal+1);return (int)$date->format('j')===$wanted;
    }

    private function event_et4_recurrence_match($interval,DateTimeImmutable $base,DateTimeImmutable $day) {
        $freq=strtolower(trim((string)($interval['freq']??'single')));$step=max(1,(int)($interval['interval']??1));$baseDay=$base->setTime(0,0,0);$candidateDay=$day->setTime(0,0,0);if($candidateDay<$baseDay)return false;$days=(int)$baseDay->diff($candidateDay)->format('%a');$weekdays=$this->event_et4_weekdays($interval);$dow=(int)$day->format('w');$weekdayOk=$weekdays?in_array($dow,$weekdays,true):true;
