            'source_status'=>(string)($row['source_status']??'active'),
            'missing_since'=>$row['missing_since']??null,
            'missing_count'=>(int)($row['missing_count']??0),
            'last_missing_run'=>(string)($row['last_missing_run']??''),
            'status'=>(string)($row['status']??'active'),
