    /** Apply Missing-Lifecycle only after a successful, complete source wave. */
    private function event_apply_missing_lifecycle_v101125($run_token,$query_start,$query_end,$sources,$label='') {
        global $wpdb;$events=$this->table('events');$run_token=sanitize_key((string)$run_token);
        $report=array('label'=>(string)$label,'run_token'=>$run_token,'scoped'=>0,'seen'=>0,'missing'=>0,'inactivated'=>0,'reactivated'=>0,'skipped'=>0,'at'=>current_time('mysql'));
        if($run_token===''){$report['error']='missing-run-token';return $report;}
        $tz=wp_timezone();$start=DateTimeImmutable::createFromFormat('!d.m.Y',(string)$query_start,$tz);$end=DateTimeImmutable::createFromFormat('!d.m.Y',(string)$query_end,$tz);
        if(!$start||!$end){$report['error']='invalid-window';return $report;}
        $startMysql=$start->setTime(0,0,0)->format('Y-m-d H:i:s');$endMysql=$end->setTime(23,59,59)->format('Y-m-d H:i:s');
        $sources=array_values(array_unique(array_filter(array_map('sanitize_key',(array)$sources))));if(!$sources){$report['error']='missing-sources';return $report;}
        $ph=implode(',',array_fill(0,count($sources),'%s'));
        $sql=$wpdb->prepare("SELECT id,status,source_status,missing_since,missing_count,last_source_run,last_missing_run FROM $events WHERE source IN ($ph) AND status IN ('active','inactive') AND ((start_at BETWEEN %s AND %s) OR (start_at<%s AND end_at IS NOT NULL AND end_at>=%s))",...array_merge($sources,array($startMysql,$endMysql,$startMysql,$startMysql)));
        $rows=(array)$wpdb->get_results($sql,ARRAY_A);$report['scoped']=count($rows);$nowTs=current_time('timestamp');$now=current_time('mysql');
        foreach($rows as $row){$seen=((string)($row['last_source_run']??'')===$run_token);$before=(string)($row['status']??'');$next=$this->event_lifecycle_transition_v101125($row,$seen,$run_token,$nowTs);
            if($seen)$report['seen']++;else if(($next['reason']??'')==='already-counted'){$report['skipped']++;continue;}else $report['missing']++;
            if(empty($next['changed']))continue;
            $data=array('source_status'=>$next['source_status'],'missing_since'=>$next['missing_since'],'missing_count'=>(int)$next['missing_count'],'last_missing_run'=>$next['last_missing_run'],'status'=>$next['status'],'updated_at'=>$now);
            $wpdb->update($events,$data,array('id'=>(int)$row['id']));
            if(!empty($next['newly_inactivated']))$report['inactivated']++;
            if($before==='inactive'&&$next['status']==='active')$report['reactivated']++;
        }
        update_option('rg_events_lifecycle_last_v101125',$report,false);return $report;
    }

    /** Apply explicit cancellations from source objects even when no occurrence is emitted. */
    private function event_apply_explicit_cancellations_v101125($items,$run_token,$sources) {
        global $wpdb;$events=$this->table('events');$run_token=sanitize_key((string)$run_token);$sources=array_values(array_unique(array_filter(array_map('sanitize_key',(array)$sources))));if(!$sources)return 0;
