        if(!$ids)return 0;$now=current_time('mysql');$count=0;$ph=implode(',',array_fill(0,count($sources),'%s'));
        foreach(array_keys($ids) as $ext){$sql=$wpdb->prepare("UPDATE $events SET status='cancelled',source_status='cancelled',missing_since=NULL,missing_count=0,last_missing_run='',last_source_run=%s,last_seen_at=%s,last_synced_at=%s,updated_at=%s WHERE source IN ($ph) AND external_id=%s AND status<>'cancelled'",...array_merge(array($run_token,$now,$now,$now),$sources,array($ext)));$n=$wpdb->query($sql);if($n!==false)$count+=(int)$n;}
