            'zip'=>$this->event_text($a['zip']??($a['postalCode']??''),20),'city'=>$this->event_text($a['city']??($a['addressLocality']??''),120),
            'district'=>$this->event_text($a['district']??'',120),'phone'=>$this->event_public_phone_v101153($a['phone']??''),'phone2'=>$this->event_public_phone_v101153($a['phone2']??''),
