                'zip'=>$this->event_text($r['zip']??($r['postalCode']??''),20),'city'=>$this->event_text($r['city']??($r['addressLocality']??''),120),
                'district'=>$this->event_text($r['district']??'',120),'phone'=>$this->event_public_phone_v101153($r['phone']??''),'phone2'=>$this->event_public_phone_v101153($r['phone2']??''),
