                if(trim((string)($merged[$key][$f]??''))===''&&trim((string)($r[$f]??''))!=='')$merged[$key][$f]=$r[$f];
            }
        }
        $out=array();
        foreach($order as $key){
            $r=$merged[$key];$r['rel']='organizer';
            if(!empty($r['web'])&&$this->event_is_provider_or_directory_url($r['web']))$r['web']='';
