    private function ingest_event_items($items,$context='feed',$with_stats=false) {
        $stats=array('raw_count'=>count((array)$items),'success'=>0,'inserted'=>0,'updated'=>0,'invalid'=>0,'date_guarded'=>0,'cancelled'=>0,'cancelled_created'=>0,'unique_occurrences'=>0,'duplicates_in_batch'=>0,'unique_external_objects'=>0,'canonical_keys'=>array(),'external_keys'=>array());
        $seen=array();$externalSeen=array();
        foreach((array)$items as $item){
            $meta=null;$event_id=$this->event_upsert_from_feed_item($item,$meta,$context);
            if(!$event_id){$stats['invalid']++;continue;}
            $stats['success']++;
            if(!empty($meta['created']))$stats['inserted']++;else$stats['updated']++;if(!empty($meta['date_guard']))$stats['date_guarded']++;if(($meta['source_status']??'')==='cancelled'){$stats['cancelled']++;if(!empty($meta['created']))$stats['cancelled_created']++;}
            $key=(string)($meta['canonical_key']??'');
            if($key!==''){
                if(isset($seen[$key]))$stats['duplicates_in_batch']++;else{$seen[$key]=1;$stats['canonical_keys'][]=$key;}
            }
            $ek=(string)($meta['external_key']??'');
            if($ek!==''&&!isset($externalSeen[$ek])){$externalSeen[$ek]=1;$stats['external_keys'][]=$ek;}
        }
        $stats['unique_occurrences']=count($stats['canonical_keys']);$stats['unique_external_objects']=count($stats['external_keys']);
        update_option('rg_events_last_ingest',array('count'=>$stats['success'],'raw_count'=>$stats['raw_count'],'inserted'=>$stats['inserted'],'updated'=>$stats['updated'],'invalid'=>$stats['invalid'],'date_guarded'=>$stats['date_guarded'],'cancelled'=>$stats['cancelled'],'cancelled_created'=>$stats['cancelled_created'],'unique_occurrences'=>$stats['unique_occurrences'],'duplicates_in_batch'=>$stats['duplicates_in_batch'],'context'=>$context,'at'=>current_time('mysql'),'timestamp'=>time()),false);
        return $with_stats?$stats:$stats['success'];
    }

    private function event_master_seen_reset() {
        delete_option('rg_events_master_seen_occurrences_v171');delete_option('rg_events_master_seen_external_v171');delete_option('rg_events_master_seen_source_rows_v174');
        add_option('rg_events_master_seen_occurrences_v171',array(),'','no');add_option('rg_events_master_seen_external_v171',array(),'','no');add_option('rg_events_master_seen_source_rows_v174',array(),'','no');
    }

    private function event_master_seen_apply($canonical_keys,$external_keys=array()) {
        $seen=get_option('rg_events_master_seen_occurrences_v171',array());if(!is_array($seen))$seen=array();
        $external=get_option('rg_events_master_seen_external_v171',array());if(!is_array($external))$external=array();
        $new=0;$repeat=0;foreach((array)$canonical_keys as $key){$key=(string)$key;if($key==='')continue;if(isset($seen[$key]))$repeat++;else{$seen[$key]=1;$new++;}}
        $externalNew=0;foreach((array)$external_keys as $key){$key=(string)$key;if($key===''||isset($external[$key]))continue;$external[$key]=1;$externalNew++;}
        update_option('rg_events_master_seen_occurrences_v171',$seen,false);update_option('rg_events_master_seen_external_v171',$external,false);
        return array('new_occurrences'=>$new,'repeat_occurrences'=>$repeat,'unique_occurrences_total'=>count($seen),'new_external_objects'=>$externalNew,'unique_external_objects_total'=>count($external));
    }

    private function event_master_unique_source_rows($items) {
        $persisted=get_option('rg_events_master_seen_source_rows_v174',array());if(!is_array($persisted))$persisted=array();$local=$persisted;$new=array();$keys=array();$repeat=0;
        foreach((array)$items as $item){if(!is_array($item))continue;$external=$this->event_external_id_from_item($item);$source=$this->event_source_name_from_item($item);$key=$external!==''?sha1($source.'|'.$external):sha1(wp_json_encode(array($item['title']??($item['name']??''),$item['timeIntervals']??($item['occurrences']??($item['subitems']??array()))),JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES));if(isset($local[$key])){$repeat++;continue;}$local[$key]=1;$keys[]=$key;$new[]=$item;}
        // Do not persist yet. The page may still fail during occurrence expansion/upsert. We
        // commit these source keys only after ingest_event_items returned successfully.
        return array('items'=>$new,'new_source_keys'=>$keys,'new_source_objects'=>count($new),'repeat_unrolled_rows'=>$repeat,'unique_source_objects_total_if_committed'=>count($local),'unique_source_objects_before'=>count($persisted));
    }

    private function event_master_commit_source_rows($keys) {
        $seen=get_option('rg_events_master_seen_source_rows_v174',array());if(!is_array($seen))$seen=array();foreach((array)$keys as $key){$key=(string)$key;if($key!=='')$seen[$key]=1;}update_option('rg_events_master_seen_source_rows_v174',$seen,false);return count($seen);
    }

    private function event_master_seen_clear() {
        delete_option('rg_events_master_seen_occurrences_v171');delete_option('rg_events_master_seen_external_v171');delete_option('rg_events_master_seen_source_rows_v174');
    }

    private function event_master_db_window_audit($night) {
        global $wpdb;$events=$this->table('events');$run_token=sanitize_key((string)($night['run_token']??''));
        $now=current_time('mysql');
        if($run_token!==''){
            $unique=(int)$wpdb->get_var($wpdb->prepare("SELECT COUNT(*) FROM $events WHERE last_master_run=%s",$run_token));
            $active=(int)$wpdb->get_var($wpdb->prepare("SELECT COUNT(*) FROM $events WHERE last_master_run=%s AND status='active' AND (end_at IS NULL OR end_at >= %s)",$run_token,$now));
            $external=(int)$wpdb->get_var($wpdb->prepare("SELECT COUNT(DISTINCT CONCAT(source,'|',external_id)) FROM $events WHERE last_master_run=%s AND external_id<>''",$run_token));
            return array('unique_touched'=>$unique,'active_touched'=>$active,'unique_external_objects'=>$external,'mode'=>(string)($night['audit_mode']??'exact-token'));
        }
        $started=(string)($night['started_at']??'');$finished=(string)($night['finished_at']??'');
        if($started==='')return array('unique_touched'=>0,'active_touched'=>0,'unique_external_objects'=>0,'mode'=>'none');
        if($finished==='')$finished=$now;
        $unique=(int)$wpdb->get_var($wpdb->prepare("SELECT COUNT(*) FROM $events WHERE last_synced_at >= %s AND last_synced_at <= %s",$started,$finished));
        $active=(int)$wpdb->get_var($wpdb->prepare("SELECT COUNT(*) FROM $events WHERE last_synced_at >= %s AND last_synced_at <= %s AND status='active' AND (end_at IS NULL OR end_at >= %s)",$started,$finished,$now));
        $external=(int)$wpdb->get_var($wpdb->prepare("SELECT COUNT(DISTINCT CONCAT(source,'|',external_id)) FROM $events WHERE last_synced_at >= %s AND last_synced_at <= %s AND external_id<>''",$started,$finished));
        return array('unique_touched'=>$unique,'active_touched'=>$active,'unique_external_objects'=>$external,'mode'=>'legacy-time-window');
    }

    private function event_master_batch_lock_acquire() {
        $name='rg_events_master_batch_lock_v172';$now=time();$existing=(int)get_option($name,0);
        if($existing && $existing < $now-180){delete_option($name);$existing=0;}
        if($existing)return false;
        return add_option($name,$now,'','no');
    }

    private function event_master_batch_lock_release() { delete_option('rg_events_master_batch_lock_v172'); }

    private function event_master_recover_run_token(&$night) {
        if(!is_array($night)||($night['status']??'')!=='running'||!empty($night['run_token']))return;
        global $wpdb;$events=$this->table('events');$started=(string)($night['started_at']??'');if($started==='')return;
        $token='recovered-'.gmdate('YmdHis').'-'.wp_rand(1000,9999);$now=current_time('mysql');
        $wpdb->query($wpdb->prepare("UPDATE $events SET last_master_run=%s WHERE last_synced_at >= %s AND last_synced_at <= %s",$token,$started,$now));
        $night['run_token']=$token;$night['audit_mode']='recovered-time-window';$night['recovered_at']=$now;update_option('rg_events_nightly_state',$night,false);
    }

    public function ensure_event_master_worker() {
        if(defined('DOING_CRON')&&DOING_CRON)return;
        $night=get_option('rg_events_nightly_state',array());if(!is_array($night))$night=array();

        // v1.7.3 one-time self-heal: v1.7.2 used "start asc,title asc" while
        // ET4 explicitly requires exactly "start asc" for unrollIntervals. Resume the
        // failed master run at the existing master_offset instead of starting over.
        $known_sort_error="unrolling intervals is only possible when sorting by 'start asc'";
        $sync=get_option('rg_events_sync_state',array());if(!is_array($sync))$sync=array();
        $failed_error=(string)($night['last_error']??'');if($failed_error==='')$failed_error=(string)($sync['last_error']??'');
        if(($night['status']??'')==='failed' && stripos($failed_error,$known_sort_error)!==false && empty($night['v173_sort_recovered'])){
            $night['failed_attempts_before_v173']=(int)($night['errors']??0);
            $night['errors']=0;
            $night['status']='running';
            $night['finished_at']='';
            $night['last_error']='';
            $night['v173_sort_recovered']=current_time('mysql');
            $night['last_progress_at']=current_time('mysql');
            // v1.7.2 incremented pages_done even for failed attempts. For this known
            // failure reconstruct successful full pages from the preserved offset.
            $resume_offset=max(0,(int)($sync['master_offset']??($night['last_offset']??0)));
            if($resume_offset>0)$night['pages_done']=(int)floor($resume_offset/100);
            update_option('rg_events_nightly_state',$night,false);
            wp_clear_scheduled_hook(self::EVENT_NIGHTLY_BATCH_HOOK);
        }

        if(($night['status']??'')!=='running')return;
        $this->event_master_recover_run_token($night);
        $lock=(int)get_option('rg_events_master_batch_lock_v172',0);if($lock && $lock>=time()-180)return;if($lock)delete_option('rg_events_master_batch_lock_v172');
        $next=wp_next_scheduled(self::EVENT_NIGHTLY_BATCH_HOOK);
        if(!$next || $next>time()+300){wp_clear_scheduled_hook(self::EVENT_NIGHTLY_BATCH_HOOK);wp_schedule_single_event(time(),self::EVENT_NIGHTLY_BATCH_HOOK);if(function_exists('spawn_cron'))spawn_cron();}
        elseif($next<=time()&&function_exists('spawn_cron'))spawn_cron();
    }

    private function event_apply_db_enrichment_to_item($item, $event_id) {
        if (!is_array($item) || !$event_id) return $item;
        global $wpdb;
        $events = $this->table('events');
        $media = $this->table('event_media');
        $row = $wpdb->get_row($wpdb->prepare("SELECT * FROM $events WHERE id=%d LIMIT 1", (int)$event_id), ARRAY_A);
        if (!$row) return $item;

        // V1.6.10: The live Open-Data-Finder fallback is still allowed before a
        // full 53-city nightly DB wave has completed. Even in that mode, overlay
        // the persistent/enriched Event DB values so verified images and repaired
        // addresses immediately reach the visitor-facing REST response.
        $item['rpg_event_db'] = array(
            'eventId'=>(int)$row['id'],
            'canonicalKey'=>(string)$row['canonical_key'],
            'addressStatus'=>(string)$row['address_status'],
            'mediaStatus'=>(string)$row['media_status'],
            'enrichmentStatus'=>(string)$row['enrichment_status'],
        );
        $visitorRow=$this->event_apply_curated_visitor_data_to_row($row);
        if(!empty($visitorRow['start_at']))$item['start']=$this->event_visitor_datetime_iso((string)$visitorRow['start_at'],$visitorRow);
        if(!empty($visitorRow['end_at']))$item['end']=$this->event_visitor_datetime_iso((string)$visitorRow['end_at'],$visitorRow);
        if (!empty($row['venue_name'])) $item['venueName'] = (string)$row['venue_name'];
        if (!empty($row['street']) || !empty($row['postcode']) || !empty($row['city'])) {
            $item['address'] = array(
                'street'=>(string)$row['street'],
                'houseNumber'=>(string)$row['house_number'],
                'postalCode'=>(string)$row['postcode'],
                'city'=>(string)$row['city'],
                'addressLocality'=>(string)$row['city'],
                'rel'=>'event',
                'type'=>'event',
            );
        }
        $participants = json_decode((string)($row['participants_json'] ?? ''), true);
        if (is_array($participants) && $participants) $item['rpg_participants'] = $participants;
        $prices=json_decode((string)($row['price_json']??''),true);if(!is_array($prices))$prices=array();
        $organizers=$this->event_current_organizers_from_row_v1063($row);
        $info=json_decode((string)($row['event_info_json']??''),true);if(!is_array($info))$info=array();
        if(isset($row['description']))$item['description']=(string)$row['description'];
        if(!empty($row['ticket_url']))$item['ticketUrl']=(string)$row['ticket_url'];
        $storedRaw=json_decode((string)($row['raw_payload']??''),true);if(!is_array($storedRaw))$storedRaw=array();
        $documents=$this->event_documents_from_item_v1063($storedRaw);$allDay=$this->event_all_day_from_row_v1063($row,$storedRaw);
        $publicWebsite=$this->event_public_website_from_item($storedRaw);
        $item=$this->event_sanitize_public_urls($item,$publicWebsite);
        $item['rpg_event_details']=array('shortDescription'=>(string)($row['short_description']??''),'priceText'=>(string)($row['price_text']??''),'prices'=>$prices,'organizers'=>$organizers,'info'=>$info,'ticketUrl'=>(string)($row['ticket_url']??''),'website'=>$publicWebsite,'canonicalUrl'=>$this->event_canonical_share_url_v1057((int)$event_id,(string)($row['title']??''),(string)($row['city']??'')),'programUrl'=>(string)($visitorRow['_rpg_program_url']??($documents[0]['url']??'')),'programLabel'=>(string)($visitorRow['_rpg_program_label']??($documents[0]['label']??'Programm')),'documents'=>$documents,'allDay'=>$allDay,'visitorHours'=>(string)($visitorRow['_rpg_visitor_hours']??''),'dayHours'=>(string)($visitorRow['_rpg_day_hours']??''),'visitorHoursSource'=>(string)($visitorRow['_rpg_visitor_hours_source']??''),'sourceCreatedAt'=>(string)($row['source_created_at']??''),'sourceChangedAt'=>(string)($row['source_changed_at']??''));

        $item=$this->event_sanitize_public_range_v101155($item,$visitorRow);

