                'contentUrl'=>$public_image,
                'rel'=>'event',
                'type'=>'image',
                'prio'=>0,
                'source'=>$isEt4Media?'et4-global-id-local':(string)$m['source'],
                'sourceUrl'=>(string)$m['source_url'],
                'license'=>(string)$m['license'],
                'artist'=>(string)$m['artist'],
                'credit'=>(string)$m['credit'],
