                'sourceUrl'=>(string)$m['source_url'],
                'license'=>(string)$m['license'],
                'artist'=>(string)$m['artist'],
                'credit'=>(string)$m['credit'],
                'mediaLabel'=>$isEt4Media?'Eventbild':$this->event_media_label_v1042((string)$m['source']),
                'visualQualityStatus'=>(string)($m['visual_quality_status']??''),'semanticVersion'=>(strpos((string)($m['visual_quality_reason']??''),'semantic-v298')===0?'v298':''),
            );
        }
