    }

    public function capture_event_feed_response($response,$handler,$request) {
        if(!($request instanceof WP_REST_Request) || $request->get_route()!=='/ruhrpottguru/v1/events')return $response;
        $data=$response instanceof WP_REST_Response?$response->get_data():$response;
        if(!is_array($data)||empty($data['items'])||!is_array($data['items']))return $response;
        // V1.7.5: the visitor endpoint is DB-first. Never feed a DB response back into
        // the same event table; that used to refresh last_seen/source timestamps without
        // any upstream source contact and made provenance/freshness audits impossible.
        $meta=is_array($data['meta']??null)?$data['meta']:array();
        if((string)($meta['source']??'')==='event-db' || (string)($data['cache']??'')==='DB')return $response;

        $count=0;
        foreach($data['items'] as $index=>$item){
            if(!is_array($item))continue;
            $event_id=$this->event_upsert_from_feed_item($item);
            if($event_id){
                $count++;
                $data['items'][$index]=$this->event_apply_db_enrichment_to_item($item,$event_id);
            }
        }
        update_option('rg_events_last_ingest',array('count'=>$count,'context'=>'frontend-rest-overlay','at'=>current_time('mysql'),'timestamp'=>time()),false);
        if($response instanceof WP_REST_Response){$response->set_data($data);return $response;}
        return $data;
    }

    private function event_feed_media_candidate($raw) {
        if (!is_array($raw)) return null;

        // V1.10.21: ET2014A stores links and images in the same media_objects
        // structure. Relations such as canonical/pages/homepage are normal HTML
        // pages and must never reach the frontend as card images. At the same
        // time, event-owned artwork may live on event-adjacent subitems or
        // occurrences. We therefore inspect only explicit event branches and
        // require positive image evidence. We deliberately do NOT recurse into
        // location/venue/address/provider structures.
        $mediaKeys = array('media_objects','mediaObjects','media_object','mediaObject','media','images','image','photos','photo');
        $hardNonImageRel = array(
            'canonical','pages','homepage','website','source','booking','socialmedia',
            'rating','qrcode','video','audio','barrierfree'
        );
        $imageRelRank = array(
            'default'=>0,'imagegallery'=>1,'gallery'=>1,'teaser'=>2,'hero'=>2,'image'=>2,'photo'=>2,'picture'=>2,
            'mobile'=>3,'thumbnail'=>4,'print'=>5,'summer'=>6,'winter'=>6,'logo'=>8,
            'download'=>9,'other'=>10
        );
        $imageRels = array('default','imagegallery','gallery','teaser','hero','image','photo','picture','mobile','thumbnail','print','summer','winter','logo');
        $candidates = array();

        $isList = function($value) {
            if (!is_array($value)) return false;
            if ($value === array()) return true;
            return array_keys($value) === range(0, count($value)-1);
        };
        $flattenMedia = function($value) use (&$flattenMedia, $isList) {
            if (!is_array($value)) return array($value);
            foreach (array('media_object','mediaObject') as $wrapper) {
                if (array_key_exists($wrapper,$value)) return $flattenMedia($value[$wrapper]);
            }
            return $isList($value) ? $value : array($value);
        };
        $flattenChildren = function($value, $wrapperKeys=array()) use (&$flattenChildren, $isList) {
            if (!is_array($value)) return array();
            foreach ((array)$wrapperKeys as $wrapper) {
                if (array_key_exists($wrapper,$value)) return $flattenChildren($value[$wrapper],array());
            }
            return $isList($value) ? $value : array($value);
        };

        $collectPools = function($node, $scopeRank, $scopeName) use (&$candidates, $mediaKeys, $flattenMedia, $hardNonImageRel, $imageRelRank, $imageRels) {
            if (!is_array($node)) return;
            foreach ($mediaKeys as $key) {
                if (!array_key_exists($key,$node)) continue;
                foreach ($flattenMedia($node[$key]) as $entry) {
                    if (!$entry) continue;

                    if (is_string($entry)) {
                        $url=esc_url_raw(trim($entry));
                        if($url && wp_http_validate_url($url) && preg_match('/\.(?:jpe?g|png|webp|gif|avif|svg)(?:[?#].*)?$/i',$url)){
                            $candidates[]=array(
                                'url'=>$url,'rel'=>'other','prio'=>9999,'license'=>'','artist'=>'','credit'=>'','source_url'=>'',
                                '_scope_rank'=>$scopeRank,'_scope'=>$scopeName,'_rel_rank'=>$imageRelRank['other']
                            );
                        }
                        continue;
                    }
                    if (!is_array($entry)) continue;

                    $type=strtolower(trim((string)($entry['type']??($entry['mimeType']??($entry['contentType']??'')))));
                    $rel=strtolower(trim((string)($entry['rel']??($entry['relation']??'other'))));
                    if(in_array($rel,$hardNonImageRel,true)) continue;

                    $explicitImageType=(strpos($type,'image/')===0 || in_array($type,array('image','photo','picture'),true));
                    $explicitImageRel=in_array($rel,$imageRels,true);
                    $nonImageType=(strpos($type,'video/')===0 || strpos($type,'audio/')===0 || $type==='application/pdf' || strpos($type,'text/html')===0);
                    if($nonImageType) continue;

                    $url='';
                    $urlFields=array('contentUrl','content_url','src','imageUrl','image_url','downloadUrl','download_url','url','href','@id');
                    foreach($urlFields as $uk){
                        if(empty($entry[$uk]) || !is_string($entry[$uk])) continue;
                        $v=esc_url_raw(trim($entry[$uk]));
                        if(!$v || !wp_http_validate_url($v)) continue;
                        $hasImageExtension=(bool)preg_match('/\.(?:jpe?g|png|webp|gif|avif|svg)(?:[?#].*)?$/i',$v);
                        // ET2014A rel is required. Opaque URLs are accepted when rel/type
                        // independently proves "image". Generic page URLs without such
                        // evidence are rejected, regardless of field name.
                        if($explicitImageType || $explicitImageRel || $hasImageExtension){$url=$v;break;}
                    }
                    if(!$url) continue;

                    $hasImageExtension=(bool)preg_match('/\.(?:jpe?g|png|webp|gif|avif|svg)(?:[?#].*)?$/i',$url);
                    if($rel==='download' && !$explicitImageType && !$hasImageExtension) continue;
                    if(!$explicitImageType && !$explicitImageRel && !$hasImageExtension) continue;

                    $prio=is_numeric($entry['prio']??null)?(int)$entry['prio']:9999;
                    $license=''; foreach(array('license','licence','licenseName','licenceName','copyrightLicense') as $lk){if(!empty($entry[$lk])&&is_string($entry[$lk])){$license=$this->event_text($entry[$lk],120);break;}}
                    $artist=''; foreach(array('artist','author','creator','photographer','copyrightHolder') as $ak){if(!empty($entry[$ak])&&is_string($entry[$ak])){$artist=$this->event_text($entry[$ak],190);break;}}
                    $credit=''; foreach(array('credit','copyright','copyrightText','attribution','description') as $ck){if(!empty($entry[$ck])&&is_string($entry[$ck])){$credit=$this->event_text($entry[$ck],500);break;}}
                    $source_url=''; foreach(array('sourceUrl','source_url','website','homepage','pageUrl','page_url') as $sk){if(!empty($entry[$sk])&&is_string($entry[$sk])){$v=esc_url_raw(trim($entry[$sk]));if(wp_http_validate_url($v) && $v!==$url){$source_url=$v;break;}}}
                    if($source_url==='' && !empty($entry['url']) && is_string($entry['url'])){$v=esc_url_raw(trim($entry['url']));if(wp_http_validate_url($v) && $v!==$url)$source_url=$v;}

                    $candidates[]=array(
                        'url'=>$url,'rel'=>$rel,'prio'=>$prio,'license'=>$license,'artist'=>$artist,'credit'=>$credit,'source_url'=>$source_url,
                        '_scope_rank'=>$scopeRank,'_scope'=>$scopeName,'_rel_rank'=>$imageRelRank[$rel]??7
                    );
                }
            }
        };

        // 1) Artwork directly owned by the event always wins.
        $collectPools($raw,0,'event');

        // 2) ET2014A permits media on subitems. These are still part of the
        // event record, unlike venue/location/provider media.
        foreach(array('subitems','subItems','sub_items') as $key){
            if(!array_key_exists($key,$raw)) continue;
            foreach($flattenChildren($raw[$key],array('subitem','subItem','item')) as $child){
                if(is_array($child)) $collectPools($child,1,'subitem');
            }
        }

        // 3) Occurrence-specific media is a valid last event-owned source.
        foreach(array('occurrences','occurrence') as $key){
            if(!array_key_exists($key,$raw)) continue;
            foreach($flattenChildren($raw[$key],array('occurrence','item')) as $child){
                if(is_array($child)) $collectPools($child,2,'occurrence');
            }
        }

        // V1.10.30: ET2014A defines an explicit image field on Address.
        // This image belongs to the SAME ET4 object and is used by destination.one
        // renderings when no top-level media_objects artwork is present. It was
        // previously discarded by our strict parser. Use it only as a fallback and
        // only for event/venue/location/default-style addresses; organizer/contact
        // images are deliberately excluded.
        if(!$candidates){
            $addressRows=$this->event_et4_list($raw['addresses']??array(),'address');
            if(isset($raw['address'])&&is_array($raw['address']))array_unshift($addressRows,$raw['address']);
            $addressCandidates=array();
            foreach($addressRows as $address){
                if(!is_array($address))continue;
                $rel=strtolower(trim((string)($address['rel']??($address['type']??''))));
                if(preg_match('/organizer|organiser|contact|author|support|billing|invoice|provider|publisher|veranstalter/',$rel))continue;
                $image=$address['image']??($address['imageUrl']??($address['image_url']??''));
                if(!is_string($image)||trim($image)==='')continue;
                $url=esc_url_raw(trim($image));
                if(!$url||!wp_http_validate_url($url))continue;
                $rank=in_array($rel,array('event','venue','location','place','main'),true)?0:($rel==='default'||$rel===''?1:2);
                $addressCandidates[]=array(
                    'url'=>$url,'rel'=>'address-image','prio'=>$rank,'license'=>'','artist'=>'','credit'=>'','source_url'=>'',
                    '_scope_rank'=>3,'_scope'=>'address','_rel_rank'=>$rank
                );
            }
            if($addressCandidates){
                usort($addressCandidates,function($a,$b){return ((int)$a['_rel_rank'])<=>((int)$b['_rel_rank']);});
                $winner=$addressCandidates[0];
                unset($winner['_scope_rank'],$winner['_scope'],$winner['_rel_rank']);
                return $winner;
            }
        }

        if(!$candidates) return null;
        usort($candidates,function($a,$b){
            $sa=(int)($a['_scope_rank']??99);$sb=(int)($b['_scope_rank']??99);
            if($sa!==$sb)return $sa<=>$sb;
            $ra=(int)($a['_rel_rank']??99);$rb=(int)($b['_rel_rank']??99);
            if($ra!==$rb)return $ra<=>$rb;
            $pa=(int)($a['prio']??9999);$pb=(int)($b['prio']??9999);
            return $pa<=>$pb;
        });
        $winner=$candidates[0];
        unset($winner['_scope_rank'],$winner['_scope'],$winner['_rel_rank']);
        return $winner;
    }

    private function event_store_authoritative_feed_media_v1022($event_id,$candidate,$source='et4-catalog') {
        global $wpdb;
        $event_id=(int)$event_id;
        if(!$event_id||!is_array($candidate)||empty($candidate['url']))return false;
        $url=esc_url_raw(trim((string)$candidate['url']));
        if(!$url||!wp_http_validate_url($url))return false;
        $media=$this->table('event_media');$events=$this->table('events');$now=current_time('mysql');
        $existing=(int)$wpdb->get_var($wpdb->prepare("SELECT id FROM $media WHERE event_id=%d AND url=%s LIMIT 1",$event_id,$url));
        $data=array(
            'source'=>$this->event_text($source,64),
            'source_url'=>esc_url_raw((string)($candidate['source_url']??($candidate['sourceUrl']??''))),
            'license'=>$this->event_text($candidate['license']??'',120),
            'artist'=>$this->event_text($candidate['artist']??'',190),
            'credit'=>$this->event_text($candidate['credit']??'',1000),
            'identity_confidence'=>1.0,
            'is_primary'=>1,'moderation_status'=>'active','verified_at'=>$now,'last_seen_at'=>$now,
            // ET4 is the licensed authoritative feed. Do not block visitor rendering on
            // a second remote image probe; the normal media-health worker can verify later.
            'health_status'=>'unchecked','health_http_status'=>0,'health_content_type'=>'','health_content_length'=>0,
            'health_checked_at'=>null,'health_error'=>''
        );
        $wpdb->query($wpdb->prepare("UPDATE $media SET is_primary=0 WHERE event_id=%d",$event_id));
        $write=false;
        if($existing){
            $result=$wpdb->update($media,$data,array('id'=>$existing));
            $write=($result!==false);
        }else{
            $data=array_merge(array('event_id'=>$event_id,'media_type'=>'image','url'=>$url),$data);
            $result=$wpdb->insert($media,$data);
            $write=($result!==false && (int)$wpdb->insert_id>0);
        }
        if(!$write)return false;

        // V1.10.33: a successful wpdb call is not sufficient proof for the
        // progress counter. Read the exact event_id+URL back from rg_event_media;
        // only a visitor-eligible, active image is a successful store.
        $persisted=(int)$wpdb->get_var($wpdb->prepare(
            "SELECT id FROM $media WHERE event_id=%d AND url=%s AND media_type='image' AND moderation_status='active' LIMIT 1",
            $event_id,$url
        ));
        if(!$persisted)return false;

        if(in_array($source,array('et4-global-id','et4-feed'),true)){
            $wpdb->query($wpdb->prepare("UPDATE $media SET local_cache_status=CASE WHEN COALESCE(local_path,'')<>'' THEN 'ready' ELSE 'pending' END, local_cache_attempts=CASE WHEN COALESCE(local_path,'')<>'' THEN local_cache_attempts ELSE 0 END, local_cache_error=CASE WHEN COALESCE(local_path,'')<>'' THEN local_cache_error ELSE '' END WHERE id=%d",$persisted));
        }

        $wpdb->query($wpdb->prepare("UPDATE $events SET media_status='verified', enrichment_status=CASE WHEN enrichment_status IN ('checked_no_media','checked_incomplete') THEN 'complete' ELSE enrichment_status END, updated_at=%s WHERE id=%d",$now,$event_id));
        return true;
    }

    private function event_et4_catalog_query_v1022($args,$max_pages=1) {
        if(!function_exists('ruhrpott_guru_et4_fetch_pages'))return array('ok'=>false,'items'=>array(),'pages'=>array(),'error'=>'Theme-ET4-Transport nicht verfuegbar');
        $defaults=array('unique'=>'true');
        return ruhrpott_guru_et4_fetch_pages(array_merge($defaults,(array)$args),max(1,(int)$max_pages),'ruhr-tourismus-open-data',true);
    }

    /**
     * V1.10.31: the ET2014A association is structural, not filename based.
     * A catalog Item owns a required global_id and may own media_objects. The
     * media_object URL therefore belongs to exactly that Item/global_id.
     * Do not title-match, venue-match or borrow another source's artwork here.
     */
    private function event_et4_global_id_v1031($item) {
        if(!is_array($item))return '';
        foreach(array('global_id','globalId') as $k){
            $v=$this->event_text($item[$k]??'',190);
            if($v!=='')return $v;
        }
        return '';
    }

    /**
     * Read the canonical image owned by the SAME ET2014A Item. Item-level
     * media_objects stays first priority. If it is absent, ET2014A address.image
     * may be used only from event/venue/location/default-like addresses of the
     * same object. Organizer/contact/provider address images are excluded; there
     * is no title/venue/cross-source borrowing.
     */
    private function event_et4_primary_media_v1031($item) {
        if(!is_array($item))return null;
        $pool=$item['media_objects']??($item['mediaObjects']??null);
        if(!is_array($pool)||!$pool)return null;
        if(array_key_exists('media_object',$pool))$pool=$pool['media_object'];
        elseif(array_key_exists('mediaObject',$pool))$pool=$pool['mediaObject'];
        if(!is_array($pool)||!$pool)return null;
        $keys=array_keys($pool);$isList=($keys===range(0,count($pool)-1));
        if(!$isList)$pool=array($pool);

        $rank=array(
            'default'=>0,'imagegallery'=>1,'gallery'=>1,'teaser'=>2,'hero'=>2,
            'image'=>2,'photo'=>2,'picture'=>2,'mobile'=>3,'thumbnail'=>4,
            'print'=>5,'summer'=>6,'winter'=>6,'logo'=>8
        );
        $blocked=array('canonical','pages','homepage','website','source','booking','socialmedia','rating','qrcode','video','audio','barrierfree');
        $candidates=array();
        foreach($pool as $m){
            if(!is_array($m))continue;
            $rel=strtolower(trim((string)($m['rel']??'')));
            if($rel===''||in_array($rel,$blocked,true))continue;
            $url='';
            foreach(array('url','contentUrl','content_url','src','imageUrl','image_url','downloadUrl','download_url','href') as $uk){
                if(empty($m[$uk])||!is_string($m[$uk]))continue;
                $u=esc_url_raw(trim($m[$uk]));
                if($u!==''&&wp_http_validate_url($u)){$url=$u;break;}
            }
            if($url==='')continue;
            $type=strtolower(trim((string)($m['type']??($m['mimeType']??($m['contentType']??'')))));
            $imageType=(strpos($type,'image/')===0||in_array($type,array('image','photo','picture'),true));
            $imageRel=array_key_exists($rel,$rank);
            $imageExt=(bool)preg_match('/\.(?:jpe?g|png|webp|gif|avif|svg)(?:[?#].*)?$/i',$url);
            if(!$imageType&&!$imageRel&&!$imageExt)continue;
            if(strpos($type,'video/')===0||strpos($type,'audio/')===0||$type==='application/pdf'||strpos($type,'text/html')===0)continue;
            $prio=is_numeric($m['prio']??null)?(int)$m['prio']:9999;
            $candidates[]=array(
                'url'=>$url,
                'rel'=>$rel,
                'prio'=>$prio,
                'license'=>$this->event_text($m['license']??($m['licence']??''),120),
                'artist'=>$this->event_text($m['artist']??($m['author']??($m['creator']??'')),190),
                'credit'=>$this->event_text($m['credit']??($m['copyright']??($m['source']??'')),1000),
                'source_url'=>'',
                '_rank'=>$rank[$rel]??7
            );
        }
        if(!$candidates){
            $addressRows=$this->event_et4_list($item['addresses']??array(),'address');
            if(isset($item['address'])&&is_array($item['address']))array_unshift($addressRows,$item['address']);
            $addressCandidates=array();
            foreach($addressRows as $address){
                if(!is_array($address))continue;
                $rel=strtolower(trim((string)($address['rel']??($address['type']??''))));
                if(preg_match('/organizer|organiser|contact|author|support|billing|invoice|provider|publisher|veranstalter/',$rel))continue;
                $image=$address['image']??($address['imageUrl']??($address['image_url']??''));
                if(!is_string($image)||trim($image)==='')continue;
                $url=esc_url_raw(trim($image));
                if(!$url||!wp_http_validate_url($url))continue;
                $rankAddress=in_array($rel,array('event','venue','location','place','main'),true)?0:($rel==='default'||$rel===''?1:2);
                $addressCandidates[]=array(
                    'url'=>$url,'rel'=>'address-image','prio'=>$rankAddress,'license'=>'','artist'=>'','credit'=>'','source_url'=>'','_rank'=>$rankAddress
                );
            }
            if($addressCandidates)$candidates=$addressCandidates;
        }
        if(!$candidates)return null;
        usort($candidates,function($a,$b){
            $r=((int)$a['_rank'])<=>((int)$b['_rank']);
            if($r!==0)return $r;
            $r=((int)$a['prio'])<=>((int)$b['prio']);
            if($r!==0)return $r;
            return strcmp((string)$a['url'],(string)$b['url']);
        });
        $out=$candidates[0];unset($out['_rank']);$out['global_id']=$this->event_et4_global_id_v1031($item);return $out;
    }

    private function event_catalog_candidate_rows_v1024($entries) {
        global $wpdb;$events=$this->table('events');
        $masterToken=$this->event_latest_master_token();
        if($masterToken==='')return array();
        $ids=array();
