            $gid=$this->event_text($e['global_id']??'',190);
            if($gid!=='')$ids[$gid]=1;
        }
        if(!$ids)return array();
        $all=array();$seen=array();
        foreach(array_chunk(array_keys($ids),80) as $chunk){
            $placeholders=implode(',',array_fill(0,count($chunk),'%s'));
            $args=array_merge(array($masterToken),$chunk);
            // Concrete v1.10.24-v1.10.30 defect: this used source='open_data_finder'
            // only. Accept both canonical labels used by the master ingest, but still
            // require the current master token and exact external_id/global_id.
            $sql=$wpdb->prepare("SELECT id,external_id,source,title,city,venue_name,postcode,lat,lng,start_at,end_at,status,raw_payload,last_master_run FROM $events WHERE last_master_run=%s AND source IN ('open_data_finder','et4') AND external_id IN ($placeholders) AND status='active'",...$args);
            foreach((array)$wpdb->get_results($sql,ARRAY_A) as $row){
                $eid=(int)($row['id']??0);if($eid&&!isset($seen[$eid])){$seen[$eid]=1;$all[]=$row;}
            }
        }
        return $all;
    }

    private function event_catalog_reconcile_items_v1024($items,$targetEventIds=array()) {
        $entries=array();$with=0;
        foreach((array)$items as $item){
            if(!is_array($item))continue;
            $gid=$this->event_et4_global_id_v1031($item);if($gid==='')continue;
            $candidate=$this->event_et4_primary_media_v1031($item);if(!$candidate||empty($candidate['url']))continue;
            $with++;$entries[$gid]=array('global_id'=>$gid,'candidate'=>$candidate);
        }
        if(!$entries)return array('with_image'=>$with,'catalog_series'=>0,'matched_series'=>0,'matched_occurrences'=>0,'stored'=>0,'unmatched_series'=>0,'ambiguous'=>0,'event_ids'=>array());

        $rows=$this->event_catalog_candidate_rows_v1024(array_values($entries));
        $byId=array();
        foreach($rows as $row){
            $ext=trim((string)($row['external_id']??''));if($ext!=='')$byId[$ext][]=$row;
        }
        $target=array();foreach((array)$targetEventIds as $id)$target[(int)$id]=1;
        $matchedSeries=0;$matchedOccurrences=0;$stored=0;$unmatched=0;$storedIds=array();
        foreach($entries as $gid=>$entry){
            $matches=array();
            foreach((array)($byId[$gid]??array()) as $row){
                $eid=(int)($row['id']??0);if(!$eid)continue;if($target&&!isset($target[$eid]))continue;$matches[]=$row;
            }
            if(!$matches){$unmatched++;continue;}
            $matchedSeries++;
            foreach($matches as $row){
                $eid=(int)$row['id'];$matchedOccurrences++;
                if($this->event_store_authoritative_feed_media_v1022($eid,$entry['candidate'],'et4-global-id')){$stored++;$storedIds[$eid]=1;}
            }
        }
        // 'ambiguous' is intentionally always zero: exact global_id matching has
        // no title/location ambiguity. A non-matching ID remains unmatched.
        return array('with_image'=>$with,'catalog_series'=>count($entries),'matched_series'=>$matchedSeries,'matched_occurrences'=>$matchedOccurrences,'stored'=>$stored,'unmatched_series'=>$unmatched,'ambiguous'=>0,'event_ids'=>array_keys($storedIds));
    }

