        return array();
    }

    public function ensure_event_raw_feed_media_backfill_v1028() {
        if(get_option(self::EVENT_RAW_MEDIA_DONE))return;
        $state=get_option(self::EVENT_RAW_MEDIA_STATE,array());if(!is_array($state))$state=array();
        $status=(string)($state['status']??'');
        if(!in_array($status,array('running','waiting_supplemental','running_final'),true)){
            $state=array('status'=>'running','pass'=>1,'last_id'=>0,'scanned'=>0,'with_image'=>0,'stored'=>0,'errors'=>0,'started_at'=>current_time('mysql'),'last_batch_at'=>'','finished_at'=>'','last_error'=>'');
            update_option(self::EVENT_RAW_MEDIA_STATE,$state,false);
        }
        if(!wp_next_scheduled(self::EVENT_RAW_MEDIA_HOOK)){
            wp_schedule_single_event(time()+1,self::EVENT_RAW_MEDIA_HOOK);
            if(function_exists('spawn_cron'))spawn_cron();
        }
    }

    public function cron_events_raw_feed_media_backfill_v1028() {
        if(get_option(self::EVENT_RAW_MEDIA_DONE))return;
        $lock='rg_events_raw_feed_media_lock_v1028';$held=(int)get_option($lock,0);
        if($held&&$held>=time()-180)return;update_option($lock,time(),false);
        try{
            global $wpdb;$events=$this->table('events');
            $state=get_option(self::EVENT_RAW_MEDIA_STATE,array());if(!is_array($state))$state=array();
            $status=(string)($state['status']??'running');

            if($status==='waiting_supplemental'){
                $supp=get_option('rg_events_supplemental_state',array());if(!is_array($supp))$supp=array();
                if(($supp['status']??'')==='running'){
                    $state['last_batch_at']=current_time('mysql');$state['wait_reason']='Supplemental-Worker noch aktiv';
                    update_option(self::EVENT_RAW_MEDIA_STATE,$state,false);
                    wp_clear_scheduled_hook(self::EVENT_RAW_MEDIA_HOOK);wp_schedule_single_event(time()+90,self::EVENT_RAW_MEDIA_HOOK);return;
                }
                $state['status']='running_final';$state['pass']=2;$state['last_id']=0;$state['wait_reason']='';
                update_option(self::EVENT_RAW_MEDIA_STATE,$state,false);
            }

            $last=max(0,(int)($state['last_id']??0));
            $rows=(array)$wpdb->get_results($wpdb->prepare(
                "SELECT id,raw_payload,source FROM $events WHERE id>%d AND status='active' AND source IN ('open_data_finder','destination_one_open_data','et4') ORDER BY id ASC LIMIT 250",
                $last
            ),ARRAY_A);
            if(!$rows){
                $supp=get_option('rg_events_supplemental_state',array());if(!is_array($supp))$supp=array();
                if((int)($state['pass']??1)===1 && ($supp['status']??'')==='running'){
                    $state['status']='waiting_supplemental';$state['last_batch_at']=current_time('mysql');$state['wait_reason']='Warte auf Abschluss des laufenden Rich-Supplemental-Laufs';
                    update_option(self::EVENT_RAW_MEDIA_STATE,$state,false);
                    wp_clear_scheduled_hook(self::EVENT_RAW_MEDIA_HOOK);wp_schedule_single_event(time()+90,self::EVENT_RAW_MEDIA_HOOK);return;
                }
                $state['status']='finished';$state['finished_at']=current_time('mysql');$state['last_batch_at']=current_time('mysql');$state['wait_reason']='';
                update_option(self::EVENT_RAW_MEDIA_STATE,$state,false);update_option(self::EVENT_RAW_MEDIA_DONE,$state['finished_at'],false);wp_clear_scheduled_hook(self::EVENT_RAW_MEDIA_HOOK);return;
            }

            foreach($rows as $row){
                $eid=(int)($row['id']??0);if($eid>$last)$last=$eid;$state['scanned']=(int)($state['scanned']??0)+1;
                $raw=json_decode((string)($row['raw_payload']??''),true);if(!is_array($raw))continue;
                try{
                    $candidate=$this->event_feed_media_candidate($raw);
                    if(!$candidate||empty($candidate['url']))continue;
                    $state['with_image']=(int)($state['with_image']??0)+1;
                    if($this->event_store_authoritative_feed_media_v1022($eid,$candidate,'et4-feed'))$state['stored']=(int)($state['stored']??0)+1;
                }catch(Throwable $e){$state['errors']=(int)($state['errors']??0)+1;$state['last_error']=$this->event_text($e->getMessage(),1000);}
            }
            $state['last_id']=$last;$state['last_batch_at']=current_time('mysql');$state['status']=((int)($state['pass']??1)===2)?'running_final':'running';
            update_option(self::EVENT_RAW_MEDIA_STATE,$state,false);
            // v1.10.41: any newly recovered et4-feed image must enter the local cache
            // without depending on a visitor page load.
            delete_option('rg_events_et4_local_media_last_idle_check_v1039');$this->ensure_event_local_media_cache_v1039();
            wp_clear_scheduled_hook(self::EVENT_RAW_MEDIA_HOOK);wp_schedule_single_event(time()+2,self::EVENT_RAW_MEDIA_HOOK);if(function_exists('spawn_cron'))spawn_cron();
        }finally{delete_option($lock);}
    }

    private function maybe_bootstrap_et4_local_media_v1039() {
        if(get_option('rg_events_et4_local_media_v1039_bootstrapped'))return;
        // One authoritative catalog refresh is required so any rotating ET4 image
        // URL/hash is current before the localizer finishes the migration.
        delete_option(self::EVENT_CATALOG_MEDIA_DONE);delete_option(self::EVENT_CATALOG_MEDIA_STATE);wp_clear_scheduled_hook(self::EVENT_CATALOG_MEDIA_HOOK);
        delete_option(self::EVENT_LOCAL_MEDIA_STATE);wp_clear_scheduled_hook(self::EVENT_LOCAL_MEDIA_HOOK);
