    }

    private function maybe_bootstrap_destination_one_local_media_v1041() {
        if(get_option('rg_events_destination_one_local_media_v1041_bootstrapped'))return;
        // v1.10.40 localized only licensed master rows. Existing rich supplemental
        // media rows are already exact same-object matches (global_id + et4-feed),
        // so only the local-cache queue must be reopened; no reimport is required.
        delete_option(self::EVENT_LOCAL_MEDIA_STATE);
        delete_option('rg_events_et4_local_media_last_idle_check_v1039');
        wp_clear_scheduled_hook(self::EVENT_LOCAL_MEDIA_HOOK);
        update_option('rg_events_destination_one_local_media_v1041_bootstrapped',current_time('mysql'),false);
    }

    private function event_local_media_pending_targets_v1041($limit=6) {
        global $wpdb;$events=$this->table('events');$media=$this->table('event_media');$master=$this->event_latest_master_token();
        $limit=max(1,min(12,(int)$limit));$out=array();$seen=array();

        // Source owner 1: current licensed Open Data Finder / ET4 master.
        if($master!==''){
            $sql=$wpdb->prepare(
                "SELECT e.external_id,MIN(COALESCE(m.local_cache_attempts,0)) AS attempts,MIN(e.start_at) AS next_start
                 FROM $events e INNER JOIN $media m ON m.event_id=e.id
                 WHERE e.last_master_run=%s AND e.source IN ('open_data_finder','et4') AND e.status='active'
                   AND e.external_id<>'' AND m.media_type='image' AND m.source='et4-global-id' AND m.moderation_status='active'
                   AND (COALESCE(m.local_cache_status,'pending')<>'ready' OR COALESCE(m.local_path,'')='')
                   AND COALESCE(m.local_cache_attempts,0)<3
                 GROUP BY e.external_id ORDER BY attempts ASC,next_start ASC,e.external_id ASC LIMIT %d",
                $master,$limit
            );
            foreach((array)$wpdb->get_col($sql) as $gid){$gid=trim((string)$gid);if($gid===''||isset($seen[$gid]))continue;$seen[$gid]=1;$out[]=array('global_id'=>$gid,'owner'=>'master');}
        }

        // Source owner 2: public destination.one rich supplemental feed. These images
        // were already persisted from the SAME unique ET2014A object as source=et4-feed.
        // Never localize a supplemental duplicate when the current master owns that global_id.
        $remaining=$limit-count($out);
        if($remaining>0){
            if($master!==''){
                $sql=$wpdb->prepare(
                    "SELECT e.external_id,MIN(COALESCE(m.local_cache_attempts,0)) AS attempts,MIN(e.start_at) AS next_start
                     FROM $events e INNER JOIN $media m ON m.event_id=e.id
                     WHERE e.source='destination_one_open_data' AND e.status='active' AND e.external_id<>''
                       AND m.media_type='image' AND m.source='et4-feed' AND m.moderation_status='active'
                       AND (COALESCE(m.local_cache_status,'pending')<>'ready' OR COALESCE(m.local_path,'')='')
                       AND COALESCE(m.local_cache_attempts,0)<3
                       AND NOT EXISTS (SELECT 1 FROM $events mo WHERE mo.last_master_run=%s AND mo.source IN ('open_data_finder','et4') AND mo.status='active' AND mo.external_id=e.external_id)
                     GROUP BY e.external_id ORDER BY attempts ASC,next_start ASC,e.external_id ASC LIMIT %d",
                    $master,$remaining
                );
            }else{
                $sql=$wpdb->prepare(
                    "SELECT e.external_id,MIN(COALESCE(m.local_cache_attempts,0)) AS attempts,MIN(e.start_at) AS next_start
                     FROM $events e INNER JOIN $media m ON m.event_id=e.id
                     WHERE e.source='destination_one_open_data' AND e.status='active' AND e.external_id<>''
                       AND m.media_type='image' AND m.source='et4-feed' AND m.moderation_status='active'
                       AND (COALESCE(m.local_cache_status,'pending')<>'ready' OR COALESCE(m.local_path,'')='')
                       AND COALESCE(m.local_cache_attempts,0)<3
                     GROUP BY e.external_id ORDER BY attempts ASC,next_start ASC,e.external_id ASC LIMIT %d",
                    $remaining
                );
            }
            foreach((array)$wpdb->get_col($sql) as $gid){$gid=trim((string)$gid);if($gid===''||isset($seen[$gid]))continue;$seen[$gid]=1;$out[]=array('global_id'=>$gid,'owner'=>'supplemental');}
        }
        return $out;
    }

    private function event_local_media_row_for_target_v1041($global_id,$owner) {
        global $wpdb;$events=$this->table('events');$media=$this->table('event_media');$master=$this->event_latest_master_token();$global_id=trim((string)$global_id);
        if($global_id==='')return null;
        if($owner==='master'){
            if($master==='')return null;
            $row=$wpdb->get_row($wpdb->prepare(
                "SELECT m.*,e.external_id,'master' AS _owner_source FROM $events e INNER JOIN $media m ON m.event_id=e.id
                 WHERE e.last_master_run=%s AND e.source IN ('open_data_finder','et4') AND e.status='active' AND e.external_id=%s
                   AND m.media_type='image' AND m.source='et4-global-id' AND m.moderation_status='active'
                 ORDER BY m.is_primary DESC,m.verified_at DESC,m.id DESC LIMIT 1",
                $master,$global_id
            ),ARRAY_A);
            return is_array($row)?$row:null;
        }
        $row=$wpdb->get_row($wpdb->prepare(
            "SELECT m.*,e.external_id,'supplemental' AS _owner_source FROM $events e INNER JOIN $media m ON m.event_id=e.id
             WHERE e.source='destination_one_open_data' AND e.status='active' AND e.external_id=%s
               AND m.media_type='image' AND m.source='et4-feed' AND m.moderation_status='active'
             ORDER BY e.last_synced_at DESC,m.is_primary DESC,m.verified_at DESC,m.id DESC LIMIT 1",
            $global_id
        ),ARRAY_A);
        return is_array($row)?$row:null;
    }

