                "UPDATE $media m INNER JOIN $events e ON e.id=m.event_id
                 SET m.local_path=%s,m.local_mime=%s,m.local_bytes=%d,m.local_content_hash=%s,m.local_cached_at=%s,m.local_cache_status='ready',m.local_cache_error=''
                 WHERE e.last_master_run=%s AND e.source IN ('open_data_finder','et4') AND e.status='active' AND e.external_id=%s
                   AND m.media_type='image' AND m.source='et4-global-id' AND m.moderation_status='active'",
                (string)$local['local_path'],(string)$local['local_mime'],(int)$local['local_bytes'],(string)$local['local_content_hash'],(string)($local['local_cached_at']?:$now),$master,$global_id
            );
        }else{
            $sql=$wpdb->prepare(
                "UPDATE $media m INNER JOIN $events e ON e.id=m.event_id
                 SET m.local_path=%s,m.local_mime=%s,m.local_bytes=%d,m.local_content_hash=%s,m.local_cached_at=%s,m.local_cache_status='ready',m.local_cache_error=''
                 WHERE e.source='destination_one_open_data' AND e.status='active' AND e.external_id=%s
                   AND m.media_type='image' AND m.source='et4-feed' AND m.moderation_status='active'",
                (string)$local['local_path'],(string)$local['local_mime'],(int)$local['local_bytes'],(string)$local['local_content_hash'],(string)($local['local_cached_at']?:$now),$global_id
            );
