                 WHERE e.last_master_run=%s AND e.source IN ('open_data_finder','et4') AND e.status='active' AND e.external_id=%s
                   AND m.media_type='image' AND m.source='et4-global-id' AND m.moderation_status='active' AND COALESCE(m.local_path,'')=''",
                $message,$master,$global_id
            );
        }else{
