                "UPDATE $media m INNER JOIN $events e ON e.id=m.event_id
                 SET m.local_cache_attempts=LEAST(3,COALESCE(m.local_cache_attempts,0)+1),m.local_cache_status=CASE WHEN COALESCE(m.local_cache_attempts,0)+1>=3 THEN 'failed' ELSE 'retry' END,m.local_cache_error=%s
                 WHERE e.source='destination_one_open_data' AND e.status='active' AND e.external_id=%s
                   AND m.media_type='image' AND m.source='et4-feed' AND m.moderation_status='active' AND COALESCE(m.local_path,'')=''",
