    public function ensure_event_local_media_cache_v1039() {
        if(wp_next_scheduled(self::EVENT_LOCAL_MEDIA_HOOK))return;
        $last=(int)get_option('rg_events_et4_local_media_last_idle_check_v1039',0);if($last&&$last>time()-300)return;
        $pending=$this->event_local_media_pending_targets_v1041(1);
        if(!$pending){update_option('rg_events_et4_local_media_last_idle_check_v1039',time(),false);return;}
        wp_schedule_single_event(time()+2,self::EVENT_LOCAL_MEDIA_HOOK);if(function_exists('spawn_cron'))spawn_cron();
    }

    public function cron_events_et4_local_media_cache_v1039() {
        $held=(int)get_option(self::EVENT_LOCAL_MEDIA_LOCK,0);if($held&&$held>=time()-240)return;update_option(self::EVENT_LOCAL_MEDIA_LOCK,time(),false);
        try{
            $state=get_option(self::EVENT_LOCAL_MEDIA_STATE,array());if(!is_array($state))$state=array();
            if(empty($state['started_at']))$state['started_at']=current_time('mysql');
            $state['status']='running';$state['last_batch_at']=current_time('mysql');$state['last_error']='';
            $targets=$this->event_local_media_pending_targets_v1041(4);
            if(!$targets){$state['status']='idle';$state['finished_at']=current_time('mysql');update_option(self::EVENT_LOCAL_MEDIA_STATE,$state,false);update_option('rg_events_et4_local_media_last_idle_check_v1039',time(),false);wp_clear_scheduled_hook(self::EVENT_LOCAL_MEDIA_HOOK);return;}
            foreach($targets as $target){
                $gid=trim((string)($target['global_id']??''));$owner=(string)($target['owner']??'master');if($gid==='')continue;
                $state['series_seen']=(int)($state['series_seen']??0)+1;$state[$owner.'_seen']=(int)($state[$owner.'_seen']??0)+1;$row=$this->event_local_media_row_for_target_v1041($gid,$owner);
                if(!$row||empty($row['url'])){$state['failed']=(int)($state['failed']??0)+1;$this->event_local_media_fail_target_v1041($gid,'Keine aktuelle ET4-Medienzeile gefunden',$owner);continue;}
                $local=$this->event_local_media_download_v1039($gid,(string)$row['url']);
                if(is_wp_error($local)){$msg=$local->get_error_message();$state['failed']=(int)($state['failed']??0)+1;$state['last_error']=$this->event_text($gid.': '.$msg,1000);$this->event_local_media_fail_target_v1041($gid,$msg,$owner);continue;}
                $changed=$this->event_local_media_propagate_target_v1041($gid,$local,$owner);$state['localized']=(int)($state['localized']??0)+1;$state[$owner.'_localized']=(int)($state[$owner.'_localized']??0)+1;$state['rows_updated']=(int)($state['rows_updated']??0)+$changed;if(($local['cache']??'')==='hit')$state['cache_hits']=(int)($state['cache_hits']??0)+1;else $state['downloads']=(int)($state['downloads']??0)+1;
            }
            update_option(self::EVENT_LOCAL_MEDIA_STATE,$state,false);wp_clear_scheduled_hook(self::EVENT_LOCAL_MEDIA_HOOK);wp_schedule_single_event(time()+3,self::EVENT_LOCAL_MEDIA_HOOK);if(function_exists('spawn_cron'))spawn_cron();
        }finally{delete_option(self::EVENT_LOCAL_MEDIA_LOCK);}
    }

    public function ensure_et4_catalog_media_backfill_v1022() {
        // V1.10.31: force exactly one clean rerun with the new global_id ->
        // media_objects binding. A prior v1.10.24-v1.10.30 'done' flag only proves
        // that the old title/source-restricted reconciler finished, not that exact
        // master IDs received their artwork. This reset touches only this media
        // backfill; event/opening-hours audits and master/supplemental states remain.
        if(!get_option('rg_events_et4_catalog_media_v1033_verified_store_cleanup')){
            delete_option(self::EVENT_CATALOG_MEDIA_DONE);
            delete_option(self::EVENT_CATALOG_MEDIA_STATE);
            wp_clear_scheduled_hook(self::EVENT_CATALOG_MEDIA_HOOK);
            update_option('rg_events_et4_catalog_media_v1033_verified_store_cleanup',current_time('mysql'),false);
        }
        // v1.10.24 intentionally starts from a fresh state; older hashlink/global-id
        // attempts are not considered proof that catalog media was reconciled.
        if(!get_option('rg_events_et4_catalog_media_v1024_cleanup')){
            foreach(array('rg_events_et4_catalog_media_backfill_v1022','rg_events_et4_catalog_media_backfill_v1023') as $oldHook)wp_clear_scheduled_hook($oldHook);
            delete_option('rg_events_et4_catalog_media_done_v1022');delete_option('rg_events_et4_catalog_media_done_v1023');
            update_option('rg_events_et4_catalog_media_v1024_cleanup',1,false);
        }
        if(get_option(self::EVENT_CATALOG_MEDIA_DONE))return;
        $state=get_option(self::EVENT_CATALOG_MEDIA_STATE,array());if(!is_array($state))$state=array();
        if(($state['status']??'')!=='running'){
            $state=array('status'=>'running','mode'=>'exact-global-id-v1031','offset'=>0,'catalog_seen'=>0,'with_image'=>0,'catalog_series'=>0,'matched_series'=>0,'matched_occurrences'=>0,'stored'=>0,'unmatched_series'=>0,'ambiguous'=>0,'errors'=>0,'started_at'=>current_time('mysql'),'last_error'=>'');
            update_option(self::EVENT_CATALOG_MEDIA_STATE,$state,false);
        }
        if(!wp_next_scheduled(self::EVENT_CATALOG_MEDIA_HOOK)){wp_schedule_single_event(time()+1,self::EVENT_CATALOG_MEDIA_HOOK);if(function_exists('spawn_cron'))spawn_cron();}
    }

    public function cron_events_et4_catalog_media_backfill_v1022() {
        if(get_option(self::EVENT_CATALOG_MEDIA_DONE))return;
        $lock='rg_events_et4_catalog_media_lock_v1024';$held=(int)get_option($lock,0);if($held&&$held>=time()-240)return;update_option($lock,time(),false);
        try{
            $state=get_option(self::EVENT_CATALOG_MEDIA_STATE,array());if(!is_array($state))$state=array();$offset=max(0,(int)($state['offset']??0));
            $today=new DateTimeImmutable('today',wp_timezone());$until=$today->modify('+365 days');
            // This is the authoritative rich ET2014A catalog representation. It is
