    private function event_media_health_probe($url) {
        $url=esc_url_raw((string)$url);
        if(!$url || !wp_http_validate_url($url)) return array('ok'=>false,'status'=>'invalid','http'=>0,'content_type'=>'','content_length'=>0,'error'=>'Ungültige URL');
        $args=array(
            'timeout'=>8,
            'redirection'=>4,
            'user-agent'=>'RuhrpottGuru/1.7.1 EventMediaHealth',
            'headers'=>array('Accept'=>'image/avif,image/webp,image/apng,image/svg+xml,image/*,*/*;q=0.8','Range'=>'bytes=0-65535'),
            'limit_response_size'=>65536,
        );
        $res=wp_remote_get($url,$args);
        if(is_wp_error($res)) return array('ok'=>false,'status'=>'unreachable','http'=>0,'content_type'=>'','content_length'=>0,'error'=>$res->get_error_message());
        $code=(int)wp_remote_retrieve_response_code($res);
        $ct=strtolower(trim((string)wp_remote_retrieve_header($res,'content-type')));
        if(strpos($ct,';')!==false)$ct=trim(strtok($ct,';'));
        $len_header=(int)wp_remote_retrieve_header($res,'content-length');
        $body=(string)wp_remote_retrieve_body($res);$body_len=strlen($body);$len=max($len_header,$body_len);
        if($code<200 || $code>=400) return array('ok'=>false,'status'=>'http_error','http'=>$code,'content_type'=>$ct,'content_length'=>$len,'error'=>'HTTP '.$code);
        if(strpos($ct,'image/')!==0) return array('ok'=>false,'status'=>'not_image','http'=>$code,'content_type'=>$ct,'content_length'=>$len,'error'=>'Content-Type ist kein Bild: '.($ct?:'unbekannt'));
        if($body_len>0 && $body_len<512) return array('ok'=>false,'status'=>'too_small','http'=>$code,'content_type'=>$ct,'content_length'=>$len,'error'=>'Bildantwort ungewöhnlich klein');
        return array('ok'=>true,'status'=>'healthy','http'=>$code,'content_type'=>$ct,'content_length'=>$len,'error'=>'');
    }

    private function event_update_media_health($media_id,$probe) {
        global $wpdb;$media=$this->table('event_media');$now=current_time('mysql');
        $wpdb->update($media,array(
            'health_status'=>$this->event_text($probe['status']??'invalid',24),
            'health_http_status'=>(int)($probe['http']??0),
            'health_content_type'=>$this->event_text($probe['content_type']??'',120),
            'health_content_length'=>(int)($probe['content_length']??0),
            'health_checked_at'=>$now,
            'health_error'=>$this->event_text($probe['error']??'',1000),
            'last_seen_at'=>$now,
        ),array('id'=>(int)$media_id));
    }

    private function event_recalculate_media_status($event_id) {
        global $wpdb;$media=$this->table('event_media');$events=$this->table('events');$now=current_time('mysql');
        $healthy=(int)$wpdb->get_var($wpdb->prepare("SELECT COUNT(*) FROM $media WHERE event_id=%d AND media_type='image' AND moderation_status='active' AND health_status='healthy'",(int)$event_id));
        $wpdb->update($events,array('media_status'=>$healthy>0?'verified':'pending','updated_at'=>$now),array('id'=>(int)$event_id));
        return $healthy>0;
    }

    private function event_media_health_check_batch($limit=60) {
        global $wpdb;$media=$this->table('event_media');$limit=max(1,min(250,(int)$limit));
        $rows=(array)$wpdb->get_results("SELECT * FROM $media WHERE media_type='image' AND moderation_status='active' ORDER BY CASE WHEN health_status='unchecked' THEN 0 ELSE 1 END, health_checked_at ASC, id ASC LIMIT ".intval($limit),ARRAY_A);
        $stats=array('checked'=>0,'healthy'=>0,'invalid'=>0,'events'=>array());
        foreach($rows as $m){$probe=$this->event_media_health_probe($m['url']);$this->event_update_media_health((int)$m['id'],$probe);$stats['checked']++;if(!empty($probe['ok']))$stats['healthy']++;else$stats['invalid']++;$stats['events'][(int)$m['event_id']]=1;}
        foreach(array_keys($stats['events']) as $eid)$this->event_recalculate_media_status($eid);
        $stats['events']=count($stats['events']);$stats['at']=current_time('mysql');update_option('rg_events_media_health_state',$stats,false);return $stats;
    }

    public function admin_events_media_health() {
        if(!current_user_can('manage_options'))wp_die('Keine Berechtigung.');check_admin_referer('rg_events_media_health');
        $stats=$this->event_media_health_check_batch(100);
        $msg=sprintf('Media-Health-Check: %d Bilder geprüft · %d erreichbar · %d ungültig/blockiert.',(int)$stats['checked'],(int)$stats['healthy'],(int)$stats['invalid']);
        wp_safe_redirect(add_query_arg(array('page'=>'rp-events','rg_event_notice'=>rawurlencode($msg)),admin_url('admin.php')));exit;
    }

    private function event_store_verified_media($event_id,$candidate,$source='event-feed',$confidence=1.0) {
        global $wpdb; if(!$event_id||!is_array($candidate)||empty($candidate['url']))return false;
        $url=esc_url_raw((string)$candidate['url']); if(!$url||!wp_http_validate_url($url))return false; $probe=$this->event_media_health_probe($url); if(empty($probe['ok']))return false;
        $media=$this->table('event_media');$events=$this->table('events');$now=current_time('mysql');
        $existing=(int)$wpdb->get_var($wpdb->prepare("SELECT id FROM $media WHERE event_id=%d AND url=%s LIMIT 1",$event_id,$url));
        $data=array(
            'source'=>$this->event_text($source,64),
            'source_url'=>esc_url_raw((string)($candidate['source_url']??($candidate['sourceUrl']??''))),
            'license'=>$this->event_text($candidate['license']??'',120),
            'artist'=>$this->event_text($candidate['artist']??'',190),
            'credit'=>$this->event_text($candidate['credit']??'',1000),
            'identity_confidence'=>max(0,min(1,(float)$confidence)),
            'is_primary'=>1,'moderation_status'=>'active','verified_at'=>$now,'last_seen_at'=>$now,'health_status'=>'healthy','health_http_status'=>(int)$probe['http'],'health_content_type'=>$this->event_text($probe['content_type'],120),'health_content_length'=>(int)$probe['content_length'],'health_checked_at'=>$now,'health_error'=>''
        );
        $wpdb->query($wpdb->prepare("UPDATE $media SET is_primary=0 WHERE event_id=%d",$event_id));
        if($existing)$wpdb->update($media,$data,array('id'=>$existing));else{$data=array_merge(array('event_id'=>$event_id,'media_type'=>'image','url'=>$url),$data);$wpdb->insert($media,$data);}
        $wpdb->update($events,array('media_status'=>'verified','updated_at'=>$now),array('id'=>$event_id));
        return true;
    }

