        if($email==='')return '';
        $title=$this->event_text($event['title']??'Veranstaltung',220);$source=esc_url_raw((string)($media['source_url']??''));$image=esc_url_raw((string)($media['url']??''));
        $subject='Bildfreigabe für „'.$title.'“ auf RuhrpottGuru';
        $body="Guten Tag,\n\nfür den regionalen Freizeitguide RuhrpottGuru möchten wir die Veranstaltung „{$title}“ darstellen. Auf Ihrer offiziellen Veranstaltungsseite wurde folgendes Bild gefunden:\n{$image}\n";
        if($source!=='')$body.="\nQuelle: {$source}\n";
        $body.="\nDürfen wir dieses Bild für die Darstellung der Veranstaltung auf ruhrpottguru.de und in unserer eigenen Social-Media-Kommunikation zum Event verwenden? Bitte teilen Sie uns – falls erforderlich – auch Fotograf/Urheber, gewünschten Credit und die konkrete Nutzungsgrundlage mit.\n\nVielen Dank und viele Grüße\nRuhrpottGuru";
