    private function event_best_nested_address($raw) {
        if(!is_array($raw))return null;$best=null;$bestScore=-999;
        $walk=function($node,$path='',$depth=0) use (&$walk,&$best,&$bestScore){
            if($depth>7||!is_array($node))return;
            $pathNorm=strtolower($path);
            $street='';foreach(array('street','streetAddress','strasse','road') as $k){if(isset($node[$k])&&is_scalar($node[$k])){$street=$this->event_text($node[$k],190);if($street!=='')break;}}
            $house='';foreach(array('houseNumber','house_number','housenumber','houseNo') as $k){if(isset($node[$k])&&is_scalar($node[$k])){$house=$this->event_text($node[$k],50);if($house!=='')break;}}
            $zip='';foreach(array('zip','postalCode','postcode','plz') as $k){if(isset($node[$k])&&is_scalar($node[$k])){$zip=$this->event_text($node[$k],20);if($zip!=='')break;}}
            $city='';foreach(array('city','addressLocality','locality','ort','town') as $k){if(isset($node[$k])&&is_scalar($node[$k])){$city=$this->event_text($node[$k],120);if($city!=='')break;}}
            if($house===''&&$street!==''&&preg_match('/^(.*?)[,\\s]+(\\d+[a-zA-Z]?(?:[-\\/]\\d+[a-zA-Z]?)?)$/u',$street,$m)){$street=trim($m[1]);$house=trim($m[2]);}
            if($street!==''||$zip!==''||$city!==''){
                $score=0;if($street!=='')$score+=5;if($house!=='')$score+=2;if($zip!=='')$score+=4;if($city!=='')$score+=4;
                $relNorm=strtolower($this->event_text($node['rel']??($node['type']??''),80));
                if(preg_match('/location|venue|place|event|main|veranstaltungsort/',$pathNorm.' '.$relNorm))$score+=8;
                if(preg_match('/organizer|organiser|organisation|contact|contact_person|author|support|lessor|billing|invoice|provider|publisher|veranstalter/',$pathNorm.' '.$relNorm))$score-=30;
                if($score>$bestScore){$bestScore=$score;$best=array('street'=>$street,'house_number'=>$house,'postcode'=>$zip,'city'=>$city,'path'=>$path,'score'=>$score);}
            }
            foreach($node as $k=>$v)if(is_array($v))$walk($v,$path===''?(string)$k:$path.'.'.$k,$depth+1);
        };
        $walk($raw); return ($best&&$bestScore>0)?$best:null;
    }

