        if($old&&$old>$nowTs-180)return;if($old)delete_option($lock);if(!add_option($lock,$nowTs,'','no'))return;
        try{
            global $wpdb;$events=$this->table('events');$state=get_option(self::EVENT_RICH_FIELDS_STATE,array());if(!is_array($state))$state=array();
            $cursor=(int)($state['cursor']??0);$state['status']='running';if(empty($state['started_at']))$state['started_at']=current_time('mysql');$state['last_at']=current_time('mysql');update_option(self::EVENT_RICH_FIELDS_STATE,$state,false);
            $master=get_option('rg_events_nightly_state',array());$supp=get_option('rg_events_supplemental_state',array());$enrich=get_option('rg_events_enrichment_state',array());
            $busy=(is_array($master)&&($master['status']??'')==='running')||(is_array($supp)&&($supp['status']??'')==='running')||(is_array($enrich)&&($enrich['status']??'')==='running');
            if($busy){$state['status']='waiting_events_sync';$state['wait_reason']='Wartet auf laufenden Event-Sync/Enrichment';$state['last_at']=current_time('mysql');update_option(self::EVENT_RICH_FIELDS_STATE,$state,false);wp_schedule_single_event(time()+60,self::EVENT_RICH_FIELDS_HOOK);return;}
            unset($state['wait_reason']);
            $rows=$wpdb->get_results($wpdb->prepare("SELECT id,raw_payload,address_status,street,house_number,postcode,city,venue_name,ticket_url,description,short_description,price_text,price_json,organizer_json,event_info_json,participants_json FROM $events WHERE id>%d AND source IN ('open_data_finder','destination_one_open_data','et4') ORDER BY id ASC LIMIT 150",$cursor),ARRAY_A);
            if(!$rows){$state['status']='finished';$state['finished_at']=current_time('mysql');update_option(self::EVENT_RICH_FIELDS_STATE,$state,false);update_option(self::EVENT_RICH_FIELDS_DONE,1,false);return;}
            foreach($rows as $row){
                $cursor=(int)$row['id'];$state['processed']=(int)($state['processed']??0)+1;$raw=json_decode((string)($row['raw_payload']??''),true);if(!is_array($raw)){$state['errors']=(int)($state['errors']??0)+1;continue;}
                $upd=array();$desc=$this->event_description_bundle($raw);$price=$this->event_price_bundle($raw,$desc);$org=$this->event_organizers_from_item($raw);$info=$this->event_info_bundle($raw,$desc);$parts=$this->event_participant_entries_from_item($raw);$ticket=$this->event_booking_url_from_item_v1058($raw);$venue=$this->event_venue_name_from_item_v1058($raw);
                $set=function($key,$value) use (&$upd,$row){if((string)($row[$key]??'')!==(string)$value)$upd[$key]=$value;};
                if(!empty($desc['description']))$set('description',$this->event_text($desc['description']));
                if(!empty($desc['short']))$set('short_description',$this->event_text($desc['short'],4000));
                if(!empty($price['text'])||!empty($price['items'])){$set('price_text',$this->event_text($price['text']??'',4000));$set('price_json',wp_json_encode($price,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES));}
                $set('organizer_json',wp_json_encode($org,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES));
                if($info)$set('event_info_json',wp_json_encode($info,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES));
                if($parts)$set('participants_json',wp_json_encode($parts,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES));
                if($ticket!=='')$set('ticket_url',$ticket);
                if(trim((string)($row['venue_name']??''))===''&&$venue!=='')$upd['venue_name']=$venue;
                if(!in_array((string)($row['address_status']??''),array('verified','manual'),true)){
                    list($street,$house,$zip,$city)=$this->event_address_from_item($raw);
                    if(trim((string)($row['street']??''))===''&&$street!=='')$upd['street']=$street;
                    if(trim((string)($row['house_number']??''))===''&&$house!=='')$upd['house_number']=$house;
                    if(trim((string)($row['postcode']??''))===''&&$zip!=='')$upd['postcode']=$zip;
                    if(trim((string)($row['city']??''))===''&&$city!=='')$upd['city']=$city;
                    $finalStreet=(string)($upd['street']??($row['street']??''));$finalZip=(string)($upd['postcode']??($row['postcode']??''));$finalCity=(string)($upd['city']??($row['city']??''));
                    if($finalStreet!==''||$finalZip!==''||$finalCity!=='')$upd['address_status']=($finalStreet!==''&&$finalZip!==''&&$finalCity!=='')?'complete':'partial';
                }
                if($upd){$upd['updated_at']=current_time('mysql');$ok=$wpdb->update($events,$upd,array('id'=>$cursor));if($ok===false)$state['errors']=(int)($state['errors']??0)+1;else $state['updated']=(int)($state['updated']??0)+1;}
            }
            $state['cursor']=$cursor;$state['last_at']=current_time('mysql');update_option(self::EVENT_RICH_FIELDS_STATE,$state,false);
            wp_schedule_single_event(time()+5,self::EVENT_RICH_FIELDS_HOOK);
        } finally { delete_option($lock); }
    }


    private function event_try_symbolic_after_context_reject_v101107($event_id,$row,$raw,&$audit) {
        if(!function_exists('ruhrpott_guru_event_media_pexels_v233'))return false;
        try{
            $symbol=ruhrpott_guru_event_media_pexels_v233(
                (string)($row['title']??''),(string)($row['city']??''),(string)($row['event_category']??''),is_array($raw)?$raw:array()
            );
            if(!is_array($symbol)||empty($symbol['imageUrl'])){$audit[]=array('step'=>'bild_symbol_fallback','status'=>'kein_treffer_nach_ortsbild_filter');return false;}
            $ok=$this->event_store_local_fallback_v1042($event_id,$symbol,'pexels-symbolic-event',(float)($symbol['identityConfidence']??0.0));
            $audit[]=array('step'=>'bild_symbol_fallback','status'=>$ok?'akzeptiert':'abgelehnt_oder_speichern_fehlgeschlagen','sourceUrl'=>$symbol['sourceUrl']??'','label'=>$symbol['mediaLabel']??'Symbolfoto');
            return (bool)$ok;
        }catch(Throwable $e){
            $audit[]=array('step'=>'bild_symbol_fallback','status'=>'fehler','grund'=>$e->getMessage());return false;
        }
    }

    private function event_enrich_one($event_id) {
        global $wpdb;$events=$this->table('events');$enr=$this->table('event_enrichment');$row=$wpdb->get_row($wpdb->prepare("SELECT * FROM $events WHERE id=%d",$event_id),ARRAY_A);if(!$row)return array('ok'=>false,'error'=>'Event fehlt');
        $raw=json_decode((string)$row['raw_payload'],true);if(!is_array($raw))$raw=array();$now=current_time('mysql');$addressChanged=false;$mediaOk=$this->event_has_live_local_media_v1042($event_id);$errors=array();$audit=array();
        $participants=$this->event_participant_entries_from_item($raw);
        if($participants){$wpdb->update($events,array('participants_json'=>wp_json_encode($participants,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES),'updated_at'=>$now),array('id'=>$event_id));$audit[]=array('step'=>'mitwirkende','status'=>'gefunden','count'=>count($participants));}else{$audit[]=array('step'=>'mitwirkende','status'=>'keine_strukturierten_daten');}
        $addr=$this->event_best_nested_address($raw);
        if($addr){$upd=array();foreach(array('street','house_number','postcode','city') as $k){if(trim((string)$row[$k])===''&&!empty($addr[$k])){$upd[$k]=$addr[$k];$row[$k]=$addr[$k];$addressChanged=true;}}if($upd){$complete=$row['street']!==''&&$row['postcode']!==''&&$row['city']!=='';$upd['address_status']=$complete?'verified':'partial';$upd['updated_at']=$now;$wpdb->update($events,$upd,array('id'=>$event_id));}$audit[]=array('step'=>'adresse_feed','status'=>$upd?'ergänzt':'bereits_vorhanden');}else{$audit[]=array('step'=>'adresse_feed','status'=>'nicht_gefunden');}
        if(!$mediaOk){
            $eventSource=strtolower(trim((string)($row['source']??'')));
            if(in_array($eventSource,array('open_data_finder','destination_one_open_data','et4'),true)){
                // Native ET4/destination.one images are handled exclusively by the
                // exact-global_id local cache. If that local file is unavailable,
                // continue into the rights-aware fallback chain instead of treating
                // an external feed URL as visitor-ready media.
                $audit[]=array('step'=>'bild_event_feed','status'=>'native_local_cache_ist_autoritaet');
            }else{
                $feed=$this->event_feed_media_candidate($raw);
                if($feed){$stored=$this->event_store_verified_media($event_id,$feed,'event-feed',1.0);$audit[]=array('step'=>'bild_event_feed','status'=>$stored?'extern_verifiziert_aber_nicht_live':'speichern_fehlgeschlagen','url'=>$feed['url']??'');}
                else{$audit[]=array('step'=>'bild_event_feed','status'=>'kein_event_eigenes_bild');}
            }
        }else{$audit[]=array('step'=>'bild_event_feed','status'=>'lokales_live_bild_bereits_vorhanden');}
        if(!$mediaOk && $this->event_auxiliary_media_research_enabled_v1056() && function_exists('ruhrpott_guru_event_media_resolver_v85')){
            $officialWebsite=$this->event_public_website_from_item($raw);
            $req=new WP_REST_Request('POST','/ruhrpottguru/v1/event-media');$req->set_header('content-type','application/json');$req->set_body(wp_json_encode(array('title'=>$row['title'],'website'=>$officialWebsite,'pageUrl'=>$officialWebsite,'sourceUrl'=>$row['source_url'],'raw'=>$raw,'venueName'=>$row['venue_name'],'city'=>$row['city'],'eventType'=>$row['event_category'],'start'=>$row['start_at'],'coords'=>array('lat'=>$row['lat'],'lng'=>$row['lng']))));
            try{
                $res=ruhrpott_guru_event_media_resolver_v85($req);$data=$res instanceof WP_REST_Response?$res->get_data():$res;
                if(is_array($data)&&!empty($data['candidateOnly'])&&!empty($data['candidate'])&&is_array($data['candidate'])){
                    $candidateStored=$this->event_store_editorial_candidate_v1042($event_id,$data['candidate']);
                    $audit[]=array('step'=>'bild_offizielle_quelle','status'=>$candidateStored?'kandidat_gespeichert':'kandidat_speichern_fehlgeschlagen','sourceUrl'=>$data['candidate']['sourceUrl']??'','identityConfidence'=>$data['candidate']['identityConfidence']??null,'rights'=>'redaktionelle_freigabe_erforderlich');
                    if(!empty($data['fallback'])&&is_array($data['fallback'])&&!empty($data['fallback']['imageUrl'])){
                        $fs=sanitize_key((string)($data['fallback']['source']??''));
                        if(in_array($fs,array('venue-commons-context','pexels-symbolic-event'),true)){
                            $mediaOk=$this->event_store_local_fallback_v1042($event_id,$data['fallback'],$fs,(float)($data['fallback']['identityConfidence']??0.0));
                            $audit[]=array('step'=>'bild_fallback','status'=>$mediaOk?'akzeptiert':'abgelehnt_oder_speichern_fehlgeschlagen','source'=>$fs,'sourceUrl'=>$data['fallback']['sourceUrl']??'','license'=>$data['fallback']['license']??'','label'=>$data['fallback']['mediaLabel']??'');
                            if(!$mediaOk&&$fs==='venue-commons-context')$mediaOk=$this->event_try_symbolic_after_context_reject_v101107($event_id,$row,$raw,$audit);
                        }
                    }
                }elseif(is_array($data)&&!empty($data['ok'])&&!empty($data['imageUrl'])){
                    $fs=sanitize_key((string)($data['source']??''));
                    if(in_array($fs,array('venue-commons-context','pexels-symbolic-event'),true)){
                        $mediaOk=$this->event_store_local_fallback_v1042($event_id,$data,$fs,(float)($data['identityConfidence']??0.0));
                        $audit[]=array('step'=>'bild_fallback','status'=>$mediaOk?'akzeptiert':'abgelehnt_oder_speichern_fehlgeschlagen','source'=>$fs,'sourceUrl'=>$data['sourceUrl']??'','license'=>$data['license']??'','label'=>$data['mediaLabel']??'');
                        if(!$mediaOk&&$fs==='venue-commons-context')$mediaOk=$this->event_try_symbolic_after_context_reject_v101107($event_id,$row,$raw,$audit);
                    }else{
                        $audit[]=array('step'=>'bild_offizielle_quelle','status'=>'nicht_automatisch_veroeffentlicht','source'=>$fs,'grund'=>'Quelle ist nicht als automatisch freigegebener Fallback klassifiziert');
                    }
                }elseif(is_array($data)&&!empty($data['message'])){$errors[]=$data['message'];$audit[]=array('step'=>'bild_offizielle_quelle','status'=>'kein_live_treffer','grund'=>$data['message']);}
                else{$audit[]=array('step'=>'bild_offizielle_quelle','status'=>'kein_treffer');}
            }catch(Throwable $e){$errors[]=$e->getMessage();$audit[]=array('step'=>'bild_offizielle_quelle','status'=>'fehler','grund'=>$e->getMessage());}
        }
        if(!$mediaOk && !$this->event_auxiliary_media_research_enabled_v1056())$audit[]=array('step'=>'bild_externe_fallbacks','status'=>'pausiert_et4_fokus','grund'=>'Bis zur Rechteklaerung werden nur ET4/ODF bzw. destination.one-eigene Medienpfade automatisch verarbeitet.');
        $fresh=$wpdb->get_row($wpdb->prepare("SELECT street,postcode,city,media_status FROM $events WHERE id=%d",$event_id),ARRAY_A);$addrOk=$fresh&&$fresh['street']!==''&&$fresh['postcode']!==''&&$fresh['city']!=='';
        // A completed check without a usable photo is a valid terminal result, not an endless retry.
        $status=$mediaOk?'complete':($addrOk?'checked_no_media':'checked_incomplete');
        $old=$wpdb->get_row($wpdb->prepare("SELECT attempts FROM $enr WHERE event_id=%d",$event_id),ARRAY_A);$edata=array('attempts'=>(int)($old['attempts']??0)+1,'last_error'=>implode(' | ',array_slice($errors,0,3)),'audit_json'=>wp_json_encode($audit,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES),'last_enriched_at'=>$now,'updated_at'=>$now);if($addressChanged){$edata['address_source']='event-feed';$edata['address_source_url']=$row['source_url'];}if($mediaOk){$edata['media_source']='verified-event-media';$edata['media_source_url']=$row['source_url'];}
        if($old)$wpdb->update($enr,$edata,array('event_id'=>$event_id));else{$edata['event_id']=$event_id;$wpdb->insert($enr,$edata);}
        $wpdb->update($events,array('enrichment_status'=>$status,'updated_at'=>$now),array('id'=>$event_id));
        return array('ok'=>true,'event_id'=>$event_id,'address'=>$addrOk,'media'=>$mediaOk,'status'=>$status);
    }

    private function event_enrich_batch($limit=5,$wave_started='') {
        global $wpdb;$events=$this->table('events');$enr=$this->table('event_enrichment');$now=current_time('mysql');
        $cutoff=$wave_started!==''?$wave_started:gmdate('Y-m-d H:i:s',time()-18*HOUR_IN_SECONDS);
        $where="(x.last_enriched_at IS NULL OR x.last_enriched_at < '".esc_sql($cutoff)."')";
        $ids=(array)$wpdb->get_col($wpdb->prepare("SELECT e.id FROM $events e LEFT JOIN $enr x ON x.event_id=e.id WHERE e.status='active' AND (e.end_at IS NULL OR e.end_at >= %s) AND e.enrichment_status IN ('pending','retry','partial') AND $where ORDER BY CASE WHEN e.media_status='pending' THEN 0 ELSE 1 END,e.start_at ASC LIMIT %d",$now,max(1,min(20,(int)$limit))));
        $done=0;$media=0;$address=0;foreach($ids as $id){$r=$this->event_enrich_one((int)$id);if(!empty($r['ok'])){$done++;if(!empty($r['media']))$media++;if(!empty($r['address']))$address++;}}
        update_option('rg_events_last_enrichment',array('at'=>$now,'processed'=>$done,'media_ok'=>$media,'address_ok'=>$address),false);
        return array('processed'=>$done,'media_ok'=>$media,'address_ok'=>$address,'had_ids'=>count($ids)>0);
    }

    private function places_import_actively_running() {
        global $wpdb;
        $muni=$this->table('places_municipalities');
        // Only a municipality that is actually claimed is considered active. A retry cooldown does not block events.
        return (int)$wpdb->get_var("SELECT COUNT(*) FROM $muni WHERE status='in_progress' AND (locked_until IS NULL OR locked_until >= UTC_TIMESTAMP())") > 0;
    }


    /**
     * V1.10.50: central read-only inventory of background workers.
     *
     * This deliberately does not change the scheduling of the existing proven workers.
     * It gives the future 53-city Event Coverage worker one authoritative gate and gives
     * RP Redaktion a single place to see what is actually allowed to run in parallel.
     */
    private function event_worker_snapshot_v1050() {
        global $wpdb;
        $now=time();
        $muni=$this->table('places_municipalities');
        $placesActive=(int)$wpdb->get_var("SELECT COUNT(*) FROM $muni WHERE status='in_progress' AND (locked_until IS NULL OR locked_until >= UTC_TIMESTAMP())")>0;

        $rows=array();
        $add=function($key,$label,$class,$state,$hook='',$activeStatuses=array('running')) use (&$rows,$now){
            $state=is_array($state)?$state:array();
            $status=(string)($state['status']??'idle');
            $next=$hook!==''?wp_next_scheduled($hook):false;
            $active=in_array($status,$activeStatuses,true);
            // A scheduled hook is not the same as a running worker. Only genuinely queued
            // transition states may reserve the gate shortly before execution. Waiting,
            // paused and ready states are explicitly passive even when their retry cron is due.
            $passive=array('finished','finished_with_errors','idle','paused','ready','waiting_workers','waiting_enrichment','waiting_theme','waiting_supplemental','waiting_events_sync','paused_places','paused_scope','waiting_quality_gate','checked','complete');
            if(!$active && $next && $next<=$now+30 && !in_array($status,$passive,true) && in_array($status,array('queued','starting','retrying'),true))$active=true;
            $rows[]=array(
                'key'=>$key,'label'=>$label,'class'=>$class,'status'=>$status,'active'=>$active,
                'next'=>$next?:0,'last'=>(string)($state['last_batch_at']??($state['last_progress_at']??($state['worker_last_heartbeat']??''))),
                'detail'=>(string)($state['wait_reason']??($state['pause_reason']??($state['last_error']??''))),
            );
        };

        $rows[]=array(
            'key'=>'places','label'=>'Places / OSM 53 Städte','class'=>'external-heavy',
            'status'=>$placesActive?'running':(get_option(self::OPTION_STATUS)==='ready'?'ready':'idle'),
            'active'=>$placesActive,'next'=>wp_next_scheduled(self::CRON_HOOK)?:0,'last'=>'','detail'=>$placesActive?'Mindestens eine Kommune ist aktuell als in_progress gesperrt.':'',
        );
        $add('event_master','ET4 365-Tage-Master (wöchentlich)','external-heavy',get_option('rg_events_nightly_state',array()),self::EVENT_NIGHTLY_BATCH_HOOK,array('running'));
        $add('event_tier','ET4 Kurz-/Planungsrefresh','external-heavy',get_option(self::EVENT_TIER_STATE,array()),self::EVENT_TIER_BATCH_HOOK,array('running'));
        $add('event_supplemental','destination.one / 53-Städte-Zusatzfeed','external-heavy',get_option('rg_events_supplemental_state',array()),self::EVENT_SUPPLEMENTAL_BATCH_HOOK,array('running'));
        // 1.10.160: the supplemental state may survive a PHP/provider abort as
        // status=running although no process owns the global import lock anymore.
        // Treat the lock as the authoritative concurrency signal. This prevents a
        // stale status row from deadlocking WeselMarketing while the resumable
        // supplemental watchdog is merely waiting for its next turn.
        $suppLock=$this->event_import_lock_v101101();$suppOwnsLock=((string)($suppLock['owner']??'')==='supplemental');
        foreach($rows as &$snapshotRow){if(($snapshotRow['key']??'')==='event_supplemental'&&($snapshotRow['status']??'')==='running'&&!$suppOwnsLock){$snapshotRow['active']=false;$snapshotRow['detail']=trim('Kein aktiver Import-Lock'.($snapshotRow['detail']!==''?' · '.$snapshotRow['detail']:''));}}unset($snapshotRow);
        $add('event_enrichment','Event-Enrichment','external-heavy',get_option('rg_events_enrichment_state',array()),self::EVENT_ENRICH_BATCH_HOOK,array('running'));
        $add('event_rich_fields','ET4 Eventdaten-Backfill','local',get_option(self::EVENT_RICH_FIELDS_STATE,array()),self::EVENT_RICH_FIELDS_HOOK,array('running'));
        $add('iga_intelligence','IGA 2027 Intelligence','local',get_option('rg_intelligence_iga_state',array()),'rg_iga_intelligence_batch_v101081',array('running'));
        $add('et4_catalog_media','ET4 Bildkatalog','external-heavy',get_option(self::EVENT_CATALOG_MEDIA_STATE,array()),self::EVENT_CATALOG_MEDIA_HOOK,array('running'));
        $add('raw_media','Raw-Payload Bild-Backfill','local',get_option(self::EVENT_RAW_MEDIA_STATE,array()),self::EVENT_RAW_MEDIA_HOOK,array('running','running_final'));
        $add('local_media','ET4 Bild-Lokalisierung','external-heavy',get_option(self::EVENT_LOCAL_MEDIA_STATE,array()),self::EVENT_LOCAL_MEDIA_HOOK,array('running'));
        $add('fallback_media','Eventbild-Fallback','external-heavy',get_option(self::EVENT_FALLBACK_MEDIA_STATE,array()),self::EVENT_FALLBACK_MEDIA_HOOK,array('running'));
        $add('context_upgrade','Event-Ort-Upgrade','local',get_option(self::EVENT_CONTEXT_UPGRADE_STATE,array()),self::EVENT_CONTEXT_UPGRADE_HOOK,array('running'));
        $add('candidate_hash','Bild-Dubletten SHA-256','external-heavy',get_option(self::EVENT_CANDIDATE_HASH_STATE,array()),self::EVENT_CANDIDATE_HASH_HOOK,array('running','retrying'));
        $add('opening_hours','Öffnungszeiten-Audit','external-heavy',get_option('rg_opening_hours_audit_state_v1108',array()),self::OPENING_AUDIT_WORKER_HOOK,array('running'));
        $add('event_coverage','53-Städte Coverage-Audit','external-heavy',get_option(self::EVENT_COVERAGE_STATE,array()),self::EVENT_COVERAGE_HOOK,array('running'));

        // V1.10.55: make long-running chains observable instead of showing only
        // a generic "running" state. This is read-only diagnostic metadata.
        $supp=get_option('rg_events_supplemental_state',array());if(!is_array($supp))$supp=array();
        $hash=get_option(self::EVENT_CANDIDATE_HASH_STATE,array());if(!is_array($hash))$hash=array();
        foreach($rows as &$wr){
            if(($wr['key']??'')==='event_supplemental'){
                $done=(int)($supp['cities_done']??0);$total=(int)($supp['cities_total']??53);$lastCity=(string)($supp['last_city']??'');
                $extra='Fortschritt '.$done.'/'.$total.($lastCity!==''?' · zuletzt '.$lastCity:'');
                if(!empty($supp['watchdog_recovered_at']))$extra.=' · Watchdog '.(string)$supp['watchdog_recovered_at'];
                $wr['detail']=trim($extra.($wr['detail']!==''?' · '.$wr['detail']:''));
            }elseif(($wr['key']??'')==='candidate_hash'){
                $processed=(int)($hash['processed']??0);$hashed=(int)($hash['hashed']??0);$failed=(int)($hash['failed']??0);$pass=(int)($hash['pass']??1);$remaining=isset($hash['remaining'])?(int)$hash['remaining']:null;
                $extra='Pass '.$pass.' · verarbeitet '.$processed.' · Hashes '.$hashed.' · fehlgeschlagen '.$failed.($remaining!==null?' · offen '.$remaining:'');
                if(!empty($hash['watchdog_recovered_at']))$extra.=' · Watchdog '.(string)$hash['watchdog_recovered_at'];
                $wr['detail']=trim($extra.($wr['detail']!==''?' · '.$wr['detail']:''));
            }elseif(($wr['key']??'')==='event_rich_fields'){
                $rich=get_option(self::EVENT_RICH_FIELDS_STATE,array());if(!is_array($rich))$rich=array();
                $extra='verarbeitet '.(int)($rich['processed']??0).' · aktualisiert '.(int)($rich['updated']??0).' · Fehler '.(int)($rich['errors']??0);
                $wr['last']=(string)($rich['last_at']??($wr['last']??''));$wr['detail']=trim($extra.($wr['detail']!==''?' · '.$wr['detail']:''));
            }
        }unset($wr);
        return $rows;
    }

    private function event_coverage_gate_v1050() {
        $workers=$this->event_worker_snapshot_v1050();
        $blockers=array();
        foreach($workers as $w){
            if(($w['key']??'')==='event_coverage')continue;
            if(!empty($w['active']) && ($w['class']??'')==='external-heavy')$blockers[]=(string)$w['label'];
        }
