    private function event_coverage_city_registry_v1052() {
        $sources=$this->event_coverage_sources_v1051();$research=$this->event_coverage_research_sources_v1054();
        $out=array();
        foreach($this->municipalities_seed() as $entry){
            $city=(string)($entry[0]??'');if($city==='')continue;
            $local=array();
            foreach($sources as $src){if(strcasecmp((string)($src['city']??''),$city)===0)$local[]=$src;}
            $researchSources=(array)($research[$city]??array());
            $hasEnabledLocal=false;foreach($local as $ls){if(!empty($ls['enabled'])){$hasEnabledLocal=true;break;}}
            $out[$city]=array(
                'city'=>$city,
                'district'=>(string)($entry[2]??''),
                'baseline'=>'ET4 / Open Data Finder',
                'local_sources'=>$local,
                'research_sources'=>$researchSources,
                'coverage_status'=>$hasEnabledLocal?'pilot_active':(($researchSources||$local)?'rights_pending':'source_research'),
            );
        }
        return $out;
    }

