    private function event_coverage_proposed_action_v1052($classification,$score) {
        $score=(int)$score;$classification=(string)$classification;
        if($classification==='conflict')return 'review_conflict';
        if($classification==='rejected')return 'reject';
        if($score<75)return 'review';
        if($classification==='existing')return 'no_change';
        if($classification==='merge_candidate')return $score>=90?'auto_merge_candidate':'audit_merge_candidate';
        if($classification==='missing')return $score>=90?'auto_import_candidate':'audit_import_candidate';
        return 'review';
    }

    private function event_coverage_normalize_title_v1051($title) {
        $title=html_entity_decode(wp_strip_all_tags((string)$title),ENT_QUOTES|ENT_HTML5,'UTF-8');
        $title=remove_accents(mb_strtolower($title));
        $title=preg_replace('~[^a-z0-9]+~u',' ',(string)$title);
        return trim(preg_replace('~\s+~',' ',(string)$title));
    }

    private function event_coverage_title_similarity_v1051($a,$b) {
        $a=$this->event_coverage_normalize_title_v1051($a);$b=$this->event_coverage_normalize_title_v1051($b);
        if($a===''||$b==='')return 0.0;if($a===$b)return 100.0;
        similar_text($a,$b,$pct);
        $max=max(strlen($a),strlen($b));$lev=$max?max(0.0,100.0-(levenshtein(substr($a,0,250),substr($b,0,250))*100.0/$max)):0.0;
        return round(max($pct,$lev),2);
    }

    private function event_coverage_http_get_v1051($url) {
        $r=wp_safe_remote_get($url,array('timeout'=>18,'redirection'=>4,'user-agent'=>'RuhrpottGuru Event Coverage/1.10.165 (+https://www.ruhrpottguru.de/)','headers'=>array('Accept'=>'text/html,application/xhtml+xml;q=0.9,*/*;q=0.8','Referer'=>'https://www.wesel-tourismus.de/'),'limit_response_size'=>3*1024*1024));
        if(is_wp_error($r))return $r;$code=(int)wp_remote_retrieve_response_code($r);$body=(string)wp_remote_retrieve_body($r);$ct=strtolower((string)wp_remote_retrieve_header($r,'content-type'));
        if($code<200||$code>=400||trim($body)==='')return new WP_Error('coverage_http','HTTP '.$code.' bei '.$url);
        if($ct!==''&&strpos($ct,'text/html')===false&&strpos($ct,'application/xhtml')===false)return new WP_Error('coverage_type','Unerwarteter Content-Type '.$ct.' bei '.$url);
        return $body;
    }

    private function event_coverage_extract_detail_links_v1051($html,$base) {
        $out=array();
        if(class_exists('DOMDocument')){
            $dom=new DOMDocument();$old=libxml_use_internal_errors(true);@$dom->loadHTML('<?xml encoding="utf-8" ?>'.$html);libxml_clear_errors();libxml_use_internal_errors($old);
            foreach($dom->getElementsByTagName('a') as $a){$href=trim((string)$a->getAttribute('href'));if(!preg_match('~(?:^|/)veranstaltung/(\d+)(?:[/?#]|$)~i',$href,$m))continue;$id=$m[1];if(strpos($href,'http')!==0)$href=rtrim($base,'/').'/veranstaltung/'.$id;$out[$id]=esc_url_raw($href);}
        }
        if(!$out&&preg_match_all('~href=["\']([^"\']*/veranstaltung/(\d+)[^"\']*)["\']~i',$html,$mm,PREG_SET_ORDER)){foreach($mm as $m){$href=$m[1];$id=$m[2];if(strpos($href,'http')!==0)$href=rtrim($base,'/').'/veranstaltung/'.$id;$out[$id]=esc_url_raw($href);}}
        return $out;
    }

    private function event_coverage_extract_list_candidates_v1051($html,$base) {
        $out=array();if(!class_exists('DOMDocument'))return $out;
        $dom=new DOMDocument();$old=libxml_use_internal_errors(true);@$dom->loadHTML('<?xml encoding="utf-8" ?>'.$html);libxml_clear_errors();libxml_use_internal_errors($old);
        foreach($dom->getElementsByTagName('a') as $a){
            $txt=trim(preg_replace('~\s+~u',' ',(string)$a->textContent));$href=trim((string)$a->getAttribute('href'));
            if($txt===''||mb_stripos($txt,'Tickets sichern')===false)continue;
            if(!preg_match('~^[A-ZÄÖÜ][a-zäöü]{2}\s+\d{1,2}\s+(.+?)\s+(Mo|Di|Mi|Do|Fr|Sa|So)\.,\s+(\d{1,2})\.\s+([A-ZÄÖÜa-zäöü]+)\s+(\d{4})\s+·\s+(\d{1,2}[:.]\d{2})\s+Uhr\s+(.+?)\s+Tickets sichern~u',$txt,$m))continue;
            $title=trim($m[1]);$dateText=$m[3].'. '.$m[4].' '.$m[5];$start=$this->event_coverage_parse_german_datetime_v1051($dateText,$m[6]);if(!$start)continue;
