    }

    public function cron_events_coverage_audit_v1051() {
        $sources=$this->event_coverage_sources_v1051();$source=$sources['wesel_marketing_calendar']??null;if(!$source||empty($source['enabled']))return;
        $state=$this->event_coverage_wesel_state_v101159();$gate=$this->event_coverage_gate_v1050();
