                $page=max(0,(int)$state['page']);$knownMax=$state['max_page'];
                if($knownMax===null||$page<=(int)$knownMax){
                    $url=$page===0?$base:add_query_arg('page',$page,$base);$html=$this->event_coverage_http_get_v1051($url);
                    if(is_wp_error($html)){$state['list_failures']=(int)$state['list_failures']+1;$state['errors']=(int)$state['errors']+1;$state['status']='retry';$state['wait_reason']=$html->get_error_message();$state['last_progress_at']=current_time('mysql');update_option(self::EVENT_COVERAGE_STATE,$state,false);$this->event_coverage_wesel_schedule_v101159(min(900,60*(int)$state['list_failures']));return;}
                    $state['list_failures']=0;$parsed=$this->event_coverage_parse_wesel_list_v101159($html,$base);$items=array_values((array)($parsed['items']??array()));$reportedMax=min($maxConfigured-1,max(0,(int)($parsed['max_page']??0)));
                    if($state['max_page']===null)$state['max_page']=$reportedMax;else $state['max_page']=min($maxConfigured-1,max((int)$state['max_page'],$reportedMax));
                    if(!$items&&$page===0){$state['status']='retry';$state['errors']=(int)$state['errors']+1;$state['wait_reason']='Offizieller Wesel-Kalender lieferte auf Seite 1 keine Eventkarten.';$state['last_progress_at']=current_time('mysql');update_option(self::EVENT_COVERAGE_STATE,$state,false);$this->event_coverage_wesel_schedule_v101159(600);return;}
                    $state['queue']=$items;$state['page']=$page+1;
                }
            }
            $loops=0;while(!empty($state['queue'])&&$loops<4){$entry=array_shift($state['queue']);$loops++;$this->event_import_lock_touch_v101101($owner);$html=$this->event_coverage_http_get_v1051((string)($entry['source_url']??''));
                if(is_wp_error($html)){$entry['attempts']=(int)($entry['attempts']??0)+1;$state['errors']=(int)$state['errors']+1;if($entry['attempts']<3)$state['queue'][]=$entry;else $state['failed_details'][(string)($entry['source_uid']??sha1(wp_json_encode($entry))) ]=$html->get_error_message();continue;}
                $c=$this->event_coverage_parse_wesel_detail_v101159($html,$entry);if(!$c||empty($c['source_uid'])||empty($c['start_at'])){$state['errors']=(int)$state['errors']+1;$state['failed_details'][(string)($entry['source_uid']??sha1(wp_json_encode($entry))) ]='Detailseite ohne verwertbaren Titel/Starttermin';continue;}
                $r=$this->event_coverage_process_wesel_candidate_v101159($c,$source,$run);$state['seen']=(int)$state['seen']+1;$action=(string)($r['action']??'audit');if($action==='imported')$state['imported']=(int)$state['imported']+1;elseif($action==='updated')$state['updated']=(int)$state['updated']+1;elseif($action==='linked_existing')$state['linked_existing']=(int)$state['linked_existing']+1;else $state['audit']=(int)$state['audit']+1;
            }
            $state['last_progress_at']=current_time('mysql');$knownMax=$state['max_page'];$morePages=($knownMax===null)||((int)$state['page']<=(int)$knownMax);
            if(!empty($state['queue'])||$morePages){$state['status']='running';$state['wait_reason']='';update_option(self::EVENT_COVERAGE_STATE,$state,false);$this->event_coverage_wesel_schedule_v101159(45);return;}
            $state['finished_at']=current_time('mysql');$state['status']=empty($state['failed_details'])?'finished':'finished_partial';$state['wait_reason']=empty($state['failed_details'])?'':'Einzelne Detailseiten blieben nach drei Versuchen unerreichbar; Missing-Lifecycle wurde deshalb nicht angewendet.';
            if(empty($state['failed_details'])){global $wpdb;$cand=$this->table('event_coverage_candidates');$wpdb->query($wpdb->prepare("UPDATE $cand SET is_active=0 WHERE source_key=%s AND scan_token<>%s",$source['key'],$run));$today=new DateTimeImmutable('today',wp_timezone());$life=$this->event_apply_missing_lifecycle_v101125($run,$today->format('d.m.Y'),$today->modify('+365 days')->format('d.m.Y'),array('wesel_marketing_calendar'),'WeselMarketing');$state['lifecycle']=$life;$state['last_success_at']=current_time('mysql');}
            update_option(self::EVENT_COVERAGE_STATE,$state,false);$this->event_coverage_wesel_schedule_v101159(4*HOUR_IN_SECONDS);
