    private function event_coverage_wesel_audit_snapshot_v101161($limit=100) {
        global $wpdb;$limit=max(1,min(200,(int)$limit));$cand=$this->table('event_coverage_candidates');$events=$this->table('events');$now=esc_sql(current_time('mysql'));$today=esc_sql(wp_date('Y-m-d',current_time('timestamp'),wp_timezone()));
        // 1.10.165: the active audit represents unresolved current/future official
        // source rows only. Definitively expired rows are historical evidence, not a
        // visitor-facing blocker and therefore do not inflate the open count.
        $where="c.source_key='wesel_marketing_calendar' AND c.is_active=1 AND c.classification IN ('missing','conflict') AND ((c.end_at IS NOT NULL AND c.end_at>='$now') OR (c.end_at IS NULL AND DATE(c.start_at)>='$today')) AND NOT EXISTS (SELECT 1 FROM $events e WHERE e.source='wesel_marketing_calendar' AND e.external_id=c.source_uid)";
        $total=(int)$wpdb->get_var("SELECT COUNT(*) FROM $cand c WHERE $where");
        $rows=(array)$wpdb->get_results("SELECT c.id,c.source_uid,c.source_url,c.title,c.start_at,c.end_at,c.venue_name,c.address_text,c.classification,c.confidence,c.audit_json FROM $cand c WHERE $where ORDER BY c.start_at ASC,c.id ASC LIMIT ".(int)$limit,ARRAY_A);
        foreach($rows as &$r){$audit=json_decode((string)($r['audit_json']??''),true);$match=is_array($audit)?(array)($audit['match']??array()):array();$reason=trim((string)($match['reason']??''));if((string)($r['classification']??'')==='conflict')$r['_audit_reason']=$reason!==''?$reason:'Konfliktprüfung erforderlich';else $r['_audit_reason']='Offizieller Wesel-Termin wartet auf Materialisierung im Zukunftstermin-Reprocess';}unset($r);
        return array('total'=>$total,'rows'=>$rows);
    }

