        $active=0;$heavy=0;foreach($workers as $w){if(!empty($w['active'])){$active++;if(($w['class']??'')==='external-heavy')$heavy++;}}
        echo '<div style="max-width:1100px;background:#fff;border:1px solid #dcdcde;border-radius:8px;padding:14px;margin:0 0 18px">';
        echo '<div style="display:flex;justify-content:space-between;gap:12px;align-items:flex-start;flex-wrap:wrap"><div><h2 style="margin:0 0 4px">Hintergrundprozesse</h2><p style="margin:0;color:#646970">Zentrale Sicht auf die bestehenden Queues. Seit v1.10.55 repariert ein Watchdog überfällige Supplemental- und SHA-256-Läufe; passive Wartezustände zählen nicht als aktive Worker.</p></div>';
        echo '<div style="padding:7px 10px;border-radius:999px;background:#fcf0c6;color:#6e4b00;font-weight:600">Lokale Coverage: WeselMarketing aktiv</div></div>';
        echo '<p><strong>'.intval($active).' Worker aktiv</strong> · '.intval($heavy).' davon extern/ressourcenintensiv';
        if(!empty($gate['blockers']))echo ' · aktuell extern aktiv: '.esc_html(implode(', ',$gate['blockers']));
        echo '</p><div style="overflow:auto"><table class="widefat striped"><thead><tr><th>Worker</th><th>Klasse</th><th>Status</th><th>Nächster Lauf</th><th>Letzte Aktivität / Fortschritt</th></tr></thead><tbody>';
        foreach($workers as $w){$status=(string)$w['status'];$isActive=!empty($w['active']);$next=!empty($w['next'])?wp_date('d.m.Y H:i:s',(int)$w['next'],wp_timezone()).' Uhr':'–';$detail=trim((string)$w['last'].((!empty($w['last'])&&!empty($w['detail']))?' · ':'').(string)$w['detail']);
            echo '<tr><td><strong>'.esc_html($w['label']).'</strong></td><td>'.(($w['class']??'')==='external-heavy'?'extern / schwer':'lokal').'</td><td><span style="display:inline-block;padding:2px 7px;border-radius:999px;background:'.($isActive?'#fcf0c6':'#f0f0f1').';">'.esc_html($status).'</span></td><td>'.esc_html($next).'</td><td>'.($detail!==''?esc_html($detail):'–').'</td></tr>';
        }
        echo '</tbody></table></div>';
        echo '<p style="margin:10px 0 0;color:#646970"><strong>Wichtig:</strong> WeselMarketing ist als freigegebene lokale Pilotquelle aktiv und nutzt denselben globalen Event-Import-Lock wie ET4. Die weiteren kommunalen Quellen bleiben bis zu ihrer jeweiligen Freigabe deaktiviert.</p></div>';
    }

    private function event_enrichment_progress_snapshot() {
        global $wpdb;$events=$this->table('events');$now=current_time('mysql');
        $total=(int)$wpdb->get_var($wpdb->prepare("SELECT COUNT(*) FROM $events WHERE status='active' AND (end_at IS NULL OR end_at >= %s)",$now));
        $open=(int)$wpdb->get_var($wpdb->prepare("SELECT COUNT(*) FROM $events WHERE status='active' AND (end_at IS NULL OR end_at >= %s) AND enrichment_status IN ('pending','retry','partial')",$now));
        $with_media=(int)$wpdb->get_var($wpdb->prepare("SELECT COUNT(*) FROM $events WHERE status='active' AND (end_at IS NULL OR end_at >= %s) AND media_status='verified'",$now));
        $failed=(int)$wpdb->get_var($wpdb->prepare("SELECT COUNT(*) FROM $events WHERE status='active' AND (end_at IS NULL OR end_at >= %s) AND enrichment_status='failed'",$now));
        return array('total'=>$total,'open'=>$open,'checked'=>max(0,$total-$open),'with_media'=>$with_media,'failed'=>$failed);
    }

    public function cron_events_enrichment_batch() {
        $state=get_option('rg_events_enrichment_state',array());if(!is_array($state))$state=array();if(($state['status']??'')!=='running')return;
        if($this->places_import_actively_running()){
            $state['status']='paused_places';$state['pause_reason']='Places-Import aktiv';$state['last_batch_at']=current_time('mysql');update_option('rg_events_enrichment_state',$state,false);
            if(!wp_next_scheduled(self::EVENT_ENRICH_BATCH_HOOK))wp_schedule_single_event(time()+120,self::EVENT_ENRICH_BATCH_HOOK);return;
        }
        if(($state['status']??'')==='paused_places')$state['status']='running';
        $started=microtime(true);$loops=0;$any=false;
        // Work for a bounded time instead of relying on one WP-Cron request per five events.
        do{
            $r=$this->event_enrich_batch(5,(string)($state['started_at']??''));$loops++;$any=$any||!empty($r['had_ids']);
            $state['processed']=(int)($state['processed']??0)+(int)$r['processed'];$state['media_ok']=(int)($state['media_ok']??0)+(int)$r['media_ok'];$state['address_ok']=(int)($state['address_ok']??0)+(int)$r['address_ok'];$state['last_batch_at']=current_time('mysql');
            if(!$r['had_ids']||$r['processed']===0)break;
            if($this->places_import_actively_running()){ $state['status']='paused_places';$state['pause_reason']='Places-Import aktiv';break; }
        }while($loops<5 && (microtime(true)-$started)<18);
        $snap=$this->event_enrichment_progress_snapshot();$state=array_merge($state,$snap);
        if(!$any || $snap['open']===0){$state['status']='finished';$state['finished_at']=current_time('mysql');}
        elseif(($state['status']??'')!=='paused_places'){$state['status']='running';}
        update_option('rg_events_enrichment_state',$state,false);
        if(($state['status']??'')!=='finished'&&!wp_next_scheduled(self::EVENT_ENRICH_BATCH_HOOK))wp_schedule_single_event(time()+60,self::EVENT_ENRICH_BATCH_HOOK);
    }

    private function start_event_enrichment_wave() {
        wp_clear_scheduled_hook(self::EVENT_ENRICH_BATCH_HOOK);$snap=$this->event_enrichment_progress_snapshot();
        update_option('rg_events_enrichment_state',array_merge(array('status'=>'running','started_at'=>current_time('mysql'),'processed'=>0,'media_ok'=>0,'address_ok'=>0,'last_batch_at'=>''),$snap),false);
        // Due immediately: the next normal WordPress cron spawn can start it without a five-second dead zone.
        wp_schedule_single_event(time(),self::EVENT_ENRICH_BATCH_HOOK);
        if(function_exists('spawn_cron'))spawn_cron();
    }

    private function event_cleanup_expired($force=false) {
        global $wpdb;$last=(int)get_option('rg_events_last_cleanup_ts',0);if(!$force && $last>time()-DAY_IN_SECONDS)return 0;
        $events=$this->table('events');$sources=$this->table('event_sources');$media=$this->table('event_media');$enr=$this->table('event_enrichment');
        $now=current_time('mysql');$cutoff=date('Y-m-d H:i:s',current_time('timestamp')-10*DAY_IN_SECONDS);
        $wpdb->query($wpdb->prepare("UPDATE $events SET status='expired',updated_at=%s WHERE status='active' AND COALESCE(end_at,start_at)<%s",$now,$now));
        $ids=(array)$wpdb->get_col($wpdb->prepare("SELECT id FROM $events WHERE COALESCE(end_at,start_at)<%s LIMIT 1000",$cutoff));
        $deleted=0;if($ids){$ids=array_map('intval',$ids);$in=implode(',',$ids);$wpdb->query("DELETE FROM $sources WHERE event_id IN ($in)");$wpdb->query("DELETE FROM $media WHERE event_id IN ($in)");$wpdb->query("DELETE FROM $enr WHERE event_id IN ($in)");$deleted=(int)$wpdb->query("DELETE FROM $events WHERE id IN ($in)");}
        update_option('rg_events_last_cleanup_ts',time(),false);update_option('rg_events_last_cleanup',array('deleted'=>$deleted,'cutoff'=>$cutoff,'at'=>$now),false);return $deleted;
    }

    private function event_sync_master_page($force=false,$run_token='',$query_start='',$query_end='',$context_prefix='master',$offset_override=null,$persist_master_offset=true) {
        $state=get_option('rg_events_sync_state',array());if(!is_array($state))$state=array();
        $offset=$offset_override===null?max(0,(int)($state['master_offset']??0)):max(0,(int)$offset_override);
        $today=new DateTimeImmutable('today',wp_timezone());$until=$today->modify('+365 days');
        $startDate=$query_start!==''?$query_start:$today->format('d.m.Y');$endDate=$query_end!==''?$query_end:$until->format('d.m.Y');
        if(!function_exists('ruhrpott_guru_et4_fetch_pages'))return array('error'=>'Theme-ET4-Transport nicht verfügbar','done'=>false,'count'=>0,'offset'=>$offset);
        // ET4 is used as the authoritative source-object filter. Unique catalog rows are
        // expanded locally into concrete occurrences inside the requested time window.
        $args=array('_start_offset'=>$offset,'unique'=>'true','q'=>'area:"Metropole Ruhr"','startdate'=>$startDate,'enddate'=>$endDate,'sort'=>'title asc');
        $result=ruhrpott_guru_et4_fetch_pages($args,1,'ruhr-tourismus-open-data',true);
        if(!is_array($result)||empty($result['ok'])){
            $err=is_array($result)?(string)($result['error']??'Unbekannter ET4-Fehler'):'Ungültige ET4-Antwort';
            $state['last_attempt_ts']=time();$state['last_error']=$err;update_option('rg_events_sync_state',$state,false);
            return array('error'=>$err,'done'=>false,'count'=>0,'offset'=>$offset);
        }
        $rawItems=is_array($result['items']??null)?$result['items']:array();
        if(function_exists('ruhrpott_guru_event_tag_list_v114'))$rawItems=ruhrpott_guru_event_tag_list_v114($rawItems,'open_data_finder');
        if(function_exists('ruhrpott_guru_event_prefer_venue_address')){foreach($rawItems as $i=>$it)if(is_array($it))$rawItems[$i]=ruhrpott_guru_event_prefer_venue_address($it);}
        $sourceDedupe=$this->event_master_unique_source_rows($rawItems);$sourceItems=$sourceDedupe['items'];
        $explicitCancelled=$this->event_apply_explicit_cancellations_v101125($sourceItems,$run_token,array('open_data_finder','et4'));
        $expanded=$this->event_et4_expand_page_occurrences($sourceItems,$startDate,$endDate);$items=$expanded['items'];$expandStats=$expanded['stats'];
        $prefix=sanitize_key((string)$context_prefix);if($prefix==='')$prefix='master';
        $ctx=$run_token!==''?$prefix.':'.$run_token:'background:Metropole Ruhr';
        $ingest=$this->ingest_event_items($items,$ctx,true);$count=(int)($ingest['success']??0);
        $seen=$this->event_master_seen_apply($ingest['canonical_keys']??array(),$ingest['external_keys']??array());
        $sourceDedupe['unique_source_objects_total']=$this->event_master_commit_source_rows($sourceDedupe['new_source_keys']??array());
        $page=$result['pages'][0]??array();$rawCount=count($rawItems);$overall=isset($page['overallcount'])&&is_numeric($page['overallcount'])?(int)$page['overallcount']:null;
        if($rawCount===0&&$overall!==null&&$overall>$offset){
            $err='ET4 lieferte eine leere Seite vor Erreichen von overallcount (Offset '.$offset.' / '.$overall.')';
            $state['last_attempt_ts']=time();$state['last_error']=$err;update_option('rg_events_sync_state',$state,false);
            return array('error'=>$err,'done'=>false,'count'=>0,'raw_count'=>0,'overall'=>$overall,'offset'=>$offset,'ingest'=>$ingest,'expand'=>$expandStats,'source_dedupe'=>$sourceDedupe,'seen'=>$seen,'explicit_cancelled'=>(int)$explicitCancelled,'page'=>$page);
        }
        $next=$offset+$rawCount;$done=$overall!==null&&$overall>0?($next>=$overall):($rawCount<100);
        $overrun=($overall!==null&&$overall>0)?max(0,$next-$overall):0;
        $state['last_attempt_ts']=time();$state['last_error']='';$state['last_success_at']=current_time('mysql');$state['last_count']=$count;$state['last_raw_count']=$rawCount;
        $state['last_new_source_objects']=(int)($sourceDedupe['new_source_objects']??0);$state['last_occurrences_generated']=(int)($expandStats['occurrences_generated']??0);
        if($persist_master_offset)$state['master_offset']=$done?0:$next;
        $state['master_overall']=$overall;$state['last_city']='Metropole Ruhr';$state['last_context']=$prefix;update_option('rg_events_sync_state',$state,false);
        return array('count'=>$count,'raw_count'=>$rawCount,'occurrences_generated'=>(int)($expandStats['occurrences_generated']??0),'overall'=>$overall,'offset'=>$offset,'next_offset'=>$next,'overrun'=>$overrun,'done'=>$done,'error'=>'','page'=>$page,'ingest'=>$ingest,'expand'=>$expandStats,'source_dedupe'=>$sourceDedupe,'seen'=>$seen,'explicit_cancelled'=>(int)$explicitCancelled);
    }

    /**
     * 1.10.102 Selm pilot: official municipal HTML calendar as a normal Event source.
     * No separate visitor surface is created. The adapter only emits canonical feed
     * items and lets event_upsert_from_feed_item() own storage/normalisation.
     */
    private function ensure_event_selm_calendar_schedule_v101102() {
        $next=wp_next_scheduled(self::EVENT_SELM_HOOK);
        if(!$next || wp_get_schedule(self::EVENT_SELM_HOOK)!==self::EVENT_HOT_SCHEDULE){
            wp_clear_scheduled_hook(self::EVENT_SELM_HOOK);
            wp_schedule_event(time()+20*MINUTE_IN_SECONDS,self::EVENT_HOT_SCHEDULE,self::EVENT_SELM_HOOK);
        }
        $state=get_option(self::EVENT_SELM_STATE,array());if(!is_array($state))$state=array();
        if(($state['status']??'')==='running' && !wp_next_scheduled(self::EVENT_SELM_BATCH_HOOK)){
            wp_schedule_single_event(time()+30,self::EVENT_SELM_BATCH_HOOK);
        }
        // Upgrades of an already-active plugin do not run activation hooks. Bootstrap
        // the first pilot wave once, but keep it behind the global Event import lock.
        if(!get_option('rg_events_selm_calendar_bootstrap_v101102')){
            update_option('rg_events_selm_calendar_bootstrap_v101102',current_time('mysql'),false);
            wp_schedule_single_event(time()+45,self::EVENT_SELM_RETRY_HOOK);
        }
    }

    private function event_selm_fetch_html_v101102($url) {
        $url=esc_url_raw((string)$url);$host=strtolower((string)wp_parse_url($url,PHP_URL_HOST));$host=preg_replace('/^www\./','',$host);if($url===''||$host!=='stadtportal-selm.de')return new WP_Error('rpg_selm_url','Ungueltige Selm-Kalender-URL');
        $res=wp_safe_remote_get($url,array(
            'timeout'=>15,'redirection'=>3,
            'user-agent'=>'RuhrpottGuru/1.0 (+https://ruhrpottguru.de; kommunaler Veranstaltungskalender, Quelle Stadt Selm)',
            'headers'=>array('Accept'=>'text/html,application/xhtml+xml','Accept-Language'=>'de-DE,de;q=0.9')
        ));
        if(is_wp_error($res))return $res;
        $code=(int)wp_remote_retrieve_response_code($res);if($code<200||$code>=300)return new WP_Error('rpg_selm_http','Selm-Kalender HTTP '.$code);
        $body=(string)wp_remote_retrieve_body($res);if(strlen($body)<500)return new WP_Error('rpg_selm_empty','Selm-Kalender lieferte keinen verwertbaren HTML-Inhalt');
        return $body;
    }

    private function event_selm_clean_text_v101102($html,$max=0) {
        $html=(string)$html;
        $html=preg_replace('~<(script|style|noscript)\b[^>]*>.*?</\1>~isu',' ',$html);
        $html=preg_replace('~<\s*(?:br\s*/?|/p|/div|/li|/tr|/td|/th|/h[1-6]|/dt|/dd)\s*>~iu',"\n",$html);
        $text=html_entity_decode(wp_strip_all_tags($html),ENT_QUOTES|ENT_HTML5,'UTF-8');
        $text=str_replace(array("\r\n","\r","\xC2\xA0"),array("\n","\n",' '),$text);
        $out=array();$blank=true;
        foreach(explode("\n",$text) as $line){$line=trim(preg_replace('/[ \t]+/u',' ',(string)$line));if($line===''){if(!$blank&&$out){$out[]='';$blank=true;}continue;}$out[]=$line;$blank=false;}
        while($out&&end($out)==='')array_pop($out);$text=trim(implode("\n",$out));
        if($max>0)$text=function_exists('mb_substr')?mb_substr($text,0,$max):substr($text,0,$max);
        return $text;
    }

    private function event_selm_listing_links_v101102($html) {
        $html=(string)$html;$out=array();if($html==='')return array();

        $store=function($id,$href,$rowHtml) use (&$out){
            $id=preg_replace('/\D+/','',(string)$id);if($id==='')return;
            $href=html_entity_decode((string)$href,ENT_QUOTES|ENT_HTML5,'UTF-8');$href=str_replace('\\/','/',$href);$href=trim($href," \t\n\r\0\x0B\"'");
            if(strpos($href,'//')===0)$href='https:'.$href;
            elseif(!preg_match('~^https?://~i',$href))$href='https://www.stadtportal-selm.de/'.ltrim($href,'/');
            $href=preg_replace('~[?#].*$~','',$href);$href=esc_url_raw($href);if($href==='')return;
            $rowText=$this->event_selm_clean_text_v101102($rowHtml,1200);
            $out[$id]=array('id'=>$id,'url'=>$href,'listing_hash'=>sha1($rowText),'listing_text'=>$rowText);
        };

        /*
         * Stadtportal Selm does not guarantee one fixed navigation element for the
         * "Anzeigen" target. Discover the canonical detail route itself rather than
         * coupling the importer to an absolute <a href>. This accepts absolute,
         * root-relative and page-relative canonical routes in href/action/data/JS
         * markup. /verwaltung/veranstaltungen/bilder/... is explicitly excluded.
         */
        $route='~(^|["\'\s=(>])((?:(?:https?:)?//(?:www\.)?stadtportal-selm\.de)?/?veranstaltungen/(?!bilder(?:/|$))[^\s"\'<>/?#]+/([0-9]{3,12})(?:[?#][^\s"\'<>]*)?/?)~imu';
        if(preg_match_all($route,$html,$mm,PREG_OFFSET_CAPTURE)){
            foreach($mm[2] as $i=>$hit){
                $pos=(int)$hit[1];$before=substr($html,0,$pos);$trStart=strripos($before,'<tr');$trEnd=stripos($html,'</tr>',$pos);
                $rowHtml=($trStart!==false&&$trEnd!==false&&$trEnd>$trStart)?substr($html,$trStart,$trEnd+5-$trStart):substr($html,max(0,$pos-500),1200);
                $store((string)($mm[3][$i][0]??''),(string)$hit[0],$rowHtml);
            }
        }

        /*
         * A listing page may shorten its own links to "slug/id" because the browser
         * resolves them relative to /veranstaltungen/. Inspect only navigation-like
         * attributes (never src), require the numeric id to terminate the path, and
         * require a letter in the slug. This avoids mistaking image directories such
         * as .../bilder/98/104198/file.png for event routes.
         */
        if(preg_match_all('~<tr\b[^>]*>.*?</tr>~isu',$html,$rows,PREG_OFFSET_CAPTURE)){
            foreach($rows[0] as $rowHit){
                $rowHtml=(string)$rowHit[0];
                if(!preg_match_all('~\b(?:href|action|data-href|data-url|data-link|onclick)\s*=\s*(["\'])(.*?)\1~isu',$rowHtml,$attrs))continue;
                foreach($attrs[2] as $raw){
                    $probe=html_entity_decode((string)$raw,ENT_QUOTES|ENT_HTML5,'UTF-8');$probe=str_replace('\\/','/',$probe);
                    if(preg_match('~(?:(?:https?:)?//(?:www\.)?stadtportal-selm\.de)?/?veranstaltungen/(?!bilder(?:/|$))([^\s"\'<>/?#]+)/([0-9]{3,12})(?=$|[?#"\'\s);])~iu',$probe,$m)){
                        $store($m[2],'https://www.stadtportal-selm.de/veranstaltungen/'.$m[1].'/'.$m[2],$rowHtml);continue;
                    }
                    $short=preg_replace('~^(?:\.\.?/)+~','',trim($probe));
                    if(preg_match('~(?:^|["\'(=:\s])(?:\./)?([A-Za-z0-9._%-]+)/([0-9]{3,12})(?=$|[?#"\'\s);])~u',$short,$m) && preg_match('/[A-Za-z]/',$m[1])){
                        $store($m[2],'https://www.stadtportal-selm.de/veranstaltungen/'.$m[1].'/'.$m[2],$rowHtml);
                    }
                }
            }
        }

        ksort($out,SORT_NATURAL);return array_values($out);
    }

    private function event_selm_label_blocks_v101102($text) {
        $labels=array('Kategorie','Datum','Beginn','Ende','Hinweise zum Termin','Veranstaltungsplatz','Straße','PLZ und Ort','Veranstalter','E-Mail','Ansprechpartner','Straße, HausNr.','PLZ, Ort','Webseite','Telefon','Facebook','Instagram','FAX','Bemerkung');
        $headingOnly=array('Termin','Veranstaltungsort','Veranstalterdaten');$known=array();foreach(array_merge($labels,$headingOnly) as $l)$known[$l]=1;
        $lines=array_values(array_filter(array_map('trim',explode("\n",(string)$text)),function($v){return $v!=='';}));$out=array();$current='';
        foreach($lines as $line){$matched='';$remainder='';foreach(array_keys($known) as $label){if(preg_match('/^'.preg_quote($label,'/').'\s*:\s*(.*)$/u',$line,$m)){$matched=$label;$remainder=trim((string)$m[1]);break;}if($line===$label){$matched=$label;break;}}if($matched!==''){$current=isset($out[$matched])?'':$matched;if($current!=='')$out[$current]=$remainder;continue;}if($current!==''){$out[$current].=($out[$current]!==''?"\n":'').$line;}}
        return $out;
    }

    private function event_selm_parse_date_v101102($dateText,$begin='',$endTime='') {
        $dateText=trim((string)$dateText);if(!preg_match_all('/(\d{1,2}\.\d{1,2}\.\d{4})/',$dateText,$dm)||empty($dm[1]))return array(null,null,false);
        $dates=$dm[1];$d1=$dates[0];$d2=end($dates)?:$d1;
        $timeOf=function($v){return preg_match('/(\d{1,2})[:.](\d{2})/',(string)$v,$m)?sprintf('%02d:%02d',(int)$m[1],(int)$m[2]):'';};
        $bt=$timeOf($begin);$et=$timeOf($endTime);$allDay=$bt==='';$tz=wp_timezone();
        $make=function($d,$t)use($tz){$fmt=$t!==''?'!d.m.Y H:i':'!d.m.Y';$src=$t!==''?$d.' '.$t:$d;$dt=DateTimeImmutable::createFromFormat($fmt,$src,$tz);return $dt instanceof DateTimeImmutable?$dt:null;};
        $start=$make($d1,$bt);if(!$start)return array(null,null,false);
        if($allDay){$finish=$make($d2,'');$finish=$finish?$finish->setTime(23,59,59):null;}
        elseif($et!=='')$finish=$make($d2,$et);
        elseif($d2!==$d1){$finish=$make($d2,'');$finish=$finish?$finish->setTime(23,59,59):null;}
        else $finish=null;
        return array($start->format(DateTimeInterface::ATOM),$finish?$finish->format(DateTimeInterface::ATOM):null,$allDay);
    }

    private function event_selm_listing_start_timestamp_v101102($text) {
        if(!preg_match('/(\d{1,2}\.\d{1,2}\.\d{4})/',(string)$text,$m))return 0;
        $dt=DateTimeImmutable::createFromFormat('!d.m.Y',(string)$m[1],wp_timezone());
        return $dt instanceof DateTimeImmutable?$dt->getTimestamp():0;
    }

    private function event_selm_extract_title_v101102($html) {
        foreach(array('h3','h2','h1') as $tag){if(preg_match('~<'.$tag.'\b[^>]*>(.*?)</'.$tag.'>~isu',(string)$html,$m)){$t=$this->event_selm_clean_text_v101102($m[1],255);if($t!==''&&!in_array(mb_strtolower($t,'UTF-8'),array('veranstaltungen','stadtportal'),true))return $t;}}
        return '';
    }

    private function event_selm_extract_description_v101102($html,$title) {
        $html=(string)$html;$start=0;
        // Detail pages currently use the first content h3 for the event title. Avoid
        // matching the literal title string because HTML entities may differ.
        if(preg_match('~<h[1-3]\b[^>]*>.*?</h[1-3]>~isu',$html,$m,PREG_OFFSET_CAPTURE))$start=$m[0][1]+strlen($m[0][0]);
        $slice=substr($html,$start);$cut=stripos($slice,'Kategorie:');if($cut!==false)$slice=substr($slice,0,$cut);
