        list($street,$house,$zip,$city)=$this->event_address_from_item($item);$venue=$this->event_venue_name_from_item_v1058($item);if($city==='')return $item;
        $events=$this->table('events');$places=$this->table('places');$want=$this->event_listing_norm($venue);$best=null;$score=-1;
        if($want!==''){
            foreach((array)$wpdb->get_results($wpdb->prepare("SELECT venue_name,street,house_number,postcode,city,lat,lng FROM $events WHERE city=%s AND venue_name<>'' AND lat IS NOT NULL AND lng IS NOT NULL ORDER BY updated_at DESC LIMIT 300",$city),ARRAY_A) as $r){$got=$this->event_listing_norm($r['venue_name']??'');$s=$got===$want?100:((strlen($want)>=7&&($got!==''&&(strpos($got,$want)!==false||strpos($want,$got)!==false)))?70:0);if($s>$score){$score=$s;$best=$r;}}
            foreach((array)$wpdb->get_results($wpdb->prepare("SELECT name,street,house_number,postcode,city,lat,lng FROM $places WHERE city=%s AND active=1 AND lifecycle_status='active' ORDER BY updated_at DESC LIMIT 800",$city),ARRAY_A) as $r){$got=$this->event_listing_norm($r['name']??'');$s=$got===$want?100:((strlen($want)>=7&&($got!==''&&(strpos($got,$want)!==false||strpos($want,$got)!==false)))?70:0);if($s>$score){$score=$s;$best=$r;}}
        }
        if($score<70&&$street!==''){
            if($house!=='')$r=$wpdb->get_row($wpdb->prepare("SELECT venue_name,street,house_number,postcode,city,lat,lng FROM $events WHERE city=%s AND street=%s AND house_number=%s AND lat IS NOT NULL AND lng IS NOT NULL ORDER BY updated_at DESC LIMIT 1",$city,$street,$house),ARRAY_A);else $r=$wpdb->get_row($wpdb->prepare("SELECT venue_name,street,house_number,postcode,city,lat,lng FROM $events WHERE city=%s AND street=%s AND lat IS NOT NULL AND lng IS NOT NULL ORDER BY updated_at DESC LIMIT 1",$city,$street),ARRAY_A);
            if(!$r){if($house!=='')$r=$wpdb->get_row($wpdb->prepare("SELECT name,street,house_number,postcode,city,lat,lng FROM $places WHERE city=%s AND street=%s AND house_number=%s AND active=1 AND lifecycle_status='active' ORDER BY updated_at DESC LIMIT 1",$city,$street,$house),ARRAY_A);else $r=$wpdb->get_row($wpdb->prepare("SELECT name,street,house_number,postcode,city,lat,lng FROM $places WHERE city=%s AND street=%s AND active=1 AND lifecycle_status='active' ORDER BY updated_at DESC LIMIT 1",$city,$street),ARRAY_A);}
