    private function event_selm_preferred_match_v101102($item) {
        if(!is_array($item))return null;global $wpdb;
        $title=$this->event_listing_norm($item['title']??'');if($title==='')return null;
        $start=$this->event_datetime_mysql($item['start']??'');if(!$start)return null;
        list($street,$house,$zip,$city)=$this->event_address_from_item($item);if($city==='')return null;
        $venue=$this->event_listing_norm($this->event_venue_name_from_item_v1058($item));
        $day=substr($start,0,10);$events=$this->table('events');
        $rows=(array)$wpdb->get_results($wpdb->prepare(
            "SELECT * FROM $events WHERE status='active' AND city=%s AND start_at BETWEEN %s AND %s AND source IN ('open_data_finder','destination_one_open_data','et4','essen_emg_export') ORDER BY start_at ASC,id ASC LIMIT 160",
            $city,$day.' 00:00:00',$day.' 23:59:59'
        ),ARRAY_A);
        $best=null;$bestScore=-1;$bestEvidence=0;$targetTs=strtotime($start);
        foreach($rows as $row){if($this->event_listing_norm($row['title']??'')!==$title)continue;$score=70;$evidence=0;$rv=$this->event_listing_norm($row['venue_name']??'');if($venue!==''&&$rv!==''&&$venue===$rv){$score+=25;$evidence++;}elseif($venue!==''&&$rv!==''&&strlen($venue)>=7&&(strpos($rv,$venue)!==false||strpos($venue,$rv)!==false)){$score+=15;$evidence++;}
            if($street!==''&&$this->event_listing_norm($row['street']??'')===$this->event_listing_norm($street)){$score+=15;$evidence++;if($house!==''&&$this->event_listing_norm($row['house_number']??'')===$this->event_listing_norm($house))$score+=5;}
            $rowTs=strtotime((string)($row['start_at']??''));if($targetTs&&$rowTs){$diff=abs($targetTs-$rowTs);if($diff<=2*HOUR_IN_SECONDS&&empty($item['allDay'])){$score+=10;$evidence++;}elseif($diff>8*HOUR_IN_SECONDS&&!empty($item['allDay']))$score+=3;}
            $rank=$this->event_public_source_rank($row);$score+=max(0,10-$rank/5);if($score>$bestScore){$bestScore=$score;$best=$row;$bestEvidence=$evidence;}
        }
        return ($best&&$bestScore>=80&&$bestEvidence>=1)?$best:null;
    }

    private function event_selm_attach_source_v101102($eventId,$item,$id,$url) {
        if(!$eventId||!is_array($item))return false;global $wpdb;$sources=$this->table('event_sources');$uid='selm:'.preg_replace('/\D+/','',(string)$id);$now=current_time('mysql');$payload=wp_json_encode($item,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES);
        $sid=(int)$wpdb->get_var($wpdb->prepare("SELECT id FROM $sources WHERE event_id=%d AND source_type='calendar' AND source_uid=%s LIMIT 1",(int)$eventId,$uid));
        $data=array('source_name'=>'stadt_selm_calendar','source_url'=>esc_url_raw((string)$url),'raw_payload'=>$payload,'last_seen_at'=>$now);
        if($sid)$wpdb->update($sources,$data,array('id'=>$sid));else{$data=array_merge(array('event_id'=>(int)$eventId,'source_type'=>'calendar','source_uid'=>$uid,'first_seen_at'=>$now),$data);$wpdb->insert($sources,$data);}
        return true;
    }

    private function event_selm_due_seconds_v101102($startAt) {
        $ts=$startAt?strtotime((string)$startAt):0;if(!$ts)return 4*HOUR_IN_SECONDS;$delta=$ts-current_time('timestamp');
        if($delta<=14*DAY_IN_SECONDS)return 4*HOUR_IN_SECONDS;if($delta<=90*DAY_IN_SECONDS)return DAY_IN_SECONDS;return 7*DAY_IN_SECONDS;
    }

    private function event_selm_apply_missing_lifecycle_v101102(&$cache,$seen) {
        global $wpdb;$events=$this->table('events');$now=time();$seen=array_fill_keys(array_map('strval',(array)$seen),1);
        foreach($cache as $id=>&$entry){if(isset($seen[(string)$id]))continue;$entry['missing_count']=(int)($entry['missing_count']??0)+1;if(empty($entry['missing_since']))$entry['missing_since']=current_time('mysql');$entry['source_status']='missing';
            $since=!empty($entry['missing_since'])?strtotime((string)$entry['missing_since']):$now;
            if($entry['missing_count']>=3 && $since && $since<=($now-DAY_IN_SECONDS)){
                $wpdb->query($wpdb->prepare("UPDATE $events SET status='expired',updated_at=%s WHERE source='stadt_selm_calendar' AND external_id=%s AND status='active'",current_time('mysql'),'selm:'.$id));$entry['source_status']='expired';
            }
        }unset($entry);
    }

    public function cron_events_selm_calendar_refresh_v101102() {
        if(get_option(self::OPTION_STATUS)!=='ready')return;
        $state=get_option(self::EVENT_SELM_STATE,array());if(!is_array($state))$state=array();if(($state['status']??'')==='running'){if(!wp_next_scheduled(self::EVENT_SELM_BATCH_HOOK))wp_schedule_single_event(time()+30,self::EVENT_SELM_BATCH_HOOK);return;}
        $busy=$this->event_import_busy_reason_v101101();if($busy!==''){update_option(self::EVENT_SELM_STATE,array('status'=>'waiting','wait_reason'=>$busy,'last_attempt_at'=>current_time('mysql')),false);wp_schedule_single_event(time()+10*MINUTE_IN_SECONDS,self::EVENT_SELM_RETRY_HOOK);return;}
        if(!$this->event_import_lock_acquire_v101101('selm_calendar')){wp_schedule_single_event(time()+10*MINUTE_IN_SECONDS,self::EVENT_SELM_RETRY_HOOK);return;}
        $html=$this->event_selm_fetch_html_v101102('https://www.stadtportal-selm.de/veranstaltungen/');
        if(is_wp_error($html)){update_option(self::EVENT_SELM_STATE,array('status'=>'failed','last_error'=>$html->get_error_message(),'last_attempt_at'=>current_time('mysql')),false);$this->event_import_lock_release_v101101('selm_calendar');return;}
        $links=$this->event_selm_listing_links_v101102($html);if(!$links){update_option(self::EVENT_SELM_STATE,array('status'=>'failed','last_error'=>'Keine Event-Detail-Links im Selm-Kalender erkannt','last_attempt_at'=>current_time('mysql')),false);$this->event_import_lock_release_v101101('selm_calendar');return;}
        global $wpdb;$events=$this->table('events');$sources=$this->table('event_sources');$cache=get_option(self::EVENT_SELM_CACHE,array());if(!is_array($cache))$cache=array();$seen=array();$queue=array();$now=time();$nowMysql=current_time('mysql');$horizonSkipped=0;$horizonMax=current_time('timestamp')+365*DAY_IN_SECONDS;
        foreach($links as $link){$id=(string)$link['id'];$seen[]=$id;$entry=is_array($cache[$id]??null)?$cache[$id]:array();$ext='selm:'.$id;$row=$wpdb->get_row($wpdb->prepare("SELECT id,start_at,status FROM $events WHERE source='stadt_selm_calendar' AND external_id=%s ORDER BY updated_at DESC LIMIT 1",$ext),ARRAY_A);
            $linked=null;if(!$row&&!empty($entry['event_id']))$linked=$wpdb->get_row($wpdb->prepare("SELECT id,start_at,status FROM $events WHERE id=%d LIMIT 1",(int)$entry['event_id']),ARRAY_A);$linkedActive=$linked&&($linked['status']??'')==='active';$known=$row?:($linkedActive?$linked:null);
            $listingStart=$this->event_selm_listing_start_timestamp_v101102((string)($link['listing_text']??''));$outsideHorizon=(!$known&&$listingStart&&$listingStart>$horizonMax);if($outsideHorizon)$horizonSkipped++;
            $lastDetail=(int)($entry['detail_ts']??0);$dueStart=(string)($known['start_at']??($entry['start_at']??''));$due=$this->event_selm_due_seconds_v101102($dueStart);$changed=empty($entry['listing_hash'])||(string)$entry['listing_hash']!==(string)$link['listing_hash'];$needs=!$outsideHorizon&&(!$known||$changed||!$lastDetail||$lastDetail<=($now-$due));
            $entry['listing_hash']=(string)$link['listing_hash'];$entry['url']=(string)$link['url'];$entry['last_seen_at']=$nowMysql;$entry['listing_start_ts']=$listingStart;$entry['missing_count']=0;$entry['missing_since']='';$entry['source_status']=$outsideHorizon?'future_horizon':'active';$cache[$id]=$entry;
            if($row&&($row['status']??'')==='expired')$wpdb->update($events,array('status'=>'active','updated_at'=>$nowMysql),array('id'=>(int)$row['id']));
            if($needs)$queue[]=$link;else if($row)$wpdb->update($events,array('last_seen_at'=>$nowMysql),array('id'=>(int)$row['id']));else if($linkedActive)$wpdb->update($sources,array('last_seen_at'=>$nowMysql),array('event_id'=>(int)$linked['id'],'source_type'=>'calendar','source_uid'=>$ext));
        }
        $this->event_selm_apply_missing_lifecycle_v101102($cache,$seen);update_option(self::EVENT_SELM_CACHE,$cache,false);
        $state=array('status'=>'running','started_at'=>$nowMysql,'last_attempt_at'=>$nowMysql,'last_progress_at'=>$nowMysql,'listing_count'=>count($links),'queued_count'=>count($queue),'horizon_skipped'=>$horizonSkipped,'cursor'=>0,'queue'=>$queue,'seen_ids'=>$seen,'processed'=>0,'inserted'=>0,'updated'=>0,'invalid'=>0,'geo_missing'=>0,'cancelled'=>0,'errors'=>0,'last_error'=>'');
        update_option(self::EVENT_SELM_STATE,$state,false);wp_clear_scheduled_hook(self::EVENT_SELM_BATCH_HOOK);wp_schedule_single_event(time()+2,self::EVENT_SELM_BATCH_HOOK);if(function_exists('spawn_cron'))spawn_cron();
    }

    public function cron_events_selm_calendar_batch_v101102() {
        $state=get_option(self::EVENT_SELM_STATE,array());if(!is_array($state)||($state['status']??'')!=='running')return;
        if(!$this->event_import_lock_acquire_v101101('selm_calendar')){wp_clear_scheduled_hook(self::EVENT_SELM_BATCH_HOOK);wp_schedule_single_event(time()+5*MINUTE_IN_SECONDS,self::EVENT_SELM_BATCH_HOOK);return;}$this->event_import_lock_touch_v101101('selm_calendar');
        $queue=is_array($state['queue']??null)?$state['queue']:array();$cursor=max(0,(int)($state['cursor']??0));$batch=array_slice($queue,$cursor,4);$cache=get_option(self::EVENT_SELM_CACHE,array());if(!is_array($cache))$cache=array();global $wpdb;$events=$this->table('events');
        foreach($batch as $link){$id=(string)($link['id']??'');$url=(string)($link['url']??'');if($id===''||$url===''){$state['invalid']++;$cursor++;continue;}$html=$this->event_selm_fetch_html_v101102($url);if(is_wp_error($html)){$state['errors']++;$state['last_error']=$html->get_error_message();$cursor++;continue;}
            $item=$this->event_selm_detail_item_v101102($id,$url,$html);if(is_wp_error($item)){$state['invalid']++;$state['last_error']=$item->get_error_message();$cursor++;continue;}
            $cancelProbe=mb_strtolower(($item['title']??'').' '.($item['description']??'').' '.wp_json_encode($item['texts']??array()),'UTF-8');$explicitCancelled=(bool)preg_match('/\b(abgesagt|faellt aus|fällt aus|entfaellt|entfällt|cancelled|canceled)\b/u',$cancelProbe);
            $preferred=$this->event_selm_preferred_match_v101102($item);$meta=null;
            if($preferred){$eventId=(int)$preferred['id'];$this->event_selm_attach_source_v101102($eventId,$item,$id,$url);$state['updated']++;}
            else{$eventId=$this->event_upsert_from_feed_item($item,$meta,'municipal:selm');if(!$eventId){$state['invalid']++;$state['last_error']='Selm-Upsert: '.(string)($meta['reason']??'unbekannt');$cursor++;continue;}if(!empty($meta['created']))$state['inserted']++;else $state['updated']++;}
            if($explicitCancelled && !$preferred){$wpdb->update($events,array('status'=>'cancelled','updated_at'=>current_time('mysql')),array('id'=>(int)$eventId));$state['cancelled']++;}
            list($gLat,$gLng)=$this->event_geo_from_item($item);if($gLat===null||$gLng===null)$state['geo_missing']++;
            $entry=is_array($cache[$id]??null)?$cache[$id]:array();$entry['detail_ts']=time();$entry['detail_at']=current_time('mysql');$entry['start_at']=(string)($item['start']??'');$entry['event_id']=(int)$eventId;$entry['source_status']=$explicitCancelled?'cancelled':'active';$entry['missing_count']=0;$entry['missing_since']='';$cache[$id]=$entry;$state['processed']++;$cursor++;
        }
        update_option(self::EVENT_SELM_CACHE,$cache,false);$state['cursor']=$cursor;$state['last_progress_at']=current_time('mysql');
        if($cursor>=count($queue)){$state['status']='finished';$state['finished_at']=current_time('mysql');$state['queue']=array();update_option(self::EVENT_SELM_STATE,$state,false);wp_clear_scheduled_hook(self::EVENT_SELM_BATCH_HOOK);$this->event_import_lock_release_v101101('selm_calendar');return;}
        update_option(self::EVENT_SELM_STATE,$state,false);wp_clear_scheduled_hook(self::EVENT_SELM_BATCH_HOOK);wp_schedule_single_event(time()+20,self::EVENT_SELM_BATCH_HOOK);if(function_exists('spawn_cron'))spawn_cron();
    }

    private function event_sync_next_city($force=false) {
        global $wpdb;$state=get_option('rg_events_sync_state',array());if(!is_array($state))$state=array();
        $last=(int)($state['last_attempt_ts']??0);if(!$force && $last>time()-1800)return array('skipped'=>true,'reason'=>'throttle');
        $muni=$this->table('places_municipalities');$places=$this->table('places');$cities=(array)$wpdb->get_results("SELECT slug,name FROM $muni ORDER BY name ASC",ARRAY_A);if(!$cities)return array('error'=>'Keine Kommunen vorhanden');
        $cursor=(int)($state['cursor']??0);if($cursor>=count($cities))$cursor=0;$tries=0;$chosen=null;$lat=null;$lng=null;
        while($tries<count($cities)){$c=$cities[$cursor];$center=$wpdb->get_row($wpdb->prepare("SELECT AVG(lat) lat,AVG(lng) lng,COUNT(*) n FROM $places WHERE active=1 AND municipality_slug=%s",$c['slug']),ARRAY_A);if($center && (int)$center['n']>0){$chosen=$c;$lat=(float)$center['lat'];$lng=(float)$center['lng'];break;}$cursor=($cursor+1)%count($cities);$tries++;}
        if(!$chosen){$state['last_attempt_ts']=time();$state['last_error']='Keine Stadt mit Places-Koordinaten gefunden';update_option('rg_events_sync_state',$state,false);return array('error'=>$state['last_error']);}
        $state['last_attempt_ts']=time();$state['last_city']=$chosen['name'];$state['last_error']='';update_option('rg_events_sync_state',$state,false);
        if(!function_exists('ruhrpott_guru_event_rest')){$state['last_error']='Theme-Eventquelle nicht verfügbar';update_option('rg_events_sync_state',$state,false);return array('error'=>$state['last_error']);}
        $req=new WP_REST_Request('POST','/ruhrpottguru/v1/events');$req->set_header('content-type','application/json');$req->set_body(wp_json_encode(array('lat'=>$lat,'lng'=>$lng,'city'=>$chosen['name'],'maxRadiusKm'=>25)));
        try{$res=ruhrpott_guru_event_rest($req);$data=$res instanceof WP_REST_Response?$res->get_data():$res;if(!is_array($data)||empty($data['items'])||!is_array($data['items'])){throw new Exception(is_array($data)&&!empty($data['message'])?$data['message']:'Keine Eventdaten');}$count=$this->ingest_event_items($data['items'],'background:'.$chosen['name']);$state['last_count']=$count;$state['last_success_at']=current_time('mysql');$state['last_error']='';}catch(Exception $e){$count=0;$state['last_error']=$e->getMessage();}
        $cursor=($cursor+1)%count($cities);$state['cursor']=$cursor;if($cursor===0)$state['last_round_finished_at']=current_time('mysql');update_option('rg_events_sync_state',$state,false);return array('city'=>$chosen['name'],'count'=>$count,'error'=>$state['last_error']);
    }

    private function event_cache_maintenance_tick() {
        // Places keeps its own 15-minute maintenance. Event source refreshes are intentionally
        // not performed here; v1.10.101 dispatches them through the tiered ET4 queue.
        $this->event_cleanup_expired(false);
    }


    /** V1.10.101: read/clean the cross-wave Event import lock. */
    private function event_import_lock_v101101() {
        $lock=get_option(self::EVENT_IMPORT_LOCK,array());if(!is_array($lock))$lock=array();
        $heartbeat=(int)($lock['heartbeat']??0);
        if($heartbeat && $heartbeat<time()-30*MINUTE_IN_SECONDS){delete_option(self::EVENT_IMPORT_LOCK);return array();}
        return $lock;
    }

    private function event_import_lock_acquire_v101101($owner) {
        $owner=sanitize_key((string)$owner);if($owner==='')return false;
        $lock=$this->event_import_lock_v101101();
        if(!empty($lock)){
            if((string)($lock['owner']??'')===$owner){
                $lock['heartbeat']=time();$lock['heartbeat_at']=current_time('mysql');update_option(self::EVENT_IMPORT_LOCK,$lock,false);return true;
            }
            return false;
        }
        $value=array('owner'=>$owner,'started'=>time(),'started_at'=>current_time('mysql'),'heartbeat'=>time(),'heartbeat_at'=>current_time('mysql'));
        return add_option(self::EVENT_IMPORT_LOCK,$value,'','no');
    }

    private function event_import_lock_touch_v101101($owner) {
        $lock=$this->event_import_lock_v101101();if(!$lock||(string)($lock['owner']??'')!==sanitize_key((string)$owner))return false;
        $lock['heartbeat']=time();$lock['heartbeat_at']=current_time('mysql');update_option(self::EVENT_IMPORT_LOCK,$lock,false);return true;
    }

    private function event_import_lock_release_v101101($owner='') {
        $lock=get_option(self::EVENT_IMPORT_LOCK,array());if(!is_array($lock))$lock=array();
        if($owner!=='' && $lock && (string)($lock['owner']??'')!==sanitize_key((string)$owner))return false;
        delete_option(self::EVENT_IMPORT_LOCK);return true;
    }

    /** Return an explanatory blocker for ET4 source imports, or an empty string. */
    private function event_import_busy_reason_v101101() {
        $night=get_option('rg_events_nightly_state',array());if(is_array($night)&&($night['status']??'')==='running')return '365-Tage-Masterimport läuft';
        $supp=get_option('rg_events_supplemental_state',array());if(is_array($supp)&&($supp['status']??'')==='running')return '53-Städte-Zusatzfeed läuft';
        $tier=get_option(self::EVENT_TIER_STATE,array());if(is_array($tier)&&($tier['status']??'')==='running')return 'ET4-'.(string)($tier['label']??'Kurzrefresh').' läuft';
        $lock=$this->event_import_lock_v101101();if($lock)return 'Import-Lock: '.(string)($lock['owner']??'unbekannt');
        return '';
    }

    private function event_sync_schedule_dispatch_v101101($delay=5) {
        $delay=max(1,(int)$delay);$next=wp_next_scheduled(self::EVENT_TIER_DISPATCH_HOOK);
        if(!$next || $next>time()+$delay+30){wp_clear_scheduled_hook(self::EVENT_TIER_DISPATCH_HOOK);wp_schedule_single_event(time()+$delay,self::EVENT_TIER_DISPATCH_HOOK);}
    }

    private function event_sync_request_v101101($tier,$source='cron') {
        $tier=sanitize_key((string)$tier);if(!in_array($tier,array('hot14','plan90','full365'),true))return false;
        $queue=get_option(self::EVENT_TIER_QUEUE,array());if(!is_array($queue))$queue=array();
        $queue[$tier]=array('requested'=>time(),'requested_at'=>current_time('mysql'),'source'=>sanitize_key((string)$source));
        update_option(self::EVENT_TIER_QUEUE,$queue,false);$this->event_sync_schedule_dispatch_v101101(3);return true;
    }

    public function cron_events_hot_refresh_v101101() {
        $this->event_sync_request_v101101('hot14','schedule');
        if(defined('DOING_CRON')&&DOING_CRON)$this->cron_events_tier_dispatch_v101101();
    }
    public function cron_events_plan_refresh_v101101() {
        $this->event_sync_request_v101101('plan90','schedule');
        if(defined('DOING_CRON')&&DOING_CRON)$this->cron_events_tier_dispatch_v101101();
    }

    /**
     * Central dispatcher: every ET4 source wave is serialized. Existing v1.10.100
     * runs are respected through their persisted state, so installing this build
     * never aborts a 03:00 master or an already-running 53-city supplemental wave.
     */
    public function cron_events_tier_dispatch_v101101() {
        $queue=get_option(self::EVENT_TIER_QUEUE,array());if(!is_array($queue)||!$queue)return;
        if(get_option(self::OPTION_STATUS)!=='ready'){$this->event_sync_schedule_dispatch_v101101(30*MINUTE_IN_SECONDS);return;}
        $busy=$this->event_import_busy_reason_v101101();
        if($busy!==''){
            update_option('rg_events_tier_dispatch_wait_v101101',array('reason'=>$busy,'at'=>current_time('mysql')),false);
            $this->event_sync_schedule_dispatch_v101101(10*MINUTE_IN_SECONDS);return;
        }
        delete_option('rg_events_tier_dispatch_wait_v101101');
        $tier=isset($queue['full365'])?'full365':(isset($queue['plan90'])?'plan90':(isset($queue['hot14'])?'hot14':''));
        if($tier==='')return;
        if(!$this->event_import_lock_acquire_v101101($tier)){$this->event_sync_schedule_dispatch_v101101(5*MINUTE_IN_SECONDS);return;}

        // A broader snapshot satisfies any narrower request that was already queued
        // before this start. New requests arriving during the run remain queued.
        if($tier==='full365'){unset($queue['full365'],$queue['plan90'],$queue['hot14']);}
        elseif($tier==='plan90'){unset($queue['plan90'],$queue['hot14']);}
        else unset($queue['hot14']);
        update_option(self::EVENT_TIER_QUEUE,$queue,false);
        wp_clear_scheduled_hook(self::EVENT_TIER_DISPATCH_HOOK);

        if($tier==='full365'){$this->start_events_full_master_v101101();return;}
        $this->start_event_tier_refresh_v101101($tier);
    }

    private function start_event_tier_refresh_v101101($tier) {
        $tier=sanitize_key((string)$tier);if(!in_array($tier,array('hot14','plan90'),true)){$this->event_import_lock_release_v101101($tier);return;}
        $today=new DateTimeImmutable('today',wp_timezone());
        if($tier==='hot14'){$start=$today;$end=$today->modify('+14 days');$label='0–14 Tage';$prefix='tier14';}
        else{$start=$today->modify('+15 days');$end=$today->modify('+90 days');$label='15–90 Tage';$prefix='tier90';}
        $this->event_master_seen_reset();
        $token=$prefix.'-'.gmdate('YmdHis').'-'.wp_rand(1000,9999);
        $state=array(
            'status'=>'running','tier'=>$tier,'label'=>$label,'context_prefix'=>$prefix,'run_token'=>$token,
            'query_start'=>$start->format('d.m.Y'),'query_end'=>$end->format('d.m.Y'),'offset'=>0,
            'started_at'=>current_time('mysql'),'finished_at'=>'','last_progress_at'=>current_time('mysql'),
            'pages_done'=>0,'raw_seen'=>0,'source_objects_seen'=>0,'occurrences_generated'=>0,
            'events_ingested'=>0,'unique_occurrences'=>0,'unique_external_objects'=>0,
            'inserted'=>0,'updated'=>0,'invalid'=>0,'cancelled'=>0,'errors'=>0,'overall'=>null,'last_error'=>'','lifecycle_missing'=>0,'lifecycle_inactivated'=>0
        );
        update_option(self::EVENT_TIER_STATE,$state,false);
        wp_clear_scheduled_hook(self::EVENT_TIER_BATCH_HOOK);
        $this->cron_events_tier_refresh_batch_v101101();
    }

    public function cron_events_tier_refresh_batch_v101101() {
        $state=get_option(self::EVENT_TIER_STATE,array());if(!is_array($state)||($state['status']??'')!=='running')return;
        $owner=sanitize_key((string)($state['tier']??''));if(!in_array($owner,array('hot14','plan90'),true))return;
        if(!$this->event_import_lock_acquire_v101101($owner)){
            wp_clear_scheduled_hook(self::EVENT_TIER_BATCH_HOOK);wp_schedule_single_event(time()+300,self::EVENT_TIER_BATCH_HOOK);return;
        }
        $this->event_import_lock_touch_v101101($owner);
        if(!$this->event_master_batch_lock_acquire()){
            wp_clear_scheduled_hook(self::EVENT_TIER_BATCH_HOOK);wp_schedule_single_event(time()+60,self::EVENT_TIER_BATCH_HOOK);return;
        }
        wp_clear_scheduled_hook(self::EVENT_TIER_BATCH_HOOK);wp_schedule_single_event(time()+240,self::EVENT_TIER_BATCH_HOOK);
        try{
            $r=$this->event_sync_master_page(
                true,(string)($state['run_token']??''),(string)($state['query_start']??''),(string)($state['query_end']??''),
                (string)($state['context_prefix']??'tier14'),(int)($state['offset']??0),false
            );
            if(!empty($r['error'])){
                $state['errors']=(int)($state['errors']??0)+1;$state['last_error']=(string)$r['error'];$state['last_attempt_at']=current_time('mysql');
                if($state['errors']>=5){
                    $state['status']='failed';$state['finished_at']=current_time('mysql');update_option(self::EVENT_TIER_STATE,$state,false);
                    wp_clear_scheduled_hook(self::EVENT_TIER_BATCH_HOOK);$this->event_master_seen_clear();$this->event_import_lock_release_v101101($owner);$this->event_sync_schedule_dispatch_v101101(30);return;
                }
                update_option(self::EVENT_TIER_STATE,$state,false);wp_clear_scheduled_hook(self::EVENT_TIER_BATCH_HOOK);wp_schedule_single_event(time()+180,self::EVENT_TIER_BATCH_HOOK);return;
            }
            $state['pages_done']=(int)($state['pages_done']??0)+1;
            $state['raw_seen']=(int)($state['raw_seen']??0)+(int)($r['raw_count']??0);
            $state['occurrences_generated']=(int)($state['occurrences_generated']??0)+(int)($r['occurrences_generated']??0);
            $state['events_ingested']=(int)($state['events_ingested']??0)+(int)($r['count']??0);
            $state['offset']=(int)($r['next_offset']??0);$state['overall']=$r['overall']??null;$state['last_progress_at']=current_time('mysql');
            $ing=is_array($r['ingest']??null)?$r['ingest']:array();
            $state['inserted']=(int)($state['inserted']??0)+(int)($ing['inserted']??0);
            $state['updated']=(int)($state['updated']??0)+(int)($ing['updated']??0);
            $state['invalid']=(int)($state['invalid']??0)+(int)($ing['invalid']??0);$state['cancelled']=(int)($state['cancelled']??0)+(int)($ing['cancelled_created']??0)+(int)($r['explicit_cancelled']??0);
            $seen=is_array($r['seen']??null)?$r['seen']:array();
            $state['unique_occurrences']=(int)($seen['unique_occurrences_total']??($state['unique_occurrences']??0));
            $state['unique_external_objects']=(int)($seen['unique_external_objects_total']??($state['unique_external_objects']??0));
            $sd=is_array($r['source_dedupe']??null)?$r['source_dedupe']:array();$state['source_objects_seen']=(int)($sd['unique_source_objects_total']??($state['source_objects_seen']??0));
            $state['last_error']='';
            if(!empty($r['done'])){
                $life=$this->event_apply_missing_lifecycle_v101125((string)($state['run_token']??''),(string)($state['query_start']??''),(string)($state['query_end']??''),array('open_data_finder','et4'),(string)($state['tier']??'tier'));
                $state['lifecycle_missing']=(int)($life['missing']??0);$state['lifecycle_inactivated']=(int)($life['inactivated']??0);$state['lifecycle_seen']=(int)($life['seen']??0);
                $state['status']='finished';$state['finished_at']=current_time('mysql');$state['offset']=0;
                update_option(self::EVENT_TIER_STATE,$state,false);update_option('rg_events_tier_last_complete_v101101',$state,false);
                wp_clear_scheduled_hook(self::EVENT_TIER_BATCH_HOOK);$this->event_master_seen_clear();$this->event_cleanup_expired(true);
                $this->event_import_lock_release_v101101($owner);$this->event_sync_schedule_dispatch_v101101(10);return;
            }
            update_option(self::EVENT_TIER_STATE,$state,false);wp_clear_scheduled_hook(self::EVENT_TIER_BATCH_HOOK);wp_schedule_single_event(time()+60,self::EVENT_TIER_BATCH_HOOK);
        }finally{$this->event_master_batch_lock_release();}
    }

    public function ensure_event_tier_worker_v101101() {
        if(defined('DOING_CRON')&&DOING_CRON)return;
        $state=get_option(self::EVENT_TIER_STATE,array());if(!is_array($state))$state=array();
        if(($state['status']??'')==='running'){
            $owner=sanitize_key((string)($state['tier']??''));
            $lock=$this->event_import_lock_v101101();
            if(!$lock && in_array($owner,array('hot14','plan90'),true))$this->event_import_lock_acquire_v101101($owner);
            $next=wp_next_scheduled(self::EVENT_TIER_BATCH_HOOK);
            $last=!empty($state['last_progress_at'])?strtotime((string)$state['last_progress_at']):0;
            $stale=$last>0&&$last<time()-15*MINUTE_IN_SECONDS;
            if(!$next || $next<time()-30 || $stale){
                wp_clear_scheduled_hook(self::EVENT_TIER_BATCH_HOOK);wp_schedule_single_event(time()+3,self::EVENT_TIER_BATCH_HOOK);
                if(function_exists('spawn_cron'))spawn_cron();
            }
            return;
        }
        $queue=get_option(self::EVENT_TIER_QUEUE,array());if(is_array($queue)&&$queue)$this->event_sync_schedule_dispatch_v101101(5);
    }

    /**
     * Start the proven 0–365 day master unchanged at data-path level. The only
     * architectural change is that it is now dispatched through the collision guard
     * and scheduled weekly instead of daily.
     */
    private function start_events_full_master_v101101() {
        if(get_option(self::OPTION_STATUS)!=='ready'){
            update_option('rg_events_nightly_state',array('status'=>'skipped','started_at'=>current_time('mysql'),'finished_at'=>current_time('mysql'),'reason'=>'Places-Katalog noch nicht bereit'),false);
            $this->event_import_lock_release_v101101('full365');return;
        }
        wp_clear_scheduled_hook(self::EVENT_NIGHTLY_BATCH_HOOK);wp_clear_scheduled_hook(self::EVENT_ENRICH_BATCH_HOOK);
        $sync=get_option('rg_events_sync_state',array());if(!is_array($sync))$sync=array();$sync['master_offset']=0;$sync['last_attempt_ts']=0;$sync['last_error']='';update_option('rg_events_sync_state',$sync,false);
        $this->event_master_seen_reset();
        $rangeStart=new DateTimeImmutable('today',wp_timezone());$rangeEnd=$rangeStart->modify('+365 days');$runToken='master-'.gmdate('YmdHis').'-'.wp_rand(1000,9999);
        update_option('rg_events_nightly_state',array('status'=>'running','mode'=>'metropole-master-unique-local-expansion-weekly','run_token'=>$runToken,'audit_mode'=>'exact-token-local-v174','query_start'=>$rangeStart->format('d.m.Y'),'query_end'=>$rangeEnd->format('d.m.Y'),'started_at'=>current_time('mysql'),'finished_at'=>'','last_progress_at'=>current_time('mysql'),'pages_done'=>0,'raw_seen'=>0,'source_objects_seen'=>0,'unrolled_repeat_rows'=>0,'occurrences_generated'=>0,'recurring_source_objects'=>0,'source_objects_without_occurrence'=>0,'events_ingested'=>0,'unique_occurrences'=>0,'duplicate_occurrences'=>0,'unique_external_objects'=>0,'inserted'=>0,'updated'=>0,'invalid'=>0,'cancelled'=>0,'errors'=>0,'lifecycle_missing'=>0,'lifecycle_inactivated'=>0,'overall'=>null,'overall_first'=>null,'overall_last'=>null,'overall_min'=>null,'overall_max'=>null,'overall_changes'=>0,'last_offset'=>0,'last_page_count'=>0,'last_generated_count'=>0,'last_overrun'=>0),false);
        $this->event_cleanup_expired(true);$this->cron_events_nightly_refresh_batch();
    }

    public function cron_events_nightly_refresh() {
