    public function cron_events_nightly_refresh_batch() {
        $night=get_option('rg_events_nightly_state',array());
        if(!is_array($night)||($night['status']??'')!=='running'){
            $this->event_import_lock_release_v101101('full365');return;
        }
        // Upgrade-safe: an already-running pre-v1.10.101 master gets ownership here
        // instead of being cancelled or reset during installation.
        if(!$this->event_import_lock_acquire_v101101('full365')){
            wp_clear_scheduled_hook(self::EVENT_NIGHTLY_BATCH_HOOK);wp_schedule_single_event(time()+300,self::EVENT_NIGHTLY_BATCH_HOOK);return;
        }
        $this->event_import_lock_touch_v101101('full365');
        if(!$this->event_master_batch_lock_acquire())return;
        // Safety retry is scheduled BEFORE the remote ET4 call. If PHP or HTTP dies hard,
        // the master run therefore cannot remain "running" without a future worker forever.
        wp_clear_scheduled_hook(self::EVENT_NIGHTLY_BATCH_HOOK);wp_schedule_single_event(time()+240,self::EVENT_NIGHTLY_BATCH_HOOK);
        try{
            $this->event_master_recover_run_token($night);
            $r=$this->event_sync_master_page(true,(string)($night['run_token']??''),(string)($night['query_start']??''),(string)($night['query_end']??''));
            $night['last_offset']=(int)($r['offset']??0);$night['last_page_count']=(int)($r['raw_count']??0);$night['last_generated_count']=(int)($r['occurrences_generated']??0);$night['last_overrun']=(int)($r['overrun']??0);
            if(!empty($r['error'])){
                $night['errors']=(int)($night['errors']??0)+1;$night['last_error']=(string)$r['error'];
                $night['last_attempt_at']=current_time('mysql');
                wp_clear_scheduled_hook(self::EVENT_NIGHTLY_BATCH_HOOK);
                if($night['errors']>=5){$night['status']='failed';$night['finished_at']=current_time('mysql');update_option('rg_events_nightly_state',$night,false);$this->event_import_lock_release_v101101('full365');$this->event_sync_schedule_dispatch_v101101(30);return;}
                update_option('rg_events_nightly_state',$night,false);wp_schedule_single_event(time()+180,self::EVENT_NIGHTLY_BATCH_HOOK);return;
            }
            // Only successful ET4 pages count as processed pages. Failed retries are attempts, not pages.
            $night['pages_done']=(int)($night['pages_done']??0)+1;
            $night['raw_seen']=(int)($night['raw_seen']??0)+(int)($r['raw_count']??0);$sd=is_array($r['source_dedupe']??null)?$r['source_dedupe']:array();$night['source_objects_seen']=(int)($sd['unique_source_objects_total']??($night['source_objects_seen']??0));$night['unrolled_repeat_rows']=max(0,(int)$night['raw_seen']-(int)$night['source_objects_seen']);
            $night['occurrences_generated']=(int)($night['occurrences_generated']??0)+(int)($r['occurrences_generated']??0);$exp=is_array($r['expand']??null)?$r['expand']:array();$night['recurring_source_objects']=(int)($night['recurring_source_objects']??0)+(int)($exp['recurring_source_objects']??0);$night['source_objects_without_occurrence']=(int)($night['source_objects_without_occurrence']??0)+(int)($exp['source_objects_without_occurrence']??0);
            $night['events_ingested']=(int)($night['events_ingested']??0)+(int)($r['count']??0);
            $night['last_progress_at']=current_time('mysql');
            $ing=is_array($r['ingest']??null)?$r['ingest']:array();
            $night['inserted']=(int)($night['inserted']??0)+(int)($ing['inserted']??0);
            $night['updated']=(int)($night['updated']??0)+(int)($ing['updated']??0);
            $night['invalid']=(int)($night['invalid']??0)+(int)($ing['invalid']??0);$night['cancelled']=(int)($night['cancelled']??0)+(int)($ing['cancelled_created']??0)+(int)($r['explicit_cancelled']??0);
            if(isset($r['overall'])&&$r['overall']!==null){$ov=(int)$r['overall'];if($night['overall_first']===null)$night['overall_first']=$ov;if($night['overall_last']!==null&&(int)$night['overall_last']!==$ov)$night['overall_changes']=(int)($night['overall_changes']??0)+1;$night['overall_last']=$ov;$night['overall']=$ov;$night['overall_min']=$night['overall_min']===null?$ov:min((int)$night['overall_min'],$ov);$night['overall_max']=$night['overall_max']===null?$ov:max((int)$night['overall_max'],$ov);}
            $seen=is_array($r['seen']??null)?$r['seen']:array();$night['unique_occurrences']=(int)($seen['unique_occurrences_total']??($night['unique_occurrences']??0));$night['unique_external_objects']=(int)($seen['unique_external_objects_total']??($night['unique_external_objects']??0));$night['duplicate_occurrences']=max(0,(int)$night['occurrences_generated']-(int)$night['unique_occurrences']);
            $night['last_error']='';
            if(!empty($r['done'])){
                $life=$this->event_apply_missing_lifecycle_v101125((string)($night['run_token']??''),(string)($night['query_start']??''),(string)($night['query_end']??''),array('open_data_finder','et4'),'full365');
                $night['lifecycle_missing']=(int)($life['missing']??0);$night['lifecycle_inactivated']=(int)($life['inactivated']??0);$night['lifecycle_seen']=(int)($life['seen']??0);
                $night['status']='finished';$night['finished_at']=current_time('mysql');$night['raw_minus_overall']=$night['overall_last']!==null?(int)$night['raw_seen']-(int)$night['overall_last']:null;
                $audit=$this->event_master_db_window_audit($night);$night['db_unique_touched']=(int)($audit['unique_touched']??0);$night['db_active_touched']=(int)($audit['active_touched']??0);$night['unique_occurrences']=$night['db_unique_touched'];$night['unique_external_objects']=(int)($audit['unique_external_objects']??0);$night['duplicate_occurrences']=max(0,(int)($night['occurrences_generated']??$night['events_ingested'])-(int)$night['unique_occurrences']);
                update_option('rg_events_nightly_state',$night,false);wp_clear_scheduled_hook(self::EVENT_NIGHTLY_BATCH_HOOK);$this->event_master_seen_clear();update_option('rg_events_last_complete_nightly_at',time(),false);$this->event_cleanup_expired(true);
                // V1.10.22: every completed nightly occurrence import gets a fresh canonical-media
                // reconciliation, so newly added ET4 events never depend on a one-time migration.
                delete_option(self::EVENT_CATALOG_MEDIA_DONE);delete_option(self::EVENT_CATALOG_MEDIA_STATE);wp_clear_scheduled_hook(self::EVENT_CATALOG_MEDIA_HOOK);$this->ensure_et4_catalog_media_backfill_v1022();
                $this->start_event_supplemental_wave((string)($night['run_token']??''));
                $this->event_sync_schedule_dispatch_v101101(30);return;
            }
            update_option('rg_events_nightly_state',$night,false);wp_clear_scheduled_hook(self::EVENT_NIGHTLY_BATCH_HOOK);wp_schedule_single_event(time()+60,self::EVENT_NIGHTLY_BATCH_HOOK);
        }finally{$this->event_master_batch_lock_release();}
    }

    /** V1.10.61: normalize series/family labels for safe matching. */
    private function event_family_norm_v1061($value) {
        return $this->event_listing_norm((string)$value);
    }

    /**
     * Read explicit ET4/destination.one parent/series relations without assuming
     * one fixed provider schema. Only relation-shaped branches are considered;
     * generic IDs elsewhere in the payload are deliberately ignored.
     */
    private function event_family_explicit_meta_v1061($raw) {
        $meta=array('ids'=>array(),'labels'=>array());
        if(!is_array($raw))return $meta;
        $idKeys=array('seriesid','series_id','eventseriesid','event_series_id','parentid','parent_id','super_event_id','supereventid','maineventid','main_event_id','collectionid','collection_id','festivalid','festival_id');
        $labelKeys=array('seriesname','series_name','eventseries','event_series','parentname','parent_name','super_event','superevent','main_event','mainevent','collection','festival','ispartof','part_of','partof');
        $relPattern='/(?:series|event[ _-]?series|parent|super[ _-]?event|main[ _-]?event|part[ _-]?of|ispartof|festival|collection|veranstaltungsreihe|reihe)/i';
        $walk=function($node,$depth=0,$parent='') use (&$walk,&$meta,$idKeys,$labelKeys,$relPattern){
            if($depth>6||!is_array($node))return;
            $rel='';foreach(array('rel','relation','type','kind','role') as $rk){if(isset($node[$rk])&&!is_array($node[$rk])){$rel=strtolower(trim((string)$node[$rk]));if($rel!=='')break;}}
            $relationNode=$rel!==''&&preg_match($relPattern,$rel);
            foreach($node as $key=>$value){
                $nk=strtolower(preg_replace('/[^a-z0-9_]+/','',remove_accents((string)$key)));
                if(!is_array($value)){
                    $v=trim(wp_strip_all_tags((string)$value));if($v==='')continue;
                    if(in_array($nk,$idKeys,true) || ($relationNode&&in_array($nk,array('id','global_id','globalid','uid','identifier','key'),true))){
                        if(strlen($v)<=190)$meta['ids'][$this->event_family_norm_v1061($v)]=1;
                    }
                    if(in_array($nk,$labelKeys,true) || ($relationNode&&in_array($nk,array('name','title','label'),true))){
                        if(preg_match('~^https?://~i',$v)){if(strlen($v)<=500)$meta['ids'][$this->event_family_norm_v1061($v)]=1;}
                        elseif(mb_strlen($v)<=255)$meta['labels'][$this->event_family_norm_v1061($v)]=$v;
                    }
                }
            }
            foreach($node as $key=>$value){if(!is_array($value))continue;$walk($value,$depth+1,(string)$key);}
        };
        $walk($raw,0,'');
        return $meta;
    }

    private function event_family_organizer_keys_v1061($row) {
        $out=array();
        foreach($this->event_current_organizers_from_row_v1063($row) as $org){
            if(!is_array($org))continue;$name=trim((string)($org['name']??($org['company']??'')));$n=$this->event_family_norm_v1061($name);if($n!=='')$out[$n]=1;
        }
        return $out;
    }

    private function event_family_title_base_v1061($title) {
        $title=trim(wp_strip_all_tags((string)$title));if($title==='')return array('norm'=>'','label'=>'','delimited'=>false);
        $parts=preg_split('/\s*(?:\||–|—|:|\s-\s)\s*/u',$title,2);
        $label=trim((string)($parts[0]??$title));$delimited=count($parts)>1;
        $norm=$this->event_family_norm_v1061($label);
        // Remove only unmistakable part numbering at the end; ordinary words remain.
        $norm=preg_replace('/\b(?:konzert|teil|folge|session|termin|tag|abend|matinee)\s+(?:[ivxlcdm]+|\d{1,3})$/i','',trim((string)$norm));
        $norm=trim(preg_replace('/\s+/',' ',$norm));
        return array('norm'=>$norm,'label'=>$label,'delimited'=>$delimited);
    }

    private function event_family_common_prefix_v1061($titleA,$titleB) {
        $a=$this->event_family_norm_v1061($titleA);$b=$this->event_family_norm_v1061($titleB);
        if($a===''||$b==='')return array('norm'=>'','tokens'=>0,'label'=>'');
        $aa=preg_split('/\s+/',$a);$bb=preg_split('/\s+/',$b);$common=array();$max=min(count($aa),count($bb));
        for($i=0;$i<$max;$i++){if($aa[$i]!==$bb[$i])break;$common[]=$aa[$i];}
        $norm=implode(' ',$common);$label='';
        if($common){$orig=preg_split('/\s+/u',trim(wp_strip_all_tags((string)$titleA)));$label=implode(' ',array_slice($orig,0,count($common)));$label=preg_replace('/[\s|:–—-]+$/u','',trim((string)$label));}
        return array('norm'=>$norm,'tokens'=>count($common),'label'=>$label);
    }

    private function event_family_has_series_cue_v1061($norm) {
        return (bool)preg_match('/\b(festival|festspiele|orgelherbst|orgelzyklus|zyklus|reihe|veranstaltungsreihe|on ice|kulturnacht|nacht der|sommerkino|winterzauber|winterwelt|weihnachtsmarkt|advent|tage|wochen|triennale|biennale|extraschicht)\b/i',(string)$norm);
    }

    /** Returns a high-confidence family match, or null. */
    private function event_family_match_v1061($current,$candidate,$currentExplicit=array()) {
        if(!is_array($current)||!is_array($candidate))return null;
        if((int)($current['id']??0)===(int)($candidate['id']??0))return null;
        $curTitle=$this->event_family_norm_v1061($current['title']??'');$canTitle=$this->event_family_norm_v1061($candidate['title']??'');
        if($curTitle===''||$canTitle===''||$curTitle===$canTitle)return null;
        // Same external_id is another occurrence of the same logical event, not a sibling event.
        $curExt=trim((string)($current['external_id']??''));$canExt=trim((string)($candidate['external_id']??''));
        if($curExt!==''&&$canExt!==''&&$curExt===$canExt)return null;
        $raw=json_decode((string)($candidate['raw_payload']??''),true);if(!is_array($raw))$raw=array();
        $explicit=$this->event_family_explicit_meta_v1061($raw);
        $sharedIds=array_intersect_key((array)($currentExplicit['ids']??array()),(array)($explicit['ids']??array()));
        $sharedLabels=array_intersect_key((array)($currentExplicit['labels']??array()),(array)($explicit['labels']??array()));
        if($sharedIds||$sharedLabels){
            $label='';if($sharedLabels){$k=array_key_first($sharedLabels);$label=(string)($currentExplicit['labels'][$k]??$explicit['labels'][$k]??'');}
            if($label===''){$prefix=$this->event_family_common_prefix_v1061($current['title']??'',$candidate['title']??'');$label=$prefix['label']?:trim((string)($current['title']??''));}
            return array('score'=>100,'label'=>$label,'reason'=>'explicit-et4-relation');
        }
        // Heuristic families are deliberately local and time-bounded.
        $cityA=$this->event_family_norm_v1061($current['city']??'');$cityB=$this->event_family_norm_v1061($candidate['city']??'');if($cityA===''||$cityA!==$cityB)return null;
        $ta=strtotime((string)($current['start_at']??''));$tb=strtotime((string)($candidate['start_at']??''));if(!$ta||!$tb)return null;$days=abs($ta-$tb)/DAY_IN_SECONDS;if($days>150)return null;
        $baseA=$this->event_family_title_base_v1061($current['title']??'');$baseB=$this->event_family_title_base_v1061($candidate['title']??'');$prefix=$this->event_family_common_prefix_v1061($current['title']??'',$candidate['title']??'');
        $score=0;$label='';$baseExact=$baseA['norm']!==''&&$baseA['norm']===$baseB['norm']&&mb_strlen($baseA['norm'])>=8;
        $baseTokenCount=$baseA['norm']!==''?count(preg_split('/\s+/',$baseA['norm'])):0;$baseCue=$this->event_family_has_series_cue_v1061($baseA['norm']);
        if($baseExact&&($baseTokenCount>=3||$baseCue)){$score+=55;$label=$baseA['label'];}
        elseif($prefix['tokens']>=3 && mb_strlen($prefix['norm'])>=10){$score+=45+min(15,max(0,$prefix['tokens']-3)*5);$label=$prefix['label'];}
        else return null;
        $venueA=$this->event_family_norm_v1061($current['venue_name']??'');$venueB=$this->event_family_norm_v1061($candidate['venue_name']??'');$sameVenue=$venueA!==''&&$venueA===$venueB;
        $orgA=$this->event_family_organizer_keys_v1061($current);$orgB=$this->event_family_organizer_keys_v1061($candidate);$sameOrg=(bool)array_intersect_key($orgA,$orgB);
        if($sameOrg)$score+=20;if($sameVenue)$score+=15;if($days<=45)$score+=10;elseif($days<=90)$score+=7;else $score+=3;
        if($this->event_family_has_series_cue_v1061($baseExact?$baseA['norm']:$prefix['norm']))$score+=10;
        $labelNorm=$this->event_family_norm_v1061($label);
        // A venue/organizer name alone must never manufacture a series.
        if($labelNorm!=='' && ($labelNorm===$venueA || isset($orgA[$labelNorm])))return null;
        if(!$sameOrg&&!$sameVenue&&!$this->event_family_has_series_cue_v1061($labelNorm))return null;
        if($score<75)return null;
        return array('score'=>$score,'label'=>$label,'reason'=>'high-confidence-title-family');
    }

    /** Read-only global family endpoint, evaluated only when a detail view opens. */
    public function rest_event_related_v1061(WP_REST_Request $request) {
        global $wpdb;$eventId=absint($request['id']);if(!$eventId)return new WP_REST_Response(array('ok'=>false,'message'=>'Ungültige Event-ID'),400);
        $events=$this->table('events');$current=$wpdb->get_row($wpdb->prepare("SELECT * FROM $events WHERE id=%d LIMIT 1",$eventId),ARRAY_A);
        if(!$current)return new WP_REST_Response(array('ok'=>false,'message'=>'Event nicht gefunden'),404);
        $currentRaw=json_decode((string)($current['raw_payload']??''),true);if(!is_array($currentRaw))$currentRaw=array();$explicit=$this->event_family_explicit_meta_v1061($currentRaw);
        $ts=strtotime((string)($current['start_at']??''));if(!$ts)$ts=current_time('timestamp');
        $from=date('Y-m-d H:i:s',$ts-180*DAY_IN_SECONDS);$to=date('Y-m-d H:i:s',$ts+180*DAY_IN_SECONDS);$now=current_time('mysql');

        // 1.10.74: concrete occurrences of the SAME ET4 global_id are not sibling
        // events, but they must be selectable in the detail view for share/calendar.
        $sameOccurrences=array();$external=trim((string)($current['external_id']??''));$currentSource=(string)($current['source']??'');
        if($external!==''){
            $same=(array)$wpdb->get_results($wpdb->prepare(
                "SELECT * FROM $events WHERE id<>%d AND status='active' AND external_id=%s AND source=%s AND start_at BETWEEN %s AND %s AND (end_at IS NULL OR end_at >= %s) ORDER BY start_at ASC,id ASC LIMIT 120",
                $eventId,$external,$currentSource,$from,$to,$now
            ),ARRAY_A);
            $seenOccurrence=array();
            foreach($same as $r){
                $r=$this->event_apply_curated_visitor_data_to_row($r);
                $key=(string)($r['start_at']??'').'|'.(string)($r['end_at']??'');if(isset($seenOccurrence[$key]))continue;$seenOccurrence[$key]=1;
                $sameOccurrences[]=$r;
            }
        }

        // Family/sibling events stay conservative and explicitly exclude same-global-id rows.
        if(!empty($explicit['ids'])||!empty($explicit['labels'])){
            $sql=$wpdb->prepare("SELECT * FROM $events WHERE id<>%d AND status='active' AND start_at BETWEEN %s AND %s AND (end_at IS NULL OR end_at >= %s) ORDER BY start_at ASC LIMIT 1200",$eventId,$from,$to,$now);
        }else{
            $sql=$wpdb->prepare("SELECT * FROM $events WHERE id<>%d AND status='active' AND city=%s AND start_at BETWEEN %s AND %s AND (end_at IS NULL OR end_at >= %s) ORDER BY start_at ASC LIMIT 500",$eventId,(string)$current['city'],$from,$to,$now);
        }
        $candidates=(array)$wpdb->get_results($sql,ARRAY_A);$matched=array();$labels=array();$reasons=array();$bestScore=0;
        foreach($candidates as $cand){$m=$this->event_family_match_v1061($current,$cand,$explicit);if(!$m)continue;$cand['_rpg_family_score']=(int)$m['score'];$matched[]=$this->event_apply_curated_visitor_data_to_row($cand);if(!empty($m['label']))$labels[]=(string)$m['label'];$reasons[(string)$m['reason']]=1;$bestScore=max($bestScore,(int)$m['score']);}
        if($matched)$matched=$this->event_listing_cluster_rows($matched);
        $seen=array();$unique=array();foreach($matched as $r){$k=$this->event_family_norm_v1061($r['title']??'').'|'.substr((string)($r['start_at']??''),0,10);if(isset($seen[$k]))continue;$seen[$k]=1;$unique[]=$r;}
        usort($unique,function($a,$b){return strtotime((string)($a['start_at']??''))<=>strtotime((string)($b['start_at']??''));});
        $label='';foreach($labels as $candidateLabel){$candidateLabel=trim($candidateLabel);if($candidateLabel!==''&&($label===''||mb_strlen($candidateLabel)<mb_strlen($label)))$label=$candidateLabel;}
        if($label==='')$label=trim((string)$current['title']);

        $items=array();
        foreach(array_slice($sameOccurrences,0,24) as $r){
            $items[]=array('eventId'=>(int)$r['id'],'title'=>(string)$r['title'],'start'=>$this->event_visitor_datetime_iso((string)$r['start_at'],$r),'end'=>$this->event_visitor_datetime_iso((string)($r['end_at']??''),$r),'allDay'=>$this->event_all_day_from_row_v1063($r,(array)json_decode((string)($r['raw_payload']??''),true)),'venueName'=>(string)$r['venue_name'],'city'=>(string)$r['city'],'category'=>(string)$r['event_category'],'canonicalUrl'=>$this->event_canonical_share_url_v1057((int)$r['id'],(string)$r['title'],(string)($r['city']??'')),'relation'=>'same-event-occurrence');
        }
        foreach(array_slice($unique,0,max(0,24-count($items))) as $r){
            $items[]=array('eventId'=>(int)$r['id'],'title'=>(string)$r['title'],'start'=>$this->event_visitor_datetime_iso((string)$r['start_at'],$r),'end'=>$this->event_visitor_datetime_iso((string)($r['end_at']??''),$r),'allDay'=>$this->event_all_day_from_row_v1063($r,(array)json_decode((string)($r['raw_payload']??''),true)),'venueName'=>(string)$r['venue_name'],'city'=>(string)$r['city'],'category'=>(string)$r['event_category'],'canonicalUrl'=>$this->event_canonical_share_url_v1057((int)$r['id'],(string)$r['title'],(string)($r['city']??'')),'relation'=>'series-family');
        }
        if(!$items)return rest_ensure_response(array('ok'=>true,'series'=>null,'count'=>0,'occurrenceCount'=>0,'familyCount'=>0,'items'=>array()));
        $seriesKey=sha1($this->event_family_norm_v1061($label).'|'.$this->event_family_norm_v1061($current['city']??''));
        $reason=$unique?implode(',',array_keys($reasons)):'same-global-id-occurrence';
        return rest_ensure_response(array('ok'=>true,'series'=>array('key'=>$seriesKey,'label'=>$label,'confidence'=>$unique?$bestScore:100,'reason'=>$reason),'count'=>count($items),'occurrenceCount'=>count($sameOccurrences),'familyCount'=>count($unique),'items'=>$items));
    }

    /**
     * V1.6.3: Frontend read model for events.
     *
     * The database only becomes authoritative after at least one complete 53-city
     * nightly wave. During the first bootstrap (or if the cache becomes stale)
     * the theme keeps its proven live Open-Data-Finder transport as fallback.
     */

    public function frontend_events_query($lat, $lng, $radius_km = 50.0, $city = '') {
        global $wpdb;
        $lat = (float)$lat; $lng = (float)$lng;
        $radius_km = min(50.0, max(1.0, (float)$radius_km));
        $last_complete = (int)get_option('rg_events_last_complete_nightly_at', 0);
        $fresh_complete = $last_complete > 0 && $last_complete >= time() - (48 * HOUR_IN_SECONDS);
        $last_ingest = get_option('rg_events_last_ingest', array());
        if (!is_array($last_ingest)) $last_ingest = array();
        $last_ingest_ts = (int)($last_ingest['timestamp'] ?? 0);
        $fresh_ingest = $last_ingest_ts > 0 && $last_ingest_ts >= time() - (48 * HOUR_IN_SECONDS);
        $events = $this->table('events');
        $media = $this->table('event_media');
        $active_count = (int)$wpdb->get_var("SELECT COUNT(*) FROM $events WHERE status='active'");

        // V1.6.11: Do not block the fast DB path until the first complete 53-city
        // wave. A recent ingest already proves that the persistent cache is alive.
        // For regions not yet present in a bootstrap cache, we still fall back to
        // the licensed live transport below by returning ready=false after the
        // local DB query yields no rows.
        // V1.10.34: freshness controls refresh scheduling, not whether already-valid
        // current DB rows are allowed to reach visitors. The old 48h hard gate made
        // the public endpoint abandon 1,787 verified DB media links and fall back to
        // sparse live ET4 occurrence rows. Query the DB whenever the catalog is mature;
        // only a genuine local miss may fall through to the live bootstrap transport.
        if ($active_count < 100) {
            return array(
                'ok' => true, 'ready' => false, 'items' => array(),
                'meta' => array(
                    'source'=>'event-db','activeCount'=>$active_count,
                    'lastCompleteNightlyAt'=>$last_complete,'lastIngestAt'=>$last_ingest_ts,
                    'reason'=>'db-not-mature'
                )
            );
        }
        $db_fresh = ($fresh_complete || $fresh_ingest);
        if (!$db_fresh) {
            $night = get_option('rg_events_nightly_state', array());
            if (!is_array($night)) $night = array();
            $last_trigger = (int)get_option('rg_events_stale_refresh_trigger_v1034', 0);
            if (($night['status'] ?? '') !== 'running' && $last_trigger < time() - 1800) {
                update_option('rg_events_stale_refresh_trigger_v1034', time(), false);
                $this->event_sync_request_v101101('hot14','stale-cache');
                if (function_exists('spawn_cron')) spawn_cron();
            }
        }

        $lat_delta = $radius_km / 111.0;
        $cos = cos(deg2rad(max(-89.0, min(89.0, $lat))));
        $lng_delta = $radius_km / (111.0 * max(0.15, abs($cos)));
        $min_lat=$lat-$lat_delta; $max_lat=$lat+$lat_delta;
        $min_lng=$lng-$lng_delta; $max_lng=$lng+$lng_delta;
        $now = current_time('mysql');

        // V1.10.85: radius-monotone DB path.
        //
        // The old implementation selected full Event rows ORDER BY start_at and
        // applied LIMIT 800 BEFORE the exact Haversine test. In dense areas a
        // larger radius therefore enlarged the bounding-box candidate pool enough
        // that nearby, later-starting rows could fall behind row 800 and disappear
        // at 10 km even though the same event was present at 5 km.
        //
        // Keep the shared-hosting-friendly PHP Haversine calculation, but make the
        // spatial decision before any result cap: fetch only lightweight point
        // columns for the complete bounding box, retain every exact in-radius ID,
        // then hydrate full rows only for those IDs in bounded chunks. This keeps
        // memory/DB transfer controlled without making membership depend on radius
        // density or event start order.
        $point_sql = $wpdb->prepare(
            "SELECT e.id,e.lat,e.lng
             FROM $events e
             WHERE e.status='active'
               AND e.lat IS NOT NULL AND e.lng IS NOT NULL
               AND e.lat BETWEEN %f AND %f AND e.lng BETWEEN %f AND %f
               AND (e.end_at >= %s OR (e.end_at IS NULL AND e.start_at >= %s))",
            $min_lat,$max_lat,$min_lng,$max_lng,$now,$now
        );
        $candidate_points = (array)$wpdb->get_results($point_sql, ARRAY_A);
        $distance_by_id = array();
        foreach ($candidate_points as $point) {
            $event_id=(int)($point['id']??0);
            if($event_id<=0) continue;
            $lat2=(float)$point['lat']; $lng2=(float)$point['lng'];
            $dlat=deg2rad($lat2-$lat); $dlng=deg2rad($lng2-$lng);
            $a=sin($dlat/2)*sin($dlat/2)+cos(deg2rad($lat))*cos(deg2rad($lat2))*sin($dlng/2)*sin($dlng/2);
            $distance=6371.0*2.0*atan2(sqrt($a),sqrt(max(0.0,1.0-$a)));
            if($distance <= $radius_km) $distance_by_id[$event_id]=$distance;
        }

        // V1.10.132: broad-radius memory fix.
        //
        // At 25/50 km a dense Ruhr search can contain ten-thousand concrete
        // occurrence rows although only a few hundred visitor-facing event
        // identities remain after the established source/series clustering.
        // Loading SELECT e.* (including raw_payload) for every occurrence before
        // clustering exhausted shared-hosting memory and caused HTTP 500 on the
        // Halloween 25 km view. Cluster first on a deliberately lightweight
        // projection, then hydrate only the chosen representatives.
        $cluster_input = array();
        if($distance_by_id){
            foreach(array_chunk(array_keys($distance_by_id),300) as $id_chunk){
                $id_sql=implode(',',array_map('intval',$id_chunk));
                if($id_sql==='') continue;
                $light_rows=(array)$wpdb->get_results(
                    "SELECT e.id,e.canonical_key,e.external_id,e.source,e.last_master_run,e.title,e.start_at,e.end_at,e.venue_name,e.city,e.lat,e.lng,
                            CASE WHEN e.description IS NULL OR e.description='' THEN '' ELSE '1' END AS description,
                            CASE WHEN e.ticket_url IS NULL OR e.ticket_url='' THEN '' ELSE '1' END AS ticket_url,
                            CASE WHEN e.price_text IS NULL OR e.price_text='' THEN '' ELSE '1' END AS price_text
                     FROM $events e
                     WHERE e.status='active' AND e.id IN ($id_sql)",
                    ARRAY_A
                );
                foreach($light_rows as $cr){
                    $event_id=(int)($cr['id']??0);
                    if(!$event_id||!isset($distance_by_id[$event_id])) continue;
                    $cr['distance_km']=$distance_by_id[$event_id];
                    $cr=$this->event_apply_curated_visitor_data_to_row($cr);
                    $visitorEnd=strtotime((string)($cr['end_at']??($cr['start_at']??'')));
                    if(!$visitorEnd || $visitorEnd>=current_time('timestamp')) $cluster_input[]=$cr;
                }
            }
        }

        // 1.10.165: the activated official Wesel source may contain legitimate
        // future city events without a safe point coordinate. When the request is
        // explicitly scoped to Wesel, append those rows as city-scoped candidates.
        // They carry no fabricated lat/lng and therefore no visitor distance.
        if(strcasecmp(trim((string)$city),'Wesel')===0){
            $city_scope_rows=(array)$wpdb->get_results($wpdb->prepare(
                "SELECT e.id,e.canonical_key,e.external_id,e.source,e.last_master_run,e.title,e.start_at,e.end_at,e.venue_name,e.city,e.lat,e.lng,
                        CASE WHEN e.description IS NULL OR e.description='' THEN '' ELSE '1' END AS description,
                        CASE WHEN e.ticket_url IS NULL OR e.ticket_url='' THEN '' ELSE '1' END AS ticket_url,
                        CASE WHEN e.price_text IS NULL OR e.price_text='' THEN '' ELSE '1' END AS price_text
                 FROM $events e
                 WHERE e.status='active' AND e.source='wesel_marketing_calendar' AND e.city=%s
                   AND (e.lat IS NULL OR e.lng IS NULL)
                   AND (e.end_at>=%s OR (e.end_at IS NULL AND DATE(e.start_at)>=DATE(%s)))
                 ORDER BY e.start_at ASC,e.id ASC LIMIT 500",
                'Wesel',$now,$now
            ),ARRAY_A);
            foreach($city_scope_rows as $cr){$cr['distance_km']=99999.0;$cr['_rpg_city_scope']=1;$cr=$this->event_apply_curated_visitor_data_to_row($cr);$cluster_input[]=$cr;}
        }
        usort($cluster_input,function($a,$b){
            $ta=strtotime((string)$a['start_at']); $tb=strtotime((string)$b['start_at']);
            if($ta===$tb) return ((float)$a['distance_km'] <=> (float)$b['distance_km']);
            return $ta <=> $tb;
        });

        // Source ownership + recurrence/short-run clustering operates entirely on
        // the lightweight projection above. No raw ET4 payload has been loaded yet.
        $clustered_rows=$this->event_listing_cluster_rows($cluster_input);

        // 1.10.166: expose ONLY genuine today/tomorrow cluster occurrence times
        // from the existing already-admitted lightweight event candidates.  This
