            "SELECT e.id FROM $events e WHERE e.status='active' AND (e.end_at IS NULL OR e.end_at >= %s) AND NOT EXISTS (SELECT 1 FROM $media m WHERE m.event_id=e.id AND m.media_type='image' AND m.moderation_status='active' AND m.local_cache_status='ready' AND m.local_path<>'' AND m.source IN ('et4-global-id','et4-feed','editorial-override','official-approved','venue-commons-context','pexels-symbolic-event'))",
            $now
