            $state['status']='waiting_enrichment';$state['last_batch_at']=current_time('mysql');$state['last_error']='Wartet auf allgemeinen Event-Enrichmentlauf';update_option(self::EVENT_FALLBACK_MEDIA_STATE,$state,false);
            wp_clear_scheduled_hook(self::EVENT_FALLBACK_MEDIA_HOOK);wp_schedule_single_event(time()+60,self::EVENT_FALLBACK_MEDIA_HOOK);return;
        }
