                    $edata=array('attempts'=>(int)($old['attempts']??0)+1,'last_error'=>$e->getMessage(),'last_enriched_at'=>$now,'updated_at'=>$now);
                    if($old)$wpdb->update($enr,$edata,array('event_id'=>$id));else{$edata['event_id']=$id;$wpdb->insert($enr,$edata);}
                    $wpdb->update($events,array('enrichment_status'=>'retry','updated_at'=>$now),array('id'=>$id));
                }
