        else{$state['status']='running';wp_clear_scheduled_hook(self::EVENT_FALLBACK_MEDIA_HOOK);wp_schedule_single_event(time()+20,self::EVENT_FALLBACK_MEDIA_HOOK);}
        update_option(self::EVENT_FALLBACK_MEDIA_STATE,$state,false);if(($state['status']??'')==='running'&&function_exists('spawn_cron'))spawn_cron();
    }


    /** V1.10.48 one-time upgrade of existing Pexels event fallbacks to Event-Ort. */
