        global $wpdb;$events=$this->table('events');$media=$this->table('event_media');$now=current_time('mysql');
        $eligible=(int)$wpdb->get_var($wpdb->prepare(
            "SELECT COUNT(DISTINCT e.id) FROM $events e WHERE e.status='active' AND (e.end_at IS NULL OR e.end_at >= %s)
             AND EXISTS (SELECT 1 FROM $media p WHERE p.event_id=e.id AND p.media_type='image' AND p.moderation_status='active' AND p.local_cache_status='ready' AND p.local_path<>'' AND p.source='pexels-symbolic-event')",$now));
        $upgraded=(int)$wpdb->get_var($wpdb->prepare(
            "SELECT COUNT(DISTINCT e.id) FROM $events e WHERE e.status='active' AND (e.end_at IS NULL OR e.end_at >= %s)
             AND EXISTS (SELECT 1 FROM $media m WHERE m.event_id=e.id AND m.media_type='image' AND m.moderation_status='active' AND m.local_cache_status='ready' AND m.local_path<>'' AND m.source='venue-commons-context')",$now));
        return array('pexels_active'=>$eligible,'event_ort_active'=>$upgraded);
    }

    private function event_context_upgrade_next_rows_v1048($cursor,$limit=2) {
        global $wpdb;$events=$this->table('events');$media=$this->table('event_media');$now=current_time('mysql');$cursor=max(0,(int)$cursor);$limit=max(1,min(5,(int)$limit));
        $sql=$wpdb->prepare(
            "SELECT e.* FROM $events e
             WHERE e.id>%d AND e.status='active' AND (e.end_at IS NULL OR e.end_at >= %s)
               AND EXISTS (SELECT 1 FROM $media p WHERE p.event_id=e.id AND p.media_type='image' AND p.moderation_status='active' AND p.local_cache_status='ready' AND p.local_path<>'' AND p.source='pexels-symbolic-event')
               AND NOT EXISTS (SELECT 1 FROM $media s WHERE s.event_id=e.id AND s.media_type='image' AND s.moderation_status='active' AND s.local_cache_status='ready' AND s.local_path<>'' AND s.source IN ('et4-global-id','et4-feed','editorial-override','official-approved','venue-commons-context'))
             ORDER BY e.id ASC LIMIT %d",$cursor,$now,$limit);
        return (array)$wpdb->get_results($sql,ARRAY_A);
    }

    private function event_context_upgrade_one_v1048($row) {
        if(!is_array($row)||empty($row['id']))return array('checked'=>false,'upgraded'=>false,'reason'=>'event-fehlt');
        if(!function_exists('ruhrpott_guru_event_media_resolver_v85'))return array('checked'=>false,'upgraded'=>false,'reason'=>'theme-resolver-fehlt');
        $event_id=(int)$row['id'];$raw=json_decode((string)($row['raw_payload']??''),true);if(!is_array($raw))$raw=array();$officialWebsite=$this->event_public_website_from_item($raw);
        $req=new WP_REST_Request('POST','/ruhrpottguru/v1/event-media');$req->set_header('content-type','application/json');$req->set_body(wp_json_encode(array('title'=>$row['title'],'website'=>$officialWebsite,'pageUrl'=>$officialWebsite,'sourceUrl'=>$row['source_url'],'raw'=>$raw,'venueName'=>$row['venue_name'],'city'=>$row['city'],'eventType'=>$row['event_category'],'start'=>$row['start_at'],'coords'=>array('lat'=>$row['lat'],'lng'=>$row['lng']))));
        $res=ruhrpott_guru_event_media_resolver_v85($req);$data=$res instanceof WP_REST_Response?$res->get_data():$res;if(!is_array($data))return array('checked'=>true,'upgraded'=>false,'reason'=>'resolver-ungueltig');
        if(!empty($data['candidateOnly'])&&!empty($data['candidate'])&&is_array($data['candidate']))$this->event_store_editorial_candidate_v1042($event_id,$data['candidate']);
        $fallback=null;if(!empty($data['candidateOnly'])&&!empty($data['fallback'])&&is_array($data['fallback']))$fallback=$data['fallback'];elseif(!empty($data['ok'])&&!empty($data['imageUrl']))$fallback=$data;
        if(!is_array($fallback)||sanitize_key((string)($fallback['source']??''))!=='venue-commons-context')return array('checked'=>true,'upgraded'=>false,'reason'=>'kein-event-ort');
        $ok=$this->event_store_local_fallback_v1042($event_id,$fallback,'venue-commons-context',(float)($fallback['identityConfidence']??0.82));
        return array('checked'=>true,'upgraded'=>(bool)$ok,'reason'=>$ok?'event-ort-gespeichert':'event-ort-speichern-fehlgeschlagen','placeId'=>(int)($fallback['placeId']??0),'placeName'=>(string)($fallback['placeName']??''));
    }

    private function start_event_context_upgrade_v1048() {
