        update_option(self::EVENT_CONTEXT_UPGRADE_STATE,array_merge(array('status'=>'running','started_at'=>current_time('mysql'),'cursor'=>0,'processed'=>0,'upgraded'=>0,'missed'=>0,'errors'=>0,'last_event_id'=>0,'last_title'=>'','last_error'=>'','last_batch_at'=>''),$snap),false);
        wp_schedule_single_event(time(),self::EVENT_CONTEXT_UPGRADE_HOOK);if(function_exists('spawn_cron'))spawn_cron();
    }

    public function ensure_event_context_upgrade_v1048() {
        if(!$this->event_auxiliary_media_research_enabled_v1056()){$this->pause_event_auxiliary_worker_v1056(self::EVENT_CONTEXT_UPGRADE_STATE,self::EVENT_CONTEXT_UPGRADE_HOOK,'ET4-Fokus: Event-Ort/Pexels-Kontextupgrade bis zur Rechteklaerung pausiert.');return;}
        if(get_option('rg_events_context_upgrade_v1048_migrated'))return;
        $state=get_option(self::EVENT_CONTEXT_UPGRADE_STATE,array());if(!is_array($state))$state=array();
        if(!$state||in_array(($state['status']??''),array('','idle','finished'),true)){$this->start_event_context_upgrade_v1048();return;}
        if(in_array(($state['status']??''),array('running','waiting_theme','paused_places','waiting_enrichment'),true)){
            $next=wp_next_scheduled(self::EVENT_CONTEXT_UPGRADE_HOOK);if(!$next||$next<time()-120||$next>time()+300){wp_clear_scheduled_hook(self::EVENT_CONTEXT_UPGRADE_HOOK);wp_schedule_single_event(time(),self::EVENT_CONTEXT_UPGRADE_HOOK);if(function_exists('spawn_cron'))spawn_cron();}
        }
    }

    public function cron_events_context_upgrade_batch_v1048() {
        if(!$this->event_auxiliary_media_research_enabled_v1056()){$this->pause_event_auxiliary_worker_v1056(self::EVENT_CONTEXT_UPGRADE_STATE,self::EVENT_CONTEXT_UPGRADE_HOOK,'ET4-Fokus: Event-Ort/Pexels-Kontextupgrade bis zur Rechteklaerung pausiert.');return;}
        $state=get_option(self::EVENT_CONTEXT_UPGRADE_STATE,array());if(!is_array($state)||!in_array(($state['status']??''),array('running','waiting_theme','paused_places','waiting_enrichment'),true))return;
        if(!function_exists('ruhrpott_guru_event_media_from_place_db_v235')){$state['status']='waiting_theme';$state['last_error']='Wartet auf Theme v235 Event-Ort-Resolver';$state['last_batch_at']=current_time('mysql');update_option(self::EVENT_CONTEXT_UPGRADE_STATE,$state,false);wp_clear_scheduled_hook(self::EVENT_CONTEXT_UPGRADE_HOOK);wp_schedule_single_event(time()+60,self::EVENT_CONTEXT_UPGRADE_HOOK);return;}
