        if($this->places_import_actively_running()){$state['status']='paused_places';$state['last_error']='Places-Import aktiv';$state['last_batch_at']=current_time('mysql');update_option(self::EVENT_CONTEXT_UPGRADE_STATE,$state,false);wp_clear_scheduled_hook(self::EVENT_CONTEXT_UPGRADE_HOOK);wp_schedule_single_event(time()+120,self::EVENT_CONTEXT_UPGRADE_HOOK);return;}
        $state['status']='running';$state['last_error']='';$started=microtime(true);$loops=0;
        do{
            $rows=$this->event_context_upgrade_next_rows_v1048((int)($state['cursor']??0),2);if(!$rows)break;
            foreach($rows as $row){$eid=(int)$row['id'];$state['cursor']=$eid;$state['last_event_id']=$eid;$state['last_title']=(string)$row['title'];
                try{$r=$this->event_context_upgrade_one_v1048($row);$state['processed']=(int)($state['processed']??0)+1;if(!empty($r['upgraded']))$state['upgraded']=(int)($state['upgraded']??0)+1;else $state['missed']=(int)($state['missed']??0)+1;$state['last_result']=$r;}
                catch(Throwable $e){$state['processed']=(int)($state['processed']??0)+1;$state['errors']=(int)($state['errors']??0)+1;$state['last_error']=$e->getMessage();}
                if((microtime(true)-$started)>=16)break 2;
            }$loops++;
        }while($loops<2&&(microtime(true)-$started)<16);
        $state['last_batch_at']=current_time('mysql');$state=array_merge($state,$this->event_context_upgrade_progress_v1048());$remaining=$this->event_context_upgrade_next_rows_v1048((int)($state['cursor']??0),1);
        if(!$remaining){$state['status']='finished';$state['finished_at']=current_time('mysql');wp_clear_scheduled_hook(self::EVENT_CONTEXT_UPGRADE_HOOK);update_option('rg_events_context_upgrade_v1048_migrated',$state['finished_at'],false);}else{$state['status']='running';wp_clear_scheduled_hook(self::EVENT_CONTEXT_UPGRADE_HOOK);wp_schedule_single_event(time()+20,self::EVENT_CONTEXT_UPGRADE_HOOK);}
        update_option(self::EVENT_CONTEXT_UPGRADE_STATE,$state,false);if(($state['status']??'')==='running'&&function_exists('spawn_cron'))spawn_cron();
    }

