        $diag['snapshot']=$this->event_enrichment_progress_snapshot();$state['diagnostic']=$diag;$state['last_batch_at']=$now;$state=array_merge($state,$diag['snapshot']);update_option('rg_events_enrichment_state',$state,false);
        $msg='Enrichment-Diagnose ausgeführt: '.($diag['result']??'unbekannt').(!empty($diag['error'])?' · '.$diag['error']:'');wp_safe_redirect(add_query_arg(array('page'=>'rp-events','rg_event_notice'=>rawurlencode($msg)),admin_url('admin.php')));exit;
