    private function opening_audit_state() {
        $state = get_option('rg_opening_hours_audit_state_v1108', array());
        return is_array($state) ? $state : array();
    }

    private function opening_audit_source_bucket($source) {
        $s = strtolower((string)$source);
        if (strpos($s,'redaktion')!==false || strpos($s,'override')!==false) return 'redaktion';
        if (strpos($s,'wikidata')!==false) return 'wikidata';
        if (strpos($s,'et4')!==false || strpos($s,'destination')!==false) return 'et4';
        if (strpos($s,'official')!==false || strpos($s,'website')!==false || strpos($s,'source-record')!==false) return 'official';
        if (strpos($s,'osm')!==false || strpos($s,'places-katalog')!==false) return 'osm';
        if (strpos($s,'schedule')!==false || strpos($s,'enrichment')!==false) return 'existing';
        return 'other';
    }

    private function opening_audit_record($place_id,$relevance,$status,$source='',$source_url='',$hours='',$attempts=array(),$error='') {
        global $wpdb;
        $table=$this->table('place_opening_audit');
        $now=current_time('mysql',true);
        $wpdb->query($wpdb->prepare(
            "INSERT INTO $table (place_id,relevance,status,source,source_url,opening_hours,attempts_json,last_error,checked_at,updated_at)
             VALUES (%d,%s,%s,%s,%s,%s,%s,%s,%s,%s)
             ON DUPLICATE KEY UPDATE relevance=VALUES(relevance),status=VALUES(status),source=VALUES(source),source_url=VALUES(source_url),opening_hours=VALUES(opening_hours),attempts_json=VALUES(attempts_json),last_error=VALUES(last_error),checked_at=VALUES(checked_at),updated_at=VALUES(updated_at)",
            (int)$place_id,sanitize_key($relevance),sanitize_key($status),substr(sanitize_text_field((string)$source),0,64),esc_url_raw((string)$source_url),sanitize_text_field((string)$hours),wp_json_encode((array)$attempts),sanitize_text_field((string)$error),$now,$now
        ));
    }

    private function opening_audit_existing_meta($row) {
        $map=$this->rp_labor_place_meta_map(array($row));
        $pid=(int)($row['id']??0);
        return isset($map[$pid]) && is_array($map[$pid]) ? $map[$pid] : array('opening_hours'=>'','opening_source'=>'','raw_tags'=>array());
    }

    private function opening_audit_requires_hours($row,$meta) {
        $category=(string)($row['primary_category']??'');
        if(!in_array($category,array('food','highlights','culture','activities'),true))return array(false,'not-relevant','Kategorie nicht öffentlich genutzt');
        $model=$this->rp_labor_access_model($row,$category,$meta);
        if(in_array(($model['mode']??''),array('closed','restricted'),true))return array(false,'excluded',($model['label']??'nicht nutzbar'));
        if(($model['mode']??'')==='public_outdoor')return array(false,'not-required',($model['label']??'öffentliches Outdoor-Ziel'));
        $tags=(array)($meta['raw_tags']??array());if(!$tags){$tags=json_decode((string)($row['raw_tags']??''),true);if(!is_array($tags))$tags=array();}
        $access=strtolower((string)($tags['access']??''));$fee=strtolower((string)($tags['fee']??''));$barrier=strtolower((string)($tags['barrier']??''));$tourism=strtolower((string)($tags['tourism']??''));$historic=strtolower((string)($tags['historic']??''));$leisure=strtolower((string)($tags['leisure']??''));$man=strtolower((string)($tags['man_made']??''));$highway=strtolower((string)($tags['highway']??''));
        $blocked=in_array($access,array('private','no','customers','permit'),true)||in_array($barrier,array('gate','turnstile','ticket_gate','entrance'),true)||in_array($fee,array('yes','required'),true);
        if(!$blocked){
            if(in_array($tourism,array('viewpoint','artwork'),true)||in_array($historic,array('memorial','monument','wayside_cross','wayside_shrine'),true)||in_array($man,array('spoil_heap'),true)||in_array($highway,array('path','footway','pedestrian'),true))return array(false,'not-required','öffentlich zugängliches Outdoor-/Landmarken-Objekt');
            if(in_array($leisure,array('park','nature_reserve'),true)&&$fee==='no')return array(false,'not-required','öffentlicher Park/Naturraum ohne Eintritt');
        }
        return array(true,'needs-hours','zeit-/zugangsgesteuerte Location oder Öffnung nicht sicher ableitbar');
    }

    public function ensure_data_hygiene_v101156() {
        if(get_option('rg_data_hygiene_v101156_done',false))return;
        global $wpdb;$now=current_time('mysql');$stats=array('opening_quarantined'=>0,'organizers_rebuilt'=>0,'participants_rebuilt'=>0,'at'=>$now);
        $schedule=$this->table('place_schedules');$places=$this->table('places');$enrichment=$this->table('place_enrichment');$audit=$this->table('place_opening_audit');
        $rows=(array)$wpdb->get_results("SELECT place_id,raw_value,source,locked FROM $schedule WHERE schedule_type='general' AND locked=0 AND (source LIKE 'official-website%' OR source='osm-opening-hours-url')",ARRAY_A);
        foreach($rows as $row){$hours=trim((string)($row['raw_value']??''));if($hours===''||$this->opening_audit_compact_plausible_v101156($hours))continue;$pid=(int)$row['place_id'];if($pid<=0)continue;
            // Remove only the exact quarantined value from derived stores. OSM/raw tags,
            // manual schedules and locked editorial values are not touched.
            $wpdb->query($wpdb->prepare("DELETE FROM $schedule WHERE place_id=%d AND schedule_type='general' AND locked=0 AND raw_value=%s",$pid,$hours));
            $wpdb->query($wpdb->prepare("UPDATE $places SET opening_hours='',updated_at=%s WHERE id=%d AND opening_hours=%s",$now,$pid,$hours));
            $wpdb->query($wpdb->prepare("UPDATE $enrichment SET opening_hours='',opening_hours_source='',updated_at=%s WHERE place_id=%d AND opening_hours=%s",$now,$pid,$hours));
            $wpdb->query($wpdb->prepare("UPDATE $audit SET opening_hours='',status='data-quality-quarantine',last_error=%s,updated_at=%s WHERE place_id=%d AND opening_hours=%s",'1.10.156: historischer HTML-Parser-Ausgang strukturell unplausibel; kein Besucherwert bis zu einer neuen belastbaren Quelle.',$now,$pid,$hours));
            $stats['opening_quarantined']++;
        }
        // Re-materialize only event rows that visibly contain footer/legal leakage.
        // This is generic and source-independent; raw_payload remains untouched.
        $events=$this->table('events');$candidates=(array)$wpdb->get_results("SELECT id,raw_payload,organizer_json,participants_json FROM $events WHERE organizer_json LIKE '%Impressum%' OR organizer_json LIKE '%Datenschutz%' OR organizer_json LIKE '%©%'",ARRAY_A);
        foreach($candidates as $row){$raw=json_decode((string)($row['raw_payload']??''),true);if(!is_array($raw)||!$raw)continue;$data=array();
            $org=$this->event_organizers_from_item($raw);$orgJson=wp_json_encode($org,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES);if($orgJson!==(string)($row['organizer_json']??'')){$data['organizer_json']=$orgJson;$stats['organizers_rebuilt']++;}
            $participants=$this->event_participant_entries_from_item($raw);$partJson=wp_json_encode($participants,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES);if($partJson!==(string)($row['participants_json']??'')){$data['participants_json']=$partJson;$stats['participants_rebuilt']++;}
            if($data){$data['updated_at']=$now;$wpdb->update($events,$data,array('id'=>(int)$row['id']));}
        }
        update_option('rg_data_hygiene_v101156_done',$stats,false);
    }

    private function opening_audit_day_code($value) {
        $v=mb_strtolower(trim((string)$value),'UTF-8');
        $v=preg_replace('#^https?://schema\.org/#i','',$v);
        $map=array(
            'monday'=>'Mo','montag'=>'Mo','mon'=>'Mo','mo'=>'Mo',
            'tuesday'=>'Di','dienstag'=>'Di','tue'=>'Di','tu'=>'Di','di'=>'Di',
            'wednesday'=>'Mi','mittwoch'=>'Mi','wed'=>'Mi','we'=>'Mi','mi'=>'Mi',
            'thursday'=>'Do','donnerstag'=>'Do','thu'=>'Do','th'=>'Do','do'=>'Do',
            'friday'=>'Fr','freitag'=>'Fr','fri'=>'Fr','fr'=>'Fr',
            'saturday'=>'Sa','samstag'=>'Sa','sat'=>'Sa','sa'=>'Sa',
            'sunday'=>'So','sonntag'=>'So','sun'=>'So','so'=>'So'
        );
        return $map[$v]??'';
