    private function opening_audit_fetch_html_result($url,$timeout=5) {
        $url=esc_url_raw((string)$url);$timeout=max(2,min(8,(int)$timeout));
        $out=array('ok'=>false,'html'=>'','url'=>$url,'http'=>0,'error'=>'','transport'=>'','content_type'=>'');
        if(!$url){$out['error']='invalid-url';return $out;}
        // Theme-Resolver zuerst weiterverwenden. Falls dessen konservativer Custom-UA vom
        // Zielserver geblockt wird, erfolgt genau ein Browser-Header-Fallback aus dem Backend.
        if(function_exists('ruhrpott_guru_food_info_fetch_html')){
            try{$html=(string)ruhrpott_guru_food_info_fetch_html($url,$timeout);if(strlen($html)>=80){$out['ok']=true;$out['html']=$html;$out['transport']='theme-helper';return $out;}}catch(Throwable $e){$out['error']='theme-helper: '.$e->getMessage();}
        }
        $getter=function_exists('wp_safe_remote_get')?'wp_safe_remote_get':'wp_remote_get';
        $r=call_user_func($getter,$url,array(
            'timeout'=>$timeout,'redirection'=>4,'limit_response_size'=>700000,
            'user-agent'=>'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/151 Safari/537.36 RuhrpottGuru/'.self::VERSION,
            'headers'=>array(
                'Accept'=>'text/html,application/xhtml+xml,application/xml;q=0.9,*/*;q=0.8',
                'Accept-Language'=>'de-DE,de;q=0.9,en;q=0.6',
                'Cache-Control'=>'no-cache',
            ),
        ));
        $out['transport']='browser-fallback';
        if(is_wp_error($r)){$out['error']=$r->get_error_message();return $out;}
        $code=(int)wp_remote_retrieve_response_code($r);$type=strtolower((string)wp_remote_retrieve_header($r,'content-type'));$body=(string)wp_remote_retrieve_body($r);
        $out['http']=$code;$out['content_type']=$type;
        $looks_html=($type===''||strpos($type,'html')!==false||strpos($type,'xhtml')!==false||stripos($body,'<!doctype html')!==false||stripos($body,'<html')!==false);
        if($code>=200&&$code<400&&$looks_html&&strlen($body)>=80){$out['ok']=true;$out['html']=$body;$out['error']='';return $out;}
        if($code<200||$code>=400)$out['error']='HTTP '.$code;
        elseif(!$looks_html)$out['error']='non-html response'.($type!==''?' ('.$type.')':'');
        else $out['error']='response too short';
        return $out;
    }

    private function opening_audit_fetch_html($url) {
        $r=$this->opening_audit_fetch_html_result($url,4);
        return !empty($r['ok'])?(string)$r['html']:'';
    }

    private function opening_audit_absolute_url($href,$base) {
