        $p=parse_url($base);if(!$p||empty($p['host']))return '';$root=($p['scheme']??'https').'://'.$p['host'].(!empty($p['port'])?':'.$p['port']:'');
        if(strpos($href,'/')===0)return esc_url_raw($root.$href);$path=$p['path']??'/';$dir=preg_replace('#/[^/]*$#','/',$path);return esc_url_raw($root.$dir.$href);
