    private function opening_audit_site_hours($url,$row=array()) {
        $url=esc_url_raw((string)$url);if(!$url)return array('hours'=>'','url'=>'','attempts'=>array(),'complete'=>false,'blocked'=>false,'reason'=>'no-url');
        $attempts=array();$root=$this->opening_audit_fetch_html_result($url,5);$html=!empty($root['ok'])?(string)$root['html']:'';
        $attempts[]=array('type'=>'official-page','url'=>$url,'ok'=>!empty($root['ok']),'http'=>(int)($root['http']??0),'error'=>(string)($root['error']??''),'transport'=>(string)($root['transport']??''),'critical'=>true);
