        $add_link=function($href,$context='')use(&$links,$url){
            $u=$this->opening_audit_absolute_url($href,$url);if(!$u||$u===$url)return;
            $ctx=mb_strtolower((string)$context.' '.(string)$href,'UTF-8');
            $critical=(bool)preg_match('/öffnungs|oeffnungs|opening|hours|\bzeiten\b/u',$ctx);
            if(!isset($links[$u]))$links[$u]=array('url'=>$u,'critical'=>$critical,'context'=>$ctx);
            elseif($critical)$links[$u]['critical']=true;
        };
        if(preg_match_all('#<a[^>]+href=["\']([^"\']+)["\'][^>]*>(.*?)</a>#is',$html,$m,PREG_SET_ORDER))foreach($m as $a){
            $text=mb_strtolower(wp_strip_all_tags($a[2]),'UTF-8');$href=mb_strtolower($a[1],'UTF-8');
            if(preg_match('/öffnungs|oeffnungs|opening|zeiten|hours|besuch|visit|info|kontakt|contact|service/u',$text.' '.$href))$add_link($a[1],$text);
        }
        if(function_exists('ruhrpott_guru_food_info_anchor_links')&&function_exists('ruhrpott_guru_food_info_priority_pages')&&function_exists('ruhrpott_guru_food_info_host')){
            $more=ruhrpott_guru_food_info_priority_pages(ruhrpott_guru_food_info_anchor_links($html,$url),ruhrpott_guru_food_info_host($url),$url);
