        $critical_blocked=false;$checked=0;$accessible=0;
        foreach(array_slice($list,0,3) as $entry){$u=(string)$entry['url'];if($host&&parse_url($u,PHP_URL_HOST)!==$host)continue;$checked++;
            $fr=$this->opening_audit_fetch_html_result($u,5);$ok=!empty($fr['ok']);$critical=!empty($entry['critical']);
            $attempts[]=array('type'=>'official-hours-page','url'=>$u,'ok'=>$ok,'http'=>(int)($fr['http']??0),'error'=>(string)($fr['error']??''),'transport'=>(string)($fr['transport']??''),'critical'=>$critical);
