    private function opening_audit_final_salvage_site($url,$row=array()) {
        $url=esc_url_raw((string)$url);$attempts=array();if(!$url)return array('hours'=>'','url'=>'','attempts'=>$attempts,'accessible'=>false);
        $p=wp_parse_url($url);if(!is_array($p)||empty($p['host']))return array('hours'=>'','url'=>$url,'attempts'=>$attempts,'accessible'=>false);
        $scheme=strtolower((string)($p['scheme']??'https'));if(!in_array($scheme,array('http','https'),true))$scheme='https';$host=strtolower((string)$p['host']);
        $port=!empty($p['port'])?':'.(int)$p['port']:'';$orig_norm=preg_replace('#/+$#','',$url);$candidates=array();
        $add=function($u,$kind)use(&$candidates,$orig_norm){$u=esc_url_raw((string)$u);if(!$u)return;$norm=preg_replace('#/+$#','',$u);if($norm===$orig_norm)return;if(!isset($candidates[$norm]))$candidates[$norm]=array('url'=>$u,'kind'=>$kind);};
        $origin=$scheme.'://'.$host.$port.'/';$add($origin,'canonical-root');
        if(strpos($host,'www.')===0){$bare=substr($host,4);if($bare!=='')$add($scheme.'://'.$bare.$port.'/','without-www');}
        elseif(substr_count($host,'.')===1)$add($scheme.'://www.'.$host.$port.'/','with-www');
        $other=$scheme==='https'?'http':'https';$add($other.'://'.$host.$port.'/','alternate-scheme');
        $roots=array_values($candidates);$accessible=false;$best_root='';
        foreach(array_slice($roots,0,4) as $entry){
            $u=(string)$entry['url'];$fr=$this->opening_audit_fetch_html_result($u,6);$ok=!empty($fr['ok']);
            $attempts[]=array('type'=>'official-final-salvage-root','kind'=>(string)$entry['kind'],'url'=>$u,'ok'=>$ok,'http'=>(int)($fr['http']??0),'error'=>(string)($fr['error']??''),'transport'=>(string)($fr['transport']??''));
            if(!$ok)continue;$accessible=true;if($best_root==='')$best_root=$u;$hours=$this->opening_audit_parse_hours_html((string)$fr['html'],$row);
            if($hours!=='')return array('hours'=>$hours,'url'=>$u,'attempts'=>$attempts,'accessible'=>true);
            $site=$this->opening_audit_site_hours($u,$row);$attempts=array_merge($attempts,(array)$site['attempts']);if((string)($site['hours']??'')!=='')return array('hours'=>(string)$site['hours'],'url'=>(string)($site['url']??$u),'attempts'=>$attempts,'accessible'=>true);
        }
