        foreach(array('/oeffnungszeiten/','/opening-hours/','/besuch/','/visit/') as $path){
            $u=esc_url_raw($base_root.$path);$fr=$this->opening_audit_fetch_html_result($u,6);$ok=!empty($fr['ok']);
            $attempts[]=array('type'=>'official-final-salvage-path','url'=>$u,'ok'=>$ok,'http'=>(int)($fr['http']??0),'error'=>(string)($fr['error']??''),'transport'=>(string)($fr['transport']??''));
            if(!$ok)continue;$accessible=true;$hours=$this->opening_audit_parse_hours_html((string)$fr['html'],$row);if($hours!=='')return array('hours'=>$hours,'url'=>$u,'attempts'=>$attempts,'accessible'=>true);
        }
        return array('hours'=>'','url'=>$url,'attempts'=>$attempts,'accessible'=>$accessible);
