    private function opening_audit_unknown_delta_salvage($row) {
        global $wpdb;$raw=json_decode((string)($row['raw_tags']??''),true);if(!is_array($raw))$raw=array();$attempts=array();
        $website=esc_url_raw(trim((string)($row['website']??'')));if(!$website)$website=esc_url_raw(trim((string)($raw['contact:website']??'')));if(!$website)$website=esc_url_raw(trim((string)($raw['website']??'')));
