        foreach(array_merge(array($direct,$website),$link_targets) as $u){$u=esc_url_raw((string)$u);if(!$u)continue;$host=(string)wp_parse_url($u,PHP_URL_HOST);if(!$host||$this->opening_audit_directory_host($host))continue;$targets[$u]=$u;}
