            if((string)($sv['hours']??'')!=='')return array('found'=>true,'hours'=>(string)$sv['hours'],'source'=>'official-website-unknown-delta','source_url'=>(string)($sv['url']??$target),'website'=>$website?:$target,'attempts'=>$attempts,'confidence'=>0.95,'complete'=>true,'reason'=>'unknown-delta-hours');
