    }

    private function opening_audit_normalize_text($value) {
        $v=$this->opening_audit_utf8($value);$v=html_entity_decode(wp_strip_all_tags((string)$v),ENT_QUOTES|ENT_HTML5,'UTF-8');$v=mb_strtolower($v,'UTF-8');
