    private function opening_audit_identity_match($html,$row) {
        $title=(string)($row['name']??'');$city=(string)($row['city']??'');$address=trim((string)($row['street']??'').' '.(string)($row['house_number']??''));
        if(function_exists('ruhrpott_guru_food_media_page_matches')&&ruhrpott_guru_food_media_page_matches($html,$title,$city,$address))return true;
        $txt=$this->opening_audit_normalize_text(substr((string)$html,0,700000));$name=$this->opening_audit_normalize_text($title);$cityn=$this->opening_audit_normalize_text($city);$addr=$this->opening_audit_normalize_text($address);
        if($name===''||$txt==='')return false;$tokens=array_values(array_filter(explode(' ',$name),function($t){return mb_strlen($t,'UTF-8')>=4&&!in_array($t,array('restaurant','cafe','café','museum','halle','park','zentrum','wesel','essen'),true);}));
        $hits=0;foreach(array_slice($tokens,0,6) as $t)if(strpos($txt,$t)!==false)$hits++;$name_ok=strpos($txt,$name)!==false||($hits>=max(1,min(2,count($tokens))));
        $local_ok=($cityn!==''&&strpos($txt,$cityn)!==false);if(!$local_ok&&$addr!==''){foreach(array_filter(explode(' ',$addr),function($x){return strlen($x)>=4;}) as $a){if(strpos($txt,$a)!==false){$local_ok=true;break;}}}
        return $name_ok&&$local_ok;
    }

    private function opening_audit_directory_host($host) {
        $host=strtolower(preg_replace('/^www\./i','',(string)$host));if($host==='')return true;
        $exact=array('duckduckgo.com','html.duckduckgo.com','bing.com','www.bing.com','facebook.com','instagram.com','tiktok.com','wikipedia.org','de.wikipedia.org','foursquare.com','mapcarta.com');
        foreach($exact as $d)if($host===$d||substr($host,-strlen('.'.$d))==='.'. $d)return true;
        if(preg_match('/(?:^|\.)(?:tripadvisor|restaurantguru|yelp|lieferando|ubereats|golocal|11880|meinestadt|oeffnungszeitenbuch|werkenntdenbesten|branchenbuch|cylex|google|yahoo)\./i',$host))return true;
        if(function_exists('ruhrpott_guru_food_info_directory_host')&&ruhrpott_guru_food_info_directory_host($host))return true;
        return false;
    }

