        $get='https://www.wikidata.org/w/api.php?'.http_build_query(array('action'=>'wbgetentities','format'=>'json','props'=>'claims','ids'=>implode('|',$ids)));$resp2=wp_remote_get($get,array('timeout'=>4,'redirection'=>2,'headers'=>array('Accept'=>'application/json'),'user-agent'=>'RuhrpottGuru/'.self::VERSION.'; '.home_url('/')));if(is_wp_error($resp2)){$attempts[]=array('type'=>'wikidata-search-p856','ok'=>false,'error'=>$resp2->get_error_message());return array('complete'=>false,'urls'=>array(),'attempts'=>$attempts);}$code2=(int)wp_remote_retrieve_response_code($resp2);$data2=json_decode(wp_remote_retrieve_body($resp2),true);if($code2<200||$code2>=300||!is_array($data2)){$attempts[]=array('type'=>'wikidata-search-p856','ok'=>false,'http'=>$code2);return array('complete'=>false,'urls'=>array(),'attempts'=>$attempts);}$urls=array();foreach((array)($data2['entities']??array()) as $entity){foreach((array)($entity['claims']['P856']??array()) as $claim){$u=esc_url_raw((string)($claim['mainsnak']['datavalue']['value']??''));if($u&&!$this->opening_audit_directory_host((string)wp_parse_url($u,PHP_URL_HOST)))$urls[]=$u;}}
