        $parts=wp_parse_url($href);if(!$parts)return '';$host=strtolower((string)($parts['host']??''));if(strpos($host,'duckduckgo.com')!==false&&!empty($parts['query'])){parse_str($parts['query'],$q);if(!empty($q['uddg']))return esc_url_raw(urldecode((string)$q['uddg']));}
