    private function opening_audit_web_discovery($row) {
        $name=trim((string)($row['name']??''));$city=trim((string)($row['city']??''));$addr=trim((string)($row['street']??'').' '.(string)($row['house_number']??''));
        if($name==='')return array('complete'=>true,'candidates'=>array(),'attempts'=>array(array('type'=>'web-discovery','status'=>'no-name')));
        $query='"'.$name.'" '.$city.' Öffnungszeiten offizielle Website';if($addr!=='')$query.=' "'.$addr.'"';
        $attempts=array();$out=array();$successful_engines=0;
        $engines=array(
            array('name'=>'duckduckgo','url'=>'https://html.duckduckgo.com/html/?q='.rawurlencode($query),'pattern'=>'#<a[^>]+class=["\'][^"\']*result__a[^"\']*["\'][^>]+href=["\']([^"\']+)["\']#is'),
            array('name'=>'bing','url'=>'https://www.bing.com/search?q='.rawurlencode($query).'&setlang=de-DE','pattern'=>'#<li[^>]+class=["\'][^"\']*b_algo[^"\']*["\'][^>]*>.*?<a[^>]+href=["\']([^"\']+)["\']#is')
        );
        foreach($engines as $engine){
            if(count(array_unique($out))>=4)break;
            $resp=wp_remote_get($engine['url'],array('timeout'=>4,'redirection'=>2,'headers'=>array('Accept'=>'text/html'),'user-agent'=>'Mozilla/5.0 (compatible; RuhrpottGuru/'.self::VERSION.'; +'.home_url('/').')'));
            if(is_wp_error($resp)){$attempts[]=array('type'=>'web-discovery','engine'=>$engine['name'],'ok'=>false,'query'=>$query,'error'=>$resp->get_error_message());continue;}
            $code=(int)wp_remote_retrieve_response_code($resp);$html=(string)wp_remote_retrieve_body($resp);$ok=$code>=200&&$code<300&&strlen($html)>100;
            $attempts[]=array('type'=>'web-discovery','engine'=>$engine['name'],'ok'=>$ok,'http'=>$code,'query'=>$query);
            if(!$ok)continue;$successful_engines++;
            $links=array();if(preg_match_all($engine['pattern'],$html,$m))$links=$m[1];
            if(!$links&&preg_match_all('#<a[^>]+href=["\'](https?://[^"\']+)["\'][^>]*>#is',$html,$m))$links=$m[1];
            foreach($links as $href){$u=$this->opening_audit_decode_search_url($href);if(!$u||!wp_http_validate_url($u))continue;$host=(string)wp_parse_url($u,PHP_URL_HOST);if($this->opening_audit_directory_host($host))continue;if(preg_match('/\.(?:pdf|jpe?g|png|gif|webp)(?:$|[?#])/i',$u))continue;$out[]=$u;if(count(array_unique($out))>=6)break;}
        }
        return array('complete'=>$successful_engines>0,'candidates'=>array_values(array_unique($out)),'attempts'=>$attempts,'successful_engines'=>$successful_engines);
    }

    private function opening_audit_save_verified_website($place_id,$url,$source='opening-audit-verified-web',$confidence=0.95) {
        global $wpdb;$place_id=(int)$place_id;$url=esc_url_raw((string)$url);if(!$place_id||!$url||$this->opening_audit_directory_host((string)wp_parse_url($url,PHP_URL_HOST)))return false;$now=current_time('mysql',true);$places=$this->table('places');
        $wpdb->query($wpdb->prepare("UPDATE $places SET website=IF(website='',%s,website),updated_at=%s WHERE id=%d",$url,$now,$place_id));$this->upsert_link($place_id,'website',$url,substr(sanitize_text_field((string)$source),0,64),(float)$confidence,$now,false);return true;
    }

    private function opening_audit_save_hours($place_id,$hours,$source,$source_url,$confidence=0.95,$website='') {
        global $wpdb;$place_id=(int)$place_id;$hours=sanitize_text_field((string)$hours);if(!$place_id||$hours==='')return false;
        $source=substr(sanitize_text_field((string)$source),0,64);
        // 1.10.156: HTML-derived schedules must pass the same structural guard at the persistence boundary.
        if($this->opening_audit_html_source_v101156($source)&&!$this->opening_audit_compact_plausible_v101156($hours))return false;$source_url=esc_url_raw((string)$source_url);$confidence=max(0.0,min(1.0,(float)$confidence));$now=current_time('mysql',true);
        $schedule=$this->table('place_schedules');
        $wpdb->query($wpdb->prepare(
            "INSERT INTO $schedule (place_id,schedule_type,raw_value,source,confidence,verified_at,last_seen_at,locked)
             VALUES (%d,'general',%s,%s,%f,%s,%s,0)
             ON DUPLICATE KEY UPDATE raw_value=IF(locked=1,raw_value,IF(VALUES(confidence)>=confidence,VALUES(raw_value),raw_value)),source=IF(locked=1,source,IF(VALUES(confidence)>=confidence,VALUES(source),source)),confidence=IF(locked=1,confidence,GREATEST(confidence,VALUES(confidence))),verified_at=IF(locked=1,verified_at,IF(VALUES(confidence)>=confidence,VALUES(verified_at),verified_at)),last_seen_at=VALUES(last_seen_at)",
            $place_id,$hours,$source,$confidence,$now,$now
        ));
        $effective=$wpdb->get_row($wpdb->prepare("SELECT raw_value,source,confidence,verified_at,locked FROM $schedule WHERE place_id=%d AND schedule_type='general' LIMIT 1",$place_id),ARRAY_A);
        if(is_array($effective)&&trim((string)($effective['raw_value']??''))!==''){
            $hours=sanitize_text_field((string)$effective['raw_value']);$source=substr(sanitize_text_field((string)($effective['source']??$source)),0,64);$confidence=(float)($effective['confidence']??$confidence);$verified=(string)($effective['verified_at']??$now);
        }else{$verified=$now;}
        $en=$this->table('place_enrichment');$existing_fresh=$wpdb->get_var($wpdb->prepare("SELECT freshness_json FROM $en WHERE place_id=%d LIMIT 1",$place_id));$fresh_arr=json_decode((string)$existing_fresh,true);if(!is_array($fresh_arr))$fresh_arr=array();$fresh_arr['opening_hours']=array('source'=>$source,'source_url'=>$source_url,'verified_at'=>$verified,'confidence'=>$confidence);$fresh=wp_json_encode($fresh_arr);
        $wpdb->query($wpdb->prepare(
            "INSERT INTO $en (place_id,opening_hours,opening_hours_source,freshness_json,last_enriched_at,updated_at) VALUES (%d,%s,%s,%s,%s,%s)
             ON DUPLICATE KEY UPDATE opening_hours=VALUES(opening_hours),opening_hours_source=VALUES(opening_hours_source),freshness_json=VALUES(freshness_json),last_enriched_at=VALUES(last_enriched_at),updated_at=VALUES(updated_at)",
            $place_id,$hours,$source,$fresh,$now,$now
        ));
        $wpdb->update($this->table('places'),array('opening_hours'=>$hours,'last_enriched_at'=>$now,'updated_at'=>$now),array('id'=>$place_id));
        if($website)$this->opening_audit_save_verified_website($place_id,$website,$source,$confidence);
        return true;
    }

    private function opening_audit_remote_search($row) {
        $raw=json_decode((string)($row['raw_tags']??''),true);if(!is_array($raw))$raw=array();$attempts=array();$pid=(int)$row['id'];
        $website=esc_url_raw((string)($row['website']??$raw['contact:website']??$raw['website']??''));$wikidata=sanitize_text_field((string)($row['wikidata']??$raw['wikidata']??''));
        $verified_site_blocked=false;$blocked_reason='';$discovery_complete=false;$official_site_accessible=false;$resolver_complete=true;$wikidata_gap=false;$salvage_marker=(string)($row['_audit_last_error']??'');$final_salvage=in_array($salvage_marker,array('__rpg_final_salvage_v1131__','__rpg_final_salvage_v1132__'),true);
        // 1.10.33: historische Unknowns bekommen bewusst KEINEN zweiten Voll-Audit.
        // Der Delta-Marker springt direkt in die neuen offiziellen Salvage-Varianten.
        if($salvage_marker==='__rpg_unknown_delta_v1133__')return $this->opening_audit_unknown_delta_salvage($row);

        // 1) Exaktes Live-OSM. Der persistierte OSM-Snapshot ist bereits identitaetsgebunden;
        // ein temporärer Live-Overpass-Ausfall allein darf den Abschluss daher nicht blockieren.
        $osm=$this->opening_audit_live_osm($row);$attempts=array_merge($attempts,(array)$osm['attempts']);$live=(array)($osm['tags']??array());
        if(!empty($live['opening_hours']))return array('found'=>true,'hours'=>sanitize_text_field((string)$live['opening_hours']),'source'=>'osm-live','source_url'=>'https://www.openstreetmap.org/'.rawurlencode((string)($osm['osm_type']??'node')).'/'.(int)($row['primary_osm_id']??0),'website'=>$website,'attempts'=>$attempts,'confidence'=>0.96,'complete'=>true,'reason'=>'osm-live-hours');
        if(!$website)$website=esc_url_raw((string)($live['contact:website']??$live['website']??''));if(!$wikidata)$wikidata=sanitize_text_field((string)($live['wikidata']??''));
        $direct_hours_url=esc_url_raw((string)($live['opening_hours:url']??$live['opening_hours_url']??$raw['opening_hours:url']??$raw['opening_hours_url']??''));
        if($direct_hours_url){$site=$this->opening_audit_site_hours($direct_hours_url,$row);$attempts=array_merge($attempts,$site['attempts']);if($site['hours']!=='')return array('found'=>true,'hours'=>$site['hours'],'source'=>'osm-opening-hours-url','source_url'=>$site['url'],'website'=>$website,'attempts'=>$attempts,'confidence'=>0.99,'complete'=>true,'reason'=>'osm-opening-hours-url');if(empty($site['complete'])){$verified_site_blocked=true;$blocked_reason=(string)($site['reason']??'official-hours-page-unreachable');}else $official_site_accessible=true;}

        // 2) Wikidata P856 / Wikidata-Suche als weiterer Identitätsweg.
        $wd=$this->opening_audit_wikidata_website($wikidata);$attempts=array_merge($attempts,(array)$wd['attempts']);if(!$website&&!empty($wd['url']))$website=esc_url_raw((string)$wd['url']);$wikidata_gap=($wikidata!==''&&empty($wd['complete'])&&!$website);
        if(!$website&&$wikidata===''){$wds=$this->opening_audit_wikidata_search_websites($row);$attempts=array_merge($attempts,(array)$wds['attempts']);foreach(array_slice((array)($wds['urls']??array()),0,2) as $wu){$wh=$this->opening_audit_fetch_html($wu);$ok=$wh!=='';$identity=$ok?$this->opening_audit_identity_match($wh,$row):false;$attempts[]=array('type'=>'wikidata-discovered-candidate','url'=>$wu,'ok'=>$ok,'identity'=>$identity);if($ok&&$identity){$website=esc_url_raw($wu);$this->opening_audit_save_verified_website($pid,$website,'wikidata-search-p856',0.96);break;}}}

        // 3) Vorhandener RuhrpottGuru-Resolver (destination.one/eT4/primäre Website-Daten).
        $request=new WP_REST_Request('POST','/ruhrpottguru/v1/place-info');$params=array('title'=>(string)$row['name'],'city'=>(string)$row['city'],'address'=>trim((string)$row['street'].' '.(string)$row['house_number']),'website'=>$website,'wikidata'=>$wikidata,'facebook'=>(string)($live['contact:facebook']??$raw['contact:facebook']??$raw['facebook']??''),'instagram'=>(string)($live['contact:instagram']??$raw['contact:instagram']??$raw['instagram']??''),'lat'=>(float)$row['lat'],'lng'=>(float)$row['lng']);
        if((string)$row['primary_category']==='food'&&function_exists('ruhrpott_guru_food_info_enrichment')){
            $request->set_header('content-type','application/json');$request->set_body(wp_json_encode($params));try{$resp=ruhrpott_guru_food_info_enrichment($request);$data=$resp instanceof WP_REST_Response?$resp->get_data():$resp;if(is_array($data)){$attempts[]=array('type'=>'food-resolver','ok'=>true,'status'=>(string)($data['status']??''),'source'=>(string)($data['source']??''),'website'=>(string)($data['website']??''));if(!empty($data['openingHours']))return array('found'=>true,'hours'=>sanitize_text_field($data['openingHours']),'source'=>(string)($data['source']??'official-website'),'source_url'=>(string)($data['sourceUrl']??$data['website']??''),'website'=>(string)($data['website']??$website),'attempts'=>$attempts,'confidence'=>(float)($data['identityConfidence']??0.97),'complete'=>true,'reason'=>'resolver-hours');if(!empty($data['website'])&&!$this->opening_audit_directory_host((string)wp_parse_url($data['website'],PHP_URL_HOST)))$website=esc_url_raw($data['website']);}else{$resolver_complete=false;$attempts[]=array('type'=>'food-resolver','ok'=>false,'status'=>'invalid-response');}}catch(Throwable $e){$resolver_complete=false;$attempts[]=array('type'=>'food-resolver','ok'=>false,'error'=>$e->getMessage());}
        }elseif(function_exists('ruhrpott_guru_place_info_enrichment')){
            $labels=array('highlights'=>'Sehenswürdigkeiten','culture'=>'Kultur','activities'=>'Aktivitäten');$params['category']=$labels[(string)$row['primary_category']]??'Sehenswürdigkeiten';$request->set_header('content-type','application/json');$request->set_body(wp_json_encode($params));try{$resp=ruhrpott_guru_place_info_enrichment($request);$data=$resp instanceof WP_REST_Response?$resp->get_data():$resp;if(is_array($data)){$attempts[]=array('type'=>'place-resolver','ok'=>true,'status'=>(string)($data['status']??''),'source'=>(string)($data['source']??''),'website'=>(string)($data['website']??''));if(!empty($data['website'])&&!$this->opening_audit_directory_host((string)wp_parse_url($data['website'],PHP_URL_HOST)))$website=esc_url_raw($data['website']);}else{$resolver_complete=false;$attempts[]=array('type'=>'place-resolver','ok'=>false,'status'=>'invalid-response');}}catch(Throwable $e){$resolver_complete=false;$attempts[]=array('type'=>'place-resolver','ok'=>false,'error'=>$e->getMessage());}
        }else{$resolver_complete=false;$attempts[]=array('type'=>'resolver','ok'=>false,'status'=>'theme-resolver-unavailable');}

        // 4) Bekannte/verifizierte Betreiberseite prüfen. Die Root-Seite und explizite
        // Öffnungszeiten-Unterseiten sind kritisch; schwache Kontakt-/Info-Unterseiten nicht.
        if($website&&!$this->opening_audit_directory_host((string)wp_parse_url($website,PHP_URL_HOST))){$this->opening_audit_save_verified_website($pid,$website,'opening-audit-primary-website',0.96);$site=$this->opening_audit_site_hours($website,$row);$attempts=array_merge($attempts,$site['attempts']);if($site['hours']!=='')return array('found'=>true,'hours'=>$site['hours'],'source'=>'official-website','source_url'=>$site['url'],'website'=>$website,'attempts'=>$attempts,'confidence'=>0.98,'complete'=>true,'reason'=>'official-website-hours');if(empty($site['complete'])){$verified_site_blocked=true;$blocked_reason=(string)($site['reason']??'official-root-unreachable');}else $official_site_accessible=true;}

        // 5) Öffentliche Websuche nur zur optionalen Discovery. Sie darf Kandidaten liefern,
        // ist aber kein verlässlicher Pflichtprovider: Suchmaschinen blockieren Server-Scraping
        // häufig, obwohl alle identitätsgebundenen Primärquellen sauber abgearbeitet wurden.
        $disc=$this->opening_audit_web_discovery($row);$attempts=array_merge($attempts,(array)$disc['attempts']);$discovery_complete=!empty($disc['complete']);
        foreach(array_slice((array)($disc['candidates']??array()),0,3) as $candidate){$host=(string)wp_parse_url($candidate,PHP_URL_HOST);if($this->opening_audit_directory_host($host))continue;$html=$this->opening_audit_fetch_html($candidate);$ok=$html!=='';$identity=$ok?$this->opening_audit_identity_match($html,$row):false;$attempts[]=array('type'=>'web-candidate','url'=>$candidate,'ok'=>$ok,'identity'=>$identity);if(!$ok||!$identity)continue;$this->opening_audit_save_verified_website($pid,$candidate,'web-discovery-verified-official',0.94);$site=$this->opening_audit_site_hours($candidate,$row);$attempts=array_merge($attempts,$site['attempts']);if($site['hours']!=='')return array('found'=>true,'hours'=>$site['hours'],'source'=>'official-website-web-discovery','source_url'=>$site['url'],'website'=>$candidate,'attempts'=>$attempts,'confidence'=>0.95,'complete'=>true,'reason'=>'web-discovery-hours');if(empty($site['complete'])){$verified_site_blocked=true;$blocked_reason=(string)($site['reason']??'official-root-unreachable');}else $official_site_accessible=true;}

        // Abschlussregel 1.10.30:
        // - Eine bekannte identitätsgebundene offizielle Seite (oder explizite Hours-URL), die
        //   technisch nicht lesbar ist, bleibt offen: dort könnten reale Zeiten stehen.
        // - Ein echter Resolver-/Wikidata-Ausfall bleibt offen, wenn auch keine unabhängige
        //   Discovery erfolgreich war.
        // - Der bloße Ausfall von DuckDuckGo/Bing bei ansonsten vollständig abgearbeiteten
        //   identitätsgebundenen Quellen ist KEIN technischer Restfall mehr.
        if($verified_site_blocked&&$final_salvage){
            $salvage_accessible=false;$targets=array_values(array_unique(array_filter(array($direct_hours_url,$website))));
            foreach($targets as $target){$sv=$this->opening_audit_final_salvage_site($target,$row);$attempts=array_merge($attempts,(array)($sv['attempts']??array()));$salvage_accessible=$salvage_accessible||!empty($sv['accessible']);if((string)($sv['hours']??'')!=='')return array('found'=>true,'hours'=>(string)$sv['hours'],'source'=>'official-website-final-salvage','source_url'=>(string)($sv['url']??$target),'website'=>$website?:$target,'attempts'=>$attempts,'confidence'=>0.95,'complete'=>true,'reason'=>'final-salvage-hours');}
            return array('found'=>false,'hours'=>'','source'=>'','source_url'=>'','website'=>$website,'attempts'=>$attempts,'confidence'=>0.0,'complete'=>true,'reason'=>$salvage_accessible?'final-salvage-exhausted':'final-salvage-unreachable','official_site_accessible'=>$salvage_accessible);
        }
        if($verified_site_blocked)return array('found'=>false,'hours'=>'','source'=>'','source_url'=>'','website'=>$website,'attempts'=>$attempts,'confidence'=>0.0,'complete'=>false,'reason'=>$blocked_reason?:'verified-official-site-blocked','official_site_accessible'=>$official_site_accessible);
        if($final_salvage&&!$discovery_complete&&!$official_site_accessible&&($wikidata_gap||!$resolver_complete))return array('found'=>false,'hours'=>'','source'=>'','source_url'=>'','website'=>$website,'attempts'=>$attempts,'confidence'=>0.0,'complete'=>true,'reason'=>'final-salvage-source-gap','official_site_accessible'=>false);
        if(!$discovery_complete&&!$official_site_accessible&&$wikidata_gap)return array('found'=>false,'hours'=>'','source'=>'','source_url'=>'','website'=>$website,'attempts'=>$attempts,'confidence'=>0.0,'complete'=>false,'reason'=>'wikidata-p856-unreachable','official_site_accessible'=>false);
        if(!$discovery_complete&&!$official_site_accessible&&!$resolver_complete)return array('found'=>false,'hours'=>'','source'=>'','source_url'=>'','website'=>$website,'attempts'=>$attempts,'confidence'=>0.0,'complete'=>false,'reason'=>'resolver-unavailable','official_site_accessible'=>false);

        $reason=$official_site_accessible?'verified-official-site-exhausted':($discovery_complete?'web-discovery-exhausted':'identity-bound-sources-exhausted-search-provider-unavailable');
        return array('found'=>false,'hours'=>'','source'=>'','source_url'=>'','website'=>$website,'attempts'=>$attempts,'confidence'=>0.0,'complete'=>true,'reason'=>$reason,'official_site_accessible'=>$official_site_accessible);
    }

    private function opening_audit_reason_label($reason) {
        $map=array(
            'official-root-unreachable'=>'Bekannte offizielle Website konnte serverseitig nicht gelesen werden.',
            'official-hours-page-unreachable'=>'Explizit verlinkte Öffnungszeiten-Seite konnte serverseitig nicht gelesen werden.',
            'wikidata-p856-unreachable'=>'Wikidata-P856 der identitätsgebundenen Location konnte technisch nicht vollständig geprüft werden.',
            'resolver-unavailable'=>'RuhrpottGuru Quellenresolver (eT4/destination.one/Website) konnte technisch nicht vollständig ausgeführt werden.',
            'verified-official-site-blocked'=>'Bekannte offizielle Website war technisch nicht vollständig prüfbar.',
            'identity-bound-sources-exhausted-search-provider-unavailable'=>'Identitätsgebundene Quellen vollständig geprüft; öffentliche Suchmaschinen-Discovery war nicht verfügbar und wird nicht als Pflichtpfad gewertet.',
            'verified-official-site-exhausted'=>'Offizielle Website vollständig geprüft, dort keine belastbare Öffnungszeit gefunden.',
            'web-discovery-exhausted'=>'Identitätsgebundene Quellen und Web-Discovery vollständig geprüft, keine belastbare Öffnungszeit gefunden.',
            'final-salvage-exhausted'=>'Letzter offizieller Salvage-Pass abgeschlossen: Betreiberseite war über einen alternativen offiziellen Pfad lesbar, enthielt aber keine belastbare Öffnungszeit.',
            'final-salvage-unreachable'=>'Letzter offizieller Salvage-Pass abgeschlossen: Betreiberseite blieb serverseitig unerreichbar; aus allen übrigen identitätsgebundenen Quellen wurde keine belastbare Öffnungszeit gefunden.',
            'final-salvage-source-gap'=>'Letzter Ergebnis-Salvage abgeschlossen: ein technischer Nebenpfad blieb nicht erreichbar, alle übrigen identitätsgebundenen Quellen lieferten jedoch keine belastbare Öffnungszeit.',
            'unknown-delta-no-official-target'=>'Delta-Pass 1.10.33 abgeschlossen: keine bereits verifizierte offizielle Website/Öffnungszeiten-URL vorhanden; die alte Recherchekette wurde bewusst nicht wiederholt.',
            'unknown-delta-exhausted'=>'Delta-Pass 1.10.33 abgeschlossen: neue offizielle URL-/Pfadvarianten wurden geprüft, aber keine zusätzliche belastbare Öffnungszeit gefunden.',
            'unknown-delta-unreachable'=>'Delta-Pass 1.10.33 abgeschlossen: die neuen offiziellen URL-/Pfadvarianten blieben serverseitig unerreichbar; der Datensatz bleibt bestätigt unbekannt.',
        );
        return $map[(string)$reason]??('Technischer Quellenpfad unvollständig: '.sanitize_key((string)$reason));
    }

    private function opening_audit_cleanup_scope() {
        global $wpdb;$a=$this->table('place_opening_audit');$places=$this->table('places');
        // Audit-Zeilen sind nur fuer den aktuellen Besucher-Katalog relevant. Places koennen
        // waehrend eines langen Audits deaktiviert oder umklassifiziert werden; solche Altzeilen
        // duerfen weder Fortschritt noch Queue ueber 100 % treiben.
        return (int)$wpdb->query("DELETE a FROM $a a LEFT JOIN $places p ON p.id=a.place_id WHERE p.id IS NULL OR p.active<>1 OR p.lifecycle_status<>'active' OR p.primary_category NOT IN ('food','highlights','culture','activities')");
    }

    private function opening_audit_category_quality() {
        global $wpdb;
        $a=$this->table('place_opening_audit');$places=$this->table('places');
        $rows=(array)$wpdb->get_results(
            "SELECT p.primary_category category,
                    COUNT(*) total,
                    SUM(CASE WHEN a.status IN ('found-existing','found-web') THEN 1 ELSE 0 END) with_hours,
                    SUM(CASE WHEN a.status='not-required' AND a.relevance='not-required' THEN 1 ELSE 0 END) no_time_needed,
                    SUM(CASE WHEN a.status='not-required' AND a.relevance='excluded' THEN 1 ELSE 0 END) excluded,
                    SUM(CASE WHEN a.status='unknown-after-exhaustive-search' THEN 1 ELSE 0 END) confirmed_unknown,
                    SUM(CASE WHEN a.status IN ('research-queued','research-incomplete','error') THEN 1 ELSE 0 END) technical_open,
                    SUM(CASE WHEN a.place_id IS NULL THEN 1 ELSE 0 END) not_inventoried
             FROM $places p
             LEFT JOIN $a a ON a.place_id=p.id
             WHERE p.active=1 AND p.lifecycle_status='active' AND p.primary_category IN ('food','highlights','culture','activities')
             GROUP BY p.primary_category
             ORDER BY FIELD(p.primary_category,'food','highlights','culture','activities')",
            ARRAY_A
        );
        $out=array();
        foreach($rows as $row){
            $cat=(string)$row['category'];
            $total=(int)$row['total'];$with=(int)$row['with_hours'];$no=(int)$row['no_time_needed'];$excluded=(int)$row['excluded'];$unknown=(int)$row['confirmed_unknown'];$open=(int)$row['technical_open'];$missing=(int)$row['not_inventoried'];
            $needs=max(0,$total-$no-$excluded);
            $coverage=$needs>0?round(100*$with/$needs,1):100.0;
            $out[$cat]=array('category'=>$cat,'total'=>$total,'with_hours'=>$with,'no_time_needed'=>$no,'excluded'=>$excluded,'confirmed_unknown'=>$unknown,'technical_open'=>$open,'not_inventoried'=>$missing,'needs_hours'=>$needs,'coverage'=>$coverage);
        }
        return $out;
    }

    private function opening_audit_snapshot() {
        global $wpdb;$a=$this->table('place_opening_audit');$places=$this->table('places');
        $scope="p.active=1 AND p.lifecycle_status='active' AND p.primary_category IN ('food','highlights','culture','activities')";
        $total=(int)$wpdb->get_var("SELECT COUNT(*) FROM $places p WHERE $scope");
        $rows=(array)$wpdb->get_results("SELECT a.status,COUNT(*) n FROM $a a JOIN $places p ON p.id=a.place_id WHERE $scope GROUP BY a.status",ARRAY_A);$counts=array();foreach($rows as $r)$counts[(string)$r['status']]=(int)$r['n'];
        $src=(array)$wpdb->get_results("SELECT a.source,COUNT(*) n FROM $a a JOIN $places p ON p.id=a.place_id WHERE $scope AND a.opening_hours<>'' GROUP BY a.source ORDER BY n DESC LIMIT 25",ARRAY_A);
        $excluded=(int)$wpdb->get_var("SELECT COUNT(*) FROM $a a JOIN $places p ON p.id=a.place_id WHERE $scope AND a.status='not-required' AND a.relevance='excluded'");
        $not_required=max(0,(int)($counts['not-required']??0)-$excluded);
        $indexed=min($total,array_sum($counts));$queued=(int)($counts['research-queued']??0);$remote_done=(int)($counts['found-web']??0)+(int)($counts['unknown-after-exhaustive-search']??0)+(int)($counts['research-incomplete']??0)+(int)($counts['error']??0);
        $finalized=(int)($counts['found-existing']??0)+(int)($counts['not-required']??0)+$remote_done;$inventory_remaining=max(0,$total-$indexed);$remaining=max(0,$inventory_remaining+$queued);
        $unresolved=(int)($counts['research-incomplete']??0)+(int)($counts['error']??0);
        return array(
            'total'=>$total,'indexed'=>$indexed,'checked'=>$finalized,'remaining'=>$remaining,'inventory_remaining'=>$inventory_remaining,
            'research_queued'=>$queued,'research_done'=>$remote_done,'counts'=>$counts,'sources'=>$src,
            'not_required_public'=>$not_required,'excluded'=>$excluded,'unresolved'=>$unresolved,
            'quality'=>$this->opening_audit_category_quality()
        );
    }

    private function opening_audit_live_state($state,$snap=null) {
        $state=is_array($state)?$state:array();$snap=is_array($snap)?$snap:$this->opening_audit_snapshot();
        if(($state['status']??'')==='finished'){
            $missing=(int)($snap['inventory_remaining']??0);$open=(int)($snap['unresolved']??0);$queued=(int)($snap['research_queued']??0);
            if($missing>0){
                $state['last_message']=$missing.' aktuelle Places sind noch nicht inventarisiert. Der Abschluss-Pass nimmt sie ohne Reset in den bestehenden Audit auf.';
            }elseif($queued>0){
                $state['last_message']=$queued.' aktuelle Places warten noch in der externen Recherche-Queue.';
            }elseif($open>0){
                $state['last_message']='Recherche-Queue vollständig abgearbeitet; '.$open.' Fälle blieben wegen blockierter/fehlgeschlagener Quellenpfade technisch offen und sind ausdrücklich NICHT als unbekannt bestätigt.';
            }else{
                $state['last_message']='Vollständiger zweiphasiger Audit abgeschlossen; der aktuelle Besucherbestand ist inventarisiert und alle identitätsgebundenen Pflichtpfade sind abgearbeitet. Öffentliche Websuche dient nur noch optionaler Discovery.';
            }
        }
        return $state;
    }

    public function ajax_opening_audit_start() {
        if(!current_user_can('manage_options'))wp_send_json_error(array('message'=>'Keine Berechtigung.'),403);
        check_ajax_referer(self::ADMIN_NONCE_ACTION,'nonce');
        global $wpdb;
        $this->opening_audit_stop_worker();
        delete_option('rg_opening_hours_audit_pause_requested_v1112');
        $this->opening_audit_worker_token();
        $wpdb->query('DELETE FROM '.$this->table('place_opening_audit'));
        $snap=$this->opening_audit_snapshot();
        $state=array(
            'status'=>'running','phase'=>'inventory','started_at'=>current_time('mysql'),'finished_at'=>'','last_id'=>0,
            'research_checked'=>0,'found_web'=>0,'errors'=>0,'last_place'=>'',
            'last_message'=>'Phase 1 gestartet: lokaler Datenbestand wird serverseitig inventarisiert',
            'total'=>$snap['total'],'worker_mode'=>'background','worker_last_heartbeat'=>'','worker_runs'=>0
        );
        update_option('rg_opening_hours_audit_state_v1108',$state,false);
        update_option('rg_opening_hours_audit_v1111_migrated',current_time('mysql'),false);
        $this->opening_audit_kick_worker();
        wp_send_json_success(array('state'=>$this->opening_audit_state(),'snapshot'=>$this->opening_audit_snapshot()));
    }

    public function ajax_opening_audit_reset() {
        if(!current_user_can('manage_options'))wp_send_json_error(array('message'=>'Keine Berechtigung.'),403);
        check_ajax_referer(self::ADMIN_NONCE_ACTION,'nonce');
        global $wpdb;
        $this->opening_audit_stop_worker();
        $wpdb->query('DELETE FROM '.$this->table('place_opening_audit'));
        delete_option('rg_opening_hours_audit_state_v1108');
        delete_option('rg_opening_hours_audit_v1110_migrated');
        delete_option('rg_opening_hours_audit_v1111_migrated');
        delete_option('rg_opening_hours_audit_v1125_recovery_started');
        delete_option('rg_opening_hours_audit_v1127_closure_started');
        delete_option('rg_opening_hours_audit_v1129_charset_recovery');
        delete_option('rg_opening_hours_audit_v1130_technical_closure');
        delete_option('rg_opening_hours_audit_v1131_final_salvage');
        delete_option('rg_opening_hours_audit_worker_token_v1112');
        delete_option('rg_opening_hours_audit_pause_requested_v1112');
        wp_send_json_success(array('snapshot'=>$this->opening_audit_snapshot()));
    }

    public function ajax_opening_audit_retry_incomplete() {
        if(!current_user_can('manage_options'))wp_send_json_error(array('message'=>'Keine Berechtigung.'),403);
        check_ajax_referer(self::ADMIN_NONCE_ACTION,'nonce');
        global $wpdb;$audit=$this->table('place_opening_audit');delete_option('rg_opening_hours_audit_pause_requested_v1112');
        $places=$this->table('places');$this->opening_audit_cleanup_scope();
        $n=(int)$wpdb->query("UPDATE $audit a JOIN $places p ON p.id=a.place_id SET a.status='research-queued',a.last_error='',a.updated_at=UTC_TIMESTAMP() WHERE p.active=1 AND p.lifecycle_status='active' AND p.primary_category IN ('food','highlights','culture','activities') AND a.status IN ('research-incomplete','error')");
        $state=$this->opening_audit_state();$state['status']='running';$state['phase']='research';$state['finished_at']='';$state['worker_mode']='background';
        $state['last_message']=$n.' unvollständige/fehlerhafte Fälle erneut in die Recherche-Queue gestellt; Background-Worker läuft.';
        update_option('rg_opening_hours_audit_state_v1108',$state,false);
        $this->opening_audit_kick_worker();
        wp_send_json_success(array('state'=>$this->opening_audit_state(),'snapshot'=>$this->opening_audit_snapshot(),'queued'=>$n));
    }

    public function ajax_opening_audit_finalize() {
        if(!current_user_can('manage_options'))wp_send_json_error(array('message'=>'Keine Berechtigung.'),403);
        check_ajax_referer(self::ADMIN_NONCE_ACTION,'nonce');
        global $wpdb;
        $audit=$this->table('place_opening_audit');$places=$this->table('places');
        $this->opening_audit_cleanup_scope();
        $before=$this->opening_audit_snapshot();
        $requeued=(int)$wpdb->query("UPDATE $audit a JOIN $places p ON p.id=a.place_id SET a.status='research-queued',a.last_error='',a.updated_at=UTC_TIMESTAMP() WHERE p.active=1 AND p.lifecycle_status='active' AND p.primary_category IN ('food','highlights','culture','activities') AND a.status IN ('research-incomplete','error')");
        $missing=(int)($before['inventory_remaining']??0);
        $state=$this->opening_audit_state();
        update_option('rg_opening_hours_audit_v1127_closure_started',current_time('mysql'),false);
        if($missing>0||$requeued>0||(int)($before['research_queued']??0)>0){
            delete_option('rg_opening_hours_audit_pause_requested_v1112');
            $state['status']='running';$state['phase']='research';$state['finished_at']='';$state['worker_mode']='background';
            $state['last_message']='Abschluss-Pass gestartet: '.$missing.' noch nicht inventarisierte Places + '.$requeued.' technisch offene Fälle. Bestätigte Unknowns und gespeicherte Zeiten bleiben unverändert.';
            update_option('rg_opening_hours_audit_state_v1108',$state,false);
            $this->opening_audit_kick_worker();
        }else{
            $state['status']='finished';$state['phase']='finished';$state['last_message']='Kein Abschluss-Pass nötig: aktueller Besucherbestand vollständig inventarisiert, keine technisch offenen Fälle.';
            update_option('rg_opening_hours_audit_state_v1108',$state,false);
        }
        $snap=$this->opening_audit_snapshot();$state=$this->opening_audit_live_state($this->opening_audit_state(),$snap);
        wp_send_json_success(array('state'=>$state,'snapshot'=>$snap,'queued'=>$requeued,'missing'=>$missing));
    }

    private function opening_audit_process_step() {
        global $wpdb;
        $state=$this->opening_audit_state();
        if(($state['status']??'')!=='running')return array('state'=>$state,'snapshot'=>$this->opening_audit_snapshot(),'done'=>true);
        $places=$this->table('places');$audit=$this->table('place_opening_audit');$phase=(string)($state['phase']??'inventory');
        $this->opening_audit_cleanup_scope();

        // v1.10.26: historischer v1.10.11-Migrationspfad bleibt upgrade-sicher, darf aber
        // niemals bereits bestaetigte Unknowns wieder oeffnen. Requeue nur fuer aktuell aktive,
        // oeffentlich genutzte Places mit technisch unvollstaendigem/fehlerhaftem Quellenpfad.
        if($phase==='research'&&!get_option('rg_opening_hours_audit_v1111_migrated',false)){
            $requeued=(int)$wpdb->query("UPDATE $audit a JOIN $places p ON p.id=a.place_id SET a.status='research-queued',a.last_error='',a.updated_at=UTC_TIMESTAMP() WHERE p.active=1 AND p.lifecycle_status='active' AND p.primary_category IN ('food','highlights','culture','activities') AND a.status IN ('research-incomplete','error')");
            update_option('rg_opening_hours_audit_v1111_migrated',current_time('mysql'),false);
            $state['last_message']=$requeued.' technisch offene Altfaelle fuer die stabilisierte Recherche erneut eingequeued.';
            update_option('rg_opening_hours_audit_state_v1108',$state,false);
        }

        if($phase==='inventory'){
            $last=(int)($state['last_id']??0);
            $rows=(array)$wpdb->get_results($wpdb->prepare("SELECT * FROM $places WHERE active=1 AND lifecycle_status='active' AND primary_category IN ('food','highlights','culture','activities') AND id>%d ORDER BY id ASC LIMIT 150",$last),ARRAY_A);
            if(!$rows){
                $state['phase']='research';
                $state['last_message']='Phase 1 abgeschlossen. Phase 2 läuft jetzt serverseitig im Hintergrund weiter.';
                update_option('rg_opening_hours_audit_state_v1108',$state,false);
                return array('state'=>$state,'snapshot'=>$this->opening_audit_snapshot(),'done'=>false,'processed'=>0,'remote_used'=>0);
            }
            $meta_map=$this->rp_labor_place_meta_map($rows);$processed=0;
            foreach($rows as $row){
                $pid=(int)$row['id'];
                $meta=isset($meta_map[$pid])&&is_array($meta_map[$pid])?$meta_map[$pid]:array('opening_hours'=>'','opening_source'=>'','raw_tags'=>array());
                list($needs,$relevance,$why)=$this->opening_audit_requires_hours($row,$meta);
                $attempts=array(array('type'=>'classification','result'=>$relevance,'reason'=>$why));
                if(!$needs){$this->opening_audit_record($pid,$relevance,'not-required','','','',$attempts,'');}
                else{
                    $existing=trim((string)($meta['opening_hours']??''));
                    if($existing!==''){
                        $src=(string)($meta['opening_source']??'existing');$confidence=(strpos(strtolower($src),'redaktion')!==false)?1.0:0.90;
                        $this->opening_audit_save_hours($pid,$existing,$src,'',$confidence,(string)($row['website']??''));
                        $this->opening_audit_record($pid,'needs-hours','found-existing',$src,'',$existing,$attempts,'');
                    }else{$this->opening_audit_record($pid,'needs-hours','research-queued','','','',$attempts,'');}
                }
                $state['last_id']=$pid;$state['last_place']=$row['name'];$processed++;
            }
            $state['last_message']='Lokale Inventur: '.$processed.' weitere Datensätze klassifiziert; Background-Worker läuft.';
            update_option('rg_opening_hours_audit_state_v1108',$state,false);
            return array('state'=>$state,'snapshot'=>$this->opening_audit_snapshot(),'done'=>false,'processed'=>$processed,'remote_used'=>0);
        }

        // Nachinventur neuer relevanter Places ohne Neustart.
        $missing=(array)$wpdb->get_results("SELECT p.* FROM $places p LEFT JOIN $audit a ON a.place_id=p.id WHERE p.active=1 AND p.lifecycle_status='active' AND p.primary_category IN ('food','highlights','culture','activities') AND a.place_id IS NULL ORDER BY p.id ASC LIMIT 50",ARRAY_A);
        if($missing){
            $meta_map=$this->rp_labor_place_meta_map($missing);$processed=0;
            foreach($missing as $mrow){
                $mpid=(int)$mrow['id'];$meta=isset($meta_map[$mpid])&&is_array($meta_map[$mpid])?$meta_map[$mpid]:array('opening_hours'=>'','opening_source'=>'','raw_tags'=>array());
                list($needs,$relevance,$why)=$this->opening_audit_requires_hours($mrow,$meta);$attempts=array(array('type'=>'classification','result'=>$relevance,'reason'=>$why,'catchup'=>true));
                if(!$needs){$this->opening_audit_record($mpid,$relevance,'not-required','','','',$attempts,'');}
                else{
                    $existing=trim((string)($meta['opening_hours']??''));
                    if($existing!==''){$src=(string)($meta['opening_source']??'existing');$confidence=(strpos(strtolower($src),'redaktion')!==false)?1.0:0.90;$this->opening_audit_save_hours($mpid,$existing,$src,'',$confidence,(string)($mrow['website']??''));$this->opening_audit_record($mpid,'needs-hours','found-existing',$src,'',$existing,$attempts,'');}
                    else{$this->opening_audit_record($mpid,'needs-hours','research-queued','','','',$attempts,'');}
                }
                $state['last_place']=$mrow['name'];$processed++;
            }
            $state['last_message']='Nachinventur: '.$processed.' seit Audit-Start neu hinzugekommene Datensätze aufgenommen.';
            update_option('rg_opening_hours_audit_state_v1108',$state,false);
            return array('state'=>$state,'snapshot'=>$this->opening_audit_snapshot(),'done'=>false,'processed'=>$processed,'remote_used'=>0);
        }

        // Phase 2: genau eine unresolved Location pro Worker-Schritt.
        $row=$wpdb->get_row("SELECT p.*,a.last_error AS _audit_last_error FROM $audit a JOIN $places p ON p.id=a.place_id WHERE a.status='research-queued' AND p.active=1 AND p.lifecycle_status='active' AND p.primary_category IN ('food','highlights','culture','activities') ORDER BY a.place_id ASC LIMIT 1",ARRAY_A);
        if(!$row){
            // 1.10.33: Direkt nach Abschluss der laufenden Queue startet serverseitig genau
            // einmal der Delta-Pass ueber historische bestaetigte Unknowns. Ausgeschlossen
            // werden Unknowns, die aus dem unmittelbar vorherigen Final-Salvage stammen,
            // damit dieselben 1.10.31/1.10.32-Methoden nicht sofort doppelt laufen.
            $delta_started=(string)get_option('rg_opening_hours_audit_v1133_unknown_delta_started','');
            $delta_complete=(string)get_option('rg_opening_hours_audit_v1133_unknown_delta_complete','');
            if($delta_started!==''&&$delta_complete===''){
                $baseline=(int)get_option('rg_opening_hours_audit_v1133_unknown_delta_baseline_found_web',0);
                $now_found=(int)$wpdb->get_var("SELECT COUNT(*) FROM $audit a JOIN $places p ON p.id=a.place_id WHERE p.active=1 AND p.lifecycle_status='active' AND p.primary_category IN ('food','highlights','culture','activities') AND a.status='found-web'");
                $gain=max(0,$now_found-$baseline);
                update_option('rg_opening_hours_audit_v1133_unknown_delta_complete',current_time('mysql'),false);
                update_option('rg_opening_hours_audit_v1133_unknown_delta_found',(int)$gain,false);
                $state['last_message']='Delta-Pass 1.10.33 abgeschlossen: '.number_format_i18n($gain).' zusätzliche Öffnungszeiten aus den historischen Unknowns gerettet.';
            }elseif($delta_started===''&&$delta_complete===''){
                $links=$this->table('place_links');$where="p.active=1 AND p.lifecycle_status='active' AND p.primary_category IN ('food','highlights','culture','activities') AND a.status='unknown-after-exhaustive-search' AND COALESCE(a.last_error,'') NOT LIKE 'Letzter offizieller Salvage-Pass abgeschlossen:%' AND COALESCE(a.last_error,'') NOT LIKE 'Letzter Ergebnis-Salvage abgeschlossen:%' AND (TRIM(COALESCE(p.website,''))<>'' OR COALESCE(p.raw_tags,'') LIKE '%opening_hours%' OR COALESCE(p.raw_tags,'') LIKE '%website%' OR EXISTS (SELECT 1 FROM $links l WHERE l.place_id=a.place_id AND l.link_type='website' AND l.status='active'))";
                $eligible=(int)$wpdb->get_var("SELECT COUNT(*) FROM $audit a JOIN $places p ON p.id=a.place_id WHERE $where");
                if($eligible>0){
                    $baseline=(int)$wpdb->get_var("SELECT COUNT(*) FROM $audit a JOIN $places p ON p.id=a.place_id WHERE p.active=1 AND p.lifecycle_status='active' AND p.primary_category IN ('food','highlights','culture','activities') AND a.status='found-web'");
                    $marker='__rpg_unknown_delta_v1133__';
                    $result=$wpdb->query($wpdb->prepare("UPDATE $audit a JOIN $places p ON p.id=a.place_id SET a.status='research-queued',a.last_error=%s,a.updated_at=UTC_TIMESTAMP() WHERE $where",$marker));
                    if($result===false){
                        $state['last_message']='Delta-Pass 1.10.33 konnte die historischen Unknowns nicht einreihen. Datenbankfehler: '.sanitize_text_field((string)$wpdb->last_error);
                        update_option('rg_opening_hours_audit_state_v1108',$state,false);
                        return array('state'=>$state,'snapshot'=>$this->opening_audit_snapshot(),'done'=>false,'processed'=>0,'remote_used'=>0);
                    }
                    if((int)$result>0){
                        update_option('rg_opening_hours_audit_v1133_unknown_delta_started',current_time('mysql'),false);
                        update_option('rg_opening_hours_audit_v1133_unknown_delta_queued',(int)$result,false);
                        update_option('rg_opening_hours_audit_v1133_unknown_delta_baseline_found_web',$baseline,false);
                        $state['status']='running';$state['phase']='research';$state['finished_at']='';$state['worker_mode']='background';
                        $state['last_message']='Automatischer Delta-Pass 1.10.33: '.number_format_i18n((int)$result).' historische Unknowns werden einmalig NUR mit den neuen offiziellen URL-/Pfadvarianten geprüft. Die alte Quellenkette wird nicht wiederholt.';
                        update_option('rg_opening_hours_audit_state_v1108',$state,false);
                        return array('state'=>$state,'snapshot'=>$this->opening_audit_snapshot(),'done'=>false,'processed'=>0,'remote_used'=>0);
                    }
                }
                update_option('rg_opening_hours_audit_v1133_unknown_delta_complete',current_time('mysql'),false);
                update_option('rg_opening_hours_audit_v1133_unknown_delta_found',0,false);
            }
            $snap=$this->opening_audit_snapshot();$incomplete=(int)($snap['counts']['research-incomplete']??0)+(int)($snap['counts']['error']??0);
            $state['status']='finished';$state['phase']='finished';$state['finished_at']=current_time('mysql');
            if(strpos((string)($state['last_message']??''),'Delta-Pass 1.10.33 abgeschlossen:')!==0)$state['last_message']=$incomplete?('Recherche-Queue vollständig abgearbeitet; '.$incomplete.' Fälle blieben wegen blockierter/fehlgeschlagener Pflichtpfade unvollständig und sind ausdrücklich NICHT als unbekannt bestätigt.'):'Vollständiger zweiphasiger Audit einschließlich Delta-Pass 1.10.33 abgeschlossen.';
            update_option('rg_opening_hours_audit_state_v1108',$state,false);
            return array('state'=>$state,'snapshot'=>$snap,'done'=>true,'processed'=>0,'remote_used'=>0);
        }
        $pid=(int)$row['id'];$old=$wpdb->get_row($wpdb->prepare("SELECT attempts_json FROM $audit WHERE place_id=%d",$pid),ARRAY_A);$attempts=json_decode((string)($old['attempts_json']??'[]'),true);if(!is_array($attempts))$attempts=array();$state['research_checked']=(int)($state['research_checked']??0)+1;
        try{
            $found=$this->opening_audit_remote_search($row);$attempts=array_merge($attempts,(array)($found['attempts']??array()));
            if(!empty($found['found'])){
                $this->opening_audit_save_hours($pid,$found['hours'],$found['source'],$found['source_url'],(float)$found['confidence'],(string)($found['website']??''));
                $this->opening_audit_record($pid,'needs-hours','found-web',$found['source'],$found['source_url'],$found['hours'],$attempts,'');
                $state['found_web']=(int)($state['found_web']??0)+1;$state['last_message']='Belastbare Öffnungszeiten gefunden: '.$row['name'];
            }elseif(!empty($found['complete'])){
                $reason=(string)($found['reason']??'web-discovery-exhausted');
                $this->opening_audit_record($pid,'needs-hours','unknown-after-exhaustive-search','','','',$attempts,$this->opening_audit_reason_label($reason));
                $state['last_message']='Nach vollständiger identitätsgebundener Quellenkette weiterhin unbekannt: '.$row['name'];
            }else{
                $reason=(string)($found['reason']??'verified-official-site-blocked');
                $this->opening_audit_record($pid,'needs-hours','research-incomplete','','','',$attempts,$this->opening_audit_reason_label($reason));
                $state['last_message']='Recherche technisch unvollständig: '.$row['name'].' · '.$this->opening_audit_reason_label($reason);
            }
        }catch(Throwable $e){
            $state['errors']=(int)($state['errors']??0)+1;
            $this->opening_audit_record($pid,'needs-hours','error','','','',$attempts,$e->getMessage());
            $state['last_message']='Fehler bei '.$row['name'].': '.$e->getMessage();
        }
        $state['last_place']=$row['name'];
        update_option('rg_opening_hours_audit_state_v1108',$state,false);
        return array('state'=>$state,'snapshot'=>$this->opening_audit_snapshot(),'done'=>false,'processed'=>1,'remote_used'=>1);
    }

    public function ajax_opening_audit_batch() {
        if(!current_user_can('manage_options'))wp_send_json_error(array('message'=>'Keine Berechtigung.'),403);
        check_ajax_referer(self::ADMIN_NONCE_ACTION,'nonce');
        // Kompatibilität mit noch offenen 1.10.11-Admin-Tabs: deren alte JS-Schleife darf
        // ab 1.10.12 keine zweite Verarbeitung mehr starten. Sie stößt nur den Background-Worker an.
        $state=$this->opening_audit_state();
        $heartbeat=(int)($state['worker_heartbeat_ts']??0);
        if(($state['status']??'')==='running'&&(!$heartbeat||$heartbeat<time()-20))$this->opening_audit_kick_worker();
        $state=$this->opening_audit_state();
        wp_send_json_success(array('state'=>$state,'snapshot'=>$this->opening_audit_snapshot(),'done'=>(($state['status']??'')!=='running'),'processed'=>0,'remote_used'=>0));
    }

    private function opening_audit_worker_lock_acquire() {
        $now=time();$old=(int)get_option(self::OPENING_AUDIT_WORKER_LOCK,0);
        if($old && $old<$now-180){delete_option(self::OPENING_AUDIT_WORKER_LOCK);$old=0;}
        if($old)return false;
        return add_option(self::OPENING_AUDIT_WORKER_LOCK,$now,'','no');
    }

    private function opening_audit_worker_lock_release() { delete_option(self::OPENING_AUDIT_WORKER_LOCK); }

    private function opening_audit_worker_token() {
        $token=(string)get_option('rg_opening_hours_audit_worker_token_v1112','');
        if($token===''){
            $token=wp_generate_password(40,false,false);
            update_option('rg_opening_hours_audit_worker_token_v1112',$token,false);
        }
        return $token;
    }

    private function opening_audit_stop_worker() {
        wp_clear_scheduled_hook(self::OPENING_AUDIT_WORKER_HOOK);
        $this->opening_audit_worker_lock_release();
        delete_option('rg_opening_hours_audit_pause_requested_v1112');
    }

    private function opening_audit_schedule_safety($delay=90) {
        wp_clear_scheduled_hook(self::OPENING_AUDIT_WORKER_HOOK);
        wp_schedule_single_event(time()+max(30,(int)$delay),self::OPENING_AUDIT_WORKER_HOOK);
    }

    private function opening_audit_dispatch_async() {
        $state=$this->opening_audit_state();
        if(($state['status']??'')!=='running'||get_option('rg_opening_hours_audit_pause_requested_v1112',false))return false;
        $token=$this->opening_audit_worker_token();
        $url=admin_url('admin-ajax.php');
        $resp=wp_remote_post($url,array(
            'timeout'=>1,'blocking'=>false,'redirection'=>0,
            'sslverify'=>apply_filters('https_local_ssl_verify',false),
            'headers'=>array('Cache-Control'=>'no-cache','X-RuhrpottGuru-Worker'=>'opening-hours-v1112'),
            'body'=>array('action'=>'rg_opening_audit_background_dispatch','token'=>$token)
        ));
        if(is_wp_error($resp)){
            $state=$this->opening_audit_state();
            $state['worker_last_error']='Loopback-Start fehlgeschlagen: '.$resp->get_error_message();
            $state['last_message']='Background-Worker wartet auf den WP-Cron-Sicherheitslauf; Loopback konnte nicht gestartet werden.';
            update_option('rg_opening_hours_audit_state_v1108',$state,false);
            return false;
        }
        return true;
    }

    private function opening_audit_kick_worker() {
        $state=$this->opening_audit_state();
        if(($state['status']??'')!=='running')return false;
        delete_option('rg_opening_hours_audit_pause_requested_v1112');
        $this->opening_audit_schedule_safety(90);
        $started=$this->opening_audit_dispatch_async();
        if(function_exists('spawn_cron'))spawn_cron();
        return $started;
    }

    private function opening_audit_revalidate_date_fragment_v1093() {
        if(get_option('rg_opening_hours_audit_v1093_date_fragment_cleanup',false)) return 0;
        global $wpdb;
        $places=$this->table('places');$schedule=$this->table('place_schedules');$enrichment=$this->table('place_enrichment');$audit=$this->table('place_opening_audit');
        // The only already verified false legacy signature is Scala Kulturspielhaus:
        // 26.02.32-12.09.2003 had been normalized to 02:32-12:09. Do not perform
        // speculative broad deletion of unusual-but-possibly-real opening times.
        $needle='%02:32-12:09%';
        $rows=(array)$wpdb->get_results($wpdb->prepare(
            "SELECT p.id,p.name,p.city,p.opening_hours AS place_hours,s.raw_value AS schedule_hours,s.source AS schedule_source,s.locked,e.opening_hours AS enrichment_hours,e.opening_hours_source
             FROM $places p
             LEFT JOIN $schedule s ON s.place_id=p.id AND s.schedule_type='general'
             LEFT JOIN $enrichment e ON e.place_id=p.id
             WHERE p.active=1 AND (p.opening_hours LIKE %s OR s.raw_value LIKE %s OR e.opening_hours LIKE %s)
             LIMIT 100",$needle,$needle,$needle
        ),ARRAY_A);
        $queued=0;$now=current_time('mysql',true);
        foreach($rows as $row){
            $pid=(int)($row['id']??0);if(!$pid)continue;
            $source=mb_strtolower((string)(($row['schedule_source']??'').' '.($row['opening_hours_source']??'')),'UTF-8');
            $known_scala=(stripos((string)($row['name']??''),'Scala')!==false && stripos((string)($row['city']??''),'Wesel')!==false);
            $web_source=(bool)preg_match('/official|website|resolver|web|salvage/u',$source);
            if(!$known_scala&&!$web_source)continue;
            if((int)($row['locked']??0)===1)continue;
            $wpdb->delete($schedule,array('place_id'=>$pid,'schedule_type'=>'general'),array('%d','%s'));
            if(strpos((string)($row['enrichment_hours']??''),'02:32-12:09')!==false)$wpdb->update($enrichment,array('opening_hours'=>'','opening_hours_source'=>'','updated_at'=>$now),array('place_id'=>$pid));
            if(strpos((string)($row['place_hours']??''),'02:32-12:09')!==false)$wpdb->update($places,array('opening_hours'=>'','updated_at'=>$now),array('id'=>$pid));
            $marker='Parser-Sicherheitsrevalidierung 1.10.93: Datumsfragment 26.02.32-12.09.2003 darf nicht als 02:32-12:09 gelten.';
            $wpdb->query($wpdb->prepare(
                "INSERT INTO $audit (place_id,relevance,status,source,source_url,opening_hours,attempts_json,last_error,checked_at,updated_at)
                 VALUES (%d,'needs-hours','research-queued','','','','[]',%s,%s,%s)
                 ON DUPLICATE KEY UPDATE relevance='needs-hours',status='research-queued',source='',source_url='',opening_hours='',last_error=VALUES(last_error),updated_at=VALUES(updated_at)",
                $pid,$marker,$now,$now
            ));
            $queued++;
        }
        update_option('rg_opening_hours_audit_v1093_date_fragment_cleanup',array('at'=>$now,'queued'=>$queued),false);
        return $queued;
    }

    public function ensure_opening_audit_worker() {
        if(defined('DOING_AJAX')&&DOING_AJAX)return;
        if(defined('DOING_CRON')&&DOING_CRON)return;
        $state=$this->opening_audit_state();
        $date_fragment_queued=$this->opening_audit_revalidate_date_fragment_v1093();
        if($date_fragment_queued>0 && $state && ($state['status']??'')==='finished'){
            delete_option('rg_opening_hours_audit_pause_requested_v1112');
            $state['status']='running';$state['phase']='research';$state['finished_at']='';$state['worker_mode']='background';
            $state['last_message']='Parser-Sicherheitsrevalidierung 1.10.93: '.(int)$date_fragment_queued.' verifizierte Datumsfragment-Altfaelle neu eingereiht; keine anderen gespeicherten Oeffnungszeiten wurden geloescht.';
            update_option('rg_opening_hours_audit_state_v1108',$state,false);
            $state=$this->opening_audit_state();
        }
        // v1.10.69 / Audit 1.10.29: Der reale Restfall "array_map(): Argument #2 ... false given"
        // entsteht ausschliesslich, wenn preg_split('/.../u') bei Legacy-Zeichensaetzen false liefert.
        // Nach dem UTF-8-Fix werden nur genau diese bereits gespeicherten Parserfehler einmalig
        // wieder aufgenommen. Andere Errors/Incomplete-Faelle bleiben fuer eine getrennte Diagnose stehen.
        if($state&&($state['status']??'')==='finished'&&!get_option('rg_opening_hours_audit_v1129_charset_recovery',false)){
