    private function opening_audit_background_run() {
        $state=$this->opening_audit_state();
        if(($state['status']??'')!=='running'||get_option('rg_opening_hours_audit_pause_requested_v1112',false))return;
        if(!$this->opening_audit_worker_lock_acquire())return;
        $continue=false;
        try{
            $state=$this->opening_audit_state();
            $state['worker_mode']='background';
            $state['worker_last_heartbeat']=current_time('mysql');
            $state['worker_heartbeat_ts']=time();
            $state['worker_runs']=(int)($state['worker_runs']??0)+1;
            $state['worker_last_error']='';
            update_option('rg_opening_hours_audit_state_v1108',$state,false);

            // Phase 1: mehrere lokale Blöcke pro Serverrequest. Phase 2: bewusst nur
            // exakt eine externe Location je Request, damit 1blu nicht überlastet wird.
            $max_steps=(($state['phase']??'inventory')==='inventory')?8:1;
            for($i=0;$i<$max_steps;$i++){
                if(get_option('rg_opening_hours_audit_pause_requested_v1112',false))break;
                $result=$this->opening_audit_process_step();
                if(!empty($result['done'])||(($result['state']['status']??'')!=='running'))break;
                if(($result['state']['phase']??'')==='research')break;
            }

            $state=$this->opening_audit_state();
            $state['worker_last_heartbeat']=current_time('mysql');$state['worker_heartbeat_ts']=time();
            if(get_option('rg_opening_hours_audit_pause_requested_v1112',false)){
                $state['status']='paused';$state['last_message']='Background-Worker manuell pausiert. Gespeicherte Ergebnisse bleiben erhalten.';
            }
            update_option('rg_opening_hours_audit_state_v1108',$state,false);
            $continue=(($state['status']??'')==='running');
        }catch(Throwable $e){
            $state=$this->opening_audit_state();
            $state['status']=get_option('rg_opening_hours_audit_pause_requested_v1112',false)?'paused':'running';
            $state['worker_last_error']=$e->getMessage();
            $state['last_message']='Background-Worker: temporärer Fehler – Sicherheitslauf bleibt geplant: '.$e->getMessage();
            $state['worker_last_heartbeat']=current_time('mysql');$state['worker_heartbeat_ts']=time();
            update_option('rg_opening_hours_audit_state_v1108',$state,false);
            $continue=(($state['status']??'')==='running');
        }
        $this->opening_audit_worker_lock_release();

        if($continue){
            $this->opening_audit_schedule_safety(90);
            // Abstand zwischen externen Locations. Danach wird eine NEUE unabhängige
            // Serveranfrage gestartet; die Admin-Seite muss nicht geöffnet sein.
            $state=$this->opening_audit_state();
            if(($state['phase']??'')==='research')sleep(3);
            $this->opening_audit_dispatch_async();
        }else{
            wp_clear_scheduled_hook(self::OPENING_AUDIT_WORKER_HOOK);
        }
    }

    public function cron_opening_audit_worker() {
        $this->opening_audit_background_run();
    }

    public function ajax_opening_audit_background_dispatch() {
        $sent=isset($_POST['token'])?sanitize_text_field(wp_unslash($_POST['token'])):'';
        $expected=(string)get_option('rg_opening_hours_audit_worker_token_v1112','');
        if($expected===''||$sent===''||!hash_equals($expected,$sent)){
            status_header(403);wp_die('Forbidden');
        }
        ignore_user_abort(true);
        if(function_exists('set_time_limit'))@set_time_limit(60);
        nocache_headers();
        $this->opening_audit_background_run();
        wp_die('OK');
    }

    public function ajax_opening_audit_resume() {
        if(!current_user_can('manage_options'))wp_send_json_error(array('message'=>'Keine Berechtigung.'),403);
        check_ajax_referer(self::ADMIN_NONCE_ACTION,'nonce');
        $state=$this->opening_audit_state();
        if(!$state)wp_send_json_error(array('message'=>'Kein gespeicherter Audit vorhanden.'),400);
        $snap=$this->opening_audit_snapshot();
        if(($state['status']??'')==='finished' && (int)($snap['research_queued']??0)===0 && (int)($snap['inventory_remaining']??0)===0){wp_send_json_success(array('state'=>$state,'snapshot'=>$snap,'done'=>true));}
        delete_option('rg_opening_hours_audit_pause_requested_v1112');
        $state['status']='running';if(($state['phase']??'')==='finished')$state['phase']='research';$state['finished_at']='';$state['worker_mode']='background';$state['last_message']='Background-Worker fortgesetzt; Browser/Computer kann geschlossen werden.';
        update_option('rg_opening_hours_audit_state_v1108',$state,false);
        $this->opening_audit_kick_worker();
        wp_send_json_success(array('state'=>$this->opening_audit_state(),'snapshot'=>$this->opening_audit_snapshot(),'done'=>false));
    }

    public function ajax_opening_audit_pause() {
        if(!current_user_can('manage_options'))wp_send_json_error(array('message'=>'Keine Berechtigung.'),403);
        check_ajax_referer(self::ADMIN_NONCE_ACTION,'nonce');
        update_option('rg_opening_hours_audit_pause_requested_v1112',1,false);
        $state=$this->opening_audit_state();$state['status']='paused';$state['last_message']='Background-Worker manuell pausiert. Gespeicherte Ergebnisse bleiben erhalten.';
        update_option('rg_opening_hours_audit_state_v1108',$state,false);
        wp_clear_scheduled_hook(self::OPENING_AUDIT_WORKER_HOOK);
        wp_send_json_success(array('state'=>$state,'snapshot'=>$this->opening_audit_snapshot(),'done'=>true));
    }

    public function ajax_opening_audit_status() {
        if(!current_user_can('manage_options'))wp_send_json_error(array('message'=>'Keine Berechtigung.'),403);
        check_ajax_referer(self::ADMIN_NONCE_ACTION,'nonce');
        $snap=$this->opening_audit_snapshot();$state=$this->opening_audit_live_state($this->opening_audit_state(),$snap);
        wp_send_json_success(array('state'=>$state,'snapshot'=>$snap,'done'=>(($state['status']??'')!=='running')));
    }

    public function render_opening_hours_page() {
        if(!current_user_can('manage_options'))return;global $wpdb;$snap=$this->opening_audit_snapshot();$state=$this->opening_audit_live_state($this->opening_audit_state(),$snap);$audit=$this->table('place_opening_audit');$nonce=wp_create_nonce(self::ADMIN_NONCE_ACTION);$c=$snap['counts'];
        echo '<div class="wrap"><h1>RP Redaktion · Öffnungszeiten-Audit 1.10.33</h1>';
        $delta_started=(string)get_option('rg_opening_hours_audit_v1133_unknown_delta_started','');$delta_complete=(string)get_option('rg_opening_hours_audit_v1133_unknown_delta_complete','');$delta_queued=(int)get_option('rg_opening_hours_audit_v1133_unknown_delta_queued',0);$delta_found=(int)get_option('rg_opening_hours_audit_v1133_unknown_delta_found',0);
        if($delta_started!==''||$delta_complete!=='')echo '<p><strong>Unknown-Delta 1.10.33:</strong> '.($delta_queued?number_format_i18n($delta_queued).' eingereiht · ':'').($delta_complete!==''?('abgeschlossen · +'.number_format_i18n($delta_found).' Öffnungszeiten'):('läuft serverseitig')).'</p>';
        echo '<p><strong>Zwei getrennte Phasen:</strong> Phase 1 inventarisiert den lokalen Bestand schnell und erzeugt nur eine Recherche-Queue. Phase 2 nimmt anschließend <strong>genau eine fehlende relevante Location nach der anderen</strong> und prüft die externe Quellenkette. „Bestätigt unbekannt“ bedeutet: alle identitätsgebundenen Pflichtpfade wurden ohne belastbare Öffnungszeit abgeschlossen; öffentliche Suchmaschinen dienen nur als zusätzliche Discovery und sind kein Pflichtprovider.</p>';
        echo '<div style="background:#fff;border:1px solid #dcdcde;border-radius:8px;padding:14px;margin:14px 0"><strong>Externe Quellenkette:</strong> aktuelles exaktes OSM-Objekt → OSM-Öffnungszeiten/URL → Wikidata P856 → RuhrpottGuru destination.one/eT4-/Website-Resolver → offizielle Website samt relevanter Unterseiten → öffentliche Websuche ausschließlich als <strong>optionale Discovery</strong> weiterer Kandidaten. Ein Ausfall von DuckDuckGo/Bing allein macht einen Datensatz nicht mehr technisch offen. Suchmaschinen-/Verzeichnisdaten werden <strong>nie</strong> als Öffnungszeit gespeichert; ein Kandidat muss als offizielle Betreiber-/kommunale Seite identitätsgeprüft sein. Bekannte offizielle Websites und explizite Öffnungszeiten-Seiten bleiben dagegen kritische Quellenpfade. Gefundene Zeiten werden dauerhaft in <code>place_schedules</code>, <code>place_enrichment</code> und <code>places</code> gespeichert.</div>';
        $cards=array(
            array('key'=>'total','label'=>'Kandidaten gesamt','value'=>$snap['total']),
            array('key'=>'indexed','label'=>'Lokal inventarisiert','value'=>$snap['indexed']),
            array('key'=>'inventory_remaining','label'=>'Noch zu inventarisieren','value'=>$snap['inventory_remaining']),
            array('key'=>'research_queued','label'=>'Recherche-Queue','value'=>$snap['research_queued']),
            array('key'=>'research_done','label'=>'Recherche abgeschlossen','value'=>$snap['research_done']),
            array('key'=>'found_existing','label'=>'Bereits vorhanden','value'=>($c['found-existing']??0)),
            array('key'=>'found_web','label'=>'Neu aus Primärquelle/Web','value'=>($c['found-web']??0)),
            array('key'=>'not_required','label'=>'Keine Zeit nötig','value'=>$snap['not_required_public']),
            array('key'=>'excluded','label'=>'Ausgeschlossen / nicht öffentlich','value'=>$snap['excluded']),
            array('key'=>'unknown','label'=>'Nach voller Recherche unbekannt','value'=>($c['unknown-after-exhaustive-search']??0)),
            array('key'=>'unresolved','label'=>'Technisch offen','value'=>$snap['unresolved']),
            array('key'=>'errors','label'=>'davon Fehler','value'=>($c['error']??0))
        );
        echo '<div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(150px,1fr));gap:10px;margin:14px 0">';foreach($cards as $card)echo '<div style="background:#fff;border:1px solid #dcdcde;border-radius:8px;padding:12px"><div id="rg-oh-card-'.esc_attr($card['key']).'" style="font-size:25px;font-weight:700">'.number_format_i18n((int)$card['value']).'</div><div style="color:#646970">'.esc_html($card['label']).'</div></div>';echo '</div>';
        $invpct=$snap['total']?min(100,round(100*$snap['indexed']/$snap['total'],1)):0;$remote_total=$snap['research_done']+$snap['research_queued'];$respct=$remote_total?min(100,round(100*$snap['research_done']/$remote_total,1)):0;
        echo '<p style="margin-bottom:4px"><strong>Phase 1 · lokale Inventur</strong> <span id="rg-oh-inv-label">'.esc_html($invpct).' %</span></p><div style="height:13px;background:#dcdcde;border-radius:999px;overflow:hidden;max-width:1000px"><div id="rg-oh-inv-bar" style="height:100%;width:'.esc_attr($invpct).'%;background:#3858e9"></div></div>';
        echo '<p style="margin:12px 0 4px"><strong>Phase 2 · echte externe Recherche</strong> <span id="rg-oh-res-label">'.esc_html($respct).' %</span></p><div style="height:13px;background:#dcdcde;border-radius:999px;overflow:hidden;max-width:1000px"><div id="rg-oh-res-bar" style="height:100%;width:'.esc_attr($respct).'%;background:#00a32a"></div></div>';
        $labels=array('food'=>'Food','highlights'=>'Highlights','culture'=>'Kultur','activities'=>'Aktivitäten');
        echo '<h2 style="margin-top:22px">Besucherqualität nach Kategorie</h2><p>Gezählt wird derselbe aktive Besucherbestand wie im Frontend. „Abdeckung“ = Orte mit belastbarer Öffnungszeit geteilt durch alle Orte, bei denen eine Öffnungszeit tatsächlich relevant ist; öffentliche Outdoor-Ziele und ausgeschlossene/geschlossene Orte werden nicht künstlich als fehlend gewertet.</p>';
        echo '<table class="widefat striped" style="max-width:1100px"><thead><tr><th>Kategorie</th><th>Gesamt</th><th>Mit Öffnungszeiten</th><th>Keine Zeit nötig</th><th>Ausgeschlossen</th><th>Bestätigt unbekannt</th><th>Technisch offen</th><th>Nicht inventarisiert</th><th>Abdeckung</th></tr></thead><tbody>';
        foreach(array('food','highlights','culture','activities') as $cat){$q=$snap['quality'][$cat]??array('total'=>0,'with_hours'=>0,'no_time_needed'=>0,'excluded'=>0,'confirmed_unknown'=>0,'technical_open'=>0,'not_inventoried'=>0,'coverage'=>0);echo '<tr><td><strong>'.esc_html($labels[$cat]).'</strong></td><td id="rg-oh-q-'.$cat.'-total">'.number_format_i18n((int)$q['total']).'</td><td id="rg-oh-q-'.$cat.'-with">'.number_format_i18n((int)$q['with_hours']).'</td><td id="rg-oh-q-'.$cat.'-no">'.number_format_i18n((int)$q['no_time_needed']).'</td><td id="rg-oh-q-'.$cat.'-excluded">'.number_format_i18n((int)$q['excluded']).'</td><td id="rg-oh-q-'.$cat.'-unknown">'.number_format_i18n((int)$q['confirmed_unknown']).'</td><td id="rg-oh-q-'.$cat.'-open">'.number_format_i18n((int)$q['technical_open']).'</td><td id="rg-oh-q-'.$cat.'-missing">'.number_format_i18n((int)$q['not_inventoried']).'</td><td id="rg-oh-q-'.$cat.'-coverage">'.esc_html(number_format_i18n((float)$q['coverage'],1)).' %</td></tr>';}
        echo '</tbody></table>';
        echo '<p id="rg-oh-status"><strong>Status:</strong> '.esc_html($state['status']??'noch nicht gestartet').' · Phase '.esc_html($state['phase']??'—').(!empty($state['last_place'])?' · zuletzt '.esc_html($state['last_place']):'').(!empty($state['last_message'])?' · '.esc_html($state['last_message']):'').'</p>';
        echo '<p><button class="button button-primary" id="rg-oh-start">Neuen zweiphasigen Audit starten</button> <button class="button" id="rg-oh-resume">Background-Audit fortsetzen</button> <button class="button" id="rg-oh-pause">Background-Audit pausieren</button> <button class="button button-secondary" id="rg-oh-finalize">Abschluss-Pass starten</button> <button class="button" id="rg-oh-retry">Unvollständige Fälle erneut prüfen</button> <button class="button" id="rg-oh-reset">Audit-Status zurücksetzen</button></p>';
        echo '<p><strong>Worker:</strong> '.esc_html((string)($state['worker_mode']??'—')).' · letzter Lauf: '.esc_html((string)($state['worker_last_heartbeat']??'noch keiner')).(!empty($state['worker_last_error'])?' · letzter Worker-Fehler: '.esc_html((string)$state['worker_last_error']):'').'</p>';
        echo '<p><small><strong>Serverseitiger Background-Worker:</strong> Nach Start/Fortsetzen läuft der Audit unabhängig von diesem Browser-Tab weiter. Du kannst andere WordPress-Seiten öffnen, Themes installieren oder den Rechner ausschalten. Phase 2 bleibt bewusst gedrosselt. Der Zeitstempel des letzten Worker-Laufs zeigt, ob der Server weiterarbeitet.</small></p>';
        if($snap['sources']){echo '<h2>Gefundene Quellen</h2><table class="widefat striped" style="max-width:900px"><thead><tr><th>Quelle</th><th>Treffer</th></tr></thead><tbody>';foreach($snap['sources'] as $r)echo '<tr><td>'.esc_html($r['source']?:'—').'</td><td>'.number_format_i18n((int)$r['n']).'</td></tr>';echo '</tbody></table>';}
        $case=isset($_GET['rg_oh_case'])?sanitize_key(wp_unslash($_GET['rg_oh_case'])):'technical';if(!in_array($case,array('technical','error','research-incomplete','unknown','all'),true))$case='technical';
        $case_defs=array(
            'technical'=>array('label'=>'Technisch offen','where'=>"a.status IN ('research-incomplete','error')",'count'=>(int)$snap['unresolved']),
            'error'=>array('label'=>'Fehler','where'=>"a.status='error'",'count'=>(int)($c['error']??0)),
            'research-incomplete'=>array('label'=>'Quellenpfad unvollständig','where'=>"a.status='research-incomplete'",'count'=>(int)($c['research-incomplete']??0)),
            'unknown'=>array('label'=>'Bestätigt unbekannt','where'=>"a.status='unknown-after-exhaustive-search'",'count'=>(int)($c['unknown-after-exhaustive-search']??0)),
            'all'=>array('label'=>'Alle Restfälle','where'=>"a.status IN ('unknown-after-exhaustive-search','research-incomplete','error')",'count'=>(int)$snap['unresolved']+(int)($c['unknown-after-exhaustive-search']??0))
        );
        echo '<h2 style="margin-top:24px">Recherche-Restfälle</h2><p style="display:flex;gap:8px;flex-wrap:wrap">';foreach($case_defs as $ck=>$def){$url=add_query_arg(array('page'=>'rp-opening-hours','rg_oh_case'=>$ck),admin_url('admin.php'));$cls=$case===$ck?'button button-primary':'button';echo '<a class="'.esc_attr($cls).'" href="'.esc_url($url).'">'.esc_html($def['label']).' ('.number_format_i18n((int)$def['count']).')</a>'; }echo '</p>';
        if(($c['research-incomplete']??0)>0){$groups=(array)$wpdb->get_results("SELECT a.last_error,COUNT(*) n,MAX(a.checked_at) last_checked FROM $audit a JOIN ".$this->table('places')." p ON p.id=a.place_id WHERE p.active=1 AND p.lifecycle_status='active' AND p.primary_category IN ('food','highlights','culture','activities') AND a.status='research-incomplete' GROUP BY a.last_error ORDER BY n DESC,last_checked DESC LIMIT 20",ARRAY_A);if($groups){echo '<h3>Technische Quellen-Signaturen</h3><table class="widefat striped" style="max-width:1200px"><thead><tr><th>Ursache</th><th>Anzahl</th><th>zuletzt</th></tr></thead><tbody>';foreach($groups as $g)echo '<tr><td><code>'.esc_html((string)$g['last_error']).'</code></td><td>'.number_format_i18n((int)$g['n']).'</td><td>'.esc_html((string)$g['last_checked']).'</td></tr>';echo '</tbody></table>';}}
        if(($c['error']??0)>0){$groups=(array)$wpdb->get_results("SELECT a.last_error,COUNT(*) n,MAX(a.checked_at) last_checked FROM $audit a JOIN ".$this->table('places')." p ON p.id=a.place_id WHERE p.active=1 AND p.lifecycle_status='active' AND p.primary_category IN ('food','highlights','culture','activities') AND a.status='error' GROUP BY a.last_error ORDER BY n DESC,last_checked DESC LIMIT 20",ARRAY_A);if($groups){echo '<h3>Fehlersignaturen</h3><table class="widefat striped" style="max-width:1200px"><thead><tr><th>Fehler</th><th>Anzahl</th><th>zuletzt</th></tr></thead><tbody>';foreach($groups as $g)echo '<tr><td><code>'.esc_html((string)$g['last_error']).'</code></td><td>'.number_format_i18n((int)$g['n']).'</td><td>'.esc_html((string)$g['last_checked']).'</td></tr>';echo '</tbody></table>';}}
        $def=$case_defs[$case];$cases=(array)$wpdb->get_results("SELECT a.place_id,p.name,p.city,p.primary_category,a.status,a.last_error,a.checked_at FROM $audit a JOIN ".$this->table('places')." p ON p.id=a.place_id WHERE p.active=1 AND p.lifecycle_status='active' AND p.primary_category IN ('food','highlights','culture','activities') AND ".$def['where']." ORDER BY a.checked_at DESC LIMIT 500",ARRAY_A);
        if($cases){echo '<h3>'.esc_html($def['label']).'</h3><p><small>Es werden maximal 500 der neuesten passenden Fälle angezeigt. Die Zähler oben beziehen sich auf den vollständigen Bestand.</small></p><table class="widefat striped" style="max-width:1200px"><thead><tr><th>Place</th><th>Ort</th><th>Kategorie</th><th>Status</th><th>Diagnose</th><th>geprüft</th></tr></thead><tbody>';foreach($cases as $r)echo '<tr><td><strong>'.esc_html($r['name']).'</strong><br>#'.intval($r['place_id']).'</td><td>'.esc_html($r['city']).'</td><td>'.esc_html($r['primary_category']).'</td><td>'.esc_html($r['status']).'</td><td>'.esc_html($r['last_error']).'</td><td>'.esc_html($r['checked_at']).'</td></tr>';echo '</tbody></table>';}
        echo '<script>(function(){const nonce='.wp_json_encode($nonce).',status=document.getElementById("rg-oh-status"),invbar=document.getElementById("rg-oh-inv-bar"),resbar=document.getElementById("rg-oh-res-bar"),invlabel=document.getElementById("rg-oh-inv-label"),reslabel=document.getElementById("rg-oh-res-label"),start=document.getElementById("rg-oh-start"),resume=document.getElementById("rg-oh-resume"),pause=document.getElementById("rg-oh-pause"),finalize=document.getElementById("rg-oh-finalize"),retry=document.getElementById("rg-oh-retry"),reset=document.getElementById("rg-oh-reset");const num=v=>new Intl.NumberFormat("de-DE").format(Number(v||0));function setCard(k,v){const e=document.getElementById("rg-oh-card-"+k);if(e)e.textContent=num(v);}async function call(action){const b=new URLSearchParams({action,nonce});const r=await fetch(ajaxurl,{method:"POST",credentials:"same-origin",headers:{"Content-Type":"application/x-www-form-urlencoded;charset=UTF-8","Accept":"application/json"},body:b});const text=await r.text();let j=null;try{j=JSON.parse(text);}catch(e){throw new Error("Serverantwort war kein JSON (HTTP "+r.status+")");}if(!r.ok||!j.success)throw new Error(j&&j.data&&j.data.message?j.data.message:"AJAX fehlgeschlagen");return j.data;}function draw(d){const s=d.snapshot||{},c=s.counts||{},st=d.state||{},total=Number(s.total||0),idx=Number(s.indexed||0),rd=Number(s.research_done||0),rq=Number(s.research_queued||0),ip=total?Math.min(100,Math.round(idx*1000/total)/10):0,rp=(rd+rq)?Math.min(100,Math.round(rd*1000/(rd+rq))/10):0;invbar.style.width=ip+"%";resbar.style.width=rp+"%";invlabel.textContent=ip+" %";reslabel.textContent=rp+" %";setCard("total",total);setCard("indexed",idx);setCard("inventory_remaining",s.inventory_remaining||0);setCard("research_queued",rq);setCard("research_done",rd);setCard("found_existing",c["found-existing"]||0);setCard("found_web",c["found-web"]||0);setCard("not_required",s.not_required_public||0);setCard("excluded",s.excluded||0);setCard("unknown",c["unknown-after-exhaustive-search"]||0);setCard("unresolved",s.unresolved||0);setCard("errors",c.error||0);const q=s.quality||{};["food","highlights","culture","activities"].forEach(cat=>{const x=q[cat]||{},map={total:x.total||0,with:x.with_hours||0,no:x.no_time_needed||0,excluded:x.excluded||0,unknown:x.confirmed_unknown||0,open:x.technical_open||0,missing:x.not_inventoried||0};Object.keys(map).forEach(k=>{const e=document.getElementById("rg-oh-q-"+cat+"-"+k);if(e)e.textContent=num(map[k]);});const ce=document.getElementById("rg-oh-q-"+cat+"-coverage");if(ce)ce.textContent=Number(x.coverage||0).toLocaleString("de-DE",{minimumFractionDigits:1,maximumFractionDigits:1})+" %";});status.textContent="Status: "+(st.status||"—")+" · Phase "+(st.phase||"—")+(st.last_place?" · zuletzt "+st.last_place:"")+(st.last_message?" · "+st.last_message:"")+(st.worker_last_heartbeat?" · Worker "+st.worker_last_heartbeat:"");}async function refresh(){try{draw(await call("rg_opening_audit_status"));}catch(e){status.textContent="Statusanzeige konnte nicht aktualisiert werden: "+e.message;}}start.addEventListener("click",async()=>{if(!confirm("Neuen Audit starten? Der alte Audit-Status wird gelöscht. Bereits dauerhaft gespeicherte Öffnungszeiten bleiben erhalten."))return;try{draw(await call("rg_opening_audit_start"));}catch(e){alert(e.message);}});resume.addEventListener("click",async()=>{try{draw(await call("rg_opening_audit_resume"));}catch(e){alert(e.message);}});pause.addEventListener("click",async()=>{try{draw(await call("rg_opening_audit_pause"));}catch(e){alert(e.message);}});finalize.addEventListener("click",async()=>{if(!confirm("Abschluss-Pass starten? Es werden nur aktuell fehlende Inventarzeilen sowie technisch unvollständige/fehlerhafte Fälle bearbeitet. Bestätigte Unknowns und gespeicherte Öffnungszeiten bleiben unverändert."))return;try{draw(await call("rg_opening_audit_finalize"));}catch(e){alert(e.message);}});retry.addEventListener("click",async()=>{if(!confirm("Alle technisch unvollständigen/fehlerhaften Fälle erneut in die Recherche-Queue stellen?"))return;try{draw(await call("rg_opening_audit_retry_incomplete"));}catch(e){alert(e.message);}});reset.addEventListener("click",async()=>{if(!confirm("Nur den Audit-Status zurücksetzen? Gespeicherte Öffnungszeiten bleiben erhalten."))return;try{await call("rg_opening_audit_reset");window.location.reload();}catch(e){alert(e.message);}});setInterval(refresh,5000);refresh();})();</script>';
        echo '</div>';
    }

    /** V1.10.109: one compact workspace shell for every RP Redaktion subpage. */
    private function rp_redaktion_screen_v101109() {
        if(!is_admin())return false;
        $page=sanitize_key((string)($_GET['page']??''));
        $post_type=sanitize_key((string)($_GET['post_type']??''));
        if(in_array($page,array('rp-redaktion','rp-places','rp-redaktion-medien','rp-events','rp-labor','rp-opening-hours'),true))return true;
        if($post_type==='rpg_community')return true;
        global $typenow;return sanitize_key((string)$typenow)==='rpg_community';
    }

    private function rp_redaktion_active_v101109() {
        $page=sanitize_key((string)($_GET['page']??''));$post_type=sanitize_key((string)($_GET['post_type']??''));
        global $typenow;if($post_type==='rpg_community'||sanitize_key((string)$typenow)==='rpg_community')return 'community';
        $map=array('rp-redaktion'=>'data','rp-places'=>'places','rp-redaktion-medien'=>'media','rp-events'=>'events','rp-labor'=>'labor','rp-opening-hours'=>'hours');
        return $map[$page]??'';
    }

    public function render_rp_redaktion_nav_v101109() {
        if(!$this->rp_redaktion_screen_v101109())return;
        if(!current_user_can('edit_posts'))return;
        $active=$this->rp_redaktion_active_v101109();
        $items=array(
            'data'=>array('Daten',add_query_arg(array('page'=>'rp-redaktion'),admin_url('admin.php'))),
            'places'=>array('Places',add_query_arg(array('page'=>'rp-places'),admin_url('admin.php'))),
            'media'=>array('Medien',add_query_arg(array('page'=>'rp-redaktion-medien'),admin_url('admin.php'))),
            'events'=>array('Events',add_query_arg(array('page'=>'rp-events'),admin_url('admin.php'))),
            'labor'=>array('Labor',add_query_arg(array('page'=>'rp-labor'),admin_url('admin.php'))),
            'hours'=>array('Öffnungszeiten',add_query_arg(array('page'=>'rp-opening-hours'),admin_url('admin.php'))),
            'community'=>array('Community',admin_url('edit.php?post_type=rpg_community')),
        );
        echo '<style id="rg-redaktion-ux-v101109">
        .rg-redaktion-workspace{position:sticky;top:32px;z-index:100;margin:8px 20px 14px 2px;background:rgba(255,255,255,.98);border:1px solid #c3c4c7;border-radius:10px;box-shadow:0 2px 6px rgba(0,0,0,.06);padding:8px}.rg-redaktion-workspace-row{display:flex;gap:6px;align-items:center;flex-wrap:wrap}.rg-redaktion-brand{font-weight:800;padding:7px 9px;margin-right:2px}.rg-redaktion-link{padding:7px 10px;border-radius:7px;text-decoration:none;font-weight:650;color:#1d2327}.rg-redaktion-link:hover{background:#f0f0f1;color:#1d2327}.rg-redaktion-link.is-active{background:#1d2327;color:#fff}.rg-redaktion-spacer{flex:1 1 24px}.rg-redaktion-controls{display:flex;gap:6px;align-items:center;flex-wrap:wrap}.rg-redaktion-fold-count{color:#646970;font-size:12px;margin-right:2px}.rg-redaktion-fold{max-width:1200px;margin:12px 0;border:1px solid #dcdcde;background:#fff;border-radius:9px;overflow:hidden}.rg-redaktion-fold>summary{cursor:pointer;list-style:none;font-weight:750;padding:12px 14px;background:#f6f7f7;display:flex;align-items:center;gap:8px}.rg-redaktion-fold>summary::-webkit-details-marker{display:none}.rg-redaktion-fold>summary:before{content:"▸";font-size:12px;transition:transform .15s ease}.rg-redaktion-fold[open]>summary:before{transform:rotate(90deg)}.rg-redaktion-fold[open]>summary{border-bottom:1px solid #dcdcde}.rg-redaktion-fold-body{padding:14px 16px}.rg-redaktion-fold-body>:first-child{margin-top:0}.rg-redaktion-fold-body>:last-child{margin-bottom:0}.rg-redaktion-fold .rg-admin-card{max-width:none;margin:0;border:0;border-radius:0;box-shadow:none}.rg-redaktion-fold .rg-admin-details{max-width:none}.rg-redaktion-submission-summary{display:flex;gap:8px;align-items:center;flex-wrap:wrap;width:100%}.rg-redaktion-submission-meta{font-weight:400;color:#646970;font-size:12px}.rg-place-workspace .rg-place-admin-tabs{top:88px!important}.rg-redaktion-compact-note{color:#646970;font-size:12px}.rg-redaktion-auto-section>summary .count{font-weight:500;color:#646970}.rg-redaktion-auto-section h2{display:none}.post-type-rpg_community .rg-redaktion-workspace{margin-left:0}
        @media(max-width:782px){.rg-redaktion-workspace{top:46px;margin-right:10px}.rg-redaktion-brand{width:100%}.rg-redaktion-spacer{display:none}.rg-redaktion-controls{width:100%}.rg-place-workspace .rg-place-admin-tabs{top:138px!important}}
        </style>';
        echo '<div class="rg-redaktion-workspace" data-rg-redaktion-workspace><div class="rg-redaktion-workspace-row"><span class="rg-redaktion-brand">RP Redaktion</span>';
        foreach($items as $key=>$item){$class='rg-redaktion-link'.($active===$key?' is-active':'');echo '<a class="'.esc_attr($class).'" href="'.esc_url($item[1]).'">'.esc_html($item[0]).'</a>';}
        echo '<span class="rg-redaktion-spacer"></span><div class="rg-redaktion-controls"><span class="rg-redaktion-fold-count" id="rg-redaktion-fold-count"></span><button type="button" class="button button-small" id="rg-redaktion-fold-close">Alles einklappen</button><button type="button" class="button button-small" id="rg-redaktion-fold-open">Alles öffnen</button></div></div></div>';
    }

    /** V1.10.109: fold long admin sections without changing their forms, IDs or worker logic. */
    public function render_rp_redaktion_ui_v101109() {
        if(!$this->rp_redaktion_screen_v101109())return;
        $active=$this->rp_redaktion_active_v101109();
