        echo '<label><strong>Anzeigen</strong><br><select name="lab_limit">';foreach(array(25,50,100,200) as $n)echo '<option value="'.$n.'" '.selected($show,$n,false).'>'.$n.'</option>';echo '</select></label><button class="button">Diagnose filtern</button></form>';

