        echo '<div style="overflow:auto"><table class="widefat striped"><thead><tr><th>Treffer</th><th>Kategorie</th><th>Entfernung</th><th>JETZT-Status</th><th>Nutzbarkeit</th><th>Score</th><th>Entscheidung</th><th>Diagnose</th></tr></thead><tbody>';
        if(!$filtered)echo '<tr><td colspan="8">Für diesen Filter keine Kandidaten.</td></tr>';
        foreach($filtered as $item){$badge=$item['decision']==='in'?'#d1e7dd':($item['decision']==='candidate'?'#fff3cd':'#f8d7da');$detail=implode(' · ',(array)$item['reasons']);
            echo '<tr><td><strong>'.esc_html($item['title']).'</strong><br><span style="color:#646970">'.esc_html($item['city']).' · ID '.(int)$item['id'].'</span>'.($item['time_text']?'<br><span style="font-size:12px">'.esc_html($item['time_text']).'</span>':'').'</td><td>'.esc_html($this->rp_labor_category_label($item['category'])).'</td><td>'.esc_html(number_format((float)$item['distance_km'],1,',','.')).' km</td><td>'.esc_html($item['status']).($item['opening_hours']?'<details style="margin-top:5px"><summary>Öffnungsdaten</summary><code style="white-space:normal">'.esc_html($item['opening_hours']).'</code><br><small>'.esc_html($item['opening_source']).'</small></details>':'').'</td><td>'.esc_html(($item['availability_mode']??'unknown').' · '.($item['availability_confidence']??'')).'</td><td><strong>'.esc_html(number_format((float)$item['score'],1,',','.')).'</strong></td><td><span style="display:inline-block;background:'.$badge.';border-radius:999px;padding:4px 9px;font-weight:600">'.esc_html($item['decision_label']).'</span></td><td><details><summary>Warum?</summary><div style="max-width:360px;padding-top:5px">'.esc_html($detail).'</div></details></td></tr>';
        }echo '</tbody></table></div>';
        echo '<div style="margin-top:16px;padding:12px 14px;background:#f6f7f7;border-radius:8px;color:#50575e"><strong>Bewusst konservativ:</strong> Komplexe oder unbekannte Öffnungszeiten werden nicht als geschlossen interpretiert. Sie bleiben „Unsicher“. 1.10.5/1.10.6: über dem Roh-Pool liegt eine rein interne 6–10-Treffer-Auswahl mit Qualitätsgate; Stadt-Testkoordinaten werden bei Auto-Modus aus dem Kommunen-Katalog aufgelöst. Vielfalt bleibt Ziel, aber schwache Kategorien werden nicht künstlich aufgefüllt. Outdoor- und Open-End-Fixes aus 1.10.1 bleiben erhalten. Score und Auswahlregel sind weiterhin Laborwerte, noch keine produktive Rankingregel.</div>';
        echo '</div></div>';
    }

    private function event_cache_stats() {
        global $wpdb;
        $events=$this->table('events');
        $now=current_time('mysql');
        // One indexed pass instead of five independent dashboard queries. media_status is
        // maintained by the enrichment/media pipeline and is sufficient for the KPI card.
        $row=$wpdb->get_row($wpdb->prepare(
            "SELECT COUNT(*) AS total,
                SUM(CASE WHEN status='active' AND (end_at IS NULL OR end_at >= %s) THEN 1 ELSE 0 END) AS upcoming,
                SUM(CASE WHEN status='active' AND (end_at IS NULL OR end_at >= %s) AND (street='' OR postcode='' OR city='') THEN 1 ELSE 0 END) AS missing_address,
                SUM(CASE WHEN status='active' AND (end_at IS NULL OR end_at >= %s) AND media_status<>'verified' THEN 1 ELSE 0 END) AS missing_media,
                SUM(CASE WHEN status='active' AND (end_at IS NULL OR end_at >= %s) AND enrichment_status IN ('pending','retry') THEN 1 ELSE 0 END) AS pending_enrichment
             FROM $events",
            $now,$now,$now,$now
        ),ARRAY_A);
        if(!is_array($row))$row=array();
        return array(
            'total'=>(int)($row['total']??0),
            'upcoming'=>(int)($row['upcoming']??0),
            'missing_address'=>(int)($row['missing_address']??0),
            'missing_media'=>(int)($row['missing_media']??0),
            'pending_enrichment'=>(int)($row['pending_enrichment']??0),
        );
    }


    private function event_active_source_balance() {
        global $wpdb;
        $events=$this->table('events');
        $now=current_time('mysql');
        $token=$this->event_latest_master_token();
        $bucket="CASE WHEN last_master_run=%s THEN 'Master / Open Data Finder' WHEN source='destination_one_open_data' THEN 'destination.one Zusatzfeed' WHEN source='essen_emg_export' THEN 'Essen EMG' ELSE CONCAT('Sonstige · ',source) END";
        $object="CASE WHEN external_id<>'' THEN external_id ELSE CONCAT('__row_',id) END";
        $inner=$wpdb->prepare(
            "SELECT $bucket AS bucket, $object AS object_key, COUNT(*) AS term_count
             FROM $events
             WHERE status='active' AND (end_at IS NULL OR end_at >= %s)
             GROUP BY bucket, object_key",
            $token,$now
        );
        $rows=(array)$wpdb->get_results(
            "SELECT bucket, COUNT(*) AS source_objects,
                    SUM(term_count) AS terms,
                    SUM(CASE WHEN term_count=1 THEN 1 ELSE 0 END) AS single_objects,
                    SUM(CASE WHEN term_count>1 THEN 1 ELSE 0 END) AS series_objects,
                    MAX(term_count) AS max_terms_per_object
             FROM ($inner) q
             GROUP BY bucket
             ORDER BY terms DESC, bucket ASC",
            ARRAY_A
        );
        $tot=array('source_objects'=>0,'terms'=>0,'single_objects'=>0,'series_objects'=>0);
        foreach($rows as &$r){
            foreach(array('source_objects','terms','single_objects','series_objects','max_terms_per_object') as $k)$r[$k]=(int)($r[$k]??0);
            $tot['source_objects']+=$r['source_objects'];$tot['terms']+=$r['terms'];$tot['single_objects']+=$r['single_objects'];$tot['series_objects']+=$r['series_objects'];
        }unset($r);
        return array('rows'=>$rows,'total'=>$tot,'at'=>$now);
    }


    private function event_series_rest_diagnostic_snapshot() {
        global $wpdb;
        $events=$this->table('events');
        $now=current_time('mysql');
        $token=$this->event_latest_master_token();
        $bucket="CASE WHEN last_master_run=%s THEN 'Master / Open Data Finder' WHEN source='destination_one_open_data' THEN 'destination.one Zusatzfeed' WHEN source='essen_emg_export' THEN 'Essen EMG' ELSE CONCAT('Sonstige · ',source) END";
        $topSql=$wpdb->prepare(
            "SELECT $bucket AS bucket, source, external_id,
                    MAX(title) AS title, MAX(city) AS city,
                    COUNT(*) AS terms,
                    COUNT(DISTINCT DATE(start_at)) AS active_days,
                    MIN(start_at) AS first_term, MAX(start_at) AS last_term
             FROM $events
             WHERE status='active' AND (end_at IS NULL OR end_at >= %s) AND external_id<>''
             GROUP BY bucket, source, external_id
             HAVING COUNT(*)>1
             ORDER BY terms DESC, bucket ASC, title ASC
             LIMIT 25",
            $token,$now
        );
        $top=(array)$wpdb->get_results($topSql,ARRAY_A);
        foreach($top as &$r){
            $r['terms']=(int)($r['terms']??0);
            $r['active_days']=(int)($r['active_days']??0);
            $r['terms_per_day']=$r['active_days']>0?round($r['terms']/$r['active_days'],2):0;
        }unset($r);

        $legacyWhere=$wpdb->prepare(
            "status='active' AND (end_at IS NULL OR end_at >= %s) AND source='open_data_finder' AND (last_master_run<>%s OR last_master_run='')",
            $now,$token
        );
        $legacyTotal=(int)$wpdb->get_var("SELECT COUNT(*) FROM $events WHERE $legacyWhere");
        $legacyCities=(array)$wpdb->get_results(
            "SELECT city,COUNT(*) AS n FROM $events WHERE $legacyWhere GROUP BY city ORDER BY n DESC,city ASC LIMIT 25",
            ARRAY_A
        );
        $sameObject=0;
        if($token!==''){
            $sameObject=(int)$wpdb->get_var($wpdb->prepare(
                "SELECT COUNT(*) FROM $events o
                 WHERE o.status='active' AND (o.end_at IS NULL OR o.end_at >= %s)
                   AND o.source='open_data_finder' AND (o.last_master_run<>%s OR o.last_master_run='')
                   AND o.external_id<>'' AND EXISTS (
                     SELECT 1 FROM $events m
                     WHERE m.last_master_run=%s AND m.external_id=o.external_id
                   )",
                $now,$token,$token
            ));
        }
        $legacyRows=(array)$wpdb->get_results(
            "SELECT id,title,city,start_at,end_at,external_id,first_seen_at,last_synced_at,source_url,last_master_run
             FROM $events
             WHERE $legacyWhere
             ORDER BY start_at ASC,id ASC
             LIMIT 60",
            ARRAY_A
        );
        return array(
            'top_series'=>$top,
            'legacy_total'=>$legacyTotal,
            'legacy_same_object_in_master'=>$sameObject,
            'legacy_cities'=>$legacyCities,
            'legacy_rows'=>$legacyRows,
            'at'=>$now
        );
    }

    private function event_source_audit_snapshot() {
        global $wpdb;
        $events=$this->table('events');
        $now=current_time('mysql');
        $night=get_option('rg_events_nightly_state',array());if(!is_array($night))$night=array();
        $token=sanitize_key((string)($night['run_token']??''));
        $where="status='active' AND (end_at IS NULL OR end_at >= %s)";
        $total=(int)$wpdb->get_var($wpdb->prepare("SELECT COUNT(*) FROM $events WHERE $where",$now));
        $master=0;$outside=$total;
        if($token!==''){
            $master=(int)$wpdb->get_var($wpdb->prepare("SELECT COUNT(*) FROM $events WHERE $where AND last_master_run=%s",$now,$token));
            $outside=max(0,$total-$master);
        }
        if($token!==''){
            $sql=$wpdb->prepare("SELECT source,COUNT(*) AS upcoming,SUM(CASE WHEN last_master_run=%s THEN 1 ELSE 0 END) AS in_master,SUM(CASE WHEN last_master_run<>%s OR last_master_run='' THEN 1 ELSE 0 END) AS outside_master,MIN(first_seen_at) AS first_seen,MAX(last_synced_at) AS last_synced FROM $events WHERE status='active' AND (end_at IS NULL OR end_at >= %s) GROUP BY source ORDER BY upcoming DESC,source ASC",$token,$token,$now);
        }else{
            $sql=$wpdb->prepare("SELECT source,COUNT(*) AS upcoming,0 AS in_master,COUNT(*) AS outside_master,MIN(first_seen_at) AS first_seen,MAX(last_synced_at) AS last_synced FROM $events WHERE status='active' AND (end_at IS NULL OR end_at >= %s) GROUP BY source ORDER BY upcoming DESC,source ASC",$now);
        }
        $rows=(array)$wpdb->get_results($sql,ARRAY_A);
        $dup=$wpdb->get_row($wpdb->prepare("SELECT COUNT(*) AS groups_count,COALESCE(SUM(n-1),0) AS extra_rows FROM (SELECT LOWER(TRIM(title)) t,start_at,LOWER(TRIM(city)) c,COUNT(*) n FROM $events WHERE status='active' AND (end_at IS NULL OR end_at >= %s) GROUP BY LOWER(TRIM(title)),start_at,LOWER(TRIM(city)) HAVING COUNT(*)>1) d",$now),ARRAY_A);
        if(!is_array($dup))$dup=array('groups_count'=>0,'extra_rows'=>0);
        $ambiguous=0;$supplemental=0;$legacy=0;
        foreach($rows as &$r){
            $src=(string)($r['source']??'');$out=(int)($r['outside_master']??0);
            $r['class']='other';$r['note']='';
            if($src==='essen_emg_export'){$r['class']='supplemental';$r['note']='offizieller Zusatzexport Essen';$supplemental+=$out;}
            elseif($src==='destination_one_open_data'){$r['class']='supplemental';$r['note']='öffentlicher destination.one/Open-Data-Pool';$supplemental+=$out;}
            elseif($src==='verified-official-wesel'){$r['class']='legacy';$r['note']='älterer verifizierter Wesel-Fallback';$legacy+=$out;}
            elseif($src==='open_data_finder' && $out>0){$r['class']='ambiguous';$r['note']='außerhalb des letzten Masters: Altbestand oder früherer öffentlicher Pool; wegen alter Quellenkennzeichnung einzeln prüfen';$ambiguous+=$out;}
            elseif($src==='open_data_finder'){$r['class']='master';$r['note']='Open-Data-Finder-Master';}
            else{$legacy+=$out;$r['note']='nicht im aktuellen Masterlauf; Quelle prüfen';}
        }unset($r);
        return array('token'=>$token,'total'=>$total,'master'=>$master,'outside'=>$outside,'rows'=>$rows,'ambiguous'=>$ambiguous,'supplemental'=>$supplemental,'legacy_other'=>$legacy,'duplicate_groups'=>(int)($dup['groups_count']??0),'duplicate_extra_rows'=>(int)($dup['extra_rows']??0));
    }

    private function event_source_forensic_snapshot() {
        global $wpdb;
        $events=$this->table('events');$sources=$this->table('event_sources');
        $now=current_time('mysql');$night=get_option('rg_events_nightly_state',array());if(!is_array($night))$night=array();
        $token=sanitize_key((string)($night['run_token']??''));$started=(string)($night['started_at']??'');
        $out=array('token'=>$token,'same_object'=>0,'outside_own_object'=>0,'without_external_id'=>0,'first_seen_since_master'=>0,'first_seen_before_master'=>0,'domains'=>array(),'samples'=>array(),'domspringen'=>array());
        if($token==='')return $out;
        $active="o.status='active' AND (o.end_at IS NULL OR o.end_at >= %s) AND (o.last_master_run<>%s OR o.last_master_run='')";
        $out['same_object']=(int)$wpdb->get_var($wpdb->prepare("SELECT COUNT(*) FROM $events o WHERE $active AND o.external_id<>'' AND EXISTS (SELECT 1 FROM $events m WHERE m.last_master_run=%s AND m.source=o.source AND m.external_id=o.external_id)",$now,$token,$token));
        $out['without_external_id']=(int)$wpdb->get_var($wpdb->prepare("SELECT COUNT(*) FROM $events o WHERE $active AND o.external_id=''",$now,$token));
        $out['outside_own_object']=(int)$wpdb->get_var($wpdb->prepare("SELECT COUNT(*) FROM $events o WHERE $active AND (o.external_id='' OR NOT EXISTS (SELECT 1 FROM $events m WHERE m.last_master_run=%s AND m.source=o.source AND m.external_id=o.external_id))",$now,$token,$token));
        if($started!==''){
            $out['first_seen_since_master']=(int)$wpdb->get_var($wpdb->prepare("SELECT COUNT(*) FROM $events o WHERE $active AND o.first_seen_at >= %s",$now,$token,$started));
            $out['first_seen_before_master']=(int)$wpdb->get_var($wpdb->prepare("SELECT COUNT(*) FROM $events o WHERE $active AND o.first_seen_at < %s",$now,$token,$started));
        }
        $urlRows=(array)$wpdb->get_results($wpdb->prepare("SELECT o.id,o.source_url,(SELECT es.source_url FROM $sources es WHERE es.event_id=o.id AND es.source_url<>'' ORDER BY es.id DESC LIMIT 1) AS feed_url FROM $events o WHERE $active AND (o.external_id='' OR NOT EXISTS (SELECT 1 FROM $events m WHERE m.last_master_run=%s AND m.source=o.source AND m.external_id=o.external_id))",$now,$token,$token),ARRAY_A);
        $domains=array();foreach($urlRows as $ur){$u=trim((string)($ur['source_url']?:$ur['feed_url']));if($u==='')continue;$h=strtolower((string)wp_parse_url($u,PHP_URL_HOST));$h=preg_replace('/^www\./','',$h);if($h==='')continue;$domains[$h]=($domains[$h]??0)+1;}arsort($domains);$out['domains']=array_slice($domains,0,15,true);
        $out['samples']=(array)$wpdb->get_results($wpdb->prepare("SELECT o.id,o.title,o.start_at,o.city,o.external_id,o.source_url,o.first_seen_at,(SELECT es.source_url FROM $sources es WHERE es.event_id=o.id AND es.source_url<>'' ORDER BY es.id DESC LIMIT 1) AS feed_url FROM $events o WHERE $active AND (o.external_id='' OR NOT EXISTS (SELECT 1 FROM $events m WHERE m.last_master_run=%s AND m.source=o.source AND m.external_id=o.external_id)) ORDER BY o.start_at ASC,o.id ASC LIMIT 30",$now,$token,$token),ARRAY_A);
        $out['domspringen']=(array)$wpdb->get_results($wpdb->prepare("SELECT o.id,o.title,o.start_at,o.city,o.external_id,o.source_url,o.first_seen_at,o.last_master_run FROM $events o WHERE o.status='active' AND (o.end_at IS NULL OR o.end_at >= %s) AND LOWER(o.title) LIKE %s ORDER BY o.start_at ASC LIMIT 20",$now,'%domspringen%'),ARRAY_A);
        return $out;
    }

    private function event_region_city_key($city) {
        $city=trim((string)$city);
        if($city==='')return '';
        $key=sanitize_title(remove_accents($city));
        $aliases=array(
            'mulheim'=>'mulheim-an-der-ruhr','muelheim'=>'mulheim-an-der-ruhr',
            'voerde'=>'voerde-niederrhein',
            'wetter'=>'wetter-ruhr',
            'frondenberg'=>'frondenberg-ruhr','froendenberg'=>'frondenberg-ruhr',
            'haltern'=>'haltern-am-see'
        );
        return $aliases[$key]??$key;
    }

    private function event_metropole_ruhr_city_keys() {
        $keys=array();
        foreach($this->municipalities_seed() as $entry){
            $name=(string)($entry[0]??'');$key=$this->event_region_city_key($name);if($key!=='')$keys[$key]=$name;
        }
        return $keys;
    }

    private function event_city_is_metropole_ruhr($city) {
        $key=$this->event_region_city_key($city);if($key==='')return false;$allowed=$this->event_metropole_ruhr_city_keys();
        // Provider aliases used in real feeds.
        $aliases=array('voerde'=>$this->event_region_city_key('Voerde (Niederrhein)'),'mulheim'=>$this->event_region_city_key('Mülheim an der Ruhr'),'mulheim-an-der-ruhr'=>$this->event_region_city_key('Mülheim an der Ruhr'),'frondenberg'=>$this->event_region_city_key('Fröndenberg/Ruhr'),'wetter'=>$this->event_region_city_key('Wetter (Ruhr)'));
        if(isset($aliases[$key]))$key=$aliases[$key];return isset($allowed[$key]);
    }

    // RPG IGA 2027 1.10.81: public read-only bridge so the modular classifier
    // reuses the existing 53-municipality truth instead of duplicating it.
    public function intelligence_is_metropole_ruhr_city($city) {
        return $this->event_city_is_metropole_ruhr($city);
    }

    private function event_latest_master_token() {
        $night=get_option('rg_events_nightly_state',array());if(!is_array($night))return '';
        return sanitize_key((string)($night['run_token']??''));
    }

    private function event_delete_ids($ids) {
        global $wpdb;$ids=array_values(array_unique(array_filter(array_map('intval',(array)$ids))));if(!$ids)return 0;
        $events=$this->table('events');$sources=$this->table('event_sources');$media=$this->table('event_media');$enr=$this->table('event_enrichment');$deleted=0;
        foreach(array_chunk($ids,400) as $chunk){$in=implode(',',array_map('intval',$chunk));$wpdb->query("DELETE FROM $sources WHERE event_id IN ($in)");$wpdb->query("DELETE FROM $media WHERE event_id IN ($in)");$wpdb->query("DELETE FROM $enr WHERE event_id IN ($in)");$deleted+=(int)$wpdb->query("DELETE FROM $events WHERE id IN ($in)");}
        return $deleted;
    }

    private function event_clean_supplemental_state() {
        $supp=get_option('rg_events_supplemental_state',array());if(!is_array($supp))$supp=array();
        $master=$this->event_latest_master_token();
        $suppToken=sanitize_key((string)($supp['supplemental_run_token']??''));
        $suppMaster=sanitize_key((string)($supp['master_run_token']??''));
        $citiesTotal=max(53,(int)($supp['cities_total']??53));
        $failed=array_values(array_filter((array)($supp['failed_cities']??array())));
        $ok=(($supp['status']??'')==='finished' && (int)($supp['cities_done']??0)>=$citiesTotal && (int)($supp['errors']??0)===0 && !$failed && $master!=='' && $suppToken!=='' && $suppMaster===$master);
        return array('ok'=>$ok,'master_token'=>$master,'supplemental_token'=>$suppToken,'state'=>$supp,'reason'=>$ok?'':($master===''?'Kein gültiger Master-Run-Token vorhanden.':($suppToken===''?'Kein sauberer Supplemental-Run-Token vorhanden.':'Der letzte 53-Städte-Zusatzlauf ist nicht fehlerfrei abgeschlossen oder gehört nicht zum aktuellen Master.')));
    }

    private function event_merge_related_rows($from_id,$to_id) {
        global $wpdb;$from_id=(int)$from_id;$to_id=(int)$to_id;if(!$from_id||!$to_id||$from_id===$to_id)return;
        $events=$this->table('events');$sources=$this->table('event_sources');$media=$this->table('event_media');$enr=$this->table('event_enrichment');
        $fromSrc=(string)$wpdb->get_var($wpdb->prepare("SELECT source FROM $events WHERE id=%d",$from_id));
        $toSrc=(string)$wpdb->get_var($wpdb->prepare("SELECT source FROM $events WHERE id=%d",$to_id));
        $sameOwner=($fromSrc!==''&&$fromSrc===$toSrc);

        // Provenance rows may be kept internally on the surviving DB record.
        $sourceRows=(array)$wpdb->get_results($wpdb->prepare("SELECT id,source_type,source_uid FROM $sources WHERE event_id=%d",$from_id),ARRAY_A);
        foreach($sourceRows as $r){
            $sid=(int)($r['id']??0);if(!$sid)continue;$type=(string)($r['source_type']??'');$uid=(string)($r['source_uid']??'');
            $exists=(int)$wpdb->get_var($wpdb->prepare("SELECT id FROM $sources WHERE event_id=%d AND source_type=%s AND source_uid=%s LIMIT 1",$to_id,$type,$uid));
            if($exists)$wpdb->delete($sources,array('id'=>$sid));else$wpdb->update($sources,array('event_id'=>$to_id),array('id'=>$sid));
        }

        // V1.10.29: media/enrichment are source-owned. A legacy row may donate
        // them only when both DB rows have the same owner source. Cross-source
        // cleanup therefore cannot silently put an EMG/destination image on ET4.
        if($sameOwner){
            $mediaRows=(array)$wpdb->get_results($wpdb->prepare("SELECT id,url,is_primary FROM $media WHERE event_id=%d",$from_id),ARRAY_A);
            $targetHasPrimary=(int)$wpdb->get_var($wpdb->prepare("SELECT COUNT(*) FROM $media WHERE event_id=%d AND is_primary=1",$to_id));
            foreach($mediaRows as $r){
                $mid=(int)($r['id']??0);if(!$mid)continue;$url=(string)($r['url']??'');
                $exists=$url!==''?(int)$wpdb->get_var($wpdb->prepare("SELECT id FROM $media WHERE event_id=%d AND url=%s LIMIT 1",$to_id,$url)):0;
                if($exists){$wpdb->delete($media,array('id'=>$mid));continue;}
                $data=array('event_id'=>$to_id);if($targetHasPrimary && !empty($r['is_primary']))$data['is_primary']=0;
                $wpdb->update($media,$data,array('id'=>$mid));
                if(!$targetHasPrimary && !empty($r['is_primary']))$targetHasPrimary=1;
            }
            $fromEnr=$wpdb->get_row($wpdb->prepare("SELECT * FROM $enr WHERE event_id=%d",$from_id),ARRAY_A);
            if($fromEnr){
                $targetEnr=(int)$wpdb->get_var($wpdb->prepare("SELECT COUNT(*) FROM $enr WHERE event_id=%d",$to_id));
                if(!$targetEnr)$wpdb->update($enr,array('event_id'=>$to_id),array('event_id'=>$from_id));else$wpdb->delete($enr,array('event_id'=>$from_id));
            }
        }
    }

    private function event_reconcile_legacy_open_data() {
        global $wpdb;$events=$this->table('events');$now=current_time('mysql');$safe=$this->event_clean_supplemental_state();
        if(empty($safe['ok']))return array('error'=>(string)($safe['reason']??'Sicherheitsprüfung fehlgeschlagen.'));
        $master=(string)$safe['master_token'];$suppToken=(string)$safe['supplemental_token'];
        $candidates=(array)$wpdb->get_results($wpdb->prepare(
            "SELECT id,external_id,start_at,title,city FROM $events WHERE status='active' AND (end_at IS NULL OR end_at >= %s) AND source='open_data_finder' AND (last_master_run<>%s OR last_master_run='') ORDER BY id ASC",
            $now,$master
        ),ARRAY_A);
        $report=array('candidates'=>count($candidates),'merged_master'=>0,'merged_supplemental'=>0,'removed_stale_master'=>0,'removed_stale_supplemental'=>0,'removed_unconfirmed'=>0,'deleted_total'=>0,'remaining_legacy'=>0,'master_token'=>$master,'supplemental_token'=>$suppToken,'at'=>$now,'error'=>'');
        if(!$candidates){update_option('rg_events_legacy_reconcile_v188',$report,false);return $report;}

        $masterRows=(array)$wpdb->get_results($wpdb->prepare("SELECT id,external_id,start_at FROM $events WHERE last_master_run=%s AND external_id<>''",$master),ARRAY_A);
        $suppRows=(array)$wpdb->get_results($wpdb->prepare("SELECT id,external_id,start_at FROM $events WHERE source='destination_one_open_data' AND last_supplemental_run=%s AND external_id<>''",$suppToken),ARRAY_A);
        $masterObjects=array();$masterExact=array();$suppObjects=array();$suppExact=array();
        foreach($masterRows as $r){$ext=(string)($r['external_id']??'');if($ext==='')continue;$masterObjects[$ext]=1;$masterExact[$ext.'|'.(string)$r['start_at']]=(int)$r['id'];}
        foreach($suppRows as $r){$ext=(string)($r['external_id']??'');if($ext==='')continue;$suppObjects[$ext]=1;$suppExact[$ext.'|'.(string)$r['start_at']]=(int)$r['id'];}

        $stale=array();$unconfirmed=array();
        foreach($candidates as $r){
            $id=(int)($r['id']??0);$ext=(string)($r['external_id']??'');$start=(string)($r['start_at']??'');if(!$id)continue;$key=$ext.'|'.$start;
            if($ext!=='' && !empty($masterExact[$key]) && (int)$masterExact[$key]!==$id){
                $this->event_merge_related_rows($id,(int)$masterExact[$key]);$report['merged_master']++;$report['deleted_total']+=$this->event_delete_ids(array($id));continue;
            }
            if($ext!=='' && !empty($suppExact[$key]) && (int)$suppExact[$key]!==$id){
                $this->event_merge_related_rows($id,(int)$suppExact[$key]);$report['merged_supplemental']++;$report['deleted_total']+=$this->event_delete_ids(array($id));continue;
            }
            if($ext!=='' && isset($masterObjects[$ext])){$report['removed_stale_master']++;$stale[]=$id;continue;}
            if($ext!=='' && isset($suppObjects[$ext])){$report['removed_stale_supplemental']++;$stale[]=$id;continue;}
            $report['removed_unconfirmed']++;$unconfirmed[]=$id;
        }
        $report['deleted_total']+=$this->event_delete_ids(array_merge($stale,$unconfirmed));
        $report['remaining_legacy']=(int)$wpdb->get_var($wpdb->prepare("SELECT COUNT(*) FROM $events WHERE status='active' AND (end_at IS NULL OR end_at >= %s) AND source='open_data_finder' AND (last_master_run<>%s OR last_master_run='')",$now,$master));
        $report['finished_at']=current_time('mysql');
        update_option('rg_events_legacy_reconcile_v188',$report,false);
        return $report;
    }

    private function event_region_cleanup_outside_master() {
        global $wpdb;$events=$this->table('events');$token=$this->event_latest_master_token();$now=current_time('mysql');
        if($token==='')return array('deleted'=>0,'inside_kept'=>0,'outside_found'=>0,'unknown'=>0,'error'=>'Kein letzter Master-Run-Token vorhanden');
        $sql=$wpdb->prepare("SELECT o.id,o.city FROM $events o WHERE o.status='active' AND (o.end_at IS NULL OR o.end_at >= %s) AND (o.last_master_run<>%s OR o.last_master_run='') AND (o.external_id='' OR NOT EXISTS (SELECT 1 FROM $events m WHERE m.last_master_run=%s AND m.source=o.source AND m.external_id=o.external_id))",$now,$token,$token);
        $rows=(array)$wpdb->get_results($sql,ARRAY_A);$outside=array();$inside=0;$unknown=0;
        foreach($rows as $r){$city=trim((string)($r['city']??''));if($city===''){$unknown++;continue;}if($this->event_city_is_metropole_ruhr($city))$inside++;else $outside[]=(int)$r['id'];}
        $deleted=$this->event_delete_ids($outside);$report=array('deleted'=>$deleted,'inside_kept'=>$inside,'outside_found'=>count($outside),'unknown'=>$unknown,'at'=>$now,'master_token'=>$token);update_option('rg_events_region_cleanup_v178',$report,false);return $report;
    }

    private function event_supplemental_master_external_set($token) {
        global $wpdb;$events=$this->table('events');$out=array();if($token==='')return $out;
        $ids=(array)$wpdb->get_col($wpdb->prepare("SELECT DISTINCT external_id FROM $events WHERE last_master_run=%s AND external_id<>''",$token));foreach($ids as $id)$out[(string)$id]=1;return $out;
    }

    private function event_supplemental_unique_source_items($items,$master_external=array()) {
        $seen=array();$out=array();$repeat=0;$masterSkipped=0;
        foreach((array)$items as $item){if(!is_array($item))continue;$external=$this->event_external_id_from_item($item);if($external!==''&&isset($master_external[$external])){$masterSkipped++;continue;}$source=$this->event_source_name_from_item($item);$key=$external!==''?sha1($source.'|'.$external):sha1(wp_json_encode(array($item['title']??($item['name']??''),$item['timeIntervals']??($item['occurrences']??($item['subitems']??array()))),JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES));if(isset($seen[$key])){$repeat++;continue;}$seen[$key]=1;$out[]=$item;}
        return array('items'=>$out,'unique'=>count($out),'repeat_rows'=>$repeat,'master_overlap_skipped'=>$masterSkipped);
    }

    private function event_fetch_supplemental_city($city,$query_start,$query_end,$master_token,$supplemental_run_token='') {
        if(!function_exists('ruhrpott_guru_et4_fetch_pages'))return array('error'=>'Theme-ET4-Transport nicht verfügbar','raw'=>0,'source_objects'=>0,'generated'=>0,'ingested'=>0,'master_overlap'=>0);
        $q=function_exists('ruhrpott_guru_event_city_query')?ruhrpott_guru_event_city_query($city):('city:"'.str_replace('"','',(string)$city).'"');
        // V1.10.27: supplemental must use the same rich-source architecture as the
        // licensed master. unique=false + unrollIntervals returned sparse occurrence
        // renderings that can omit event-owned media/subitems. Fetch one canonical rich
        // source object and expand its intervals locally; the copied occurrence payload
        // therefore retains media_objects for card/detail rendering and persistence.
        $args=array('unique'=>'true','q'=>$q,'startdate'=>$query_start,'enddate'=>$query_end,'sort'=>'title asc');
