    private function event_prune_stale_destination_one_after_supplemental($master_token,$supplemental_run_token,$query_start='',$query_end='') {
        $master_token=sanitize_key((string)$master_token);$supplemental_run_token=sanitize_key((string)$supplemental_run_token);
        if($supplemental_run_token==='')return array('missing'=>0,'inactivated'=>0,'seen'=>0,'error'=>'missing-run-token');
