    public function cron_events_supplemental_refresh_batch() {
        $state=get_option('rg_events_supplemental_state',array());
        if(!is_array($state)||($state['status']??'')!=='running'){return;}
        // 1.10.160: a newly requested/resuming WeselMarketing run gets the next
        // serial event-import slot. The 53-city supplemental wave is resumable by
        // city_index, so yielding here loses no data and prevents lock ping-pong.
        $coverage=$this->event_coverage_wesel_state_v101159();$coverageStatus=(string)($coverage['status']??'');$coveragePriority=in_array($coverageStatus,array('starting','running','retry'),true);
        if(!$coveragePriority&&$coverageStatus==='waiting_lock'&&strpos((string)($coverage['wait_reason']??''),'53-Städte-Zusatzfeed')!==false){$last=!empty($coverage['last_progress_at'])?strtotime((string)$coverage['last_progress_at']):0;$coveragePriority=(!$last||$last>=time()-30*MINUTE_IN_SECONDS);}
        if($coveragePriority){$lock=$this->event_import_lock_v101101();if((string)($lock['owner']??'')==='supplemental')$this->event_import_lock_release_v101101('supplemental');$state['wait_reason']='WeselMarketing-Sync hat Vorrang';$state['last_wait_at']=current_time('mysql');update_option('rg_events_supplemental_state',$state,false);wp_clear_scheduled_hook(self::EVENT_SUPPLEMENTAL_BATCH_HOOK);wp_schedule_single_event(time()+300,self::EVENT_SUPPLEMENTAL_BATCH_HOOK);wp_clear_scheduled_hook(self::EVENT_COVERAGE_HOOK);wp_schedule_single_event(time()+3,self::EVENT_COVERAGE_HOOK);if(function_exists('spawn_cron'))spawn_cron();return;}
        if(!$this->event_import_lock_acquire_v101101('supplemental')){
            wp_clear_scheduled_hook(self::EVENT_SUPPLEMENTAL_BATCH_HOOK);wp_schedule_single_event(time()+300,self::EVENT_SUPPLEMENTAL_BATCH_HOOK);return;
        }
        $this->event_import_lock_touch_v101101('supplemental');
        $this->pause_event_enrichment_for_supplemental();

        if($this->places_import_actively_running()){
            $state['wait_reason']='Places-Import aktiv';
            $state['last_wait_at']=current_time('mysql');
            update_option('rg_events_supplemental_state',$state,false);
            wp_clear_scheduled_hook(self::EVENT_SUPPLEMENTAL_BATCH_HOOK);
            wp_schedule_single_event(time()+120,self::EVENT_SUPPLEMENTAL_BATCH_HOOK);
            // Waiting on Places is passive: do not monopolize the global event lock.
            $this->event_import_lock_release_v101101('supplemental');
            return;
        }

        $state['wait_reason']='';
        $cities=array_map(function($x){return (string)($x[0]??'');},$this->municipalities_seed());
        $cities=array_values(array_filter($cities));
        $idx=max(0,(int)($state['city_index']??0));

        if($idx>=count($cities)){
            $failed=array_values(array_unique(array_filter((array)($state['failed_cities']??array()))));
            if(!$failed){
                $life=$this->event_prune_stale_destination_one_after_supplemental(
                    (string)($state['master_run_token']??''),
                    (string)($state['supplemental_run_token']??''),
                    (string)($state['query_start']??''),(string)($state['query_end']??'')
                );
                $state['pruned_stale']=0;$state['lifecycle_missing']=(int)($life['missing']??0);$state['lifecycle_inactivated']=(int)($life['inactivated']??0);$state['lifecycle_seen']=(int)($life['seen']??0);
                $state['status']='finished';
            }else{
                $state['status']='finished_with_errors';
                $state['pruned_stale']=0;
            }
            $state['finished_at']=current_time('mysql');
            $state['wait_reason']='';
            $state['attempt_city']='';$state['city_attempt_count']=0;$state['inflight_city']='';$state['inflight_started_at']='';
            update_option('rg_events_supplemental_state',$state,false);
            wp_clear_scheduled_hook(self::EVENT_SUPPLEMENTAL_BATCH_HOOK);
            $this->event_import_lock_release_v101101('supplemental');
            $this->start_event_enrichment_wave();
            $this->start_event_fallback_media_wave_v1044('nightly');
            $this->event_sync_schedule_dispatch_v101101(30);
            return;
        }

        $city=$cities[$idx];
        // V1.10.55 hard-timeout protection: count/persist the city attempt and
        // schedule a safety retry BEFORE the external provider call. If PHP dies
        // inside the request, the next cron can continue instead of leaving this
        // city in "running" forever.
        $attemptCity=(string)($state['attempt_city']??'');
        $attemptCount=$attemptCity===$city?((int)($state['city_attempt_count']??0)+1):1;
        if($attemptCount>3){
            $failed=(array)($state['failed_cities']??array());$failed[]=$city;$state['failed_cities']=array_values(array_unique($failed));
            $state['errors']=(int)($state['errors']??0)+1;$state['last_error']='Stadt nach 3 Provider-Versuchen übersprungen: '.$city;
            $state['last_city']=$city;$state['last_progress_at']=current_time('mysql');$state['city_index']=$idx+1;$state['cities_done']=$idx+1;
            $state['attempt_city']='';$state['city_attempt_count']=0;$state['inflight_city']='';$state['inflight_started_at']='';$state['city_retry_count']=0;$state['wait_reason']='';
            update_option('rg_events_supplemental_state',$state,false);wp_clear_scheduled_hook(self::EVENT_SUPPLEMENTAL_BATCH_HOOK);wp_schedule_single_event(time()+15,self::EVENT_SUPPLEMENTAL_BATCH_HOOK);return;
        }
        $state['attempt_city']=$city;$state['city_attempt_count']=$attemptCount;$state['inflight_city']=$city;$state['inflight_started_at']=current_time('mysql');$state['last_attempt_at']=current_time('mysql');
        update_option('rg_events_supplemental_state',$state,false);
        wp_clear_scheduled_hook(self::EVENT_SUPPLEMENTAL_BATCH_HOOK);wp_schedule_single_event(time()+240,self::EVENT_SUPPLEMENTAL_BATCH_HOOK);

        $r=$this->event_fetch_supplemental_city(
            $city,
            (string)($state['query_start']??''),
            (string)($state['query_end']??''),
            (string)($state['master_run_token']??''),
            (string)($state['supplemental_run_token']??'')
        );
        $state=get_option('rg_events_supplemental_state',array());if(!is_array($state))$state=array();
        $state['last_city']=$city;
        $state['last_progress_at']=current_time('mysql');
        $state['inflight_city']='';$state['inflight_started_at']='';

        if(!empty($r['error'])){
            $state['errors']=(int)($state['errors']??0)+1;
            $state['last_error']=(string)$r['error'];
            $retry=max($attemptCount,(int)($state['city_retry_count']??0)+1);
            $state['city_retry_count']=$retry;
            $state['wait_reason']='Retry '.$retry.'/3 für '.$city;
            if($retry<3){
                update_option('rg_events_supplemental_state',$state,false);
                wp_clear_scheduled_hook(self::EVENT_SUPPLEMENTAL_BATCH_HOOK);
                wp_schedule_single_event(time()+90,self::EVENT_SUPPLEMENTAL_BATCH_HOOK);
                return;
            }
            $failed=(array)($state['failed_cities']??array());
            $failed[]=$city;
            $state['failed_cities']=array_values(array_unique($failed));
            $state['city_retry_count']=0;$state['attempt_city']='';$state['city_attempt_count']=0;
            $state['city_index']=$idx+1;
            $state['cities_done']=$idx+1;
            $state['wait_reason']='';
        }else{
            $state['last_error']='';
            $state['city_retry_count']=0;$state['attempt_city']='';$state['city_attempt_count']=0;
            foreach(array(
                'provider_raw_seen'=>'provider_raw',
                'raw_seen'=>'raw',
                'wrong_city_rejected'=>'wrong_city_rejected',
                'outside_region_rejected'=>'outside_region_rejected',
                'source_objects'=>'source_objects',
                'occurrences_generated'=>'generated',
                'ingested'=>'ingested',
                'inserted'=>'inserted',
                'updated'=>'updated',
                'invalid'=>'invalid',
                'master_overlap_skipped'=>'master_overlap',
                'repeat_rows'=>'repeat_rows',
                'cancelled'=>'cancelled_total'
            ) as $sk=>$rk){
                $state[$sk]=(int)($state[$sk]??0)+(int)($r[$rk]??0);
            }
            $state['last_provider_raw']=(int)($r['provider_raw']??0);
            $state['last_exact_city_raw']=(int)($r['raw']??0);
            $state['last_wrong_city_rejected']=(int)($r['wrong_city_rejected']??0);
            $state['city_index']=$idx+1;
            $state['cities_done']=$idx+1;
        }

        update_option('rg_events_supplemental_state',$state,false);
        wp_clear_scheduled_hook(self::EVENT_SUPPLEMENTAL_BATCH_HOOK);
        wp_schedule_single_event(time()+20,self::EVENT_SUPPLEMENTAL_BATCH_HOOK);
        if(function_exists('spawn_cron'))spawn_cron();
    }

    public function ensure_event_supplemental_worker() {
        $night=get_option('rg_events_nightly_state',array());if(!is_array($night)||($night['status']??'')!=='finished')return;$token=sanitize_key((string)($night['run_token']??''));if($token==='')return;$state=get_option('rg_events_supplemental_state',array());if(!is_array($state))$state=array();
        if(($state['status']??'')==='waiting_events_sync'){$this->start_event_supplemental_wave($token);return;}
        if((string)($state['master_run_token']??'')!==$token && ($state['status']??'')!=='running'){$this->start_event_supplemental_wave($token);return;}
        if(($state['status']??'')!=='running')return;
        // A supplemental run has priority over enrichment. Repair missing/overdue
        // cron hooks and stale heartbeats instead of leaving the 53-city wave
        // permanently in running state after a provider/PHP abort.
        $this->pause_event_enrichment_for_supplemental();
        $next=wp_next_scheduled(self::EVENT_SUPPLEMENTAL_BATCH_HOOK);$overdue=$next && $next < time()-30;
        $last=0;foreach(array('last_progress_at','last_attempt_at','last_wait_at','started_at') as $tf){if(!empty($state[$tf])){$tt=strtotime((string)$state[$tf]);if($tt)$last=max($last,$tt);}}$stale=$last>0&&$last<time()-15*MINUTE_IN_SECONDS;
        if(!$next || $overdue || $stale){
            if($stale){$state['watchdog_recovered_at']=current_time('mysql');$state['watchdog_reason']='Supplemental-Heartbeat älter als 15 Minuten';update_option('rg_events_supplemental_state',$state,false);}
            wp_clear_scheduled_hook(self::EVENT_SUPPLEMENTAL_BATCH_HOOK);wp_schedule_single_event(time()+3,self::EVENT_SUPPLEMENTAL_BATCH_HOOK);if(function_exists('spawn_cron'))spawn_cron();
        }
    }

    private function event_region_forensic_snapshot() {
        global $wpdb;
        $events=$this->table('events');$now=current_time('mysql');$night=get_option('rg_events_nightly_state',array());if(!is_array($night))$night=array();
        $token=sanitize_key((string)($night['run_token']??''));
        $out=array('token'=>$token,'inside'=>0,'outside'=>0,'unknown'=>0,'inside_cities'=>array(),'outside_cities'=>array(),'unknown_cities'=>array(),'inside_samples'=>array(),'outside_samples'=>array(),'unknown_samples'=>array(),'rows'=>0);
        if($token==='')return $out;
        $sql=$wpdb->prepare("SELECT o.id,o.title,o.start_at,o.city,o.postcode,o.lat,o.lng,o.external_id,o.source_url,o.first_seen_at FROM $events o WHERE o.status='active' AND (o.end_at IS NULL OR o.end_at >= %s) AND (o.last_master_run<>%s OR o.last_master_run='') AND (o.external_id='' OR NOT EXISTS (SELECT 1 FROM $events m WHERE m.last_master_run=%s AND m.source=o.source AND m.external_id=o.external_id)) ORDER BY o.start_at ASC,o.id ASC",$now,$token,$token);
        $rows=(array)$wpdb->get_results($sql,ARRAY_A);$out['rows']=count($rows);$allowed=$this->event_metropole_ruhr_city_keys();
        $generic=array('ruhrgebiet'=>1,'metropole-ruhr'=>1,'metropole-ruhrgebiet'=>1,'nrw'=>1,'nordrhein-westfalen'=>1,'deutschland'=>1);
        foreach($rows as $r){
            $city=trim((string)($r['city']??''));$key=$this->event_region_city_key($city);
            if($key!==''&&isset($allowed[$key])){$bucket='inside';$label=$allowed[$key];}
            elseif($key===''||isset($generic[$key])){$bucket='unknown';$label=$city!==''?$city:'ohne Stadt';}
            else{$bucket='outside';$label=$city;}
            $out[$bucket]++;
            $mapKey=$label!==''?$label:'ohne Stadt';$out[$bucket.'_cities'][$mapKey]=($out[$bucket.'_cities'][$mapKey]??0)+1;
            if(count($out[$bucket.'_samples'])<25)$out[$bucket.'_samples'][]=$r;
        }
        foreach(array('inside_cities','outside_cities','unknown_cities') as $k){arsort($out[$k]);$out[$k]=array_slice($out[$k],0,25,true);}
        return $out;
    }


