    /** 1.10.99: frozen editorial research snapshot from the 53-municipality sweep on 2026-09-22. */
    private function halloween_2026_research_snapshot_v101099() {
        $with=array();
        foreach($this->halloween_2026_editorial_anchors_v101097() as $a){
            $m=trim((string)($a['research_municipality']??($a['address']['city']??'')));
            if($m!=='')$with[$this->event_region_city_key($m)]=$m;
        }
        $all=array();foreach($this->municipalities_seed() as $entry){$n=trim((string)($entry[0]??''));if($n!=='')$all[$this->event_region_city_key($n)]=$n;}
        $without=array();foreach($all as $k=>$n)if(!isset($with[$k]))$without[]=$n;
        natcasesort($without);$without=array_values($without);
        return array('researched_at'=>'2026-09-22','municipalities_total'=>count($all),'municipalities_with_anchor'=>count($with),'municipalities_without_anchor'=>count($without),'without'=>$without);
    }

    private function halloween_2026_anchor_geo_valid_v101099($anchor) {
        $lat=(float)($anchor['geo']['lat']??($anchor['geo']['latitude']??0));$lng=(float)($anchor['geo']['lng']??($anchor['geo']['longitude']??0));
        return abs($lat)>0.000001&&abs($lng)>0.000001;
    }

    private function halloween_2026_city_variants_v101099($city) {
        $city=trim((string)$city);$vals=array($city);$key=$this->event_region_city_key($city);
        $map=array('voerde-niederrhein'=>array('Voerde','Voerde (Niederrhein)'),'mulheim-an-der-ruhr'=>array('Mülheim an der Ruhr','Muelheim an der Ruhr','Mülheim'),'frondenberg-ruhr'=>array('Fröndenberg/Ruhr','Fröndenberg','Froendenberg'),'wetter-ruhr'=>array('Wetter (Ruhr)','Wetter'),'haltern-am-see'=>array('Haltern am See','Haltern'));
