    private function halloween_2026_local_venue_enrich_v101099($anchor) {
        if(!is_array($anchor))return $anchor;
        if($this->halloween_2026_anchor_geo_valid_v101099($anchor))return $anchor;
        global $wpdb;$events=$this->table('events');$places=$this->table('places');
        $venue=trim((string)($anchor['venueName']??''));$city=trim((string)($anchor['address']['city']??''));if($venue===''||$city==='')return $anchor;
        $want=$this->event_listing_norm($venue);if($want==='')return $anchor;
        $best=null;$bestScore=-1;
        foreach($this->halloween_2026_city_variants_v101099($city) as $cv){
            $rows=(array)$wpdb->get_results($wpdb->prepare("SELECT venue_name,street,house_number,postcode,city,lat,lng FROM $events WHERE city=%s AND venue_name<>'' AND lat IS NOT NULL AND lng IS NOT NULL ORDER BY updated_at DESC LIMIT 250",$cv),ARRAY_A);
            foreach($rows as $r){$got=$this->event_listing_norm((string)($r['venue_name']??''));if($got==='')continue;$score=($got===$want)?100:((strlen($want)>=7&&(strpos($got,$want)!==false||strpos($want,$got)!==false))?70:0);if($score>$bestScore){$bestScore=$score;$best=$r;}}
        }
        if($bestScore<70){
            $best=null;$bestScore=-1;
            foreach($this->halloween_2026_city_variants_v101099($city) as $cv){
                $rows=(array)$wpdb->get_results($wpdb->prepare("SELECT name,street,house_number,postcode,city,lat,lng FROM $places WHERE city=%s AND active=1 AND lifecycle_status='active' ORDER BY updated_at DESC LIMIT 600",$cv),ARRAY_A);
                foreach($rows as $r){$got=$this->event_listing_norm((string)($r['name']??''));if($got==='')continue;$score=($got===$want)?100:((strlen($want)>=7&&(strpos($got,$want)!==false||strpos($want,$got)!==false))?70:0);if($score>$bestScore){$bestScore=$score;$best=$r;}}
            }
        }
        if(!$best||$bestScore<70){
            // Exact local address is a second identity-safe resolver when the venue spelling differs.
            $street=trim((string)($anchor['address']['street']??''));$house=trim((string)($anchor['address']['houseNumber']??''));
            if($street!==''){
                foreach($this->halloween_2026_city_variants_v101099($city) as $cv){
                    if($house!=='')$r=$wpdb->get_row($wpdb->prepare("SELECT venue_name,street,house_number,postcode,city,lat,lng FROM $events WHERE city=%s AND street=%s AND house_number=%s AND lat IS NOT NULL AND lng IS NOT NULL ORDER BY updated_at DESC LIMIT 1",$cv,$street,$house),ARRAY_A);
                    else $r=$wpdb->get_row($wpdb->prepare("SELECT venue_name,street,house_number,postcode,city,lat,lng FROM $events WHERE city=%s AND street=%s AND lat IS NOT NULL AND lng IS NOT NULL ORDER BY updated_at DESC LIMIT 1",$cv,$street),ARRAY_A);
                    if($r){$best=$r;$bestScore=80;break;}
                    if($house!=='')$r=$wpdb->get_row($wpdb->prepare("SELECT name,street,house_number,postcode,city,lat,lng FROM $places WHERE city=%s AND street=%s AND house_number=%s AND active=1 AND lifecycle_status='active' ORDER BY updated_at DESC LIMIT 1",$cv,$street,$house),ARRAY_A);
                    else $r=$wpdb->get_row($wpdb->prepare("SELECT name,street,house_number,postcode,city,lat,lng FROM $places WHERE city=%s AND street=%s AND active=1 AND lifecycle_status='active' ORDER BY updated_at DESC LIMIT 1",$cv,$street),ARRAY_A);
                    if($r){$best=$r;$bestScore=80;break;}
                }
            }
        }
        if(!$best||$bestScore<70)return $anchor;
        $lat=(float)($best['lat']??0);$lng=(float)($best['lng']??0);if(abs($lat)<0.000001||abs($lng)<0.000001)return $anchor;
        $anchor['geo']=array('lat'=>$lat,'lng'=>$lng);
        if(empty($anchor['address'])||!is_array($anchor['address']))$anchor['address']=array();
        foreach(array('street'=>'street','houseNumber'=>'house_number','zip'=>'postcode') as $to=>$from)if(empty($anchor['address'][$to])&&!empty($best[$from]))$anchor['address'][$to]=(string)$best[$from];
        if(empty($anchor['address']['city'])&&!empty($best['city']))$anchor['address']['city']=(string)$best['city'];
        return $anchor;
    }

    private function halloween_2026_existing_match_v101097($anchor) {
        global $wpdb;
        $events=$this->table('events');
        $city=$this->event_text($anchor['address']['city']??'',120);
        $start=$this->event_datetime_mysql($anchor['start']??null);
        if($city===''||!$start)return null;
        $ts=strtotime($start);$from=wp_date('Y-m-d H:i:s',$ts-3*HOUR_IN_SECONDS,wp_timezone());$to=wp_date('Y-m-d H:i:s',$ts+3*HOUR_IN_SECONDS,wp_timezone());
        // Date/time narrows the set first; city aliases are compared with the canonical 53-city normalizer.
        $rows=(array)$wpdb->get_results($wpdb->prepare("SELECT id,title,venue_name,start_at,source,external_id,status,city FROM $events WHERE start_at BETWEEN %s AND %s AND status='active' ORDER BY start_at ASC,id ASC",$from,$to),ARRAY_A);
        $wantCity=$this->event_region_city_key($city);$wantTitle=$this->event_listing_norm((string)($anchor['title']??''));$wantVenue=$this->event_listing_norm((string)($anchor['venueName']??''));
        foreach($rows as $row){
            if($this->event_region_city_key((string)($row['city']??''))!==$wantCity)continue;
            $rt=$this->event_listing_norm((string)($row['title']??''));$rv=$this->event_listing_norm((string)($row['venue_name']??''));
            if($rt!==''&&$rt===$wantTitle)return $row;
            if($wantVenue!==''&&$rv===$wantVenue&&strpos($wantTitle,'halloween')!==false&&strpos($rt,'halloween')!==false)return $row;
        }
        return null;
    }

