        foreach($anchors as $rawAnchor){
            $stats['checked']++;$anchor=$rawAnchor;$label=(string)($anchor['title']??'');$city=(string)($anchor['research_municipality']??($anchor['address']['city']??''));
            $existing=$this->halloween_2026_existing_match_v101097($anchor);
            if($existing && strtolower((string)($existing['source']??''))!=='rpg_seasonal_editorial'){
                $stats['existing']++;$stats['items'][]=array('title'=>$label,'city'=>$city,'status'=>'bereits im Eventbestand','source'=>(string)($existing['source']??''),'event_id'=>(int)($existing['id']??0));continue;
