        echo '<p><strong>'.number_format_i18n((int)$research['municipalities_total']).'/'.number_format_i18n((int)$research['municipalities_total']).' Kommunen recherchiert</strong> (Web-Sweep 22.09.2026). In <strong>'.number_format_i18n((int)$research['municipalities_with_anchor']).' Kommunen</strong> wurde mindestens ein belastbarer 2026-Halloween-Anker verifiziert; für '.number_format_i18n((int)$research['municipalities_without_anchor']).' Kommunen gab es in diesem Sweep noch keinen zusätzlichen belastbaren öffentlichen Anker. Das ist kein Beleg, dass dort keine Veranstaltung stattfindet.</p>';
        echo '<p><strong>'.number_format_i18n($total).' verifizierte Anker</strong> im Halloween-Zeitraum. Der Fallback speichert nur Fakten + Quell-URL; keine fremden Beschreibungstexte oder Bilder. ET4/destination.one/Open Data Finder bleiben bei Dubletten höher priorisiert. Neue Fallbacks werden nur mit lokal belegbarer Venue-Geoposition veröffentlicht.</p>';
        echo '<div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(140px,1fr));gap:8px;margin:10px 0 14px">';
        foreach(array('geprüft'=>(int)($s['checked']??0),'bereits vorhanden'=>(int)($s['existing']??0),'Fallback ergänzt'=>(int)($s['inserted']??0),'aktualisiert'=>(int)($s['refreshed']??0),'Geo offen'=>(int)($s['geo_unresolved']??0),'Fehler'=>(int)($s['errors']??0)) as $k=>$v)echo '<div style="background:#f6f7f7;padding:10px;border-radius:6px"><strong>'.number_format_i18n($v).'</strong><br><small>'.esc_html($k).'</small></div>';
        echo '</div>';
        if(!empty($s['items'])&&is_array($s['items'])){echo '<div style="overflow:auto;max-height:620px"><table class="widefat striped"><thead><tr><th>Event</th><th>Stadt</th><th>Status</th><th>Quelle</th></tr></thead><tbody>';foreach($s['items'] as $r){echo '<tr><td>'.esc_html((string)($r['title']??''));if(!empty($r['event_id']))echo '<br><small>Event #'.(int)$r['event_id'].'</small>';echo '</td><td>'.esc_html((string)($r['city']??''));echo '</td><td>'.esc_html((string)($r['status']??''));echo '</td><td><code>'.esc_html((string)($r['source']??'')).'</code></td></tr>';}echo '</tbody></table></div>';}
        if(!empty($research['without'])){echo '<details style="margin-top:12px"><summary><strong>25 Kommunen ohne zusätzlichen belastbaren Web-Anker in diesem Sweep</strong></summary><p style="line-height:1.7">'.esc_html(implode(' · ',(array)$research['without'])).'</p></details>';}
        $url=wp_nonce_url(admin_url('admin-post.php?action=rg_events_halloween_2026_refresh'),'rg_events_halloween_2026_refresh_v101097');echo '<p style="margin-bottom:0"><a class="button" href="'.esc_url($url).'">Halloween-2026-Anker erneut prüfen</a></p></div>';
    }

    private function event_admin_sources() {
        // Avoid SELECT DISTINCT on every admin page load. These are the supported event sources.
        return array('open_data_finder','destination_one_open_data','essen_emg_export','verified-official-wesel','rpg_seasonal_editorial');
    }

    private function event_admin_filters_from_request() {
        $city=sanitize_text_field(wp_unslash((string)($_GET['event_city']??'')));
        $source=sanitize_key((string)($_GET['event_source']??''));
        $master_scope=sanitize_key((string)($_GET['event_master_scope']??'all'));if(!in_array($master_scope,array('all','latest','outside'),true))$master_scope='all';
        $status=sanitize_key((string)($_GET['event_status']??'all'));
        if(!in_array($status,array('all','active','expired'),true))$status='all';
        $media=sanitize_key((string)($_GET['event_media']??'all'));
        if(!in_array($media,array('all','with','without'),true))$media='all';
        $address=sanitize_key((string)($_GET['event_address']??'all'));
        if(!in_array($address,array('all','complete','incomplete'),true))$address='all';
        $enrichment=sanitize_key((string)($_GET['event_enrichment']??'all'));
        if(!in_array($enrichment,array('all','pending','complete','checked_no_media','checked_incomplete','retry','failed'),true))$enrichment='all';
        $when=sanitize_key((string)($_GET['event_when']??'all'));
        if(!in_array($when,array('all','today','7days','30days','past'),true))$when='all';
        $search=sanitize_text_field(wp_unslash((string)($_GET['event_search']??'')));
        $limit=absint($_GET['event_limit']??50);if(!in_array($limit,array(50,100,200),true))$limit=50;
        return array('city'=>$city,'source'=>$source,'master_scope'=>$master_scope,'status'=>$status,'media'=>$media,'address'=>$address,'enrichment'=>$enrichment,'when'=>$when,'search'=>$search,'limit'=>$limit);
    }

    private function event_admin_cities() {
        // The event cache is region-gated. Reuse the canonical 53-municipality seed instead of
        // scanning the growing events table for DISTINCT city values on each page load.
        $cities=array();
        foreach($this->municipalities_seed() as $entry){$name=trim((string)($entry[0]??''));if($name!=='')$cities[$name]=1;}
        $cities=array_keys($cities);natcasesort($cities);return array_values($cities);
    }

    private function event_admin_filters_active($filters) {
        if(trim((string)($filters['city']??''))!=='')return true;
        if(trim((string)($filters['source']??''))!=='')return true;
        if(trim((string)($filters['search']??''))!=='')return true;
        foreach(array('master_scope','status','media','address','enrichment','when') as $key){if(($filters[$key]??'all')!=='all')return true;}
        return false;
    }

    private function event_admin_where($filters,&$params) {
        global $wpdb;$params=array();$where=array('1=1');
        if(!empty($filters['city'])){$where[]='e.city=%s';$params[]=$filters['city'];}
        if(!empty($filters['source'])){$where[]='e.source=%s';$params[]=$filters['source'];}
        $night=get_option('rg_events_nightly_state',array());$latest_token=is_array($night)?sanitize_key((string)($night['run_token']??'')):'';
        if($latest_token!==''&&($filters['master_scope']??'all')==='latest'){$where[]='e.last_master_run=%s';$params[]=$latest_token;}
        elseif($latest_token!==''&&($filters['master_scope']??'all')==='outside'){$where[]="(e.last_master_run<>%s OR e.last_master_run='')";$params[]=$latest_token;}
        if(($filters['status']??'all')!=='all'){$where[]='e.status=%s';$params[]=$filters['status'];}
        if(($filters['media']??'all')==='with'){$where[]="EXISTS (SELECT 1 FROM {$this->table('event_media')} m WHERE m.event_id=e.id AND m.is_primary=1 AND m.moderation_status='active')";}
        elseif(($filters['media']??'all')==='without'){$where[]="NOT EXISTS (SELECT 1 FROM {$this->table('event_media')} m WHERE m.event_id=e.id AND m.is_primary=1 AND m.moderation_status='active')";}
        if(($filters['address']??'all')==='complete'){$where[]="(e.street<>'' AND e.postcode<>'' AND e.city<>'')";}
        elseif(($filters['address']??'all')==='incomplete'){$where[]="(e.street='' OR e.postcode='' OR e.city='')";}
        if(($filters['enrichment']??'all')!=='all'){$where[]='e.enrichment_status=%s';$params[]=$filters['enrichment'];}
        $today=wp_date('Y-m-d 00:00:00',null,wp_timezone());
        $tomorrow=wp_date('Y-m-d 00:00:00',strtotime('+1 day',current_time('timestamp')),wp_timezone());
        if(($filters['when']??'all')==='today'){$where[]='e.start_at >= %s AND e.start_at < %s';$params[]=$today;$params[]=$tomorrow;}
        elseif(($filters['when']??'all')==='7days'){$where[]='e.start_at >= %s AND e.start_at < %s';$params[]=$today;$params[]=wp_date('Y-m-d 00:00:00',strtotime('+7 days',current_time('timestamp')),wp_timezone());}
        elseif(($filters['when']??'all')==='30days'){$where[]='e.start_at >= %s AND e.start_at < %s';$params[]=$today;$params[]=wp_date('Y-m-d 00:00:00',strtotime('+30 days',current_time('timestamp')),wp_timezone());}
        elseif(($filters['when']??'all')==='past'){$where[]='COALESCE(e.end_at,e.start_at) < %s';$params[]=$today;}
        if(!empty($filters['search'])){
            $like='%'.$wpdb->esc_like($filters['search']).'%';
            if(ctype_digit($filters['search'])){$where[]='(e.id=%d OR e.title LIKE %s OR e.venue_name LIKE %s OR e.street LIKE %s OR e.city LIKE %s OR e.source LIKE %s)';$params[]=(int)$filters['search'];for($i=0;$i<5;$i++)$params[]=$like;}
            else{$where[]='(e.title LIKE %s OR e.venue_name LIKE %s OR e.street LIKE %s OR e.city LIKE %s OR e.source LIKE %s)';for($i=0;$i<5;$i++)$params[]=$like;}
        }
        return $where;
    }

    private function event_admin_rows($filters) {
        global $wpdb;$events=$this->table('events');$params=array();$where=$this->event_admin_where($filters,$params);$limit=(int)($filters['limit']??50);
        $sql="SELECT e.id,e.title,e.start_at,e.end_at,e.venue_name,e.street,e.house_number,e.postcode,e.city,e.address_status,e.media_status,e.enrichment_status,e.status,e.source AS source_name,e.last_synced_at,e.last_master_run,e.participants_json FROM $events e WHERE ".implode(' AND ',$where)." ORDER BY e.start_at ASC,e.id ASC LIMIT $limit";
        return (array)$wpdb->get_results($params?$wpdb->prepare($sql,$params):$sql,ARRAY_A);
    }

    private function event_admin_count($filters) {
        global $wpdb;$events=$this->table('events');$params=array();$where=$this->event_admin_where($filters,$params);$sql="SELECT COUNT(*) FROM $events e WHERE ".implode(' AND ',$where);return (int)$wpdb->get_var($params?$wpdb->prepare($sql,$params):$sql);
    }

    private function event_admin_label($kind,$value) {
        $maps=array(
            'status'=>array('active'=>'Aktiv','inactive'=>'Quelle fehlt','expired'=>'Abgelaufen','cancelled'=>'Abgesagt'),
            'address'=>array('verified'=>'Vollständig','complete'=>'Vollständig','partial'=>'Teilweise','pending'=>'Offen'),
            'media'=>array('verified'=>'Geprüft','pending'=>'Offen','rejected'=>'Verworfen'),
            'enrichment'=>array('complete'=>'Geprüft · Bild vorhanden','checked_no_media'=>'Geprüft · kein Bild','checked_incomplete'=>'Geprüft · unvollständig','partial'=>'Teilweise','pending'=>'Offen','retry'=>'Erneut prüfen','failed'=>'Fehlgeschlagen')
        );
        $value=(string)$value;return $maps[$kind][$value]??($value!==''?$value:'–');
    }

    public function admin_event_media_candidate_v1042() {
        if(!current_user_can('manage_options'))wp_die('Keine Berechtigung.');
        $event_id=(int)($_POST['event_id']??0);$media_id=(int)($_POST['media_id']??0);$decision=sanitize_key((string)($_POST['decision']??''));
        check_admin_referer('rg_event_media_candidate_'.$media_id);
        global $wpdb;$media=$this->table('event_media');$row=$wpdb->get_row($wpdb->prepare("SELECT * FROM $media WHERE id=%d AND event_id=%d",$media_id,$event_id),ARRAY_A);if(!$row)wp_die('Bildkandidat nicht gefunden.');
        if(($row['source']??'')!=='official-candidate'||($row['moderation_status']??'')!=='candidate')wp_die('Dieser Bildkandidat ist bereits abschließend bearbeitet.');
        $hash=$this->event_candidate_try_hash_and_store_v1049($row);if($hash!=='')$row['source_content_hash']=$hash;
        $duplicates=$this->event_candidate_duplicate_rows_v1049($row);if(!$duplicates)$duplicates=array($row);$uses=count($duplicates);
        $now=current_time('mysql');$user=(int)get_current_user_id();$note=$this->event_text($_POST['rights_note']??'',2000);$msg='';
        if($decision==='reject'){
            foreach($duplicates as $d){$wpdb->update($media,array('moderation_status'=>'rejected','rights_status'=>'rejected','rights_note'=>$note,'rights_checked_at'=>$now,'rights_checked_by'=>$user,'is_primary'=>0,'last_seen_at'=>$now),array('id'=>(int)$d['id']));$this->event_reselect_primary_v1042((int)$d['event_id']);}
            $msg='Bild verworfen. Die Entscheidung wurde auf '.number_format_i18n($uses).' identische Verwendung'.($uses===1?'':'en').' übertragen.';
        }elseif($decision==='unclear'){
            foreach($duplicates as $d)$wpdb->update($media,array('moderation_status'=>'candidate','rights_status'=>'unclear','rights_note'=>$note,'rights_checked_at'=>$now,'rights_checked_by'=>$user,'health_error'=>'Rechte unklar · redaktionelle Prüfung offen','local_cache_error'=>'Rechte unklar · nicht live','is_primary'=>0,'last_seen_at'=>$now),array('id'=>(int)$d['id']));
            $msg='Bild als unklar markiert. Die Entscheidung gilt für '.number_format_i18n($uses).' identische Verwendung'.($uses===1?'':'en').'.';
        }elseif($decision==='approve'){
            $basis=sanitize_key((string)($_POST['rights_basis']??''));$opts=$this->event_rights_basis_options_v1045();if(!isset($opts[$basis]))wp_die('Bitte eine gültige Nutzungsgrundlage auswählen.');
            $detail=$this->event_text($_POST['license_detail']??'',120);$license=$this->event_rights_basis_label_v1045($basis,$detail);$credit=$this->event_text($_POST['credit']??'',1000);$artist=$this->event_text($_POST['artist']??'',190);$holder=$this->event_text($_POST['rights_holder']??'',190);$proof=esc_url_raw((string)($_POST['rights_proof_url']??''));
            if($basis==='other'&&$detail==='')wp_die('Bei „Sonstige dokumentierte Freigabe“ ist eine konkrete Bezeichnung Pflicht.');
            if($license===''||$credit==='')wp_die('Nutzungsgrundlage und Credit sind für die Freigabe Pflicht.');
            if($proof===''&&$note==='')wp_die('Bitte mindestens eine Nachweis-URL oder eine nachvollziehbare Rechte-Notiz dokumentieren.');
            $candidate=array('imageUrl'=>(string)$row['url'],'sourceUrl'=>(string)$row['source_url'],'license'=>$license,'credit'=>$credit,'artist'=>$artist,'identityConfidence'=>(float)$row['identity_confidence'],'rightsStatus'=>'approved','rightsBasis'=>$basis,'rightsHolder'=>$holder,'rightsProofUrl'=>$proof,'rightsNote'=>$note,'rightsCheckedAt'=>$now,'rightsCheckedBy'=>$user,'sourceContentHash'=>$hash);
            if(!$this->event_store_local_fallback_v1042($event_id,$candidate,'official-approved',(float)$row['identity_confidence']))wp_die('Bild konnte nicht lokalisiert/freigegeben werden.');
            $approved=$wpdb->get_row($wpdb->prepare("SELECT * FROM $media WHERE id=%d",$media_id),ARRAY_A);if(!$approved||($approved['source']??'')!=='official-approved')wp_die('Freigabe wurde gespeichert, aber der freigegebene Medienstand konnte nicht verifiziert werden.');
            // Re-evaluate duplicates against the bytes that were actually cached. This closes the tiny
            // race in which a mutable source URL changes between fingerprinting and local download.
            $duplicates=$this->event_candidate_duplicate_rows_v1049($approved);$uses=1+count($duplicates);$applied=1;
            foreach($duplicates as $d){if($this->event_candidate_clone_approved_v1049($d,$approved))$applied++;}
            $msg='Bild freigegeben. Eine Rechteprüfung gilt jetzt für '.number_format_i18n($applied).' identische Verwendung'.($applied===1?'':'en').'.';
            if($applied<$uses)$msg.=' '.number_format_i18n($uses-$applied).' Verwendung'.(($uses-$applied)===1?'':'en').' konnte(n) nicht automatisch übernommen werden.';
        }else wp_die('Ungültige Aktion.');
        wp_safe_redirect(add_query_arg(array('page'=>'rp-events','event_detail'=>$event_id,'rg_event_notice'=>rawurlencode($msg)),admin_url('admin.php')).'#rg-event-audit');exit;
    }

