        echo '<h3>Enrichment-Prüfweg</h3>';if($audit){echo '<table class="widefat striped"><thead><tr><th>Prüfschritt</th><th>Ergebnis</th><th>Details</th></tr></thead><tbody>';foreach($audit as $a){$details=$a;$step=$details['step']??'';$status=$details['status']??'';unset($details['step'],$details['status']);echo '<tr><td>'.esc_html($step).'</td><td>'.esc_html($status).'</td><td><code style="white-space:pre-wrap">'.esc_html(wp_json_encode($details,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES)).'</code></td></tr>';}echo '</tbody></table>';}else echo '<p><em>Noch kein protokollierter Enrichment-Lauf. Beim nächsten Enrichment wird der Prüfweg gespeichert.</em></p>';
        if($x){echo '<p><strong>Versuche:</strong> '.intval($x['attempts']).' · <strong>zuletzt:</strong> '.esc_html($x['last_enriched_at']??'–').(!empty($x['last_error'])?' · <strong>letzter Fehler:</strong> '.esc_html($x['last_error']):'').'</p>';}
        echo '<h3>Gespeicherte Eventbilder</h3>';
        if($ms){
            echo '<table class="widefat striped"><thead><tr><th>Primär / Status</th><th>Bild</th><th>Quelle</th><th>Lizenz/Credit</th><th>Matching</th><th>Health</th><th>Redaktion</th></tr></thead><tbody>';
            foreach($ms as $m){
                $localPublic=$this->event_local_media_public_url_v1039($m);$openUrl=$localPublic!==''?$localPublic:(string)($m['url']??'');
                $status=(string)($m['moderation_status']??'active');$isCandidate=($status==='candidate'||(string)($m['source']??'')==='official-candidate');
                echo '<tr><td>'.($m['is_primary']?'<strong>Ja</strong>':'Nein').'<br><small>'.esc_html($status).'</small></td>';
                echo '<td>'.($openUrl!==''?'<a href="'.esc_url($openUrl).'" target="_blank" rel="noopener">Bild öffnen</a>':'–').($localPublic!==''?'<br><small>lokal gespeichert</small>':($isCandidate?'<br><small>nur Kandidat · nicht live</small>':'')).'</td>';
                echo '<td><strong>'.esc_html((string)$m['source']).'</strong>'.(!empty($m['source_url'])?'<br><a href="'.esc_url($m['source_url']).'" target="_blank" rel="noopener">Quellseite</a>':'').'</td>';
                echo '<td>'.esc_html(trim(($m['license']??'').' '.($m['credit']??''))).(!empty($m['artist'])?'<br><small>'.esc_html($m['artist']).'</small>':'').(!empty($m['rights_status'])?'<br><small>Rechte: '.esc_html($this->event_rights_status_label_v1045((string)$m['rights_status'])).(!empty($m['rights_holder'])?' · '.esc_html($m['rights_holder']):'').'</small>':'').(!empty($m['rights_proof_url'])?'<br><small><a href="'.esc_url($m['rights_proof_url']).'" target="_blank" rel="noopener">Rechtenachweis</a></small>':'').'</td>';
                echo '<td>'.esc_html($m['identity_confidence']).'</td>';
                echo '<td><strong>'.esc_html($m['health_status']??'unchecked').'</strong><br><small>HTTP '.intval($m['health_http_status']??0).' · '.esc_html($m['health_content_type']??'').(!empty($m['health_checked_at'])?' · '.esc_html($m['health_checked_at']):'').'</small>'.(!empty($m['health_error'])?'<br><small style="color:#b32d2e">'.esc_html($m['health_error']).'</small>':'').'</td>';
                echo '<td>';
                if($isCandidate){
                    $rightsStatus=(string)($m['rights_status']??'pending');$mailto=$this->event_permission_request_mailto_v1045($e,$m,$orgs);$candidateCredit=((string)($m['credit']??'')==='Bildkandidat · offizielle Veranstaltungsseite')?'':(string)($m['credit']??'');$duplicateUses=count($this->event_candidate_duplicate_rows_v1049($m));
                    echo '<div style="min-width:320px"><p style="margin:0 0 8px"><strong>Rechtestatus:</strong> '.esc_html($this->event_rights_status_label_v1045($rightsStatus)).'</p>';
                    if($duplicateUses>1)echo '<p style="margin:0 0 8px;padding:8px 10px;background:#e7f5ea;border-left:3px solid #00a32a"><strong>Dieses identische Bild wird '.number_format_i18n($duplicateUses).'× verwendet.</strong><br><small>Deine Rechteentscheidung wird automatisch auf alle diese Verwendungen übertragen.</small></p>';
                    if($openUrl!=='')echo '<p style="margin:0 0 8px"><img src="'.esc_url($openUrl).'" alt="" loading="lazy" referrerpolicy="no-referrer" style="max-width:240px;max-height:150px;object-fit:cover;border:1px solid #dcdcde;border-radius:4px"></p>';
                    echo '<p style="margin:0 0 8px;color:#646970"><small>Das gefundene Bild bzw. ein <code>og:image</code> ist noch keine Nutzungserlaubnis. Freigabe nur mit dokumentierter Grundlage.</small></p>';
                    if($mailto!=='')echo '<p style="margin:0 0 10px"><a class="button" href="'.esc_attr($mailto).'">Freigabe anfragen</a> <small>öffnet dein E-Mail-Programm mit vorbereitetem Text</small></p>';
                    echo '<form method="post" action="'.esc_url(admin_url('admin-post.php')).'"><input type="hidden" name="action" value="rg_event_media_candidate"><input type="hidden" name="event_id" value="'.intval($event_id).'"><input type="hidden" name="media_id" value="'.intval($m['id']).'">';wp_nonce_field('rg_event_media_candidate_'.intval($m['id']));
                    echo '<p style="margin:0 0 6px"><label><strong>Nutzungsgrundlage</strong><br><select name="rights_basis" style="width:100%"><option value="">Bitte auswählen …</option>';foreach($this->event_rights_basis_options_v1045() as $v=>$l)echo '<option value="'.esc_attr($v).'">'.esc_html($l).'</option>';echo '</select></label></p>';
                    echo '<p style="margin:0 0 6px"><label>Lizenz-/Freigabe-Detail<br><input type="text" name="license_detail" class="regular-text" placeholder="z. B. CC BY-SA 4.0 / Freigabe vom 11.09.2026"></label></p>';
                    echo '<p style="margin:0 0 6px"><label>Rechteinhaber<br><input type="text" name="rights_holder" class="regular-text" value="'.esc_attr((string)($m['rights_holder']??'')).'"></label></p>';
                    echo '<p style="margin:0 0 6px"><label><strong>Credit</strong><br><input type="text" name="credit" class="regular-text" placeholder="Pflicht bei Freigabe" value="'.esc_attr($candidateCredit).'"></label></p>';
                    echo '<p style="margin:0 0 6px"><label>Urheber/Fotograf<br><input type="text" name="artist" class="regular-text" value="'.esc_attr((string)($m['artist']??'')).'"></label></p>';
                    echo '<p style="margin:0 0 6px"><label>Nachweis-URL<br><input type="url" name="rights_proof_url" class="regular-text" placeholder="Lizenzseite / Presseseite / dokumentierte Freigabe-URL" value="'.esc_attr((string)($m['rights_proof_url']??'')).'"></label></p>';
                    echo '<p style="margin:0 0 8px"><label>Rechte-Notiz / Nachweis<br><textarea name="rights_note" rows="3" style="width:100%" placeholder="z. B. schriftliche Freigabe per E-Mail vom … / Nutzungsbedingungen geprüft …">'.esc_textarea((string)($m['rights_note']??'')).'</textarea></label></p>';
                    echo '<button class="button button-primary" name="decision" value="approve">Rechte geprüft · freigeben</button> <button class="button" name="decision" value="unclear">Unklar</button> <button class="button" name="decision" value="reject">Verwerfen</button></form></div>';
                }else echo '–';
                echo '</td></tr>';
            }
            echo '</tbody></table>';
        }else echo '<p><em>Noch kein geprüftes Eventbild gespeichert.</em></p>';

        echo '<h3>Redaktionelles Eventbild</h3><div style="background:#f6f7f7;border:1px solid #dcdcde;border-radius:6px;padding:12px;max-width:900px">';
        echo '<p style="margin-top:0">Optionaler manueller Override für genau diese <code>global_id</code>. Das Bild wird lokal gespeichert und übersteuert automatische Fallbacks, aber niemals ein natives ET4/ODF- oder destination.one-Eventbild.</p>';
        echo '<form method="post" enctype="multipart/form-data" action="'.esc_url(admin_url('admin-post.php')).'"><input type="hidden" name="action" value="rg_event_media_override"><input type="hidden" name="event_id" value="'.intval($event_id).'">';wp_nonce_field('rg_event_media_override_'.intval($event_id));
        echo '<p><label><strong>Bilddatei</strong><br><input type="file" name="event_override_image" accept="image/jpeg,image/png,image/webp,image/gif,image/avif" required></label></p>';
        echo '<p><label><strong>Nutzungsgrundlage</strong><br><select name="rights_basis" required><option value="">Bitte auswählen …</option>';foreach($this->event_rights_basis_options_v1045() as $v=>$l)echo '<option value="'.esc_attr($v).'">'.esc_html($l).'</option>';echo '</select></label></p>';
        echo '<p><label>Lizenz-/Freigabe-Detail<br><input type="text" name="license_detail" class="regular-text" placeholder="z. B. CC BY 4.0 / Freigabe vom …"></label></p>';
        echo '<p><label>Rechteinhaber<br><input type="text" name="rights_holder" class="regular-text"></label></p>';
        echo '<p><label><strong>Credit</strong><br><input type="text" name="credit" class="regular-text" required></label></p>';
        echo '<p><label>Urheber/Fotograf<br><input type="text" name="artist" class="regular-text"></label></p>';
        echo '<p><label>Bild-/Quellseite<br><input type="url" name="source_url" class="regular-text" placeholder="https://…"></label></p>';
        echo '<p><label>Rechtenachweis-URL<br><input type="url" name="rights_proof_url" class="regular-text" placeholder="Lizenz-/Presseseite"></label></p>';
        echo '<p><label>Rechte-Notiz / Nachweis<br><textarea name="rights_note" rows="3" class="large-text" placeholder="z. B. schriftliche Freigabe per E-Mail vom …"></textarea></label></p>';
        submit_button('Redaktionelles Bild lokal speichern','secondary','submit',false);echo '</form></div>';
        echo '<h3>Feed-Quellen</h3>';if($ss){echo '<ul>';foreach($ss as $src)echo '<li>'.esc_html($src['source_name']?:$src['source_type']).(!empty($src['source_url'])?' · <a href="'.esc_url($src['source_url']).'" target="_blank" rel="noopener">öffnen</a>':'').'</li>';echo '</ul>';}else echo '<p>–</p>';echo '</div>';
    }


    /** V1.10.64 read-only audit using the SAME visitor clustering/dedupe logic as the public lists. */
    private function event_final_quality_audit_v1063() {
        global $wpdb;$events=$this->table('events');$media=$this->table('event_media');$cities=array('Essen','Dortmund','Duisburg','Bochum','Oberhausen','Wesel');$rows=array();$now=current_time('mysql');
        foreach($cities as $city){
            // Fetch enough raw occurrences first; then collapse exactly as the visitor list does.
            $part=(array)$wpdb->get_results($wpdb->prepare("SELECT * FROM $events WHERE status='active' AND city=%s AND (end_at IS NULL OR end_at >= %s) ORDER BY start_at ASC,id ASC LIMIT 60",$city,$now),ARRAY_A);
            $part=array_values(array_map(array($this,'event_apply_curated_visitor_data_to_row'),$part));
            $part=$this->event_listing_cluster_rows($part);
            usort($part,function($a,$b){return strtotime((string)($a['start_at']??''))<=>strtotime((string)($b['start_at']??''));});
            foreach(array_slice($part,0,2) as $r)$rows[]=$r;
        }
        $out=array();
        foreach($rows as $r){
            $raw=json_decode((string)($r['raw_payload']??''),true);if(!is_array($raw))$raw=array();
            $org=$this->event_current_organizers_from_row_v1063($r);$docs=$this->event_documents_from_item_v1063($raw);$website=$this->event_public_website_from_item($raw);$ticket=$this->event_booking_url_from_item_v1058($raw);
            $clusterIds=!empty($r['_rpg_cluster_ids'])?array_values(array_filter(array_map('intval',(array)$r['_rpg_cluster_ids']))):array((int)$r['id']);if(!$clusterIds)$clusterIds=array((int)$r['id']);
            $idSql=implode(',',array_map('intval',$clusterIds));$hasImage=(int)$wpdb->get_var("SELECT COUNT(*) FROM $media WHERE event_id IN ($idSql) AND media_type='image' AND moderation_status='active' AND local_cache_status='ready' AND local_path<>''")>0;
            $participants=(array)json_decode((string)($r['participants_json']??''),true);$info=(array)json_decode((string)($r['event_info_json']??''),true);
            $descriptionOk=trim((string)$r['description'])!=='';$addressOk=trim((string)$r['venue_name'])!==''||trim((string)$r['street'])!=='';
            // 1.10.79: distinguish a real source-data gap from a parser/normalization loss.
            $rawDescriptionBundle=$this->event_description_bundle($raw);
            $rawDescriptionAvailable=trim((string)($rawDescriptionBundle['full']??''))!==''||trim((string)($rawDescriptionBundle['short']??''))!=='';
            $rawExplicitWebsite='';
            foreach(array('website','homepage','web','officialUrl','official_url','eventUrl','event_url','sameAs') as $wk){
                $wu=esc_url_raw($this->event_text($raw[$wk]??'',1000));
                if($wu!==''&&preg_match('~^https?://~i',$wu)&&!$this->event_is_provider_or_directory_url($wu)){$rawExplicitWebsite=$wu;break;}
            }
            $startText=trim((string)$r['start_at']);$calendarOk=$startText!==''&&strtotime($startText)!==false;
            $shareUrl=$this->event_canonical_share_url_v1057((int)$r['id'],(string)$r['title'],(string)($r['city']??''));
            $shareHost=strtolower((string)wp_parse_url($shareUrl,PHP_URL_HOST));$shareHost=preg_replace('/^www\./','',$shareHost);
            $homeHost=strtolower((string)wp_parse_url(home_url('/'),PHP_URL_HOST));$homeHost=preg_replace('/^www\./','',$homeHost);
            $sharePath=(string)wp_parse_url($shareUrl,PHP_URL_PATH);
            $shareOk=$shareUrl!==''&&$shareHost!==''&&$shareHost===$homeHost&&strpos($sharePath,'/teilen/event/'.(int)$r['id'].'/')===0;
            // 1.10.78: exercise the real single-Event read model used by direct links,
            // inline related navigation and OG/Twitter share metadata.
            $direct=$this->share_event_payload((int)$r['id']);$directItem=is_array($direct['item']??null)?$direct['item']:array();$directMedia=is_array($directItem['rpg_event_media']??null)?$directItem['rpg_event_media']:array();
            $directImage=esc_url_raw((string)($directMedia['imageUrl']??''));$directShareImage=esc_url_raw((string)($direct['share']['image']??''));$directObj='';
            if(!empty($directItem['media_objects'][0])&&is_array($directItem['media_objects'][0]))$directObj=esc_url_raw((string)($directItem['media_objects'][0]['url']??($directItem['media_objects'][0]['contentUrl']??'')));
            $directSource=sanitize_key((string)($directMedia['source']??''));$allowedDirectSources=array('et4-global-id-local','editorial-override','official-approved','venue-editorial-pool','venue-commons-context','pexels-symbolic-event');
            // A direct ET4 payload must never expose a provider/raw image branch after finalization.
            // With an image, every public image pointer must resolve to the standardized final image;
            // without an image, no legacy media branch may leak through at all.
            $directRawLeak=false;
            foreach(array('mediaObjects','media_object','mediaObject','media','images','photos','photo','thumbnailUrl') as $mk){if(!empty($directItem[$mk])){$directRawLeak=true;break;}}
            $directTopImage=esc_url_raw((string)($directItem['image']??''));$directTopImageUrl=esc_url_raw((string)($directItem['imageUrl']??''));
            if($directImage===''){
                if(!empty($directItem['media_objects'])||$directTopImage!==''||$directTopImageUrl!=='')$directRawLeak=true;
            }
            $directPointersOk=$directImage===''?(!$directRawLeak):($directObj===$directImage&&$directTopImage===$directImage&&$directTopImageUrl===$directImage);
            $directMediaOk=($directImage===$directShareImage)&&$directPointersOk&&($directImage===''||(in_array($directSource,$allowedDirectSources,true)&&!empty($directMedia['verified'])));
            $directDetails=is_array($directItem['rpg_event_details']??null)?$directItem['rpg_event_details']:array();$directCanonical=esc_url_raw((string)($directDetails['canonicalUrl']??''));
            $directCanonicalOk=$directCanonical!==''&&untrailingslashit($directCanonical)===untrailingslashit($shareUrl);
            $dgeo=is_array($directItem['geo']??null)?$directItem['geo']:array();$dlat=$dgeo['latitude']??($directItem['latitude']??null);$dlng=$dgeo['longitude']??($directItem['longitude']??null);$directContextOk=(is_numeric($dlat)&&is_numeric($dlng))||trim((string)($direct['share']['city']??''))!=='';
            $seriesMeta=$this->event_family_explicit_meta_v1061($raw);$seriesHint=!empty($seriesMeta['ids'])||!empty($seriesMeta['labels'])||$this->event_family_has_series_cue_v1061($this->event_family_norm_v1061((string)$r['title']));
            $categoryHay=mb_strtolower((string)$r['title'].' '.(string)($r['event_category']??'').' '.implode(' ',(array)($info['categories']??array())),'UTF-8');
            $participantsExpected=(bool)preg_match('/konzert|orgel|orchester|chor|ensemble|musik|theater|bühne|buehne|oper|kabarett|comedy|lesung|show|performance/iu',$categoryHay);
            $rawJson=(string)wp_json_encode($raw,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES);$programExpected=(bool)preg_match('/"(?:program(?:me)?|programm|flyer|schedule|timetable|agenda|brochure|document|pdf)[^"]*"\s*:/iu',$rawJson);
            $critical=array();$notes=array();
            $organizerEvidence=$this->event_organizer_role_evidence_v1064($raw);$organizerConflict=false;
            foreach($org as $oo){$on=trim((string)(($oo['name']??'')!==''?$oo['name']:($oo['company']??'')));$okey=$this->event_org_identity_v1063($on);if($okey==='')continue;$oe=(array)($organizerEvidence[$okey]??array());if((int)($oe['negative']??0)<=-70&&(int)($oe['positive']??0)<100){$organizerConflict=true;break;}}
            if(trim((string)$r['title'])==='')$critical[]='Titel fehlt';
            if(!$calendarOk)$critical[]='Termin fehlt/ungültig';
            if(trim((string)$r['city'])==='')$critical[]='Stadt fehlt';
            if(!$addressOk)$critical[]='Ort/Adresse fehlt';
            if(!$descriptionOk&&$rawDescriptionAvailable)$critical[]='Beschreibung im Import/Resolver verloren';
            if($rawExplicitWebsite!==''&&$website==='')$critical[]='Event-Webseite im Resolver verloren';
            if($website!==''&&$this->event_is_provider_or_directory_url($website))$critical[]='unsichere Event-Webseite';
            if($ticket!==''&&$this->event_is_provider_or_directory_url($ticket))$critical[]='unsicherer Ticketlink';
            if(!$shareOk)$critical[]='RuhrpottGuru-Direktlink ungültig';
            if(!$directMediaOk)$critical[]='Direkt-/Share-Medien nicht konsistent';
            if(!$directCanonicalOk)$critical[]='Direktpayload nutzt abweichende Canonical-URL';
            if(!$directContextOk)$critical[]='Direktlink ohne Event-Ort-Kontext';
            if($organizerConflict)$critical[]='Veranstalter hat Provider/Media-Rollenkonflikt';
            if(!$hasImage)$notes[]='kein lokales Eventbild';
            if(!$descriptionOk&&!$rawDescriptionAvailable)$notes[]='Quelle liefert keine Beschreibung';
            if(!count($org))$notes[]='Veranstalter nicht hinterlegt';
            if($website===''&&$ticket==='')$notes[]='kein Web-/Ticketlink';
            if($participantsExpected&&!count($participants))$notes[]='Mitwirkende nicht hinterlegt';
            if($programExpected&&!count($docs))$notes[]='Programmhinweis ohne Download';
            $level=$critical?'Prüfen':($notes?'Hinweis':'OK');$reasons=$critical?:$notes;
            $organizerNames=array();
            foreach($org as $o){$n=trim((string)(($o['name']??'')!==''?$o['name']:($o['company']??'')));if($n!==''&&!in_array($n,$organizerNames,true))$organizerNames[]=$n;}
            $host=function($url){$h=wp_parse_url((string)$url,PHP_URL_HOST);$h=strtolower((string)$h);return preg_replace('/^www\./','',$h);};
            $out[]=array(
                'id'=>(int)$r['id'],'city'=>(string)$r['city'],'title'=>(string)$r['title'],'start'=>(string)$r['start_at'],'allDay'=>$this->event_all_day_from_row_v1063($r,$raw),
                'occurrences'=>max(1,(int)($r['_rpg_cluster_count']??count($clusterIds))),'image'=>$hasImage,'address'=>$addressOk,'description'=>$descriptionOk,'price'=>trim((string)$r['price_text'])!=='',
                'organizer'=>count($org),'organizerNames'=>$organizerNames,'participants'=>count($participants),'participantsExpected'=>$participantsExpected,
                'website'=>$website!==''?1:0,'websiteUrl'=>$website,'websiteHost'=>$host($website),
                'ticket'=>$ticket!==''?1:0,'ticketUrl'=>$ticket,'ticketHost'=>$host($ticket),
                'documents'=>count($docs),'calendar'=>$calendarOk,'seriesHint'=>$seriesHint,
                'shareOk'=>$shareOk,'shareUrl'=>$shareUrl,'shareHost'=>$shareHost,'directMediaOk'=>$directMediaOk,'directCanonicalOk'=>$directCanonicalOk,'directContextOk'=>$directContextOk,'directImageSource'=>$directSource,'organizerConflict'=>$organizerConflict,
                'level'=>$level,'reasons'=>$reasons,'critical'=>$critical,'notes'=>$notes
            );
        }
        return $out;
    }

    private function render_event_final_quality_audit_v1063() {
        $rows=$this->event_final_quality_audit_v1063();$counts=array('OK'=>0,'Hinweis'=>0,'Prüfen'=>0);foreach($rows as $r)$counts[$r['level']]++;
        echo '<div style="max-width:1180px;background:#fff;border:1px solid #dcdcde;border-radius:8px;padding:16px;margin:0 0 18px"><h2 style="margin-top:0">Event-Finalcheck · Besucheransicht</h2><p>Bis zu zwei aktuelle <strong>sichtbare Eventkarten</strong> aus Essen, Dortmund, Duisburg, Bochum, Oberhausen und Wesel. Vor der Prüfung laufen dieselbe Dedupe-/Occurrence-Clusterlogik und derselbe Veranstalter-Resolver wie im Besucher-Frontend. Veranstalternamen sowie die tatsächlichen Ziel-Domains von Event-Webseite und Ticketlink werden sichtbar ausgewiesen. Zusätzlich werden der kanonische RuhrpottGuru-Direktlink, der echte Single-Event-/Share-Payload inklusive Bildhierarchie und Event-Ort-Kontext, Kalenderfähigkeit und verbliebene Organizer-Rollenkonflikte geprüft. Es werden ausschließlich lokal gespeicherte Eventdaten verwendet.</p>';
        echo '<div style="display:flex;gap:10px;flex-wrap:wrap;margin:12px 0 16px">';
        foreach(array('OK'=>array('#e7f5ea','#176b2c'),'Hinweis'=>array('#fff4ce','#8a5a00'),'Prüfen'=>array('#fde8e7','#9b1c1c')) as $label=>$colors)echo '<div style="background:'.$colors[0].';color:'.$colors[1].';border-radius:999px;padding:7px 12px;font-weight:700">'.esc_html($label).' · '.number_format_i18n($counts[$label]).'</div>';
        echo '</div><div style="overflow:auto"><table class="widefat striped"><thead><tr><th>Status</th><th>Stadt / Event</th><th>Termin</th><th>Termine → Karte</th><th>Adresse</th><th>Bild</th><th>Text</th><th>Preis</th><th>Veranstalter</th><th>Mitwirk.</th><th>Web/Ticket-Ziel</th><th>Share</th><th>Direkt/E2E</th><th>Kalender</th><th>Reihe</th><th>Programm</th></tr></thead><tbody>';
        foreach($rows as $r){
            $badge=$r['level']==='OK'?array('#e7f5ea','#176b2c'):($r['level']==='Hinweis'?array('#fff4ce','#8a5a00'):array('#fde8e7','#9b1c1c'));
            $reason=$r['reasons']?implode(' · ',$r['reasons']):'keine Auffälligkeit';
            $orgCell='–';if(!empty($r['organizerNames'])){$orgCell='<strong>'.esc_html(implode(' · ',$r['organizerNames'])).'</strong><br><small>'.number_format_i18n(count($r['organizerNames'])).' erkannt</small>';}
            $linkBits=array();
            if(!empty($r['websiteUrl']))$linkBits[]='<a href="'.esc_url($r['websiteUrl']).'" target="_blank" rel="noopener">Web</a><br><small>'.esc_html($r['websiteHost']).'</small>';
            if(!empty($r['ticketUrl']))$linkBits[]='<a href="'.esc_url($r['ticketUrl']).'" target="_blank" rel="noopener">Ticket</a><br><small>'.esc_html($r['ticketHost']).'</small>';
            $linkCell=$linkBits?implode('<br>',$linkBits):'–';
            $shareCell=!empty($r['shareOk'])?('<a href="'.esc_url($r['shareUrl']).'" target="_blank" rel="noopener">✓ Direktlink</a><br><small>'.esc_html($r['shareHost']).'</small>'):'✕';
            $directCell=(!empty($r['directMediaOk'])&&!empty($r['directCanonicalOk'])&&!empty($r['directContextOk']))?'✓':'✕';if(!empty($r['directImageSource']))$directCell.='<br><small>'.esc_html($r['directImageSource']).'</small>';
            echo '<tr><td><span style="display:inline-block;background:'.$badge[0].';color:'.$badge[1].';border-radius:999px;padding:3px 8px;font-weight:700">'.esc_html($r['level']).'</span><br><small>'.esc_html($reason).'</small></td><td><strong>'.esc_html($r['city']).'</strong><br>'.esc_html($r['title']).'</td><td>'.esc_html($r['start']).($r['allDay']?'<br><small>Ganztag</small>':'').'</td><td>'.number_format_i18n($r['occurrences']).' → 1</td><td>'.($r['address']?'✓':'–').'</td><td>'.($r['image']?'✓':'–').'</td><td>'.($r['description']?'✓':'–').'</td><td>'.($r['price']?'✓':'–').'</td><td>'.$orgCell.'</td><td>'.($r['participants']?number_format_i18n($r['participants']):($r['participantsExpected']?'–':'n. r.')).'</td><td>'.$linkCell.'</td><td>'.$shareCell.'</td><td>'.$directCell.'</td><td>'.($r['calendar']?'✓':'✕').'</td><td>'.($r['seriesHint']?'Hinweis':'–').'</td><td>'.number_format_i18n($r['documents']).'</td></tr>';
        }
        if(!$rows)echo '<tr><td colspan="16">Keine passenden aktuellen Events im lokalen Bestand gefunden.</td></tr>';echo '</tbody></table></div><p style="margin:12px 0 0;color:#646970"><small><strong>Prüfen</strong> = vorhandene Quelldaten gehen technisch verloren, Kerninformation fehlt trotz Quelle oder ein Link ist unsicher. <strong>Hinweis</strong> = die Quelle selbst liefert eine optionale/qualitative Ergänzung nicht. <strong>OK</strong> = in den geprüften Besucherfeldern keine Auffälligkeit. Preis, Programm und Mitwirkende sind nur dann Pflicht, wenn die Quelldaten bzw. Eventart sie erwarten lassen.</small></p></div>';
    }

    public function render_rp_events_page() {
