        $selmState=get_option(self::EVENT_SELM_STATE,array());if(!is_array($selmState))$selmState=array();$selmNext=wp_next_scheduled(self::EVENT_SELM_HOOK);$selmBatchNext=wp_next_scheduled(self::EVENT_SELM_BATCH_HOOK);$selmStatus=(string)($selmState['status']??'wartet');
