        $opts=array('all'=>'Alle Bilder','with'=>'Mit geprüftem Bild','without'=>'Ohne geprüftes Bild');echo '<label><strong>Bild</strong><br><select name="event_media" style="width:100%">';foreach($opts as $v=>$l)echo '<option value="'.$v.'" '.selected($event_filters['media'],$v,false).'>'.$l.'</option>';echo '</select></label>';
        $opts=array('all'=>'Alle Adressen','complete'=>'Vollständig','incomplete'=>'Unvollständig');echo '<label><strong>Adresse</strong><br><select name="event_address" style="width:100%">';foreach($opts as $v=>$l)echo '<option value="'.$v.'" '.selected($event_filters['address'],$v,false).'>'.$l.'</option>';echo '</select></label>';
        $opts=array('all'=>'Alle Enrichments','pending'=>'Offen','complete'=>'Geprüft · Bild vorhanden','checked_no_media'=>'Geprüft · kein Bild','checked_incomplete'=>'Geprüft · unvollständig','retry'=>'Erneut prüfen','failed'=>'Fehlgeschlagen');echo '<label><strong>Enrichment</strong><br><select name="event_enrichment" style="width:100%">';foreach($opts as $v=>$l)echo '<option value="'.$v.'" '.selected($event_filters['enrichment'],$v,false).'>'.$l.'</option>';echo '</select></label>';
        $opts=array('all'=>'Alle Termine','today'=>'Heute','7days'=>'Nächste 7 Tage','30days'=>'Nächste 30 Tage','past'=>'Vergangen');echo '<label><strong>Termin</strong><br><select name="event_when" style="width:100%">';foreach($opts as $v=>$l)echo '<option value="'.$v.'" '.selected($event_filters['when'],$v,false).'>'.$l.'</option>';echo '</select></label>';
        echo '<label><strong>Suche</strong><br><input type="search" name="event_search" value="'.esc_attr($event_filters['search']).'" placeholder="Event, Venue, Straße, Stadt …" style="width:100%"></label>';
        echo '<label><strong>Anzahl</strong><br><select name="event_limit" style="width:100%">';foreach(array(50,100,200) as $n)echo '<option value="'.$n.'" '.selected($event_filters['limit'],$n,false).'>'.$n.'</option>';echo '</select></label>';
        echo '</div><div style="display:flex;gap:8px;align-items:center;margin-top:12px"><button class="button button-primary" type="submit">Filtern</button><a class="button" href="'.esc_url(add_query_arg(array('page'=>'rp-events'),admin_url('admin.php'))).'#rg-event-audit">Zurücksetzen</a>'.($filters_active?'<span style="color:#646970">'.number_format_i18n($filtered_count).' angezeigt · Limit '.intval($event_filters['limit']).'</span>':'<span style="color:#646970">Eventliste wird erst nach Auswahl eines Filters oder einer Suche geladen.</span>').'</div></form>';
