        echo '</tbody></table></div>';
    }

    private function contribution_field_labels() {
        return array(
            'opening_hours'=>'Öffnungszeiten','website'=>'Website','phone'=>'Telefon','menu_url'=>'Speisekarte / Menü',
            'reservation_url'=>'Reservierungslink','cuisine'=>'Küche / Angebot','price_tier'=>'Preis-Hinweis','description'=>'Beschreibung / Hinweis',
            'community_status'=>'Status des Ortes','access'=>'Zugang / Zugänglichkeit','accessibility'=>'Barrierefreiheit','admission'=>'Eintritt / Kosten',
            'ticket_url'=>'Tickets','program_url'=>'Programm','booking_url'=>'Buchung / Reservierung','activity_type'=>'Art der Aktivität / Ausstattung',
            'instagram'=>'Instagram','mixed_candy'=>'Gemischte Tüte','coffee'=>'Kaffee','sandwiches'=>'Belegte Brötchen','seating'=>'Sitzplätze',
            'lottery'=>'Lotto','parcel_shop'=>'Paketshop','tobacco'=>'Tabak','late_night'=>'Spät geöffnet'
        );
    }

    private function contribution_category_label($category) {
        $map=array('food'=>'Food','highlights'=>'Highlights','culture'=>'Kultur','activities'=>'Aktivitäten','buedchen'=>'Büdchen','wurst'=>'Imbissbuden','night'=>'Nachtfoto');
        $category=sanitize_key((string)$category);return $map[$category]??($category!==''?$category:'–');
    }

    private function current_place_contribution_value($place_id,$field) {
        global $wpdb;$place_id=(int)$place_id;$field=sanitize_key((string)$field);
        $orow=$this->override_row($place_id);$odata=$this->decode_override_data($orow?:'');
        $override=$this->override_field_value($odata,$field,null);if($override!==null)return is_bool($override)?($override?'Ja':'Nein'):(string)$override;
        if(array_key_exists($field,$odata['features']))return $odata['features'][$field]?'Ja':'Nein';
        $places=$this->table('places');$row=$wpdb->get_row($wpdb->prepare("SELECT * FROM $places WHERE id=%d",$place_id),ARRAY_A);if(!$row)return '';
        $tags=json_decode((string)($row['raw_tags']??''),true);if(!is_array($tags))$tags=array();
        $map=array('phone'=>'phone','website'=>'website','opening_hours'=>'opening_hours','instagram'=>'contact:instagram','description'=>'description','menu_url'=>'menu','reservation_url'=>'reservation:website','booking_url'=>'booking','ticket_url'=>'tickets','program_url'=>'programme','cuisine'=>'cuisine','access'=>'access','accessibility'=>'wheelchair','admission'=>'charge');
        if(isset($map[$field]) && isset($tags[$map[$field]]))return (string)$tags[$map[$field]];
        if(isset($row[$field]))return (string)$row[$field];
        return '';
    }

    private function pending_data_contributions($limit=120) {
        $rows=$this->pending_place_contributions($limit);$out=array();
        foreach($rows as $row){$payload=json_decode((string)$row['payload_json'],true);$fields=is_array($payload['fields']??null)?$payload['fields']:array();if($fields){$row['_payload']=$payload;$row['_fields']=$fields;$out[]=$row;}}
        return $out;
    }

    private function submission_pending_media_count($submission_id) {
        global $wpdb;$m=$this->table('place_media_submissions');return (int)$wpdb->get_var($wpdb->prepare("SELECT COUNT(*) FROM $m WHERE submission_id=%d AND status='pending'",(int)$submission_id));
    }

    private function submission_pending_data_count($submission_id) {
        global $wpdb;$s=$this->table('place_override_submissions');$row=$wpdb->get_row($wpdb->prepare("SELECT payload_json FROM $s WHERE id=%d AND status='pending' AND submission_type='place_contribution'",(int)$submission_id),ARRAY_A);
        if(!$row)return 0;$payload=json_decode((string)$row['payload_json'],true);$fields=is_array($payload['fields']??null)?$payload['fields']:array();return count($fields);
    }

    public function render_rp_editor_data_page() {
        if(!current_user_can('manage_options'))wp_die('Keine Berechtigung.');
        $rows=$this->pending_data_contributions(160);$labels=$this->contribution_field_labels();
        echo '<div class="wrap"><h1>RP Redaktion · Daten</h1><p>Hier erscheinen ausschließlich neue Datenvorschläge. Jedes Feld kann unabhängig übernommen oder abgelehnt werden. Reine Bild-Einsendungen erscheinen nur unter <strong>Medien</strong>.</p>';
        echo '<p><a class="button" href="'.esc_url(add_query_arg(array('page'=>'rp-redaktion-medien'),admin_url('admin.php'))).'">Zu Medien →</a></p>';
        if(!empty($_GET['rg_contribution_reviewed']))echo '<div class="notice notice-success inline"><p>Datenentscheidung gespeichert.</p></div>';
        if(!$rows){echo '<div style="max-width:1100px;background:#fff;border:1px solid #dcdcde;border-radius:8px;padding:18px"><strong>Keine neuen Daten zur Freigabe.</strong></div></div>';return;}
        foreach($rows as $sub){$payload=$sub['_payload'];$fields=$sub['_fields'];$cat=(string)($payload['category']??'');$media_count=$this->submission_pending_media_count((int)$sub['id']);
            echo '<div style="max-width:1150px;background:#fff;border:1px solid #dcdcde;border-radius:9px;padding:14px;margin:14px 0">';
            echo '<div style="display:flex;justify-content:space-between;gap:12px;flex-wrap:wrap"><div><h2 style="margin:0 0 4px;font-size:18px">'.esc_html($sub['place_name']?:('#'.$sub['place_id'])).'</h2><div style="color:#646970">'.esc_html($this->contribution_category_label($cat)).' · Einsendung #'.intval($sub['id']).' · '.esc_html($sub['created_at']).'</div></div>';
            if($media_count)echo '<a class="button" href="'.esc_url(add_query_arg(array('page'=>'rp-redaktion-medien','submission_id'=>(int)$sub['id']),admin_url('admin.php'))).'">enthält zusätzlich '.intval($media_count).' Bild'.($media_count===1?'':'er').' →</a>';
            echo '</div><table class="widefat striped" style="margin-top:12px"><thead><tr><th>Feld</th><th>Bisher</th><th>Vorschlag</th><th>Entscheidung</th></tr></thead><tbody>';
            foreach($fields as $field=>$value){$field=sanitize_key((string)$field);$old=$this->current_place_contribution_value((int)$sub['place_id'],$field);$display=is_bool($value)?($value?'Ja':'Nein'):(string)$value;
                echo '<tr><td><strong>'.esc_html($labels[$field]??$field).'</strong></td><td>'.($old!==''?esc_html($old):'<em>unbekannt</em>').'</td><td><strong>'.esc_html($display).'</strong></td><td><div style="display:flex;gap:6px;flex-wrap:wrap">';
                foreach(array('approve_field'=>'✓ Übernehmen','reject_field'=>'✕ Ablehnen') as $decision=>$label){echo '<form method="post" action="'.esc_url(admin_url('admin-post.php')).'">';wp_nonce_field('rg_place_contribution_review');echo '<input type="hidden" name="action" value="rg_place_contribution_review"><input type="hidden" name="submission_id" value="'.intval($sub['id']).'"><input type="hidden" name="field_name" value="'.esc_attr($field).'"><input type="hidden" name="decision" value="'.esc_attr($decision).'"><button class="button button-small" type="submit">'.esc_html($label).'</button></form>';}
                echo '</div></td></tr>';
            }
            echo '</tbody></table></div>';
        }
        echo '</div>';
    }

    private function media_admin_has_filter() {
        foreach(array('media_search','media_source','media_status','media_category','media_relation','media_content') as $key)if(isset($_GET[$key]) && trim((string)$_GET[$key])!=='')return true;return false;
    }

    public function render_rp_editor_media_page() {
        if(!current_user_can('manage_options'))wp_die('Keine Berechtigung.');
        global $wpdb;
        $pending=$this->pending_place_media_submissions(200);$focus=absint($_GET['submission_id']??0);
        if($focus)usort($pending,function($a,$b)use($focus){return ((int)$a['submission_id']===$focus?-1:0)<=>((int)$b['submission_id']===$focus?-1:0);});
        echo '<div class="wrap"><h1>RP Redaktion · Medien</h1><p>Standardmäßig siehst du nur neu eingereichte Bilder, die noch nicht freigegeben oder abgelehnt wurden. Der bestehende Medienbestand wird erst nach einer gezielten Suche geladen.</p>';
        echo '<p><a class="button" href="'.esc_url(add_query_arg(array('page'=>'rp-redaktion'),admin_url('admin.php'))).'">← Zu Daten</a></p>';
        if(!empty($_GET['rg_media_reviewed']))echo '<div class="notice notice-success inline"><p>Bildentscheidung gespeichert.</p></div>';
        echo '<h2>Neue Bilder zur Freigabe</h2>';
        if(!$pending){echo '<div style="max-width:1100px;background:#fff;border:1px solid #dcdcde;border-radius:8px;padding:18px"><strong>Keine neuen Bilder zur Freigabe.</strong></div>';}
        else{echo '<div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(280px,1fr));gap:12px;max-width:1200px">';foreach($pending as $m){$payload=json_decode((string)($m['parent_payload_json']??''),true);$cat=is_array($payload)?(string)($payload['category']??''):'';$data_count=$this->submission_pending_data_count((int)$m['submission_id']);
            echo '<div style="background:#fff;border:'.($focus && (int)$m['submission_id']===$focus?'2px solid #2271b1':'1px solid #dcdcde').';border-radius:8px;padding:12px"><div style="aspect-ratio:16/10;background:#f0f0f1;border-radius:6px;overflow:hidden"><img src="'.esc_url($m['file_url']).'" alt="" style="width:100%;height:100%;object-fit:cover"></div>';
            $parent=$wpdb->get_row($wpdb->prepare("SELECT submitter_name,submitter_email,email_verified_at FROM ".$this->table('place_override_submissions')." WHERE id=%d",(int)$m['submission_id']),ARRAY_A);
            echo '<p style="margin:10px 0 4px"><strong>'.esc_html($m['place_name']?:('#'.$m['place_id'])).'</strong> · '.esc_html($m['city']??'').'</p><p style="margin:4px 0;color:#646970">'.esc_html($this->contribution_category_label($cat)).' · Einsendung #'.intval($m['submission_id']).'</p>'.($cat==='night'?'<p style="margin:4px 0"><span style="display:inline-block;background:#111827;color:#fff;padding:3px 8px;border-radius:999px;font-size:11px;font-weight:700">🌙 Nachtfoto</span></p>':'').'<p style="margin:4px 0"><strong>Copyright:</strong> '.esc_html($m['copyright_text']).'</p>'.(!empty($m['source_url'])?'<p style="margin:4px 0"><a href="'.esc_url($m['source_url']).'" target="_blank" rel="noopener noreferrer">Quelle / Website ↗</a></p>':'').'<p style="margin:4px 0"><strong>Einreicher:</strong> '.esc_html($parent['submitter_name']??'').' · '.esc_html($parent['submitter_email']??'').'</p><p style="margin:4px 0;color:#2271b1"><strong>E-Mail bestätigt:</strong> '.esc_html($parent['email_verified_at']??'').'</p><p style="margin:4px 0;color:#646970;font-size:12px">'.esc_html($m['original_name']).' · '.esc_html($m['created_at']).'</p><p><a class="button" target="_blank" href="'.esc_url(wp_nonce_url(admin_url('admin-post.php?action=rg_place_rights_dossier&submission_id='.(int)$m['submission_id']),'rg_place_rights_dossier_'.(int)$m['submission_id'])).'">Rechteakte anzeigen</a></p>';
            if($data_count)echo '<p><a href="'.esc_url(add_query_arg(array('page'=>'rp-redaktion'),admin_url('admin.php'))).'">Einsendung enthält zusätzlich '.intval($data_count).' offene Datenänderung'.($data_count===1?'':'en').' →</a></p>';
            echo '<div style="display:flex;gap:6px;flex-wrap:wrap">';foreach(array('approve'=>'✓ Bild freigeben','reject'=>'✕ Bild ablehnen') as $decision=>$label){echo '<form method="post" action="'.esc_url(admin_url('admin-post.php')).'">';wp_nonce_field('rg_place_media_submission_review');echo '<input type="hidden" name="action" value="rg_place_media_submission_review"><input type="hidden" name="media_submission_id" value="'.intval($m['id']).'"><input type="hidden" name="decision" value="'.esc_attr($decision).'"><button class="button button-small" type="submit">'.esc_html($label).'</button></form>'; }echo '</div></div>'; }echo '</div>';}
        $this->render_rp_media_crop_editor_v101112();
        echo '<hr style="margin:32px 0"><h2 id="rg-media-library">Medienbestand durchsuchen</h2><p>Hier wird <strong>nichts automatisch geladen</strong>. Setze mindestens einen Filter, z. B. <em>Kultur + manuell hinzugefügt</em>.</p>';
        $this->render_rp_media_library();echo '</div>';
    }


    /** 1.10.122: resolve the same active crop payload used by visitor responses. */
    private function render_rp_media_library() {
        $media_filters=$this->place_media_admin_filters();$has_filter=$this->media_admin_has_filter();$media_sources=$this->place_media_sources();
        echo '<form method="get" action="'.esc_url(admin_url('admin.php')).'#rg-media-library" style="display:flex;gap:8px;flex-wrap:wrap;align-items:end;max-width:1200px;background:#fff;border:1px solid #dcdcde;padding:12px;border-radius:8px">';
        echo '<input type="hidden" name="page" value="rp-redaktion-medien">';
        echo '<label style="min-width:260px;flex:1"><strong>Suche</strong><br><input class="regular-text" style="width:100%" type="search" name="media_search" value="'.esc_attr($media_filters['search']).'" placeholder="Event, Veranstaltungsort, Location, Urheber, Copyright, Bild-ID …"></label>';
        echo '<label><strong>Kategorie</strong><br><select name="media_category"><option value="">Alle Kategorien</option>';foreach(array('food'=>'Food','highlights'=>'Highlights','culture'=>'Kultur','activities'=>'Aktivitäten') as $k=>$label)echo '<option value="'.esc_attr($k).'" '.selected($media_filters['category'],$k,false).'>'.esc_html($label).'</option>';echo '</select></label>';
        echo '<label><strong>Medientyp</strong><br><select name="media_relation"><option value="">Alle Bilder</option><option value="place" '.selected($media_filters['relation'],'place',false).'>Normale Ortsbilder</option><option value="night" '.selected($media_filters['relation'],'night',false).'>Nachtfotos</option></select></label>';
        echo '<label><strong>Bildinhalt</strong><br><select name="media_content"><option value="">Alle Inhalte</option><option value="text_any" '.selected($media_filters['content'],'text_any',false).'>Text oder Bild + Text</option><option value="mixed" '.selected($media_filters['content'],'mixed',false).'>Bild + Text</option><option value="text" '.selected($media_filters['content'],'text',false).'>Überwiegend Text / Plakat</option><option value="image" '.selected($media_filters['content'],'image',false).'>Nur Bild / Foto</option><option value="unknown" '.selected($media_filters['content'],'unknown',false).'>Noch nicht analysiert</option></select></label>';
        echo '<label><strong>Herkunft</strong><br><select name="media_source"><option value="">Alle Quellen</option><option value="community_upload" '.selected($media_filters['source'],'community_upload',false).'>manuell / Community</option>';foreach($media_sources as $source){if($source==='community_upload')continue;echo '<option value="'.esc_attr($source).'" '.selected($media_filters['source'],$source,false).'>'.esc_html($source).'</option>';}echo '</select></label>';
        echo '<label><strong>Status</strong><br><select name="media_status"><option value="">beliebig</option>';foreach(array('active'=>'Aktiv / sichtbar','disabled'=>'Deaktiviert') as $k=>$label)echo '<option value="'.esc_attr($k).'" '.selected($media_filters['status'],$k,false).'>'.esc_html($label).'</option>';echo '</select></label>';
        echo '<button class="button button-primary" type="submit">Medien suchen</button><a class="button" href="'.esc_url(add_query_arg(array('page'=>'rp-redaktion-medien'),admin_url('admin.php'))).'#rg-media-library">Zurücksetzen</a></form>';
        if(!$has_filter){echo '<p><em>Kein Filter gesetzt – deshalb werden keine Bestandsbilder geladen.</em></p>';return;}
