        $strong=$this->event_auto_visual_decision_v101110($m)!=='';
        if($strong || ($score>=0.72 && $edges>=0.055))$class='text';
        elseif($score>=0.48 || ($edges>=0.085 && $bimodal>=0.20))$class='mixed';
        else $class='image';
        return array('class'=>$class,'score'=>round($score,4),'reason'=>'heuristic-v101112','metrics'=>$m);
    }

    public function cron_place_media_text_classify_tick_v101112() {
        global $wpdb;$media=$this->table('place_media');$eventMedia=$this->table('event_media');$now=current_time('mysql');$processed=0;$counts=array('image'=>0,'mixed'=>0,'text'=>0,'unavailable'=>0);
        $placeRows=(array)$wpdb->get_results("SELECT id,url,source,source_url,artist,credit,'' AS local_path FROM $media WHERE media_type='image' AND content_class='unknown' ORDER BY id ASC LIMIT 6",ARRAY_A);
        $eventRows=(array)$wpdb->get_results("SELECT id,url,source,source_url,artist,credit,local_path FROM $eventMedia WHERE media_type='image' AND content_class='unknown' AND local_cache_status='ready' AND local_path<>'' ORDER BY id ASC LIMIT 6",ARRAY_A);
        foreach(array(array($media,$placeRows),array($eventMedia,$eventRows)) as $bucket){$table=$bucket[0];foreach($bucket[1] as $row){$result=$this->place_media_content_classify_v101112($row);$class=in_array((string)$result['class'],array('image','mixed','text','unavailable'),true)?(string)$result['class']:'unavailable';$update=array('content_class'=>$class,'content_text_score'=>(float)($result['score']??0),'content_class_reason'=>substr((string)($result['reason']??''),0,190),'content_classified_at'=>$now);$formats=array('%s','%f','%s','%s');if($table===$media && $class!=='unavailable'){$update['last_seen_at']=$now;$formats[]='%s';}$wpdb->update($table,$update,array('id'=>(int)$row['id']),$formats,array('%d'));$processed++;$counts[$class]++;}}
        $remainingPlace=(int)$wpdb->get_var("SELECT COUNT(*) FROM $media WHERE media_type='image' AND content_class='unknown'");$remainingEvent=(int)$wpdb->get_var("SELECT COUNT(*) FROM $eventMedia WHERE media_type='image' AND content_class='unknown' AND local_cache_status='ready' AND local_path<>''");$remaining=$remainingPlace+$remainingEvent;update_option(self::PLACE_MEDIA_TEXT_CLASSIFY_STATE,array('updated_at'=>$now,'processed_last'=>$processed,'remaining'=>$remaining,'remaining_place'=>$remainingPlace,'remaining_event'=>$remainingEvent,'counts_last'=>$counts),false);
        if($remaining>0 && !wp_next_scheduled(self::PLACE_MEDIA_TEXT_CLASSIFY_HOOK))wp_schedule_single_event(time()+25,self::PLACE_MEDIA_TEXT_CLASSIFY_HOOK);
    }

    private function municipality_admin_rows() {
        global $wpdb;
        $table = $this->table('places_municipalities');
        return (array) $wpdb->get_results(
            "SELECT slug,name,status,raw_count,imported_count,attempts,last_error,locked_until,last_synced_at,updated_at
             FROM $table
             ORDER BY name ASC",
            ARRAY_A
        );
    }

    private function admin_status_label($status) {
        $status = (string) $status;
        $labels = array(
            'complete' => '✓ fertig',
            'in_progress' => '↻ läuft',
            'pending' => '… ausstehend',
            'failed' => '✕ fehlgeschlagen',
        );
        return isset($labels[$status]) ? $labels[$status] : $status;
    }

    private function adapter_test_query($body) {
        return "[out:json][timeout:15];\n(\n" . $body . "\n);\nout center 1500;";
    }

