    private function places_workspace_section_v1077() {
        $section=sanitize_key((string)($_GET['rg_section']??'places'));
        return in_array($section,array('places','buedchen','imbiss'),true)?$section:'places';
    }

    private function places_workspace_url_v1077($section='places',$args=array()) {
        $section=in_array($section,array('places','buedchen','imbiss'),true)?$section:'places';
        return add_query_arg(array_merge(array('page'=>'rp-places','rg_section'=>$section),$args),admin_url('admin.php'));
    }

    private function places_workspace_search_v1077($section,$query='',$category='') {
        global $wpdb;$places=$this->table('places');$wurst=$this->table('wurst_candidates');
        $query=trim((string)$query);$category=sanitize_key((string)$category);$params=array();
        if($section==='buedchen'){
            $where="p.active=1 AND p.primary_category='buedchen'";
            $join='';
            $select="p.id,p.name,p.city,p.street,p.house_number,p.primary_category,p.opening_hours,p.website,p.raw_tags";
        }elseif($section==='imbiss'){
            $where="p.active=1";$join=" INNER JOIN $wurst w ON w.place_id=p.id ";
            $select="p.id,p.name,p.city,p.street,p.house_number,p.primary_category,p.opening_hours,p.website,p.raw_tags,w.tier,w.score,w.review_status,w.public_eligible";
        }else{
            $where="p.active=1 AND p.lifecycle_status='active' AND p.primary_category IN ('food','highlights','culture','activities') AND NOT EXISTS (SELECT 1 FROM $wurst wx WHERE wx.place_id=p.id)";
            $join='';$select="p.id,p.name,p.city,p.street,p.house_number,p.primary_category,p.opening_hours,p.website,p.raw_tags";
            if(in_array($category,array('food','highlights','culture','activities'),true)){$where.=" AND p.primary_category=%s";$params[]=$category;}
        }
        if($query!==''){$like='%'.$wpdb->esc_like($query).'%';$where.=" AND (p.name LIKE %s OR p.city LIKE %s OR p.street LIKE %s)";array_push($params,$like,$like,$like);}
        if($section==='places' && $query==='') return array();
        $order=$section==='imbiss'?"w.public_eligible DESC,CASE w.tier WHEN 'A' THEN 0 WHEN 'B' THEN 1 WHEN 'U' THEN 2 ELSE 3 END,p.city,p.name":"p.city,p.name";
        $sql="SELECT $select FROM $places p $join WHERE $where ORDER BY $order LIMIT 120";
        return (array)$wpdb->get_results($params?$wpdb->prepare($sql,$params):$sql,ARRAY_A);
    }

    private function render_places_workspace_tabs_v1077($active) {
        $tabs=array('places'=>'Places','buedchen'=>'Büdchen','imbiss'=>'Imbiss');
        echo '<nav class="rg-place-admin-tabs" aria-label="Place-Bereiche">';
        foreach($tabs as $key=>$label){$cls=$active===$key?'rg-place-admin-tab is-active':'rg-place-admin-tab';echo '<a class="'.esc_attr($cls).'" href="'.esc_url($this->places_workspace_url_v1077($key)).'">'.esc_html($label).'</a>';}
        echo '</nav>';
    }

    private function render_place_image_pool_v1077($place_id,$section) {
        global $wpdb;$manual_media=$this->place_editorial_media_rows_v1076($place_id,true);
        $auto_media=$wpdb->get_row($wpdb->prepare("SELECT * FROM {$this->table('place_media')} WHERE place_id=%d AND media_type='image' AND relation_type='place' AND moderation_status='active' AND source<>'editorial-place-upload' ORDER BY is_primary DESC,identity_confidence DESC,visual_quality DESC,id ASC LIMIT 1",$place_id),ARRAY_A);
        echo '<section class="rg-admin-card"><h2 style="margin-top:0">Ortsbilder</h2>';
        if(!empty($_GET['rg_media_saved']))echo '<div class="notice notice-success inline"><p>Ortsbilder aktualisiert.</p></div>';
        echo '<p>Mehrere freigegebene Bilder können für diesen Ort hinterlegt werden. Normale Places verwenden sie im Detail-Slider; Events ohne eigenes Eventbild erhalten weiterhin genau ein stabiles Einzelbild aus diesem Pool.</p>';
        if($auto_media){echo '<div class="rg-auto-image"><img src="'.esc_url((string)$auto_media['url']).'" alt=""><div><strong>Automatisches Ortsbild im Hintergrund</strong><br><span class="description">'.esc_html((string)$auto_media['source']).' · bleibt gespeichert und kann jederzeit wieder aktiviert werden.</span></div></div>';}
        if($manual_media){
            echo '<details class="rg-admin-details"><summary>Vorhandene manuelle Ortsbilder ('.number_format_i18n(count($manual_media)).')</summary><div class="rg-image-grid">';
            foreach($manual_media as $mm){$active=(string)$mm['moderation_status']==='active';echo '<article class="rg-image-card"'.(!$active?' style="opacity:.58"':'').'>';
                echo '<img src="'.esc_url($mm['url']).'" alt=""><p><strong>'.(!empty($mm['is_primary'])?'★ Hauptbild':'Ortsbild').'</strong> · '.($active?'aktiv':'deaktiviert').'</p>';
                echo '<form method="post" action="'.esc_url(admin_url('admin-post.php')).'">';wp_nonce_field('rg_places_manage_media_v1076');echo '<input type="hidden" name="action" value="rg_places_manage_media_v1076"><input type="hidden" name="place_id" value="'.intval($place_id).'"><input type="hidden" name="media_id" value="'.intval($mm['id']).'"><input type="hidden" name="media_action" value="update_meta"><input type="hidden" name="return_page" value="rp-places"><input type="hidden" name="rg_section" value="'.esc_attr($section).'">';
                echo '<p><label>Credit<br><input class="widefat" name="credit" required value="'.esc_attr((string)$mm['credit']).'"></label></p><p><label>Urheber/Fotograf<br><input class="widefat" name="artist" value="'.esc_attr((string)$mm['artist']).'"></label></p><p><label>Lizenz / Nutzungsgrundlage<br><input class="widefat" name="license" required value="'.esc_attr((string)$mm['license']).'"></label></p><p><label>Quell-URL<br><input class="widefat" type="url" name="source_url" value="'.esc_attr((string)$mm['source_url']).'"></label></p><button class="button button-small" type="submit">Metadaten speichern</button></form>';
                echo '<div class="rg-inline-actions">';if($active&&!$mm['is_primary']){echo '<form method="post" action="'.esc_url(admin_url('admin-post.php')).'">';wp_nonce_field('rg_places_manage_media_v1076');echo '<input type="hidden" name="action" value="rg_places_manage_media_v1076"><input type="hidden" name="place_id" value="'.intval($place_id).'"><input type="hidden" name="media_id" value="'.intval($mm['id']).'"><input type="hidden" name="media_action" value="set_primary"><input type="hidden" name="return_page" value="rp-places"><input type="hidden" name="rg_section" value="'.esc_attr($section).'"><button class="button button-primary button-small">Als Hauptbild</button></form>';}
                echo '<form method="post" action="'.esc_url(admin_url('admin-post.php')).'">';wp_nonce_field('rg_places_manage_media_v1076');echo '<input type="hidden" name="action" value="rg_places_manage_media_v1076"><input type="hidden" name="place_id" value="'.intval($place_id).'"><input type="hidden" name="media_id" value="'.intval($mm['id']).'"><input type="hidden" name="media_action" value="'.($active?'disable':'reactivate').'"><input type="hidden" name="return_page" value="rp-places"><input type="hidden" name="rg_section" value="'.esc_attr($section).'"><button class="button button-small">'.($active?'Deaktivieren':'Reaktivieren').'</button></form></div></article>';
            }
            echo '</div></details>';
        }
        echo '<h3>Neue Ortsbilder hinzufügen</h3><form method="post" action="'.esc_url(admin_url('admin-post.php')).'" id="rg-place-media-upload-v1076">';wp_nonce_field('rg_places_upload_media_v1076');
        echo '<input type="hidden" name="action" value="rg_places_upload_media_v1076"><input type="hidden" name="place_id" value="'.intval($place_id).'"><input type="hidden" name="return_page" value="rp-places"><input type="hidden" name="rg_section" value="'.esc_attr($section).'"><input type="hidden" name="attachment_ids" id="rg-place-media-attachment-ids" value="">';
        echo '<p><button type="button" class="button button-primary" id="rg-place-media-picker">Bilder auswählen / hochladen</button> <span id="rg-place-media-selection" class="description">Noch keine Bilder ausgewählt.</span></p><div class="rg-meta-grid"><label><strong>Credit *</strong><input class="regular-text" required name="credit" placeholder="z. B. © Max Mustermann / RuhrpottGuru"></label><label><strong>Urheber/Fotograf</strong><input class="regular-text" name="artist"></label><label><strong>Lizenz / Nutzungsgrundlage *</strong><input class="regular-text" required name="license" placeholder="z. B. Eigenes Foto / CC BY-SA 4.0"></label><label><strong>Quell-URL</strong><input class="regular-text" type="url" name="source_url" placeholder="optional"></label></div><p><button class="button button-primary" type="submit">Ausgewählte Ortsbilder übernehmen</button></p></form>';
        if(array_filter($manual_media,function($x){return (string)$x['moderation_status']==='active';})){echo '<form method="post" action="'.esc_url(admin_url('admin-post.php')).'" onsubmit="return confirm(\'Manuellen Ortsbild-Pool deaktivieren und automatische Bilder wieder verwenden?\')">';wp_nonce_field('rg_places_manage_media_v1076');echo '<input type="hidden" name="action" value="rg_places_manage_media_v1076"><input type="hidden" name="place_id" value="'.intval($place_id).'"><input type="hidden" name="media_id" value="'.intval($manual_media[0]['id']).'"><input type="hidden" name="media_action" value="restore_auto"><input type="hidden" name="return_page" value="rp-places"><input type="hidden" name="rg_section" value="'.esc_attr($section).'"><button class="button">Automatische Bilder wieder verwenden</button></form>';}
        echo '</section>';
        echo '<script>(function(){const b=document.getElementById("rg-place-media-picker"),ids=document.getElementById("rg-place-media-attachment-ids"),label=document.getElementById("rg-place-media-selection");if(!b||!window.wp||!wp.media)return;let frame;b.addEventListener("click",function(e){e.preventDefault();if(frame){frame.open();return;}frame=wp.media({title:"Ortsbilder auswählen",button:{text:"Bilder übernehmen"},library:{type:"image"},multiple:true});frame.on("select",function(){const sel=frame.state().get("selection").toJSON();ids.value=sel.map(x=>x.id).join(",");label.textContent=sel.length+" Bild"+(sel.length===1?"":"er")+" ausgewählt";});frame.open();});})();</script>';
    }

    private function render_place_editor_v1077($place_id,$section) {
        global $wpdb;$places=$this->table('places');$place=$wpdb->get_row($wpdb->prepare("SELECT * FROM $places WHERE id=%d",(int)$place_id),ARRAY_A);if(!$place){echo '<div class="notice notice-error"><p>Place nicht gefunden.</p></div>';return;}
        $orow=$this->override_row($place_id);$odata=$this->decode_override_data($orow?:'');
