        echo '<p>Nur ausgefüllte Felder überschreiben die Importdaten. Leere Felder fallen auf Import/OSM zurück.</p><form method="post" action="'.esc_url(admin_url('admin-post.php')).'">';wp_nonce_field('rg_places_save_override');
        echo '<input type="hidden" name="action" value="rg_places_save_override"><input type="hidden" name="place_id" value="'.intval($place_id).'"><input type="hidden" name="return_page" value="rp-places"><input type="hidden" name="rg_section" value="'.esc_attr($section).'">';
        echo '<table class="form-table"><tbody>';$editable=array('name'=>'Name','street'=>'Straße','house_number'=>'Hausnummer','postcode'=>'PLZ','city'=>'Ort','phone'=>'Telefon','website'=>'Website','opening_hours'=>'Öffnungszeiten (OSM-Syntax)','instagram'=>'Instagram','description'=>'Kurzbeschreibung');
        foreach($editable as $field=>$label){$value=$this->override_field_value($odata,$field,'');echo '<tr><th><label>'.esc_html($label).'</label></th><td>';if(in_array($field,array('opening_hours','description'),true))echo '<textarea class="large-text" rows="3" name="fields['.esc_attr($field).']">'.esc_textarea($value).'</textarea>';else echo '<input class="regular-text" type="text" name="fields['.esc_attr($field).']" value="'.esc_attr($value).'">';$base=isset($place[$field])?(string)$place[$field]:'';if($base!=='')echo '<p class="description">Import: '.esc_html($base).'</p>';echo '</td></tr>';}
        echo '<tr><th>Quelle</th><td><select name="source_type">';foreach(array('editorial'=>'RuhrpottGuru Redaktion','operator'=>'Betreiber bestätigt','official'=>'Offizielle Quelle') as $k=>$label)echo '<option value="'.esc_attr($k).'" '.selected(($orow['source_type']??'editorial'),$k,false).'>'.esc_html($label).'</option>';echo '</select> <input class="regular-text" type="text" name="source_label" value="'.esc_attr($orow['source_label']??'RuhrpottGuru Redaktion').'" placeholder="z. B. Betreiber telefonisch bestätigt"></td></tr></tbody></table>';
        if($section==='buedchen' || (string)$place['primary_category']==='buedchen'){
            echo '<h3>Büdchen-Merkmale</h3><div class="rg-feature-grid">';$features=array('mixed_candy'=>'Gemischte Tüte','coffee'=>'Kaffee','sandwiches'=>'Belegte Brötchen','seating'=>'Sitzgelegenheiten','lottery'=>'Lotto','parcel_shop'=>'Paketshop','tobacco'=>'Tabak','late_night'=>'Spät geöffnet');foreach($features as $key=>$label){$current=array_key_exists($key,$odata['features'])?($odata['features'][$key]?'yes':'no'):'unknown';echo '<label><strong>'.esc_html($label).'</strong><br><select name="features['.esc_attr($key).']"><option value="unknown" '.selected($current,'unknown',false).'>unbekannt</option><option value="yes" '.selected($current,'yes',false).'>ja</option><option value="no" '.selected($current,'no',false).'>nein</option></select></label>'; }echo '</div>';
        }
        submit_button('Redaktionelle Daten speichern');echo '</form></div></details>';
    }

    /**
     * Places 1.10.80 final acceptance: real visitor feeds from representative
     * Ruhr cities plus the non-destructive historical refresh state. No web
     * lookup is required here; this deliberately validates the exact stored
     * inventory and the same read-time intelligence used by the frontend.
     */
    private function places_quality_refresh_state_v1080() {
        global $wpdb;
        $municipalities=$this->table('places_municipalities');
        $places=$this->table('places');
        $sources=$this->table('place_sources');
        $started=(string)get_option('rg_places_quality_refresh_started_at','');
        $completed=0;$remaining=0;$stale_core=0;
        if($started!==''){
            $completed=(int)$wpdb->get_var($wpdb->prepare(
                "SELECT COUNT(*) FROM $municipalities WHERE status='complete' AND last_synced_at IS NOT NULL AND last_synced_at >= %s",
                $started
            ));
            $remaining=max(0,53-$completed);
            // Only judge stale core rows in municipalities that have already
            // completed this exact 1.10.80 wave. Their public core must have been
            // touched by the current primary source or by the reconciliation.
            $stale_core=(int)$wpdb->get_var($wpdb->prepare(
                "SELECT COUNT(*)
                 FROM $places p
                 INNER JOIN $municipalities m ON m.slug=p.municipality_slug
                 LEFT JOIN $sources ps ON ps.place_id=p.id AND ps.source_type='osm'
                      AND ps.osm_type=p.primary_osm_type AND ps.osm_id=p.primary_osm_id
                 WHERE p.active=1 AND p.lifecycle_status='active'
                   AND m.status='complete' AND m.last_synced_at IS NOT NULL AND m.last_synced_at >= %s
                   AND (ps.id IS NULL OR p.last_synced_at IS NULL OR p.last_synced_at < %s)",
                $started,$started
            ));
        }
        $active_lifecycle_mismatch=(int)$wpdb->get_var(
            "SELECT COUNT(*) FROM $places WHERE active=1 AND lifecycle_status<>'active'"
        );
        return array(
            'startedAt'=>$started,'completed'=>$completed,'remaining'=>$remaining,
            'staleCore'=>$stale_core,'activeLifecycleMismatch'=>$active_lifecycle_mismatch
        );
    }

    /**
     * 1.10.127 – read-only catalogue-wide quality audit for the 53 municipalities.
     * No external requests and no writes. Activities V2 is deliberately inventory-only.
     */
    private function places_quality_53_audit_v101127() {
        global $wpdb;
        $places=$this->table('places');$municipalities=$this->table('places_municipalities');$media=$this->table('place_media');$categories=$this->table('place_categories');
        $muniRows=(array)$wpdb->get_results("SELECT slug,name,status,last_synced_at FROM $municipalities ORDER BY name ASC",ARRAY_A);
        $bySlug=array();
        foreach($muniRows as $m){
            $slug=(string)$m['slug'];
            $bySlug[$slug]=array('slug'=>$slug,'name'=>(string)$m['name'],'sync_status'=>(string)$m['status'],'last_synced_at'=>(string)($m['last_synced_at']??''),'total'=>0,
                'cats'=>array('food'=>0,'highlights'=>0,'culture'=>0,'activities'=>0),'with_media'=>0,'media_pct'=>0.0,'with_symbolic_media'=>0,'symbolic_media_pct'=>0.0,
                'food_drift'=>0,'highlight_hidden'=>0,'highlight_drift'=>0,'culture_hidden'=>0,'culture_drift'=>0,'stolpersteine'=>0);
        }
        $officialSlugs=array_keys($bySlug);usort($officialSlugs,function($a,$b){return strlen($b)<=>strlen($a);});
        $samples=array('food_drift'=>array(),'highlight_hidden'=>array(),'highlight_drift'=>array(),'culture_hidden'=>array(),'culture_drift'=>array(),'stolpersteine'=>array());
        $all=array('total'=>0,'with_media'=>0,'with_symbolic_media'=>0,'unmapped_municipality'=>0,'cats'=>array('food'=>0,'highlights'=>0,'culture'=>0,'activities'=>0),'food_drift'=>0,'highlight_hidden'=>0,'highlight_drift'=>0,'culture_hidden'=>0,'culture_drift'=>0,'stolpersteine'=>0);
        $lastId=0;$batchSize=800;
        do{
            $rows=(array)$wpdb->get_results($wpdb->prepare("SELECT p.id,p.name,p.city,p.municipality_slug,p.street,p.house_number,p.postcode,p.lat,p.lng,p.website,p.opening_hours,p.wikidata,p.wikipedia,p.primary_category,p.primary_subcategory,p.quality_score,p.raw_tags,p.lifecycle_status,p.active,(SELECT GROUP_CONCAT(DISTINCT c.category ORDER BY c.category SEPARATOR ',') FROM $categories c WHERE c.place_id=p.id AND c.category IN ('food','highlights','culture','activities')) AS _rg_categories,CASE WHEN EXISTS(SELECT 1 FROM $media m WHERE m.place_id=p.id AND m.media_type='image' AND m.relation_type='place' AND m.moderation_status='active' AND m.identity_confidence>=0.88) THEN 1 ELSE 0 END AS _rg_has_persisted_media,CASE WHEN EXISTS(SELECT 1 FROM $media ms WHERE ms.place_id=p.id AND ms.media_type='image' AND ms.relation_type='place' AND ms.moderation_status='active' AND ms.identity_confidence<0.88) THEN 1 ELSE 0 END AS _rg_has_symbolic_media FROM $places p WHERE p.active=1 AND p.lifecycle_status='active' AND EXISTS(SELECT 1 FROM $categories cx WHERE cx.place_id=p.id AND cx.category IN ('food','highlights','culture','activities')) AND p.id>%d ORDER BY p.id ASC LIMIT %d",$lastId,$batchSize),ARRAY_A);
            foreach($rows as $row){
                $lastId=max($lastId,(int)$row['id']);
            $rawSlug=sanitize_title((string)($row['municipality_slug']??''));$slug=$rawSlug;
            if(!isset($bySlug[$slug])){
                $citySlug=sanitize_title((string)($row['city']??''));
                if($citySlug!=='' && isset($bySlug[$citySlug]))$slug=$citySlug;
                else{foreach($officialSlugs as $candidate){if($rawSlug!=='' && strpos($rawSlug,$candidate.'-')===0){$slug=$candidate;break;}}}
            }
            if(!isset($bySlug[$slug])){$all['unmapped_municipality']++;continue;}
            $members=array_values(array_intersect(array_filter(array_map('trim',explode(',',(string)($row['_rg_categories']??'')))),array('food','highlights','culture','activities')));if(!$members){$fallback=(string)($row['primary_category']??'');if(in_array($fallback,array('food','highlights','culture','activities'),true))$members=array($fallback);}
            $tags=json_decode((string)($row['raw_tags']??''),true);if(!is_array($tags))$tags=array();
            $direct=!empty($row['_rg_has_persisted_media']);$symbolic=!empty($row['_rg_has_symbolic_media']);
            if(!$direct){foreach(array('image','image:url') as $key){$v=trim((string)($tags[$key]??''));if($v!==''&&(preg_match('#^(?:https?:)?//#i',$v)||preg_match('/\.(?:jpe?g|png|webp|gif|avif)(?:[?#].*)?$/i',$v))){$direct=true;break;}}}
            if(!$direct){$commons=trim((string)($tags['wikimedia_commons']??''));if($commons!==''&&(stripos($commons,'File:')!==false||stripos($commons,'Special:FilePath/')!==false||preg_match('/\.(?:jpe?g|png|webp|gif|avif)(?:[?#].*)?$/i',$commons)))$direct=true;}
            $bySlug[$slug]['total']++;$all['total']++;
            foreach($members as $cat){$bySlug[$slug]['cats'][$cat]++;$all['cats'][$cat]++;}
            if($direct){$bySlug[$slug]['with_media']++;$all['with_media']++;}
            elseif($symbolic){$bySlug[$slug]['with_symbolic_media']++;$all['with_symbolic_media']++;}
            $classified=$this->classify_tags($tags,(string)$row['name']);$current=(string)($classified['category']??'');
            $sample=function($key,$reason) use (&$samples,$row,$slug){if(count($samples[$key])<25)$samples[$key][]=array('id'=>(int)$row['id'],'name'=>(string)$row['name'],'city'=>(string)$row['city'],'slug'=>$slug,'reason'=>$reason);};
            if(in_array('food',$members,true) && $current!=='food'){$bySlug[$slug]['food_drift']++;$all['food_drift']++;$sample('food_drift','aktueller Classifier: '.($current!==''?$current:'kein Treffer'));}
            if(in_array('highlights',$members,true)){
                if($current!=='highlights'){$bySlug[$slug]['highlight_drift']++;$all['highlight_drift']++;$sample('highlight_drift','aktueller Classifier: '.($current!==''?$current:'kein Treffer'));}
                if($this->highlight_experience_profile($row)===null){$bySlug[$slug]['highlight_hidden']++;$all['highlight_hidden']++;$sample('highlight_hidden','besteht aktuelle Highlight-Visitor-Intelligence nicht');}
            }
            if(in_array('culture',$members,true)){
                $stolper=$this->is_stolperstein_row($row);
                if($stolper){$bySlug[$slug]['stolpersteine']++;$all['stolpersteine']++;$sample('stolpersteine','bewusst aus öffentlichem Kulturfeed gefiltert');}
                if($current!=='culture'){$bySlug[$slug]['culture_drift']++;$all['culture_drift']++;$sample('culture_drift','aktueller Classifier: '.($current!==''?$current:'kein Treffer'));}
                if($this->culture_experience_profile($row)===null){$bySlug[$slug]['culture_hidden']++;$all['culture_hidden']++;if(!$stolper)$sample('culture_hidden','besteht aktuelle Kultur-Visitor-Intelligence nicht');}
            }
            // Activities V2 is intentionally not re-evaluated here; membership and media are counted only.
            }
        }while(count($rows)===$batchSize);
        foreach($bySlug as &$m){$m['media_pct']=$m['total']>0?round(100*$m['with_media']/$m['total'],1):0.0;$m['symbolic_media_pct']=$m['total']>0?round(100*$m['with_symbolic_media']/$m['total'],1):0.0;}unset($m);
        $all['media_pct']=$all['total']>0?round(100*$all['with_media']/$all['total'],1):0.0;$all['symbolic_media_pct']=$all['total']>0?round(100*$all['with_symbolic_media']/$all['total'],1):0.0;
        $mediaState=array('total'=>0,'unknown'=>0,'image'=>0,'mixed'=>0,'text'=>0,'unavailable'=>0);
        $mediaColumns=(array)$wpdb->get_col("SHOW COLUMNS FROM $media",0);
        $eventsTable=$this->table('events');$eventColumns=(array)$wpdb->get_col("SHOW COLUMNS FROM $eventsTable",0);
        $mediaRowsTotal=(int)$wpdb->get_var("SELECT COUNT(*) FROM $media WHERE media_type='image' AND relation_type='place'");
        $mediaRowsActive=(int)$wpdb->get_var("SELECT COUNT(*) FROM $media WHERE media_type='image' AND relation_type='place' AND moderation_status='active'");
        $mediaActivePlaces=(int)$wpdb->get_var("SELECT COUNT(DISTINCT place_id) FROM $media WHERE media_type='image' AND relation_type='place' AND moderation_status='active'");
        $mediaQueryError='';
        if(in_array('content_class',$mediaColumns,true)){
            $mr=(array)$wpdb->get_results("SELECT content_class,COUNT(*) n FROM $media WHERE media_type='image' AND relation_type='place' AND moderation_status='active' GROUP BY content_class",ARRAY_A);
            $mediaQueryError=(string)$wpdb->last_error;
            foreach($mr as $x){$k=(string)$x['content_class'];$n=(int)$x['n'];$mediaState['total']+=$n;if(isset($mediaState[$k]))$mediaState[$k]+=$n;}
        }else{$mediaQueryError='content_class fehlt im place_media-Schema';}
        $schemaState=array(
            'schema_version'=>(string)get_option('rg_places_schema_version',''),
            'place_media_content_fields'=>count(array_intersect(array('content_class','content_text_score','content_class_reason','content_classified_at'),$mediaColumns))===4,
            'event_lifecycle_fields'=>count(array_intersect(array('source_status','missing_since','missing_count','last_source_run','last_missing_run'),$eventColumns))===5,
            'place_media_rows_total'=>$mediaRowsTotal,
            'place_media_rows_active'=>$mediaRowsActive,
            'place_media_active_places'=>$mediaActivePlaces,
            'place_media_invalid_relation_rows'=>(int)$wpdb->get_var("SELECT COUNT(*) FROM $media WHERE relation_type='' OR relation_type NOT IN ('place','contextual','night')"),
            'place_media_zero_visual_quality_rows'=>(int)$wpdb->get_var("SELECT COUNT(*) FROM $media WHERE visual_quality=0.0000"),
            'place_media_zero_last_seen_rows'=>(int)$wpdb->get_var("SELECT COUNT(*) FROM $media WHERE last_seen_at IS NULL OR last_seen_at='0000-00-00 00:00:00'"),
            'place_media_multi_primary_places'=>(int)$wpdb->get_var("SELECT COUNT(*) FROM (SELECT place_id FROM $media WHERE media_type='image' AND relation_type='place' AND moderation_status='active' AND is_primary=1 GROUP BY place_id HAVING COUNT(*)>1) mp"),
            'active_blank_primary_category'=>(int)$wpdb->get_var("SELECT COUNT(*) FROM $places WHERE active=1 AND primary_category=''"),
            'active_outside_nrw_guard'=>(int)$wpdb->get_var("SELECT COUNT(*) FROM $places WHERE active=1 AND (lat<50.20 OR lat>52.70 OR lng<5.70 OR lng>9.70)"),
            'place_media_contract_repair_v101129'=>(string)get_option('rg_place_media_contract_repair_v101129_done',''),
            'media_group_query_error'=>$mediaQueryError,
        );
        $lifecycle=(int)$wpdb->get_var("SELECT COUNT(*) FROM $places WHERE active=1 AND lifecycle_status<>'active'");
        $syncComplete=0;foreach($bySlug as $m){if($m['sync_status']==='complete')$syncComplete++;}
        return array('municipalities'=>array_values($bySlug),'all'=>$all,'samples'=>$samples,'media'=>$mediaState,'schema'=>$schemaState,'sync_complete'=>$syncComplete,'municipality_count'=>count($bySlug),'active_lifecycle_mismatch'=>$lifecycle,'unmapped_municipality'=>(int)$all['unmapped_municipality']);
    }

    private function render_places_quality_53_audit_v101127() {
        $a=$this->places_quality_53_audit_v101127();$all=$a['all'];$media=$a['media'];$schema=$a['schema']??array();
        echo '<section class="rg-admin-card" style="max-width:1250px"><h2 style="margin-top:0">Places-Abschlusscheck · 53 Kommunen</h2>';
        echo '<p><strong>Read-only:</strong> Dieser Report liest ausschließlich den aktuellen Katalog. Es werden keine Orte, Kategorien, Bilder, Worker, Imports oder Reprocessing-Jobs verändert. Activities V2 wird nur inventarisiert, nicht neu bewertet.</p>';
        echo '<div class="rg-count-cards">';
        foreach(array('Kommunen Sync komplett'=>(int)$a['sync_complete'].' / 53','aktive Places'=>(int)$all['total'],'belastbares Ortsbild'=>(int)$all['with_media'].' · '.number_format_i18n((float)$all['media_pct'],1).' %','nur Symbolbild'=>(int)$all['with_symbolic_media'].' · '.number_format_i18n((float)$all['symbolic_media_pct'],1).' %','Food Drift'=>(int)$all['food_drift'],'Highlights verborgen'=>(int)$all['highlight_hidden'],'Kultur verborgen'=>(int)$all['culture_hidden'],'Stolpersteine im Kultur-Altbestand'=>(int)$all['stolpersteine']) as $l=>$v)echo '<div class="rg-count-card"><small>'.esc_html($l).'</small><strong>'.esc_html((string)$v).'</strong></div>';
        echo '</div>';
        if((int)$a['active_lifecycle_mismatch']>0)echo '<p style="padding:9px 11px;background:#f7d4d4;border:1px solid #dba1a1;border-radius:7px"><strong>Prüfen:</strong> '.intval($a['active_lifecycle_mismatch']).' Places sind active=1, aber lifecycle_status ist nicht active.</p>';if((int)$a['unmapped_municipality']>0)echo '<p style="padding:9px 11px;background:#fff8df;border:1px solid #e0c968;border-radius:7px"><strong>Hinweis:</strong> '.intval($a['unmapped_municipality']).' aktive Places ließen sich keinem der 53 Kommunen-Slugs eindeutig zuordnen und wurden nicht in der Kommunentabelle gezählt.</p>';
        echo '<h3>Bild-/Inhaltsanalyse</h3><p>Aktive Place-Bilder: <strong>'.intval($media['total']).'</strong> · Foto: <strong>'.intval($media['image']).'</strong> · Bild+Text: <strong>'.intval($media['mixed']).'</strong> · Text/Plakat: <strong>'.intval($media['text']).'</strong> · nicht abrufbar: <strong>'.intval($media['unavailable']).'</strong> · noch nicht analysiert: <strong>'.intval($media['unknown']).'</strong>.</p>';
        echo '<div style="overflow:auto"><table class="widefat striped"><thead><tr><th>Kommune</th><th>Sync</th><th>Places</th><th>Food</th><th>Highlights</th><th>Kultur</th><th>Aktiv</th><th>Ortsbild</th><th>Symbolbild</th><th>Food Drift</th><th>Highlights verborgen / Drift</th><th>Kultur verborgen / Drift</th><th>Stolpersteine</th></tr></thead><tbody>';
        foreach($a['municipalities'] as $m){echo '<tr><td><strong>'.esc_html($m['name']).'</strong><br><code>'.esc_html($m['slug']).'</code></td><td>'.esc_html($m['sync_status']).'</td><td>'.intval($m['total']).'</td><td>'.intval($m['cats']['food']).'</td><td>'.intval($m['cats']['highlights']).'</td><td>'.intval($m['cats']['culture']).'</td><td>'.intval($m['cats']['activities']).'</td><td>'.intval($m['with_media']).' · '.esc_html(number_format_i18n((float)$m['media_pct'],1)).'%</td><td>'.intval($m['with_symbolic_media']).' · '.esc_html(number_format_i18n((float)$m['symbolic_media_pct'],1)).'%</td><td>'.intval($m['food_drift']).'</td><td>'.intval($m['highlight_hidden']).' / '.intval($m['highlight_drift']).'</td><td>'.intval($m['culture_hidden']).' / '.intval($m['culture_drift']).'</td><td>'.intval($m['stolpersteine']).'</td></tr>';}
        echo '</tbody></table></div>';
        $labels=array('food_drift'=>'Food · Classifier-Drift','highlight_hidden'=>'Highlights · Visitor-Intelligence blendet aus','highlight_drift'=>'Highlights · Classifier-Drift','culture_hidden'=>'Kultur · Visitor-Intelligence blendet aus','culture_drift'=>'Kultur · Classifier-Drift','stolpersteine'=>'Kultur · Stolpersteine bewusst ausgefiltert');
        foreach($labels as $key=>$label){$rows=$a['samples'][$key];if(!$rows)continue;echo '<details class="rg-admin-details"><summary>'.esc_html($label).' · Stichprobe '.intval(count($rows)).'</summary><div class="rg-result-table"><table class="widefat striped"><thead><tr><th>ID</th><th>Ort</th><th>Kommune</th><th>Grund</th><th></th></tr></thead><tbody>';foreach($rows as $r){$url=add_query_arg(array('page'=>'rp-places','rg_section'=>'places','edit_place'=>(int)$r['id']),admin_url('admin.php'));echo '<tr><td>#'.intval($r['id']).'</td><td><strong>'.esc_html($r['name']).'</strong></td><td>'.esc_html($r['city']).'</td><td>'.esc_html($r['reason']).'</td><td><a class="button button-small" href="'.esc_url($url).'">Öffnen</a></td></tr>'; }echo '</tbody></table></div></details>';}
        $diag=array('version'=>self::VERSION,'schema'=>$schema,'sync_complete'=>(int)$a['sync_complete'],'municipality_count'=>(int)$a['municipality_count'],'active_places'=>(int)$all['total'],'categories'=>$all['cats'],'media_verified'=>(int)$all['with_media'],'media_verified_pct'=>(float)$all['media_pct'],'media_symbolic'=>(int)$all['with_symbolic_media'],'media_symbolic_pct'=>(float)$all['symbolic_media_pct'],'place_media_analysis'=>$media,'food_drift'=>(int)$all['food_drift'],'highlight_hidden'=>(int)$all['highlight_hidden'],'highlight_drift'=>(int)$all['highlight_drift'],'culture_hidden'=>(int)$all['culture_hidden'],'culture_drift'=>(int)$all['culture_drift'],'stolpersteine'=>(int)$all['stolpersteine'],'active_lifecycle_mismatch'=>(int)$a['active_lifecycle_mismatch'],'unmapped_municipality'=>(int)$a['unmapped_municipality']);
        echo '<h3>Kompakte Diagnose für die Abschlussabnahme</h3><p>Den folgenden Block kannst du bei Bedarf komplett kopieren und hier in den Chat schicken.</p><textarea readonly style="width:100%;min-height:190px;font-family:monospace">'.esc_textarea(wp_json_encode($diag,JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES)).'</textarea>';
        echo '</section>';
    }

    private function places_final_quality_audit_v1080() {
        $centres=array(
            'Essen'=>array(51.4556,7.0116),
            'Dortmund'=>array(51.5136,7.4653),
            'Duisburg'=>array(51.4344,6.7623),
            'Bochum'=>array(51.4818,7.2162),
            'Oberhausen'=>array(51.4963,6.8638),
            'Wesel'=>array(51.6572,6.6186),
        );
        $rows=array();$counts=array('ok'=>0,'hint'=>0,'check'=>0);
        foreach($centres as $centre=>$coord){
            list($lat,$lng)=$coord;
            $feeds=array(
                'highlights'=>$this->nearby_highlight_experience_rows($lat,$lng,15,8),
                'culture'=>$this->nearby_rows('culture',$lat,$lng,15,8,'all'),
                'activities'=>$this->nearby_activity_experience_rows($lat,$lng,15,8),
            );
            foreach($feeds as $category=>$items){
                if(!$items){
                    $rows[]=array('status'=>'hint','centre'=>$centre,'category'=>$category,'name'=>'—','city'=>'—','distance'=>null,'bucket'=>'—','sourceCategory'=>'—','reason'=>'Im 15-km-Abnahmefenster kein qualifizierter öffentlicher Treffer.');
                    $counts['hint']++;continue;
                }
                $row=$items[0];$profile=null;$reason='Öffentlicher Besucherfeed besteht die Kategorie-Intelligence.';
                if($category==='culture')$profile=$this->culture_experience_profile($row);
                elseif($category==='activities')$profile=$this->activity_experience_profile($row,false);
                else $profile=$this->highlight_experience_profile($row);
                $status=$profile?'ok':'check';
                if(!$profile)$reason='Treffer wurde ausgeliefert, besteht aber die aktuelle Kategorie-Intelligence nicht.';
                if($category==='culture' && $this->is_stolperstein_row($row)){$status='check';$reason='Stolperstein ist in den öffentlichen Kulturfeed gelangt.';}
                if(!empty($row['lifecycle_status']) && (string)$row['lifecycle_status']!=='active'){$status='check';$reason='Nicht aktiver Lifecycle-Status ist öffentlich sichtbar.';}
                $bucket='';
                if($category==='culture')$bucket=(string)($row['_rg_culture_bucket']??($profile['bucket']??''));
                elseif($category==='activities')$bucket=(string)($row['_rg_activity_bucket']??($profile['bucket']??''));
                else $bucket=(string)($row['_rg_highlight_bucket']??($profile['bucket']??''));
                $rows[]=array(
                    'status'=>$status,'centre'=>$centre,'category'=>$category,
                    'name'=>(string)($row['name']??''),'city'=>(string)($row['city']??''),
                    'distance'=>isset($row['distance_km'])?(float)$row['distance_km']:null,
                    'bucket'=>$bucket!==''?$bucket:'—',
                    'sourceCategory'=>(string)($row['primary_category']??''),
                    'reason'=>$reason,
                );
                $counts[$status]++;
            }
        }
        $refresh=$this->places_quality_refresh_state_v1080();
        if((int)$refresh['activeLifecycleMismatch']>0){$counts['check']++;}
        elseif((int)$refresh['staleCore']>0){$counts['check']++;}
        elseif((int)$refresh['remaining']>0){$counts['hint']++;}
        else{$counts['ok']++;}
        return array('rows'=>$rows,'counts'=>$counts,'refresh'=>$refresh);
    }

    private function render_places_final_quality_audit_v1080() {
        $audit=$this->places_final_quality_audit_v1080();$c=$audit['counts'];$r=$audit['refresh'];
        $label=array('highlights'=>'Highlights','culture'=>'Kultur','activities'=>'Aktivitäten');
        echo '<section class="rg-admin-card" style="max-width:1150px"><h2 style="margin-top:0">Places-Finalcheck · Besucheransicht</h2>';
        echo '<p>Reale Besucherfeeds aus Essen, Dortmund, Duisburg, Bochum, Oberhausen und Wesel. Geprüft werden dieselben Highlight-, Kultur- und Aktivitäten-Resolver wie im Frontend. Bilder sind bewusst kein Sichtbarkeitskriterium.</p>';
        echo '<p><span style="display:inline-block;background:#d7f1dc;color:#0a6124;padding:5px 9px;border-radius:999px;font-weight:700">OK · '.intval($c['ok']).'</span> &nbsp; <span style="display:inline-block;background:#fff2c2;color:#735c00;padding:5px 9px;border-radius:999px;font-weight:700">Hinweis · '.intval($c['hint']).'</span> &nbsp; <span style="display:inline-block;background:#f7d4d4;color:#8a1f1f;padding:5px 9px;border-radius:999px;font-weight:700">Prüfen · '.intval($c['check']).'</span></p>';
        $wave_ok=((int)$r['remaining']===0 && (int)$r['staleCore']===0 && (int)$r['activeLifecycleMismatch']===0);
        echo '<div style="padding:10px 12px;border-radius:8px;margin:10px 0 16px;background:'.($wave_ok?'#eef8ef':'#fff8df').';border:1px solid '.($wave_ok?'#b8d8b8':'#e0c968').'">';
        echo '<strong>Altbestands-Refresh 1.10.80:</strong> '.intval($r['completed']).'/53 Kommunen abgeschlossen';
        if((int)$r['remaining']>0)echo ' · '.intval($r['remaining']).' noch automatisch offen';
        echo ' · stale Primary nach bereits aktualisierten Kommunen: <strong>'.intval($r['staleCore']).'</strong> · aktive Lifecycle-Widersprüche: <strong>'.intval($r['activeLifecycleMismatch']).'</strong>.';
        echo '</div>';
        echo '<div style="overflow:auto"><table class="widefat striped"><thead><tr><th>Status</th><th>Testzentrum</th><th>Kategorie</th><th>Treffer</th><th>Ort</th><th>Entf.</th><th>Intelligence</th><th>DB-Kategorie</th><th>Bewertung</th></tr></thead><tbody>';
        foreach($audit['rows'] as $row){
            $status=(string)$row['status'];$badge=$status==='ok'?'<span style="color:#087b24;font-weight:700">OK</span>':($status==='hint'?'<span style="color:#8a6a00;font-weight:700">Hinweis</span>':'<span style="color:#b32d2e;font-weight:700">Prüfen</span>');
            $distance=$row['distance']===null?'—':number_format_i18n((float)$row['distance'],1).' km';
            echo '<tr><td>'.$badge.'</td><td>'.esc_html($row['centre']).'</td><td>'.esc_html($label[$row['category']]??$row['category']).'</td><td><strong>'.esc_html($row['name']).'</strong></td><td>'.esc_html($row['city']).'</td><td>'.esc_html($distance).'</td><td>'.esc_html($row['bucket']).'</td><td>'.esc_html($row['sourceCategory']).'</td><td>'.esc_html($row['reason']).'</td></tr>';
        }
        echo '</tbody></table></div></section>';
    }

