                $tags=json_decode((string)$row['raw_tags'],true); if(!is_array($tags))$tags=array();

                echo '<tr>';
                echo '<td><input type="checkbox" class="rg-wurst-row-check" value="'.intval($row['place_id']).'" aria-label="'.esc_attr($row['name']).' auswählen"></td>';
                echo '<td style="min-width:180px"><strong>'.esc_html($row['name']).'</strong><br><small>'.esc_html(trim(($row['street']??'').' '.($row['house_number']??'').', '.($row['city']??''))).'</small>';
                if(!empty($row['primary_subcategory'])) echo '<br><small>Food: '.esc_html($row['primary_subcategory']).'</small>';
                echo '</td>';

                $tier_color=$row['tier']==='A'?'#008a20':($row['tier']==='B'?'#996800':($row['tier']==='X'?'#b32d2e':'#50575e'));
                echo '<td style="min-width:115px"><strong style="color:'.$tier_color.'">Tier '.esc_html($row['tier']).'</strong><br>Score '.intval($row['score']).'<br><small>'.esc_html($row['auto_decision']).'<br>Review: '.esc_html($row['review_status']).'</small></td>';

                echo '<td style="min-width:260px">';
                if(!empty($row['audit_reason'])) echo '<div style="margin-bottom:6px"><strong>Audit-Grund:</strong><br>'.esc_html($row['audit_reason']).'</div>';
                if($signals) echo '<div><strong>Positive Signale:</strong><br>'.esc_html(implode(' · ',$signals)).'</div>';
                if($excl) echo '<div style="margin-top:6px;color:#b32d2e"><strong>Ausschluss:</strong><br>'.esc_html(implode(' · ',$excl)).'</div>';
                if(!$signals&&!$excl) echo '<span style="color:#646970">keine gespeicherte Begründung</span>';
                echo '</td>';

                echo '<td style="min-width:220px">';
                if($menu) echo '<div><strong>Erkannte Gerichte:</strong><br>'.esc_html(implode(', ',$menu)).'</div>';
                else echo '<div><strong>Erkannte Gerichte:</strong> <span style="color:#646970">unbekannt</span></div>';
                echo '<div style="margin-top:5px"><strong>Quellenstatus (tier-neutral):</strong> '.esc_html($row['website_scan_status']).'</div>';
                if(!empty($row['website'])) echo '<div><a href="'.esc_url($row['website']).'" target="_blank" rel="noopener">Offizielle Website ↗</a></div>';
                if(!empty($tags['cuisine'])) echo '<div style="margin-top:5px"><small>OSM cuisine: '.esc_html($tags['cuisine']).'</small></div>';
                echo '</td>';

                echo '<td style="min-width:160px"><div style="display:flex;gap:5px;flex-wrap:wrap">';
                foreach(array('confirmed'=>'✓ Bestätigt','rejected'=>'✕ Kein Wurst-Imbiss','auto'=>'↺ Automatik') as $decision=>$label){
                    echo '<form method="post" action="'.esc_url(admin_url('admin-post.php')).'">';
                    wp_nonce_field('rg_places_review_wurst');
                    echo '<input type="hidden" name="action" value="rg_places_review_wurst"><input type="hidden" name="place_id" value="'.intval($row['place_id']).'"><input type="hidden" name="decision" value="'.esc_attr($decision).'">';
                    foreach(array('tier','city','menu','review','website','search') as $filter_key) {
                        $request_key='wurst_'.$filter_key;
                        $filter_value=$wurst_filters[$filter_key]??'';
                        if($filter_value!=='' && $filter_value!=='all') echo '<input type="hidden" name="'.esc_attr($request_key).'" value="'.esc_attr($filter_value).'">';
                    }
                    echo '<input type="hidden" name="wurst_limit" value="'.intval($wurst_limit).'">';
                    echo '<button type="submit" class="button button-small">'.esc_html($label).'</button></form>';
                }
                echo '</div></td></tr>';
            }
            echo '</tbody></table>';

            if($wurst_visible_count < $wurst_count && $wurst_limit < 3000) {
                $more_args=array(
                    'page'=>'ruhrpottguru-places',
                    'wurst_limit'=>min(3000,$wurst_limit+120)
                );
                foreach(array('tier','city','menu','review','website','search') as $filter_key) {
                    $filter_value=$wurst_filters[$filter_key]??'';
                    if($filter_value!=='' && $filter_value!=='all') $more_args['wurst_'.$filter_key]=$filter_value;
                }
                $more_url=add_query_arg($more_args,admin_url('tools.php')).'#rg-wurst-audit';
                $remaining=max(0,$wurst_count-$wurst_visible_count);
                $next_batch=min(120,$remaining);
                echo '<p style="max-width:1150px;text-align:center;margin:16px 0 4px">';
                echo '<a class="button button-primary button-large" href="'.esc_url($more_url).'">Weitere '.number_format_i18n($next_batch).' laden</a>';
                echo '<br><small style="display:inline-block;margin-top:6px;color:#646970">'.number_format_i18n($remaining).' weitere Treffer vorhanden</small>';
                echo '</p>';
            }

            echo '<script>(function(){
                const all=document.getElementById("rg-wurst-check-all");
                const status=document.getElementById("rg-wurst-bulk-status");
                const nonce='.wp_json_encode($bulk_nonce).';
                const checks=()=>Array.from(document.querySelectorAll(".rg-wurst-row-check"));
                if(all) all.addEventListener("change",()=>checks().forEach(c=>c.checked=all.checked));
                document.querySelectorAll("[data-rg-wurst-bulk]").forEach(btn=>{
                    btn.addEventListener("click",async()=>{
                        const ids=checks().filter(c=>c.checked).map(c=>c.value);
                        if(!ids.length){status.textContent="Bitte mindestens einen Eintrag auswählen.";return;}
                        const decision=btn.getAttribute("data-rg-wurst-bulk");
                        document.querySelectorAll("[data-rg-wurst-bulk]").forEach(b=>b.disabled=true);
                        status.textContent=ids.length+" Einträge werden gespeichert …";
                        const body=new URLSearchParams({action:"rg_wurst_bulk_review",nonce,decision});
                        ids.forEach(id=>body.append("ids[]",id));
                        try{
                            const r=await fetch(ajaxurl,{method:"POST",headers:{"Content-Type":"application/x-www-form-urlencoded;charset=UTF-8"},body});
                            const j=await r.json();
                            if(!j.success) throw new Error("save");
                            sessionStorage.setItem("rgWurstReturnToAudit","1");
                            window.location.reload();
                        }catch(e){
                            status.textContent="Speichern fehlgeschlagen.";
                            document.querySelectorAll("[data-rg-wurst-bulk]").forEach(b=>b.disabled=false);
                        }
                    });
                });
                if(sessionStorage.getItem("rgWurstReturnToAudit")==="1"){
                    sessionStorage.removeItem("rgWurstReturnToAudit");
                    setTimeout(()=>document.getElementById("rg-wurst-audit")?.scrollIntoView({block:"start"}),50);
                }
            })();</script>';
        }

        $wurst_suggestions=$this->pending_wurst_suggestions(30);
        echo '<div id="rg-wurst-suggestions" style="max-width:1150px;background:#fff;border:1px solid #dcdcde;border-radius:8px;padding:14px;margin:18px 0">';
        echo '<h3 style="margin:0 0 8px">Fehlende Stammbuden · Community</h3>';
        echo '<p>Neue Vorschläge aus dem Frontend sind bewusst nur <strong>eingereicht/ungeprüft</strong>. Sie werden nicht automatisch zu Tier A/B/U und niemals automatisch veröffentlicht.</p>';
        if(!$wurst_suggestions){
            echo '<p><em>Keine offenen Vorschläge.</em></p>';
        }else{
            echo '<table class="widefat striped"><thead><tr><th>Name</th><th>Ort / Adresse</th><th>Hinweis</th><th>Eingang</th><th>Aktion</th></tr></thead><tbody>';
            foreach($wurst_suggestions as $sub){
                $payload=json_decode((string)$sub['payload_json'],true); if(!is_array($payload))$payload=array();
                echo '<tr><td><strong>'.esc_html($payload['name']??'').'</strong>';
                if(!empty($payload['website'])) echo '<br><a href="'.esc_url($payload['website']).'" target="_blank" rel="noopener">Website ↗</a>';
                echo '</td><td>'.esc_html(trim(($payload['city']??'').' · '.($payload['address']??''),' ·')).'</td><td>'.esc_html($payload['note']??'').'</td><td>'.esc_html($sub['created_at']).'</td><td><div style="display:flex;gap:6px;flex-wrap:wrap">';
                foreach(array('reviewed'=>'✓ Gesehen','reject'=>'✕ Verwerfen') as $decision=>$label){
                    echo '<form method="post" action="'.esc_url(admin_url('admin-post.php')).'">';
                    wp_nonce_field('rg_wurst_suggestion_review');
                    echo '<input type="hidden" name="action" value="rg_wurst_suggestion_review"><input type="hidden" name="submission_id" value="'.intval($sub['id']).'"><input type="hidden" name="decision" value="'.esc_attr($decision).'"><button type="submit" class="button button-small">'.esc_html($label).'</button></form>';
                }
                echo '</div></td></tr>';
            }
            echo '</tbody></table>';
        }
        echo '</div>';

        $wurst_nonce=wp_create_nonce(self::ADMIN_NONCE_ACTION);
        echo '<script>(function(){const backfill=document.getElementById("rg-wurst-backfill"),web=document.getElementById("rg-wurst-websites"),progress=document.getElementById("rg-wurst-progress");if(!backfill)return;const nonce='.wp_json_encode($wurst_nonce).';let running=false;function stats(s){return "Inventar "+s.total+" · A "+s.tier_a+" · B "+s.tier_b+" · C "+s.tier_c+" · X "+s.excluded;}async function backfillRun(){if(running)return;running=true;backfill.disabled=true;backfill.textContent="Bestand wird analysiert …";while(running){const body=new URLSearchParams({action:"rg_wurst_backfill_batch",nonce});const r=await fetch(ajaxurl,{method:"POST",headers:{"Content-Type":"application/x-www-form-urlencoded;charset=UTF-8"},body});const j=await r.json();if(!j.success)break;progress.textContent="Bestand analysiert: "+j.data.state.processed+" · "+stats(j.data.stats);if(j.data.state.done)break;await new Promise(x=>setTimeout(x,180));}running=false;backfill.disabled=false;backfill.textContent="Analyse abgeschlossen / erneut prüfen";}async function webRun(){if(running)return;running=true;web.disabled=true;web.textContent="Optionale Menüquellen werden geprüft …";while(running){const body=new URLSearchParams({action:"rg_wurst_website_enrich_batch",nonce});const r=await fetch(ajaxurl,{method:"POST",headers:{"Content-Type":"application/x-www-form-urlencoded;charset=UTF-8"},body});const j=await r.json();if(!j.success)break;progress.textContent="Menüquellen-Prüfung: "+stats(j.data.stats)+" · verbleibend "+j.data.run.remaining;if(!j.data.run.remaining||!j.data.run.processed)break;await new Promise(x=>setTimeout(x,500));}running=false;web.disabled=false;web.textContent="Menüquellen-Prüfung abgeschlossen";}backfill.addEventListener("click",backfillRun);web.addEventListener("click",webRun);})();</script>';

        echo '<h2 id="rg-buedchen" style="margin-top:28px">Büdchen- & Trinkhallen-Radar · Bestandsaufnahme</h2>';
        echo '<p>V1.2.5 importiert <code>shop=kiosk</code> und <code>shop=convenience</code> als eigene Special-Kandidaten. Die bestehenden vier Hauptkategorien und ihre öffentliche Sortierung bleiben davon getrennt.</p>';
        echo '<div style="display:flex;gap:10px;flex-wrap:wrap;margin:12px 0 16px">';
        foreach (array(
            'Kandidaten gesamt'=>$buedchen_stats['total'],
