                echo '<tr><th>Quelle</th><td><select name="source_type">';
                foreach(array('editorial'=>'RuhrpottGuru Redaktion','operator'=>'Betreiber bestätigt','official'=>'Offizielle Quelle') as $k=>$label) echo '<option value="'.esc_attr($k).'" '.selected(($orow['source_type']??'editorial'),$k,false).'>'.esc_html($label).'</option>';
                echo '</select> <input class="regular-text" type="text" name="source_label" value="'.esc_attr($orow['source_label']??'RuhrpottGuru Redaktion').'" placeholder="z. B. Betreiber telefonisch bestätigt"></td></tr>';
                echo '</tbody></table>';
                echo '<h3>Büdchen-Merkmale</h3><div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(210px,1fr));gap:10px">';
                $features=array('mixed_candy'=>'Gemischte Tüte','coffee'=>'Kaffee','sandwiches'=>'Belegte Brötchen','seating'=>'Sitzgelegenheiten','lottery'=>'Lotto','parcel_shop'=>'Paketshop','tobacco'=>'Tabak','late_night'=>'Spät geöffnet');
                foreach($features as $key=>$label){
                    $current=array_key_exists($key,$odata['features']) ? ($odata['features'][$key]?'yes':'no') : 'unknown';
                    echo '<label style="border:1px solid #dcdcde;padding:10px;border-radius:6px"><strong>'.esc_html($label).'</strong><br><select name="features['.esc_attr($key).']"><option value="unknown" '.selected($current,'unknown',false).'>unbekannt</option><option value="yes" '.selected($current,'yes',false).'>ja</option><option value="no" '.selected($current,'no',false).'>nein</option></select></label>';
                }
                echo '</div>';
                submit_button('Redaktionelle Daten speichern');
