                // an Event without its own Event image receives exactly one pool image.
                $manual_media=$this->place_editorial_media_rows_v1076($edit_place,true);
                $auto_media=$wpdb->get_row($wpdb->prepare("SELECT * FROM {$this->table('place_media')} WHERE place_id=%d AND media_type='image' AND relation_type='place' AND moderation_status='active' AND source<>'editorial-place-upload' ORDER BY is_primary DESC,identity_confidence DESC,visual_quality DESC,id ASC LIMIT 1",$edit_place),ARRAY_A);
                echo '<h3 style="margin-top:24px">Ortsbilder</h3>';
                if(!empty($_GET['rg_media_saved']))echo '<div class="notice notice-success inline"><p>Ortsbilder aktualisiert.</p></div>';
                echo '<p>Mehrere freigegebene Bilder können für diesen Ort hinterlegt werden. <strong>Normale Places</strong> nutzen sie im bestehenden Detail-Slider. <strong>Events</strong> zeigen weiterhin genau ein Bild; fehlt ein eigenes Eventbild, wird ein stabiles Einzelbild aus diesem Pool verwendet.</p>';
                echo '<div style="max-width:1100px;background:#fff;border:1px solid #dcdcde;padding:18px;border-radius:8px">';
                if($auto_media){echo '<div style="display:flex;gap:12px;align-items:center;padding:10px;background:#f6f7f7;border-radius:8px;margin-bottom:14px"><img src="'.esc_url((string)$auto_media['url']).'" alt="" style="width:150px;aspect-ratio:16/9;object-fit:cover;border-radius:6px"><div><strong>Automatisches Ortsbild im Hintergrund</strong><br><span class="description">'.esc_html((string)$auto_media['source']).' · bleibt erhalten und wird wieder sichtbar, wenn der manuelle Pool deaktiviert wird.</span></div></div>';}
                if($manual_media){echo '<div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(240px,1fr));gap:12px;margin-bottom:18px">';foreach($manual_media as $mm){$active=(string)$mm['moderation_status']==='active';echo '<div style="border:1px solid #dcdcde;border-radius:8px;padding:10px;'.(!$active?'opacity:.58;':'').'">';echo '<div style="aspect-ratio:16/9;background:#f0f0f1;border-radius:6px;overflow:hidden"><img src="'.esc_url($mm['url']).'" alt="" style="width:100%;height:100%;object-fit:cover"></div>';echo '<p style="margin:8px 0 4px"><strong>'.(!empty($mm['is_primary'])?'★ Hauptbild':'Ortsbild').'</strong> · '.($active?'aktiv':'deaktiviert').'</p>';
                    echo '<form method="post" action="'.esc_url(admin_url('admin-post.php')).'">';wp_nonce_field('rg_places_manage_media_v1076');echo '<input type="hidden" name="action" value="rg_places_manage_media_v1076"><input type="hidden" name="place_id" value="'.intval($edit_place).'"><input type="hidden" name="media_id" value="'.intval($mm['id']).'"><input type="hidden" name="media_action" value="update_meta">';echo '<p><label>Credit<br><input class="widefat" name="credit" required value="'.esc_attr((string)$mm['credit']).'"></label></p><p><label>Urheber/Fotograf<br><input class="widefat" name="artist" value="'.esc_attr((string)$mm['artist']).'"></label></p><p><label>Lizenz / Nutzungsgrundlage<br><input class="widefat" name="license" required value="'.esc_attr((string)$mm['license']).'"></label></p><p><label>Quell-URL<br><input class="widefat" type="url" name="source_url" value="'.esc_attr((string)$mm['source_url']).'"></label></p><button class="button button-small" type="submit">Metadaten speichern</button></form>';
                    echo '<div style="display:flex;gap:6px;flex-wrap:wrap;margin-top:8px">';if($active&&!$mm['is_primary']){echo '<form method="post" action="'.esc_url(admin_url('admin-post.php')).'">';wp_nonce_field('rg_places_manage_media_v1076');echo '<input type="hidden" name="action" value="rg_places_manage_media_v1076"><input type="hidden" name="place_id" value="'.intval($edit_place).'"><input type="hidden" name="media_id" value="'.intval($mm['id']).'"><input type="hidden" name="media_action" value="set_primary"><button class="button button-primary button-small">Als Hauptbild</button></form>';}echo '<form method="post" action="'.esc_url(admin_url('admin-post.php')).'">';wp_nonce_field('rg_places_manage_media_v1076');echo '<input type="hidden" name="action" value="rg_places_manage_media_v1076"><input type="hidden" name="place_id" value="'.intval($edit_place).'"><input type="hidden" name="media_id" value="'.intval($mm['id']).'"><input type="hidden" name="media_action" value="'.($active?'disable':'reactivate').'"><button class="button button-small">'.($active?'Deaktivieren':'Reaktivieren').'</button></form></div></div>'; }echo '</div>';}
                echo '<form method="post" action="'.esc_url(admin_url('admin-post.php')).'" id="rg-place-media-upload-v1076">';wp_nonce_field('rg_places_upload_media_v1076');echo '<input type="hidden" name="action" value="rg_places_upload_media_v1076"><input type="hidden" name="place_id" value="'.intval($edit_place).'"><input type="hidden" name="attachment_ids" id="rg-place-media-attachment-ids" value=""><p><button type="button" class="button button-primary" id="rg-place-media-picker">Bilder auswählen / hochladen</button> <span id="rg-place-media-selection" class="description">Noch keine Bilder ausgewählt.</span></p><p><label><strong>Credit *</strong><br><input class="regular-text" required name="credit" placeholder="z. B. © Max Mustermann / RuhrpottGuru"></label></p><p><label><strong>Urheber/Fotograf</strong><br><input class="regular-text" name="artist"></label></p><p><label><strong>Lizenz / Nutzungsgrundlage *</strong><br><input class="regular-text" required name="license" placeholder="z. B. Eigenes Foto / CC BY-SA 4.0 / schriftliche Freigabe"></label></p><p><label><strong>Quell-URL</strong><br><input class="regular-text" type="url" name="source_url" placeholder="optional"></label></p><p class="description">Die Angaben gelten für die in diesem Schritt ausgewählten Bilder und können danach pro Bild einzeln geändert werden.</p><button class="button button-primary" type="submit">Ausgewählte Ortsbilder übernehmen</button></form>';
                if(array_filter($manual_media,function($x){return (string)$x['moderation_status']==='active';})){echo '<form method="post" action="'.esc_url(admin_url('admin-post.php')).'" style="margin-top:14px" onsubmit="return confirm(\'Manuellen Ortsbild-Pool deaktivieren und automatische Bilder wieder verwenden?\')">';wp_nonce_field('rg_places_manage_media_v1076');echo '<input type="hidden" name="action" value="rg_places_manage_media_v1076"><input type="hidden" name="place_id" value="'.intval($edit_place).'"><input type="hidden" name="media_id" value="'.intval($manual_media[0]['id']).'"><input type="hidden" name="media_action" value="restore_auto"><button class="button">Automatische Bilder wieder verwenden</button></form>';}
                echo '</div>';
                echo '<script>(function(){const b=document.getElementById("rg-place-media-picker"),ids=document.getElementById("rg-place-media-attachment-ids"),label=document.getElementById("rg-place-media-selection");if(!b||!window.wp||!wp.media)return;let frame;b.addEventListener("click",function(e){e.preventDefault();if(frame){frame.open();return;}frame=wp.media({title:"Ortsbilder auswählen",button:{text:"Bilder übernehmen"},library:{type:"image"},multiple:true});frame.on("select",function(){const sel=frame.state().get("selection").toJSON();ids.value=sel.map(x=>x.id).join(",");label.textContent=sel.length+" Bild"+(sel.length===1?"":"er")+" ausgewählt";});frame.open();});})();</script>';
            }
        }

        // Community-Daten und -Bilder werden unter „RP Redaktion“ getrennt moderiert.

        $media_stats=$this->buedchen_media_stats();
        $media_state=$this->buedchen_media_state();
        echo '<h2 style="margin-top:30px">Büdchen-Bilder · automatische Anreicherung</h2>';
        echo '<p>Die Bildsuche läuft <strong>nicht im Besucher-Browser</strong>, sondern hier serverseitig und speichert belastbare Treffer dauerhaft in <code>place_media</code>. Verwendet werden nur identitätsgebundene Quellen aus der bestehenden RuhrpottGuru-Medienlogik (OSM-Bild, Commons/Wikidata/Wikipedia, offizielle Website, regionale Open-Data-Quellen und konservative Street-Imagery). Allgemeine Eventmotive werden <strong>nicht automatisch</strong> als Ortsfoto übernommen.</p>';
        echo '<div id="rg-bude-media-box" style="max-width:1100px;border:1px solid #dcdcde;background:#fff;border-radius:8px;padding:14px">';
        echo '<div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(150px,1fr));gap:10px">';
        foreach(array(
            'Büdchen gesamt'=>$media_stats['total'],
            'Radar-fähig'=>$media_stats['publicEligible'],
            'mit Hauptbild'=>$media_stats['withPrimaryImage'],
            'mit irgendeinem Bild'=>$media_stats['withAnyImage'],
            'noch ohne Hauptbild'=>$media_stats['withoutPrimary'],
            'in diesem Lauf geprüft'=>$media_state['processed'],
        ) as $label=>$value){
            echo '<div style="padding:10px;border:1px solid #e2e4e7;border-radius:6px"><small>'.esc_html($label).'</small><div style="font-size:22px;font-weight:700">'.number_format_i18n((int)$value).'</div></div>';
        }
        echo '</div>';
        echo '<p id="rg-bude-media-progress" style="margin:12px 0 8px"><strong>Gefunden:</strong> '.intval($media_state['found']).' · <strong>als Hauptbild bestätigt:</strong> '.intval($media_state['primary']).' · <strong>ohne Treffer:</strong> '.intval($media_state['skipped']).'</p>';
        echo '<p><button type="button" class="button button-primary" id="rg-bude-media-start">Büdchen-Bilder jetzt anreichern</button> ';
        echo '<button type="button" class="button" id="rg-bude-media-reset">Prüflauf zurücksetzen</button></p>';
        echo '<p class="description">Der Lauf arbeitet in kleinen 4er-Paketen. Zwischen den Paketen bleibt WordPress responsiv. Du kannst die Seite offen lassen; die Daten werden nach jedem Paket gespeichert.</p>';
        echo '</div>';
        $nonce=wp_create_nonce(self::ADMIN_NONCE_ACTION);
        echo '<script>(function(){const start=document.getElementById("rg-bude-media-start"),reset=document.getElementById("rg-bude-media-reset"),progress=document.getElementById("rg-bude-media-progress");if(!start)return;let running=false;const nonce='.wp_json_encode($nonce).';async function step(){if(!running)return;const body=new URLSearchParams({action:"rg_buedchen_media_enrich_batch",nonce});try{const r=await fetch(ajaxurl,{method:"POST",headers:{"Content-Type":"application/x-www-form-urlencoded;charset=UTF-8"},body});const j=await r.json();if(!j.success)throw new Error("Fehler");const s=j.data.state,i=j.data.inventory;progress.innerHTML="<strong>Geprüft:</strong> "+s.processed+" · <strong>gefunden:</strong> "+s.found+" · <strong>Hauptbilder:</strong> "+s.primary+" · <strong>ohne Treffer:</strong> "+s.skipped+" · <strong>aktuell mit Hauptbild:</strong> "+i.withPrimaryImage;if(j.data.remaining){setTimeout(step,450);}else{running=false;start.disabled=false;start.textContent="Anreicherung abgeschlossen";}}catch(e){running=false;start.disabled=false;start.textContent="Weiter versuchen";progress.textContent="Anreicherung unterbrochen. Bereits gespeicherte Treffer bleiben erhalten.";}}start.addEventListener("click",function(){if(running)return;running=true;start.disabled=true;start.textContent="Bilder werden geprüft …";step();});reset.addEventListener("click",async function(){if(running)return;const body=new URLSearchParams({action:"rg_buedchen_media_reset",nonce});await fetch(ajaxurl,{method:"POST",headers:{"Content-Type":"application/x-www-form-urlencoded;charset=UTF-8"},body});location.reload();});})();</script>';

        $pending_submissions=$this->pending_buedchen_submissions(30);
        echo '<h2 id="rg-communities" style="margin-top:30px">Büdchen-Hinweise · Community & Betreiber</h2>';
        if(!$pending_submissions){
            echo '<p>Noch keine offenen Hinweise.</p>';
        }else{
            echo '<table class="widefat striped" style="max-width:1100px"><thead><tr><th>Büdchen</th><th>Hinweis</th><th>Quelle</th><th>Eingang</th><th>Aktion</th></tr></thead><tbody>';
            foreach($pending_submissions as $sub){
                $payload=json_decode((string)$sub['payload_json'],true); if(!is_array($payload))$payload=array();
                $fields=(isset($payload['fields'])&&is_array($payload['fields']))
                    ? $payload['fields']
                    : (!empty($payload['field'])?array((string)$payload['field']=>$payload['value']??''):array());
                $lines=array();
                foreach($fields as $field=>$value) {
                    $display=is_bool($value)?($value?'Ja':'Nein'):(string)$value;
                    $lines[]='<code>'.esc_html((string)$field).'</code>: '.esc_html($display);
                }
                echo '<tr><td><strong>'.esc_html($sub['place_name']?:('#'.$sub['place_id'])).'</strong><br><small>'.esc_html(trim(($sub['street']??'').' '.($sub['house_number']??'').', '.($sub['city']??''))).'</small></td>';
                echo '<td>'.implode('<br>',$lines).'</td><td>'.esc_html($sub['source_label']).'</td><td>'.esc_html($sub['created_at']).'</td><td><div style="display:flex;gap:6px;flex-wrap:wrap">';
                foreach(array('approve'=>'✓ Übernehmen','reject'=>'✕ Ablehnen') as $decision=>$label){
                    echo '<form method="post" action="'.esc_url(admin_url('admin-post.php')).'">';
                    wp_nonce_field('rg_places_submission_review');
                    echo '<input type="hidden" name="action" value="rg_places_submission_review"><input type="hidden" name="submission_id" value="'.intval($sub['id']).'"><input type="hidden" name="decision" value="'.esc_attr($decision).'"><button class="button button-small" type="submit">'.esc_html($label).'</button></form>';
                }
                echo '</div></td></tr>';
            }
            echo '</tbody></table>';
        }

        echo '<details class="rg-admin-details" style="margin-top:30px"><summary>Büdchen-Qualitätsprüfung · Stichprobe A/B/C</summary><div style="padding:0 14px 14px">';
        echo '<p>Hier prüfst du echte Kandidaten aus dem aktuellen Datenbestand. <strong>Bestätigt</strong> darf auch einen Tier-C-Kandidaten später freigeben; <strong>Kein Büdchen</strong> schließt einen Kandidaten aus dem Radar aus. OSM-Daten selbst werden nicht verändert.</p>';
        $samples=$this->buedchen_review_samples(6);
        foreach($samples as $tier=>$items){
            echo '<h3>Tier '.esc_html($tier).'</h3><div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(290px,1fr));gap:10px;max-width:1100px">';
            foreach($items as $item){
                $tags=json_decode((string)$item['raw_tags'],true); if(!is_array($tags))$tags=array();
                $odata=$this->decode_override_data($item['override_data']??'');
                $review=sanitize_key((string)($odata['buedchen']['review_status']??'auto'));
                echo '<div style="background:#fff;border:1px solid #dcdcde;border-radius:8px;padding:12px">';
                echo '<div style="display:flex;justify-content:space-between;gap:8px"><strong>'.esc_html($item['name']).'</strong><span>Tier '.esc_html($tier).' · '.esc_html($tags['rg:buedchen_score']??'?').'</span></div>';
                echo '<p style="margin:6px 0;color:#50575e">'.esc_html(trim(($item['street']??'').' '.($item['house_number']??'').', '.($item['city']??''))).'</p>';
                echo '<p style="font-size:12px;margin:5px 0"><strong>OSM:</strong> '.esc_html($tags['shop']??'').' · <strong>Signale:</strong> '.esc_html(str_replace('|',' · ',$tags['rg:buedchen_signals']??'')).'</p>';
                echo '<p style="font-size:12px;margin:5px 0"><strong>Öffnungszeiten:</strong> '.esc_html($item['opening_hours']?:'unbekannt').' · <strong>Website:</strong> '.($item['website']?'vorhanden':'—').'</p>';
                if($review!=='auto') echo '<p><strong>Redaktion:</strong> '.esc_html($review==='verified'?'✓ bestätigt':'✕ ausgeschlossen').'</p>';
                echo '<div style="display:flex;gap:6px;flex-wrap:wrap;margin-top:10px">';
                foreach(array('verified'=>'✓ Bestätigt','rejected'=>'✕ Kein Büdchen','auto'=>'↺ Automatik') as $verdict=>$label){
                    echo '<form method="post" action="'.esc_url(admin_url('admin-post.php')).'">';
                    wp_nonce_field('rg_places_review_buedchen');
                    echo '<input type="hidden" name="action" value="rg_places_review_buedchen"><input type="hidden" name="place_id" value="'.intval($item['id']).'"><input type="hidden" name="verdict" value="'.esc_attr($verdict).'">';
                    echo '<button type="submit" class="button button-small">'.esc_html($label).'</button></form>';
                }
                echo '<a class="button button-small" href="'.esc_url(add_query_arg(array('page'=>'rp-places','rg_section'=>'buedchen','edit_place'=>(int)$item['id']),admin_url('admin.php'))).'">Daten ergänzen</a>';
                echo '</div></div>';
            }
            echo '</div>';
        }
        echo '</div></details>';

        echo '<h2 id="rg-municipalities" style="margin-top:28px">Kommunenstatus</h2>';
        echo '<p>Alle 53 Kommunen mit letztem erfolgreichen Importstand. Fehlgeschlagene Aktualisierungen lassen den letzten vollständigen Datenstand aktiv.</p>';
        echo '<div style="max-width:1100px;overflow-x:auto"><table class="widefat striped"><thead><tr>';
        echo '<th>Kommune</th><th>Status</th><th>Rohdaten</th><th>importiert</th><th>Versuche seit 1.2.6</th><th>letzter Sync</th><th>letzter Fehler</th>';
        echo '</tr></thead><tbody>';
        foreach ($municipalities as $row) {
            $status = (string)($row['status'] ?? '');
            $is_error = $status === 'failed';
            $error = trim((string)($row['last_error'] ?? ''));
            if (!$is_error && $status === 'complete') {
                // A historic bootstrap error is no longer an active problem after a successful retry.
                $error = '';
            }
            echo '<tr>';
            echo '<td><strong>'.esc_html($row['name']).'</strong><br><code>'.esc_html($row['slug']).'</code></td>';
            echo '<td>'.esc_html($this->admin_status_label($status)).'</td>';
            echo '<td>'.number_format_i18n((int)$row['raw_count']).'</td>';
            echo '<td>'.number_format_i18n((int)$row['imported_count']).'</td>';
            echo '<td>'.number_format_i18n((int)$row['attempts']).'</td>';
            echo '<td>'.($row['last_synced_at'] ? esc_html($row['last_synced_at']).' UTC' : '—').'</td>';
            echo '<td style="max-width:330px;word-break:break-word">'.($error !== '' ? esc_html($error) : '—').'</td>';
            echo '</tr>';
        }
        echo '</tbody></table></div>';

        echo '<h2 id="rg-system">Automatik</h2><p>Die Befüllung und Synchronisation läuft selbständig. Im Status READY liest das Frontend die vier ortsfesten Kategorien aus MySQL; OSM/Overpass wird nur noch für Hintergrund-Synchronisation verwendet. Der Admin-Browser unterstützt die Synchronisation automatisch, falls das Hosting direkte Overpass-Verbindungen blockiert.</p>';
        echo '<h2>Rollback</h2><p>Der v70-Theme-Build ist der festgelegte OSM-Rollback-Punkt. Ein Theme-Rollback lässt diese Tabellen unangetastet, nutzt sie aber nicht.</p>';
        echo '<h2>OSM-Lizenz/Export</h2><p>Ortsbasis: © OpenStreetMap contributors · ODbL 1.0. Der OSM-basierte Derived-Layer wird getrennt vom RuhrpottGuru-Enrichment als komprimierter NDJSON-Export bereitgestellt.</p>';
        if ($report) echo '<h2>Letzte Validierung</h2><details class="rg-admin-details"><summary>Validierungsreport anzeigen</summary><pre style="padding:12px;margin:0;overflow:auto">'.esc_html(wp_json_encode($report, JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE)).'</pre></details>';
        echo '<script>(function(){var root=document.querySelector(".rg-places-tech");if(!root)return;function labelFor(t){var n=t;for(var d=0;d<4&&n;d++,n=n.parentElement){var p=n.previousElementSibling;while(p){if(p.matches&&p.matches("h2,h3")){var x=(p.textContent||"").trim();if(x)return x+" · Liste";}p=p.previousElementSibling;}}return "Liste ein-/ausklappen";}root.querySelectorAll("table.widefat").forEach(function(t){if(t.closest("details"))return;var d=document.createElement("details");d.className="rg-admin-details rg-auto-list";var s=document.createElement("summary");s.textContent=labelFor(t);t.parentNode.insertBefore(d,t);d.appendChild(s);d.appendChild(t);});})();</script>';
        echo '</div>';
    }

    /* V1.10.9 – Community-Beiträge zu bestehenden Places. */
    public function register_community_cpt() {
        register_post_type('rpg_community', array(
            'labels'=>array('name'=>'Community-Beiträge','singular_name'=>'Community-Beitrag','add_new_item'=>'Community-Beitrag hinzufügen','edit_item'=>'Community-Beitrag prüfen','menu_name'=>'Community'),
            'public'=>false,'show_ui'=>true,'show_in_menu'=>false,'show_in_rest'=>false,
            'supports'=>array('title','editor','thumbnail'),'map_meta_cap'=>true,
            'capability_type'=>'post','has_archive'=>false,'rewrite'=>false,'query_var'=>false,
        ));
        $private=array('_rpg_place_id','_rpg_place_category','_rpg_author_nickname','_rpg_author_email','_rpg_author_instagram','_rpg_terms_accepted','_rpg_terms_version','_rpg_terms_accepted_at','_rpg_privacy_accepted','_rpg_image_rights_confirmed','_rpg_media_origin');
        foreach($private as $key){
            register_post_meta('rpg_community',$key,array('single'=>true,'type'=>'string','show_in_rest'=>false,'auth_callback'=>function(){return current_user_can('edit_posts');}));
        }
    }

    /** V1.10.151 – Moderationskontext direkt am Community-Beitrag. */
    public function add_community_review_meta_box_v101151() {
        add_meta_box('rpg-community-review-v101151','Community-Prüfung',array($this,'render_community_review_meta_box_v101151'),'rpg_community','normal','high');
    }

    private function community_place_v101151($place_id) {
        global $wpdb;
        $place_id=absint($place_id);
        if(!$place_id)return null;
        return $wpdb->get_row($wpdb->prepare("SELECT id,name,city,primary_category,active,lifecycle_status FROM {$this->table('places')} WHERE id=%d",$place_id),ARRAY_A);
    }

    private function community_images_v101151($post_id) {
        $items=get_children(array('post_parent'=>absint($post_id),'post_type'=>'attachment','post_mime_type'=>'image','post_status'=>'inherit','orderby'=>'ID','order'=>'ASC','numberposts'=>5));
        return array_values((array)$items);
    }

    public function render_community_review_meta_box_v101151($post) {
        if(!$post||$post->post_type!=='rpg_community')return;
        $place_id=absint(get_post_meta($post->ID,'_rpg_place_id',true));
        $place=$this->community_place_v101151($place_id);
        $nickname=(string)get_post_meta($post->ID,'_rpg_author_nickname',true);
        $email=(string)get_post_meta($post->ID,'_rpg_author_email',true);
        $instagram=(string)get_post_meta($post->ID,'_rpg_author_instagram',true);
        $terms=(string)get_post_meta($post->ID,'_rpg_terms_accepted',true)==='1';
        $terms_version=(string)get_post_meta($post->ID,'_rpg_terms_version',true);
        $terms_at=(string)get_post_meta($post->ID,'_rpg_terms_accepted_at',true);
        $privacy=(string)get_post_meta($post->ID,'_rpg_privacy_accepted',true)==='1';
        $rights=(string)get_post_meta($post->ID,'_rpg_image_rights_confirmed',true)==='1';
        $images=$this->community_images_v101151($post->ID);
        echo '<style>.rpg-community-review-grid{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:14px 22px}.rpg-community-review-card{border:1px solid #dcdcde;border-radius:8px;padding:12px;background:#fff}.rpg-community-review-card h3{margin:0 0 8px;font-size:13px}.rpg-community-review-meta{display:grid;grid-template-columns:120px 1fr;gap:6px 10px;margin:0}.rpg-community-review-meta dt{font-weight:700}.rpg-community-review-meta dd{margin:0;word-break:break-word}.rpg-community-review-images{display:grid;grid-template-columns:repeat(auto-fit,minmax(140px,1fr));gap:10px;margin-top:10px}.rpg-community-review-image{border:1px solid #dcdcde;border-radius:8px;overflow:hidden;background:#f6f7f7}.rpg-community-review-image img{display:block;width:100%;aspect-ratio:4/3;object-fit:cover}.rpg-community-review-image span{display:block;padding:7px;font-size:11px;word-break:break-word}.rpg-community-review-ok{color:#137333;font-weight:700}.rpg-community-review-bad{color:#b32d2e;font-weight:700}@media(max-width:782px){.rpg-community-review-grid{grid-template-columns:1fr}.rpg-community-review-meta{grid-template-columns:1fr}.rpg-community-review-meta dt{margin-top:6px}}</style>';
        echo '<div class="rpg-community-review-grid">';
        echo '<div class="rpg-community-review-card"><h3>Ort & Zuordnung</h3><dl class="rpg-community-review-meta">';
        echo '<dt>Place</dt><dd>'.($place?'<strong>'.esc_html($place['name']).'</strong> · '.esc_html($place['city']):'<span class="rpg-community-review-bad">Place nicht gefunden</span>').'</dd>';
        echo '<dt>Place-ID</dt><dd>#'.intval($place_id).'</dd>';
        echo '<dt>Kategorie</dt><dd>'.esc_html($place?(string)$place['primary_category']:(string)get_post_meta($post->ID,'_rpg_place_category',true)).'</dd>';
        if($place)echo '<dt>Place-Status</dt><dd>'.($place['active']?'<span class="rpg-community-review-ok">aktiv</span>':'<span class="rpg-community-review-bad">inaktiv</span>').' · '.esc_html((string)$place['lifecycle_status']).'</dd>';
        echo '</dl></div>';
        echo '<div class="rpg-community-review-card"><h3>Einreicher</h3><dl class="rpg-community-review-meta">';
        echo '<dt>Name / Nickname</dt><dd>'.esc_html($nickname?:'—').'</dd>';
        echo '<dt>E-Mail</dt><dd>'.($email!==''?'<a href="mailto:'.esc_attr($email).'">'.esc_html($email).'</a>':'—').'</dd>';
        echo '<dt>Instagram</dt><dd>'.esc_html($instagram?:'—').'</dd>';
        echo '</dl></div>';
        echo '<div class="rpg-community-review-card"><h3>Zustimmungen</h3><dl class="rpg-community-review-meta">';
        echo '<dt>Bedingungen</dt><dd class="'.($terms?'rpg-community-review-ok':'rpg-community-review-bad').'">'.($terms?'bestätigt':'fehlt').($terms_version!==''?' · Version '.esc_html($terms_version):'').'</dd>';
        echo '<dt>Datenschutz</dt><dd class="'.($privacy?'rpg-community-review-ok':'rpg-community-review-bad').'">'.($privacy?'bestätigt':'fehlt').'</dd>';
        echo '<dt>Bildrechte</dt><dd class="'.($rights?'rpg-community-review-ok':'rpg-community-review-bad').'">'.($rights?'bestätigt':'fehlt').'</dd>';
        echo '<dt>Bestätigt am</dt><dd>'.esc_html($terms_at?:'—').' UTC</dd>';
        echo '</dl></div>';
        echo '<div class="rpg-community-review-card"><h3>Moderation</h3><p style="margin:0 0 8px">Prüfe Text, Zuordnung und alle Fotos. <strong>Freigeben</strong> erfolgt über „Veröffentlichen“ im WordPress-Statuskasten. <strong>Ablehnen</strong> erfolgt über „In den Papierkorb verschieben“.</p><p style="margin:0">Öffentlich erscheinen ausschließlich veröffentlichte Beiträge. E-Mail-Adresse und Zustimmungsdaten werden nie über den öffentlichen Community-Endpunkt ausgegeben.</p></div>';
        echo '</div>';
        echo '<div class="rpg-community-review-card" style="margin-top:14px"><h3>Fotos ('.intval(count($images)).' / 5)</h3>';
        if(!$images){echo '<p class="rpg-community-review-bad">Keine Fotos vorhanden. Dieser Beitrag erfüllt den Community-Vertrag nicht und sollte nicht freigegeben werden.</p>';}else{echo '<div class="rpg-community-review-images">';foreach($images as $image){$url=wp_get_attachment_url($image->ID);$thumb=wp_get_attachment_image($image->ID,'medium',false,array('loading'=>'lazy'));echo '<a class="rpg-community-review-image" href="'.esc_url($url).'" target="_blank" rel="noopener noreferrer">'.$thumb.'<span>#'.intval($image->ID).' · '.esc_html(get_the_title($image->ID)).'</span></a>';}echo '</div>';}
        echo '</div>';
    }

    public function community_admin_columns_v101151($columns) {
        return array('cb'=>'<input type="checkbox" />','title'=>'Beitrag','rpg_place'=>'Ort','rpg_submitter'=>'Einreicher','rpg_photos'=>'Fotos','date'=>'Eingereicht');
    }

    public function community_admin_column_v101151($column,$post_id) {
        if($column==='rpg_place'){
            $place_id=absint(get_post_meta($post_id,'_rpg_place_id',true));$place=$this->community_place_v101151($place_id);
            echo $place?'<strong>'.esc_html($place['name']).'</strong><br><small>'.esc_html($place['city']).' · #'.intval($place_id).'</small>':'<span style="color:#b32d2e">Place #'.intval($place_id).' fehlt</span>';
        }elseif($column==='rpg_submitter'){
            $nickname=(string)get_post_meta($post_id,'_rpg_author_nickname',true);$email=(string)get_post_meta($post_id,'_rpg_author_email',true);
            echo esc_html($nickname?:'—');if($email!=='')echo '<br><small><a href="mailto:'.esc_attr($email).'">'.esc_html($email).'</a></small>';
        }elseif($column==='rpg_photos'){
            $count=count($this->community_images_v101151($post_id));echo intval($count).' / 5';if($count<1)echo '<br><small style="color:#b32d2e">Pflichtbild fehlt</small>';
        }
    }

    private function community_origin_ok(){
        $home=strtolower((string)wp_parse_url(home_url('/'),PHP_URL_HOST));
        foreach(array('HTTP_ORIGIN','HTTP_REFERER') as $h){if(empty($_SERVER[$h]))continue;$host=strtolower((string)wp_parse_url((string)$_SERVER[$h],PHP_URL_HOST));if($host!==''&&$host!==$home)return false;}return true;
    }
    private function community_rate_key(){
        $ip=(string)($_SERVER['REMOTE_ADDR']??'');$ua=(string)($_SERVER['HTTP_USER_AGENT']??'');
        return 'rg_community_story_'.substr(hash_hmac('sha256',$ip.'|'.$ua,wp_salt('nonce')),0,28);
    }

    public function rest_community_story_submit(WP_REST_Request $request){
        global $wpdb;
        if(!$this->community_origin_ok()) return new WP_REST_Response(array('ok'=>false,'message'=>'Anfrage nicht erlaubt.'),403);
        $len=(int)($_SERVER['CONTENT_LENGTH']??0);if($len>12*1024*1024)return new WP_REST_Response(array('ok'=>false,'message'=>'Die Einsendung ist zu groß. Fotos werden vor dem Upload automatisch optimiert.'),413);
        if(trim((string)$request->get_param('company'))!=='')return new WP_REST_Response(array('ok'=>false,'message'=>'Einsendung abgelehnt.'),400);
        $rk=$this->community_rate_key();$count=(int)get_transient($rk);if($count>=5)return new WP_REST_Response(array('ok'=>false,'message'=>'Bitte versuche es später erneut.'),429);
        $place_id=absint($request->get_param('place_id'));
        $place=$wpdb->get_row($wpdb->prepare("SELECT id,name,city,primary_category FROM {$this->table('places')} WHERE id=%d AND active=1",$place_id),ARRAY_A);
        if(!$place)return new WP_REST_Response(array('ok'=>false,'message'=>'Ort nicht gefunden.'),404);
        $category=sanitize_key((string)$place['primary_category']);
        $title=trim(sanitize_text_field((string)$request->get_param('title')));$content=trim(wp_kses_post((string)$request->get_param('content')));
        $nickname=trim(sanitize_text_field((string)$request->get_param('nickname')));$email=sanitize_email(trim((string)$request->get_param('email')));$instagram=trim(sanitize_text_field((string)$request->get_param('instagram')));
        if(mb_strlen($title)<4||mb_strlen($title)>120)return new WP_REST_Response(array('ok'=>false,'message'=>'Bitte gib eine kurze Überschrift ein.'),400);
        if(mb_strlen(wp_strip_all_tags($content))<20||mb_strlen(wp_strip_all_tags($content))>6000)return new WP_REST_Response(array('ok'=>false,'message'=>'Dein Beitrag sollte zwischen 20 und 6000 Zeichen lang sein.'),400);
        if($nickname===''||!is_email($email))return new WP_REST_Response(array('ok'=>false,'message'=>'Nickname und gültige E-Mail-Adresse sind erforderlich.'),400);
        if((string)$request->get_param('terms_accepted')!=='1'||(string)$request->get_param('privacy_accepted')!=='1')return new WP_REST_Response(array('ok'=>false,'message'=>'Bitte bestätige Einreichungsbedingungen und Datenschutz.'),400);
        if((string)$request->get_param('image_rights_confirmed')!=='1')return new WP_REST_Response(array('ok'=>false,'message'=>'Bitte bestätige die Bildrechte.'),400);

        $files=(array)$request->get_file_params();$images=array();
        foreach($files as $key=>$file){if(strpos((string)$key,'image_')!==0)continue;$images[]=$file;}
        if(count($images)<1)return new WP_REST_Response(array('ok'=>false,'message'=>'Mindestens ein Foto ist für Community-Beiträge Pflicht.'),400);
        if(count($images)>5)return new WP_REST_Response(array('ok'=>false,'message'=>'Maximal 5 Fotos pro Beitrag.'),400);
        foreach($images as $file){
            if(!is_array($file)||!isset($file['tmp_name'],$file['name']))return new WP_REST_Response(array('ok'=>false,'message'=>'Ein Foto konnte nicht verarbeitet werden.'),400);
            $error=(int)($file['error']??UPLOAD_ERR_OK);if($error!==UPLOAD_ERR_OK)return new WP_REST_Response(array('ok'=>false,'message'=>'Ein Foto wurde nicht vollständig hochgeladen. Bitte wähle die Datei erneut aus.'),400);
            $size=(int)($file['size']??0);if($size<1)return new WP_REST_Response(array('ok'=>false,'message'=>'Eine ausgewählte Bilddatei ist leer.'),400);if($size>2*1024*1024)return new WP_REST_Response(array('ok'=>false,'message'=>'Jedes hochgeladene Foto darf nach der automatischen Optimierung maximal 2 MB groß sein.'),400);
            $ext=strtolower(pathinfo((string)$file['name'],PATHINFO_EXTENSION));if(!in_array($ext,array('jpg','jpeg','png','webp'),true))return new WP_REST_Response(array('ok'=>false,'message'=>'Erlaubt sind nur JPG, PNG oder WebP.'),400);
        }

        $post_id=wp_insert_post(array('post_type'=>'rpg_community','post_status'=>'pending','post_title'=>$title,'post_content'=>$content),true);
        if(is_wp_error($post_id))return new WP_REST_Response(array('ok'=>false,'message'=>'Der Beitrag konnte nicht gespeichert werden.'),500);
        $now=current_time('mysql',true);$meta=array('_rpg_place_id'=>(string)$place_id,'_rpg_place_category'=>$category,'_rpg_author_nickname'=>$nickname,'_rpg_author_email'=>$email,'_rpg_author_instagram'=>$instagram,'_rpg_terms_accepted'=>'1','_rpg_terms_version'=>'1.0','_rpg_terms_accepted_at'=>$now,'_rpg_privacy_accepted'=>'1','_rpg_image_rights_confirmed'=>'1','_rpg_media_origin'=>'community');foreach($meta as $k=>$v)update_post_meta($post_id,$k,$v);
        require_once ABSPATH.'wp-admin/includes/file.php';require_once ABSPATH.'wp-admin/includes/media.php';require_once ABSPATH.'wp-admin/includes/image.php';
        $uploaded_ids=array();$upload_error='';$i=0;
        foreach($images as $file){
            $ext=strtolower(pathinfo((string)$file['name'],PATHINFO_EXTENSION));$file['name']='ruhrpottguru-community-'.$place_id.'-'.gmdate('Ymd-His').'-'.$i.'.'.$ext;$_FILES['rpg_community_upload']=$file;
            $aid=media_handle_upload('rpg_community_upload',$post_id,array(),array('test_form'=>false));unset($_FILES['rpg_community_upload']);
            if(is_wp_error($aid)){$upload_error=$aid->get_error_message();break;}
            update_post_meta($aid,'_rpg_media_origin','community');update_post_meta($aid,'_rpg_place_id',(string)$place_id);update_post_meta($aid,'_rpg_community_post_id',(string)$post_id);$uploaded_ids[]=(int)$aid;$i++;
        }
        if($upload_error!==''||count($uploaded_ids)!==count($images)){
            foreach($uploaded_ids as $aid)wp_delete_attachment($aid,true);
            wp_delete_post($post_id,true);
            return new WP_REST_Response(array('ok'=>false,'message'=>'Mindestens ein Foto konnte nicht sicher gespeichert werden. Bitte prüfe die Dateien und versuche es erneut.'),400);
        }
        set_post_thumbnail($post_id,$uploaded_ids[0]);
        set_transient($rk,$count+1,30*MINUTE_IN_SECONDS);
        wp_mail(get_option('admin_email'),'Neuer RuhrpottGuru Community-Beitrag','Neuer Beitrag zu '.$place['name'].' (ID '.$place_id.'): '.$title."\n\n".admin_url('post.php?post='.$post_id.'&action=edit'));
        return rest_ensure_response(array('ok'=>true,'postId'=>$post_id,'uploadedCount'=>count($uploaded_ids),'message'=>'Danke für deinen Tipp! Wir schauen ihn uns kurz an. Nach der Freigabe kann er hier beim Ort erscheinen.'));
    }

    public function rest_community_stories(WP_REST_Request $request){
        $place_id=absint($request['id']);if(!$place_id)return new WP_REST_Response(array('ok'=>false),400);
        $q=new WP_Query(array('post_type'=>'rpg_community','post_status'=>'publish','posts_per_page'=>20,'meta_key'=>'_rpg_place_id','meta_value'=>(string)$place_id,'orderby'=>'date','order'=>'DESC','no_found_rows'=>true));$items=array();
        foreach($q->posts as $p){$thumb=get_the_post_thumbnail_url($p,'large');$items[]=array('id'=>(int)$p->ID,'title'=>get_the_title($p),'content'=>wpautop(wp_kses_post($p->post_content)),'nickname'=>(string)get_post_meta($p->ID,'_rpg_author_nickname',true),'instagram'=>(string)get_post_meta($p->ID,'_rpg_author_instagram',true),'imageUrl'=>$thumb?:'','publishedAt'=>get_post_time('c',true,$p));}
        return rest_ensure_response(array('ok'=>true,'count'=>count($items),'items'=>$items));
    }

}

